# #Requires -Version 5.1  # commented out for ps12exe compatibility
<#
.SYNOPSIS
    StreamReady PC Optimization Toolkit v6
.DESCRIPTION
    Gaming-optimised Windows tweaks. Sidebar navigation. Dashboard overview.
    GPU vendor tweaks, timer resolution control.
    Requires Administrator.
#>

#region Bootstrap & Auto-Elevation
# ─── Auto-Elevate ──────────────────────────────────────────────────────────────
function Test-Admin {
    ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole(
        [Security.Principal.WindowsBuiltInRole]::Administrator)
}
if (-not (Test-Admin)) {
    # Explain why the UAC prompt is about to appear before actually triggering it -
    # a bare elevation prompt with no context looks suspicious to a new user.
    try {
        Add-Type -AssemblyName System.Windows.Forms -EA SilentlyContinue
        [System.Windows.Forms.MessageBox]::Show(
            "StreamReady needs to run as Administrator because it changes system-wide settings (registry, services, and Windows features).`n`nClick OK, then approve the Windows prompt that appears next.",
            "StreamReady - Administrator Required",
            [System.Windows.Forms.MessageBoxButtons]::OK,
            [System.Windows.Forms.MessageBoxIcon]::Information) | Out-Null
    } catch {}
    $exePath = [System.Diagnostics.Process]::GetCurrentProcess().MainModule.FileName
    # Compiled StreamReady.exe relaunches itself; a plain script relaunches PowerShell with the script path.
    if ($exePath -like '*StreamReady.exe') {
        Start-Process $exePath -Verb RunAs
    } else {
        Start-Process PowerShell -ArgumentList "-NoProfile -ExecutionPolicy Bypass -File `"$PSCommandPath`"" -Verb RunAs
    }
    exit
}

Add-Type -AssemblyName PresentationFramework, PresentationCore, WindowsBase, Microsoft.VisualBasic
try { Add-Type -AssemblyName System.Security } catch { [System.Reflection.Assembly]::LoadWithPartialName('System.Security') | Out-Null }

# ─── Verbose Log Console ────────────────────────────────────────────────────
# Applying a batch of tweaks runs synchronously on the WPF UI thread, so the
# main window stops repainting for the couple of seconds it takes to finish -
# the inline Activity Log panel can't show anything live during that hitch.
# A real Win32 console isn't gated by WPF's Dispatcher, so writes to it appear
# immediately even while the main window is frozen mid-apply.
$script:VerboseConsoleAvailable = $false
try {
    Add-Type -Name ConsoleNative -Namespace StreamReady -MemberDefinition @'
[DllImport("kernel32.dll", SetLastError = true)] public static extern bool AllocConsole();
[DllImport("kernel32.dll")] public static extern IntPtr GetConsoleWindow();
[DllImport("kernel32.dll", CharSet = CharSet.Auto, SetLastError = true)] public static extern bool SetConsoleTitle(string lpConsoleTitle);
[DllImport("kernel32.dll", SetLastError = true)] public static extern IntPtr GetStdHandle(int nStdHandle);
[DllImport("kernel32.dll", SetLastError = true)] public static extern bool GetConsoleMode(IntPtr hConsoleHandle, out uint lpMode);
[DllImport("kernel32.dll", SetLastError = true)] public static extern bool SetConsoleMode(IntPtr hConsoleHandle, uint dwMode);
[DllImport("kernel32.dll")] public static extern bool GetSystemTimes(out long idle, out long kernel, out long user);
'@

    # Only allocate if the process doesn't already own a console (e.g. compiled -noConsole).
    if ([StreamReady.ConsoleNative]::GetConsoleWindow() -eq [IntPtr]::Zero) {
        [StreamReady.ConsoleNative]::AllocConsole() | Out-Null
    }
    [StreamReady.ConsoleNative]::SetConsoleTitle('StreamReady - Verbose Log') | Out-Null

    # This console's output codepage defaults to the system's OEM codepage (e.g. 437),
    # not UTF-8 - every non-ASCII character this app logs (em dashes, arrows, checkmarks,
    # emoji) would otherwise come out as mojibake like "ÔÇö" for "-". Setting
    # Console.OutputEncoding switches the real console's codepage to UTF-8 (65001) to
    # match what the StreamWriters below actually write.
    [Console]::OutputEncoding = [System.Text.Encoding]::UTF8

    # Re-bind Console.Out/Error to the (possibly just-created) console. In a
    # -noConsole compiled exe the cached stream handles predate this window,
    # so Write-Host would silently go nowhere without this.
    $stdout = New-Object System.IO.StreamWriter([Console]::OpenStandardOutput(), [System.Text.Encoding]::UTF8)
    $stdout.AutoFlush = $true
    [Console]::SetOut($stdout)
    $stderr = New-Object System.IO.StreamWriter([Console]::OpenStandardError(), [System.Text.Encoding]::UTF8)
    $stderr.AutoFlush = $true
    [Console]::SetError($stderr)

    # Disable QuickEdit mode - if left on, a user click-selecting text in the
    # console pauses its output buffer, which blocks Write-Host and would
    # freeze tweak application until they pressed Esc. Defeats the point.
    $STD_INPUT_HANDLE      = -10
    $ENABLE_QUICK_EDIT     = 0x0040
    $ENABLE_EXTENDED_FLAGS = 0x0080
    $hIn  = [StreamReady.ConsoleNative]::GetStdHandle($STD_INPUT_HANDLE)
    [uint32]$mode = 0
    if ([StreamReady.ConsoleNative]::GetConsoleMode($hIn, [ref]$mode)) {
        $mode = ($mode -band (-bnot $ENABLE_QUICK_EDIT)) -bor $ENABLE_EXTENDED_FLAGS
        [StreamReady.ConsoleNative]::SetConsoleMode($hIn, $mode) | Out-Null
    }

    $script:VerboseConsoleAvailable = $true
} catch {
    $script:VerboseConsoleAvailable = $false
}
#endregion Bootstrap & Auto-Elevation

#region Logging & Registry Primitives
#region Write-SR / Coalesce / Set-RegLogged
# ─── PS 5.1 null-coalescing helper ─────────────────────────────────────────────
function Coalesce { param($a, $b) if ($null -ne $a) { $a } else { $b } }

# ─── Persistent log file - every change and undo, written outside the project
# folder so a runtime log never ends up in the repo or in a release zip ─────────
$script:LogDir     = "$env:LOCALAPPDATA\StreamReady\logs"
$script:LogFilePath = Join-Path $script:LogDir ("StreamReady-{0}.log" -f (Get-Date -Format 'yyyy-MM-dd'))
try {
    if (-not (Test-Path $script:LogDir)) { New-Item -Path $script:LogDir -ItemType Directory -Force | Out-Null }
} catch {}

# ─── Console Logging (CTT-style) ───────────────────────────────────────────────
function Write-SR {
    param(
        [string]$Message,
        [ValidateSet('INFO','APPLY','OK','FAIL','UNDO','REG','SVC','NET','WARN','SECTION')]
        [string]$Type = 'INFO'
    )
    $ts = Get-Date -Format 'HH:mm:ss'

    # Persistent log file (%LOCALAPPDATA%\StreamReady\logs) - every apply/undo/registry
    # write/failure, so a user (or support) can see exactly what StreamReady changed,
    # even after the app is closed. Best-effort: a locked/missing log file must never
    # block the actual tweak it's logging.
    try {
        $logLine = if ($Type -eq 'SECTION') { "-- $Message --" } else { "[$(Get-Date -Format 'yyyy-MM-dd HH:mm:ss')] [$Type] $Message" }
        Add-Content -Path $script:LogFilePath -Value $logLine -Encoding UTF8 -EA SilentlyContinue
    } catch {}

    # NOTE: Write-Host below only fires once $script:VerboseConsoleAvailable is true,
    # i.e. after the app has explicitly allocated (or confirmed) a real console window
    # in the Bootstrap region. That guard is what avoids the old bug where, in a
    # compiled -noConsole exe with no console at all, ps2exe's runtime fell back to
    # showing EVERY Write-Host call as its own MessageBox popup - a flood of popups on
    # every single tweak/registry write.

    # Mirror into the separate Verbose Log console window - unlike the WPF panel below,
    # this isn't gated by the UI thread's Dispatcher, so it stays live even while the
    # main window hitches during a synchronous apply batch.
    #
    # Deliberately NOT using Write-Host here: Write-Host routes through $Host.UI, and a
    # ps2exe "-noConsole" compiled exe replaces $Host with its own implementation (that's
    # how it avoids a console window in the first place) - so even after AllocConsole()
    # creates a real console and [Console]::SetOut() rebinds .NET's Console.Out to it
    # (both above in Bootstrap), Write-Host still never reaches that stream; it silently
    # goes through ps2exe's replacement host instead. Writing straight to [Console]
    # bypasses $Host entirely and reaches the real console we allocated, in both the
    # compiled exe and when run as a raw .ps1 (where [Console] is the same object the
    # default host already writes through, so this is safe either way).
    if ($script:VerboseConsoleAvailable) {
        try {
            $consoleColor = switch ($Type) {
                'OK'      { [ConsoleColor]::Green }
                'FAIL'    { [ConsoleColor]::Red }
                'WARN'    { [ConsoleColor]::Yellow }
                'SECTION' { [ConsoleColor]::Magenta }
                'APPLY'   { [ConsoleColor]::White }
                'UNDO'    { [ConsoleColor]::DarkMagenta }
                default   { [ConsoleColor]::DarkGray }
            }
            $consoleLine = if ($Type -eq 'SECTION') { "-- $Message --" } else { "[$ts] [$Type] $Message" }
            $prevColor = [Console]::ForegroundColor
            [Console]::ForegroundColor = $consoleColor
            [Console]::Out.WriteLine($consoleLine)
            [Console]::ForegroundColor = $prevColor
        } catch {}
    }

    # Mirror into the in-app scrolling Activity Log (inline collapsible panel, toggled via the ▤ Log button), once the UI has loaded.
    # $c is only populated after the WPF window loads; guard covers calls made before then.
    if ($c -and $c.ContainsKey('LogList') -and $c['LogList']) {
        try {
            $logColor = switch ($Type) {
                'OK'      { '#56dd92' }
                'FAIL'    { '#ff6b6b' }
                'WARN'    { '#f0b545' }
                'SECTION' { '#a78bff' }
                'APPLY'   { '#edecf3' }
                'UNDO'    { '#c7b8ff' }
                default   { '#8b8b9c' }
            }
            $item = [System.Windows.Controls.TextBlock]::new()
            $item.Text = if ($Type -eq 'SECTION') { "── $Message ──" } else { "[$ts] [$Type] $Message" }
            $item.Foreground   = [System.Windows.Media.BrushConverter]::new().ConvertFromString($logColor)
            $item.FontFamily   = 'Consolas'
            $item.FontSize     = 11
            $item.TextWrapping = 'Wrap'
            $c['LogList'].Items.Add($item) | Out-Null
            if ($c['LogList'].Items.Count -gt 500) { $c['LogList'].Items.RemoveAt(0) }
            $c['LogList'].ScrollIntoView($item)
        } catch {}
    }
}

# Wrap Set-Reg so every registry write is logged
function Set-RegLogged {
    param($p, $n, $v, $t = "DWord")
    Write-SR "Set  $p\$n  =  $v  ($t)" 'REG'
    Set-Reg $p $n $v $t
}
#endregion Write-SR / Coalesce / Set-RegLogged
#endregion Logging & Registry Primitives

#region Startup Helpers
# NOTE: Write-SR is available here (defined in #region Logging & Registry Primitives above).
# Set-Reg / Get-RegVal are defined later in #region Registry Helpers & Progress.
# Do not call Set-Reg or Get-RegVal from within this region.

# ── Resolve the real logged-in user (app runs elevated; HKCU = Admin hive) ──────
$script:LogonUser    = $null
$script:LogonUserSID = $null
try {
    $script:LogonUser = (Get-CimInstance Win32_ComputerSystem).UserName
    if ($script:LogonUser) {
        $script:LogonUserSID = (New-Object Security.Principal.NTAccount($script:LogonUser)).Translate(
            [Security.Principal.SecurityIdentifier]).Value
    } else {
        Write-SR "Could not resolve logged-in user - HKCU-dependent tweaks will be skipped" 'WARN'
    }
} catch {
    Write-SR "SID resolution failed: $_" 'WARN'
}

# ── Mount HKU: PSDrive if not already present ────────────────────────────────────
if (-not (Get-PSDrive HKU -ErrorAction SilentlyContinue)) {
    try {
        New-PSDrive -Name HKU -PSProvider Registry -Root HKEY_USERS | Out-Null
    } catch {
        Write-SR "Could not mount HKU: PSDrive - HKCU-dependent tweaks may not apply correctly: $_" 'WARN'
    }
}

# ── Detect discrete GPU vendor ───────────────────────────────────────────────────
$script:GpuVendor       = "none"
$script:DashboardLoaded = $false
$script:GpuName   = "No discrete GPU detected"
try {
    $gpuInfo = Get-CimInstance Win32_VideoController |
               Where-Object { $_.AdapterCompatibility -notmatch 'Intel|Microsoft' } |
               Select-Object -First 1
    if ($gpuInfo) {
        $script:GpuName = $gpuInfo.Name
        # Primary: use AdapterCompatibility; fallback to Name for drivers with empty Compatibility field
        $vendorSource = if ($gpuInfo.AdapterCompatibility) { $gpuInfo.AdapterCompatibility } else { $gpuInfo.Name }
        if ($vendorSource -match "NVIDIA") { $script:GpuVendor = "nvidia" }
        elseif ($vendorSource -match "AMD|ATI|Radeon") { $script:GpuVendor = "amd" }
        else { Write-SR "GPU detected ($($script:GpuName)) but vendor not identified - GPU tweaks unavailable" 'WARN' }
    }
} catch {
    Write-SR "GPU detection failed: $_" 'WARN'
}

# ── Find correct GPU driver class subkey (avoids hardcoding \0000) ──────────────
$script:GpuSubkey = $null
# Script-level function (PowerShell 5.1 convention - accessible globally within this session).
# Called once at startup; result cached in $script:GpuSubkey. Re-call if driver is updated.
function Get-GpuDriverSubkey {
    param([string]$Vendor)
    $classPath = "HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4d36e968-e325-11ce-bfc1-08002be10318}"
    foreach ($key in Get-ChildItem $classPath -ErrorAction SilentlyContinue) {
        $desc = (Get-ItemProperty $key.PSPath -Name DriverDesc -ErrorAction SilentlyContinue).DriverDesc
        if ($Vendor -eq "nvidia" -and $desc -match "NVIDIA") { return $key.PSPath }
        if ($Vendor -eq "amd"    -and $desc -match "AMD|Radeon") { return $key.PSPath }
    }
    return $null
}
if ($script:GpuVendor -ne "none") {
    $script:GpuSubkey = Get-GpuDriverSubkey -Vendor $script:GpuVendor
    if (-not $script:GpuSubkey) {
        Write-SR "GPU driver subkey not found for vendor: $($script:GpuVendor)" 'WARN'
    }
}

#endregion Startup Helpers

#region License System
# The Open Source Edition has no licence system. The app is fully unlocked with no nag screens.
#endregion License System

#region XAML UI
# ─── XAML ──────────────────────────────────────────────────────────────────────
[xml]$XAML = @"
<Window
    xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
    xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
    Title="StreamReady (Open Source Edition) v1.0.0" MinWidth="900" MinHeight="560"
    WindowStartupLocation="CenterScreen"
    Background="#08080e" FontFamily="Segoe UI">
<!-- #region Styles & Resources -->
<Window.Resources>
    <Style TargetType="ScrollBar">
        <Setter Property="Background" Value="Transparent"/>
        <Setter Property="Width" Value="11"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="ScrollBar">
                    <Border Background="#0b0b12" CornerRadius="5">
                        <Track x:Name="PART_Track" IsDirectionReversed="True">
                            <Track.DecreaseRepeatButton><RepeatButton Command="ScrollBar.PageUpCommand" Opacity="0" Focusable="False" IsTabStop="False"/></Track.DecreaseRepeatButton>
                            <Track.Thumb><Thumb><Thumb.Template><ControlTemplate TargetType="Thumb"><Border Background="#3a3548" CornerRadius="5" Margin="1"/></ControlTemplate></Thumb.Template></Thumb></Track.Thumb>
                            <Track.IncreaseRepeatButton><RepeatButton Command="ScrollBar.PageDownCommand" Opacity="0" Focusable="False" IsTabStop="False"/></Track.IncreaseRepeatButton>
                        </Track>
                    </Border>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
        <Style.Triggers>
            <Trigger Property="Orientation" Value="Horizontal">
                <Setter Property="Width" Value="Auto"/>
                <Setter Property="Height" Value="11"/>
                <Setter Property="Template">
                    <Setter.Value>
                        <ControlTemplate TargetType="ScrollBar">
                            <Border Background="#0b0b12" CornerRadius="5">
                                <Track x:Name="PART_Track" IsDirectionReversed="False">
                                    <Track.DecreaseRepeatButton><RepeatButton Command="ScrollBar.PageLeftCommand" Opacity="0" Focusable="False" IsTabStop="False"/></Track.DecreaseRepeatButton>
                                    <Track.Thumb><Thumb><Thumb.Template><ControlTemplate TargetType="Thumb"><Border Background="#3a3548" CornerRadius="5" Margin="1"/></ControlTemplate></Thumb.Template></Thumb></Track.Thumb>
                                    <Track.IncreaseRepeatButton><RepeatButton Command="ScrollBar.PageRightCommand" Opacity="0" Focusable="False" IsTabStop="False"/></Track.IncreaseRepeatButton>
                                </Track>
                            </Border>
                        </ControlTemplate>
                    </Setter.Value>
                </Setter>
            </Trigger>
        </Style.Triggers>
    </Style>

    <!-- Base button (shared logic, rarely used directly) -->
    <Style x:Key="Btn" TargetType="Button">
        <Setter Property="Background"      Value="#1A7C5CFF"/>
        <Setter Property="Foreground"      Value="#edecf3"/>
        <Setter Property="BorderThickness" Value="0"/>
        <Setter Property="Padding"         Value="16,8"/>
        <Setter Property="Margin"          Value="4,0"/>
        <Setter Property="Cursor"          Value="Hand"/>
        <Setter Property="FontSize"        Value="12"/>
        <Setter Property="FontWeight"      Value="SemiBold"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="Button">
                    <Border x:Name="bd" Background="{TemplateBinding Background}"
                            CornerRadius="6" Padding="{TemplateBinding Padding}">
                        <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
                    </Border>
                    <ControlTemplate.Triggers>
                        <Trigger Property="IsMouseOver" Value="True">
                            <Setter TargetName="bd" Property="Opacity" Value="0.85"/>
                        </Trigger>
                        <Trigger Property="IsPressed" Value="True">
                            <Setter TargetName="bd" Property="Opacity" Value="0.7"/>
                        </Trigger>
                        <Trigger Property="IsEnabled" Value="False">
                            <Setter TargetName="bd" Property="Background" Value="#15131f"/>
                            <Setter Property="Foreground" Value="#5f5f70"/>
                        </Trigger>
                    </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>

    <!-- Primary - purple gradient -->
    <Style x:Key="BtnPrimary" TargetType="Button">
        <Setter Property="Foreground"      Value="#FFFFFF"/>
        <Setter Property="BorderThickness" Value="0"/>
        <Setter Property="Padding"         Value="16,8"/>
        <Setter Property="Margin"          Value="4,0"/>
        <Setter Property="Cursor"          Value="Hand"/>
        <Setter Property="FontSize"        Value="12"/>
        <Setter Property="FontWeight"      Value="SemiBold"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="Button">
                    <Border x:Name="bd" CornerRadius="6" Padding="{TemplateBinding Padding}">
                        <Border.Background>
                            <LinearGradientBrush StartPoint="0,0" EndPoint="1,1">
                                <GradientStop Color="#8b6dff" Offset="0"/>
                                <GradientStop Color="#6d4eea" Offset="1"/>
                            </LinearGradientBrush>
                        </Border.Background>
                        <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
                    </Border>
                    <ControlTemplate.Triggers>
                        <Trigger Property="IsMouseOver" Value="True">
                            <Setter TargetName="bd" Property="Opacity" Value="0.88"/>
                        </Trigger>
                        <Trigger Property="IsPressed" Value="True">
                            <Setter TargetName="bd" Property="Opacity" Value="0.72"/>
                        </Trigger>
                        <Trigger Property="IsEnabled" Value="False">
                            <Setter TargetName="bd" Property="Opacity" Value="0.35"/>
                        </Trigger>
                    </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>

    <!-- Accent - red -->
    <Style x:Key="BtnAccent" TargetType="Button">
        <Setter Property="Background"      Value="#ff6b6b"/>
        <Setter Property="Foreground"      Value="#FFFFFF"/>
        <Setter Property="BorderThickness" Value="0"/>
        <Setter Property="Padding"         Value="16,8"/>
        <Setter Property="Margin"          Value="4,0"/>
        <Setter Property="Cursor"          Value="Hand"/>
        <Setter Property="FontSize"        Value="12"/>
        <Setter Property="FontWeight"      Value="SemiBold"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="Button">
                    <Border x:Name="bd" Background="{TemplateBinding Background}"
                            CornerRadius="6" Padding="{TemplateBinding Padding}">
                        <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
                    </Border>
                    <ControlTemplate.Triggers>
                        <Trigger Property="IsMouseOver" Value="True">
                            <Setter TargetName="bd" Property="Background" Value="#ff8686"/>
                        </Trigger>
                        <Trigger Property="IsPressed" Value="True">
                            <Setter TargetName="bd" Property="Background" Value="#e0504f"/>
                        </Trigger>
                        <Trigger Property="IsEnabled" Value="False">
                            <Setter TargetName="bd" Property="Background" Value="#15131f"/>
                            <Setter Property="Foreground" Value="#5f5f70"/>
                        </Trigger>
                    </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>

    <!-- Gray - secondary/undo -->
    <Style x:Key="BtnGray" TargetType="Button">
        <Setter Property="Background"      Value="#12121d"/>
        <Setter Property="Foreground"      Value="#8b8b9c"/>
        <Setter Property="BorderThickness" Value="0"/>
        <Setter Property="Padding"         Value="16,8"/>
        <Setter Property="Margin"          Value="4,0"/>
        <Setter Property="Cursor"          Value="Hand"/>
        <Setter Property="FontSize"        Value="12"/>
        <Setter Property="FontWeight"      Value="SemiBold"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="Button">
                    <Border x:Name="bd" Background="{TemplateBinding Background}"
                            CornerRadius="6" Padding="{TemplateBinding Padding}">
                        <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
                    </Border>
                    <ControlTemplate.Triggers>
                        <Trigger Property="IsMouseOver" Value="True">
                            <Setter TargetName="bd" Property="Background" Value="#1c1a30"/>
                        </Trigger>
                        <Trigger Property="IsPressed" Value="True">
                            <Setter TargetName="bd" Property="Background" Value="#0d0d16"/>
                        </Trigger>
                        <Trigger Property="IsEnabled" Value="False">
                            <Setter TargetName="bd" Property="Background" Value="#0d0d16"/>
                            <Setter Property="Foreground" Value="#5f5f70"/>
                        </Trigger>
                    </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>

    <!-- Outline - transparent with border -->
    <Style x:Key="BtnOutline" TargetType="Button">
        <Setter Property="Background"      Value="Transparent"/>
        <Setter Property="Foreground"      Value="#8b8b9c"/>
        <Setter Property="BorderThickness" Value="1"/>
        <Setter Property="BorderBrush"     Value="#597C5CFF"/>
        <Setter Property="Padding"         Value="16,8"/>
        <Setter Property="Margin"          Value="4,0"/>
        <Setter Property="Cursor"          Value="Hand"/>
        <Setter Property="FontSize"        Value="12"/>
        <Setter Property="FontWeight"      Value="SemiBold"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="Button">
                    <Border x:Name="bd" Background="{TemplateBinding Background}"
                            BorderBrush="{TemplateBinding BorderBrush}"
                            BorderThickness="{TemplateBinding BorderThickness}"
                            CornerRadius="6" Padding="{TemplateBinding Padding}">
                        <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
                    </Border>
                    <ControlTemplate.Triggers>
                        <Trigger Property="IsMouseOver" Value="True">
                            <Setter TargetName="bd" Property="Background" Value="#0F7C5CFF"/>
                        </Trigger>
                        <Trigger Property="IsPressed" Value="True">
                            <Setter TargetName="bd" Property="Background" Value="#1A7C5CFF"/>
                        </Trigger>
                    </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>

    <!-- Small utility buttons -->
    <Style x:Key="BtnSmall" TargetType="Button">
        <Setter Property="Background"      Value="#12121d"/>
        <Setter Property="Foreground"      Value="#8b8b9c"/>
        <Setter Property="BorderThickness" Value="0"/>
        <Setter Property="Padding"         Value="12,6"/>
        <Setter Property="Margin"          Value="3,2"/>
        <Setter Property="Cursor"          Value="Hand"/>
        <Setter Property="FontSize"        Value="11"/>
        <Setter Property="FontWeight"      Value="SemiBold"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="Button">
                    <Border x:Name="bd" Background="{TemplateBinding Background}"
                            CornerRadius="5" Padding="{TemplateBinding Padding}">
                        <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
                    </Border>
                    <ControlTemplate.Triggers>
                        <Trigger Property="IsMouseOver" Value="True">
                            <Setter TargetName="bd" Property="Background" Value="#1c1a30"/>
                        </Trigger>
                        <Trigger Property="IsPressed" Value="True">
                            <Setter TargetName="bd" Property="Background" Value="#0d0d16"/>
                        </Trigger>
                    </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>

    <!-- Toggle switch (Marshal-style instrument-panel look) - replaces the old
         square gradient-fill checkbox. Same IsChecked-trigger mechanism as before,
         just pill/thumb geometry instead of a filled square. -->
    <Style x:Key="Chk" TargetType="CheckBox">
        <Setter Property="Foreground"               Value="#c9c7d6"/>
        <Setter Property="Margin"                   Value="2,5"/>
        <Setter Property="FontSize"                 Value="12"/>
        <Setter Property="Cursor"                   Value="Hand"/>
        <Setter Property="VerticalContentAlignment" Value="Center"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="CheckBox">
                    <StackPanel Orientation="Horizontal">
                        <Border x:Name="track" Width="30" Height="16" CornerRadius="8"
                                BorderThickness="1" BorderBrush="#28242f" Background="#171522"
                                VerticalAlignment="Center" Margin="0,0,9,0">
                            <Border x:Name="thumb" Width="12" Height="12" CornerRadius="6"
                                    Background="#767685"
                                    HorizontalAlignment="Left" Margin="1,0,0,0"/>
                        </Border>
                        <ContentPresenter VerticalAlignment="Center"/>
                    </StackPanel>
                    <ControlTemplate.Triggers>
                        <Trigger Property="IsChecked" Value="True">
                            <Setter TargetName="track" Property="BorderThickness" Value="0"/>
                            <Setter TargetName="track" Property="Background">
                                <Setter.Value>
                                    <LinearGradientBrush StartPoint="0,0" EndPoint="1,1">
                                        <GradientStop Color="#8b6dff" Offset="0"/>
                                        <GradientStop Color="#6d4eea" Offset="1"/>
                                    </LinearGradientBrush>
                                </Setter.Value>
                            </Setter>
                            <Setter TargetName="thumb" Property="HorizontalAlignment" Value="Right"/>
                            <Setter TargetName="thumb" Property="Margin" Value="0,0,1,0"/>
                            <Setter TargetName="thumb" Property="Background" Value="#FFFFFF"/>
                        </Trigger>
                        <Trigger Property="IsEnabled" Value="False">
                            <Setter Property="Opacity" Value="0.5"/>
                        </Trigger>
                    </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>
    <Style x:Key="ChkWarn" TargetType="CheckBox" BasedOn="{StaticResource Chk}">
        <Setter Property="Foreground" Value="#ff6b6b"/>
    </Style>

    <!-- Section header label - purple (default) -->
    <Style x:Key="SecHdr" TargetType="TextBlock">
        <Setter Property="Foreground"  Value="#a78bff"/>
        <Setter Property="FontSize"    Value="9"/>
        <Setter Property="FontWeight"  Value="Bold"/>
        <Setter Property="Margin"      Value="0,0,0,10"/>
    </Style>
    <!-- Section header label - red (destructive sections only) -->
    <Style x:Key="SecHdrRed" TargetType="TextBlock">
        <Setter Property="Foreground"  Value="#ff6b6b"/>
        <Setter Property="FontSize"    Value="9"/>
        <Setter Property="FontWeight"  Value="Bold"/>
        <Setter Property="Margin"      Value="0,0,0,10"/>
    </Style>

    <!-- Universal card -->
    <Style x:Key="Card" TargetType="Border">
        <Setter Property="Background"      Value="#0d0d16"/>
        <Setter Property="BorderBrush"     Value="#2E7C5CFF"/>
        <Setter Property="BorderThickness" Value="1"/>
        <Setter Property="CornerRadius"    Value="8"/>
        <Setter Property="Padding"         Value="14,16"/>
        <Setter Property="Margin"          Value="0,0,0,10"/>
    </Style>

    <!-- Description text under checkboxes - left margin matches the toggle-switch
         width (30px track + 9px gap) above so it lines up under the label text -->
    <Style x:Key="Desc" TargetType="TextBlock">
        <Setter Property="Foreground"   Value="#5f5f70"/>
        <Setter Property="FontSize"     Value="10"/>
        <Setter Property="Margin"       Value="39,0,0,4"/>
        <Setter Property="TextWrapping" Value="Wrap"/>
    </Style>

    <!-- Separator line -->
    <Style x:Key="Sep" TargetType="Separator">
        <Setter Property="Background" Value="#2E7C5CFF"/>
        <Setter Property="Margin"     Value="0,8"/>
        <Setter Property="Height"     Value="1"/>
    </Style>

    <!-- ListBox (startup list) -->
    <!-- Applies to every ListBox in the app (implicit style, no x:Key) - WPF's default
         ListBox template shows a horizontal scrollbar the instant item content is even
         1px wider than available space, which bit the icon-only sidebar rail (40px items
         in a 64px column, zero slack) after the redesign. Disabling it centrally here
         covers every current and future ListBox instead of setting it on each one. -->
    <Style TargetType="ListBox">
        <Setter Property="Background"      Value="#0d0d16"/>
        <Setter Property="Foreground"      Value="#edecf3"/>
        <Setter Property="BorderBrush"     Value="#2E7C5CFF"/>
        <Setter Property="BorderThickness" Value="1"/>
        <Setter Property="FontSize"        Value="11"/>
        <Setter Property="ScrollViewer.HorizontalScrollBarVisibility" Value="Disabled"/>
    </Style>
    <Style TargetType="ListBoxItem">
        <Setter Property="Padding" Value="8,4"/>
        <Setter Property="Cursor"  Value="Hand"/>
        <Style.Triggers>
            <Trigger Property="IsSelected"  Value="True"><Setter Property="Background" Value="#1A7C5CFF"/></Trigger>
            <Trigger Property="IsMouseOver" Value="True"><Setter Property="Background" Value="#0F7C5CFF"/></Trigger>
        </Style.Triggers>
    </Style>

    <!-- Progress bar - solid fill via TemplateBinding Foreground (runtime color changes stay working) -->
    <Style TargetType="ProgressBar">
        <Setter Property="Background"      Value="#1A7C5CFF"/>
        <Setter Property="Foreground"      Value="#7c5cff"/>
        <Setter Property="BorderThickness" Value="0"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="ProgressBar">
                    <Border Background="{TemplateBinding Background}" ClipToBounds="True">
                        <Border x:Name="PART_Indicator" HorizontalAlignment="Left"
                                Background="{TemplateBinding Foreground}"/>
                    </Border>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>
    <Style x:Key="ScoreCardButton" TargetType="Button">
        <Setter Property="Background" Value="#0d0d16"/><Setter Property="Foreground" Value="#edecf3"/>
        <Setter Property="BorderBrush" Value="#28242f"/><Setter Property="BorderThickness" Value="1"/>
        <Setter Property="Padding" Value="14"/><Setter Property="HorizontalContentAlignment" Value="Stretch"/>
        <Setter Property="Cursor" Value="Hand"/>
        <Setter Property="Template"><Setter.Value><ControlTemplate TargetType="Button">
            <Border Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}" CornerRadius="8" Padding="{TemplateBinding Padding}"><ContentPresenter HorizontalAlignment="Stretch"/></Border>
        </ControlTemplate></Setter.Value></Setter>
        <Style.Triggers>
            <Trigger Property="IsMouseOver" Value="True"><Setter Property="BorderBrush" Value="#a78bff"/><Setter Property="Background" Value="#171326"/></Trigger>
            <Trigger Property="IsKeyboardFocused" Value="True"><Setter Property="BorderBrush" Value="#a78bff"/><Setter Property="BorderThickness" Value="2"/></Trigger>
            <Trigger Property="IsEnabled" Value="False"><Setter Property="Cursor" Value="Arrow"/></Trigger>
        </Style.Triggers>
    </Style>

    <!-- v7 shell styles (top bar, mode switch, goal cards, links, big Undo) -->
    <Style x:Key="BtnSeg" TargetType="Button">
        <Setter Property="Background"      Value="Transparent"/>
        <Setter Property="Foreground"      Value="#8b8b9c"/>
        <Setter Property="BorderThickness" Value="0"/>
        <Setter Property="Padding"         Value="22,6"/>
        <Setter Property="Margin"          Value="0"/>
        <Setter Property="Cursor"          Value="Hand"/>
        <Setter Property="FontSize"        Value="13"/>
        <Setter Property="FontWeight"      Value="SemiBold"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="Button">
                    <Border x:Name="bd" Background="{TemplateBinding Background}"
                            CornerRadius="6" Padding="{TemplateBinding Padding}">
                        <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
                    </Border>
                    <ControlTemplate.Triggers>
                        <Trigger Property="IsMouseOver" Value="True">
                            <Setter TargetName="bd" Property="Opacity" Value="0.88"/>
                        </Trigger>
                    </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>

    <Style x:Key="BtnTop" TargetType="Button">
        <Setter Property="Background"      Value="Transparent"/>
        <Setter Property="Foreground"      Value="#c9c7d6"/>
        <Setter Property="BorderThickness" Value="0"/>
        <Setter Property="Padding"         Value="12,7"/>
        <Setter Property="Margin"          Value="2,0"/>
        <Setter Property="Cursor"          Value="Hand"/>
        <Setter Property="FontSize"        Value="13"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="Button">
                    <Border x:Name="bd" Background="{TemplateBinding Background}"
                            CornerRadius="6" Padding="{TemplateBinding Padding}">
                        <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
                    </Border>
                    <ControlTemplate.Triggers>
                        <Trigger Property="IsMouseOver" Value="True">
                            <Setter TargetName="bd" Property="Background" Value="#1A7C5CFF"/>
                            <Setter Property="Foreground" Value="#edecf3"/>
                        </Trigger>
                    </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>

    <Style x:Key="BtnLink" TargetType="Button">
        <Setter Property="Background"      Value="Transparent"/>
        <Setter Property="Foreground"      Value="#a78bff"/>
        <Setter Property="BorderThickness" Value="0"/>
        <Setter Property="Padding"         Value="0,4"/>
        <Setter Property="Margin"          Value="0"/>
        <Setter Property="Cursor"          Value="Hand"/>
        <Setter Property="FontSize"        Value="13"/>
        <Setter Property="HorizontalContentAlignment" Value="Left"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="Button">
                    <Border Background="Transparent" Padding="{TemplateBinding Padding}">
                        <ContentPresenter HorizontalAlignment="{TemplateBinding HorizontalContentAlignment}" VerticalAlignment="Center"/>
                    </Border>
                    <ControlTemplate.Triggers>
                        <Trigger Property="IsMouseOver" Value="True">
                            <Setter Property="Foreground" Value="#c9b8ff"/>
                        </Trigger>
                    </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>

    <Style x:Key="BtnCard" TargetType="Button">
        <Setter Property="Background"      Value="#0d0d16"/>
        <Setter Property="Foreground"      Value="#edecf3"/>
        <Setter Property="BorderBrush"     Value="#28242f"/>
        <Setter Property="BorderThickness" Value="1"/>
        <Setter Property="Padding"         Value="14,12"/>
        <Setter Property="Margin"          Value="0,0,10,10"/>
        <Setter Property="Cursor"          Value="Hand"/>
        <Setter Property="HorizontalContentAlignment" Value="Stretch"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="Button">
                    <Border x:Name="bd" Background="{TemplateBinding Background}"
                            BorderBrush="{TemplateBinding BorderBrush}"
                            BorderThickness="{TemplateBinding BorderThickness}"
                            CornerRadius="8" Padding="{TemplateBinding Padding}">
                        <ContentPresenter HorizontalAlignment="Stretch" VerticalAlignment="Center"/>
                    </Border>
                    <ControlTemplate.Triggers>
                        <Trigger Property="IsMouseOver" Value="True">
                            <Setter TargetName="bd" Property="BorderBrush" Value="#7c5cff"/>
                            <Setter TargetName="bd" Property="Background" Value="#12121d"/>
                        </Trigger>
                        <Trigger Property="IsPressed" Value="True">
                            <Setter TargetName="bd" Property="Background" Value="#1A7C5CFF"/>
                        </Trigger>
                    </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>

    <Style x:Key="BtnUndoBig" TargetType="Button">
        <Setter Property="Background"      Value="Transparent"/>
        <Setter Property="Foreground"      Value="#a78bff"/>
        <Setter Property="BorderBrush"     Value="#597C5CFF"/>
        <Setter Property="BorderThickness" Value="1"/>
        <Setter Property="Padding"         Value="18,8"/>
        <Setter Property="Cursor"          Value="Hand"/>
        <Setter Property="FontSize"        Value="13"/>
        <Setter Property="FontWeight"      Value="SemiBold"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="Button">
                    <Border x:Name="bd" Background="{TemplateBinding Background}"
                            BorderBrush="{TemplateBinding BorderBrush}"
                            BorderThickness="{TemplateBinding BorderThickness}"
                            CornerRadius="8" Padding="{TemplateBinding Padding}">
                        <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
                    </Border>
                    <ControlTemplate.Triggers>
                        <Trigger Property="IsMouseOver" Value="True">
                            <Setter TargetName="bd" Property="Background" Value="#1A7C5CFF"/>
                        </Trigger>
                        <Trigger Property="IsEnabled" Value="False">
                            <Setter TargetName="bd" Property="BorderBrush" Value="#28242f"/>
                            <Setter Property="Foreground" Value="#5f5f70"/>
                        </Trigger>
                    </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>

    <Style x:Key="BtnNav" TargetType="Button">
        <Setter Property="Background"      Value="Transparent"/>
        <Setter Property="Foreground"      Value="#8b8b9c"/>
        <Setter Property="BorderBrush"     Value="Transparent"/>
        <Setter Property="BorderThickness" Value="0,0,0,2"/>
        <Setter Property="Padding"         Value="16,10"/>
        <Setter Property="Cursor"          Value="Hand"/>
        <Setter Property="FontSize"        Value="13"/>
        <Setter Property="FontWeight"      Value="SemiBold"/>
        <Setter Property="Template">
            <Setter.Value>
                <ControlTemplate TargetType="Button">
                    <Border x:Name="bd" Background="{TemplateBinding Background}"
                            BorderBrush="{TemplateBinding BorderBrush}"
                            BorderThickness="{TemplateBinding BorderThickness}"
                            Padding="{TemplateBinding Padding}">
                        <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
                    </Border>
                    <ControlTemplate.Triggers>
                        <Trigger Property="IsMouseOver" Value="True">
                            <Setter Property="Foreground" Value="#edecf3"/>
                        </Trigger>
                    </ControlTemplate.Triggers>
                </ControlTemplate>
            </Setter.Value>
        </Setter>
    </Style>
<!-- #endregion Styles & Resources -->
</Window.Resources>
<Grid x:Name="RootGrid" Background="#08080e">
    <Grid.RowDefinitions>
        <RowDefinition Height="Auto"/>
        <RowDefinition Height="*"/>
        <RowDefinition Height="Auto"/>
        <RowDefinition Height="Auto"/>
    </Grid.RowDefinitions>
    <!-- Header (Row 0) - collapsed as of the 2026-09-24 redesign (Option D has no persistent
         top chrome bar; admin/version status moved into the Dashboard's own header row below).
         Row height set to 0 and content removed rather than deleting the RowDefinition, so every
         other Grid.Row index in this window doesn't need renumbering. -->
    <!-- v7 top bar: logo + version, Simple | Pro switch, Search, Help, Log, About -->
    <StackPanel Grid.Row="0">
    <Border Background="#050508" BorderBrush="#1E7C5CFF" BorderThickness="0,0,0,1" Padding="16,9">
        <DockPanel LastChildFill="False">
            <StackPanel DockPanel.Dock="Left" Orientation="Horizontal" VerticalAlignment="Center">
                <Border Width="28" Height="28" CornerRadius="6" VerticalAlignment="Center">
                    <Border.Background>
                        <LinearGradientBrush StartPoint="0,0" EndPoint="1,1">
                            <GradientStop Color="#a78bff" Offset="0"/>
                            <GradientStop Color="#6d4eea" Offset="1"/>
                        </LinearGradientBrush>
                    </Border.Background>
                    <TextBlock Text="S" FontSize="14" FontWeight="Black" Foreground="White"
                               HorizontalAlignment="Center" VerticalAlignment="Center"/>
                </Border>
                <TextBlock Text="StreamReady" FontSize="16" FontWeight="Bold" Foreground="#edecf3"
                           Margin="10,0,6,0" VerticalAlignment="Center"/>
                <TextBlock Text="v1.0.0" FontSize="11" Foreground="#8b8b9c" VerticalAlignment="Center"/>
                <Border x:Name="ModeSwitch" Margin="20,0,0,0" Background="#0d0d16" BorderBrush="#28242f"
                        BorderThickness="1" CornerRadius="8" Padding="2" VerticalAlignment="Center">
                    <StackPanel Orientation="Horizontal">
                        <Button x:Name="BtnModeSimple" Content="Simple" Style="{StaticResource BtnSeg}"
                                ToolTip="Friendly view: pick a goal and let StreamReady choose the safe settings."/>
                        <Button x:Name="BtnModePro" Content="Pro" Style="{StaticResource BtnSeg}"
                                ToolTip="Every setting, grouped by area."/>
                    </StackPanel>
                </Border>
            </StackPanel>
            <StackPanel DockPanel.Dock="Right" Orientation="Horizontal" VerticalAlignment="Center">
                <Border Width="190" Height="32" Margin="0,0,10,0" Background="#0d0d16" BorderBrush="#28242f"
                        BorderThickness="1" CornerRadius="8">
                    <Grid>
                        <TextBox x:Name="TxtSearch" Background="Transparent" BorderThickness="0" Foreground="#edecf3"
                                 CaretBrush="#edecf3" FontSize="13" Padding="10,0" VerticalContentAlignment="Center"
                                 ToolTip="Search every setting by name or what it does (Ctrl+K)"/>
                        <TextBlock x:Name="TxtSearchHint" Text="Search settings" Foreground="#8b8b9c" FontSize="13"
                                   Margin="12,0,0,0" VerticalAlignment="Center" IsHitTestVisible="False"/>
                    </Grid>
                </Border>
                <Button x:Name="BtnHelp" Content="Help" Style="{StaticResource BtnTop}" ToolTip="Help, glossary and Show welcome again"/>
                <Button x:Name="BtnToggleLog" Content="Log" Style="{StaticResource BtnTop}" ToolTip="Show or hide the activity log"/>
                <Button x:Name="BtnAbout" Content="About" Style="{StaticResource BtnTop}"/>
            </StackPanel>
        </DockPanel>
    </Border>
    <Border x:Name="NavRow" Background="#08080e" BorderBrush="#1E7C5CFF" BorderThickness="0,0,0,1" Padding="16,0">
        <DockPanel LastChildFill="False">
            <StackPanel DockPanel.Dock="Left" Orientation="Horizontal">
                <Button x:Name="BtnNavHome" Content="Home" Style="{StaticResource BtnNav}"/>
                <Button x:Name="BtnNavMyPc" Content="My PC" Style="{StaticResource BtnNav}"/>
                <Button x:Name="BtnNavHistory" Content="History and Undo" Style="{StaticResource BtnNav}"/>
                <Button x:Name="BtnNavSettings" Content="Settings" Style="{StaticResource BtnNav}"/>
            </StackPanel>
            <TextBlock x:Name="NavPcText" DockPanel.Dock="Right" Text="" FontSize="12" Foreground="#8b8b9c" VerticalAlignment="Center"/>
        </DockPanel>
    </Border>
    </StackPanel>
    <!-- #region Sidebar Navigation -->
    <Grid x:Name="ProHost" Grid.Row="1" Visibility="Collapsed">
        <Grid.ColumnDefinitions>
            <ColumnDefinition Width="64"/>
            <ColumnDefinition Width="*"/>
        </Grid.ColumnDefinitions>

        <!-- ── Sidebar - icon-only rail (Option D) ─────────────────────────── -->
        <Border Grid.Column="0" Background="#050508" BorderBrush="#1E7C5CFF" BorderThickness="0,0,1,0">
            <DockPanel>
                <!-- Logo mark -->
                <Border DockPanel.Dock="Top" Width="28" Height="28" CornerRadius="6"
                        Margin="0,16,0,18" HorizontalAlignment="Center">
                    <Border.Background>
                        <LinearGradientBrush StartPoint="0,0" EndPoint="1,1">
                            <GradientStop Color="#a78bff" Offset="0"/>
                            <GradientStop Color="#6d4eea" Offset="1"/>
                        </LinearGradientBrush>
                    </Border.Background>
                    <TextBlock Text="S" FontSize="14" FontWeight="Black" Foreground="White"
                               HorizontalAlignment="Center" VerticalAlignment="Center"/>
                </Border>
                <!-- Nav ListBox - icon-only, tooltip carries the label -->
                <ListBox x:Name="SideNav" Background="Transparent" BorderThickness="0"
                         SelectionMode="Single" HorizontalContentAlignment="Center">
                    <ListBox.ItemContainerStyle>
                        <Style TargetType="ListBoxItem">
                            <Setter Property="Width"           Value="40"/>
                            <Setter Property="Height"          Value="36"/>
                            <Setter Property="Margin"          Value="12,0,12,4"/>
                            <Setter Property="HorizontalContentAlignment" Value="Center"/>
                            <Setter Property="VerticalContentAlignment"   Value="Center"/>
                            <Setter Property="Foreground"      Value="#767685"/>
                            <Setter Property="Background"      Value="Transparent"/>
                            <Setter Property="BorderThickness" Value="1"/>
                            <Setter Property="BorderBrush"     Value="Transparent"/>
                            <Setter Property="Cursor"          Value="Hand"/>
                            <Setter Property="FontSize"        Value="15"/>
                            <Setter Property="Template">
                                <Setter.Value>
                                    <ControlTemplate TargetType="ListBoxItem">
                                        <Border x:Name="bd" CornerRadius="6"
                                                Background="{TemplateBinding Background}"
                                                BorderBrush="{TemplateBinding BorderBrush}"
                                                BorderThickness="{TemplateBinding BorderThickness}">
                                            <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
                                        </Border>
                                        <ControlTemplate.Triggers>
                                            <Trigger Property="IsSelected" Value="True">
                                                <Setter TargetName="bd" Property="Background"  Value="#1A7C5CFF"/>
                                                <Setter TargetName="bd" Property="BorderBrush" Value="#597C5CFF"/>
                                                <Setter Property="Foreground" Value="#a78bff"/>
                                            </Trigger>
                                            <Trigger Property="IsMouseOver" Value="True">
                                                <Setter TargetName="bd" Property="Background" Value="#0F7C5CFF"/>
                                                <Setter Property="Foreground" Value="#c9c7d6"/>
                                            </Trigger>
                                        </ControlTemplate.Triggers>
                                    </ControlTemplate>
                                </Setter.Value>
                            </Setter>
                        </Style>
                    </ListBox.ItemContainerStyle>
                    <ListBoxItem Tag="SecDashboard" Content="⚡" ToolTip="Dashboard"/>
                    <ListBoxItem Tag="SecGaming"    Content="🎮" ToolTip="Gaming"/>
                    <ListBoxItem Tag="SecPrivacy"   Content="🔒" ToolTip="Privacy"/>
                    <ListBoxItem Tag="SecTweaks"    Content="🔧" ToolTip="Tweaks"/>
                    <ListBoxItem Tag="SecNetwork"   Content="🌐" ToolTip="Network"/>
                    <ListBoxItem Tag="SecUpdates"   Content="🔄" ToolTip="Updates"/>
                    <ListBoxItem Tag="SecSystem"    Content="💻" ToolTip="System"/>
                    <ListBoxItem Tag="SecDownloads" Content="🔽" ToolTip="Downloads"/>
                </ListBox>
            </DockPanel>
        </Border>

        <!-- ── Content Area ─────────────────────────────────────────────── -->
        <ScrollViewer Grid.Column="1" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled" Background="#08080e">
            <StackPanel x:Name="ContentArea">

                <!-- #region Dashboard Section -->
                <Border x:Name="SecDashboard" Visibility="Visible" Margin="0">
                <StackPanel Margin="20">
                    <DockPanel Margin="0,0,0,14" LastChildFill="False">
                        <TextBlock DockPanel.Dock="Left" Text="System Overview" FontSize="16" FontWeight="SemiBold"
                                   Foreground="#edecf3"/>
                        <TextBlock DockPanel.Dock="Right" Text="✓ Admin  ·  v1.0.0" FontSize="11"
                                   Foreground="#5f5f70" VerticalAlignment="Center"/>
                    </DockPanel>

                    <!-- Stats row: CPU / GPU / RAM / Ping - label carries identity ("CPU · i9-14900K"),
                         the big value is a live metric (temp/load/usage/ping), sub-line is secondary
                         spec info, sparkline redraws on each Update-DashboardMetrics tick. -->
                    <UniformGrid Rows="1" Columns="4" Margin="0,0,0,12">
                        <Border Background="#12121d" BorderBrush="#28242f" BorderThickness="1" CornerRadius="6" Margin="0,0,6,0" Padding="12">
                            <StackPanel>
                                <TextBlock x:Name="LblDashCpuLabel" Text="CPU" FontSize="9" FontWeight="Bold" Foreground="#a78bff" Margin="0,0,0,4" TextTrimming="CharacterEllipsis"/>
                                <DockPanel LastChildFill="False">
                                    <TextBlock x:Name="LblDashCpu" DockPanel.Dock="Left" Text="-" FontSize="14" FontWeight="Bold" Foreground="#edecf3" Typography.NumeralAlignment="Tabular"/>
                                    <Polyline x:Name="SparkCpu" DockPanel.Dock="Right" Width="48" Height="20" Stroke="#7c5cff" StrokeThickness="1.6" StrokeLineJoin="Round"/>
                                </DockPanel>
                                <TextBlock x:Name="LblDashCpuSub" Text="-" FontSize="10" Foreground="#8b8b9c" Margin="0,2,0,0" Typography.NumeralAlignment="Tabular"/>
                            </StackPanel>
                        </Border>
                        <Border Background="#12121d" BorderBrush="#28242f" BorderThickness="1" CornerRadius="6" Margin="0,0,6,0" Padding="12">
                            <StackPanel>
                                <TextBlock x:Name="LblDashGpuLabel" Text="GPU" FontSize="9" FontWeight="Bold" Foreground="#a78bff" Margin="0,0,0,4" TextTrimming="CharacterEllipsis"/>
                                <DockPanel LastChildFill="False">
                                    <TextBlock x:Name="LblDashGpu" DockPanel.Dock="Left" Text="-" FontSize="14" FontWeight="Bold" Foreground="#edecf3" Typography.NumeralAlignment="Tabular"/>
                                    <Polyline x:Name="SparkGpu" DockPanel.Dock="Right" Width="48" Height="20" Stroke="#c77dff" StrokeThickness="1.6" StrokeLineJoin="Round"/>
                                </DockPanel>
                            </StackPanel>
                        </Border>
                        <Border Background="#12121d" BorderBrush="#28242f" BorderThickness="1" CornerRadius="6" Margin="0,0,6,0" Padding="12">
                            <StackPanel>
                                <TextBlock x:Name="LblDashRamLabel" Text="RAM" FontSize="9" FontWeight="Bold" Foreground="#a78bff" Margin="0,0,0,4"/>
                                <DockPanel LastChildFill="False">
                                    <TextBlock x:Name="LblDashRam" DockPanel.Dock="Left" Text="-" FontSize="14" FontWeight="Bold" Foreground="#edecf3" Typography.NumeralAlignment="Tabular"/>
                                    <Polyline x:Name="SparkRam" DockPanel.Dock="Right" Width="48" Height="20" Stroke="#56dd92" StrokeThickness="1.6" StrokeLineJoin="Round"/>
                                </DockPanel>
                                <TextBlock x:Name="LblDashRamSub" Text="-" FontSize="10" Foreground="#8b8b9c" Margin="0,2,0,0" Typography.NumeralAlignment="Tabular"/>
                            </StackPanel>
                        </Border>
                        <Border Background="#12121d" BorderBrush="#28242f" BorderThickness="1" CornerRadius="6" Padding="12">
                            <StackPanel>
                                <TextBlock Text="PING" FontSize="9" FontWeight="Bold" Foreground="#a78bff" Margin="0,0,0,4"/>
                                <DockPanel LastChildFill="False">
                                <TextBlock x:Name="LblDashPing" DockPanel.Dock="Left" Text="…" FontSize="14" FontWeight="Bold" Foreground="#edecf3" Typography.NumeralAlignment="Tabular"/>
                                <Polyline x:Name="SparkPing" DockPanel.Dock="Right" Width="48" Height="20" Stroke="#56dd92" StrokeThickness="1.6" StrokeLineJoin="Round"/>
                                </DockPanel>
                                <TextBlock x:Name="LblDashPingSub" Text="8.8.8.8" FontSize="10" Foreground="#8b8b9c" Margin="0,2,0,0" Typography.NumeralAlignment="Tabular"/>
                            </StackPanel>
                        </Border>
                    </UniformGrid>

                    <!-- Timer resolution status banner -->
                    <Border x:Name="BannerTimerActive" Background="#0e2a1e" BorderBrush="#2fae6f"
                            BorderThickness="1" CornerRadius="6" Padding="12,8" Margin="0,0,0,12"
                            Visibility="Collapsed">
                        <DockPanel>
                            <TextBlock DockPanel.Dock="Right" Text="ACTIVE" FontSize="10" FontWeight="Bold"
                                       Foreground="#56dd92" VerticalAlignment="Center" Margin="8,0,0,0"/>
                            <StackPanel>
                                <TextBlock Text="⏱ Timer Resolution - 0.5ms" FontSize="11" FontWeight="Bold" Foreground="#56dd92"/>
                                <TextBlock Text="Maximum precision active · Windows default is 15.6ms"
                                           FontSize="10" Foreground="#8b8b9c" Margin="0,2,0,0"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>
                    <Border x:Name="BannerTimerDefault" Background="#12121d" BorderBrush="#28242f"
                            BorderThickness="1" CornerRadius="6" Padding="12,8" Margin="0,0,0,12"
                            Visibility="Visible">
                        <TextBlock Text="⏱ Timer Resolution - 15.6ms (Windows default)"
                                   FontSize="11" Foreground="#8b8b9c"/>
                    </Border>

                    <!-- System Health Report -->
                    <Border Background="#12121d" BorderBrush="#28242f" BorderThickness="1" CornerRadius="6" Padding="12,10" Margin="0,0,0,14">
                        <StackPanel>
                            <DockPanel Margin="0,0,0,8">
                                <Button x:Name="BtnRefreshHealth" DockPanel.Dock="Right" Content="↻" Style="{StaticResource BtnGray}" Width="26" Height="20" FontSize="12" Padding="0"/>
                                <TextBlock Text="SYSTEM HEALTH" FontSize="9" FontWeight="Bold" Foreground="#5f5f70" VerticalAlignment="Center"/>
                            </DockPanel>
                            <TextBlock x:Name="LblHealthRam"      Text="RAM: checking..." FontSize="11" Foreground="#8b8b9c" Margin="0,2"/>
                            <TextBlock x:Name="LblHealthDisplay"  Text="Display: checking..." FontSize="11" Foreground="#8b8b9c" Margin="0,2"/>
                            <TextBlock x:Name="LblHealthNetwork"  Text="Network: checking..." FontSize="11" Foreground="#8b8b9c" Margin="0,2"/>
                            <TextBlock x:Name="LblHealthStorage"  Text="Storage: checking..." FontSize="11" Foreground="#8b8b9c" Margin="0,2"/>
                            <TextBlock x:Name="LblHealthRebar"    Text="ReBAR: checking..." FontSize="11" Foreground="#8b8b9c" Margin="0,2"/>
                            <TextBlock x:Name="LblHealthCpu"      Text="CPU: checking..." FontSize="11" Foreground="#8b8b9c" Margin="0,2"/>
                            <TextBlock x:Name="LblHealthPagefile" Text="Pagefile: checking..." FontSize="11" Foreground="#8b8b9c" Margin="0,2"/>
                            <TextBlock x:Name="LblHealthGpuTemp"  Text="GPU Temp: checking..." FontSize="11" Foreground="#8b8b9c" Margin="0,2"/>
                            <TextBlock x:Name="LblHealthDrivers"  Text="Drivers: checking..." FontSize="11" Foreground="#8b8b9c" Margin="0,2"/>
                        </StackPanel>
                    </Border>

                    <!-- Tweak drift banner: shown only when a previously-applied tweak has been reset
                         (typically by a Windows Update) since the last time StreamReady checked. -->
                    <Border x:Name="BannerDriftDetected" Background="#2c2410" BorderBrush="#f0b545"
                            BorderThickness="1" CornerRadius="6" Padding="12,8" Margin="0,0,0,14"
                            Visibility="Collapsed">
                        <DockPanel>
                            <Button x:Name="BtnReapplyDrifted" DockPanel.Dock="Right" Content="↻ Reapply"
                                    Style="{StaticResource BtnAccent}" Height="28" Padding="10,0" Margin="8,0,0,0"/>
                            <StackPanel>
                                <TextBlock x:Name="LblDriftTitle" Text="⚠ Tweaks reset" FontSize="11" FontWeight="Bold" Foreground="#f0b545"/>
                                <TextBlock x:Name="LblDriftDetail" Text="" FontSize="10" Foreground="#8b8b9c" Margin="0,2,0,0" TextWrapping="Wrap"/>
                            </StackPanel>
                        </DockPanel>
                    </Border>

                    <!-- Active optimisations (toggle matrix) + Presets - two-column
                         instrument-panel layout, Option D -->
                    <Grid Margin="0,0,0,0">
                        <Grid.ColumnDefinitions>
                            <ColumnDefinition Width="1.3*"/>
                            <ColumnDefinition Width="16"/>
                            <ColumnDefinition Width="1*"/>
                        </Grid.ColumnDefinitions>

                        <Border Grid.Column="0" Background="#12121d" BorderBrush="#28242f"
                                BorderThickness="1" CornerRadius="6" Padding="14,12" VerticalAlignment="Top">
                            <StackPanel>
                                <TextBlock x:Name="LblActiveOptHeader" Text="ACTIVE OPTIMISATIONS"
                                           FontSize="11" FontWeight="Bold" Foreground="#c9c7d6" Margin="0,0,0,8"/>
                                <Separator Style="{StaticResource Sep}"/>
                                <UniformGrid x:Name="PanelActiveBadges" Columns="2" Margin="0,4,0,0"/>
                            </StackPanel>
                        </Border>

                        <Border Grid.Column="2" Background="#12121d" BorderBrush="#28242f"
                                BorderThickness="1" CornerRadius="6" Padding="14,12" VerticalAlignment="Top">
                            <StackPanel>
                                <TextBlock Text="PRESETS" FontSize="11" FontWeight="Bold" Foreground="#c9c7d6" Margin="0,0,0,8"/>
                                <Separator Style="{StaticResource Sep}"/>
                                <TextBlock Text="Pick a preset to tick a recommended set of tweaks. Nothing is applied until you review your list and press Apply."
                                           FontSize="10.5" Foreground="#8b8b9c" TextWrapping="Wrap" Margin="0,2,0,8"/>
                                <UniformGrid Rows="1" Columns="2">
                                    <Button x:Name="BtnDashPresetGaming"    Content="Gaming"    Style="{StaticResource BtnSmall}" Margin="0,0,4,0" ToolTip="Safe latency and performance tweaks, no usability loss"/>
                                    <Button x:Name="BtnDashPresetStreaming" Content="Streaming" Style="{StaticResource BtnSmall}" ToolTip="The Gaming set plus OBS priority and sound ducking"/>
                                </UniformGrid>
                            </StackPanel>
                        </Border>
                    </Grid>
                </StackPanel>
                </Border>
                <!-- #endregion Dashboard Section -->

                <!-- #region Gaming Section -->
                <Border x:Name="SecGaming" Visibility="Collapsed" Background="#08080e">
                <StackPanel>
                    <!-- Sub-tab bar -->
                    <Border Background="#050508" BorderBrush="#1E7C5CFF" BorderThickness="0,0,0,1"
                            Padding="0,0,0,0">
                        <StackPanel Orientation="Horizontal" Margin="14,0">
                            <Border x:Name="BtnGamTabTweaks" Cursor="Hand" Padding="0,0,24,0">
                                <StackPanel>
                                    <TextBlock Text="Tweaks" Foreground="#a78bff"
                                               FontSize="12" FontWeight="SemiBold"
                                               Margin="0,10,0,8"/>
                                    <Rectangle Height="2" Fill="#7c5cff" Visibility="Visible"/>
                                </StackPanel>
                            </Border>
                            <Border x:Name="BtnGamTabGpu" Cursor="Hand" Padding="0,0,24,0">
                                <StackPanel>
                                    <TextBlock Text="GPU" Foreground="#767685"
                                               FontSize="12" Margin="0,10,0,8"/>
                                    <Rectangle Height="2" Fill="#7c5cff" Visibility="Collapsed"/>
                                </StackPanel>
                            </Border>
                        </StackPanel>
                    </Border>
                    <!-- GamPanTweaks (default visible) -->
                    <Border x:Name="GamPanTweaks" Visibility="Visible">
                    <StackPanel Margin="8,4">
                <Border Style="{StaticResource Card}">
                    <StackPanel>
                        <TextBlock Text="SELECTION TOOLS" Style="{StaticResource SecHdr}"/>
                        <TextBlock Text="Use these to quickly select or clear settings, then review your list and press Apply."
                                   Style="{StaticResource Desc}" Margin="0,0,0,10"/>
                        <WrapPanel>
                            <!-- Preset buttons are intentionally not shown here - presets only appear on the Dashboard.
                                 These buttons still exist (Visibility=Collapsed) because the Dashboard's quick-preset
                                 buttons trigger them via RaiseEvent; they just aren't rendered on the Gaming tab. -->
                            <Button x:Name="BtnPresetGaming"        Content="⚡ Gaming Preset"          Style="{StaticResource BtnAccent}" Height="34" Visibility="Collapsed"/>
                            <Button x:Name="BtnPresetStreaming"      Content="📡 Streaming Preset"       Style="{StaticResource Btn}"       Height="34" Visibility="Collapsed"/>
                            <Button x:Name="BtnSelectAll"            Content="☑ Select All"             Style="{StaticResource BtnGray}"   Height="34"/>
                            <Button x:Name="BtnDeselectAll"          Content="☐ Deselect All"           Style="{StaticResource BtnGray}"   Height="34"/>
                            <Button x:Name="BtnSaveProfile"          Content="💾 Save Profile"          Style="{StaticResource BtnGray}"   Height="34"/>
                            <Button x:Name="BtnLoadProfile"          Content="📂 Load Profile"          Style="{StaticResource BtnGray}"   Height="34"/>
                        </WrapPanel>
                    </StackPanel>
                </Border>
                <Border Style="{StaticResource Card}">
                    <StackPanel>
                        <TextBlock Text="GAMING OPTIMIZATIONS" Style="{StaticResource SecHdr}"/>
                        <CheckBox x:Name="ChkGameMode"   Style="{StaticResource Chk}" Content="Windows Game Mode"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Prioritizes GPU/CPU for your active game"/>
                        <CheckBox x:Name="ChkHighPerf"   Style="{StaticResource Chk}" Content="High Performance Power Plan"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Prevents CPU throttling during gameplay"/>
                        <CheckBox x:Name="ChkUltPerf"    Style="{StaticResource Chk}" Content="Ultimate Performance Power Plan"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Hidden plan for maximum CPU output - best for desktop PCs"/>
                        <CheckBox x:Name="ChkHwGpu"      Style="{StaticResource Chk}" Content="Hardware-Accelerated GPU Scheduling (HAGS)"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Reduces GPU latency - needs compatible GPU + driver, reboot required"/>
                        <CheckBox x:Name="ChkMouseFix"   Style="{StaticResource Chk}" Content="Disable Mouse Acceleration"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Removes pointer precision for consistent raw mouse input"/>
                        <CheckBox x:Name="ChkXboxDvr"    Style="{StaticResource Chk}" Content="Disable Xbox Game Bar / DVR"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Removes background game recording overhead"/>
                        <CheckBox x:Name="ChkFSO"        Style="{StaticResource Chk}" Content="Disable Fullscreen Optimizations"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Reduces latency in some games - good for fast-paced play"/>
                        <CheckBox x:Name="ChkStickyKeys" Style="{StaticResource Chk}" Content="Disable Sticky Keys Prompt"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Stops Shift-spam triggering Sticky Keys dialog mid-game"/>
                    </StackPanel>
                </Border>
                <Border Style="{StaticResource Card}">
                    <StackPanel>
                        <TextBlock Text="STREAMING OPTIMIZATIONS" Style="{StaticResource SecHdr}"/>
                        <CheckBox x:Name="ChkObsPriority" Style="{StaticResource Chk}" Content="Set OBS to High Process Priority"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Gives OBS more CPU time for encoding - persists via registry"/>
                        <CheckBox x:Name="ChkQoS"         Style="{StaticResource Chk}" Content="Remove Windows Network Bandwidth Reserve"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Windows holds back 20% of bandwidth by default - removes that cap"/>
                    </StackPanel>
                </Border>
                <Border Style="{StaticResource Card}">
                    <StackPanel>
                        <TextBlock Text="ADVANCED GAMING PERFORMANCE" Style="{StaticResource SecHdr}"/>
                        <CheckBox x:Name="ChkMMCSS"          Style="{StaticResource Chk}" Content="Boost MMCSS System Responsiveness"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Reduces CPU reserved for background tasks from 20% → 10%, giving games more headroom"/>
                        <CheckBox x:Name="ChkNetworkThrottle" Style="{StaticResource Chk}" Content="Disable Network Throttling Index"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Removes Windows' multimedia network throttle - can lower ping in online games"/>
                        <CheckBox x:Name="ChkNaglesAlgo"      Style="{StaticResource Chk}" Content="Disable Nagle's Algorithm"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Reduces TCP packet bundling latency on your active NIC - improves online gaming ping"/>
                        <CheckBox x:Name="ChkPowerThrottle"   Style="{StaticResource Chk}" Content="Disable Power Throttling"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Prevents Windows from throttling CPU/GPU power - helps on laptops and battery-managed systems"/>
                        <CheckBox x:Name="ChkGamesMMCSS"      Style="{StaticResource Chk}" Content="Boost MMCSS Games Task Priority (GPU Priority 8)"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Raises GPU/CPU scheduling priority for games in the Windows Multimedia Class Scheduler"/>
                        <CheckBox x:Name="ChkDisablePageExec" Style="{StaticResource Chk}" Content="Keep Kernel Pages in RAM (Disable Paging Executive)"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Forces kernel data to stay in physical RAM, reducing DPC latency and input lag"/>
                        <CheckBox x:Name="ChkAutoHDR"         Style="{StaticResource Chk}" Content="Enable Auto HDR (Windows 11)"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Automatically upgrades SDR games to HDR on compatible HDR displays"/>
                        <CheckBox x:Name="ChkVRR"             Style="{StaticResource Chk}" Content="Enable Variable Refresh Rate (VRR/FreeSync/G-Sync)"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Enables VRR for windowed and fullscreen games on compatible displays"/>
                        <CheckBox x:Name="ChkWindowedGameOpt" Style="{StaticResource Chk}" Content="Enable Optimizations for Windowed Games"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Applies Windows 11 latency improvements to windowed-mode games"/>
                        <CheckBox x:Name="ChkTimerRes" Style="{StaticResource Chk}" Content="Timer Resolution - 0.5ms (maximum precision)"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Sets Windows timer resolution to 0.5ms for lowest possible input latency - persists via scheduled task at logon"/>
                        <CheckBox x:Name="ChkDefenderExclusions" Style="{StaticResource Chk}" Content="Windows Defender - Add Game Launcher Exclusions"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Excludes Steam, Epic, Riot, EA and Battle.net folders from real-time scanning - eliminates mid-game hitches caused by Defender scanning game files"/>
                        <CheckBox x:Name="ChkVisualPerf" Style="{StaticResource Chk}" Content="Visual Effects - Performance Mode"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Sets all Windows animations to off - taskbar, window shadows, and compositor effects (also disables taskbar animations separately)"/>
                        <CheckBox x:Name="ChkNtfsOpt" Style="{StaticResource Chk}" Content="NTFS Optimisations (Last Access + 8.3 Filenames)"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Disables last-access timestamp writes and short 8.3 filename generation - reduces background disk I/O during gameplay"/>
                        <CheckBox x:Name="ChkSysMainDisable" Style="{StaticResource Chk}" Content="Disable SysMain (Superfetch)"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Stops Windows pre-loading apps into RAM in the background - reduces disk I/O on HDDs and hybrid drives during gameplay"/>
                        <CheckBox x:Name="ChkAudioLatency" Style="{StaticResource Chk}" Content="Pro Audio MMCSS Priority Boost"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Sets the Windows MMCSS Pro Audio task to realtime scheduling category and GPU priority 8 - reduces audio processing jitter"/>
                        <CheckBox x:Name="ChkUsbSuspend" Style="{StaticResource Chk}" Content="Disable USB Selective Suspend"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Prevents Windows from power-cycling USB HID devices (mice, keyboards, headsets) - eliminates the rare input dropout on busy USB controllers"/>
                        <CheckBox x:Name="ChkNicLatency" Style="{StaticResource Chk}" Content="NIC Latency Tuning (LSO + RSC Off)"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Disables Large Send Offload and Receive Segment Coalescing on your active NIC - reduces TCP batching latency (complements Nagle tweak above)"/>
                        <CheckBox x:Name="ChkBcdTweaks" Style="{StaticResource Chk}" Content="BCD Performance Tweaks (Dynamic Tick Off + TSC Sync)"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Disables Windows dynamic timer tick coalescing and sets enhanced TSC sync - widely used for consistent frame pacing"/>
                        <CheckBox x:Name="ChkCoreParkingDisable" Style="{StaticResource Chk}" Content="Disable CPU Core Parking"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Prevents Windows from putting CPU cores into sleep states mid-game - eliminates micro-stutters caused by cores waking up"/>
                        <CheckBox x:Name="ChkWin32Priority" Style="{StaticResource Chk}" Content="Win32 Priority Separation - Max Foreground Boost"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Sets CPU time-slice allocation so the active game window gets maximum CPU time over background tasks"/>
                        <CheckBox x:Name="ChkVbsDisable" Style="{StaticResource Chk}" Content="Disable VBS / Hyper-V (Requires Reboot) ⚠"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Removes the Hyper-V hypervisor layer - can yield 5–15% FPS uplift on affected systems. Reboot required. Re-enable before using WSL2 or virtual machines."/>
                        <CheckBox x:Name="ChkAhciLpmOff" Style="{StaticResource Chk}" Content="Disable AHCI Link Power Management"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Stops your SSD/HDD transitioning to low-power states between reads - eliminates storage-caused frame time spikes"/>
                        <CheckBox x:Name="ChkTcpGameTweaks" Style="{StaticResource Chk}" Content="TCP Per-Adapter Game Tweaks (ACK Frequency + NoDelay)"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Sets TcpAckFrequency=1 and TCPNoDelay=1 on your active NIC - tells Windows to send TCP packets immediately with no batching delay"/>
                        <CheckBox x:Name="ChkNicIntMod" Style="{StaticResource Chk}" Content="Disable NIC Interrupt Moderation"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Forces your NIC to interrupt the CPU for every received packet instead of batching them - lowest possible network latency"/>
                        <CheckBox x:Name="ChkNicPowerSaving" Style="{StaticResource Chk}" Content="Disable NIC Device Power Management"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Stops Windows suspending your network adapter itself to save power (separate from the offload settings above) - a common, hard-to-diagnose cause of random latency spikes and brief disconnects"/>
                        <CheckBox x:Name="ChkNicEeeDisable" Style="{StaticResource Chk}" Content="Disable Energy Efficient Ethernet (EEE)"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Disables the wired Ethernet power-saving mode that briefly drops link speed during idle gaps - a known source of micro-latency and packet loss on gaming NICs"/>
                        <CheckBox x:Name="ChkMemCompDisable" Style="{StaticResource Chk}" Content="Disable Memory Compression"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Stops Windows compressing RAM contents in the background - removes CPU overhead from the compression algorithm. Best on 16GB+ systems."/>
                        <CheckBox x:Name="ChkPcieAspm" Style="{StaticResource Chk}" Content="Disable PCIe Active State Power Management (ASPM)"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Prevents GPU, NVMe, and NIC from entering PCIe low-power states between frames - eliminates PCIe-induced latency spikes"/>
                    </StackPanel>
                </Border>
                <!-- WiFi Gaming Mode -->
                <Border Style="{StaticResource Card}">
                <StackPanel>
                    <TextBlock Text="WIFI GAMING MODE" Style="{StaticResource SecHdr}"/>
                    <TextBlock x:Name="LblWifiStatus" FontSize="11" Foreground="#8b8b9c" TextWrapping="Wrap" Margin="0,0,0,8" Text="Checking adapter..."/>
                    <WrapPanel>
                        <Button x:Name="BtnWifiGamingMode" Content="Apply WiFi Gaming Mode" Style="{StaticResource BtnAccent}" Margin="0,0,8,0"/>
                    </WrapPanel>
                    <TextBlock FontSize="10" Foreground="#5f5f70" TextWrapping="Wrap" Margin="0,8,0,0"
                               Text="Disables power saving, sets roaming aggressiveness to lowest, and prefers 5 GHz band on your WiFi adapter. For wired connections this button is not needed."/>
                </StackPanel>
                </Border>
                <!-- Display Refresh Rate -->
                <Border Style="{StaticResource Card}">
                <StackPanel>
                    <TextBlock Text="DISPLAY REFRESH RATE" Style="{StaticResource SecHdr}"/>
                    <TextBlock x:Name="LblDisplayRefreshStatus" FontSize="11" Foreground="#8b8b9c" TextWrapping="Wrap" Margin="0,0,0,8" Text="Checking display..."/>
                    <WrapPanel>
                        <Button x:Name="BtnSetMaxRefreshRate" Content="Set Maximum Refresh Rate" Style="{StaticResource BtnAccent}" Margin="0,0,8,0"/>
                    </WrapPanel>
                    <TextBlock FontSize="10" Foreground="#5f5f70" TextWrapping="Wrap" Margin="0,8,0,0"
                               Text="Finds the highest refresh rate supported by your monitor at your current resolution and applies it. Fixes the common 60 Hz misconfiguration after driver reinstalls."/>
                </StackPanel>
                </Border>
                <!-- USB HID Polling Rate (HIDUSBF) -->
                <Border Style="{StaticResource Card}">
                <StackPanel>
                    <TextBlock Text="USB HID POLLING RATE - HIDUSBF" Style="{StaticResource SecHdr}"/>
                    <TextBlock FontSize="11" Foreground="#8b8b9c" TextWrapping="Wrap" Margin="0,0,0,8"
                               Text="Overclock your mouse/keyboard USB polling rate for lower input latency. Standard USB polls at 125 Hz - gaming mice support 500–8000 Hz. Uses HIDUSBF."/>
                    <TextBlock x:Name="LblUsbPollingStatus" FontSize="11" Foreground="#8b8b9c" TextWrapping="Wrap" Margin="0,0,0,8"
                               Text="Click Download &amp; Launch to automatically fetch and open HIDUSBF."/>
                    <WrapPanel>
                        <Button x:Name="BtnUsbPollingDownload" Content="⬇ Download &amp; Launch HIDUSBF" Style="{StaticResource BtnAccent}" Margin="0,0,8,0"/>
                    </WrapPanel>
                    <TextBlock FontSize="10" Foreground="#5f5f70" TextWrapping="Wrap" Margin="0,8,0,0"
                               Text="HIDUSBF runs as its own interface - select your HID device and choose a polling rate from the dropdown, then click Install Service."/>
                </StackPanel>
                </Border>
                <!-- Keyboard Repeat Rate -->
                <Border Style="{StaticResource Card}">
                <StackPanel>
                    <TextBlock Text="KEYBOARD REPEAT RATE" Style="{StaticResource SecHdr}"/>
                    <TextBlock Style="{StaticResource Desc}" Margin="0,0,0,8"
                               Text="Sets the shortest before-repeat delay and fastest repeat rate Windows allows - shaves a little latency off held-key input (movement spam, console commands)."/>
                    <CheckBox x:Name="ChkKeyboardRepeat" Style="{StaticResource Chk}" Content="Maximum keyboard repeat rate"/>
                </StackPanel>
                </Border>
                <!-- Per-App Discrete GPU Preference -->
                <Border Style="{StaticResource Card}">
                <StackPanel>
                    <TextBlock Text="FORCE DISCRETE GPU (PER-APP)" Style="{StaticResource SecHdr}"/>
                    <TextBlock FontSize="11" Foreground="#8b8b9c" TextWrapping="Wrap" Margin="0,0,0,8"
                               Text="On laptops with both an integrated and discrete GPU, Windows sometimes defaults a game to the weaker integrated GPU. Pick a game's .exe to force it onto your discrete GPU."/>
                    <TextBlock x:Name="LblGpuPrefStatus" FontSize="11" Foreground="#8b8b9c" TextWrapping="Wrap" Margin="0,0,0,8" Text="No game selected."/>
                    <WrapPanel>
                        <Button x:Name="BtnGpuPrefBrowse" Content="Browse for .exe..." Style="{StaticResource BtnGray}" Margin="0,0,8,0"/>
                        <Button x:Name="BtnGpuPrefApply"  Content="Force Discrete GPU" Style="{StaticResource BtnAccent}" Margin="0,0,8,0" IsEnabled="False"/>
                        <Button x:Name="BtnGpuPrefRemove" Content="Remove Selected" Style="{StaticResource BtnGray}" IsEnabled="False"/>
                    </WrapPanel>
                    <TextBlock Text="Configured games:" FontSize="10" Foreground="#5f5f70" Margin="0,10,0,4"/>
                    <ListBox x:Name="LstGpuPrefApps" Background="#0d0d16" Foreground="#c9c7d6" BorderBrush="#28242f" BorderThickness="1" MaxHeight="90" FontSize="11"/>
                </StackPanel>
                </Border>
                    </StackPanel>
                    </Border><!-- end GamPanTweaks -->

                    <!-- GamPanGpu (default collapsed) -->
                    <Border x:Name="GamPanGpu" Visibility="Collapsed">
                    <StackPanel Margin="8,4">
                <!-- GPU Tweaks sub-section -->
                <Border Style="{StaticResource Card}">
                <StackPanel>
                    <TextBlock Text="GPU TWEAKS" Style="{StaticResource SecHdr}"/>

                    <!-- No GPU message (shown when vendor = none) -->
                    <TextBlock x:Name="LblNoGpu" Visibility="Collapsed"
                               Text="No discrete GPU detected - GPU tweaks unavailable."
                               FontSize="12" Foreground="#8b8b9c" Margin="0,4,0,0"/>

                    <!-- Nvidia panel -->
                    <StackPanel x:Name="PanelNvidia" Visibility="Collapsed">
                        <TextBlock Text="NVIDIA" FontSize="9" FontWeight="Bold" Foreground="#76b900"
                                   Margin="0,0,0,8"/>
                        <CheckBox x:Name="ChkGpuNvULL"       Style="{StaticResource Chk}" Content="Ultra Low Latency Mode"    Margin="0,0,0,6"/>
                        <CheckBox x:Name="ChkGpuNvFHBC"      Style="{StaticResource Chk}" Content="Disable Frame Buffer Hibernation" Margin="0,0,0,6"/>
                        <CheckBox x:Name="ChkGpuNvPState"    Style="{StaticResource Chk}" Content="Force P0 P-State (max clocks)" Margin="0,0,0,6"/>
                        <CheckBox x:Name="ChkGpuNvTexFilter" Style="{StaticResource Chk}" Content="Texture Filtering - Performance" Margin="0,0,0,6"/>
                        <CheckBox x:Name="ChkGpuNvTelemetry"    Style="{StaticResource Chk}" Content="Disable NVIDIA Telemetry (NvTelemetryContainer)" Margin="0,0,0,6"/>
                        <CheckBox x:Name="ChkGpuNvThreadedOpt" Style="{StaticResource Chk}" Content="Threaded Optimization - Force On" Margin="0,0,0,6"/>
                        <CheckBox x:Name="ChkGpuNvNpiProfile"   Style="{StaticResource Chk}" Content="Apply NPI Profile (VSync Off + FRL Low Latency + Preferred Refresh Rate)" Margin="0,0,0,6"
                                  ToolTip="Launches Nvidia Profile Inspector, which will ask 'Replace' or 'Merge' - always choose Merge to keep your existing per-game profile settings. Replace will reset those profiles and keep only what's in StreamReady's file."/>
                        <CheckBox x:Name="ChkNvidiaShaderCache"  Style="{StaticResource Chk}" Content="Unlimited Shader Cache Size" Margin="0,0,0,0"/>
                    </StackPanel>

                    <!-- AMD panel -->
                    <StackPanel x:Name="PanelAmd" Visibility="Collapsed">
                        <TextBlock Text="AMD" FontSize="9" FontWeight="Bold" Foreground="#e04f4f"
                                   Margin="0,0,0,8"/>
                        <CheckBox x:Name="ChkGpuAmdAntiLag"  Style="{StaticResource Chk}" Content="Enable Anti-Lag+ (RDNA 3+)"   Margin="0,0,0,6"/>
                        <CheckBox x:Name="ChkGpuAmdULPS"     Style="{StaticResource Chk}" Content="Disable ULPS (eliminates stutter)" Margin="0,0,0,6"/>
                        <CheckBox x:Name="ChkGpuAmdRSR"      Style="{StaticResource Chk}" Content="Image Sharpening (RSR)" Margin="0,0,0,6"/>
                        <CheckBox x:Name="ChkGpuAmdTDR"      Style="{StaticResource Chk}" Content="TDR Delay - 60s crash recovery" Margin="0,0,0,6"/>
                        <CheckBox x:Name="ChkGpuAmdTexFilter" Style="{StaticResource Chk}" Content="Texture Filtering - Performance" Margin="0,0,0,6"/>
                        <CheckBox x:Name="ChkGpuAmdTelemetry" Style="{StaticResource Chk}" Content="Disable AMD Crash Defender Telemetry" Margin="0,0,0,0"/>
                    </StackPanel>
                </StackPanel>
                </Border>
                <!-- Intel Hybrid CPU Optimizer -->
                <Border Style="{StaticResource Card}">
                <StackPanel>
                    <TextBlock Text="INTEL HYBRID CPU OPTIMIZER (12th–14th GEN)" Style="{StaticResource SecHdr}"/>
                    <TextBlock x:Name="LblIntelHybridStatus" FontSize="11" Foreground="#8b8b9c" TextWrapping="Wrap" Margin="0,0,0,8" Text="Checking CPU..."/>
                    <WrapPanel>
                        <Button x:Name="BtnIntelHybridApply" Content="Apply P-Core Affinity" Style="{StaticResource BtnAccent}" Margin="0,0,8,0" IsEnabled="False"/>
                    </WrapPanel>
                    <TextBlock FontSize="10" Foreground="#5f5f70" TextWrapping="Wrap" Margin="0,8,0,0"
                               Text="On Intel 12th–14th gen (Alder/Raptor/Meteor Lake) sets Thread Director hints so games run on P-cores and background tasks use E-cores. Detected automatically."/>
                </StackPanel>
                </Border>
                <!-- AMD Launcher Priority + CPU Mitigation Bypass -->
                <Border Style="{StaticResource Card}">
                <StackPanel>
                    <TextBlock Text="AMD LAUNCHER PRIORITY + CPU MITIGATION BYPASS" Style="{StaticResource SecHdr}"/>
                    <TextBlock x:Name="LblAmdVcacheStatus" FontSize="11" Foreground="#8b8b9c" TextWrapping="Wrap" Margin="0,0,0,8" Text="Checking CPU..."/>
                    <WrapPanel>
                        <Button x:Name="BtnAmdVcacheApply" Content="Disable CPU Mitigations (Perf)" Style="{StaticResource BtnAccent}" Margin="0,0,8,0" IsEnabled="False"
                                ToolTip="Raises priority for common game launchers (Steam, Epic, Battle.net, Riot, EA) and disables Spectre/Meltdown/L1TF CPU speculative-execution mitigations for a performance gain. This is a security tradeoff, not core/CCD affinity pinning."/>
                    </WrapPanel>
                    <TextBlock FontSize="10" Foreground="#5f5f70" TextWrapping="Wrap" Margin="0,8,0,0"
                               Text="Raises launcher priority and disables Spectre/Meltdown/L1TF CPU security mitigations for a performance gain. This is a security tradeoff - it does not pin processes to a specific CCD/core group despite living on this GPU tab's AMD panel."/>
                </StackPanel>
                </Border>
                    </StackPanel>
                    </Border><!-- end GamPanGpu -->

                </StackPanel>
                </Border>
                <!-- #endregion Gaming Section -->
                <!-- #region Privacy Section -->
                <Border x:Name="SecPrivacy" Visibility="Collapsed" Background="#08080e">
            <StackPanel Margin="8,4">
                <Border Style="{StaticResource Card}">
                    <StackPanel>
                        <TextBlock Text="TELEMETRY &amp; TRACKING" Style="{StaticResource SecHdr}"/>
                        <CheckBox x:Name="ChkTelemetry"      Style="{StaticResource Chk}" Content="Disable Windows Telemetry"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Stops diagnostic data being sent to Microsoft (DiagTrack + registry)"/>
                        <CheckBox x:Name="ChkActivityHistory" Style="{StaticResource Chk}" Content="Disable Activity History"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Stops Windows tracking apps, files, and websites you use"/>
                        <CheckBox x:Name="ChkLocation"        Style="{StaticResource Chk}" Content="Disable Location Tracking"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Prevents apps and Windows from accessing your location"/>
                        <CheckBox x:Name="ChkAds"             Style="{StaticResource Chk}" Content="Disable Personalized Advertising ID"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Disables the ad ID used to track you across apps"/>
                        <CheckBox x:Name="ChkPs7Tele"         Style="{StaticResource Chk}" Content="Disable PowerShell 7 Telemetry"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Sets POWERSHELL_TELEMETRY_OPTOUT environment variable"/>
                    </StackPanel>
                </Border>
                <Border Style="{StaticResource Card}">
                    <StackPanel>
                        <TextBlock Text="DEBLOAT" Style="{StaticResource SecHdr}"/>
                        <CheckBox x:Name="ChkCopilot"    Style="{StaticResource Chk}" Content="Disable Microsoft Copilot"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Removes Copilot from taskbar and disables via policy"/>
                        <CheckBox x:Name="ChkWidgets"    Style="{StaticResource Chk}" Content="Remove Widgets / News Feed"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Disables the Windows 11 widgets panel"/>
                        <CheckBox x:Name="ChkConsumer"   Style="{StaticResource Chk}" Content="Disable Consumer Features (Suggested Apps)"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Stops Microsoft installing sponsored apps automatically"/>
                        <CheckBox x:Name="ChkBingSearch" Style="{StaticResource Chk}" Content="Disable Bing Search in Start Menu"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Removes web results from the Start Menu search"/>
                        <CheckBox x:Name="ChkBgApps"     Style="{StaticResource Chk}" Content="Disable Background Apps"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Prevents UWP apps running in background"/>
                        <CheckBox x:Name="ChkDeliveryOpt" Style="{StaticResource Chk}" Content="Disable Delivery Optimization (P2P Updates)"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Stops Windows using your bandwidth to distribute updates to other PCs"/>
                        <CheckBox x:Name="ChkLockScreen"  Style="{StaticResource Chk}" Content="Disable Lock Screen"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Skips the lock screen image and goes directly to the sign-in screen"/>
                        <CheckBox x:Name="ChkStartupSound" Style="{StaticResource Chk}" Content="Disable Windows Startup Sound"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Silences the sound that plays when Windows starts up"/>
                        <CheckBox x:Name="ChkSoundDucking" Style="{StaticResource Chk}" Content="Disable Sound Ducking (Do Nothing on Comms Activity)"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Stops Windows lowering other app volumes when a call is detected"/>
                        <CheckBox x:Name="ChkDisableNotifications" Style="{StaticResource Chk}" Content="Disable Notification Tray / Action Center"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Hides the notification bell and action center from taskbar"/>
                        <CheckBox x:Name="ChkDisableCrossDevice"   Style="{StaticResource Chk}" Content="Disable Cross-Device Resume"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Stops Windows syncing your recent activity with other devices"/>
                        <CheckBox x:Name="ChkStartMenuRec"         Style="{StaticResource Chk}" Content="Disable Start Menu Recommendations"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Removes app recommendations from the Windows 11 Start Menu"/>
                    </StackPanel>
                </Border>
                <Border Style="{StaticResource Card}">
                    <StackPanel>
                        <TextBlock Text="ADVANCED REMOVAL ⚠" Style="{StaticResource SecHdr}"/>
                        <TextBlock Text="Larger changes - read descriptions before selecting." Foreground="#f0b545" FontSize="11" Margin="0,0,0,8"/>
                        <CheckBox x:Name="ChkOneDrive"    Style="{StaticResource ChkWarn}" Content="Remove OneDrive"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Fully uninstalls OneDrive. Files stay in the OneDrive folder."/>
                        <CheckBox x:Name="ChkEdgeDebloat" Style="{StaticResource ChkWarn}" Content="Edge Debloat (telemetry, shopping, sidebar)"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Applies policy to disable Edge tracking features - does NOT remove Edge"/>
                    </StackPanel>
                </Border>
            </StackPanel>
                </Border>
                <!-- #endregion Privacy Section -->
                <!-- #region Tweaks Section -->
                <Border x:Name="SecTweaks" Visibility="Collapsed" Background="#08080e">
            <StackPanel Margin="8,4">
                <Border Style="{StaticResource Card}">
                    <StackPanel>
                        <TextBlock Text="ESSENTIAL TWEAKS" Style="{StaticResource SecHdr}"/>
                        <CheckBox x:Name="ChkNumLock"         Style="{StaticResource Chk}" Content="NumLock On at Startup"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Ensures NumLock is always on when Windows starts"/>
                        <CheckBox x:Name="ChkShowExt"         Style="{StaticResource Chk}" Content="Show File Extensions in Explorer"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Shows .exe, .txt etc - helps identify files"/>
                        <CheckBox x:Name="ChkShowHidden"      Style="{StaticResource Chk}" Content="Show Hidden Files"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Makes hidden files and folders visible in Explorer"/>
                        <CheckBox x:Name="ChkEndTask"         Style="{StaticResource Chk}" Content="Enable Right-Click End Task on Taskbar"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Adds End Task when right-clicking apps in taskbar"/>
                        <CheckBox x:Name="ChkDarkMode"        Style="{StaticResource Chk}" Content="Enable Dark Mode"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Sets system-wide dark theme for Windows and apps"/>
                        <CheckBox x:Name="ChkDetailedBSOD"    Style="{StaticResource Chk}" Content="Detailed BSOD Info"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Shows technical details on Blue Screen instead of sad emoji"/>
                        <CheckBox x:Name="ChkDisableHibernate" Style="{StaticResource Chk}" Content="Disable Hibernation"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Frees several GB of disk by removing hiberfil.sys"/>
                        <CheckBox x:Name="ChkDisableFastStartup" Style="{StaticResource Chk}" Content="Disable Fast Startup"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Fast Startup hibernates the kernel on shutdown - a known cause of dual-boot corruption and stale driver/BIOS state. Sleep/hibernate keep working normally."/>
                        <CheckBox x:Name="ChkDisableWpbt"      Style="{StaticResource Chk}" Content="Disable Windows Platform Binary Table (WPBT)"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Prevents OEM firmware from forcing software installs - improves security"/>
                        <CheckBox x:Name="ChkDisableExplorerFolderDiscovery" Style="{StaticResource Chk}" Content="Disable Explorer Automatic Folder Type Discovery"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Stops Explorer changing view layout automatically - speeds up folder opens"/>
                        <CheckBox x:Name="ChkServicesManual"   Style="{StaticResource Chk}" Content="Set Non-Essential Services to Manual"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Reduces startup load - sets telemetry/consumer services to manual start"/>
                        <CheckBox x:Name="ChkVerboseLogon"     Style="{StaticResource Chk}" Content="Verbose Messages During Logon"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Shows what Windows is doing during startup and shutdown"/>
                        <CheckBox x:Name="ChkFastShutdown"     Style="{StaticResource Chk}" Content="Speed Up Shutdown (Reduce Service Wait Timeout)"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Reduces how long Windows waits for services before force-closing them at shutdown"/>
                        <CheckBox x:Name="ChkShowFullPath"     Style="{StaticResource Chk}" Content="Show Full Path in Explorer Title Bar"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Displays the full folder path in the Explorer window title instead of just the folder name"/>
                        <CheckBox x:Name="ChkPhotoViewer"      Style="{StaticResource Chk}" Content="Enable Classic Windows Photo Viewer"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Restores the classic Photo Viewer as the default image viewer instead of the Photos app"/>
                    </StackPanel>
                </Border>
                <Border Style="{StaticResource Card}">
                    <StackPanel>
                        <TextBlock Text="TASKBAR &amp; EXPLORER" Style="{StaticResource SecHdr}"/>
                        <CheckBox x:Name="ChkCenterTaskbar" Style="{StaticResource Chk}" Content="Center Taskbar Icons (Win11)"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Centers app icons on the taskbar"/>
                        <CheckBox x:Name="ChkTaskbarSearch" Style="{StaticResource Chk}" Content="Hide Search Button in Taskbar"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Removes the search icon from taskbar"/>
                        <CheckBox x:Name="ChkTaskView"      Style="{StaticResource Chk}" Content="Hide Task View Button"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Removes the Task View / Virtual Desktops button"/>
                        <CheckBox x:Name="ChkClassicMenu"   Style="{StaticResource Chk}" Content="Classic Right-Click Menu (Win11)"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Restores the full classic context menu in Explorer"/>
                        <CheckBox x:Name="ChkRemoveGallery" Style="{StaticResource Chk}" Content="Remove Gallery from Explorer Sidebar"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Hides Gallery from File Explorer's left panel"/>
                        <CheckBox x:Name="ChkRemoveHome"    Style="{StaticResource Chk}" Content="Remove Home from Explorer Sidebar"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Removes the Home / Quick Access item from Explorer navigation"/>
                        <CheckBox x:Name="ChkRevertStartMenu" Style="{StaticResource Chk}" Content="Revert Start Menu to Old Style (Win11)"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Restores the Windows 10-style Start Menu layout in Windows 11"/>
                    </StackPanel>
                </Border>
                <Border Style="{StaticResource Card}">
                    <StackPanel>
                        <TextBlock Text="ADVANCED TWEAKS ⚠" Style="{StaticResource SecHdr}"/>
                        <TextBlock Text="Power-user options - read before selecting." Foreground="#f0b545" FontSize="11" Margin="0,0,0,8"/>
                        <CheckBox x:Name="ChkDisableIPv6"         Style="{StaticResource ChkWarn}" Content="Disable IPv6"/>
                        <TextBlock Style="{StaticResource Desc}" Text="May help on IPv4-only networks - can break some VPNs"/>
                        <CheckBox x:Name="ChkPreferIPv4"          Style="{StaticResource ChkWarn}" Content="Prefer IPv4 over IPv6"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Routes traffic through IPv4 first without disabling IPv6"/>
                        <CheckBox x:Name="ChkDisableTeredo"       Style="{StaticResource ChkWarn}" Content="Disable Teredo Tunneling"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Removes IPv6 tunnel that can cause gaming latency spikes"/>
                        <CheckBox x:Name="ChkDisableStorageSense" Style="{StaticResource ChkWarn}" Content="Disable Storage Sense"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Stops Windows auto-deleting files"/>
                        <CheckBox x:Name="ChkSetDisplayPerf"      Style="{StaticResource ChkWarn}" Content="Set Display for Performance (disable animations)"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Turns off visual effects - good for lower-end systems"/>
                        <CheckBox x:Name="ChkDisableMultiplaneOverlay" Style="{StaticResource ChkWarn}" Content="Disable Multiplane Overlay (MPO)"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Fixes stuttering/flickering on some GPU+display combos - reboot required"/>
                        <CheckBox x:Name="ChkSetUtcTime"          Style="{StaticResource ChkWarn}" Content="Set Clock to UTC (Dual-Boot Linux/Windows)"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Makes Windows use UTC hardware clock - needed for accurate time when dual-booting Linux"/>
                        <CheckBox x:Name="ChkHideSettingsHome"    Style="{StaticResource ChkWarn}" Content="Remove Settings Home Page (Win11)"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Hides the new Settings home/dashboard page added in recent Win11 updates"/>
                    </StackPanel>
                </Border>
            </StackPanel>
                </Border>
                <!-- #endregion Tweaks Section -->
                <!-- #region System Section -->
                <Border x:Name="SecSystem" Visibility="Collapsed" Background="#08080e">
            <StackPanel Margin="8,4">
                <Border Style="{StaticResource Card}">
                    <StackPanel>
                        <TextBlock Text="SYSTEM INFORMATION" Style="{StaticResource SecHdr}"/>
                        <Grid>
                            <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
                            <StackPanel Margin="0,0,12,0">
                                <TextBlock x:Name="TxtCpu"       Text="CPU: -" Foreground="#edecf3" FontSize="12" Margin="0,3"/>
                                <TextBlock x:Name="TxtRam"       Text="RAM: -" Foreground="#edecf3" FontSize="12" Margin="0,3"/>
                                <TextBlock x:Name="TxtGpu"       Text="GPU: -" Foreground="#edecf3" FontSize="12" Margin="0,3"/>
                            </StackPanel>
                            <StackPanel Grid.Column="1">
                                <TextBlock x:Name="TxtOs"        Text="OS: -"         Foreground="#edecf3" FontSize="12" Margin="0,3"/>
                                <TextBlock x:Name="TxtPowerPlan" Text="Power Plan: -"  Foreground="#edecf3" FontSize="12" Margin="0,3"/>
                                <TextBlock x:Name="TxtUptime"    Text="Uptime: -"      Foreground="#edecf3" FontSize="12" Margin="0,3"/>
                            </StackPanel>
                        </Grid>
                        <WrapPanel Margin="0,10,0,0">
                            <Button x:Name="BtnRefreshInfo"      Content="🔄 Refresh"              Style="{StaticResource BtnSmall}"/>
                            <Button x:Name="BtnRestorePoint"     Content="🛡️ Create Restore Point" Style="{StaticResource BtnSmall}"/>
                            <Button x:Name="BtnCleanTemp"        Content="🧹 Clean Temp Files"      Style="{StaticResource BtnSmall}"/>
                            <Button x:Name="BtnDiskCleanup"      Content="💿 Disk Cleanup"          Style="{StaticResource BtnSmall}"/>
                            <Button x:Name="BtnSFC"              Content="🩺 Corruption Scan"       Style="{StaticResource BtnSmall}"/>
                            <Button x:Name="BtnPagefileOpt"      Content="📄 Set Pagefile to System Managed" Style="{StaticResource BtnSmall}"/>
                            <Button x:Name="BtnProcessIdleTasks" Content="⚡ Run Idle Tasks Now"    Style="{StaticResource BtnSmall}"/>
                            <Button x:Name="BtnClearShaderCache" Content="🗑 Clear Shader Cache"    Style="{StaticResource BtnSmall}"/>
                            <Button x:Name="BtnReleaseStandby"   Content="🧠 Release Standby RAM"   Style="{StaticResource BtnSmall}"/>
                        </WrapPanel>
                    </StackPanel>
                </Border>
                <Border Style="{StaticResource Card}">
                    <StackPanel>
                        <TextBlock Text="STARTUP PROGRAMS" Style="{StaticResource SecHdr}"/>
                        <ListBox x:Name="StartupList" MaxHeight="150" Margin="0,0,0,8"/>
                        <WrapPanel>
                            <Button x:Name="BtnDisableStartup" Content="Disable Selected" Style="{StaticResource BtnSmall}"/>
                            <Button x:Name="BtnRefreshStartup" Content="🔄 Refresh"        Style="{StaticResource BtnSmall}"/>
                        </WrapPanel>
                    </StackPanel>
                </Border>
                <Border Style="{StaticResource Card}">
                    <StackPanel>
                        <TextBlock Text="WINDOWS OPTIONAL FEATURES" Style="{StaticResource SecHdr}"/>
                        <WrapPanel>
                            <Button x:Name="BtnInstallWSL"     Content="Install WSL"        Style="{StaticResource BtnSmall}"/>
                            <Button x:Name="BtnInstallHyperV"  Content="Install Hyper-V"    Style="{StaticResource BtnSmall}"/>
                            <Button x:Name="BtnInstallSandbox" Content="Install Sandbox"    Style="{StaticResource BtnSmall}"/>
                            <Button x:Name="BtnInstallDotNet"  Content="Install .NET 2/3/4" Style="{StaticResource BtnSmall}"/>
                            <Button x:Name="BtnInstallNFS"     Content="Install NFS Client" Style="{StaticResource BtnSmall}"/>
                            <Button x:Name="BtnInstallLegacyMedia" Content="Install Legacy Media (WMP)" Style="{StaticResource BtnSmall}"/>
                            <Button x:Name="BtnEnableF8Boot"   Content="Enable F8 Boot Recovery" Style="{StaticResource BtnSmall}"/>
                            <Button x:Name="BtnEnableRegBackup" Content="Daily Registry Backup" Style="{StaticResource BtnSmall}"/>
                            <Button x:Name="BtnEnableSSH"      Content="Enable OpenSSH Server"  Style="{StaticResource BtnSmall}"/>
                            <Button x:Name="BtnDisableSSH"     Content="Disable OpenSSH Server" Style="{StaticResource BtnSmall}"/>
                        </WrapPanel>
                    </StackPanel>
                </Border>
                <Border Style="{StaticResource Card}">
                    <StackPanel>
                        <TextBlock Text="STORAGE HEALTH &amp; ADAPTIVE TWEAKS" Style="{StaticResource SecHdr}"/>
                        <TextBlock x:Name="LblStorageHealth" Text="Click Check Storage to scan drive type and SMART health." Foreground="#8b8b9c" FontSize="11" TextWrapping="Wrap" Margin="0,0,0,8"/>
                        <WrapPanel>
                            <Button x:Name="BtnStorageCheck"    Content="🔍 Check Storage"       Style="{StaticResource BtnSmall}"/>
                            <Button x:Name="BtnStorageAdaptive" Content="⚡ Apply Adaptive Tweaks" Style="{StaticResource BtnAccent}"/>
                        </WrapPanel>
                        <TextBlock FontSize="10" Foreground="#5f5f70" TextWrapping="Wrap" Margin="0,8,0,0"
                                   Text="Adaptive Tweaks automatically applies the right settings for your drive type: NVMe gets power-management off; SSD gets TRIM verified and defrag disabled; HDD gets read-ahead and write-cache enabled."/>
                    </StackPanel>
                </Border>
                <Border Style="{StaticResource Card}">
                    <StackPanel>
                        <TextBlock Text="FIXES" Style="{StaticResource SecHdr}"/>
                        <WrapPanel>
                            <Button x:Name="BtnFixWinget"      Content="🔧 Reinstall Winget"   Style="{StaticResource BtnSmall}"/>
                            <Button x:Name="BtnSetupAutologin" Content="🔑 Set Up Auto Login"  Style="{StaticResource BtnSmall}"/>
                            <Button x:Name="BtnDisableAutologin" Content="Disable Auto Login" Style="{StaticResource BtnSmall}"/>
                        </WrapPanel>
                    </StackPanel>
                </Border>
                <Border Style="{StaticResource Card}">
                    <StackPanel>
                        <TextBlock Text="QUICK OPEN - LEGACY PANELS" Style="{StaticResource SecHdr}"/>
                        <WrapPanel>
                            <Button x:Name="BtnOpenCP"       Content="Control Panel"       Style="{StaticResource BtnSmall}"/>
                            <Button x:Name="BtnOpenDiskMgmt" Content="Disk Management"     Style="{StaticResource BtnSmall}"/>
                            <Button x:Name="BtnOpenNetConn"  Content="Network Connections" Style="{StaticResource BtnSmall}"/>
                            <Button x:Name="BtnOpenPower"    Content="Power Options"       Style="{StaticResource BtnSmall}"/>
                            <Button x:Name="BtnOpenSound"    Content="Sound Settings"      Style="{StaticResource BtnSmall}"/>
                            <Button x:Name="BtnOpenSystem"   Content="System Properties"   Style="{StaticResource BtnSmall}"/>
                            <Button x:Name="BtnOpenRestore"  Content="System Restore"      Style="{StaticResource BtnSmall}"/>
                            <Button x:Name="BtnOpenTaskMgr"  Content="Task Manager"        Style="{StaticResource BtnSmall}"/>
                            <Button x:Name="BtnOpenCompMgmt" Content="Computer Management" Style="{StaticResource BtnSmall}"/>
                            <Button x:Name="BtnOpenPrinters" Content="Printers"            Style="{StaticResource BtnSmall}"/>
                            <Button x:Name="BtnOpenRegion"   Content="Region"              Style="{StaticResource BtnSmall}"/>
                            <Button x:Name="BtnOpenDateTime" Content="Date &amp; Time"     Style="{StaticResource BtnSmall}"/>
                        </WrapPanel>
                    </StackPanel>
                </Border>
            </StackPanel>
                </Border>
                <!-- #endregion System Section -->
                <!-- #region Network Section -->
                <Border x:Name="SecNetwork" Visibility="Collapsed" Background="#08080e">
            <StackPanel Margin="8,4">
                <Border Style="{StaticResource Card}">
                    <StackPanel>
                        <TextBlock Text="NETWORK STATUS" Style="{StaticResource SecHdr}"/>
                        <TextBlock x:Name="TxtPing"    Text="Ping (8.8.8.8): -" Foreground="#edecf3" FontSize="12" Margin="0,3"/>
                        <TextBlock x:Name="TxtAdapter" Text="Adapter: -"         Foreground="#edecf3" FontSize="12" Margin="0,3"/>
                        <TextBlock x:Name="TxtDns"     Text="DNS: -"             Foreground="#edecf3" FontSize="12" Margin="0,3"/>
                        <Button x:Name="BtnRefreshNet" Content="🔄 Refresh" Style="{StaticResource BtnSmall}" HorizontalAlignment="Left" Margin="0,8,0,0"/>
                    </StackPanel>
                </Border>
                <Border Style="{StaticResource Card}">
                    <StackPanel>
                        <TextBlock Text="REGIONAL LATENCY TEST" Style="{StaticResource SecHdr}"/>
                        <TextBlock Style="{StaticResource Desc}" Margin="0,0,0,8"
                                   Text="Ping to fixed servers in a few world regions - a rough reference for where your connection is fastest, not a specific game's server (game server IPs aren't public/stable)."/>
                        <TextBlock x:Name="TxtPingUSEast" Text="US East: -"    Foreground="#edecf3" FontSize="12" Margin="0,3"/>
                        <TextBlock x:Name="TxtPingUSWest" Text="US West: -"    Foreground="#edecf3" FontSize="12" Margin="0,3"/>
                        <TextBlock x:Name="TxtPingEU"     Text="EU: -"         Foreground="#edecf3" FontSize="12" Margin="0,3"/>
                        <TextBlock x:Name="TxtPingAsia"   Text="Asia: -"       Foreground="#edecf3" FontSize="12" Margin="0,3"/>
                        <Button x:Name="BtnTestRegionalPing" Content="🌐 Test All Regions" Style="{StaticResource BtnSmall}" HorizontalAlignment="Left" Margin="0,8,0,0"/>
                    </StackPanel>
                </Border>
                <Border Style="{StaticResource Card}">
                    <StackPanel>
                        <TextBlock Text="DNS SPEED TEST" Style="{StaticResource SecHdr}"/>
                        <TextBlock Style="{StaticResource Desc}" Margin="0,0,0,8"
                                   Text="Times a real DNS lookup (not just a ping) against 9 public providers - Cloudflare, Google, Quad9, OpenDNS, CleanBrowsing, NextDNS, Mullvad, ControlD, and AdGuard - to find the fastest one for your connection right now."/>
                        <StackPanel x:Name="PanelDnsResults"/>
                        <WrapPanel Margin="0,8,0,0">
                            <Button x:Name="BtnDnsSpeedTest" Content="🔍 Test DNS Speed" Style="{StaticResource BtnSmall}" Margin="0,0,8,0"/>
                            <Button x:Name="BtnUseFastestDns" Content="Use Fastest" Style="{StaticResource BtnAccent}" Visibility="Collapsed"/>
                        </WrapPanel>
                    </StackPanel>
                </Border>
                <Border Style="{StaticResource Card}">
                    <StackPanel>
                        <TextBlock Text="CHANGE DNS PROVIDER" Style="{StaticResource SecHdr}"/>
                        <TextBlock Text="Instantly switches DNS on all active adapters." Style="{StaticResource Desc}" Margin="0,0,0,8"/>
                        <WrapPanel>
                            <Button x:Name="BtnDnsCloudflare" Content="Cloudflare 1.1.1.1"    Style="{StaticResource BtnSmall}"/>
                            <Button x:Name="BtnDnsGoogle"     Content="Google 8.8.8.8"         Style="{StaticResource BtnSmall}"/>
                            <Button x:Name="BtnDnsQuad9"      Content="Quad9 9.9.9.9"          Style="{StaticResource BtnSmall}"/>
                            <Button x:Name="BtnDnsOpenDNS"    Content="OpenDNS"                Style="{StaticResource BtnSmall}"/>
                            <Button x:Name="BtnDnsDefault"    Content="↩ Reset to DHCP"        Style="{StaticResource BtnGray}"/>
                        </WrapPanel>
                    </StackPanel>
                </Border>
                <Border Style="{StaticResource Card}">
                    <StackPanel>
                        <TextBlock Text="NETWORK FIXES" Style="{StaticResource SecHdr}"/>
                        <StackPanel Margin="0,4">
                            <TextBlock Text="Flush DNS Cache" Foreground="#edecf3" FontSize="12"/>
                            <TextBlock Style="{StaticResource Desc}" Text="Clears cached DNS - fixes sites that won't load"/>
                            <Button x:Name="BtnFlushDns" Content="Run" Style="{StaticResource BtnSmall}" HorizontalAlignment="Left"/>
                        </StackPanel>
                        <Separator Style="{StaticResource Sep}"/>
                        <StackPanel Margin="0,4">
                            <TextBlock Text="Reset Winsock" Foreground="#edecf3" FontSize="12"/>
                            <TextBlock Style="{StaticResource Desc}" Text="Resets network stack - fixes many issues (reboot required)"/>
                            <Button x:Name="BtnWinsock" Content="Run" Style="{StaticResource BtnSmall}" HorizontalAlignment="Left"/>
                        </StackPanel>
                        <Separator Style="{StaticResource Sep}"/>
                        <StackPanel Margin="0,4">
                            <TextBlock Text="Full Network Reset" Foreground="#edecf3" FontSize="12"/>
                            <TextBlock Style="{StaticResource Desc}" Text="DNS flush + Winsock + IP stack - reboot required"/>
                            <Button x:Name="BtnNetReset" Content="Run" Style="{StaticResource BtnAccent}" HorizontalAlignment="Left"/>
                        </StackPanel>
                        <Separator Style="{StaticResource Sep}"/>
                        <StackPanel Margin="0,4">
                            <TextBlock Text="Reset Windows Update Cache" Foreground="#edecf3" FontSize="12"/>
                            <TextBlock Style="{StaticResource Desc}" Text="Clears WU cache and restarts services - fixes stuck updates"/>
                            <Button x:Name="BtnResetWU" Content="Run" Style="{StaticResource BtnSmall}" HorizontalAlignment="Left"/>
                        </StackPanel>
                    </StackPanel>
                </Border>
            </StackPanel>
                </Border>
                <!-- #endregion Network Section -->
                <!-- #region Updates Section -->
                <Border x:Name="SecUpdates" Visibility="Collapsed" Background="#08080e">
            <StackPanel Margin="8,4">
                <Border Style="{StaticResource Card}">
                    <StackPanel>
                        <TextBlock Text="WINDOWS UPDATE POLICY" Style="{StaticResource SecHdr}"/>
                        <WrapPanel Margin="0,0,0,10">
                            <Button x:Name="BtnWUDefault"  Content="✅ Default (Auto)"              Style="{StaticResource BtnPrimary}" Height="34"/>
                            <Button x:Name="BtnWUSecurity" Content="🔒 Security Only"               Style="{StaticResource Btn}"      Height="34"/>
                            <Button x:Name="BtnWUDisable"  Content="⚠ Disable All Updates"          Style="{StaticResource BtnAccent}" Height="34"/>
                        </WrapPanel>
                        <TextBlock Text="Security Only defers feature updates for about a year and leaves quality (security) updates on. It does not guarantee which patches Windows installs." Foreground="#8b8b9c" FontSize="11" Margin="0,0,0,2" TextWrapping="Wrap"/>
                        <TextBlock Text="⚠ Disable All is not recommended for internet-connected PCs." Foreground="#ff6b6b" FontSize="11" TextWrapping="Wrap"/>
                    </StackPanel>
                </Border>
                <Border Style="{StaticResource Card}">
                    <StackPanel>
                        <TextBlock Text="WINDOWS UPDATE FINE-TUNING" Style="{StaticResource SecHdr}"/>
                        <TextBlock Text="These apply on top of the policy selected above." Foreground="#8b8b9c" FontSize="11" Margin="0,0,0,8" TextWrapping="Wrap"/>
                        <CheckBox x:Name="ChkNoAutoRestart"     Style="{StaticResource Chk}" Content="Prevent Automatic Restart After Updates"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Stops Windows restarting your PC automatically to finish update installs"/>
                        <CheckBox x:Name="ChkExcludeDriversWU"  Style="{StaticResource Chk}" Content="Exclude Drivers from Windows Update"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Prevents Windows Update from installing or updating drivers - install them manually instead"/>
                        <CheckBox x:Name="ChkDisableDeliveryWU" Style="{StaticResource Chk}" Content="Disable Delivery Optimization (P2P Update Sharing)"/>
                        <TextBlock Style="{StaticResource Desc}" Text="Stops Windows uploading updates to other PCs on the internet - saves bandwidth"/>
                    </StackPanel>
                </Border>
                <Border Style="{StaticResource Card}">
                    <StackPanel>
                        <TextBlock Text="INSTALL APPLICATIONS (via Winget)" Style="{StaticResource SecHdr}"/>
                        <TextBlock Text="Tick apps below and press Install Selected Apps." Foreground="#8b8b9c" FontSize="11" Margin="0,0,0,10"/>
                        <TextBlock Text="BROWSERS" Foreground="#8b8b9c" FontSize="10" FontWeight="SemiBold" Margin="0,4,0,4"/>
                        <WrapPanel>
                            <CheckBox x:Name="ChkInstallChrome"  Style="{StaticResource Chk}" Content="Google Chrome" Margin="8,4"/>
                            <CheckBox x:Name="ChkInstallFirefox" Style="{StaticResource Chk}" Content="Firefox"       Margin="8,4"/>
                            <CheckBox x:Name="ChkInstallBrave"   Style="{StaticResource Chk}" Content="Brave"         Margin="8,4"/>
                        </WrapPanel>
                        <TextBlock Text="COMMUNICATION" Foreground="#8b8b9c" FontSize="10" FontWeight="SemiBold" Margin="0,10,0,4"/>
                        <WrapPanel>
                            <CheckBox x:Name="ChkInstallDiscord" Style="{StaticResource Chk}" Content="Discord" Margin="8,4"/>
                            <CheckBox x:Name="ChkInstallSlack"   Style="{StaticResource Chk}" Content="Slack"   Margin="8,4"/>
                            <CheckBox x:Name="ChkInstallZoom"    Style="{StaticResource Chk}" Content="Zoom"    Margin="8,4"/>
                        </WrapPanel>
                        <TextBlock Text="STREAMING / GAMING" Foreground="#8b8b9c" FontSize="10" FontWeight="SemiBold" Margin="0,10,0,4"/>
                        <WrapPanel>
                            <CheckBox x:Name="ChkInstallOBS"   Style="{StaticResource Chk}" Content="OBS Studio" Margin="8,4"/>
                            <CheckBox x:Name="ChkInstallSteam" Style="{StaticResource Chk}" Content="Steam"      Margin="8,4"/>
                        </WrapPanel>
                        <TextBlock Text="UTILITIES" Foreground="#8b8b9c" FontSize="10" FontWeight="SemiBold" Margin="0,10,0,4"/>
                        <WrapPanel>
                            <CheckBox x:Name="ChkInstall7zip"    Style="{StaticResource Chk}" Content="7-Zip"     Margin="8,4"/>
                            <CheckBox x:Name="ChkInstallVLC"     Style="{StaticResource Chk}" Content="VLC"       Margin="8,4"/>
                            <CheckBox x:Name="ChkInstallNotepad" Style="{StaticResource Chk}" Content="Notepad++" Margin="8,4"/>
                            <CheckBox x:Name="ChkInstallVSCode"  Style="{StaticResource Chk}" Content="VS Code"   Margin="8,4"/>
                            <CheckBox x:Name="ChkInstallGit"     Style="{StaticResource Chk}" Content="Git"       Margin="8,4"/>
                            <CheckBox x:Name="ChkInstallWinRAR"  Style="{StaticResource Chk}" Content="WinRAR"    Margin="8,4"/>
                        </WrapPanel>
                        <TextBlock Text="CUSTOMIZATION" Foreground="#8b8b9c" FontSize="10" FontWeight="SemiBold" Margin="0,10,0,4"/>
                        <WrapPanel>
                            <CheckBox x:Name="ChkInstallStartAllBack" Style="{StaticResource Chk}" Content="StartAllBack"  Margin="8,4"/>
                            <CheckBox x:Name="ChkInstallNilesoft"     Style="{StaticResource Chk}" Content="Nilesoft Shell" Margin="8,4"/>
                            <CheckBox x:Name="ChkInstallTranslucentTB" Style="{StaticResource Chk}" Content="TranslucentTB" Margin="8,4"/>
                        </WrapPanel>
                        <TextBlock Text="MEDIA &amp; PRODUCTIVITY" Foreground="#8b8b9c" FontSize="10" FontWeight="SemiBold" Margin="0,10,0,4"/>
                        <WrapPanel>
                            <CheckBox x:Name="ChkInstallMPC"         Style="{StaticResource Chk}" Content="MPC-HC"        Margin="8,4"/>
                            <CheckBox x:Name="ChkInstallOnlyOffice"  Style="{StaticResource Chk}" Content="OnlyOffice"    Margin="8,4"/>
                            <CheckBox x:Name="ChkInstallHandbrake"   Style="{StaticResource Chk}" Content="HandBrake"     Margin="8,4"/>
                        </WrapPanel>
                        <Button x:Name="BtnInstallApps" Content="⬇  Install Selected Apps" Style="{StaticResource BtnPrimary}" Height="36" Margin="0,14,0,0" HorizontalAlignment="Left"/>
                    </StackPanel>
                </Border>
            </StackPanel>
                <!-- #endregion Updates Section -->
                </Border>

                <!-- #region Downloads Section -->
                <Border x:Name="SecDownloads" Visibility="Collapsed" Background="#08080e">
            <StackPanel Margin="8,4">
                <Border Style="{StaticResource Card}">
                    <StackPanel>
                        <TextBlock Text="PERFORMANCE &amp; MONITORING TOOLS" Style="{StaticResource SecHdr}"/>
                        <TextBlock Text="Essential tools for monitoring and tuning your gaming PC. Each is installed via Winget." Foreground="#8b8b9c" FontSize="11" Margin="0,0,0,12" TextWrapping="Wrap"/>
                        <!-- HWiNFO64 -->
                        <Grid Margin="0,0,0,10">
                            <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
                            <StackPanel>
                                <TextBlock Text="HWiNFO64" Foreground="#edecf3" FontSize="12" FontWeight="SemiBold"/>
                                <TextBlock Text="Real-time hardware monitoring - CPU, GPU, temps, clocks, voltages." Foreground="#8b8b9c" FontSize="11"/>
                            </StackPanel>
                            <Button x:Name="BtnDlHWiNFO" Grid.Column="1" Content="Install" Style="{StaticResource BtnSmall}" VerticalAlignment="Center"/>
                        </Grid>
                        <Separator Style="{StaticResource Sep}"/>
                        <!-- MSI Afterburner -->
                        <Grid Margin="0,8,0,10">
                            <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
                            <StackPanel>
                                <TextBlock Text="MSI Afterburner" Foreground="#edecf3" FontSize="12" FontWeight="SemiBold"/>
                                <TextBlock Text="GPU overclocking, fan curves, and in-game FPS/temp overlay." Foreground="#8b8b9c" FontSize="11"/>
                            </StackPanel>
                            <Button x:Name="BtnDlAfterburner" Grid.Column="1" Content="Install" Style="{StaticResource BtnSmall}" VerticalAlignment="Center"/>
                        </Grid>
                        <Separator Style="{StaticResource Sep}"/>
                        <!-- GPU-Z -->
                        <Grid Margin="0,8,0,10">
                            <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
                            <StackPanel>
                                <TextBlock Text="GPU-Z" Foreground="#edecf3" FontSize="12" FontWeight="SemiBold"/>
                                <TextBlock Text="Detailed GPU specs, sensors, and BIOS version readout." Foreground="#8b8b9c" FontSize="11"/>
                            </StackPanel>
                            <Button x:Name="BtnDlGpuZ" Grid.Column="1" Content="Install" Style="{StaticResource BtnSmall}" VerticalAlignment="Center"/>
                        </Grid>
                        <Separator Style="{StaticResource Sep}"/>
                        <!-- CPU-Z -->
                        <Grid Margin="0,8,0,10">
                            <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
                            <StackPanel>
                                <TextBlock Text="CPU-Z" Foreground="#edecf3" FontSize="12" FontWeight="SemiBold"/>
                                <TextBlock Text="Detailed CPU, memory, and motherboard information." Foreground="#8b8b9c" FontSize="11"/>
                            </StackPanel>
                            <Button x:Name="BtnDlCpuZ" Grid.Column="1" Content="Install" Style="{StaticResource BtnSmall}" VerticalAlignment="Center"/>
                        </Grid>
                        <Separator Style="{StaticResource Sep}"/>
                        <!-- CrystalDiskInfo -->
                        <Grid Margin="0,8,0,10">
                            <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
                            <StackPanel>
                                <TextBlock Text="CrystalDiskInfo" Foreground="#edecf3" FontSize="12" FontWeight="SemiBold"/>
                                <TextBlock Text="SSD/HDD health via SMART data - catch failing drives early." Foreground="#8b8b9c" FontSize="11"/>
                            </StackPanel>
                            <Button x:Name="BtnDlCrystalDisk" Grid.Column="1" Content="Install" Style="{StaticResource BtnSmall}" VerticalAlignment="Center"/>
                        </Grid>
                        <Separator Style="{StaticResource Sep}"/>
                        <!-- Process Lasso -->
                        <Grid Margin="0,8,0,10">
                            <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
                            <StackPanel>
                                <TextBlock Text="Process Lasso" Foreground="#edecf3" FontSize="12" FontWeight="SemiBold"/>
                                <TextBlock Text="Automated CPU priority management - keeps your PC responsive under load." Foreground="#8b8b9c" FontSize="11"/>
                            </StackPanel>
                            <Button x:Name="BtnDlProcessLasso" Grid.Column="1" Content="Install" Style="{StaticResource BtnSmall}" VerticalAlignment="Center"/>
                        </Grid>
                        <Separator Style="{StaticResource Sep}"/>
                        <!-- CapFrameX -->
                        <Grid Margin="0,8,0,10">
                            <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
                            <StackPanel>
                                <TextBlock Text="CapFrameX" Foreground="#edecf3" FontSize="12" FontWeight="SemiBold"/>
                                <TextBlock Text="Frame time capture and latency benchmarking - see real 1% and 0.1% lows." Foreground="#8b8b9c" FontSize="11"/>
                            </StackPanel>
                            <Button x:Name="BtnDlCapFrameX" Grid.Column="1" Content="Install" Style="{StaticResource BtnSmall}" VerticalAlignment="Center"/>
                        </Grid>
                        <Separator Style="{StaticResource Sep}"/>
                        <!-- TreeSize Free -->
                        <Grid Margin="0,8,0,10">
                            <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
                            <StackPanel>
                                <TextBlock Text="TreeSize Free" Foreground="#edecf3" FontSize="12" FontWeight="SemiBold"/>
                                <TextBlock Text="Visualise disk usage - find what's eating your storage fast." Foreground="#8b8b9c" FontSize="11"/>
                            </StackPanel>
                            <Button x:Name="BtnDlTreeSize" Grid.Column="1" Content="Install" Style="{StaticResource BtnSmall}" VerticalAlignment="Center"/>
                        </Grid>
                        <Separator Style="{StaticResource Sep}"/>
                        <!-- Equalizer APO -->
                        <Grid Margin="0,8,0,10">
                            <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
                            <StackPanel>
                                <TextBlock Text="Equalizer APO" Foreground="#edecf3" FontSize="12" FontWeight="SemiBold"/>
                                <TextBlock Text="System-wide parametric audio EQ - reduce ear fatigue, boost clarity." Foreground="#8b8b9c" FontSize="11"/>
                            </StackPanel>
                            <Button x:Name="BtnDlEqualizerAPO" Grid.Column="1" Content="Install" Style="{StaticResource BtnSmall}" VerticalAlignment="Center"/>
                        </Grid>
                        <Separator Style="{StaticResource Sep}"/>
                        <!-- LatencyMon -->
                        <Grid Margin="0,8,0,8">
                            <Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
                            <StackPanel>
                                <TextBlock Text="LatencyMon" Foreground="#edecf3" FontSize="12" FontWeight="SemiBold"/>
                                <TextBlock Text="DPC/ISR latency checker - finds which driver is causing stutter or audio dropouts." Foreground="#8b8b9c" FontSize="11"/>
                            </StackPanel>
                            <Button x:Name="BtnDlLatencyMon" Grid.Column="1" Content="Install" Style="{StaticResource BtnSmall}" VerticalAlignment="Center"/>
                        </Grid>
                    </StackPanel>
                </Border>
            </StackPanel>
                </Border>
                <!-- #endregion Downloads Section -->

            </StackPanel>
        </ScrollViewer>
    </Grid>
    <!-- #endregion Sidebar Navigation -->
    <!-- #region v7 Simple mode: welcome, Home, goal page, search, help -->
    <Grid x:Name="SimpleHost" Grid.Row="1" Background="#08080e" Visibility="Visible">
    <Grid.ColumnDefinitions>
        <ColumnDefinition Width="Auto"/>
        <ColumnDefinition Width="*"/>
    </Grid.ColumnDefinitions>
    <Grid.RowDefinitions>
        <RowDefinition Height="*"/>
        <RowDefinition Height="Auto"/>
    </Grid.RowDefinitions>
    <!-- Pro: one left navigation of areas -->
    <Border x:Name="ProNav" Grid.Column="0" Grid.Row="0" Grid.RowSpan="2" Visibility="Collapsed" Width="236" Background="#050508" BorderBrush="#1E7C5CFF" BorderThickness="0,0,1,0">
        <ScrollViewer VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
            <StackPanel x:Name="ProNavList" Margin="10,12,10,12"/>
        </ScrollViewer>
    </Border>
    <ScrollViewer x:Name="SimpleScroll" Grid.Row="0" Grid.Column="1" VerticalScrollBarVisibility="Auto"
                  HorizontalScrollBarVisibility="Disabled" Background="#08080e">
        <StackPanel Margin="28,18,28,24">

            <!-- First run: a short plain welcome -->
            <StackPanel x:Name="PageWelcome" Visibility="Collapsed" HorizontalAlignment="Center" Width="600">
                <StackPanel Orientation="Horizontal" HorizontalAlignment="Center" Margin="0,0,0,20">
                    <Border BorderBrush="#7c5cff" BorderThickness="0,0,0,2" Padding="12,4" Margin="4,0"><TextBlock Text="1  Welcome" FontSize="12" FontWeight="SemiBold" Foreground="#a78bff"/></Border>
                    <Border BorderBrush="#28242f" BorderThickness="0,0,0,2" Padding="12,4" Margin="4,0"><TextBlock Text="2  Your PC" FontSize="12" FontWeight="SemiBold" Foreground="#8b8b9c"/></Border>
                    <Border BorderBrush="#28242f" BorderThickness="0,0,0,2" Padding="12,4" Margin="4,0"><TextBlock Text="3  Your plan" FontSize="12" FontWeight="SemiBold" Foreground="#8b8b9c"/></Border>
                </StackPanel>
                <Canvas Width="54" Height="54" HorizontalAlignment="Center" Margin="0,8,0,12">
                    <Ellipse Width="54" Height="54" Fill="#7c5cff"/>
                    <Ellipse Width="7" Height="7" Fill="White" Canvas.Left="14" Canvas.Top="18"/>
                    <Ellipse Width="7" Height="7" Fill="White" Canvas.Left="33" Canvas.Top="18"/>
                    <Path Data="M14,32 Q27,44 40,32" Stroke="White" StrokeThickness="3" StrokeStartLineCap="Round" StrokeEndLineCap="Round"/>
                </Canvas>
                <TextBlock Text="A FRIENDLY START" FontSize="11" FontWeight="Bold" Foreground="#a78bff" HorizontalAlignment="Center" Margin="0,0,0,8"/>
                <TextBlock Text="Welcome to StreamReady." FontSize="28" FontWeight="SemiBold" Foreground="#edecf3" HorizontalAlignment="Center"/>
                <TextBlock Text="Tune your PC for games and streaming, one clear choice at a time."
                           FontSize="14" Foreground="#c9c7d6" TextWrapping="Wrap" TextAlignment="Center" Margin="0,8,0,18"/>
                <Border Background="#0d0d16" BorderBrush="#28242f" BorderThickness="1" CornerRadius="10" Padding="20,10">
                    <StackPanel>
                        <TextBlock Text="Nothing changes until you press Apply" FontSize="14" Foreground="#edecf3" Margin="0,8"/>
                        <Separator Style="{StaticResource Sep}" Margin="0"/>
                        <TextBlock Text="You choose every setting: pick a goal or a preset, or look at them all" FontSize="14" Foreground="#edecf3" Margin="0,8"/>
                        <Separator Style="{StaticResource Sep}" Margin="0"/>
                        <TextBlock Text="Easy way back: your originals are saved before any change" FontSize="14" Foreground="#edecf3" Margin="0,8"/>
                    </StackPanel>
                </Border>
            </StackPanel>
            <!-- Scout step 2: read-only PC check -->
            <StackPanel x:Name="PageScan" Visibility="Collapsed" HorizontalAlignment="Center" Width="600">
                <StackPanel Orientation="Horizontal" HorizontalAlignment="Center" Margin="0,0,0,20">
                    <Border BorderBrush="#28242f" BorderThickness="0,0,0,2" Padding="12,4" Margin="4,0"><TextBlock Text="1  Welcome" FontSize="12" FontWeight="SemiBold" Foreground="#8b8b9c"/></Border>
                    <Border BorderBrush="#7c5cff" BorderThickness="0,0,0,2" Padding="12,4" Margin="4,0"><TextBlock Text="2  Your PC" FontSize="12" FontWeight="SemiBold" Foreground="#a78bff"/></Border>
                    <Border BorderBrush="#28242f" BorderThickness="0,0,0,2" Padding="12,4" Margin="4,0"><TextBlock Text="3  Your plan" FontSize="12" FontWeight="SemiBold" Foreground="#8b8b9c"/></Border>
                </StackPanel>
                <TextBlock Text="Here is what Scout found on your PC." FontSize="26" FontWeight="SemiBold" Foreground="#edecf3"/>
                <TextBlock x:Name="ScanIntro" Text="This check only reads your PC. Nothing was changed. I use it to suggest settings that fit." FontSize="14" Foreground="#c9c7d6" TextWrapping="Wrap" Margin="0,6,0,16"/>
                <Border Margin="0,0,0,14"><Button x:Name="BtnScanScore" Style="{StaticResource ScoreCardButton}" IsEnabled="False" AutomationProperties.HelpText="Counts checkable gaming settings, not PC speed.">
    <StackPanel><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
        <Grid Width="76" Height="76" Margin="0,0,12,0"><Ellipse Width="76" Height="76" Stroke="#28242f" StrokeThickness="8"/>
            <Ellipse x:Name="ScanRingArc" Width="76" Height="76" Stroke="#a78bff" StrokeThickness="8" StrokeDashArray="0,100" StrokeDashCap="Round" RenderTransformOrigin="0.5,0.5"><Ellipse.RenderTransform><RotateTransform Angle="-90"/></Ellipse.RenderTransform></Ellipse>
            <StackPanel VerticalAlignment="Center"><TextBlock x:Name="ScanScoreNum" Text="-" FontSize="24" FontWeight="SemiBold" Foreground="#edecf3" HorizontalAlignment="Center"/><TextBlock Text="/ 100" FontSize="10" Foreground="#8b8b9c" HorizontalAlignment="Center"/></StackPanel>
        </Grid>
        <StackPanel Grid.Column="1" VerticalAlignment="Center"><TextBlock x:Name="ScanScoreTitle" Text="Checking..." FontSize="14" FontWeight="SemiBold" Foreground="#edecf3" TextWrapping="Wrap"/><TextBlock x:Name="ScanScoreSub" Text="Not a speed score" FontSize="12" Foreground="#c9c7d6" TextWrapping="Wrap" Margin="0,3,0,0"/></StackPanel>
    </Grid><TextBlock x:Name="ScanScoreLink" Text="" FontSize="12" Foreground="#a78bff" TextWrapping="Wrap" Margin="0,8,0,0"/><TextBlock x:Name="ScanScoreExcluded" Text="" FontSize="11" Foreground="#8b8b9c" TextWrapping="Wrap" Margin="0,6,0,0" Visibility="Collapsed"/></StackPanel>
</Button>
</Border>
                <StackPanel x:Name="ScanList"/>
            </StackPanel>

            <!-- Scout step 3: short plan -->
            <StackPanel x:Name="PagePlan" Visibility="Collapsed" HorizontalAlignment="Center" Width="640">
                <StackPanel Orientation="Horizontal" HorizontalAlignment="Center" Margin="0,0,0,20">
                    <Border BorderBrush="#28242f" BorderThickness="0,0,0,2" Padding="12,4" Margin="4,0"><TextBlock Text="1  Welcome" FontSize="12" FontWeight="SemiBold" Foreground="#8b8b9c"/></Border>
                    <Border BorderBrush="#28242f" BorderThickness="0,0,0,2" Padding="12,4" Margin="4,0"><TextBlock Text="2  Your PC" FontSize="12" FontWeight="SemiBold" Foreground="#8b8b9c"/></Border>
                    <Border BorderBrush="#7c5cff" BorderThickness="0,0,0,2" Padding="12,4" Margin="4,0"><TextBlock Text="3  Your plan" FontSize="12" FontWeight="SemiBold" Foreground="#a78bff"/></Border>
                </StackPanel>
                <TextBlock x:Name="PlanTitle" Text="Here is what I suggest." FontSize="26" FontWeight="SemiBold" Foreground="#edecf3"/>
                <TextBlock x:Name="PlanIntro" Text="" FontSize="14" Foreground="#c9c7d6" TextWrapping="Wrap" Margin="0,6,0,16"/>
                <StackPanel x:Name="PlanList"/>
                <TextBlock x:Name="PlanMore" Text="" FontSize="13" Foreground="#8b8b9c" TextWrapping="Wrap" Margin="2,4,0,0"/>
            </StackPanel>


            <!-- Home: health ring + four live tiles + Fix what matters most + eight goals -->
            <StackPanel x:Name="PageHome" Visibility="Collapsed">
                <DockPanel Margin="0,0,0,14" LastChildFill="False">
                    <TextBlock x:Name="HomeSubtitle" DockPanel.Dock="Right" Text="" FontSize="12" Foreground="#8b8b9c" VerticalAlignment="Bottom"/>
                    <TextBlock Text="Your PC, ready for what is next." FontSize="26" FontWeight="SemiBold" Foreground="#edecf3"/>
                </DockPanel>
                <Grid Margin="0,0,0,12">
                    <Grid.ColumnDefinitions>
                        <ColumnDefinition Width="1.35*"/>
                        <ColumnDefinition Width="1*"/>
                        <ColumnDefinition Width="1*"/>
                        <ColumnDefinition Width="1*"/>
                        <ColumnDefinition Width="1*"/>
                    </Grid.ColumnDefinitions>
<StackPanel Grid.Column="0" Margin="0,0,10,0"><Button x:Name="BtnHomeScore" Style="{StaticResource ScoreCardButton}" IsEnabled="False" AutomationProperties.HelpText="Counts checkable gaming settings, not PC speed.">
    <StackPanel><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
        <Grid Width="76" Height="76" Margin="0,0,12,0"><Ellipse Width="76" Height="76" Stroke="#28242f" StrokeThickness="8"/>
            <Ellipse x:Name="HomeRingArc" Width="76" Height="76" Stroke="#a78bff" StrokeThickness="8" StrokeDashArray="0,100" StrokeDashCap="Round" RenderTransformOrigin="0.5,0.5"><Ellipse.RenderTransform><RotateTransform Angle="-90"/></Ellipse.RenderTransform></Ellipse>
            <StackPanel VerticalAlignment="Center"><TextBlock x:Name="HomeScoreNum" Text="-" FontSize="24" FontWeight="SemiBold" Foreground="#edecf3" HorizontalAlignment="Center"/><TextBlock Text="/ 100" FontSize="10" Foreground="#8b8b9c" HorizontalAlignment="Center"/></StackPanel>
        </Grid>
        <StackPanel Grid.Column="1" VerticalAlignment="Center"><TextBlock x:Name="HomeScoreTitle" Text="Checking..." FontSize="14" FontWeight="SemiBold" Foreground="#edecf3" TextWrapping="Wrap"/><TextBlock x:Name="HomeScoreSub" Text="Not a speed score" FontSize="12" Foreground="#c9c7d6" TextWrapping="Wrap" Margin="0,3,0,0"/></StackPanel>
    </Grid><TextBlock x:Name="HomeScoreLink" Text="" FontSize="12" Foreground="#a78bff" TextWrapping="Wrap" Margin="0,8,0,0"/><TextBlock x:Name="HomeScoreExcluded" Text="" FontSize="11" Foreground="#8b8b9c" TextWrapping="Wrap" Margin="0,6,0,0" Visibility="Collapsed"/></StackPanel>
</Button>
<Button x:Name="BtnScoreInfo" Content="How this score works" Style="{StaticResource BtnLink}" FontSize="12" Margin="0,8,0,0"/><TextBlock x:Name="HomeScoreExplain" Visibility="Collapsed" FontSize="12" Foreground="#8b8b9c" TextWrapping="Wrap" Margin="0,4,0,0" Text="This is the share of checkable gaming settings that are on, not a speed score. Select the score to see what is left. More is not always better for your PC."/></StackPanel>
                    <Border Grid.Column="1" Background="#0d0d16" BorderBrush="#28242f" BorderThickness="1" CornerRadius="8" Padding="14,12" Margin="0,0,10,0">
                        <StackPanel>
                            <TextBlock Text="Processor / CPU" FontSize="12" Foreground="#8b8b9c"/>
                            <TextBlock x:Name="HomeCpuVal" Text="-" FontSize="24" FontWeight="SemiBold" Foreground="#edecf3" Margin="0,2,0,0"/>
                            <TextBlock x:Name="HomeCpuName" Text="" FontSize="12" Foreground="#c9c7d6" TextTrimming="CharacterEllipsis"/>
                            <TextBlock x:Name="HomeCpuSub" Text="" FontSize="11" Foreground="#8b8b9c" TextTrimming="CharacterEllipsis"/>
                            <Viewbox Height="24" Stretch="Fill" Margin="0,6,0,0"><Polyline x:Name="HomeSparkCpu" Width="48" Height="20" Stroke="#7c5cff" StrokeThickness="1.6" StrokeLineJoin="Round"/></Viewbox>
                        </StackPanel>
                    </Border>
                    <Border Grid.Column="2" Background="#0d0d16" BorderBrush="#28242f" BorderThickness="1" CornerRadius="8" Padding="14,12" Margin="0,0,10,0">
                        <StackPanel>
                            <TextBlock Text="Graphics / GPU" FontSize="12" Foreground="#8b8b9c"/>
                            <TextBlock x:Name="HomeGpuVal" Text="-" FontSize="24" FontWeight="SemiBold" Foreground="#edecf3" Margin="0,2,0,0"/>
                            <TextBlock x:Name="HomeGpuName" Text="" FontSize="12" Foreground="#c9c7d6" TextTrimming="CharacterEllipsis"/>
                            <TextBlock x:Name="HomeGpuSub" Text="" FontSize="11" Foreground="#8b8b9c" TextTrimming="CharacterEllipsis"/>
                            <Viewbox Height="24" Stretch="Fill" Margin="0,6,0,0"><Polyline x:Name="HomeSparkGpu" Width="48" Height="20" Stroke="#c77dff" StrokeThickness="1.6" StrokeLineJoin="Round"/></Viewbox>
                        </StackPanel>
                    </Border>
                    <Border Grid.Column="3" Background="#0d0d16" BorderBrush="#28242f" BorderThickness="1" CornerRadius="8" Padding="14,12" Margin="0,0,10,0">
                        <StackPanel>
                            <TextBlock Text="Memory / RAM" FontSize="12" Foreground="#8b8b9c"/>
                            <TextBlock x:Name="HomeRamVal" Text="-" FontSize="24" FontWeight="SemiBold" Foreground="#edecf3" Margin="0,2,0,0"/>
                            <TextBlock x:Name="HomeRamName" Text="" FontSize="12" Foreground="#c9c7d6" TextTrimming="CharacterEllipsis"/>
                            <TextBlock x:Name="HomeRamSub" Text="" FontSize="11" Foreground="#8b8b9c" TextTrimming="CharacterEllipsis"/>
                            <Viewbox Height="24" Stretch="Fill" Margin="0,6,0,0"><Polyline x:Name="HomeSparkRam" Width="48" Height="20" Stroke="#7c5cff" StrokeThickness="1.6" StrokeLineJoin="Round"/></Viewbox>
                        </StackPanel>
                    </Border>
                    <Border Grid.Column="4" Background="#0d0d16" BorderBrush="#28242f" BorderThickness="1" CornerRadius="8" Padding="14,12">
                        <StackPanel>
                            <TextBlock Text="Internet / Ping" FontSize="12" Foreground="#8b8b9c"/>
                            <TextBlock x:Name="HomePingVal" Text="-" FontSize="24" FontWeight="SemiBold" Foreground="#edecf3" Margin="0,2,0,0"/>
                            <TextBlock x:Name="HomePingName" Text="" FontSize="12" Foreground="#c9c7d6" TextTrimming="CharacterEllipsis"/>
                            <TextBlock x:Name="HomePingSub" Text="" FontSize="11" Foreground="#8b8b9c" TextTrimming="CharacterEllipsis"/>
                            <Viewbox Height="24" Stretch="Fill" Margin="0,6,0,0"><Polyline x:Name="HomeSparkPing" Width="48" Height="20" Stroke="#56dd92" StrokeThickness="1.6" StrokeLineJoin="Round"/></Viewbox>
                        </StackPanel>
                    </Border>
                </Grid>

                <Border Background="#12101f" BorderBrush="#597C5CFF" BorderThickness="1" CornerRadius="8" Padding="16,12" Margin="0,0,0,18">
                    <DockPanel>
                        <Button x:Name="BtnFixMatters" DockPanel.Dock="Right" Content="See recommended items" Style="{StaticResource BtnPrimary}" Height="38" Padding="20,0" Margin="16,0,0,0"/>
                        <StackPanel VerticalAlignment="Center">
                            <TextBlock Text="Fix what matters most" FontSize="15" FontWeight="SemiBold" Foreground="#edecf3"/>
                            <TextBlock x:Name="HomeFixSub" Text="A gentle starting set for your PC. You see the list and choose what to add." FontSize="13" Foreground="#c9c7d6" TextWrapping="Wrap"/>
                        </StackPanel>
                    </DockPanel>
                </Border>
                <TextBlock x:Name="HomeNotice" Visibility="Collapsed" FontSize="13" Foreground="#56dd92" TextWrapping="Wrap" Margin="2,-8,0,12"/>

                <DockPanel Margin="0,0,0,10" LastChildFill="False">
                    <TextBlock DockPanel.Dock="Right" Text="Pick one to look at it first. Nothing is added yet." FontSize="12" Foreground="#8b8b9c" VerticalAlignment="Bottom"/>
                    <TextBlock Text="Quick presets" FontSize="19" FontWeight="SemiBold" Foreground="#edecf3"/>
                </DockPanel>
                <UniformGrid x:Name="HomePresets" Columns="5" Margin="0,0,-10,14"/>

                <DockPanel Margin="0,0,0,10" LastChildFill="False">
                    <TextBlock DockPanel.Dock="Right" Text="Pick a goal to see its list." FontSize="12" Foreground="#8b8b9c" VerticalAlignment="Bottom"/>
                    <TextBlock Text="What do you want to do today?" FontSize="19" FontWeight="SemiBold" Foreground="#edecf3"/>
                </DockPanel>
                <UniformGrid x:Name="HomeGoals" Columns="4" Margin="0,0,-10,0"/>
            </StackPanel>

            <!-- Goal page -->
            <StackPanel x:Name="PageGoal" Visibility="Collapsed">
                <Button x:Name="BtnGoalBack" Content="Back to Home" Style="{StaticResource BtnLink}" Margin="0,0,0,10"/>
                <TextBlock Text="YOUR GOAL, YOUR CHOICE" FontSize="11" FontWeight="Bold" Foreground="#a78bff" Margin="0,0,0,4"/>
                <DockPanel Margin="0,0,0,4" LastChildFill="False">
                    <Border x:Name="GoalRecBadge" DockPanel.Dock="Right" Visibility="Collapsed" Background="#1A7C5CFF" BorderBrush="#597C5CFF"
                            BorderThickness="1" CornerRadius="10" Padding="10,3" VerticalAlignment="Center">
                        <TextBlock x:Name="GoalRecBadgeText" Text="Recommended for your laptop" FontSize="12" Foreground="#a78bff"/>
                    </Border>
                    <TextBlock x:Name="GoalTitle" Text="" FontSize="28" FontWeight="SemiBold" Foreground="#edecf3"/>
                </DockPanel>
                <TextBlock x:Name="GoalIntro" Text="" FontSize="14" Foreground="#c9c7d6" TextWrapping="Wrap" Margin="0,0,0,14"/>
                <Grid>
                    <Grid.ColumnDefinitions>
                        <ColumnDefinition Width="2*"/>
                        <ColumnDefinition Width="18"/>
                        <ColumnDefinition Width="1*" MinWidth="230"/>
                    </Grid.ColumnDefinitions>
                    <StackPanel Grid.Column="0">
                        <StackPanel x:Name="GoalItems"/>
                        <TextBlock x:Name="GoalOptTitle" Visibility="Collapsed" FontSize="13" Foreground="#8b8b9c" TextWrapping="Wrap" Margin="2,6,0,8"/>
                        <StackPanel x:Name="GoalOptional"/>
                        <StackPanel x:Name="GoalLinks"/>
                    </StackPanel>
                    <Border Grid.Column="2" Background="#0d0d16" BorderBrush="#28242f" BorderThickness="1" CornerRadius="10" Padding="18" VerticalAlignment="Top">
                        <StackPanel>
                            <Canvas Width="54" Height="54" HorizontalAlignment="Left" Margin="0,0,0,12">
                                <Ellipse Width="54" Height="54" Fill="#7c5cff"/>
                                <Ellipse Width="7" Height="7" Fill="White" Canvas.Left="14" Canvas.Top="18"/>
                                <Ellipse Width="7" Height="7" Fill="White" Canvas.Left="33" Canvas.Top="18"/>
                                <Path Data="M14,32 Q27,44 40,32" Stroke="White" StrokeThickness="3" StrokeStartLineCap="Round" StrokeEndLineCap="Round"/>
                            </Canvas>
                            <TextBlock Text="Start with a little." FontSize="17" FontWeight="SemiBold" Foreground="#edecf3"/>
                            <TextBlock Text="Try a few changes, then see how your PC feels." FontSize="13" Foreground="#c9c7d6" TextWrapping="Wrap" Margin="0,6,0,12"/>
                            <TextBlock Text="Nothing changes yet" FontSize="14" FontWeight="SemiBold" Foreground="#edecf3"/>
                            <TextBlock Text="Your choices wait in the review list until you press Apply." FontSize="13" Foreground="#c9c7d6" TextWrapping="Wrap" Margin="0,6,0,10"/>
                            <Button x:Name="BtnGoalBasket" Content="Review my list" Style="{StaticResource BtnGray}" Height="36" HorizontalAlignment="Left" Margin="0"/>
                        </StackPanel>
                    </Border>
                </Grid>
            </StackPanel>

            <!-- Pro area pages (built in code from the original cards) -->
            <StackPanel x:Name="PageProArea" Visibility="Collapsed"/>

            <!-- Preset preview -->
            <StackPanel x:Name="PagePreset" Visibility="Collapsed">
                <Button x:Name="BtnPresetBack" Content="Back to Home" Style="{StaticResource BtnLink}" Margin="0,0,0,10"/>
                <TextBlock Text="PRESET PREVIEW" FontSize="11" FontWeight="Bold" Foreground="#a78bff" Margin="0,0,0,4"/>
                <TextBlock x:Name="PresetTitle" Text="" FontSize="28" FontWeight="SemiBold" Foreground="#edecf3"/>
                <TextBlock x:Name="PresetIntro" Text="" FontSize="14" Foreground="#c9c7d6" TextWrapping="Wrap" Margin="0,4,0,14"/>
                <Border x:Name="PresetWarn" Visibility="Collapsed" Background="#14f0b545" BorderBrush="#66f0b545" BorderThickness="1" CornerRadius="8" Padding="14,10" Margin="0,0,0,14">
                    <StackPanel>
                        <TextBlock Text="Please read this first" FontSize="14" FontWeight="SemiBold" Foreground="#f0b545"/>
                        <TextBlock x:Name="PresetWarnText" Text="" FontSize="13" Foreground="#c9c7d6" TextWrapping="Wrap" Margin="0,4,0,8"/>
                        <CheckBox x:Name="ChkPresetAck" Content="I understand" Style="{StaticResource Chk}"/>
                    </StackPanel>
                </Border>
                <StackPanel x:Name="PresetList"/>
            </StackPanel>

            <!-- Search results -->
            <StackPanel x:Name="PageSearch" Visibility="Collapsed">
                <Button x:Name="BtnSearchClose" Content="Close search" Style="{StaticResource BtnLink}" Margin="0,0,0,10"/>
                <TextBlock x:Name="SearchTitle" Text="Search" FontSize="26" FontWeight="SemiBold" Foreground="#edecf3"/>
                <TextBlock x:Name="SearchSub" Text="" FontSize="13" Foreground="#c9c7d6" TextWrapping="Wrap" Margin="0,4,0,14"/>
                <StackPanel x:Name="SearchItems" MaxWidth="900" HorizontalAlignment="Left"/>
            </StackPanel>

            <!-- Help -->
            <StackPanel x:Name="PageHelp" Visibility="Collapsed" MaxWidth="760" HorizontalAlignment="Left">
                <Button x:Name="BtnHelpBack" Content="Back" Style="{StaticResource BtnLink}" Margin="0,0,0,10"/>
                <TextBlock Text="Help" FontSize="26" FontWeight="SemiBold" Foreground="#edecf3" Margin="0,0,0,12"/>
                <Border Background="#0d0d16" BorderBrush="#28242f" BorderThickness="1" CornerRadius="10" Padding="18" Margin="0,0,0,12">
                    <StackPanel>
                        <TextBlock Text="What do Safe, Careful and Advanced mean?" FontSize="15" FontWeight="SemiBold" Foreground="#edecf3" Margin="0,0,0,8"/>
                        <TextBlock Text="Safe: a normal Windows setting. Nothing usually goes wrong." FontSize="13" Foreground="#56dd92" TextWrapping="Wrap" Margin="0,2"/>
                        <TextBlock Text="Careful: a few PCs or apps may behave differently. If anything feels off, press Undo." FontSize="13" Foreground="#f0b545" TextWrapping="Wrap" Margin="0,2"/>
                        <TextBlock Text="Advanced: can affect stability or security on some PCs. Only for people who are comfortable with that." FontSize="13" Foreground="#ff6b6b" TextWrapping="Wrap" Margin="0,2"/>
                        <TextBlock Text="Goals only ever tick Safe items. Presets list Careful items too: they start switched on in the preview, and you can switch any of them off." FontSize="13" Foreground="#c9c7d6" TextWrapping="Wrap" Margin="0,8,0,0"/>
                        <TextBlock Text="These badges describe risk, not recovery. A tool such as Clean Temporary Files has a Safe badge but cannot bring deleted files back. The README grades (Exact, Partly, Manual, Cannot be undone) say what Undo can do." FontSize="13" Foreground="#c9c7d6" TextWrapping="Wrap" Margin="0,8,0,0"/>
                    </StackPanel>
                </Border>
                <Border Background="#0d0d16" BorderBrush="#28242f" BorderThickness="1" CornerRadius="10" Padding="18" Margin="0,0,0,12">
                    <StackPanel>
                        <TextBlock Text="How your changes are kept safe" FontSize="15" FontWeight="SemiBold" Foreground="#edecf3" Margin="0,0,0,8"/>
                        <TextBlock Text="Settings you switch on go to the review list, and nothing in the review list changes until you press Apply. Before a batch StreamReady tries to make a Windows restore point; that can fail, and it is a last resort, not the way to undo a single setting. Each setting saves its own original first, and Undo Last Batch (bottom left) or History puts it back. Tools marked Applies immediately act when you click them, after any confirmation: they do not use the review list, they have their own recorded originals where that is possible, and some things cannot be put back (for example deleted temporary files). See the grades in the README." FontSize="13" Foreground="#c9c7d6" TextWrapping="Wrap"/>
                    </StackPanel>
                </Border>
                <Border Background="#0d0d16" BorderBrush="#28242f" BorderThickness="1" CornerRadius="10" Padding="18" Margin="0,0,0,12">
                    <StackPanel>
                        <TextBlock Text="Why does StreamReady ask for Administrator?" FontSize="15" FontWeight="SemiBold" Foreground="#edecf3" Margin="0,0,0,8"/>
                        <TextBlock Text="It changes Windows settings that only an Administrator may change, such as registry values, services and Windows features. Windows will ask you to approve this when the app starts." FontSize="13" Foreground="#c9c7d6" TextWrapping="Wrap"/>
                    </StackPanel>
                </Border>
                <Border Background="#0d0d16" BorderBrush="#28242f" BorderThickness="1" CornerRadius="10" Padding="18" Margin="0,0,0,12">
                    <StackPanel>
                        <TextBlock Text="Tips" FontSize="15" FontWeight="SemiBold" Foreground="#edecf3" Margin="0,0,0,8"/>
                        <TextBlock Text="Ctrl+K jumps to the search box. Use Pro to see every setting in its own area. Support: join our Discord at discord.gg/2M5VKf77bp" FontSize="13" Foreground="#c9c7d6" TextWrapping="Wrap"/>
                        <WrapPanel Margin="0,12,0,0"><Button x:Name="BtnHelpWelcome" Content="Show welcome again" Style="{StaticResource BtnGray}" Height="36" Margin="0,0,8,0"/><Button x:Name="BtnHelpPaid" Content="What the paid version adds" Style="{StaticResource BtnGray}" Height="36" Margin="0,0,8,0"/><Button x:Name="BtnHelpJargon" Content="Jargon Buster" Style="{StaticResource BtnGray}" Height="36"/></WrapPanel>
                    </StackPanel>
                </Border>
            </StackPanel>



            <!-- What the paid version adds (calm information page, never a pop-up) -->
            <StackPanel x:Name="PagePaid" Visibility="Collapsed" MaxWidth="760" HorizontalAlignment="Left">
                <Button x:Name="BtnPaidBack" Content="Back" Style="{StaticResource BtnLink}" Margin="0,0,0,10"/>
                <TextBlock Text="What the paid version adds" FontSize="28" FontWeight="SemiBold" Foreground="#edecf3"/>
                <TextBlock Text="This free edition is complete on its own and stays free. The paid edition is for people who want more tools on top. Nothing here is a trial, and nothing in the free edition is locked behind a timer." FontSize="14" Foreground="#c9c7d6" TextWrapping="Wrap" Margin="0,6,0,14"/>
                <Border Background="#0d0d16" BorderBrush="#28242f" BorderThickness="1" CornerRadius="10" Padding="18" Margin="0,0,0,12">
                    <StackPanel>
                        <TextBlock Text="The paid version adds" FontSize="15" FontWeight="SemiBold" Foreground="#edecf3" Margin="0,0,0,8"/>
                        <TextBlock Text="Competitive, Advanced and Laptop presets" FontSize="13" Foreground="#c9c7d6" Margin="0,3"/>
                        <TextBlock Text="Goal pages for battery saving on laptops and for tuning one specific game" FontSize="13" Foreground="#c9c7d6" TextWrapping="Wrap" Margin="0,3"/>
                        <TextBlock Text="MSI / IRQ management (per-device interrupt mode and priority)" FontSize="13" Foreground="#c9c7d6" TextWrapping="Wrap" Margin="0,3"/>
                        <TextBlock Text="Per-game configs with backup and restore (Call of Duty BO6, Valorant, Fortnite, CS2)" FontSize="13" Foreground="#c9c7d6" TextWrapping="Wrap" Margin="0,3"/>
                        <TextBlock Text="CPU Core Optimizer for hybrid CPUs" FontSize="13" Foreground="#c9c7d6" Margin="0,3"/>
                        <TextBlock Text="A guided first-run: a friendly PC check and a short plan" FontSize="13" Foreground="#c9c7d6" TextWrapping="Wrap" Margin="0,3"/>
                        <TextBlock Text="Report a problem: saves your log to a text file for support" FontSize="13" Foreground="#c9c7d6" TextWrapping="Wrap" Margin="0,3"/>
                        <TextBlock Text="Licence-backed support and updates" FontSize="13" Foreground="#c9c7d6" Margin="0,3"/>
                    </StackPanel>
                </Border>
                <Border Background="#0d0d16" BorderBrush="#28242f" BorderThickness="1" CornerRadius="10" Padding="18" Margin="0,0,0,12">
                    <StackPanel>
                        <TextBlock Text="No tracking" FontSize="15" FontWeight="SemiBold" Foreground="#edecf3" Margin="0,0,0,8"/>
                        <TextBlock Text="Neither edition has analytics, advertising or tracking built in. This free edition will never nag you or open pop-ups about the paid version." FontSize="13" Foreground="#c9c7d6" TextWrapping="Wrap"/>
                    </StackPanel>
                </Border>
                <Border Background="#0d0d16" BorderBrush="#28242f" BorderThickness="1" CornerRadius="10" Padding="18" Margin="0,0,0,12">
                    <StackPanel>
                        <TextBlock Text="Project page" FontSize="15" FontWeight="SemiBold" Foreground="#edecf3" Margin="0,0,0,8"/>
                        <TextBlock Text="The project page is listed below. You can select and copy the address." FontSize="13" Foreground="#c9c7d6" TextWrapping="Wrap" Margin="0,0,0,8"/>
                        <TextBox x:Name="TxtPaidLink" Text="https://github.com/StreamReadyDev/streamready-oss" IsReadOnly="True" Background="#12121d" BorderBrush="#28242f" Foreground="#a78bff" FontSize="13" Padding="8,6"/>
                    </StackPanel>
                </Border>
            </StackPanel>

            <!-- v7 stage 2: review basket -->
            <StackPanel x:Name="PageBasket" Visibility="Collapsed" MaxWidth="900" HorizontalAlignment="Left">
                <Button x:Name="BtnBasketBack" Content="Back" Style="{StaticResource BtnLink}" Margin="0,0,0,10"/>
                <TextBlock Text="Review your changes" FontSize="28" FontWeight="SemiBold" Foreground="#edecf3"/>
                <TextBlock x:Name="BasketTotals" Text="" FontSize="14" Foreground="#c9c7d6" Margin="0,4,0,4" TextWrapping="Wrap"/>
                <TextBlock Text="Your originals are saved before any change, so Undo can put them back. A restore point is also tried first, as a last resort." FontSize="13" Foreground="#56dd92" TextWrapping="Wrap" Margin="0,0,0,14"/>
                <Border x:Name="BasketAdvBox" Visibility="Collapsed" Background="#14ff6b6b" BorderBrush="#66ff6b6b" BorderThickness="1" CornerRadius="8" Padding="14,10" Margin="0,4,0,12">
                    <StackPanel>
                        <TextBlock Text="Advanced items can affect stability or security on some PCs." FontSize="13" Foreground="#ff6b6b" FontWeight="SemiBold" TextWrapping="Wrap"/>
                        <CheckBox x:Name="ChkAdvAck" Style="{StaticResource Chk}" Margin="0,8,0,0" Content="I understand, and I want to apply the Advanced items."/>
                    </StackPanel>
                </Border>
                <DockPanel LastChildFill="False" Margin="0,6,0,0">
                    <Button x:Name="BtnBasketApply" DockPanel.Dock="Left" Content="Apply now" Style="{StaticResource BtnPrimary}" Height="44" Padding="28,0" FontSize="15" Margin="0" IsEnabled="False"/>
                    <Button x:Name="BtnBasketClear" DockPanel.Dock="Left" Content="Remove everything" Style="{StaticResource BtnGray}" Height="44" Margin="12,0,0,0"/>
                    <Button x:Name="BtnBasketWhyAdmin" DockPanel.Dock="Left" Content="Why does Windows ask for permission?" Style="{StaticResource BtnLink}" Margin="18,0,0,0" VerticalAlignment="Center"/>
                </DockPanel>
                <StackPanel x:Name="BasketItems"/>
                <TextBlock x:Name="BasketEmpty" Visibility="Collapsed" Text="Nothing is selected yet. Pick a goal on Home, or switch on settings in the table." FontSize="14" Foreground="#8b8b9c" TextWrapping="Wrap"/>
            </StackPanel>

            <!-- applying -->
            <StackPanel x:Name="PageApplying" Visibility="Collapsed" MaxWidth="700" HorizontalAlignment="Center">
                <TextBlock Text="Working on it" FontSize="28" FontWeight="SemiBold" Foreground="#edecf3" Margin="0,30,0,6"/>
                <TextBlock Text="A restore point is tried first, then your changes are applied one by one. Please keep this window open." FontSize="14" Foreground="#c9c7d6" TextWrapping="Wrap" Margin="0,0,0,18"/>
                <ProgressBar x:Name="ApplyProgress" Height="10" Minimum="0" Maximum="100" Value="0" Foreground="#7c5cff" Background="#171522" BorderThickness="0"/>
                <TextBlock x:Name="ApplyStep" Text="Starting..." FontSize="14" Foreground="#edecf3" Margin="0,12,0,0" TextWrapping="Wrap"/>
            </StackPanel>

            <!-- what changed -->
            <StackPanel x:Name="PageResult" Visibility="Collapsed" MaxWidth="900" HorizontalAlignment="Left">
                <TextBlock Text="What changed" FontSize="28" FontWeight="SemiBold" Foreground="#edecf3"/>
                <TextBlock x:Name="ResultScoreChange" Text="" FontSize="13" Foreground="#a78bff" Margin="0,4,0,8" Visibility="Collapsed"/>
                <TextBlock x:Name="ResultSummary" Text="" FontSize="14" Foreground="#c9c7d6" Margin="0,4,0,12" TextWrapping="Wrap"/>
                <Border x:Name="RebootBanner" Visibility="Collapsed" Background="#2c2410" BorderBrush="#f0b545" BorderThickness="1" CornerRadius="8" Padding="14,10" Margin="0,0,0,12">
                    <DockPanel>
                        <StackPanel DockPanel.Dock="Right" Orientation="Horizontal">
                            <Button x:Name="BtnRestartLater" Content="Restart later" Style="{StaticResource BtnPrimary}" Height="36"/>
                            <Button x:Name="BtnRestartNow" Content="Restart now" Style="{StaticResource BtnGray}" Height="36"/>
                        </StackPanel>
                        <StackPanel VerticalAlignment="Center">
                            <TextBlock Text="A restart is needed" FontSize="14" FontWeight="SemiBold" Foreground="#f0b545"/>
                            <TextBlock x:Name="RebootText" Text="Some changes only start working after a restart. Save your work first." FontSize="13" Foreground="#c9c7d6" TextWrapping="Wrap"/>
                        </StackPanel>
                    </DockPanel>
                </Border>
                <StackPanel x:Name="ResultItems"/>
                <TextBlock x:Name="ResultNote" Text="" FontSize="12" Foreground="#8b8b9c" TextWrapping="Wrap" Margin="0,4,0,10"/>
                <DockPanel LastChildFill="False">
                    <Button x:Name="BtnResultUndoAll" DockPanel.Dock="Left" Content="Undo this whole batch" Style="{StaticResource BtnUndoBig}" Height="42"/>
                    <Button x:Name="BtnResultHome" DockPanel.Dock="Left" Content="Back to Home" Style="{StaticResource BtnGray}" Height="42" Margin="12,0,0,0"/>
                </DockPanel>
            </StackPanel>

            <!-- history -->
            <StackPanel x:Name="PageHistory" Visibility="Collapsed" MaxWidth="900" HorizontalAlignment="Left">
                <TextBlock Text="History and Undo" FontSize="28" FontWeight="SemiBold" Foreground="#edecf3"/>
                <TextBlock Text="Batches you applied while StreamReady has been open. StreamReady saves the original of everything it changes, so you can undo it after a restart too (see Saved originals below). A few items, for example removing OneDrive, can only show you the steps to put them back by hand, and say so." FontSize="13" Foreground="#c9c7d6" Margin="0,4,0,12" TextWrapping="Wrap"/>
                <Button x:Name="BtnHistoryUndoLast" Content="Undo last batch" Style="{StaticResource BtnUndoBig}" Height="42" HorizontalAlignment="Left" Margin="0,0,0,12"/>
                <StackPanel x:Name="HistoryItems"/>
                <TextBlock x:Name="HistoryEmpty" Text="Nothing to undo yet. When you apply changes, each batch shows up here with an Undo button." FontSize="14" Foreground="#8b8b9c" TextWrapping="Wrap"/>
                <TextBlock x:Name="HistoryKept" Text="" FontSize="12" Foreground="#8b8b9c" TextWrapping="Wrap" Margin="0,12,0,0"/>
            </StackPanel>

            <!-- My PC -->
            <StackPanel x:Name="PageMyPc" Visibility="Collapsed" MaxWidth="900" HorizontalAlignment="Left">
                <DockPanel LastChildFill="False" Margin="0,0,0,10">
                    <Button x:Name="BtnMyPcRefresh" DockPanel.Dock="Right" Content="Check again" Style="{StaticResource BtnGray}" Height="36"/>
                    <TextBlock Text="My PC" FontSize="28" FontWeight="SemiBold" Foreground="#edecf3"/>
                </DockPanel>
                <TextBlock Text="A read-only look at your PC. Nothing here changes anything." FontSize="13" Foreground="#c9c7d6" Margin="0,0,0,12"/>
                <StackPanel x:Name="MyPcItems"/>
            </StackPanel>

            <!-- Settings -->
            <StackPanel x:Name="PageSettings" Visibility="Collapsed" MaxWidth="760" HorizontalAlignment="Left">
                <TextBlock Text="Settings" FontSize="28" FontWeight="SemiBold" Foreground="#edecf3" Margin="0,0,0,12"/>
                <Border Background="#0d0d16" BorderBrush="#28242f" BorderThickness="1" CornerRadius="10" Padding="18" Margin="0,0,0,12">
                    <StackPanel>
                        <CheckBox x:Name="ChkSetLarge" Style="{StaticResource Chk}" FontSize="14" Content="Larger text"/>
                        <TextBlock Text="Enlarges the main window content by about 15 percent." FontSize="12" Foreground="#8b8b9c" Margin="39,0,0,10"/>
                        <CheckBox x:Name="ChkSetSafe" Style="{StaticResource Chk}" FontSize="14" Content="Safe Mode"/>
                        <TextBlock Text="When on, only Safe settings can be switched on. Careful and Advanced ones are locked." FontSize="12" Foreground="#8b8b9c" Margin="39,0,0,10" TextWrapping="Wrap"/>
                    </StackPanel>
                </Border>
                <Border Background="#0d0d16" BorderBrush="#28242f" BorderThickness="1" CornerRadius="10" Padding="18" Margin="0,0,0,12">
                    <StackPanel>
                        <TextBlock Text="Help and support" FontSize="15" FontWeight="SemiBold" Foreground="#edecf3" Margin="0,0,0,8"/>
                        <WrapPanel>
                            <Button x:Name="BtnSetWelcome" Content="Show welcome again" Style="{StaticResource BtnGray}" Height="36" Margin="0,0,8,8"/>
                            <Button x:Name="BtnSetJargon" Content="Jargon Buster" Style="{StaticResource BtnGray}" Height="36" Margin="0,0,8,8"/>
                            <Button x:Name="BtnSetPaid" Content="What the paid version adds" Style="{StaticResource BtnGray}" Height="36" Margin="0,0,8,8"/>
                            <Button x:Name="BtnSetAbout" Content="About" Style="{StaticResource BtnGray}" Height="36" Margin="0,0,8,8"/>
                        </WrapPanel>
                        <TextBlock x:Name="SettingsNote" Text="" FontSize="12" Foreground="#56dd92" TextWrapping="Wrap"/>
                    </StackPanel>
                </Border>
            </StackPanel>

            <!-- Pro: tweak table -->
            <StackPanel x:Name="PageTable" Visibility="Collapsed">
                <DockPanel LastChildFill="False" Margin="0,0,0,8">
                    <TextBlock x:Name="TableCount" DockPanel.Dock="Right" Text="" FontSize="12" Foreground="#8b8b9c" VerticalAlignment="Bottom"/>
                    <TextBlock Text="Everything" FontSize="26" FontWeight="SemiBold" Foreground="#edecf3"/>
                </DockPanel>
                <StackPanel x:Name="ProToolbar"/>
                <Border Background="#0d0d16" BorderBrush="#28242f" BorderThickness="1" CornerRadius="8" Height="36" Margin="0,0,0,8">
                    <Grid>
                        <TextBox x:Name="TxtTableSearch" Background="Transparent" BorderThickness="0" Foreground="#edecf3" CaretBrush="#edecf3" FontSize="13" Padding="10,0" VerticalContentAlignment="Center"/>
                        <TextBlock x:Name="TxtTableHint" Text="Filter by name, what it does, or the original name" Foreground="#8b8b9c" FontSize="13" Margin="12,0,0,0" VerticalAlignment="Center" IsHitTestVisible="False"/>
                    </Grid>
                </Border>
                <WrapPanel x:Name="TableFilters" Margin="0,0,0,8"/>
                <Border Background="#0d0d16" BorderBrush="#28242f" BorderThickness="1" CornerRadius="8" Padding="0">
                    <StackPanel x:Name="TableRows"/>
                </Border>
            </StackPanel>
        </StackPanel>
    </ScrollViewer>
    <!-- Action bar for the welcome page and the goal and preset pages: pinned so the main button is always reachable, even in a short window -->
    <Border x:Name="ActionBar" Grid.Row="1" Grid.Column="1" Visibility="Collapsed" Background="#050508" BorderBrush="#1E7C5CFF" BorderThickness="0,1,0,0" Padding="24,12">
        <Grid>
            <StackPanel x:Name="BarWelcome" Orientation="Horizontal" Visibility="Collapsed">
                <Button x:Name="BtnWelcomeStart" Content="Get started" Style="{StaticResource BtnPrimary}" Height="42" Padding="26,0" FontSize="15" Margin="0"/>
                <TextBlock Text="You can choose your own settings at any time." FontSize="12" Foreground="#8b8b9c" Margin="28,0,0,0" VerticalAlignment="Center"/>
            </StackPanel>
            <StackPanel x:Name="BarScan" Orientation="Horizontal" Visibility="Collapsed">
                <Button x:Name="BtnScanNext" Content="See my plan" Style="{StaticResource BtnPrimary}" Height="42" Padding="26,0" FontSize="15" Margin="0"/>
                <Button x:Name="BtnScanBack" Content="Back" Style="{StaticResource BtnLink}" Margin="18,0,0,0" VerticalAlignment="Center"/>
                <TextBlock Text="This check only reads your PC." FontSize="12" Foreground="#8b8b9c" Margin="28,0,0,0" VerticalAlignment="Center"/>
            </StackPanel>
            <StackPanel x:Name="BarPlan" Orientation="Horizontal" Visibility="Collapsed">
                <Button x:Name="BtnPlanGo" Content="Get my PC ready" Style="{StaticResource BtnPrimary}" Height="42" Padding="26,0" FontSize="15" Margin="0"/>
                <Button x:Name="BtnPlanSkip" Content="Skip, take me Home" Style="{StaticResource BtnLink}" Margin="18,0,0,0" VerticalAlignment="Center"/>
                <TextBlock Text="Ticks only what you switched on, then opens your review list. Nothing changes until you press Apply." FontSize="12" Foreground="#8b8b9c" TextWrapping="Wrap" MaxWidth="360" Margin="28,0,0,0" VerticalAlignment="Center"/>
            </StackPanel>

            <StackPanel x:Name="BarList" Orientation="Horizontal" Visibility="Collapsed">
                <Button x:Name="BtnListAdd" Content="Add to review list" Style="{StaticResource BtnPrimary}" Height="42" Padding="26,0" FontSize="15" Margin="0"/>
                <Button x:Name="BtnListBack" Content="Back" Style="{StaticResource BtnLink}" Margin="18,0,0,0" VerticalAlignment="Center"/>
                <TextBlock x:Name="LblListHint" Text="Only what is switched on is added. Nothing changes until you press Apply." FontSize="12" Foreground="#8b8b9c" TextWrapping="Wrap" MaxWidth="380" Margin="28,0,0,0" VerticalAlignment="Center"/>
            </StackPanel>
        </Grid>
    </Border>
    </Grid>
    <!-- #endregion v7 Simple mode -->
    <!-- Row 2: Progress + verbose Activity Log (inline collapsible panel, no popup) -->
    <Border x:Name="LogBarBorder" Grid.Row="2" Background="#050508" BorderBrush="#1E7C5CFF" BorderThickness="0,1,0,0">
        <DockPanel>
            <ProgressBar x:Name="ProgressBar" DockPanel.Dock="Top"
                         Height="4" Minimum="0" Maximum="100" Value="0"
                         Foreground="#7c5cff"/>
            <DockPanel DockPanel.Dock="Top" Margin="16,4,16,4">
                <!-- Log and About buttons now live in the top bar (same x:Name). -->
                <TextBlock x:Name="LogText" DockPanel.Dock="Right"
                           Text="Welcome to StreamReady" Foreground="#5f5f70"
                           FontSize="11" VerticalAlignment="Center" Margin="0,0,12,0"/>
                <TextBlock x:Name="ProgressLabel" Text="Ready" Foreground="#767685"
                           FontSize="11" VerticalAlignment="Center"/>
            </DockPanel>
            <ListBox x:Name="LogList" DockPanel.Dock="Top" Height="130" Margin="12,0,12,8"
                     Visibility="Collapsed"
                     Background="Transparent" BorderThickness="0"
                     ScrollViewer.HorizontalScrollBarVisibility="Disabled"/>
        </DockPanel>
    </Border>
    <!-- Row 3: bottom bar on every screen: Undo, review basket text, Review and apply -->
    <Border x:Name="BottomBar" Grid.Row="3" Background="#050508" BorderBrush="#1E7C5CFF" BorderThickness="0,1,0,0" MinHeight="62">
        <Grid Margin="16,8">
            <Grid.ColumnDefinitions>
                <ColumnDefinition Width="Auto"/>
                <ColumnDefinition Width="*"/>
                <ColumnDefinition Width="Auto"/>
            </Grid.ColumnDefinitions>
            <Button x:Name="BtnUndoLast" Grid.Column="0" Content="Undo Last Batch"
                    Style="{StaticResource BtnUndoBig}" Height="42" IsEnabled="False" Margin="0,0,18,0"
                    ToolTip="Put back the settings from the last batch you applied."/>
            <StackPanel Grid.Column="1" VerticalAlignment="Center">
                <TextBlock x:Name="TxtSelectionCount" Text="0 selected: 0 Safe, 0 Careful, 0 Advanced"
                           Foreground="#8b8b9c" FontSize="13" FontWeight="SemiBold" TextTrimming="CharacterEllipsis"/>
                <TextBlock Text="A restore point is tried before each batch" Foreground="#56dd92" FontSize="12" Margin="0,3,0,0" TextTrimming="CharacterEllipsis"/>
            </StackPanel>
            <Button x:Name="BtnOpenBasket" Grid.Column="2" Content="Review and apply"
                    Style="{StaticResource BtnPrimary}" Height="42" MinWidth="180" FontSize="14" IsEnabled="False" Margin="12,0,0,0"
                    ToolTip="Open your review list. Nothing changes until you press Apply now there."/>
            <!-- The original apply button stays (hidden): the basket page raises its Click so the original batch engine runs. -->
            <Button x:Name="BtnApplyAll" Grid.Column="2" Content="Apply Selected" Visibility="Collapsed"
                    Style="{StaticResource BtnPrimary}" Height="42" IsEnabled="False"/>
        </Grid>
    </Border>
    <!-- Command palette (Ctrl+K) -->
    <Grid x:Name="PaletteHost" Grid.Row="0" Grid.RowSpan="4" Visibility="Collapsed" Background="#B3000000">
        <Border Width="560" VerticalAlignment="Top" Margin="0,90,0,0" Background="#0d0d16" BorderBrush="#7c5cff" BorderThickness="1" CornerRadius="10" Padding="12">
            <StackPanel>
                <TextBox x:Name="TxtPalette" Background="#12121d" BorderBrush="#28242f" Foreground="#edecf3" CaretBrush="#edecf3" FontSize="15" Padding="10,8"
                         ToolTip="Type to search settings, pages and actions. Enter to open, Esc to close."/>
                <ListBox x:Name="LstPalette" Margin="0,8,0,0" MaxHeight="360" Background="Transparent" BorderThickness="0" Foreground="#edecf3" FontSize="14"/>
                <TextBlock Text="Enter to open, Esc to close" FontSize="11" Foreground="#5f5f70" Margin="2,8,0,0"/>
            </StackPanel>
        </Border>
    </Grid>
</Grid>
</Window>
"@
#endregion XAML UI

#region Core Engine
