foreach ($n in $names) { $c[$n] = $window.FindName($n) }

# ─── Activity log toggle (inline collapsible panel, not a Popup) ───────────────
if ($c['BtnToggleLog'] -and $c['LogList']) {
    $c['BtnToggleLog'].Add_Click({
        $c['LogList'].Visibility = if ($c['LogList'].Visibility -eq 'Visible') { 'Collapsed' } else { 'Visible' }
    })
}

# ─── About box ──────────────────────────────────────────────────────────────────
if ($c['BtnAbout']) {
    $c['BtnAbout'].Add_Click({ Show-AboutWindow })
}

# ─── Tweak checkbox list ───────────────────────────────────────────────────────
$tweakBoxes = @(
    'ChkGameMode','ChkHighPerf','ChkUltPerf','ChkHwGpu','ChkMouseFix',
    'ChkXboxDvr','ChkFSO','ChkStickyKeys','ChkObsPriority','ChkQoS',
