    'ChkDisableWpbt','ChkDisableExplorerFolderDiscovery','ChkServicesManual','ChkVerboseLogon',
    'ChkFastShutdown','ChkShowFullPath','ChkPhotoViewer',
    'ChkDisableIPv6','ChkPreferIPv4','ChkDisableTeredo','ChkDisableStorageSense','ChkSetDisplayPerf',
    'ChkDisableMultiplaneOverlay','ChkSetUtcTime','ChkHideSettingsHome',
    'ChkNoAutoRestart','ChkExcludeDriversWU','ChkDisableDeliveryWU',
    # v6 GPU Tweaks (vendor-conditional - populated via $dispatch at runtime)
    'ChkGpuNvULL','ChkGpuNvFHBC','ChkGpuNvPState','ChkGpuNvTexFilter','ChkGpuNvTelemetry',
    'ChkGpuNvThreadedOpt','ChkGpuNvNpiProfile',
    'ChkGpuAmdAntiLag','ChkGpuAmdULPS','ChkGpuAmdRSR','ChkGpuAmdTDR','ChkGpuAmdTexFilter','ChkGpuAmdTelemetry',
