$script:TweakInfo = @{}
foreach ($ln in ($script:TweakInfoRaw -split "`r?`n")) {
    $p = $ln.Split('|')
    if ($p.Count -ge 6 -and $p[0]) { $script:TweakInfo[$p[0]] = @{ Risk = $p[1]; Name = $p[2]; Desc = $p[3]; Tech = $p[4]; Area = $p[5] } }
}
function Get-TweakRisk { param([string]$Id)
    if ($script:TweakInfo.ContainsKey($Id)) { return $script:TweakInfo[$Id].Risk }
    return 'C'
}

function Update-Count {
    $n = 0; $nS = 0; $nC = 0; $nA = 0
    foreach ($nm in $tweakBoxes) {
        if ($c[$nm] -and $c[$nm].IsChecked) {
            $n++
            switch (Get-TweakRisk $nm) { 'S' { $nS++ } 'A' { $nA++ } default { $nC++ } }
        }
    }
    # Review basket text: "N selected: x Safe, y Careful, z Advanced" (unknown tweaks count as Careful)
    $tb = $c['TxtSelectionCount']
    $tb.Inlines.Clear()
    $parts = @(
        @("$n selected: ", '#edecf3'), ("$nS Safe", '#56dd92'), (', ', '#8b8b9c'),
        ("$nC Careful", '#f0b545'), (', ', '#8b8b9c'), ("$nA Advanced", '#ff6b6b')
    )
    foreach ($p in $parts) {
        $r = New-Object System.Windows.Documents.Run $p[0]
        $r.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString($(if ($n -eq 0 -and $p[1] -eq '#edecf3') { '#8b8b9c' } else { $p[1] }))
        $tb.Inlines.Add($r)
    }
    if ($n -eq 0 -and $c['HomeNotice']) { $c['HomeNotice'].Visibility = 'Collapsed' }
    $c['BtnApplyAll'].Content   = if ($n -gt 0) { "Apply Selected ($n)" } else { "Apply Selected" }
    $c['BtnApplyAll'].IsEnabled = ($n -gt 0)
    if (Get-Command Update-BasketUi -ErrorAction SilentlyContinue) { Update-BasketUi $n $nS $nC $nA }
}

function Get-RegVal { param($p,$n) try { (Get-ItemProperty $p -Name $n -EA Stop).$n } catch { $null } }
function Set-Reg    { param($p,$n,$v,$t="DWord") if (-not (Test-Path $p)) { New-Item -Path $p -Force|Out-Null }; Set-ItemProperty -Path $p -Name $n -Value $v -Type $t -ErrorAction Stop }

# Win32_Processor / Win32_PhysicalMemory / Win32_VideoController get queried independently
# by ~10 different functions across Dashboard/Health Report/CPU/GPU detection, several of
# them back-to-back during startup and again on every Dashboard revisit. None of that data
# changes meaningfully faster than a few seconds, so a short TTL cache turns those into one
# real WMI round-trip instead of many. Keyed by class name (+ namespace when non-default)
# so different callers asking for the same class share one cached result.
$script:_CimCache = @{}
function Get-CachedCim {
    param([string]$ClassName, [string]$Namespace = 'root/cimv2', [int]$TtlSeconds = 5, [switch]$Live)
    # Win32_Processor takes about one second to answer whenever the live fields (current clock speed, load) are included. Nearly every caller
    # only wants the fixed facts, so those are read on their own and kept for ten minutes. Use -Live when the live fields are needed.
    $props = $null; $suffix = ''
    if ($ClassName -eq 'Win32_Processor' -and -not $Live) {
        $props = @('Name','Manufacturer','NumberOfCores','NumberOfLogicalProcessors','MaxClockSpeed','ProcessorId','Description','Caption','Family','SocketDesignation','L2CacheSize','L3CacheSize')
        $suffix = '#static'; if ($TtlSeconds -lt 600) { $TtlSeconds = 600 }
    }
    $key   = "$Namespace!$ClassName$suffix"
    $now   = [DateTime]::Now
    $entry = $script:_CimCache[$key]
    if ($entry -and ($now - $entry.Time).TotalSeconds -lt $TtlSeconds) {
        return $entry.Data
    }
    $data = if ($props) { Get-CimInstance -Namespace $Namespace -ClassName $ClassName -Property $props } else { Get-CimInstance -Namespace $Namespace -ClassName $ClassName }
    $script:_CimCache[$key] = @{ Time = $now; Data = $data }
    return $data
}

# Appends a sample to a rolling per-metric history buffer and redraws the given Dashboard
# sparkline Polyline to fit it, auto-scaled to the buffer's own min/max each time so the
# line always uses the tile's full height regardless of the metric's absolute range.
$script:_SparkHistory = @{}
function Update-Sparkline {
    param([string]$Key, [double]$Value, $Polyline, [int]$MaxSamples = 8)
    if (-not $Polyline) { return }
    if (-not $script:_SparkHistory.ContainsKey($Key)) {
        $script:_SparkHistory[$Key] = New-Object System.Collections.Generic.List[double]
    }
    $hist = $script:_SparkHistory[$Key]
    # Seed with a duplicate of the very first sample so a (flat) line is visible on the
    # first draw instead of nothing showing until a second real sample comes in.
    if ($hist.Count -eq 0) { $hist.Add($Value) }
    $hist.Add($Value)
    while ($hist.Count -gt $MaxSamples) { $hist.RemoveAt(0) }

    $w = $Polyline.Width; $h = $Polyline.Height
    $min = ($hist | Measure-Object -Minimum).Minimum
    $max = ($hist | Measure-Object -Maximum).Maximum
    $range = if ($max -eq $min) { 1 } else { $max - $min }
    # Always span the polyline's full width regardless of how many samples exist so far
    # (dividing by a fixed MaxSamples-1 would leave the line stuck in the left portion of
    # the box until the buffer fully fills).
    $lastIdx = [math]::Max($hist.Count - 1, 1)
    $points = New-Object System.Windows.Media.PointCollection
    for ($i = 0; $i -lt $hist.Count; $i++) {
        $x = $w * $i / $lastIdx
        $y = $h - ((($hist[$i] - $min) / $range) * ($h - 4)) - 2
        $points.Add([System.Windows.Point]::new($x, $y)) | Out-Null
    }
    $Polyline.Points = $points
}

# Resolves the Tcpip\Parameters\Interfaces\{GUID} key for the adapter carrying the
# current default IPv4 address - the single source of truth for "the active adapter"
# used by both Apply-NaglesAlgo and Test-Nagle, so the dashboard badge always agrees
# with what was actually written to the registry.
function Get-ActiveAdapterIfacePath {
    $ifaces = "HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces"
    # Prefer the adapter actually carrying the default route (lowest-metric 0.0.0.0/0),
    # so a VPN or Hyper-V/WSL virtual adapter with its own IPv4 address doesn't get
    # picked over the real physical gaming NIC. Falls back to the old "first DHCP/Manual
    # address" behavior if no default route can be resolved.
    $myIP = $null
    $route = Get-NetRoute -DestinationPrefix "0.0.0.0/0" -AddressFamily IPv4 -EA SilentlyContinue |
             Sort-Object -Property RouteMetric | Select-Object -First 1
    if ($route) {
        $myIP = (Get-NetIPAddress -InterfaceIndex $route.InterfaceIndex -AddressFamily IPv4 -EA SilentlyContinue |
                 Where-Object { $_.PrefixOrigin -eq 'Dhcp' -or $_.PrefixOrigin -eq 'Manual' } |
                 Select-Object -First 1).IPAddress
    }
    if (-not $myIP) {
        $myIP = (Get-NetIPAddress -AddressFamily IPv4 | Where-Object { $_.PrefixOrigin -eq 'Dhcp' -or $_.PrefixOrigin -eq 'Manual' } | Select-Object -First 1).IPAddress
    }
    if (-not $myIP) { return $null }
    $target = $null
    Get-ChildItem $ifaces -EA SilentlyContinue | ForEach-Object {
        $dhcpObj = Get-ItemProperty $_.PSPath -Name "DhcpIPAddress" -EA SilentlyContinue
        $dhcp = if ($dhcpObj) { $dhcpObj.DhcpIPAddress } else { $null }
        $statObj = Get-ItemProperty $_.PSPath -Name "IPAddress" -EA SilentlyContinue
        $stat = if ($statObj) { $statObj.IPAddress } else { $null }
        if ($dhcp -eq $myIP -or ($stat -and $stat -contains $myIP)) { $target = $_.PSPath }
    }
    return $target
}

# --- Original-state undo (v7) ---------------------------------------------------------------------
# Records, BEFORE a tweak writes, whether each registry key and value existed and what the value was
# (type and data), then restores exactly that on Undo: a value that did not exist is deleted, a value
# that did exist gets its original type and data back, a key is removed only if the tweak created it
# and it is empty again. Pre-existing subkeys and values are never deleted. In the free edition the saved originals live in
# ProgramData\StreamReady-OSS\undo (the engine region below), so Undo survives closing the app.
# Entry format: 'Key|ValueName' or 'Key|ValueName|Token' (Token = one name=number pair inside a string value).
# Crash-recovery file for a tweak that stopped part-way: imported into the engine store at the next start, then set aside.
$script:UndoRecordPath = "$env:LOCALAPPDATA\StreamReady\undo_records_oss.json"
$script:UndoSpecs = @{
    'ChkHwGpu' = @('HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers|HwSchMode')
    'ChkObsPriority' = @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\obs64.exe\PerfOptions|CpuPriorityClass')
    'ChkQoS' = @('HKLM:\SOFTWARE\Policies\Microsoft\Windows\Psched|NonBestEffortLimit')
    'ChkMMCSS' = @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile|SystemResponsiveness')
    'ChkNetworkThrottle' = @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile|NetworkThrottlingIndex')
    'ChkPowerThrottle' = @('HKLM:\SYSTEM\CurrentControlSet\Control\Power\PowerThrottling|PowerThrottlingOff')
    'ChkGamesMMCSS' = @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Games|GPU Priority', 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Games|Priority', 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Games|Scheduling Category')
    'ChkDisablePageExec' = @('HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management|DisablePagingExecutive')
    'ChkVisualPerf' = @('HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\VisualEffects|VisualFXSetting', 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced|TaskbarAnimations')
    'ChkNtfsOpt' = @('HKLM:\SYSTEM\CurrentControlSet\Control\FileSystem|NtfsDisableLastAccessUpdate', 'HKLM:\SYSTEM\CurrentControlSet\Control\FileSystem|NtfsDisable8dot3NameCreation')
    'ChkAudioLatency' = @('HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Pro Audio|Priority', 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Pro Audio|GPU Priority', 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Pro Audio|Scheduling Category', 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Pro Audio|SFIO Priority')
    'ChkWin32Priority' = @('HKLM:\SYSTEM\CurrentControlSet\Control\PriorityControl|Win32PrioritySeparation')
    'ChkAhciLpmOff' = @('HKLM:\SYSTEM\CurrentControlSet\Services\storahci\Parameters\Device|TxnMaxPayload', 'HKLM:\SYSTEM\CurrentControlSet\Services\storahci\Parameters\Device|LPM Management Enabled', 'HKLM:\SYSTEM\CurrentControlSet\Services\storahci|EnableIdlePowerManagement')
    'ChkGpuNvThreadedOpt' = @('HKLM:\SOFTWARE\NVIDIA Corporation\Global\NVTweak|ThreadedOptimization')
    'ChkNvidiaShaderCache' = @('HKLM:\SOFTWARE\NVIDIA Corporation\Global\NVTweak|ShaderCacheSize')
    'ChkGpuAmdTDR' = @('HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers|TdrDelay')
    'ChkLocation' = @('HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\CapabilityAccessManager\ConsentStore\location|Value')
    'ChkBingSearch' = @('HKCU:\Software\Microsoft\Windows\CurrentVersion\Search|BingSearchEnabled', 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Search|CortanaConsent')
    'ChkBgApps' = @('HKCU:\Software\Microsoft\Windows\CurrentVersion\BackgroundAccessApplications|GlobalUserDisabled')
    'ChkDisableNotifications' = @('HKCU:\Software\Policies\Microsoft\Windows\Explorer|DisableNotificationCenter', 'HKCU:\Software\Microsoft\Windows\CurrentVersion\PushNotifications|ToastEnabled')
    'ChkEdgeDebloat' = @('HKLM:\SOFTWARE\Policies\Microsoft\Edge|HubsSidebarEnabled', 'HKLM:\SOFTWARE\Policies\Microsoft\Edge|MicrosoftEdgeShoppingAssistantEnabled', 'HKLM:\SOFTWARE\Policies\Microsoft\Edge|DiagnosticData')
    'ChkDisableFastStartup' = @('HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Power|HiberbootEnabled')
    'ChkDisableWpbt' = @('HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager|DisableWpbtExecution')
