# ─── Wire checkboxes to counter ────────────────────────────────────────────────
foreach ($name in $tweakBoxes) {
    $chk = $c[$name]
    if (-not $chk) { continue }
    $chk.Add_Checked(   { Update-Count })
    $chk.Add_Unchecked( { Update-Count })
}
