#region Gaming Tweaks
# ─── Apply functions (each returns an undo scriptblock) ───────────────────────
function Apply-GameMode {
    Write-SR "Enabling Windows Game Mode" 'APPLY'
    $o = @{ a=(Get-RegVal "HKCU:\Software\Microsoft\GameBar" "AllowAutoGameMode"); b=(Get-RegVal "HKCU:\Software\Microsoft\GameBar" "AutoGameModeEnabled") }
    Set-RegLogged "HKCU:\Software\Microsoft\GameBar" "AllowAutoGameMode"   1
    Set-RegLogged "HKCU:\Software\Microsoft\GameBar" "AutoGameModeEnabled" 1
    $va = [int](Coalesce $o.a 0); $vb = [int](Coalesce $o.b 0)
    Write-SR "Game Mode enabled successfully" 'OK'
    return [scriptblock]::Create("Set-Reg 'HKCU:\Software\Microsoft\GameBar' 'AllowAutoGameMode' $va; Set-Reg 'HKCU:\Software\Microsoft\GameBar' 'AutoGameModeEnabled' $vb")
}
function Apply-HighPerf {
    Write-SR "Switching to High Performance power plan" 'APPLY'
    $old = ((powercfg -getactivescheme) -replace '.*GUID: ([a-f0-9\-]+).*','$1').Trim()
    Write-SR "Previous power plan GUID: $old" 'INFO'
    powercfg -setactive 8c5e7fda-e8bf-4a96-9a85-a6e23a8c635c 2>$null
    Write-SR "Power plan set to High Performance" 'OK'
    return [scriptblock]::Create("powercfg -setactive '$old' 2>`$null")
}
function Apply-UltPerf {
    Write-SR "Switching to Ultimate Performance power plan" 'APPLY'
    $old = ((powercfg -getactivescheme) -replace '.*GUID: ([a-f0-9\-]+).*','$1').Trim()
    Write-SR "Previous power plan GUID: $old" 'INFO'

    # Check if an Ultimate Performance plan already exists
    $existing = (powercfg -list | Where-Object { $_ -match 'Ultimate Performance' } | Select-Object -First 1)
    $ult = if ($existing) { ($existing -replace '.*GUID: ([a-f0-9\-]+).*','$1').Trim() } else { $null }
    $wasPreExisting = $null -ne $ult

    if (-not $ult) {
        Write-SR "Duplicating Ultimate Performance base plan" 'INFO'
        $dupOut = powercfg -duplicatescheme e9a42b02-d5df-448d-aa00-03f14749eb61
        $ult = ($dupOut -replace '.*GUID: ([a-f0-9\-]+).*','$1').Trim()
        $script:UndoPowerCreatedGuid = $ult
    } else {
        Write-SR "Ultimate Performance plan already exists (GUID: $ult) - reusing" 'INFO'
    }

    if ($ult) {
        Write-SR "Activating Ultimate Performance plan GUID: $ult" 'INFO'
        powercfg -setactive $ult 2>$null
        Write-SR "Power plan set to Ultimate Performance" 'OK'
    } else {
        Write-SR "Could not locate or create Ultimate Performance plan" 'WARN'
    }

    # Only delete the plan on undo if we created it (not if it pre-existed)
    if ($ult -and -not $wasPreExisting) {
        return [scriptblock]::Create("powercfg -setactive '$old' 2>`$null; powercfg -deletescheme '$ult' 2>`$null")
    } else {
        return [scriptblock]::Create("powercfg -setactive '$old' 2>`$null")
    }
}
function Apply-HwGpu {
    Write-SR "Enabling Hardware-Accelerated GPU Scheduling (HAGS)" 'APPLY'
    $o = Get-RegVal "HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers" "HwSchMode"
    Write-SR "Current HwSchMode value: $(Coalesce $o 'not set')" 'INFO'
    Set-RegLogged "HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers" "HwSchMode" 2
    Write-SR "HAGS enabled - reboot required to take effect" 'OK'
    $v = [int](Coalesce $o 1)
    return [scriptblock]::Create("Set-Reg 'HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers' 'HwSchMode' $v")
}
function Apply-MouseFix {
    Write-SR "Disabling Mouse Acceleration (Pointer Precision)" 'APPLY'
    $o = @{ s=(Get-RegVal "HKCU:\Control Panel\Mouse" "MouseSpeed"); t1=(Get-RegVal "HKCU:\Control Panel\Mouse" "MouseThreshold1"); t2=(Get-RegVal "HKCU:\Control Panel\Mouse" "MouseThreshold2") }
    Write-SR "Previous values - Speed: $(Coalesce $o.s 1)  Threshold1: $(Coalesce $o.t1 6)  Threshold2: $(Coalesce $o.t2 10)" 'INFO'
    Set-RegLogged "HKCU:\Control Panel\Mouse" "MouseSpeed"      "0" "String"
    Set-RegLogged "HKCU:\Control Panel\Mouse" "MouseThreshold1" "0" "String"
    Set-RegLogged "HKCU:\Control Panel\Mouse" "MouseThreshold2" "0" "String"
    Write-SR "Mouse acceleration disabled - raw input active" 'OK'
    $vs = Coalesce $o.s 1; $vt1 = Coalesce $o.t1 6; $vt2 = Coalesce $o.t2 10
    return [scriptblock]::Create("Set-Reg 'HKCU:\Control Panel\Mouse' 'MouseSpeed' '$(ConvertTo-SqValue $vs)' 'String'; Set-Reg 'HKCU:\Control Panel\Mouse' 'MouseThreshold1' '$(ConvertTo-SqValue $vt1)' 'String'; Set-Reg 'HKCU:\Control Panel\Mouse' 'MouseThreshold2' '$(ConvertTo-SqValue $vt2)' 'String'")
}
function Apply-KeyboardRepeat {
    Write-SR "Setting Keyboard Repeat Rate to maximum" 'APPLY'
    $o = @{ d=(Get-RegVal "HKCU:\Control Panel\Keyboard" "KeyboardDelay"); s=(Get-RegVal "HKCU:\Control Panel\Keyboard" "KeyboardSpeed") }
    Write-SR "Previous values - Delay: $(Coalesce $o.d 1)  Speed: $(Coalesce $o.s 31)" 'INFO'
    Set-RegLogged "HKCU:\Control Panel\Keyboard" "KeyboardDelay" "0"  "String"
    Set-RegLogged "HKCU:\Control Panel\Keyboard" "KeyboardSpeed" "31" "String"
    Write-SR "Keyboard repeat delay set to shortest, repeat rate set to fastest" 'OK'
    $vd = Coalesce $o.d 1; $vs = Coalesce $o.s 31
    return [scriptblock]::Create("Set-Reg 'HKCU:\Control Panel\Keyboard' 'KeyboardDelay' '$(ConvertTo-SqValue $vd)' 'String'; Set-Reg 'HKCU:\Control Panel\Keyboard' 'KeyboardSpeed' '$(ConvertTo-SqValue $vs)' 'String'")
}
function Apply-XboxDvr {
    Write-SR "Disabling Xbox Game Bar / DVR" 'APPLY'
    $o = @{ a=(Get-RegVal "HKCU:\Software\Microsoft\Windows\CurrentVersion\GameDVR" "AppCaptureEnabled"); b=(Get-RegVal "HKCU:\System\GameConfigStore" "GameDVR_Enabled") }
    Set-RegLogged "HKCU:\Software\Microsoft\Windows\CurrentVersion\GameDVR" "AppCaptureEnabled" 0
    Set-RegLogged "HKCU:\System\GameConfigStore" "GameDVR_Enabled" 0
    Write-SR "Xbox Game Bar and DVR disabled" 'OK'
    $va = [int](Coalesce $o.a 1); $vb = [int](Coalesce $o.b 1)
    return [scriptblock]::Create("Set-Reg 'HKCU:\Software\Microsoft\Windows\CurrentVersion\GameDVR' 'AppCaptureEnabled' $va; Set-Reg 'HKCU:\System\GameConfigStore' 'GameDVR_Enabled' $vb")
}
function Apply-FSO {
    Write-SR "Disabling Fullscreen Optimizations" 'APPLY'
    $o = @{ m=(Get-RegVal "HKCU:\System\GameConfigStore" "GameDVR_FSEBehaviorMode"); b=(Get-RegVal "HKCU:\System\GameConfigStore" "GameDVR_FSEBehavior") }
    Set-RegLogged "HKCU:\System\GameConfigStore" "GameDVR_FSEBehaviorMode" 2
    Set-RegLogged "HKCU:\System\GameConfigStore" "GameDVR_FSEBehavior"     2
    Write-SR "Fullscreen Optimizations disabled" 'OK'
    $vm = [int](Coalesce $o.m 0); $vb = [int](Coalesce $o.b 0)
    return [scriptblock]::Create("Set-Reg 'HKCU:\System\GameConfigStore' 'GameDVR_FSEBehaviorMode' $vm; Set-Reg 'HKCU:\System\GameConfigStore' 'GameDVR_FSEBehavior' $vb")
