function Apply-StickyKeys {
    Write-SR "Disabling Sticky Keys prompt" 'APPLY'
    Set-RegLogged "HKCU:\Control Panel\Accessibility\StickyKeys"        "Flags" "506" "String"
    Set-RegLogged "HKCU:\Control Panel\Accessibility\ToggleKeys"        "Flags" "58"  "String"
    Set-RegLogged "HKCU:\Control Panel\Accessibility\Keyboard Response" "Flags" "122" "String"
    Write-SR "Sticky Keys, Toggle Keys and Filter Keys prompts suppressed" 'OK'
    return { Set-Reg "HKCU:\Control Panel\Accessibility\StickyKeys" "Flags" "510" "String"; Set-Reg "HKCU:\Control Panel\Accessibility\ToggleKeys" "Flags" "62" "String"; Set-Reg "HKCU:\Control Panel\Accessibility\Keyboard Response" "Flags" "126" "String" }
}
function Apply-ObsPriority {
    Write-SR "Setting OBS to High CPU priority via IFEO" 'APPLY'
    $p = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\obs64.exe\PerfOptions"
    $existed = Test-Path $p
    $oldVal  = if ($existed) { (Get-ItemProperty $p -Name "CpuPriorityClass" -EA SilentlyContinue).CpuPriorityClass } else { $null }
    if (-not $existed) {
        Write-SR "Creating IFEO key for obs64.exe" 'REG'
        New-Item -Path $p -Force | Out-Null
    }
    Write-SR "Set  $p\CpuPriorityClass  =  3  (High)" 'REG'
    Set-ItemProperty $p -Name "CpuPriorityClass" -Value 3 -Type DWord
    Write-SR "OBS priority set to High (class 3)" 'OK'
    if ($existed) {
        $v = if ($null -ne $oldVal) { $oldVal } else { 2 }
        return [scriptblock]::Create("Set-ItemProperty '$p' -Name 'CpuPriorityClass' -Value $v -Type DWord")
    }
    else { return { Remove-Item "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\obs64.exe\PerfOptions" -Recurse -Force -EA SilentlyContinue } }
}
function Apply-QoS {
    Write-SR "Removing Windows network bandwidth reserve (QoS 20% cap)" 'APPLY'
    $p = "HKLM:\SOFTWARE\Policies\Microsoft\Windows\Psched"
    $o = Get-RegVal $p "NonBestEffortLimit"
    Write-SR "Current NonBestEffortLimit: $(Coalesce $o 20)%" 'INFO'
    if (-not (Test-Path $p)) { New-Item -Path $p -Force | Out-Null }
    Write-SR "Set  $p\NonBestEffortLimit  =  0" 'REG'
    Set-ItemProperty $p -Name "NonBestEffortLimit" -Value 0 -Type DWord
    Write-SR "Bandwidth reserve removed - full bandwidth now available" 'OK'
    $v = [int](Coalesce $o 20)
    return [scriptblock]::Create("Set-ItemProperty 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Psched' -Name 'NonBestEffortLimit' -Value $v -Type DWord")
}
