#region Privacy Tweaks
function Apply-Telemetry {
    Write-SR "Disabling Windows Telemetry (DiagTrack)" 'APPLY'
    Write-SR "Stopping DiagTrack service" 'SVC'
    Stop-Service DiagTrack -Force -EA SilentlyContinue
    Write-SR "Setting DiagTrack startup to Disabled" 'SVC'
    Set-Service  DiagTrack -StartupType Disabled -EA SilentlyContinue
    Set-RegLogged "HKLM:\SOFTWARE\Policies\Microsoft\Windows\DataCollection" "AllowTelemetry" 0
    Write-SR "Telemetry disabled and DiagTrack service stopped" 'OK'
    return { Set-Service DiagTrack -StartupType Automatic -EA SilentlyContinue; Start-Service DiagTrack -EA SilentlyContinue; Remove-ItemProperty "HKLM:\SOFTWARE\Policies\Microsoft\Windows\DataCollection" -Name "AllowTelemetry" -EA SilentlyContinue }
}
function Apply-ActivityHistory {
    Write-SR "Disabling Activity History / Timeline" 'APPLY'
    $p = "HKLM:\SOFTWARE\Policies\Microsoft\Windows\System"
    $o = @{ a=(Get-RegVal $p "EnableActivityFeed"); b=(Get-RegVal $p "PublishUserActivities"); c=(Get-RegVal $p "UploadUserActivities") }
    Set-RegLogged $p "EnableActivityFeed"    0
    Set-RegLogged $p "PublishUserActivities" 0
    Set-RegLogged $p "UploadUserActivities"  0
    Write-SR "Activity History tracking disabled" 'OK'
    $va = [int](Coalesce $o.a 1); $vb = [int](Coalesce $o.b 1); $vc = [int](Coalesce $o.c 1)
    return [scriptblock]::Create("Set-Reg '$p' 'EnableActivityFeed' $va; Set-Reg '$p' 'PublishUserActivities' $vb; Set-Reg '$p' 'UploadUserActivities' $vc")
}
function Apply-Location {
    Write-SR "Disabling Location Tracking" 'APPLY'
    $o = Get-RegVal "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\CapabilityAccessManager\ConsentStore\location" "Value"
    Write-SR "Current location consent: $(Coalesce $o 'Allow')" 'INFO'
    Set-RegLogged "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\CapabilityAccessManager\ConsentStore\location" "Value" "Deny" "String"
    Write-SR "Location access set to Deny for all apps" 'OK'
    $v = Coalesce $o 'Allow'
    return [scriptblock]::Create("Set-Reg 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\CapabilityAccessManager\ConsentStore\location' 'Value' '$(ConvertTo-SqValue $v)' 'String'")
}
function Apply-Ads {
    Write-SR "Disabling Personalized Advertising ID" 'APPLY'
    $hklmPath = "HKLM:\SOFTWARE\Policies\Microsoft\Windows\AdvertisingInfo"
    $oHklm = Get-RegVal $hklmPath "DisabledByGroupPolicy"
    Set-RegLogged "HKCU:\Software\Microsoft\Windows\CurrentVersion\AdvertisingInfo" "Enabled" 0
    Set-RegLogged $hklmPath "DisabledByGroupPolicy" 1
    Write-SR "Advertising ID disabled" 'OK'
    if ($null -eq $oHklm) {
        return { Set-Reg "HKCU:\Software\Microsoft\Windows\CurrentVersion\AdvertisingInfo" "Enabled" 1; Remove-ItemProperty "HKLM:\SOFTWARE\Policies\Microsoft\Windows\AdvertisingInfo" -Name "DisabledByGroupPolicy" -EA SilentlyContinue }
    }
    $vh = [int]$oHklm
    return [scriptblock]::Create("Set-Reg 'HKCU:\Software\Microsoft\Windows\CurrentVersion\AdvertisingInfo' 'Enabled' 1; Set-Reg '$hklmPath' 'DisabledByGroupPolicy' $vh")
}
