    return { Remove-ItemProperty "HKCU:\Software\Policies\Microsoft\Windows\WindowsCopilot" -Name "TurnOffWindowsCopilot" -EA SilentlyContinue; Remove-ItemProperty "HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsCopilot" -Name "TurnOffWindowsCopilot" -EA SilentlyContinue }
}
function Apply-Widgets {
    Write-SR "Removing Widgets / News Feed from taskbar" 'APPLY'
    $hkcu = "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced"
    $hklm = "HKLM:\SOFTWARE\Policies\Microsoft\Dsh"
    $o = Get-RegVal $hkcu "TaskbarDa"
    $v = [int](Coalesce $o 1)
    try {
        Set-RegLogged $hkcu "TaskbarDa" 0
        Write-SR "Widgets hidden via user registry" 'OK'
        return [scriptblock]::Create("Set-Reg '$hkcu' 'TaskbarDa' $v")
    } catch {
        Write-SR "User registry write blocked - falling back to policy path" 'WARN'
        try {
            Set-RegLogged $hklm "AllowNewsAndInterests" 0
            Write-SR "Widgets disabled via HKLM policy" 'OK'
            return [scriptblock]::Create("Remove-ItemProperty '$hklm' -Name 'AllowNewsAndInterests' -EA SilentlyContinue")
        } catch {
            # Recent Windows 11 builds protect this setting (the UCPD driver blocks other programs from changing it). Nothing was changed, so this is a skip, not a failure.
            Write-SR "Windows protects the Widgets setting on this PC, so StreamReady left it unchanged. You can turn Widgets off in Settings > Personalisation > Taskbar." 'WARN'
            $script:ScoreSkipReason = 'Protected'
            return $null
        }
    }
}
