function Apply-OneDrive {
    Write-SR "Uninstalling OneDrive" 'APPLY'
    Write-SR "Killing OneDrive process" 'SVC'
    Stop-Process -Name OneDrive -Force -EA SilentlyContinue
    $ran = $false
    $usedPaths = [System.Collections.Generic.List[string]]::new()
    foreach ($path in @("$env:SystemRoot\SysWOW64\OneDriveSetup.exe", "$env:SystemRoot\System32\OneDriveSetup.exe")) {
        if (Test-Path $path) {
            Write-SR "Running OneDriveSetup.exe /uninstall ($([System.IO.Path]::GetDirectoryName($path) | Split-Path -Leaf))" 'INFO'
            try { Start-Process $path -ArgumentList "/uninstall" -Wait } catch { Write-SR "Uninstall step failed: $_" 'WARN' }
            $usedPaths.Add($path)
            $ran = $true
        }
    }
    if (-not $ran) { Write-SR "OneDriveSetup.exe not found - OneDrive may already be removed or installed via Store" 'INFO' }
    else { Write-SR "OneDrive uninstalled - your OneDrive folder and files remain untouched" 'OK' }

    if ($usedPaths.Count -eq 0) {
        return { Write-SR "Nothing to undo - OneDriveSetup.exe wasn't found when this tweak ran" 'UNDO' }
    }
    # The setup stub (OneDriveSetup.exe) stays on disk after /uninstall - rerunning it
    # with no arguments triggers a normal reinstall for the current user, same as
    # Microsoft's own documented reinstall step.
    $undoPath = $usedPaths[0]
    return [scriptblock]::Create("Start-Process '$undoPath' -EA SilentlyContinue; Write-SR 'UNDO: OneDrive reinstall triggered - it will finish setting up in the background' 'UNDO'")
}
function Apply-EdgeDebloat {
    Write-SR "Applying Edge Debloat policies (telemetry, sidebar, shopping)" 'APPLY'
    $p = "HKLM:\SOFTWARE\Policies\Microsoft\Edge"
    $keyExisted = Test-Path $p
    if (-not $keyExisted) {
        Write-SR "Creating Edge policy key" 'REG'
        New-Item -Path $p -Force | Out-Null
    }
    # Back up only the 3 values this tweak touches, so undo restores exactly those -
    # not the whole policy key, which may hold other admin-set Edge policies.
    $prevSidebar  = Get-RegVal $p "HubsSidebarEnabled"
    $prevShopping = Get-RegVal $p "MicrosoftEdgeShoppingAssistantEnabled"
    $prevDiag     = Get-RegVal $p "DiagnosticData"

    Write-SR "Set  $p\HubsSidebarEnabled  =  0" 'REG'
    Set-ItemProperty $p -Name "HubsSidebarEnabled"                    -Value 0 -Type DWord
    Write-SR "Set  $p\MicrosoftEdgeShoppingAssistantEnabled  =  0" 'REG'
    Set-ItemProperty $p -Name "MicrosoftEdgeShoppingAssistantEnabled" -Value 0 -Type DWord
    Write-SR "Set  $p\DiagnosticData  =  0" 'REG'
    Set-ItemProperty $p -Name "DiagnosticData"                        -Value 0 -Type DWord
    Write-SR "Edge sidebar, shopping assistant, and diagnostic data disabled" 'OK'

    return {
        if ($keyExisted) {
            foreach ($entry in @(
                @{ Name = 'HubsSidebarEnabled'; Prev = $prevSidebar },
                @{ Name = 'MicrosoftEdgeShoppingAssistantEnabled'; Prev = $prevShopping },
                @{ Name = 'DiagnosticData'; Prev = $prevDiag }
            )) {
                if ($null -eq $entry.Prev) {
                    Remove-ItemProperty $p -Name $entry.Name -EA SilentlyContinue
                } else {
                    Set-Reg $p $entry.Name $entry.Prev
                }
            }
        } else {
            Remove-Item $p -Recurse -Force -EA SilentlyContinue
        }
        Write-SR "UNDO: Edge debloat values restored to their prior state" 'UNDO'
    }.GetNewClosure()
}
