    Write-SR "Hibernation disabled - hiberfil.sys removed, disk space freed" 'OK'
    return { powercfg -h on | Out-Null }
}
function Apply-DisableFastStartup {
    # Independent of "Disable Hibernation" above - Fast Startup hibernates the kernel
    # session on shutdown (not full hibernation), and is a well-known source of dual-boot
    # filesystem corruption and driver/BIOS state not fully resetting between boots.
    # Disabling it keeps hibernate/sleep working normally; only cold shutdown changes.
    Write-SR "Disabling Fast Startup (Hiberboot)" 'APPLY'
    $path = "HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Power"
    $old = Get-RegVal $path "HiberbootEnabled"
    Set-RegLogged $path "HiberbootEnabled" 0
    Write-SR "Fast Startup disabled - full shutdown/boot each time (helps dual-boot and BIOS/driver reliability)" 'OK'
    $oldVal = if ($null -ne $old) { [int]$old } else { 1 }
    return [scriptblock]::Create("Set-Reg '$path' 'HiberbootEnabled' $oldVal 'DWord'; Write-SR 'UNDO: Fast Startup restored' 'UNDO'")
}
