function Apply-DisableIPv6 {
    Write-SR "Disabling IPv6 on all active network adapters" 'APPLY'
    # Capture which adapters actually had IPv6 enabled beforehand, so undo only
    # re-enables those - previously undo blindly re-enabled IPv6 on every adapter,
    # including ones where a user had intentionally disabled it before ever using
    # this tweak.
    $wasEnabled = @(Get-NetAdapterFrozen | ForEach-Object {
        $binding = Get-NetAdapterBinding -Name $_.Name -ComponentID ms_tcpip6 -EA SilentlyContinue
        if ($binding -and $binding.Enabled) { $_.Name }
    })
    Get-NetAdapterFrozen | ForEach-Object {
        Write-SR "Disabling IPv6 binding on adapter: $($_.Name)" 'NET'
        Disable-NetAdapterBinding -Name $_.Name -ComponentID ms_tcpip6 -EA SilentlyContinue
    }
    Write-SR "IPv6 disabled on all adapters" 'OK'
    $escapedNames   = $wasEnabled | ForEach-Object { $_ -replace $script:SqPattern, '$&$&' }
    $namesToRestore = $escapedNames -join "','"
    return [scriptblock]::Create("`$restoreNames = @('$namesToRestore') | Where-Object { `$_ }; foreach (`$n in `$restoreNames) { Enable-NetAdapterBinding -Name `$n -ComponentID ms_tcpip6 -EA SilentlyContinue }")
}
