function Apply-ServicesManual {
    Write-SR "Setting non-essential services to Manual startup" 'APPLY'
    $services = @(
        "DiagTrack","dmwappushservice","SysMain","WSearch",
        "XblAuthManager","XblGameSave","XboxGipSvc","XboxNetApiSvc",
        "MapsBroker","lfsvc","WerSvc","Fax","RetailDemo"
    )
    $prior = @{}
    foreach ($svc in $services) {
        try {
            $svcObj = Get-Service $svc -EA SilentlyContinue
            if ($svcObj) { $prior[$svc] = @{ StartType = $svcObj.StartType; WasRunning = ($svcObj.Status -eq 'Running') } }
            Set-Service $svc -StartupType Manual -EA SilentlyContinue
            Stop-Service $svc -Force -EA SilentlyContinue
            Write-SR "Set to Manual: $svc" 'SVC'
        } catch { Write-SR "Could not change: $svc - $_" 'WARN' }
    }
    Write-SR "Non-essential services set to Manual" 'OK'
    return {
        foreach ($svc in $prior.Keys) {
            $info = $prior[$svc]
            try {
                Set-Service $svc -StartupType $info.StartType -EA SilentlyContinue
                if ($info.WasRunning) { Start-Service $svc -EA SilentlyContinue }
                Write-SR "Restored: $svc -> $($info.StartType)$(if ($info.WasRunning) { ' (started)' })" 'UNDO'
            } catch { Write-SR "Could not restore: $svc - $_" 'WARN' }
        }
    }.GetNewClosure()
}
