function Apply-MMCSS {
    Write-SR "Boosting MMCSS System Responsiveness (10% background CPU reserve)" 'APPLY'
    $p = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile"
