    Write-SR "NetworkThrottlingIndex set to 0xFFFFFFFF - throttle disabled" 'OK'
    $v = [long](Coalesce $o 10)
    return [scriptblock]::Create("Set-Reg 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile' 'NetworkThrottlingIndex' $v")
}
function Apply-NaglesAlgo {
    Write-SR "Disabling Nagle's Algorithm on active network adapters" 'APPLY'
    $target = Get-ActiveAdapterIfacePath
    if ($target) {
        $oldAck   = Get-RegVal $target 'TcpAckFrequency'
        $oldDelay = Get-RegVal $target 'TCPNoDelay'
        $oldTicks = Get-RegVal $target 'TcpDelAckTicks'
        Write-SR "Applying Nagle disable to: $target" 'NET'
        Set-RegLogged $target "TcpAckFrequency" 1
        Set-RegLogged $target "TCPNoDelay"      1
        Set-RegLogged $target "TcpDelAckTicks"  0
        Write-SR "Nagle's Algorithm disabled on active adapter" 'OK'
        # Restore whatever was actually there before, matching the pattern used by
        # Apply-TcpGameTweaks - previously this unconditionally deleted the values on
        # undo, destroying any pre-existing customization instead of restoring it.
        if ($null -eq $oldAck -and $null -eq $oldDelay -and $null -eq $oldTicks) {
            return [scriptblock]::Create("Remove-ItemProperty '$target' -Name 'TcpAckFrequency' -EA SilentlyContinue; Remove-ItemProperty '$target' -Name 'TCPNoDelay' -EA SilentlyContinue; Remove-ItemProperty '$target' -Name 'TcpDelAckTicks' -EA SilentlyContinue")
        }
        $vAck   = if ($null -ne $oldAck)   { [int]$oldAck   } else { 0 }
        $vDelay = if ($null -ne $oldDelay) { [int]$oldDelay } else { 0 }
        $vTicks = if ($null -ne $oldTicks) { [int]$oldTicks } else { 2 }
        return [scriptblock]::Create("Set-Reg '$target' 'TcpAckFrequency' $vAck 'DWord'; Set-Reg '$target' 'TCPNoDelay' $vDelay 'DWord'; Set-Reg '$target' 'TcpDelAckTicks' $vTicks 'DWord'")
    } else {
        Write-SR "Could not locate active adapter interface key - skipping" 'WARN'
        $script:ScoreSkipReason = 'MissingTarget'; return $null
    }
}
