function Apply-AutoHDR {
    Write-SR "Enabling Auto HDR" 'APPLY'
    $p = "HKCU:\Software\Microsoft\DirectX\UserGpuPreferences"
    $o = Get-RegVal $p "DirectXUserGlobalSettings"
    $cur = if ($o) { $o } else { "" }
    $new = if ($cur -match "AutoHDREnable=") { $cur -replace "AutoHDREnable=\d+","AutoHDREnable=1" } else { $cur + "AutoHDREnable=1;" }
    Set-RegLogged $p "DirectXUserGlobalSettings" $new "String"
    Write-SR "Auto HDR enabled in DirectX user GPU preferences" 'OK'
    # Surgical undo: read current value at undo time, only patch AutoHDREnable back
    if ($cur -match "AutoHDREnable=(\d+)") {
        $orig = $Matches[1]
        return [scriptblock]::Create("`$v=(Get-ItemProperty 'HKCU:\Software\Microsoft\DirectX\UserGpuPreferences' -Name 'DirectXUserGlobalSettings' -EA SilentlyContinue).DirectXUserGlobalSettings; `$v=`$v -replace 'AutoHDREnable=\d+','AutoHDREnable=$orig'; Set-Reg 'HKCU:\Software\Microsoft\DirectX\UserGpuPreferences' 'DirectXUserGlobalSettings' `$v 'String'")
    } else {
        return [scriptblock]::Create("`$v=(Get-ItemProperty 'HKCU:\Software\Microsoft\DirectX\UserGpuPreferences' -Name 'DirectXUserGlobalSettings' -EA SilentlyContinue).DirectXUserGlobalSettings; `$v=`$v -replace 'AutoHDREnable=\d+;?',''; Set-Reg 'HKCU:\Software\Microsoft\DirectX\UserGpuPreferences' 'DirectXUserGlobalSettings' `$v 'String'")
    }
}
