function Apply-PhotoViewer {
    Write-SR "Restoring classic Windows Photo Viewer as default image viewer" 'APPLY'
    $exts = @(".jpg",".jpeg",".png",".bmp",".gif",".tiff",".tif")
    $p2 = "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\FileExts"

    # Capture prior state for every key/value this tweak is about to touch, so undo
    # restores exactly what was there before instead of just telling the user to
    # redo it manually via Settings.
    $prevClasses = @{}
    $prevUserChoice = @{}
    foreach ($ext in $exts) {
        $p = "HKCU:\Software\Classes\$ext"
        $prevClasses[$ext] = @{ Existed = (Test-Path $p); Value = (Get-RegVal $p "(default)") }
        if (-not (Test-Path $p)) { New-Item $p -Force | Out-Null }
        Set-ItemProperty $p -Name "(default)" -Value "PhotoViewer.FileAssoc.Tiff" -Type String
        Write-SR "Set Photo Viewer for: $ext" 'REG'
    }
    foreach ($ext in $exts) {
        $ep = "$p2\$ext\UserChoice"
        $prevUserChoice[$ext] = @{ Existed = (Test-Path $ep); ProgId = (Get-RegVal $ep "ProgId"); Hash = (Get-RegVal $ep "Hash") }
        if (-not (Test-Path $ep)) { New-Item $ep -Force | Out-Null }
        Set-ItemProperty $ep -Name "ProgId" -Value "PhotoViewer.FileAssoc.Tiff" -Type String
        Set-ItemProperty $ep -Name "Hash"   -Value "" -Type String -EA SilentlyContinue
        Write-SR "UserChoice set for: $ext" 'REG'
    }
    Write-SR "Classic Photo Viewer restored for common image types" 'OK'

    return {
        foreach ($ext in $exts) {
            $p  = "HKCU:\Software\Classes\$ext"
            $ep = "$p2\$ext\UserChoice"
            $prevC = $prevClasses[$ext]
            $prevU = $prevUserChoice[$ext]
            if ($prevC.Existed) {
                if ($null -ne $prevC.Value) { Set-Reg $p "(default)" $prevC.Value "String" }
            } else {
                Remove-Item $p -Recurse -Force -EA SilentlyContinue
            }
            if ($prevU.Existed) {
                if ($null -ne $prevU.ProgId) { Set-Reg $ep "ProgId" $prevU.ProgId "String" }
                if ($null -ne $prevU.Hash)   { Set-Reg $ep "Hash"   $prevU.Hash   "String" }
            } else {
                Remove-Item $ep -Recurse -Force -EA SilentlyContinue
            }
        }
        Write-SR "UNDO: Photo Viewer file associations restored to their prior state (sign out and back in if Explorer doesn't pick it up immediately)" 'UNDO'
    }.GetNewClosure()
}
