#endregion Network Tweaks

#region GPU Tweaks

# ── Shared helper: ensure HKU path for logged-in user ──────────────────────────
function Get-HkuPath { param([string]$SubPath)
    if (-not $script:LogonUserSID) {
        Write-SR "Cannot write to user registry - logged-in user not resolved" 'WARN'
        return $null
    }
    return "HKU:\$($script:LogonUserSID)\$SubPath"
}

# ── Nvidia tweaks ───────────────────────────────────────────────────────────────
function Apply-GpuNvULL {
    Write-SR "Nvidia: Enabling Ultra Low Latency Mode (PreRenderedFrames=1)" 'APPLY'
    $path = Get-HkuPath "SOFTWARE\NVIDIA Corporation\Global\NvTweak"
    if (-not $path) { $script:ScoreSkipReason = 'MissingTarget'; return $null }
    if (-not (Test-Path $path)) { New-Item $path -Force | Out-Null }
    $old = (Get-ItemProperty $path -Name PreRenderedFrames -EA SilentlyContinue).PreRenderedFrames
    Set-RegLogged $path "PreRenderedFrames" 1
    Write-SR "Nvidia ULL Mode enabled" 'OK'
    $oldVal = if ($null -ne $old) { $old } else { 3 }
    return [scriptblock]::Create("Set-ItemProperty '$path' -Name PreRenderedFrames -Value $oldVal -Type DWord; Write-SR 'UNDO: Nvidia ULL Mode reverted' 'UNDO'")
}

function Apply-GpuNvFHBC {
    if (-not $script:GpuSubkey) { Write-SR "GPU subkey not found - skipping FHBC" 'WARN'; return $null }
    if (-not (Test-UndoGpuTarget)) { Write-SR 'The graphics driver entry is not the one that was saved, so nothing was changed.' 'FAIL'; throw 'The graphics driver entry is not the one that was saved, so nothing was changed.' }
    Write-SR "Nvidia: Disabling Frame Buffer Hibernation (FHBC)" 'APPLY'
    $old = (Get-ItemProperty $script:GpuSubkey -Name DisableFBHibernation -EA SilentlyContinue).DisableFBHibernation
    Set-RegLogged $script:GpuSubkey "DisableFBHibernation" 1
    Write-SR "Nvidia FHBC disabled" 'OK'
    $oldVal = if ($null -ne $old) { $old } else { 0 }
    $sub = $script:GpuSubkey
    return [scriptblock]::Create("Set-ItemProperty '$sub' -Name DisableFBHibernation -Value $oldVal -Type DWord; Write-SR 'UNDO: Nvidia FHBC reverted' 'UNDO'")
}

function Apply-GpuNvPState {
    if (-not $script:GpuSubkey) { Write-SR "GPU subkey not found - skipping P-State" 'WARN'; return $null }
    if (-not (Test-UndoGpuTarget)) { Write-SR 'The graphics driver entry is not the one that was saved, so nothing was changed.' 'FAIL'; throw 'The graphics driver entry is not the one that was saved, so nothing was changed.' }
    Write-SR "Nvidia: Forcing P0 P-State (max clocks always)" 'APPLY'
    $old = (Get-ItemProperty $script:GpuSubkey -Name PerfLevelSrc -EA SilentlyContinue).PerfLevelSrc
    Set-RegLogged $script:GpuSubkey "PerfLevelSrc" 0x00002222
    Write-SR "Nvidia P-State locked to P0" 'OK'
    $oldVal = if ($null -ne $old) { $old } else { 0x00003322 }
    $sub = $script:GpuSubkey
    return [scriptblock]::Create("Set-ItemProperty '$sub' -Name PerfLevelSrc -Value $oldVal -Type DWord; Write-SR 'UNDO: Nvidia P-State reverted' 'UNDO'")
}

function Apply-GpuNvTexFilter {
    if (-not $script:GpuSubkey) { Write-SR "GPU subkey not found - skipping TexFilter" 'WARN'; return $null }
    if (-not (Test-UndoGpuTarget)) { Write-SR 'The graphics driver entry is not the one that was saved, so nothing was changed.' 'FAIL'; throw 'The graphics driver entry is not the one that was saved, so nothing was changed.' }
    Write-SR "Nvidia: Setting texture filtering to High Performance" 'APPLY'
    $old = (Get-ItemProperty $script:GpuSubkey -Name TextureFilteringMode -EA SilentlyContinue).TextureFilteringMode
    Set-RegLogged $script:GpuSubkey "TextureFilteringMode" 0x00000020
    Write-SR "Nvidia texture filtering set to High Performance" 'OK'
    $oldVal = if ($null -ne $old) { $old } else { 0x00000001 }
    $sub = $script:GpuSubkey
    return [scriptblock]::Create("Set-ItemProperty '$sub' -Name TextureFilteringMode -Value $oldVal -Type DWord; Write-SR 'UNDO: Nvidia texture filter reverted' 'UNDO'")
}

function Apply-GpuNvTelemetry {
    Write-SR "Nvidia: Disabling NvTelemetryContainer service" 'APPLY'
    try {
        $svc = Get-Service NvTelemetryContainer -EA SilentlyContinue
        if ($svc) {
            $oldStartStr = $svc.StartType.ToString()
            Stop-Service NvTelemetryContainer -Force -EA SilentlyContinue
            Set-Service  NvTelemetryContainer -StartupType Disabled
            Write-SR "NvTelemetryContainer stopped and disabled" 'OK'
            return [scriptblock]::Create("Set-Service NvTelemetryContainer -StartupType $oldStartStr -EA SilentlyContinue; Write-SR 'UNDO: NvTelemetryContainer restored' 'UNDO'")
        } else { Write-SR "NvTelemetryContainer service not found (may not be installed)" 'INFO'; return $null }
    } catch { Write-SR "Nvidia telemetry disable failed: $_" 'FAIL'; return $null }
}

function Apply-GpuNvThreadedOpt {
    Write-SR "Nvidia: Forcing Threaded Optimization on" 'APPLY'
    $path = "HKLM:\SOFTWARE\NVIDIA Corporation\Global\NVTweak"
    if (-not (Test-Path $path)) { New-Item $path -Force | Out-Null }
    $old = (Get-ItemProperty $path -Name ThreadedOptimization -EA SilentlyContinue).ThreadedOptimization
    Set-RegLogged $path "ThreadedOptimization" 1
    Write-SR "Nvidia Threaded Optimization set to On" 'OK'
    $oldVal = if ($null -ne $old) { $old } else { 0 }
    return [scriptblock]::Create("Set-ItemProperty 'HKLM:\SOFTWARE\NVIDIA Corporation\Global\NVTweak' -Name ThreadedOptimization -Value $oldVal -Type DWord; Write-SR 'UNDO: Nvidia Threaded Optimization reverted' 'UNDO'")
}

# ---- Folder StreamReady uses for anything it later runs with administrator rights ----
# (downloaded tools and the helper scripts that scheduled tasks start). Only Administrators and
# SYSTEM can change it, so a normal (non-elevated) program running as the same user cannot swap a
# file for its own code. Anything unexpected inside it (a link, a file owned by someone else, a file
# anyone but Administrators/SYSTEM can write) means the whole folder is wiped and rebuilt. Returns
# $true only when the finished folder has been read back and confirmed safe.

# Rights that let an account change a file or folder (including the raw "generic" bits).
$script:SrWriteMask = [int](
    [System.Security.AccessControl.FileSystemRights]::WriteData -bor
    [System.Security.AccessControl.FileSystemRights]::AppendData -bor
    [System.Security.AccessControl.FileSystemRights]::Delete -bor
    [System.Security.AccessControl.FileSystemRights]::DeleteSubdirectoriesAndFiles -bor
    [System.Security.AccessControl.FileSystemRights]::ChangePermissions -bor
    [System.Security.AccessControl.FileSystemRights]::TakeOwnership -bor
    [System.Security.AccessControl.FileSystemRights]::WriteAttributes -bor
    [System.Security.AccessControl.FileSystemRights]::WriteExtendedAttributes -bor
    0x10000000 -bor 0x40000000)

# True when one item (file or folder) is owned by Administrators/SYSTEM and no other account can write to it.
function Test-SrItemLocked {
    param([Parameter(Mandatory)][string]$LiteralPath, [switch]$RequireProtected)
    $trusted = @('S-1-5-32-544', 'S-1-5-18')
    $acl      = Get-Acl -LiteralPath $LiteralPath -ErrorAction Stop
    $ownerSid = $acl.GetOwner([System.Security.Principal.SecurityIdentifier]).Value
    if ($ownerSid -notin $trusted) { return $false }
    if ($RequireProtected -and -not $acl.AreAccessRulesProtected) { return $false }
    foreach ($rule in $acl.Access) {
        if ($rule.AccessControlType -ne 'Allow') { continue }
        $sid = $rule.IdentityReference.Translate([System.Security.Principal.SecurityIdentifier]).Value
        if ($sid -in $trusted) { continue }
        if (([int]$rule.FileSystemRights) -band $script:SrWriteMask) { return $false }
    }
    return $true
}

function Test-SrTreeTrusted {
    param([Parameter(Mandatory)][string]$Path)
    $item = Get-Item -LiteralPath $Path -Force -ErrorAction Stop
    if (-not $item.PSIsContainer) { return $false }
    if ($item.Attributes -band [System.IO.FileAttributes]::ReparsePoint) { return $false }
    if (-not (Test-SrItemLocked -LiteralPath $Path -RequireProtected)) { return $false }
    foreach ($child in (Get-ChildItem -LiteralPath $Path -Recurse -Force -ErrorAction Stop)) {
        if ($child.Attributes -band [System.IO.FileAttributes]::ReparsePoint) { return $false }
        if (-not (Test-SrItemLocked -LiteralPath $child.FullName)) { return $false }
    }
    return $true
}

function Initialize-ProtectedDir {
    param([Parameter(Mandatory)][string]$Path)
    try {
        $sidAdmins = New-Object System.Security.Principal.SecurityIdentifier('S-1-5-32-544')
        $sidSystem = New-Object System.Security.Principal.SecurityIdentifier('S-1-5-18')
        $sidUsers  = New-Object System.Security.Principal.SecurityIdentifier('S-1-5-32-545')

        # Reuse only if the folder AND everything inside it passes the checks.
        $trustedExisting = $false
        if (Test-Path -LiteralPath $Path) {
            try { $trustedExisting = Test-SrTreeTrusted -Path $Path } catch { $trustedExisting = $false }
            if ($trustedExisting) { return $true }

            if ((Test-Path -LiteralPath (Join-Path $Path 'undo')) -or (Test-Path -LiteralPath (Join-Path $Path 'undo-files'))) {
                Write-SR "Folder $Path holds saved originals and is not locked down; it was NOT cleared. Fix its permissions by hand." 'WARN'
                return $false
            }
            Write-SR "Folder $Path is not locked down - clearing it before use" 'WARN'
            $existing = Get-Item -LiteralPath $Path -Force -ErrorAction Stop
            if ($existing.PSIsContainer) {
                & cmd.exe /c "rmdir /s /q `"$Path`"" | Out-Null      # removes links without following them
            } else {
                Remove-Item -LiteralPath $Path -Force -ErrorAction Stop
            }
            if (Test-Path -LiteralPath $Path) { throw "could not clear $Path" }
        }

        $parent = Split-Path $Path -Parent
        if (-not (Test-Path -LiteralPath $parent)) { New-Item -ItemType Directory -Path $parent -ErrorAction Stop | Out-Null }

        # Build the intended security descriptor, create the folder with it in one step, then read it back.
        $inh   = [System.Security.AccessControl.InheritanceFlags]'ContainerInherit,ObjectInherit'
        $none  = [System.Security.AccessControl.PropagationFlags]::None
        $allow = [System.Security.AccessControl.AccessControlType]::Allow
        $sec   = New-Object System.Security.AccessControl.DirectorySecurity
        $sec.SetOwner($sidAdmins)
        $sec.SetAccessRuleProtection($true, $false)
        foreach ($sid in @($sidAdmins, $sidSystem)) {
            $sec.AddAccessRule((New-Object System.Security.AccessControl.FileSystemAccessRule($sid, 'FullControl', $inh, $none, $allow)))
        }
        $sec.AddAccessRule((New-Object System.Security.AccessControl.FileSystemAccessRule($sidUsers, 'ReadAndExecute', $inh, $none, $allow)))

        if (Test-Path -LiteralPath $Path) { throw "$Path appeared while it was being created - refusing to use it" }
        try {
            [void][System.IO.Directory]::CreateDirectory($Path, $sec)
        } catch {
            # Fallback: plain create (it fails if the name already exists), then apply the descriptor.
            New-Item -ItemType Directory -Path $Path -ErrorAction Stop | Out-Null
            Set-Acl -LiteralPath $Path -AclObject $sec -ErrorAction Stop
        }

        # Read back: not a link, owner and permissions exactly as intended.
        $made = Get-Item -LiteralPath $Path -Force -ErrorAction Stop
        if (-not $made.PSIsContainer -or ($made.Attributes -band [System.IO.FileAttributes]::ReparsePoint)) { throw "$Path is not a plain folder" }
        if (-not (Test-SrItemLocked -LiteralPath $Path -RequireProtected)) { throw "permissions on $Path are not as intended" }
        $acl = Get-Acl -LiteralPath $Path -ErrorAction Stop
        $haveAdmins = $false
        foreach ($rule in $acl.Access) {
            if ($rule.AccessControlType -eq 'Allow' -and $rule.IdentityReference.Translate([System.Security.Principal.SecurityIdentifier]).Value -eq $sidAdmins.Value -and
                ($rule.FileSystemRights -band [System.Security.AccessControl.FileSystemRights]::FullControl) -eq [System.Security.AccessControl.FileSystemRights]::FullControl) { $haveAdmins = $true }
        }
        if (-not $haveAdmins) { throw "Administrators lack full control of $Path" }
        return $true
    } catch {
        Write-SR "Could not create a protected folder at ${Path}: $_" 'FAIL'
        return $false
    }
}

# ---- Quote escaping for generated undo scripts ----
# Windows PowerShell treats U+0027 and U+2018 to U+201B all as single-quote characters, so all five
# are doubled. A doubled quote inside a '...' string is a literal quote, so the value stays plain text.
$script:SqPattern = "['" + [char]0x2018 + [char]0x2019 + [char]0x201A + [char]0x201B + "]"
function ConvertTo-SqValue {
    param($Value)
    return [regex]::Replace("$Value", $script:SqPattern, '$&$&')
}

# ---- Defender exclusion path check ----
# True only for a real, ordinary folder on a local drive that is safe to hand to Defender as an exclusion:
# no links anywhere in the path, not a drive root, not Windows / Program Files / ProgramData / any user
# profile (or anything inside the ones that are not normal game locations).
function Test-SafeExclusionPath {
    param([string]$Path)
    try {
        if ([string]::IsNullOrWhiteSpace($Path)) { return $false }
        if ($Path -notmatch '^[A-Za-z]:\\') { return $false }
        if (-not (Test-Path -LiteralPath $Path -PathType Container)) { return $false }
        $full = [System.IO.Path]::GetFullPath($Path).TrimEnd('\')
        if ($full.Length -le 3) { return $false }

        # No link at the folder or at any ancestor.
        $cur = $full
        while ($cur -and $cur.Length -gt 3) {
            $it = Get-Item -LiteralPath $cur -Force -ErrorAction Stop
            if ($it.Attributes -band [System.IO.FileAttributes]::ReparsePoint) { return $false }
            $cur = Split-Path $cur -Parent
        }

        $sys = $env:SystemDrive
        $exactBlocked = @($env:ProgramFiles, ${env:ProgramFiles(x86)}) | Where-Object { $_ } | ForEach-Object { $_.TrimEnd('\') }
        if ($exactBlocked -contains $full) { return $false }

        # Not inside any of these (checked on whole path components, not text prefixes).
        $usersRoot = if ($env:USERPROFILE) { (Split-Path $env:USERPROFILE -Parent) } else { "$sys\Users" }
        $blockedTrees = @($env:SystemRoot, $env:ProgramData, $usersRoot, $env:USERPROFILE, $env:APPDATA, $env:LOCALAPPDATA, $env:TEMP, "$sys\Users") |
            Where-Object { $_ } | ForEach-Object { $_.TrimEnd('\') } | Select-Object -Unique
        foreach ($b in $blockedTrees) {
            if ($full.Equals($b, [System.StringComparison]::OrdinalIgnoreCase)) { return $false }
            if ($full.StartsWith($b + '\', [System.StringComparison]::OrdinalIgnoreCase)) { return $false }
        }
        return $true
    } catch { return $false }
}

# ---- Downloaded tool cache: remember exactly what the user approved ----
# After a download passes the checks, the exe's SHA-256 is recorded inside the protected folder. On later
# runs the tool is used only if the file still matches that record and its signature is still not broken.
function Save-ToolRecord {
    param([Parameter(Mandatory)][string]$Dir, [Parameter(Mandatory)][string]$ExePath)
    $rel  = $ExePath.Substring($Dir.TrimEnd('\').Length + 1)
    $hash = (Get-FileHash -LiteralPath $ExePath -Algorithm SHA256 -ErrorAction Stop).Hash
    Set-Content -LiteralPath (Join-Path $Dir 'installed.sha256') -Value @($rel, $hash) -Encoding ASCII -ErrorAction Stop
}
function Get-TrustedToolExe {
    param([Parameter(Mandatory)][string]$Dir)
    try {
        $rec = Join-Path $Dir 'installed.sha256'
        if (-not (Test-Path -LiteralPath $rec)) { return $null }
        $lines = @(Get-Content -LiteralPath $rec -ErrorAction Stop)
        if ($lines.Count -lt 2) { return $null }
        $exe = Join-Path $Dir $lines[0]
        if (-not (Test-Path -LiteralPath $exe -PathType Leaf)) { return $null }
        if ((Get-FileHash -LiteralPath $exe -Algorithm SHA256 -ErrorAction Stop).Hash -ne $lines[1].Trim()) { return $null }
        $sig = Get-AuthenticodeSignature -FilePath $exe -ErrorAction Stop
        if ($sig.Status -ne 'Valid' -and $sig.Status -ne 'NotSigned') { return $null }
        return $exe
    } catch { return $null }
}

# Verifies the Authenticode signature of a downloaded third-party executable before it's
# ever elevated and run. These tools are fetched from their latest upstream GitHub release
# automatically, so a fixed SHA-256 pin would break on every new upstream release -
# signature validation is the check that still works against a moving target. When a
# binary isn't signed at all (common for small indie tools), it can't be silently trusted
# either: warn clearly and require the user to explicitly confirm before it ever runs.
function Confirm-DownloadedExeTrust {
    param([Parameter(Mandatory)][string]$Path, [Parameter(Mandatory)][string]$FriendlyName)
    $sig = try { Get-AuthenticodeSignature -FilePath $Path -EA Stop } catch { $null }
    if ($sig -and $sig.Status -eq 'Valid') {
        $signer = if ($sig.SignerCertificate) { $sig.SignerCertificate.Subject } else { 'unknown' }
        Write-SR "$FriendlyName signature verified - signed by: $signer" 'OK'
        return $true
    }
    if (-not $sig -or $sig.Status -ne 'NotSigned') {
        $bad = if ($sig) { $sig.Status } else { 'could not be checked' }
        Write-SR "$FriendlyName failed the signature check ($bad) - refusing to run it" 'FAIL'
        [System.Windows.MessageBox]::Show("$FriendlyName did not pass its digital signature check ($bad), so StreamReady will not run it.", "StreamReady - Download Blocked", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Error) | Out-Null
        return $false
    }
    $statusText = $sig.Status
    Write-SR "$FriendlyName is not Authenticode-signed (status: $statusText) - publisher could not be automatically verified" 'WARN'
    $msg = "$FriendlyName was downloaded from its official GitHub releases page but is not digitally signed, so StreamReady can't automatically verify its publisher.`n`nOnly continue if you trust this source. Run it anyway?"
    $result = [System.Windows.MessageBox]::Show($msg, "StreamReady - Unverified Download", [System.Windows.MessageBoxButton]::YesNo, [System.Windows.MessageBoxImage]::Warning)
    return ($result -eq [System.Windows.MessageBoxResult]::Yes)
}

function Get-NpiExe {
    # Download is unpacked in a staging folder and checked first; only a tool that passed is moved into the
    # cache, and the cache is trusted only while the file still matches what was approved.
    $toolRoot = "$env:ProgramData\StreamReady-OSS"
    $npiDir   = "$toolRoot\tools\NPI"
    if (-not (Initialize-ProtectedDir $toolRoot)) { return $null }
    try {
        if (-not (Test-Path -LiteralPath $npiDir)) { New-Item $npiDir -ItemType Directory -ErrorAction Stop | Out-Null }
        $cached = Get-TrustedToolExe $npiDir
        if ($cached) { Write-SR "NPI found in local cache (unchanged since you approved it)" 'INFO'; return $cached }
        if (@(Get-ChildItem -LiteralPath $npiDir -Force -ErrorAction Stop).Count -gt 0) {
            Write-SR "Cached NPI copy could not be verified - clearing it and downloading again" 'WARN'
            Get-ChildItem -LiteralPath $npiDir -Force | Remove-Item -Recurse -Force -ErrorAction Stop
        }
    } catch { Write-SR "NPI cache check failed: $_" 'FAIL'; return $null }

    Write-SR "Nvidia Profile Inspector not found - downloading latest release from GitHub..." 'NET'
    $stage = "$toolRoot\staging\npi-$([guid]::NewGuid().ToString('N'))"
    try {
        $release = Invoke-RestMethod -Uri "https://api.github.com/repos/Orbmu2k/nvidiaProfileInspector/releases/latest" -UseBasicParsing -EA Stop
        $asset   = $release.assets | Where-Object { $_.name -like "*.zip" } | Select-Object -First 1
        if (-not $asset) { Write-SR "No zip asset found in latest NPI release" 'FAIL'; return $null }

        New-Item $stage -ItemType Directory -Force -ErrorAction Stop | Out-Null
        $zipPath = "$stage\npi.zip"
        $xDir    = "$stage\x"
        Write-SR "Downloading $($asset.name) ($([math]::Round($asset.size/1MB,1)) MB)..." 'NET'
        Invoke-WebRequest -Uri $asset.browser_download_url -OutFile $zipPath -UseBasicParsing -EA Stop
        Expand-Archive -Path $zipPath -DestinationPath $xDir -Force -ErrorAction Stop

        $exe = Get-ChildItem $xDir -Filter "nvidiaProfileInspector.exe" -Recurse -ErrorAction Stop | Select-Object -First 1
        if (-not $exe) { Write-SR "nvidiaProfileInspector.exe not found after extraction" 'FAIL'; return $null }
        $rel = $exe.FullName.Substring($xDir.Length + 1)

        if (-not (Confirm-DownloadedExeTrust -Path $exe.FullName -FriendlyName "Nvidia Profile Inspector")) {
            Write-SR "NPI run cancelled (signature check not accepted)" 'FAIL'
            return $null
        }
        foreach ($child in (Get-ChildItem -LiteralPath $xDir -Force)) {
            Move-Item -LiteralPath $child.FullName -Destination $npiDir -Force -ErrorAction Stop
        }
        $final = Join-Path $npiDir $rel
        Save-ToolRecord -Dir $npiDir -ExePath $final
        Write-SR "NPI installed to: $final" 'OK'
        return $final
    } catch {
        Write-SR "NPI download failed: $_" 'FAIL'
        # A half-finished install must never be reused on the next run.
        try { Get-ChildItem -LiteralPath $npiDir -Force -ErrorAction SilentlyContinue | Remove-Item -Recurse -Force -ErrorAction SilentlyContinue } catch {}
        return $null
    } finally {
        Remove-Item -LiteralPath $stage -Recurse -Force -ErrorAction SilentlyContinue
    }
}
function Apply-GpuNvNpiProfile {
    # Resolve the StreamReady root - works for .ps1 (src/ subfolder), compiled .exe (root), or any working dir
    $scriptDir = if ($PSCommandPath) { Split-Path $PSCommandPath -Parent }
                 elseif ($PSScriptRoot) { $PSScriptRoot }
                 else { Split-Path -Parent ([System.Diagnostics.Process]::GetCurrentProcess().MainModule.FileName) }
    $srRoot    = if ($scriptDir -and (Split-Path $scriptDir -Leaf) -eq 'src') { Split-Path $scriptDir -Parent } else { $scriptDir }
    $nipPath = Join-Path $srRoot "StreamReady_Tweaks.nip"
    if (-not (Test-Path $nipPath)) {
        Write-SR "StreamReady_Tweaks.nip not found - expected at: $nipPath" 'WARN'; return $null
    }

    $npiExe = Get-NpiExe
    if (-not $npiExe) { Write-SR "Could not locate or install Nvidia Profile Inspector" 'FAIL'; return $null }

    Write-SR "Applying NPI profile: StreamReady_Tweaks.nip" 'APPLY'
    Write-SR "  Settings: VSync Force Off · FRL Low Latency · Preferred Refresh = Highest · Texture Filter opts" 'INFO'
    Write-SR "Nvidia Profile Inspector will ask Replace or Merge - choose MERGE to keep your existing per-game profiles. Replace resets them to only what's in this file." 'WARN'
    try {
        # No -WindowStyle Hidden: NPI's Import Profiles dialog needs to be visible since
        # it always requires a manual Replace/Merge choice - there is no silent-merge CLI flag.
        $proc = Start-Process -FilePath $npiExe -ArgumentList "`"$nipPath`"" -Wait -PassThru -EA Stop
        if ($proc.ExitCode -eq 0) {
            Write-SR "NPI profile applied successfully" 'OK'
        } else {
            Write-SR "NPI exited with code $($proc.ExitCode) - profile may not have applied fully" 'WARN'
        }
    } catch {
        Write-SR "NPI profile apply failed: $_" 'FAIL'; return $null
    }

    return [scriptblock]::Create("Write-SR 'UNDO: NPI profile - to revert open Nvidia Control Panel > Manage 3D Settings > Restore Defaults' 'UNDO'")
}

# ── AMD tweaks ──────────────────────────────────────────────────────────────────
function Apply-GpuAmdAntiLag {
    if (-not $script:GpuSubkey) { Write-SR "GPU subkey not found - skipping Anti-Lag+" 'WARN'; $script:ScoreSkipReason = 'MissingTarget'; return $null }
    if (-not (Test-UndoGpuTarget)) { Write-SR 'The graphics driver entry is not the one that was saved, so nothing was changed.' 'FAIL'; throw 'The graphics driver entry is not the one that was saved, so nothing was changed.' }
    Write-SR "AMD: Enabling Anti-Lag+" 'APPLY'
    $old = (Get-ItemProperty $script:GpuSubkey -Name KMD_EnableAntiLag -EA SilentlyContinue).KMD_EnableAntiLag
    Set-RegLogged $script:GpuSubkey "KMD_EnableAntiLag" 1
    Write-SR "AMD Anti-Lag+ enabled" 'OK'
    $oldVal = if ($null -ne $old) { $old } else { 0 }
    $sub = $script:GpuSubkey
    return [scriptblock]::Create("Set-ItemProperty '$sub' -Name KMD_EnableAntiLag -Value $oldVal -Type DWord; Write-SR 'UNDO: AMD Anti-Lag+ reverted' 'UNDO'")
}

function Apply-GpuAmdULPS {
    if (-not $script:GpuSubkey) { Write-SR "GPU subkey not found - skipping ULPS" 'WARN'; return $null }
    if (-not (Test-UndoGpuTarget)) { Write-SR 'The graphics driver entry is not the one that was saved, so nothing was changed.' 'FAIL'; throw 'The graphics driver entry is not the one that was saved, so nothing was changed.' }
    Write-SR "AMD: Disabling ULPS (Ultra Low Power State)" 'APPLY'
    $old = (Get-ItemProperty $script:GpuSubkey -Name EnableUlps -EA SilentlyContinue).EnableUlps
    Set-RegLogged $script:GpuSubkey "EnableUlps" 0
    Write-SR "AMD ULPS disabled - stutter eliminated" 'OK'
    $oldVal = if ($null -ne $old) { $old } else { 1 }
    $sub = $script:GpuSubkey
    return [scriptblock]::Create("Set-ItemProperty '$sub' -Name EnableUlps -Value $oldVal -Type DWord; Write-SR 'UNDO: AMD ULPS reverted' 'UNDO'")
}

function Apply-GpuAmdRSR {
    $path = Get-HkuPath "SOFTWARE\AMD\CN"
    if (-not $path) { return $null }
    Write-SR "AMD: Enabling Image Sharpening (RSR)" 'APPLY'
    if (-not (Test-Path $path)) { New-Item $path -Force | Out-Null }
    $old = (Get-ItemProperty $path -Name RSR_ENABLED -EA SilentlyContinue).RSR_ENABLED
    Set-RegLogged $path "RSR_ENABLED" 1
    Write-SR "AMD RSR sharpening enabled" 'OK'
    $oldVal = if ($null -ne $old) { $old } else { 0 }
    return [scriptblock]::Create("Set-ItemProperty '$path' -Name RSR_ENABLED -Value $oldVal -Type DWord; Write-SR 'UNDO: AMD RSR reverted' 'UNDO'")
}

function Apply-GpuAmdTDR {
    Write-SR "AMD: Setting TDR delay to 60s" 'APPLY'
    $path = "HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers"
    $old  = (Get-ItemProperty $path -Name TdrDelay -EA SilentlyContinue).TdrDelay
    Set-RegLogged $path "TdrDelay" 60
    Write-SR "TDR delay set to 60s" 'OK'
    $oldVal = if ($null -ne $old) { $old } else { 2 }
    return [scriptblock]::Create("Set-ItemProperty '$path' -Name TdrDelay -Value $oldVal -Type DWord; Write-SR 'UNDO: TDR delay reverted' 'UNDO'")
}

function Apply-GpuAmdTexFilter {
    if (-not $script:GpuSubkey) { Write-SR "GPU subkey not found - skipping AMD TexFilter" 'WARN'; return $null }
    if (-not (Test-UndoGpuTarget)) { Write-SR 'The graphics driver entry is not the one that was saved, so nothing was changed.' 'FAIL'; throw 'The graphics driver entry is not the one that was saved, so nothing was changed.' }
    Write-SR "AMD: Setting texture filtering to Performance" 'APPLY'
    $old = (Get-ItemProperty $script:GpuSubkey -Name TextureFilteringQuality -EA SilentlyContinue).TextureFilteringQuality
    Set-RegLogged $script:GpuSubkey "TextureFilteringQuality" 1
    Write-SR "AMD texture filtering set to Performance" 'OK'
    $oldVal = if ($null -ne $old) { $old } else { 0 }
    $sub = $script:GpuSubkey
    return [scriptblock]::Create("Set-ItemProperty '$sub' -Name TextureFilteringQuality -Value $oldVal -Type DWord; Write-SR 'UNDO: AMD texture filter reverted' 'UNDO'")
}

function Apply-GpuAmdTelemetry {
    Write-SR "AMD: Disabling AMD Crash Defender (amdfendr) service" 'APPLY'
    try {
        $svc = Get-Service amdfendr -EA SilentlyContinue
        if ($svc) {
            $oldStartStr = $svc.StartType.ToString()
            Stop-Service amdfendr -Force -EA SilentlyContinue
            Set-Service  amdfendr -StartupType Disabled
            Write-SR "AMD Crash Defender stopped and disabled" 'OK'
            return [scriptblock]::Create("Set-Service amdfendr -StartupType $oldStartStr -EA SilentlyContinue; Write-SR 'UNDO: AMD Crash Defender restored' 'UNDO'")
        } else { Write-SR "amdfendr service not found (AMD Crash Defender not installed)" 'INFO'; return $null }
    } catch { Write-SR "AMD telemetry disable failed: $_" 'FAIL'; return $null }
}

#endregion GPU Tweaks

#region Timer Resolution

function Apply-TimerResolution {
    Write-SR "Setting Windows Timer Resolution to 0.5ms" 'APPLY'

    $helperDir  = "$env:ProgramData\StreamReady-OSS"
    $helperPath = "$helperDir\SetTimerRes.ps1"
    if (-not (Initialize-ProtectedDir $helperDir)) { Write-SR "Could not create a protected folder for the timer helper" 'FAIL'; return $null }

    # Write the at-logon helper script (runs in its own fresh powershell.exe process).
    # NtSetTimerResolution's boost only lasts for the calling process's lifetime, so
    # this script must stay resident (not set-and-exit, as it did before) for the
    # 0.5ms resolution to actually hold - that's what lets it keep working
    # independent of StreamReady.exe staying open, and reapply automatically after
    # every restart via the AtLogOn scheduled task trigger below.
    $helperScript = @'
Add-Type @"
using System;
using System.Runtime.InteropServices;
public class NtTimer {
    [DllImport("ntdll.dll")] public static extern int NtSetTimerResolution(int DesiredResolution, bool SetResolution, out int CurrentResolution);
}
"@
$c = 0
[NtTimer]::NtSetTimerResolution(5000, $true, [ref]$c)
while ($true) { Start-Sleep -Seconds 3600 }
'@
    Set-Content -Path $helperPath -Value $helperScript -Encoding UTF8

    # Resolve logged-in user for task principal (use startup-resolved value)
    $logonUser = $script:LogonUser
    if (-not $logonUser) {
        Write-SR "Could not resolve logged-in user - timer task not registered" 'WARN'
        return { Undo-TimerResolution }
    }

    # Register scheduled task to run helper at every logon. No ExecutionTimeLimit
    # (New-TimeSpan -Hours 0 means "unlimited" to Task Scheduler) - a time limit would
    # kill the resident helper after that long, defeating the whole point of it
    # staying resident.
    $action   = New-ScheduledTaskAction -Execute "$env:SystemRoot\System32\WindowsPowerShell\v1.0\powershell.exe" `
                    -Argument "-NoProfile -NonInteractive -WindowStyle Hidden -ExecutionPolicy Bypass -File `"$helperPath`""
    $trigger  = New-ScheduledTaskTrigger -AtLogOn
    $settings = New-ScheduledTaskSettingsSet -ExecutionTimeLimit (New-TimeSpan -Hours 0) -MultipleInstances IgnoreNew
    $principal = New-ScheduledTaskPrincipal -UserId $logonUser -RunLevel Highest
    Unregister-ScheduledTask -TaskName "StreamReady_TimerRes" -Confirm:$false -ErrorAction SilentlyContinue
    Register-ScheduledTask -TaskName "StreamReady_TimerRes" -Action $action `
        -Trigger $trigger -Settings $settings -Principal $principal -Force -ErrorAction Stop | Out-Null

    # Start the resident helper right now too, so the boost is active for the current
    # session immediately - held by this standalone helper process, not by StreamReady
    # itself, so it keeps working even after StreamReady is closed.
    $timerStarted = $true
    try { Start-ScheduledTask -TaskName "StreamReady_TimerRes" -ErrorAction Stop } catch { $timerStarted = $false; Write-SR "Timer task registered but could not be started now: $_ (it will start at next logon)" 'WARN' }
    if ($timerStarted) { Write-SR "Timer resolution set to 0.5ms via a resident background helper - active now and at every logon, independent of StreamReady staying open" 'OK' }
    else { Write-SR "Timer helper registered but NOT running yet - the 0.5ms boost starts at next logon" 'WARN' }

    return { Undo-TimerResolution }
}

function Undo-TimerResolution {
    Write-SR "Reverting Timer Resolution to Windows default (15.6ms)" 'UNDO'
    Unregister-ScheduledTask -TaskName "StreamReady_TimerRes" -Confirm:$false -ErrorAction SilentlyContinue
    # Unregistering only removes the task definition - it does not stop the resident
    # helper that's already running (same class of bug already fixed for the CPU Core
    # Optimizer's watcher). Find and kill the actual running instance directly.
    try {
        Get-CimInstance Win32_Process -EA SilentlyContinue |
            Where-Object { $_.CommandLine -like '*StreamReady-OSS\SetTimerRes.ps1*' } |
            ForEach-Object { try { Stop-Process -Id $_.ProcessId -Force -EA SilentlyContinue } catch {} }
    } catch {}
    Remove-Item "$env:ProgramData\StreamReady-OSS\SetTimerRes.ps1" -Force -ErrorAction SilentlyContinue
    Write-SR "Timer resolution restored to default" 'OK'
}

#endregion Timer Resolution

#region Additional Gaming Tweaks

function Apply-DefenderExclusions {
    Write-SR "Adding Windows Defender game folder exclusions" 'APPLY'

    # Check Defender is available
    try { $mpPref = Get-MpPreference -EA Stop } catch {
        Write-SR "Windows Defender not available - skipping exclusions" 'WARN'
        return $null
    }

    # Gather candidate folders: common launcher locations, then Steam libraries from libraryfolders.vdf.
    $raw = [System.Collections.Generic.List[string]]::new()
    $candidates = @(
        "${env:ProgramFiles(x86)}\Steam",
        "${env:ProgramFiles}\Steam",
        "${env:ProgramFiles}\Epic Games",
        "${env:ProgramFiles(x86)}\Epic Games",
        "${env:ProgramFiles}\Riot Games",
        "${env:ProgramFiles(x86)}\Riot Games",
        "${env:ProgramFiles}\EA Games",
        "${env:ProgramFiles}\Electronic Arts",
        "${env:ProgramFiles(x86)}\Electronic Arts",
        "${env:ProgramFiles(x86)}\Battle.net",
        "${env:ProgramFiles}\Battle.net",
        "${env:ProgramFiles(x86)}\Activision"
    )
    foreach ($p in $candidates) { if (Test-Path -LiteralPath $p) { $raw.Add($p) } }

    $steamInst = "${env:ProgramFiles(x86)}\Steam","${env:ProgramFiles}\Steam" |
        Where-Object { Test-Path "$_\steamapps\libraryfolders.vdf" } | Select-Object -First 1
    if ($steamInst) {
        $vdf = Get-Content "$steamInst\steamapps\libraryfolders.vdf" -Raw -EA SilentlyContinue
        $vdf | Select-String '"path"\s+"([^"]+)"' -AllMatches | ForEach-Object {
            $_.Matches | ForEach-Object {
                $lib = $_.Groups[1].Value -replace '\\\\','\'
                # The VDF is only a hint: a real library has a steamapps folder.
                if (Test-Path -LiteralPath "$lib\steamapps" -PathType Container) { $raw.Add($lib) }
                else { Write-SR "Skipped Steam library path (no steamapps folder): $lib" 'WARN' }
            }
        }
    }

    # Keep only safe, distinct folders (a folder already in the list is not reported again).
    $paths = [System.Collections.Generic.List[string]]::new()
    foreach ($p in $raw) {
        $full = try { [System.IO.Path]::GetFullPath($p).TrimEnd('\') } catch { $p }
        if ($paths -contains $full) { continue }
        if (-not (Test-SafeExclusionPath $full)) { Write-SR "Skipped (not a normal game folder): $full" 'WARN'; continue }
        $paths.Add($full)
    }
    $planned = Undo-Engine-PlanValues 'ChkDefenderExclusions' 'PreferenceSet' 'Members'
    if ($null -ne $planned) { $keepP = [System.Collections.Generic.List[string]]::new(); foreach ($pp in $paths) { if ($planned -contains $pp) { $keepP.Add($pp) } else { Write-SR "Skipped (not in the saved plan): $pp" 'WARN' } }; $paths = $keepP }
    if ($paths.Count -eq 0) {
        Write-SR "No game launcher folders found - nothing to exclude" 'WARN'
        return $null
    }

    $added = [System.Collections.Generic.List[string]]::new()
    foreach ($p in $paths) {
        # Check again right before applying, in case the folder changed since the first look.
        if (-not (Test-SafeExclusionPath $p)) { Write-SR "Skipped (changed since checked): $p" 'WARN'; continue }
        try {
            Add-MpPreference -ExclusionPath $p -ErrorAction Stop
            $added.Add($p)
            Write-SR "Exclusion path: $p" 'OK'
        } catch { Write-SR "Could not add exclusion for ${p}: $_" 'WARN' }
    }
    if ($added.Count -eq 0) { return $null }

    # Escape embedded single quotes (all five kinds) before wrapping in '...' so a folder name
    # cannot break out of the generated undo script.
    $pathList = ($added | ForEach-Object { "'" + (ConvertTo-SqValue $_) + "'" }) -join ','
    return [scriptblock]::Create("
        @($pathList) | ForEach-Object { Remove-MpPreference -ExclusionPath `$_ -EA SilentlyContinue }
        Write-SR 'UNDO: Defender game exclusions removed' 'UNDO'
    ")
}
function Apply-VisualPerf {
    Write-SR "Setting Visual Effects to Performance mode" 'APPLY'

    $vfxPath = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\VisualEffects'
    $advPath = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced'

    if (-not (Test-Path $vfxPath)) { New-Item $vfxPath -Force | Out-Null }

    $oldVfx  = (Get-ItemProperty $vfxPath -Name VisualFXSetting  -EA SilentlyContinue).VisualFXSetting
    $oldAnim = (Get-ItemProperty $advPath  -Name TaskbarAnimations -EA SilentlyContinue).TaskbarAnimations

    Set-RegLogged $vfxPath "VisualFXSetting"   2
    Set-RegLogged $advPath "TaskbarAnimations" 0
    Write-SR "VisualFXSetting=2 (Performance), TaskbarAnimations=0" 'OK'

    $oldV = if ($null -ne $oldVfx)  { $oldVfx  } else { 0 }
    $oldA = if ($null -ne $oldAnim) { $oldAnim } else { 1 }
    return [scriptblock]::Create("
        Set-ItemProperty 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\VisualEffects' -Name VisualFXSetting   -Value $oldV -Type DWord
        Set-ItemProperty 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced'      -Name TaskbarAnimations -Value $oldA -Type DWord
        Write-SR 'UNDO: Visual Effects restored' 'UNDO'
    ")
}

function Apply-NtfsOpt {
    Write-SR "Applying NTFS optimisations" 'APPLY'

    $fsPath = 'HKLM:\SYSTEM\CurrentControlSet\Control\FileSystem'
    $oldLast = (Get-ItemProperty $fsPath -Name NtfsDisableLastAccessUpdate    -EA SilentlyContinue).NtfsDisableLastAccessUpdate
    $old83   = (Get-ItemProperty $fsPath -Name NtfsDisable8dot3NameCreation   -EA SilentlyContinue).NtfsDisable8dot3NameCreation

    Set-RegLogged $fsPath "NtfsDisableLastAccessUpdate"  1
    Set-RegLogged $fsPath "NtfsDisable8dot3NameCreation" 1
    Write-SR "NTFS last-access timestamps disabled" 'OK'
    Write-SR "NTFS 8.3 filename generation disabled" 'OK'

    $oldLastVal = if ($null -ne $oldLast) { $oldLast } else { 0 }
    $old83Val   = if ($null -ne $old83)   { $old83   } else { 0 }
    return [scriptblock]::Create("
        Set-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\FileSystem' -Name NtfsDisableLastAccessUpdate  -Value $oldLastVal -Type DWord
        Set-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Control\FileSystem' -Name NtfsDisable8dot3NameCreation -Value $old83Val   -Type DWord
        Write-SR 'UNDO: NTFS settings restored' 'UNDO'
    ")
}

function Apply-SysMainDisable {
    Write-SR "Disabling SysMain (Superfetch)" 'APPLY'

    $svc = Get-Service -Name SysMain -EA SilentlyContinue
    if (-not $svc) {
        Write-SR "SysMain service not found" 'WARN'
        return $null
    }

    $oldStart = $svc.StartType.ToString()
    Stop-Service SysMain -Force -EA SilentlyContinue
    Set-Service  SysMain -StartupType Disabled
    Write-SR "SysMain stopped and set to Disabled" 'SVC'

    return [scriptblock]::Create("
        Set-Service  SysMain -StartupType $oldStart
        Start-Service SysMain -EA SilentlyContinue
        Write-SR 'UNDO: SysMain restored to $oldStart' 'UNDO'
    ")
}

function Apply-AudioLatency {
    Write-SR "Boosting MMCSS Pro Audio priority" 'APPLY'

    $proPath = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Pro Audio'
    if (-not (Test-Path $proPath)) { New-Item $proPath -Force | Out-Null }

    $oldPri  = (Get-ItemProperty $proPath -Name 'Priority'             -EA SilentlyContinue).Priority
    $oldGpu  = (Get-ItemProperty $proPath -Name 'GPU Priority'         -EA SilentlyContinue).'GPU Priority'
    $oldScat = (Get-ItemProperty $proPath -Name 'Scheduling Category'  -EA SilentlyContinue).'Scheduling Category'
    $oldSfio = (Get-ItemProperty $proPath -Name 'SFIO Priority'        -EA SilentlyContinue).'SFIO Priority'

    Set-RegLogged $proPath 'Priority'            1      'DWord'
    Set-RegLogged $proPath 'GPU Priority'        8      'DWord'
    Set-RegLogged $proPath 'Scheduling Category' 'High' 'String'
    Set-RegLogged $proPath 'SFIO Priority'       'High' 'String'
    Write-SR "Pro Audio: Priority=1 (realtime), GPU Priority=8, Scheduling=High" 'OK'

    $oldPriVal  = if ($null -ne $oldPri)  { $oldPri  } else { 2 }
    $oldGpuVal  = if ($null -ne $oldGpu)  { $oldGpu  } else { 2 }
    $oldScatVal = if ($oldScat)           { $oldScat  } else { 'Medium' }
    $oldSfioVal = if ($oldSfio)           { $oldSfio  } else { 'Normal' }
    return [scriptblock]::Create("
        Set-ItemProperty '$proPath' -Name 'Priority'            -Value $oldPriVal  -Type DWord
        Set-ItemProperty '$proPath' -Name 'GPU Priority'        -Value $oldGpuVal  -Type DWord
        Set-ItemProperty '$proPath' -Name 'Scheduling Category' -Value '$oldScatVal' -Type String
        Set-ItemProperty '$proPath' -Name 'SFIO Priority'       -Value '$oldSfioVal' -Type String
        Write-SR 'UNDO: Pro Audio MMCSS settings restored' 'UNDO'
    ")
}

function Apply-UsbSuspend {
    Write-SR "Disabling USB Selective Suspend" 'APPLY'

    # Registry - plan-independent, always applies
    $usbPath = 'HKLM:\SYSTEM\CurrentControlSet\Services\USB'
    $oldReg = $null
    if (Test-Path $usbPath) {
        $oldReg = (Get-ItemProperty $usbPath -Name DisableSelectiveSuspend -EA SilentlyContinue).DisableSelectiveSuspend
        Set-RegLogged $usbPath "DisableSelectiveSuspend" 1
    }

    # Power scheme - disable for both AC and DC on the active scheme
    $schemeRaw = (& powercfg /getactivescheme 2>$null)
    $schemeGuid = if ($schemeRaw -match 'GUID: ([a-f0-9\-]+)') { $Matches[1] } else { 'SCHEME_CURRENT' }
    & powercfg /setacvalueindex $schemeGuid 2a737441-1930-4402-8d77-b2bebba308a3 48e6b7a6-50f5-4782-a5d4-53bb8f07e226 0 2>$null
    & powercfg /setdcvalueindex $schemeGuid 2a737441-1930-4402-8d77-b2bebba308a3 48e6b7a6-50f5-4782-a5d4-53bb8f07e226 0 2>$null
    & powercfg /setactive $schemeGuid 2>$null
    Write-SR "USB Selective Suspend disabled in active power scheme" 'OK'

    $oldRegVal = if ($null -ne $oldReg) { $oldReg } else { 0 }
    return [scriptblock]::Create("
        Set-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Services\USB' -Name DisableSelectiveSuspend -Value $oldRegVal -Type DWord -EA SilentlyContinue
        & powercfg /setacvalueindex $schemeGuid 2a737441-1930-4402-8d77-b2bebba308a3 48e6b7a6-50f5-4782-a5d4-53bb8f07e226 1 2>`$null
        & powercfg /setdcvalueindex $schemeGuid 2a737441-1930-4402-8d77-b2bebba308a3 48e6b7a6-50f5-4782-a5d4-53bb8f07e226 1 2>`$null
        & powercfg /setactive $schemeGuid 2>`$null
        Write-SR 'UNDO: USB Selective Suspend restored' 'UNDO'
    ")
}

function Apply-NicLatency {
    Write-SR "Applying NIC latency tuning (LSO + RSC off)" 'APPLY'

    $nics = Get-NetAdapterFrozen | Where-Object {
        $_.Status -eq 'Up' -and
        $_.InterfaceDescription -notmatch 'Loopback|Virtual|Hyper-V|Wi-Fi Direct|Bluetooth|TAP|VPN|Miniport'
    }
    if (-not $nics) {
        Write-SR "No active physical NICs found" 'WARN'
        return $null
    }

    $undoParts = [System.Collections.Generic.List[string]]::new()

    foreach ($nic in $nics) {
        $n = $nic.Name -replace $script:SqPattern, '$&$&'

        try { Disable-NetAdapterLso -Name $nic.Name -EA Stop; Write-SR "LSO disabled: $n" 'OK'
              $undoParts.Add("Enable-NetAdapterLso -Name '$n' -EA SilentlyContinue") }
        catch { Write-SR "LSO not supported on $n" 'WARN' }

        try { Disable-NetAdapterRsc -Name $nic.Name -EA Stop; Write-SR "RSC disabled: $n" 'OK'
              $undoParts.Add("Enable-NetAdapterRsc -Name '$n' -EA SilentlyContinue") }
        catch { Write-SR "RSC not supported on $n" 'WARN' }

    }

    if ($undoParts.Count -eq 0) { return $null }
    return [scriptblock]::Create(($undoParts -join "`n") + "`nWrite-SR 'UNDO: NIC latency settings restored' 'UNDO'")
}

#endregion Additional Gaming Tweaks

#region Extended Gaming Tweaks
function Apply-BcdTweaks {
    Write-SR "BCD Performance Tweaks" 'SECTION'
    bcdedit /set disabledynamictick yes 2>$null | Out-Null
    if ($LASTEXITCODE -ne 0) { Write-SR "disabledynamictick failed (exit $LASTEXITCODE) - may require Secure Boot off or elevated bcdedit" 'WARN' }
    else { Write-SR "disabledynamictick = yes" 'OK' }
    bcdedit /set tscsyncpolicy enhanced 2>$null | Out-Null
    if ($LASTEXITCODE -ne 0) { Write-SR "tscsyncpolicy failed (exit $LASTEXITCODE)" 'WARN' }
    else { Write-SR "tscsyncpolicy = enhanced" 'OK' }
    Write-SR "BCD tweaks applied - reboot to take full effect" 'OK'
    return [scriptblock]::Create("bcdedit /deletevalue disabledynamictick 2>`$null | Out-Null; bcdedit /deletevalue tscsyncpolicy 2>`$null | Out-Null; Write-SR 'UNDO: BCD tweaks removed - reboot to restore defaults' 'UNDO'")
}

function Apply-CoreParkingDisable {
    Write-SR "Disabling CPU Core Parking" 'SECTION'
    # 54533251-82be-4824-96c1-47b60b740d00 = Processor power management
    # 0cc5b647-c1df-4637-891a-dec35c318583 = Processor performance core parking min cores
    $base = "HKLM:\SYSTEM\CurrentControlSet\Control\Power\PowerSettings\54533251-82be-4824-96c1-47b60b740d00\0cc5b647-c1df-4637-891a-dec35c318583"
    $oldMax = Get-RegVal $base 'ValueMax'
    Set-Reg $base 'ValueMax' 0 'DWord'
    Write-SR "Core parking ValueMax set to 0 (all cores always active)" 'OK'
    $oldAcVal = 0
    # Falls back to the 'SCHEME_CURRENT' alias (always valid) if the GUID parse below
    # fails before assigning it, so the undo scriptblock never interpolates a blank
    # GUID into its powercfg calls.
    $planGuid = 'SCHEME_CURRENT'
    try {
        $planGuid = (powercfg /getactivescheme) -replace '.*GUID: ([a-f0-9-]+).*','$1'
        $queryOut = powercfg /query $planGuid 54533251-82be-4824-96c1-47b60b740d00 0cc5b647-c1df-4637-891a-dec35c318583 2>$null
        $acLine = $queryOut | Where-Object { $_ -match 'Current AC Power Setting Index' } | Select-Object -First 1
        if ($acLine -match '0x([0-9a-fA-F]+)') { $oldAcVal = [int]('0x' + $Matches[1]) }
        powercfg /setacvalueindex $planGuid 54533251-82be-4824-96c1-47b60b740d00 0cc5b647-c1df-4637-891a-dec35c318583 100 2>$null | Out-Null
        powercfg /setactive $planGuid 2>$null | Out-Null
        Write-SR "Core parking min cores set to 100% via powercfg" 'OK'
    } catch { Write-SR "powercfg core park step skipped: $_" 'WARN' }
    $oldMaxVal = if ($null -ne $oldMax) { [int]$oldMax } else { 100 }
    return [scriptblock]::Create("
        Set-Reg '$base' 'ValueMax' $oldMaxVal 'DWord'
        try { powercfg /setacvalueindex $planGuid 54533251-82be-4824-96c1-47b60b740d00 0cc5b647-c1df-4637-891a-dec35c318583 $oldAcVal | Out-Null; powercfg /setactive $planGuid | Out-Null } catch {}
        Write-SR 'UNDO: CPU core parking settings restored' 'UNDO'
    ")
}

function Apply-Win32Priority {
    Write-SR "Win32 Priority Separation" 'SECTION'
    $old = Get-RegVal "HKLM:\SYSTEM\CurrentControlSet\Control\PriorityControl" 'Win32PrioritySeparation'
    # 0x26 = 38 decimal: short fixed quantum, foreground 3x boost
    Set-Reg "HKLM:\SYSTEM\CurrentControlSet\Control\PriorityControl" 'Win32PrioritySeparation' 38 'DWord'
    Write-SR "Win32PrioritySeparation = 38 (0x26) - max foreground CPU time" 'OK'
    $oldVal = if ($null -ne $old) { [int]$old } else { 2 }
    return [scriptblock]::Create("Set-Reg 'HKLM:\SYSTEM\CurrentControlSet\Control\PriorityControl' 'Win32PrioritySeparation' $oldVal 'DWord'; Write-SR 'UNDO: Win32PrioritySeparation restored to $oldVal' 'UNDO'")
}

function Apply-VbsDisable {
    Write-SR "Disabling VBS / Hyper-V" 'SECTION'
    $oldVbs   = Get-RegVal "HKLM:\SYSTEM\CurrentControlSet\Control\DeviceGuard" 'EnableVirtualizationBasedSecurity'
    $oldPlat  = Get-RegVal "HKLM:\SYSTEM\CurrentControlSet\Control\DeviceGuard" 'RequirePlatformSecurityFeatures'
    $oldHvci  = Get-RegVal "HKLM:\SYSTEM\CurrentControlSet\Control\DeviceGuard\Scenarios\HypervisorEnforcedCodeIntegrity" 'Enabled'
    # Check Hyper-V launch type before disabling (fast bcdedit check - avoids slow DISM)
    $bcdOut = bcdedit /enum '{current}' 2>$null
    $hvLaunchLine = $bcdOut | Where-Object { $_ -match 'hypervisorlaunchtype' } | Select-Object -First 1
    $hvWasEnabled = $hvLaunchLine -and ($hvLaunchLine -notmatch '\bOff\b')
    # Disable Virtualization Based Security
    Set-Reg "HKLM:\SYSTEM\CurrentControlSet\Control\DeviceGuard" 'EnableVirtualizationBasedSecurity' 0 'DWord'
    Set-Reg "HKLM:\SYSTEM\CurrentControlSet\Control\DeviceGuard" 'RequirePlatformSecurityFeatures'   0 'DWord'
    Set-Reg "HKLM:\SYSTEM\CurrentControlSet\Control\DeviceGuard\Scenarios\HypervisorEnforcedCodeIntegrity" 'Enabled' 0 'DWord'
    Write-SR "VBS registry keys disabled" 'OK'
    # Disable Hyper-V boot components
    bcdedit /set hypervisorlaunchtype off 2>$null | Out-Null
    if ($LASTEXITCODE -ne 0) { Write-SR "bcdedit hypervisor step failed (exit $LASTEXITCODE)" 'WARN' }
    else { Write-SR "hypervisorlaunchtype = off" 'OK' }
    try {
        Disable-WindowsOptionalFeature -Online -FeatureName "Microsoft-Hyper-V-All" -NoRestart -EA SilentlyContinue | Out-Null
        Write-SR "Hyper-V Windows feature disabled" 'OK'
    } catch { Write-SR "Hyper-V feature disable skipped: $_" 'WARN' }
    Write-SR "Reboot required for VBS/Hyper-V changes to take effect" 'WARN'
    $vOldVbs  = if ($null -ne $oldVbs)  { [int]$oldVbs  } else { 0 }
    $vOldPlat = if ($null -ne $oldPlat) { [int]$oldPlat } else { 0 }
    $vOldHvci = if ($null -ne $oldHvci) { [int]$oldHvci } else { 0 }
    $hvUndo   = if ($hvWasEnabled) { "Enable-WindowsOptionalFeature -Online -FeatureName 'Microsoft-Hyper-V-All' -NoRestart -EA SilentlyContinue | Out-Null" } else { '' }
    return [scriptblock]::Create("
        Set-Reg 'HKLM:\SYSTEM\CurrentControlSet\Control\DeviceGuard' 'EnableVirtualizationBasedSecurity' $vOldVbs 'DWord'
        Set-Reg 'HKLM:\SYSTEM\CurrentControlSet\Control\DeviceGuard' 'RequirePlatformSecurityFeatures' $vOldPlat 'DWord'
        Set-Reg 'HKLM:\SYSTEM\CurrentControlSet\Control\DeviceGuard\Scenarios\HypervisorEnforcedCodeIntegrity' 'Enabled' $vOldHvci 'DWord'
        bcdedit /set hypervisorlaunchtype auto 2>`$null | Out-Null
        $hvUndo
        Write-SR 'UNDO: VBS/Hyper-V settings restored - reboot required' 'UNDO'
    ")
}

function Apply-AhciLpmOff {
    Write-SR "Disabling AHCI Link Power Management" 'SECTION'
    $base     = "HKLM:\SYSTEM\CurrentControlSet\Services\storahci\Parameters\Device"
    $ahciPath = "HKLM:\SYSTEM\CurrentControlSet\Services\storahci"
    $oldTxn  = Get-RegVal $base 'TxnMaxPayload'
    $oldLpm  = Get-RegVal $base 'LPM Management Enabled'
    $oldIdle = Get-RegVal $ahciPath 'EnableIdlePowerManagement'
    if (-not (Test-Path $base)) { New-Item $base -Force | Out-Null }
    Set-Reg $base 'TxnMaxPayload'          0  'DWord'
    Set-Reg $base 'LPM Management Enabled' 0  'DWord'
    Set-Reg $ahciPath 'EnableIdlePowerManagement' 0 'DWord'
    Write-SR "AHCI LPM disabled - storage devices stay at full power" 'OK'
    $vTxn  = if ($null -ne $oldTxn)  { [int]$oldTxn  } else { 0 }
    $vLpm  = if ($null -ne $oldLpm)  { [int]$oldLpm  } else { 1 }
    $vIdle = if ($null -ne $oldIdle) { [int]$oldIdle } else { 1 }
    return [scriptblock]::Create("
        Set-Reg '$base' 'TxnMaxPayload' $vTxn 'DWord'
        Set-Reg '$base' 'LPM Management Enabled' $vLpm 'DWord'
        Set-Reg '$ahciPath' 'EnableIdlePowerManagement' $vIdle 'DWord'
        Write-SR 'UNDO: AHCI LPM settings restored' 'UNDO'
    ")
}

function Apply-TcpGameTweaks {
    Write-SR "TCP Per-Adapter Game Tweaks" 'SECTION'
    $undoParts = [System.Collections.Generic.List[string]]::new()
    try {
        $adapters = Get-NetAdapterFrozen | Where-Object { $_.Status -eq 'Up' -and $_.InterfaceDescription -notmatch 'Loopback|Hyper-V|VMware|VirtualBox' }
        foreach ($a in $adapters) {
            $ifaceGuid = $a.InterfaceGuid
            $regPath = "HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces\$ifaceGuid"
            if (Test-Path $regPath) {
                $oldAck   = Get-RegVal $regPath 'TcpAckFrequency'
                $oldDelay = Get-RegVal $regPath 'TCPNoDelay'
                $oldTicks = Get-RegVal $regPath 'TcpDelAckTicks'
                Set-Reg $regPath 'TcpAckFrequency' 1 'DWord'
                Set-Reg $regPath 'TCPNoDelay'      1 'DWord'
                Set-Reg $regPath 'TcpDelAckTicks'  0 'DWord'
                Write-SR "TCP tweaks applied to: $($a.Name)" 'OK'
                $vAck   = if ($null -ne $oldAck)   { [int]$oldAck   } else { 0 }
                $vDelay = if ($null -ne $oldDelay) { [int]$oldDelay } else { 0 }
                $vTicks = if ($null -ne $oldTicks) { [int]$oldTicks } else { 2 }
                $undoParts.Add("Set-Reg '$regPath' 'TcpAckFrequency' $vAck 'DWord'; Set-Reg '$regPath' 'TCPNoDelay' $vDelay 'DWord'; Set-Reg '$regPath' 'TcpDelAckTicks' $vTicks 'DWord'")
            }
        }
        Write-SR "TcpAckFrequency=1, TCPNoDelay=1, TcpDelAckTicks=0 set on all active adapters" 'OK'
    } catch {
        Write-SR "TCP game tweaks failed: $_" 'FAIL'
    }
    if ($undoParts.Count -eq 0) { return $null }
    return [scriptblock]::Create(($undoParts -join "`n") + "`nWrite-SR 'UNDO: TCP game tweaks restored' 'UNDO'")
}

function Apply-NicIntMod {
    Write-SR "Disabling NIC Interrupt Moderation" 'SECTION'
    $undoParts = [System.Collections.Generic.List[string]]::new()
    try {
        $adapters = Get-NetAdapterFrozen | Where-Object { $_.Status -eq 'Up' -and $_.InterfaceDescription -notmatch 'Loopback|Hyper-V|VMware|VirtualBox' }
        foreach ($a in $adapters) {
            $props = Get-NetAdapterAdvancedProperty -Name $a.Name -EA SilentlyContinue
            $imProp = $props | Where-Object { $_.DisplayName -match 'Interrupt Moderation' } | Select-Object -First 1
            if ($imProp) {
                $oldVal = $imProp.DisplayValue
                Set-NetAdapterAdvancedProperty -Name $a.Name -DisplayName $imProp.DisplayName -DisplayValue 'Disabled' -EA SilentlyContinue
                Write-SR "Interrupt Moderation disabled on: $($a.Name)" 'OK'
                $undoParts.Add("Set-NetAdapterAdvancedProperty -Name '$($a.Name -replace $script:SqPattern, '$&$&')' -DisplayName '$($imProp.DisplayName -replace $script:SqPattern, '$&$&')' -DisplayValue '$($oldVal -replace $script:SqPattern, '$&$&')' -EA SilentlyContinue")
            } else {
                Write-SR "Interrupt Moderation property not found on: $($a.Name) (driver may not expose it)" 'WARN'
            }
        }
    } catch {
        Write-SR "NIC Interrupt Moderation tweak failed: $_" 'FAIL'
    }
    if ($undoParts.Count -eq 0) { return $null }
    return [scriptblock]::Create(($undoParts -join "`n") + "`nWrite-SR 'UNDO: NIC Interrupt Moderation restored' 'UNDO'")
}

# Resolves the Class\{4d36e972-...}\NNNN driver instance key for a NIC, matched by its
# NetCfgInstanceId (== Get-NetAdapter's InterfaceGuid) - the network equivalent of
# Get-GpuDriverSubkey above, needed because PnPCapabilities lives on the driver instance
# key, not anywhere Set-NetAdapter* cmdlets can reach.
function Get-NicDriverSubkey {
    param([string]$InterfaceGuid)
    $classPath = "HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4d36e972-e325-11ce-bfc1-08002be10318}"
    foreach ($key in Get-ChildItem $classPath -ErrorAction SilentlyContinue) {
        $guid = (Get-ItemProperty $key.PSPath -Name NetCfgInstanceId -ErrorAction SilentlyContinue).NetCfgInstanceId
        if ($guid -and $guid -eq $InterfaceGuid) { return $key.PSPath }
    }
    return $null
}

function Apply-NicPowerSaving {
    # PnPCapabilities=24 (CM_DEVCAP_NO_DISPLAY_IN_UI-adjacent bits for power) is exactly
    # what unticking "Allow the computer to turn off this device to save power" on the
    # adapter's Device Manager > Power Management tab writes - distinct from
    # Set-NetAdapterPowerManagement (which only covers WoL/ARP/NS offload, not this).
    Write-SR "Disabling NIC device power management" 'SECTION'
    $undoParts = [System.Collections.Generic.List[string]]::new()
    $scoreProbeFailed = $false
    $ErrorActionPreference = 'Stop'
    try {
        $adapters = Get-NetAdapterFrozen | Where-Object { $_.Status -eq 'Up' -and $_.InterfaceDescription -notmatch 'Loopback|Hyper-V|VMware|VirtualBox' }
        foreach ($a in $adapters) {
            $previousDriverError = $Error[0]
            $sub = Get-NicDriverSubkey -InterfaceGuid $a.InterfaceGuid
            if (-not $sub -and -not [object]::ReferenceEquals($Error[0],$previousDriverError) -and $Error[0].CategoryInfo.Category -ne 'ObjectNotFound') { $scoreProbeFailed = $true }
            if (-not $sub) { Write-SR "Driver key not found for: $($a.Name)" 'WARN'; continue }
            $old = Get-RegVal $sub 'PnPCapabilities'
            Set-RegLogged $sub 'PnPCapabilities' 24
            Write-SR "Device-level power management disabled on: $($a.Name)" 'OK'
            if ($null -ne $old) {
                $undoParts.Add("Set-Reg '$sub' 'PnPCapabilities' $([int]$old) 'DWord'")
            } else {
                $undoParts.Add("Remove-ItemProperty '$sub' -Name 'PnPCapabilities' -EA SilentlyContinue")
            }
        }
    } catch {
        $scoreProbeFailed = $true
        Write-SR "NIC power management tweak failed: $_" 'FAIL'
    }
    if ($undoParts.Count -eq 0) { if (-not $scoreProbeFailed) { $script:ScoreSkipReason = 'MissingTarget' }; return $null }
    return [scriptblock]::Create(($undoParts -join "`n") + "`nWrite-SR 'UNDO: NIC device power management restored' 'UNDO'")
}

function Apply-NicEeeDisable {
    # Energy Efficient Ethernet is wired-only (802.3az) - excludes WiFi adapters, unlike
    # the interrupt-moderation/offload tweaks above which apply to any active adapter.
    Write-SR "Disabling Energy Efficient Ethernet (EEE)" 'SECTION'
    $undoParts = [System.Collections.Generic.List[string]]::new()
    $scoreProbeFailed = $false
    $ErrorActionPreference = 'Stop'
    try {
        $adapters = Get-NetAdapterFrozen | Where-Object {
            $_.Status -eq 'Up' -and
            $_.InterfaceDescription -notmatch 'Loopback|Hyper-V|VMware|VirtualBox|Wi-Fi|Wireless|802\.11'
        }
        foreach ($a in $adapters) {
            $props   = Get-NetAdapterAdvancedProperty -Name $a.Name -EA Stop
            $eeeProp = $props | Where-Object { $_.DisplayName -match 'Energy.?Efficient.?Ethernet|Green Ethernet|EEE' } | Select-Object -First 1
            if ($eeeProp) {
                $oldVal = $eeeProp.DisplayValue
                Set-NetAdapterAdvancedProperty -Name $a.Name -DisplayName $eeeProp.DisplayName -DisplayValue 'Disabled' -EA SilentlyContinue
                Write-SR "EEE disabled on: $($a.Name)" 'OK'
                $undoParts.Add("Set-NetAdapterAdvancedProperty -Name '$($a.Name -replace $script:SqPattern, '$&$&')' -DisplayName '$($eeeProp.DisplayName -replace $script:SqPattern, '$&$&')' -DisplayValue '$($oldVal -replace $script:SqPattern, '$&$&')' -EA SilentlyContinue")
            } else {
                Write-SR "EEE property not found on: $($a.Name) (driver may not expose it, or adapter doesn't support EEE)" 'WARN'
            }
        }
    } catch {
        $scoreProbeFailed = $true
        Write-SR "EEE disable tweak failed: $_" 'FAIL'
    }
    if ($undoParts.Count -eq 0) { if (-not $scoreProbeFailed) { $script:ScoreSkipReason = 'MissingTarget' }; return $null }
    return [scriptblock]::Create(($undoParts -join "`n") + "`nWrite-SR 'UNDO: Energy Efficient Ethernet restored' 'UNDO'")
}

function Apply-MemCompDisable {
    Write-SR "Disabling Memory Compression" 'SECTION'
    $wasEnabled = $false
    try {
        $status = (Get-MMAgent).MemoryCompression
        $wasEnabled = [bool]$status
        if ($status) {
            Disable-MMAgent -MemoryCompression -EA Stop
            Write-SR "Memory Compression disabled" 'OK'
        } else {
            Write-SR "Memory Compression was already disabled" 'OK'
        }
    } catch {
        Write-SR "Memory Compression disable failed: $_" 'FAIL'
    }
    $reEnableCmd = if ($wasEnabled) { 'Enable-MMAgent -MemoryCompression -EA SilentlyContinue' } else { '' }
    return [scriptblock]::Create("$reEnableCmd; Write-SR 'UNDO: Memory Compression state restored' 'UNDO'")
}
#endregion Extended Gaming Tweaks

#region Hardware Detection & Adaptive Features

# ── Colour helper ──────────────────────────────────────────────────────────────
function Set-HealthLabel {
    param([string]$Name, [string]$Text, [string]$Color = '#8b8b9c')
    if ($c[$Name]) {
        $c[$Name].Text       = $Text
        $c[$Name].Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString($Color)
    }
}

# ── RAM / XMP detection ────────────────────────────────────────────────────────
function Get-XmpStatus {
    try {
        $dimms = Get-CachedCim Win32_PhysicalMemory
        $rated = ($dimms | Measure-Object Speed -Maximum).Maximum
        # Compare against the SLOWEST running DIMM, not just the first one enumerated -
        # all DIMMs in a kit should run at the same clock, so the minimum is what
        # actually determines whether XMP is genuinely active across the whole kit.
        # Previously only checked dimms[0], which could misreport XMP status on
        # mismatched/multi-kit systems where the first enumerated DIMM isn't
        # representative of the others.
        $runningSpeeds = $dimms | ForEach-Object {
            $speed = $_.ConfiguredClockSpeed
            if (-not $speed -or $speed -eq 0) { $speed = $_.Speed }
            $speed
        }
        $running = ($runningSpeeds | Measure-Object -Minimum).Minimum
        return @{ RatedMHz = [int]$rated; RunningMHz = [int]$running; XmpActive = ($running -ge $rated * 0.95) }
    } catch { return @{ RatedMHz = 0; RunningMHz = 0; XmpActive = $null } }
}

# ── Display / refresh-rate detection ──────────────────────────────────────────
# Registers the DisplayCfg P/Invoke type once per session (Add-Type throws if a type
# with the same name is defined twice, so this is guarded like the other Add-Type
# blocks in this file).
function Register-DisplayCfgType {
    if (([System.Management.Automation.PSTypeName]'DisplayCfg').Type) { return }
    Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;
public class DisplayCfg {
    [StructLayout(LayoutKind.Sequential, CharSet=CharSet.Ansi)]
    public struct DEVMODE {
        [MarshalAs(UnmanagedType.ByValTStr, SizeConst=32)] public string dmDeviceName;
        public short dmSpecVersion, dmDriverVersion, dmSize, dmDriverExtra;
        public int   dmFields, dmPositionX, dmPositionY, dmDisplayOrientation, dmDisplayFixedOutput;
        public short dmColor, dmDuplex, dmYResolution, dmTTOption, dmCollate;
        [MarshalAs(UnmanagedType.ByValTStr, SizeConst=32)] public string dmFormName;
        public short dmLogPixels; public int dmBitsPerPel, dmPelsWidth, dmPelsHeight,
                     dmDisplayFlags, dmDisplayFrequency, dmICMMethod, dmICMIntent,
                     dmMediaType, dmDitherType, dmReserved1, dmReserved2, dmPanningWidth, dmPanningHeight;
    }
    [StructLayout(LayoutKind.Sequential, CharSet=CharSet.Ansi)]
    public struct DISPLAY_DEVICE {
        public int cb;
        [MarshalAs(UnmanagedType.ByValTStr, SizeConst=32)]  public string DeviceName;
        [MarshalAs(UnmanagedType.ByValTStr, SizeConst=128)] public string DeviceString;
        public int StateFlags;
        [MarshalAs(UnmanagedType.ByValTStr, SizeConst=128)] public string DeviceID;
        [MarshalAs(UnmanagedType.ByValTStr, SizeConst=128)] public string DeviceKey;
    }
    [DllImport("user32.dll")] public static extern bool EnumDisplaySettings(string dev, int mode, ref DEVMODE dm);
    [DllImport("user32.dll")] public static extern int  ChangeDisplaySettings(ref DEVMODE dm, int flags);
    [DllImport("user32.dll")] public static extern bool EnumDisplayDevices(string lpDevice, uint iDevNum, ref DISPLAY_DEVICE lpDisplayDevice, uint dwFlags);
    public const int ENUM_CURRENT = -1; public const int CDS_UPDATEREGISTRY = 1;
    public const int DISPLAY_DEVICE_ACTIVE = 0x1; public const int DISPLAY_DEVICE_PRIMARY_DEVICE = 0x4;
}
'@
}

# EnumDisplaySettings requires a real device name (e.g. "\\.\DISPLAY1") - passing
# null/empty fails with ERROR_INVALID_PARAMETER on many systems despite some docs
# suggesting null means "current display". Resolve the active primary monitor's
# device name via EnumDisplayDevices, with a best-effort fallback.
function Get-PrimaryDisplayDeviceName {
    Register-DisplayCfgType
    $i = 0
    while ($true) {
        $dd = New-Object DisplayCfg+DISPLAY_DEVICE
        $dd.cb = [Runtime.InteropServices.Marshal]::SizeOf($dd)
        if (-not [DisplayCfg]::EnumDisplayDevices($null, $i, [ref]$dd, 0)) { break }
        $isActive  = ($dd.StateFlags -band [DisplayCfg]::DISPLAY_DEVICE_ACTIVE) -ne 0
        $isPrimary = ($dd.StateFlags -band [DisplayCfg]::DISPLAY_DEVICE_PRIMARY_DEVICE) -ne 0
        if ($isActive -and $isPrimary) { return $dd.DeviceName }
        $i++
    }
    return "\\.\DISPLAY1"
}

function Get-DisplayStatus {
    try {
        Register-DisplayCfgType
        $devName = Get-PrimaryDisplayDeviceName
        $cur = New-Object DisplayCfg+DEVMODE; $cur.dmSize = [Runtime.InteropServices.Marshal]::SizeOf($cur)
        if (-not [DisplayCfg]::EnumDisplaySettings($devName, [DisplayCfg]::ENUM_CURRENT, [ref]$cur)) {
            return @{ CurrentHz = 0; MaxHz = 0; AtMax = $null }
        }
        $maxHz = $cur.dmDisplayFrequency; $i = 0
        while ($true) {
            $m = New-Object DisplayCfg+DEVMODE; $m.dmSize = [Runtime.InteropServices.Marshal]::SizeOf($m)
            if (-not [DisplayCfg]::EnumDisplaySettings($devName, $i, [ref]$m)) { break }
            if ($m.dmPelsWidth -eq $cur.dmPelsWidth -and $m.dmPelsHeight -eq $cur.dmPelsHeight -and
                $m.dmBitsPerPel -eq $cur.dmBitsPerPel -and $m.dmDisplayFrequency -gt $maxHz) {
                $maxHz = $m.dmDisplayFrequency
            }
            $i++
        }
        return @{ CurrentHz = [int]$cur.dmDisplayFrequency; MaxHz = [int]$maxHz;
                  AtMax = ($cur.dmDisplayFrequency -ge $maxHz) }
    } catch { return @{ CurrentHz = 0; MaxHz = 0; AtMax = $null } }
}

function Set-MaxRefreshRate {
    Register-DisplayCfgType
    $devName = Get-PrimaryDisplayDeviceName
    $cur = New-Object DisplayCfg+DEVMODE; $cur.dmSize = [Runtime.InteropServices.Marshal]::SizeOf($cur)
    [DisplayCfg]::EnumDisplaySettings($devName, [DisplayCfg]::ENUM_CURRENT, [ref]$cur) | Out-Null
    $originalHz = $cur.dmDisplayFrequency
    $best = $cur; $maxHz = $originalHz; $i = 0
    while ($true) {
        $m = New-Object DisplayCfg+DEVMODE; $m.dmSize = [Runtime.InteropServices.Marshal]::SizeOf($m)
        if (-not [DisplayCfg]::EnumDisplaySettings($devName, $i, [ref]$m)) { break }
        if ($m.dmPelsWidth -eq $cur.dmPelsWidth -and $m.dmPelsHeight -eq $cur.dmPelsHeight -and
            $m.dmBitsPerPel -eq $cur.dmBitsPerPel -and $m.dmDisplayFrequency -gt $maxHz) {
            $maxHz = $m.dmDisplayFrequency; $best = $m
        }
        $i++
    }
    # Undo needs to re-find and re-apply the ORIGINAL frequency's mode, not just flip a
    # registry value - display modes are selected by enumerating DEVMODE entries, so the
    # undo scriptblock re-runs that same enumeration (in the main app process, where the
    # DisplayCfg type is already registered) targeting $originalHz instead of the max.
    $undo = $null
    if ($maxHz -gt $originalHz) {
        [DisplayCfg]::ChangeDisplaySettings([ref]$best, [DisplayCfg]::CDS_UPDATEREGISTRY) | Out-Null
        $devNameEsc = $devName -replace $script:SqPattern, '$&$&'
        $undo = [scriptblock]::Create(@"
Register-DisplayCfgType
`$dev = '$devNameEsc'
`$target = $originalHz
`$i2 = 0
while (`$true) {
    `$m2 = New-Object DisplayCfg+DEVMODE; `$m2.dmSize = [Runtime.InteropServices.Marshal]::SizeOf(`$m2)
    if (-not [DisplayCfg]::EnumDisplaySettings(`$dev, `$i2, [ref]`$m2)) { break }
    if (`$m2.dmDisplayFrequency -eq `$target) {
        [DisplayCfg]::ChangeDisplaySettings([ref]`$m2, [DisplayCfg]::CDS_UPDATEREGISTRY) | Out-Null
        break
    }
    `$i2++
}
Write-SR 'UNDO: Display refresh rate reverted to $originalHz Hz' 'UNDO'
"@)
    }
    return @{ Hz = $maxHz; Undo = $undo }
}

# ── WiFi / Ethernet detection ──────────────────────────────────────────────────
function Get-NetworkAdapterStatus {
    $up = Get-NetAdapter | Where-Object { $_.Status -eq 'Up' }
    $wifi = $up | Where-Object { $_.InterfaceDescription -match 'Wi-Fi|Wireless|802\.11|WiFi' } | Select-Object -First 1
    $eth  = $up | Where-Object { $_.InterfaceDescription -notmatch 'Wi-Fi|Wireless|802\.11|WiFi|Hyper-V|VMware|VirtualBox|Loopback' } | Select-Object -First 1
    return @{ OnWifi = ($null -ne $wifi); HasEthernet = ($null -ne $eth); WifiAdapter = $wifi; EthAdapter = $eth }
}

function Apply-WifiGamingMode {
    Write-SR "WiFi Gaming Mode" 'SECTION'
    $net = Get-NetworkAdapterStatus
    if (-not $net.WifiAdapter) { Write-SR "No active WiFi adapter found" 'WARN'; return $null }
    $name = $net.WifiAdapter.Name
    Write-SR "Tuning WiFi adapter: $name" 'APPLY'

    # Capture prior state before changing anything, so undo restores what was actually
    # there instead of assuming a default - same pattern every other Apply-* in this
    # file follows for registry writes.
    $prevPm  = try { Get-NetAdapterPowerManagement -Name $name -EA SilentlyContinue } catch { $null }
    $prevArp = if ($prevPm -and $prevPm.ArpOffload) { $prevPm.ArpOffload } else { 'Enabled' }
    $prevNs  = if ($prevPm -and $prevPm.NsOffload)  { $prevPm.NsOffload }  else { 'Enabled' }
    try { Set-NetAdapterPowerManagement -Name $name -ArpOffload Disabled -NsOffload Disabled -EA SilentlyContinue } catch {}

    $propsToTry = @(
        @{ Name='Roaming Aggressiveness'; Values=@('1  Lowest','1','Lowest') },
        @{ Name='Roaming Sensitivity';    Values=@('1','Lowest') },
        @{ Name='Preferred Band';         Values=@('2. 5GHz','5GHz','Prefer 5GHz') },
        @{ Name='802.11n/ac Wireless Mode'; Values=@('5GHz 802.11ac','5 GHz 802.11ac') }
    )
    $priorValues = @{}
    foreach ($prop in $propsToTry) {
        $priorValues[$prop.Name] = try {
            (Get-NetAdapterAdvancedProperty -Name $name -DisplayName $prop.Name -EA SilentlyContinue).DisplayValue
        } catch { $null }
        foreach ($val in $prop.Values) {
            try { Set-NetAdapterAdvancedProperty -Name $name -DisplayName $prop.Name -DisplayValue $val -EA Stop; break } catch {}
        }
    }
    Write-SR "WiFi Gaming Mode applied to $name" 'OK'

    $nameEsc = $name -replace $script:SqPattern, '$&$&'
    $restoreLines = foreach ($propName in $priorValues.Keys) {
        $prior = $priorValues[$propName]
        if ($null -ne $prior) {
            $propEsc  = $propName -replace $script:SqPattern, '$&$&'
            $priorEsc = "$prior" -replace $script:SqPattern, '$&$&'
            "try { Set-NetAdapterAdvancedProperty -Name '$nameEsc' -DisplayName '$propEsc' -DisplayValue '$priorEsc' -EA SilentlyContinue } catch {}"
        }
    }
    $restoreScript = ($restoreLines -join "`n") + "`n" +
        "try { Set-NetAdapterPowerManagement -Name '$nameEsc' -ArpOffload $prevArp -NsOffload $prevNs -EA SilentlyContinue } catch {}`n" +
        "Write-SR 'UNDO: WiFi Gaming Mode reverted on $nameEsc' 'UNDO'"
    return [scriptblock]::Create($restoreScript)
}

# ── Storage detection ──────────────────────────────────────────────────────────
function Get-StorageInfo {
    # Returns info for every physical disk, not just one - a system with both an
    # SSD and an NVMe drive (very common) needs both detected and both tweaked.
    $trimEnabled = $false
    try {
        $trimOut = fsutil behavior query DisableDeleteNotify 2>$null
        $trimEnabled = ($trimOut -match 'DisableDeleteNotify = 0')
    } catch {}

    $disks = @()
    try {
        foreach ($disk in (Get-PhysicalDisk | Sort-Object DeviceId)) {
            $type = if ($disk.BusType -eq 'NVMe') { 'NVMe' }
                    elseif ($disk.MediaType -eq 'SSD') { 'SSD' }
                    elseif ($disk.MediaType -eq 'HDD') { 'HDD' }
                    else { $disk.MediaType }
            $disks += [PSCustomObject]@{
                DeviceId     = $disk.DeviceId
                FriendlyName = $disk.FriendlyName
                Type         = $type
                Health       = $disk.HealthStatus
                TrimEnabled  = $trimEnabled
            }
        }
    } catch {}
    return $disks
}

function Apply-StorageAdaptive {
    Write-SR "Storage Adaptive Tweaks" 'SECTION'
    $disks = Get-StorageInfo
    if (-not $disks) { Write-SR "No physical disks detected" 'WARN'; return $null }
    $types = $disks.Type | Select-Object -Unique
    Write-SR "Detected drive type(s): $($types -join ', ')" 'INFO'
    # The underlying tweaks (fsutil TRIM, stornvme/storvsc driver params, defrag
    # service) are system/driver-wide, not tied to one specific disk instance, so
    # each distinct type present only needs to be applied once - but every type
    # present must be covered (a system can have both an SSD and an NVMe drive).
    # Every write below captures its actual prior value first so undo restores what
    # was really there, matching the pattern the rest of this file's Apply-* use.
    $undoLines = @()
    foreach ($type in $types) {
    switch ($type) {
        'NVMe' {
            # Disable NVMe host-controller power management
            $nvmePath = "HKLM:\SYSTEM\CurrentControlSet\Services\stornvme\Parameters\Device"
            if (-not (Test-Path $nvmePath)) { New-Item $nvmePath -Force | Out-Null }
            $prevIdle = (Get-ItemProperty $nvmePath -Name IdlePowerManagement -EA SilentlyContinue).IdlePowerManagement
            Set-Reg $nvmePath 'IdlePowerManagement' 0 'DWord'
            # Set StorPort queue depth
            $storvscPath = "HKLM:\SYSTEM\CurrentControlSet\Services\storvsc"
            $prevQueue = (Get-ItemProperty $storvscPath -Name RequestedQueueDepth -EA SilentlyContinue).RequestedQueueDepth
            Set-Reg $storvscPath 'RequestedQueueDepth' 254 'DWord'
            Write-SR "NVMe: power management off, queue depth 254" 'OK'

            $undoLines += if ($null -ne $prevIdle) { "Set-ItemProperty '$nvmePath' -Name IdlePowerManagement -Value $prevIdle -Type DWord -EA SilentlyContinue" }
                          else { "Remove-ItemProperty '$nvmePath' -Name IdlePowerManagement -EA SilentlyContinue" }
            $undoLines += if ($null -ne $prevQueue) { "Set-ItemProperty '$storvscPath' -Name RequestedQueueDepth -Value $prevQueue -Type DWord -EA SilentlyContinue" }
                          else { "Remove-ItemProperty '$storvscPath' -Name RequestedQueueDepth -EA SilentlyContinue" }
        }
        'SSD' {
            # Verify TRIM enabled
            $prevTrimOut = fsutil behavior query DisableDeleteNotify 2>$null
            $prevTrimDisabled = ($prevTrimOut -match 'DisableDeleteNotify = 1')
            fsutil behavior set DisableDeleteNotify 0 | Out-Null
            Write-SR "SSD: TRIM enabled" 'OK'
            # Disable scheduled defrag for SSD
            $svc = Get-Service 'defragsvc' -EA SilentlyContinue
            $prevStartType = if ($svc) { $svc.StartType } else { $null }
            try {
                if ($svc -and $svc.StartType -ne 'Disabled') { Set-Service 'defragsvc' -StartupType Manual -EA SilentlyContinue }
                Write-SR "SSD: defrag service set to Manual" 'OK'
            } catch {}

            if ($prevTrimDisabled) { $undoLines += "fsutil behavior set DisableDeleteNotify 1 | Out-Null" }
            if ($prevStartType -and $prevStartType -ne 'Manual') {
                $undoLines += "try { Set-Service 'defragsvc' -StartupType $prevStartType -EA SilentlyContinue } catch {}"
            }
        }
        'HDD' {
            # Enable write caching
            try {
                $hddDisks = Get-CimInstance Win32_DiskDrive
                foreach ($d in $hddDisks) {
                    $d | Invoke-CimMethod -MethodName 'SetBusTypeAttributes' -Arguments @{ AttributesBits = 0 } -EA SilentlyContinue | Out-Null
                }
            } catch {}
            # Increase read-ahead
            $prefetchPath = "HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management"
            $prevPrefetch = (Get-ItemProperty $prefetchPath -Name EnablePrefetcher -EA SilentlyContinue).EnablePrefetcher
            Set-Reg $prefetchPath 'EnablePrefetcher' 3 'DWord'
            Write-SR "HDD: read-ahead and prefetcher enabled" 'OK'

            $undoLines += if ($null -ne $prevPrefetch) { "Set-ItemProperty '$prefetchPath' -Name EnablePrefetcher -Value $prevPrefetch -Type DWord -EA SilentlyContinue" }
                          else { "Remove-ItemProperty '$prefetchPath' -Name EnablePrefetcher -EA SilentlyContinue" }
        }
    }
    }
    Write-SR "Storage adaptive tweaks complete for: $($types -join ', ')" 'OK'

    if ($undoLines.Count -eq 0) { return $null }
    $undoLines += "Write-SR 'UNDO: Storage adaptive tweaks reverted' 'UNDO'"
    return [scriptblock]::Create(($undoLines -join "`n"))
}

# ── CPU throttle detection ─────────────────────────────────────────────────────
function Get-CpuThrottleStatus {
    try {
        $cpu = Get-CachedCim Win32_Processor -Live -TtlSeconds 300 | Select-Object -First 1
        $max = [int]$cpu.MaxClockSpeed; $cur = [int]$cpu.CurrentClockSpeed
        $pct = if ($max -gt 0) { [math]::Round($cur / $max * 100) } else { 100 }
        return @{ MaxMHz=$max; CurrentMHz=$cur; ThrottlePct=$pct; IsThrottling=($pct -lt 85) }
    } catch { return @{ MaxMHz=0; CurrentMHz=0; ThrottlePct=100; IsThrottling=$false } }
}

# ── GPU temperature (NVIDIA nvidia-smi) ────────────────────────────────────────
function Get-GpuTemp {
    # NVIDIA: nvidia-smi ships with every driver install, always available.
    try {
        $smi = @("$env:ProgramFiles\NVIDIA Corporation\NVSMI\nvidia-smi.exe",
                 "$env:SystemRoot\System32\nvidia-smi.exe", "nvidia-smi") | Where-Object { Test-Path $_ } | Select-Object -First 1
        if ($smi) {
            $t = & $smi --query-gpu=temperature.gpu --format=csv,noheader 2>$null
            if ($t -match '^\s*\d+\s*$') { return [int]($t.Trim()) }
        }
    } catch {}

    # AMD (and everyone else) has no bundled equivalent CLI tool, and AMD's real sensor
    # path is undocumented driver-internal WMI calls not safe to guess at blind. Instead,
    # fall back to LibreHardwareMonitor/OpenHardwareMonitor's WMI namespace if the user
    # already has either running (common among enthusiasts) - safe to probe either way,
    # since the namespace simply doesn't exist when the tool isn't running.
    foreach ($ns in @('root\LibreHardwareMonitor', 'root\OpenHardwareMonitor')) {
        try {
            $sensor = Get-CimInstance -Namespace $ns -ClassName Sensor -EA Stop |
                Where-Object { $_.SensorType -eq 'Temperature' -and $_.Name -match 'GPU Core|GPU Hot Spot|GPU Temperature' } |
                Select-Object -First 1
            if ($sensor -and $null -ne $sensor.Value) { return [int][math]::Round($sensor.Value) }
        } catch {}
    }
    return $null
}

# ── CPU temperature (LibreHardwareMonitor/OpenHardwareMonitor only - no bundled CLI
# tool exists for CPU temp the way nvidia-smi covers GPU, and Windows' own ACPI thermal
# zone WMI class isn't reliably CPU-specific, so this only ever returns a real reading
# or nothing, never a guess). ──────────────────────────────────────────────────────
function Get-CpuTemp {
    foreach ($ns in @('root\LibreHardwareMonitor', 'root\OpenHardwareMonitor')) {
        try {
            $sensor = Get-CimInstance -Namespace $ns -ClassName Sensor -EA Stop |
                Where-Object { $_.SensorType -eq 'Temperature' -and $_.Name -match 'CPU Package|Core \(Tctl/Tdie\)|CPU Core|Core Average' } |
                Select-Object -First 1
            if ($sensor -and $null -ne $sensor.Value) { return [int][math]::Round($sensor.Value) }
        } catch {}
    }
    return $null
}

# Win32_Processor.LoadPercentage is a known-unreliable WMI property - it's simply not
# populated on some systems/drivers/VMs. This computes real CPU busy% from two raw perf
# counter samples instead (the standard PERF_100NSEC_TIMER delta formula), which is what
# every real CPU meter does under the hood - deliberately not Get-Counter, which has its
# own overhead/reliability issues in a compiled-exe host. Needs two calls spaced apart to
# produce a value (the first seeds a baseline and returns $null) - naturally satisfied by
# this being called every tick of the Dashboard's own 4s metrics timer.
$script:_CpuLoadPrev = $null
# Overall CPU busy percent from the Windows system times (a few microseconds). Needs a previous sample, which is taken once at start.
$script:_SysTimesPrev = $null
function Get-CpuLoadFast {
    try {
        $i = [long]0; $k = [long]0; $u = [long]0
        if (-not [StreamReady.ConsoleNative]::GetSystemTimes([ref]$i, [ref]$k, [ref]$u)) { return $null }
        $prev = $script:_SysTimesPrev
        $script:_SysTimesPrev = @{ I = $i; K = $k; U = $u }
        if (-not $prev) { return $null }
        $dTotal = ($k - $prev.K) + ($u - $prev.U); $dIdle = $i - $prev.I
        if ($dTotal -le 0) { return $null }
        return [int][math]::Round([math]::Max(0, [math]::Min(100, 100.0 * ($dTotal - $dIdle) / $dTotal)))
    } catch { return $null }
}
try { [void](Get-CpuLoadFast) } catch {}
function Get-CpuLoadPercent {
    try {
        $raw = Get-CimInstance Win32_PerfRawData_PerfOS_Processor -Filter "Name='_Total'" -EA Stop
        if (-not $raw) { return $null }
        $n2 = [double]$raw.PercentProcessorTime
        $d2 = [double]$raw.Timestamp_Sys100NS
        $prev = $script:_CpuLoadPrev
        $script:_CpuLoadPrev = @{ N = $n2; D = $d2 }
        if ($prev -and ($d2 -gt $prev.D)) {
            $pct = 100 * (($n2 - $prev.N) / ($d2 - $prev.D))
            return [math]::Round([math]::Max(0, [math]::Min(100, $pct)))
        }
    } catch {}
    return $null
}

# ── Driver age check (advisory only - read-only, no downloading/installing) ────
# Driver dates are self-reported by vendors via the INF and aren't always accurate
# (some vendors re-stamp old drivers on repackage), so this is framed as a hint to
# go check Windows Update / the vendor site, not a hard verdict.
$script:_DriverHealthCache = $null; $script:_DriverHealthTime = [datetime]::MinValue
function Get-DriverHealthInfo {
    if ($script:_DriverHealthCache -and (([datetime]::Now - $script:_DriverHealthTime).TotalMinutes -lt 10)) { return $script:_DriverHealthCache }
    $r = Get-DriverHealthInfoUncached
    if ($null -ne $r.AgeDays) { $script:_DriverHealthCache = $r; $script:_DriverHealthTime = [datetime]::Now }
    return $r
}
function Get-DriverHealthInfoUncached {
    try {
        $classes = @('Display','Net','HDC','Media')  # GPU, network, storage controllers, audio
        $drivers = Get-CimInstance Win32_PnPSignedDriver -EA Stop |
            Where-Object { $_.DeviceClass -in $classes -and $_.DriverDate -and $_.Manufacturer -notmatch '^Microsoft' -and $_.DeviceName -notmatch 'Kernel Debug|WAN Miniport|Miniport|Virtual|Loopback|VB-Audio|Audio Cable|Hi-Fi Cable|Voicemeeter|Stereo Mix|Indirect|Remote Desktop|Parsec|Software' }
        if (-not $drivers) { return @{ OldestDate = $null; OldestDevice = $null; AgeDays = $null } }
        $oldest = $drivers | Sort-Object DriverDate | Select-Object -First 1
        $ageDays = ([datetime]::Now - $oldest.DriverDate).Days
        return @{ OldestDate = $oldest.DriverDate; OldestDevice = $oldest.DeviceName; AgeDays = $ageDays }
    } catch { return @{ OldestDate = $null; OldestDevice = $null; AgeDays = $null } }
}

# ── ReBAR hint (heuristic) ─────────────────────────────────────────────────────
function Get-ReBarHint {
    # ReBAR cannot be reliably detected from userland without a driver;
    # we check if the GPU's memory aperture in PCI config looks large.
    try {
        $vid = Get-CachedCim Win32_VideoController | Select-Object -First 1
        if ($vid.AdapterRAM -and [long]$vid.AdapterRAM -gt 0) {
            # AdapterRAM is unreliable for >4GB GPUs; return advisory
            return @{ Status='Advisory'; GpuName=$vid.Name }
        }
    } catch {}
    return @{ Status='Advisory'; GpuName='Unknown' }
}

# ── Intel Hybrid detection ─────────────────────────────────────────────────────
function Get-IntelHybridInfo {
    $cpu = Get-CachedCim Win32_Processor | Select-Object -First 1
    $name = $cpu.Name
    $isHybrid = $name -match 'i[3-9]-1[2-4]\d{3}|Core Ultra [3-9]'
    return @{ IsHybrid=$isHybrid; CpuName=$name; Cores=$cpu.NumberOfCores; Threads=$cpu.NumberOfLogicalProcessors }
}

function Apply-IntelHybridAffinity {
    Write-SR "Intel Hybrid CPU - P-Core Affinity" 'SECTION'
    # P-cores are the first N physical cores; each has 2 logical (HT).
    # E-cores have 1 logical each. We set the preferred affinity hint via
    # registry so the Thread Director maps game threads to P-cores.
    $undoParts = [System.Collections.Generic.List[string]]::new()

    # Set CpuPriorityClass hint via IFEO (Image File Execution Options) for common launchers
    $launchers = @('steam.exe','EpicGamesLauncher.exe','Battle.net.exe','RiotClientServices.exe','EADesktop.exe')
    foreach ($exe in $launchers) {
        $ifeo = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\$exe\PerfOptions"
        $oldPri = Get-RegVal $ifeo 'CpuPriorityClass'
        $oldIo  = Get-RegVal $ifeo 'IoPriority'
        if (-not (Test-Path $ifeo)) { New-Item $ifeo -Force | Out-Null }
        Set-Reg $ifeo 'CpuPriorityClass'    3    'DWord'  # Above Normal
        Set-Reg $ifeo 'IoPriority'          3    'DWord'  # High
        Write-SR "IFEO PerfOptions set for $exe" 'OK'
        if ($null -ne $oldPri) { $undoParts.Add("Set-Reg '$ifeo' 'CpuPriorityClass' $oldPri 'DWord'") }
        else                   { $undoParts.Add("Remove-ItemProperty '$ifeo' -Name 'CpuPriorityClass' -EA SilentlyContinue") }
        if ($null -ne $oldIo)  { $undoParts.Add("Set-Reg '$ifeo' 'IoPriority' $oldIo 'DWord'") }
        else                   { $undoParts.Add("Remove-ItemProperty '$ifeo' -Name 'IoPriority' -EA SilentlyContinue") }
    }

    # Ensure HeteroPolicy is set so OS prefers P-cores for foreground tasks
    $heteroPath = "HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\kernel"
    $oldHetero  = Get-RegVal $heteroPath 'DisableHeteroClass'
    Set-Reg $heteroPath 'DisableHeteroClass' 0 'DWord'
    Write-SR "Intel hybrid affinity hints applied - P-cores will be preferred for foreground/game processes" 'OK'
    if ($null -ne $oldHetero) { $undoParts.Add("Set-Reg '$heteroPath' 'DisableHeteroClass' $oldHetero 'DWord'") }
    else                      { $undoParts.Add("Remove-ItemProperty '$heteroPath' -Name 'DisableHeteroClass' -EA SilentlyContinue") }

    return [scriptblock]::Create(($undoParts -join "`n") + "`nWrite-SR 'UNDO: Intel Hybrid P-Core affinity hints restored' 'UNDO'")
}

# ── AMD 3D V-Cache detection ───────────────────────────────────────────────────
function Get-AmdVcacheInfo {
    $cpu  = Get-CachedCim Win32_Processor | Select-Object -First 1
    $name = $cpu.Name
    $is3D = $name -match '5800X3D|7800X3D|7900X3D|7950X3D|7600X3D|9800X3D|9900X3D|9950X3D'
    $isDualCcd = $name -match '7900X3D|7950X3D|9900X3D|9950X3D'
    return @{ Is3DCache=$is3D; IsDualCcd=$isDualCcd; CpuName=$name; Cores=$cpu.NumberOfCores }
}

function Apply-AmdCpuMitigationBypass {
    # NOTE: this used to be named/described as "3D V-Cache CCD Affinity" and claimed
    # to pin game launchers to the V-Cache CCD and set their "preferred NUMA node."
    # That was inaccurate: CpuPriorityClass is a generic priority hint (not CCD/core
    # specific - it doesn't target any particular CCD), and FeatureSettings/
    # FeatureSettingsOverride are Microsoft's documented Spectre/Meltdown/L1TF
    # speculative-execution mitigation toggle (see KB4073119) - nothing to do with
    # NUMA nodes or CCDs. This function is relabeled to describe what it actually
    # does: raise launcher priority, and disable CPU security mitigations for a
    # performance gain. The unused CCD-affinity mask computation was also dead code
    # (the mask was never applied to anything) and has been removed.
    Write-SR "AMD: Launcher Priority Boost + CPU Security Mitigation Bypass" 'SECTION'

    $undoParts = [System.Collections.Generic.List[string]]::new()

    $launchers = @('steam.exe','EpicGamesLauncher.exe','Battle.net.exe','RiotClientServices.exe','EADesktop.exe')
    foreach ($exe in $launchers) {
        $ifeo = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\$exe\PerfOptions"
        $old = Get-RegVal $ifeo 'CpuPriorityClass'
        if (-not (Test-Path $ifeo)) { New-Item $ifeo -Force | Out-Null }
        Set-Reg $ifeo 'CpuPriorityClass' 3 'DWord'
        Write-SR "IFEO priority raised for $exe" 'OK'
        if ($null -ne $old) { $undoParts.Add("Set-Reg '$ifeo' 'CpuPriorityClass' $old 'DWord'") }
        else                { $undoParts.Add("Remove-ItemProperty '$ifeo' -Name 'CpuPriorityClass' -EA SilentlyContinue") }
    }

    # Disables Spectre/Meltdown/L1TF mitigations. Per KB4073119, FeatureSettingsOverride
    # requires FeatureSettingsOverrideMask set alongside it or the override is ignored -
    # that companion value was previously missing entirely.
    $mmPath = "HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management"
    $oldSettings     = Get-RegVal $mmPath 'FeatureSettings'
    $oldOverride     = Get-RegVal $mmPath 'FeatureSettingsOverride'
    $oldOverrideMask = Get-RegVal $mmPath 'FeatureSettingsOverrideMask'
    Set-Reg $mmPath 'FeatureSettings'             1 'DWord'
    Set-Reg $mmPath 'FeatureSettingsOverride'     3 'DWord'
    Set-Reg $mmPath 'FeatureSettingsOverrideMask' 3 'DWord'
    Write-SR "CPU security mitigations (Spectre/Meltdown/L1TF) disabled for performance - this is a security tradeoff" 'WARN'

    if ($null -ne $oldSettings)     { $undoParts.Add("Set-Reg '$mmPath' 'FeatureSettings' $oldSettings 'DWord'") }
    else                            { $undoParts.Add("Remove-ItemProperty '$mmPath' -Name 'FeatureSettings' -EA SilentlyContinue") }
    if ($null -ne $oldOverride)     { $undoParts.Add("Set-Reg '$mmPath' 'FeatureSettingsOverride' $oldOverride 'DWord'") }
    else                            { $undoParts.Add("Remove-ItemProperty '$mmPath' -Name 'FeatureSettingsOverride' -EA SilentlyContinue") }
    if ($null -ne $oldOverrideMask) { $undoParts.Add("Set-Reg '$mmPath' 'FeatureSettingsOverrideMask' $oldOverrideMask 'DWord'") }
    else                            { $undoParts.Add("Remove-ItemProperty '$mmPath' -Name 'FeatureSettingsOverrideMask' -EA SilentlyContinue") }

    return [scriptblock]::Create(($undoParts -join "`n") + "`nWrite-SR 'UNDO: AMD launcher priority + CPU mitigations restored' 'UNDO'")
}

# ── PCIe ASPM disable ──────────────────────────────────────────────────────────
function Apply-PcieAspm {
    Write-SR "Disabling PCIe ASPM" 'SECTION'
    $oldOverride = Get-RegVal "HKLM:\SYSTEM\CurrentControlSet\Control\Power" 'PlatformAoAcOverride'
    Set-Reg "HKLM:\SYSTEM\CurrentControlSet\Control\Power" 'PlatformAoAcOverride' 0 'DWord'
    $oldAcAspm = $null
    # Falls back to the 'SCHEME_CURRENT' alias (always valid) if the GUID parse below
    # fails before assigning it, so the undo scriptblock never interpolates a blank
    # GUID into its powercfg calls.
    $planGuid = 'SCHEME_CURRENT'
    try {
        $planGuid = ((powercfg /getactivescheme) -split 'GUID: ')[1] -split ' ' | Select-Object -First 1
        $queryOut = powercfg /query $planGuid 501a4d13-42af-4429-9fd1-a8218c268e20 ee12f906-d277-404b-b6da-e5fa1a576df5 2>$null
        $acLine   = $queryOut | Where-Object { $_ -match 'Current AC Power Setting Index' } | Select-Object -First 1
        if ($acLine -match '0x([0-9a-fA-F]+)') { $oldAcAspm = [int]('0x' + $Matches[1]) }
        powercfg /setacvalueindex $planGuid 501a4d13-42af-4429-9fd1-a8218c268e20 ee12f906-d277-404b-b6da-e5fa1a576df5 0 | Out-Null
        powercfg /setactive $planGuid | Out-Null
        Write-SR "PCIe Link State Power Management set to Off via powercfg" 'OK'
    } catch { Write-SR "powercfg ASPM step failed: $_" 'WARN' }
    Write-SR "PCIe ASPM disabled" 'OK'
    $vOverride = if ($null -ne $oldOverride) { [int]$oldOverride } else { 1 }
    $vAspm     = if ($null -ne $oldAcAspm)  { $oldAcAspm } else { 2 }
    return [scriptblock]::Create("
        Set-Reg 'HKLM:\SYSTEM\CurrentControlSet\Control\Power' 'PlatformAoAcOverride' $vOverride 'DWord'
        try { powercfg /setacvalueindex $planGuid 501a4d13-42af-4429-9fd1-a8218c268e20 ee12f906-d277-404b-b6da-e5fa1a576df5 $vAspm | Out-Null; powercfg /setactive $planGuid | Out-Null } catch {}
        Write-SR 'UNDO: PCIe ASPM settings restored' 'UNDO'
    ")
}

# ── NVIDIA Shader Cache unlimited ─────────────────────────────────────────────
function Apply-NvidiaShaderCache {
    Write-SR "NVIDIA Shader Cache - Unlimited" 'SECTION'
    $base = "HKLM:\SOFTWARE\NVIDIA Corporation\Global\NVTweak"
    if (-not (Test-Path $base)) { New-Item $base -Force | Out-Null }
    $oldSize = Get-RegVal $base 'ShaderCacheSize'
    # ShaderCacheSize 0 = unlimited
    Set-Reg $base 'ShaderCacheSize' 0 'DWord'
    # NOTE: this used to also force VRROptimizeEnable=0 in DirectXUserGlobalSettings -
    # unrelated to shader cache and it silently overwrote whatever the dedicated VRR
    # tweak (Apply-VRR) had set, so ticking both VRR and this tweak together would
    # leave VRR disabled with no warning. Removed; VRROptimizeEnable is Apply-VRR's
    # responsibility alone.
    Write-SR "NVIDIA shader cache set to unlimited - resolves stutter in new game areas" 'OK'

    $vOldSize = if ($null -ne $oldSize) { try { [int]$oldSize } catch { -1 } } else { -1 }
    $restoreSize = if ($vOldSize -ge 0) { "Set-Reg '$base' 'ShaderCacheSize' $vOldSize 'DWord'" } else { "Remove-ItemProperty '$base' 'ShaderCacheSize' -EA SilentlyContinue" }
    return [scriptblock]::Create("$restoreSize; Write-SR 'UNDO: NVIDIA shader cache settings restored' 'UNDO'")
}

# ── Dashboard Health Report loader ────────────────────────────────────────────
function Load-HealthReport {
    param([switch]$Force)
    # This report includes some of the more expensive queries in the app (driver
    # enumeration via Get-CimInstance Win32_PnPSignedDriver among them), but it's
    # triggered on every single Dashboard revisit (SideNav SelectionChanged), not just
    # the first. None of this data changes on a human timescale, so skip re-running it
    # if it ran recently - unless the user explicitly clicked "Refresh".
    if (-not $Force -and $script:_LastHealthReportTime -and
        ((Get-Date) - $script:_LastHealthReportTime).TotalSeconds -lt 120) {
        return
    }
    $script:_LastHealthReportTime = Get-Date

    $green  = '#56dd92'; $yellow = '#f0b545'; $red = '#ff6b6b'; $gray = '#8b8b9c'

    # RAM / XMP
    try {
        $xmp = Get-XmpStatus
        if ($xmp.RatedMHz -gt 0 -and $xmp.RunningMHz -gt 0) {
            if ($xmp.XmpActive) {
                Set-HealthLabel 'LblHealthRam' "RAM: $($xmp.RunningMHz) MHz - XMP/EXPO active ✓" $green
            } else {
                Set-HealthLabel 'LblHealthRam' "RAM: $($xmp.RunningMHz) MHz - rated $($xmp.RatedMHz) MHz, enable XMP/EXPO in BIOS ⚠" $yellow
            }
        } else { Set-HealthLabel 'LblHealthRam' "RAM: speed unknown" $gray }
    } catch { Set-HealthLabel 'LblHealthRam' "RAM: error reading" $gray }

    # Display refresh rate
    try {
        $disp = Get-DisplayStatus
        if ($disp.CurrentHz -gt 0) {
            if ($disp.AtMax) {
                Set-HealthLabel 'LblHealthDisplay' "Display: $($disp.CurrentHz) Hz - at maximum ✓" $green
            } else {
                Set-HealthLabel 'LblHealthDisplay' "Display: $($disp.CurrentHz) Hz - monitor supports $($disp.MaxHz) Hz ⚠" $yellow
            }
        } else { Set-HealthLabel 'LblHealthDisplay' "Display: refresh rate unknown" $gray }
    } catch { Set-HealthLabel 'LblHealthDisplay' "Display: error reading" $gray }

    # Network
    try {
        $net = Get-NetworkAdapterStatus
        if ($net.HasEthernet) {
            Set-HealthLabel 'LblHealthNetwork' "Network: Ethernet connected ✓" $green
        } elseif ($net.OnWifi) {
            Set-HealthLabel 'LblHealthNetwork' "Network: WiFi only - Ethernet recommended for gaming ⚠" $yellow
        } else {
            Set-HealthLabel 'LblHealthNetwork' "Network: no active adapter" $gray
        }
    } catch { Set-HealthLabel 'LblHealthNetwork' "Network: error reading" $gray }

    # Storage
    try {
        $disks = Get-StorageInfo
        if (-not $disks) {
            Set-HealthLabel 'LblHealthStorage' "Storage: no disks detected" $gray
        } else {
            $badHealth  = $disks.Health | Where-Object { $_ -ne 'Healthy' -and $_ -notmatch 'Warning' }
            $warnHealth = $disks.Health | Where-Object { $_ -match 'Warning' }
            $healthCol  = if ($badHealth) { $red } elseif ($warnHealth) { $yellow } else { $green }
            $summary = ($disks | ForEach-Object {
                $trimNote = if ($_.Type -eq 'SSD' -or $_.Type -eq 'NVMe') { if ($_.TrimEnabled) { ', TRIM ✓' } else { ', TRIM OFF ⚠' } } else { '' }
                "$($_.Type) - $($_.Health)$trimNote"
            }) -join '  |  '
            Set-HealthLabel 'LblHealthStorage' "Storage: $summary" $healthCol
        }
    } catch { Set-HealthLabel 'LblHealthStorage' "Storage: error reading" $gray }

    # ReBAR
    Set-HealthLabel 'LblHealthRebar' "Your PC may support a faster graphics mode. This is optional and only for advanced users. Check your PC maker's guide before changing BIOS settings." $gray

    # CPU throttle
    try {
        $thr = Get-CpuThrottleStatus
        if ($thr.MaxMHz -gt 0) {
            if (-not $thr.IsThrottling) {
                Set-HealthLabel 'LblHealthCpu' "CPU: $($thr.CurrentMHz) MHz - no throttling ✓" $green
            } else {
                Set-HealthLabel 'LblHealthCpu' "CPU: $($thr.CurrentMHz) MHz of $($thr.MaxMHz) MHz - throttling detected ⚠" $yellow
            }
        } else { Set-HealthLabel 'LblHealthCpu' "CPU: clock speed unknown" $gray }
    } catch { Set-HealthLabel 'LblHealthCpu' "CPU: error reading" $gray }

    # Pagefile
    try {
        $cs = Get-CimInstance Win32_ComputerSystem
        if ($cs.AutomaticManagedPagefile) {
            Set-HealthLabel 'LblHealthPagefile' "Pagefile: system managed ✓" $green
        } else {
            Set-HealthLabel 'LblHealthPagefile' "Pagefile: custom fixed size, system managed recommended ⚠" $yellow
        }
    } catch { Set-HealthLabel 'LblHealthPagefile' "Pagefile: error reading" $gray }

    # GPU temperature
    try {
        $temp = Get-GpuTemp
        if ($null -ne $temp) {
            $tCol = if ($temp -lt 80) { $green } elseif ($temp -lt 90) { $yellow } else { $red }
            $tMsg = if ($temp -ge 90) { " - thermal throttling risk ⚠" } elseif ($temp -ge 80) { " - running hot ⚠" } else { " - OK ✓" }
            Set-HealthLabel 'LblHealthGpuTemp' "GPU Temp: ${temp}°C$tMsg" $tCol
        } else {
            Set-HealthLabel 'LblHealthGpuTemp' "GPU Temp: N/A - use HWiNFO64 for monitoring ℹ" $gray
        }
    } catch { Set-HealthLabel 'LblHealthGpuTemp' "GPU Temp: error reading" $gray }

    # Driver age (GPU/Network/Storage/Audio) - advisory only, no downloading/installing
    try {
        $drv = Get-DriverHealthInfo
        if ($null -eq $drv.AgeDays) {
            Set-HealthLabel 'LblHealthDrivers' "Drivers: unable to read driver info" $gray
        } elseif ($drv.AgeDays -gt 545) {  # ~18 months
            Set-HealthLabel 'LblHealthDrivers' "Drivers: oldest is $($drv.AgeDays) days old ($($drv.OldestDevice)) - check Windows Update or the vendor site ⚠" $yellow
        } else {
            Set-HealthLabel 'LblHealthDrivers' "Drivers: all reasonably current (oldest $($drv.AgeDays) days) ✓" $green
        }
    } catch { Set-HealthLabel 'LblHealthDrivers' "Drivers: error reading" $gray }
}

# ── Storage health loader ──────────────────────────────────────────────────────
function Load-StorageHealth {
    try {
        $disks = Get-StorageInfo
        if (-not $disks) {
            $c['LblStorageHealth'].Text = "No physical disks detected."
            Write-SR "Storage: no physical disks detected" 'WARN'
            return
        }
        $lines = foreach ($d in $disks) {
            $trimNote = if ($d.Type -match 'SSD|NVMe') { if ($d.TrimEnabled) { ' | TRIM enabled' } else { ' | TRIM DISABLED' } } else { '' }
            "$($d.FriendlyName) - $($d.Type) | Health: $($d.Health)$trimNote"
        }
        $msg = $lines -join "`n"
        $c['LblStorageHealth'].Text = $msg
        $worstIsBad  = ($disks.Health | Where-Object { $_ -ne 'Healthy' -and $_ -notmatch 'Warning' })
        $worstIsWarn = ($disks.Health | Where-Object { $_ -match 'Warning' })
        $col = if ($worstIsBad) { '#ff6b6b' } elseif ($worstIsWarn) { '#f0b545' } else { '#56dd92' }
        $c['LblStorageHealth'].Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString($col)
        Write-SR "Storage: $($disks.Count) drive(s) - $($msg -replace "`n", ' | ')" 'OK'
    } catch {
        $c['LblStorageHealth'].Text = "Storage check failed: $_"
        Write-SR "Storage health check failed: $_" 'FAIL'
    }
}

# ── Intel Hybrid / AMD 3D card initializer ────────────────────────────────────
function Initialize-CpuArchCards {
    # Intel Hybrid
    $intel = Get-IntelHybridInfo
    if ($intel.IsHybrid) {
        $c['LblIntelHybridStatus'].Text = "$($intel.CpuName) - Hybrid architecture detected ($($intel.Cores) cores, $($intel.Threads) threads). P-Core affinity hints can be applied to game launchers."
        $c['BtnIntelHybridApply'].IsEnabled = $true
    } else {
        $c['LblIntelHybridStatus'].Text = "Not applicable - $($intel.CpuName) does not have P/E-core hybrid architecture."
        $c['BtnIntelHybridApply'].IsEnabled = $false
    }

    # AMD launcher priority + CPU mitigation bypass (shown on the 3D V-Cache dual-CCD
    # chips this card is scoped to, but the tweak itself is not actually CCD-specific -
    # see Apply-AmdCpuMitigationBypass for why)
    $amd = Get-AmdVcacheInfo
    if ($amd.Is3DCache) {
        $msg = if ($amd.IsDualCcd) {
            "$($amd.CpuName) detected. Available: launcher priority boost + CPU security mitigation bypass (Spectre/Meltdown/L1TF) for a performance gain."
        } else {
            "$($amd.CpuName) - single-CCD, not currently offered here."
        }
        $c['LblAmdVcacheStatus'].Text = $msg
        $c['BtnAmdVcacheApply'].IsEnabled = $amd.IsDualCcd
    } else {
        $c['LblAmdVcacheStatus'].Text = "Not applicable - $($amd.CpuName) does not have 3D V-Cache."
        $c['BtnAmdVcacheApply'].IsEnabled = $false
    }

    # WiFi status
    $net = Get-NetworkAdapterStatus
    if ($net.HasEthernet -and -not $net.OnWifi) {
        $c['LblWifiStatus'].Text = "Ethernet connected - WiFi Gaming Mode not required."
    } elseif ($net.OnWifi) {
        $adapter = $net.WifiAdapter.InterfaceDescription
        $c['LblWifiStatus'].Text = "WiFi adapter: $adapter - apply gaming mode to reduce latency and disable power saving."
    } else {
        $c['LblWifiStatus'].Text = "No active network adapter detected."
    }

    # Display refresh
    $disp = Get-DisplayStatus
    if ($disp.CurrentHz -gt 0) {
        if ($disp.AtMax) {
            $c['LblDisplayRefreshStatus'].Text = "Running at maximum refresh rate: $($disp.CurrentHz) Hz ✓"
        } else {
            $c['LblDisplayRefreshStatus'].Text = "Currently $($disp.CurrentHz) Hz - monitor supports up to $($disp.MaxHz) Hz. Click below to apply maximum."
        }
    } else {
        $c['LblDisplayRefreshStatus'].Text = "Could not read display refresh rate."
    }
}

