#region Test-* Companions

# Returns $true if the registry value matches the "applied" state
function Test-GameMode        { (Get-ItemProperty "HKCU:\Software\Microsoft\GameBar" -Name AllowAutoGameMode -EA SilentlyContinue).AllowAutoGameMode -eq 1 }
function Test-HwGpu           { (Get-ItemProperty "HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers" -Name HwSchMode -EA SilentlyContinue).HwSchMode -eq 2 }
function Test-MouseFix        { (Get-ItemProperty "HKCU:\Control Panel\Mouse" -Name MouseSpeed -EA SilentlyContinue).MouseSpeed -eq "0" }
function Test-XboxDvr         { (Get-ItemProperty "HKCU:\System\GameConfigStore" -Name GameDVR_Enabled -EA SilentlyContinue).GameDVR_Enabled -eq 0 }
function Test-Nagle { $previousError = $Error[0]; $target = Get-ActiveAdapterIfacePath; if (-not $target) { if (-not [object]::ReferenceEquals($Error[0],$previousError) -and $Error[0].CategoryInfo.Category -ne 'ObjectNotFound') { throw 'Could not check network applicability.' }; return $null }; (Get-ItemProperty $target -Name TcpAckFrequency -EA SilentlyContinue).TcpAckFrequency -eq 1 }
function Test-NetworkThrottle { [uint32](Get-ItemProperty "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile" -Name NetworkThrottlingIndex -EA SilentlyContinue).NetworkThrottlingIndex -eq [uint32]0xFFFFFFFF }
function Test-MMCSS           { (Get-ItemProperty "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile" -Name SystemResponsiveness -EA SilentlyContinue).SystemResponsiveness -le 10 }
function Test-PowerThrottle   { (Get-ItemProperty "HKLM:\SYSTEM\CurrentControlSet\Control\Power\PowerThrottling" -Name PowerThrottlingOff -EA SilentlyContinue).PowerThrottlingOff -eq 1 }
function Test-FSO             { (Get-ItemProperty "HKCU:\System\GameConfigStore" -Name GameDVR_FSEBehavior -EA SilentlyContinue).GameDVR_FSEBehavior -eq 2 }
# Fast scheduled task check. Get-ScheduledTask takes about 0.8 s per call on a normal PC and was called many times per page;
# the Task Scheduler service answers in a few milliseconds. Falls back to the cmdlet if the service cannot be reached.
$script:SrTaskService = $null
function Test-SrTaskExists {
    param([string]$Name)
    try {
        if (-not $script:SrTaskService) { $svc = New-Object -ComObject 'Schedule.Service'; $svc.Connect(); $script:SrTaskService = $svc }
        try { $null = $script:SrTaskService.GetFolder('\').GetTask($Name); return $true }
        catch { $ex = $_.Exception; $hr = 0; try { $hr = $ex.HResult; if ($ex.InnerException) { $hr = $ex.InnerException.HResult } } catch {}; if ($hr -eq -2147024894 -or $hr -eq -2147024893) { return $false }; throw }
    } catch {
        $script:SrTaskService = $null
        return ($null -ne (Get-ScheduledTask -TaskName $Name -EA SilentlyContinue))
    }
}
function Test-TimerResolution { Test-SrTaskExists 'StreamReady_TimerRes' }
function Test-DisableFastStartup { (Get-ItemProperty "HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Power" -Name HiberbootEnabled -EA SilentlyContinue).HiberbootEnabled -eq 0 }
function Test-NicPowerSaving {
    $ErrorActionPreference = 'Stop'
    $net = Get-NetworkAdapterStatus
    $a = if ($net.EthAdapter) { $net.EthAdapter } else { $net.WifiAdapter }
    if (-not $a) { return $null }
    $previousError = $Error[0]
    $sub = Get-NicDriverSubkey -InterfaceGuid $a.InterfaceGuid
    if (-not $sub) {
        if (-not [object]::ReferenceEquals($Error[0],$previousError) -and $Error[0].CategoryInfo.Category -in @('PermissionDenied','SecurityError','ResourceUnavailable')) { throw 'Could not check network driver applicability.' }
        return $null
    }
    $readErrors = @()
    $value = Get-ItemProperty $sub -Name PnPCapabilities -EA SilentlyContinue -ErrorVariable readErrors
    if (@($readErrors | Where-Object { $_.CategoryInfo.Category -ne 'ObjectNotFound' }).Count -gt 0) { throw 'Could not read network power status.' }
    $value.PnPCapabilities -eq 24
}
function Test-NicEeeDisable {
    $ErrorActionPreference = 'Stop'
    $net = Get-NetworkAdapterStatus
    if (-not $net.EthAdapter) { return $null }
    $p = Get-NetAdapterAdvancedProperty -Name $net.EthAdapter.Name -EA Stop |
         Where-Object { $_.DisplayName -match 'Energy.?Efficient.?Ethernet|Green Ethernet|EEE' } | Select-Object -First 1
    if (-not $p) { return $null }
    return ($p.DisplayValue -eq 'Disabled')
}
function Test-GpuNvULL {
    if ($script:GpuVendor -ne "nvidia") { return $false }
    $path = Get-HkuPath "SOFTWARE\NVIDIA Corporation\Global\NvTweak"
    if (-not $path) { return $false }
    (Get-ItemProperty $path -Name PreRenderedFrames -EA SilentlyContinue).PreRenderedFrames -eq 1
}
function Test-GpuAmdAntiLag {
    if ($script:GpuVendor -ne "amd") { return $false }
    if (-not $script:GpuSubkey) { return $null }
    (Get-ItemProperty $script:GpuSubkey -Name KMD_EnableAntiLag -EA SilentlyContinue).KMD_EnableAntiLag -eq 1
}

# Master badge list: [DisplayName, Test-Function]
$script:BadgeTests = @(
    @{ Label="Game Mode";       Fn={ Test-GameMode };        CheckboxName='ChkGameMode' }
    @{ Label="HAGS";            Fn={ Test-HwGpu };           CheckboxName='ChkHwGpu' }
    @{ Label="Mouse Fix";       Fn={ Test-MouseFix };        CheckboxName='ChkMouseFix' }
    @{ Label="No Xbox DVR";     Fn={ Test-XboxDvr };         CheckboxName='ChkXboxDvr' }
    @{ Label="No Nagle";        Fn={ Test-Nagle };           CheckboxName='ChkNaglesAlgo' }
    @{ Label="Net Throttle";    Fn={ Test-NetworkThrottle }; CheckboxName='ChkNetworkThrottle' }
    @{ Label="MMCSS";           Fn={ Test-MMCSS };           CheckboxName='ChkMMCSS' }
    @{ Label="No Pwr Throttle"; Fn={ Test-PowerThrottle };   CheckboxName='ChkPowerThrottle' }
    @{ Label="FSO Off";         Fn={ Test-FSO };             CheckboxName='ChkFSO' }
    @{ Label="Timer 0.5ms";     Fn={ Test-TimerResolution }; CheckboxName='ChkTimerRes' }
    @{ Label="Fast Startup Off"; Fn={ Test-DisableFastStartup }; CheckboxName='ChkDisableFastStartup' }
    @{ Label="NIC Power Save Off"; Fn={ Test-NicPowerSaving }; CheckboxName='ChkNicPowerSaving' }
    @{ Label="EEE Off";          Fn={ Test-NicEeeDisable }; CheckboxName='ChkNicEeeDisable' }
    @{ Label="Nvidia ULL";      Fn={ Test-GpuNvULL };        CheckboxName='ChkGpuNvULL' }
    @{ Label="AMD Anti-Lag+";   Fn={ Test-GpuAmdAntiLag };   CheckboxName='ChkGpuAmdAntiLag' }
)

function Load-ActiveBadges {
    $c['PanelActiveBadges'].Children.Clear()
    $activeTests = [System.Collections.Generic.List[object]]::new()
    $script:SetupScoreNotApplicableIds = @()
    $script:SetupScoreApplicableIds = @()
    foreach ($test in $script:BadgeTests) {
        try {
            $status = & $test.Fn
            if ($null -eq $status) { if ($test.CheckboxName) { $script:SetupScoreNotApplicableIds += $test.CheckboxName } }
            elseif ($status -eq $true) { $activeTests.Add($test); if ($test.CheckboxName) { $script:SetupScoreApplicableIds += $test.CheckboxName } }
            elseif ($test.CheckboxName -and (Test-ScoreCapabilityProbe $test.CheckboxName)) { $script:SetupScoreApplicableIds += $test.CheckboxName }
        } catch { } # A failed status read is unknown, not evidence of absence.
    }

    $totalTweaks = try { $tweakBoxes.Count } catch { 0 }
    $c['LblActiveOptHeader'].Text = "ACTIVE OPTIMISATIONS - $(@($activeTests).Count) OF $totalTweaks"

    foreach ($test in $activeTests) {
        # Read-only status row: label + a toggle-switch-styled indicator (always "on" -
        # this list only ever shows tweaks whose Test-* companion reports active). Mirrors
        # the Chk toggle-switch style in Window.Resources so the Dashboard summary matches
        # the same visual language as every tweak checkbox elsewhere in the app.
        $row = New-Object System.Windows.Controls.Grid
        $row.Margin = [System.Windows.Thickness]::new(0,4,10,4)
        $colLabel = New-Object System.Windows.Controls.ColumnDefinition
        $colLabel.Width = [System.Windows.GridLength]::new(1, [System.Windows.GridUnitType]::Star)
        $colSwitch = New-Object System.Windows.Controls.ColumnDefinition
        $colSwitch.Width = [System.Windows.GridLength]::Auto
        $row.ColumnDefinitions.Add($colLabel)
        $row.ColumnDefinitions.Add($colSwitch)

        $lbl = New-Object System.Windows.Controls.TextBlock
        $lbl.Text          = $test.Label
        $lbl.FontSize       = 11
        $lbl.Foreground     = [System.Windows.Media.SolidColorBrush][System.Windows.Media.ColorConverter]::ConvertFromString("#c9c7d6")
        $lbl.VerticalAlignment = 'Center'
        [System.Windows.Controls.Grid]::SetColumn($lbl, 0)
        $row.Children.Add($lbl) | Out-Null

        $track = New-Object System.Windows.Controls.Border
        $track.Width  = 26; $track.Height = 14
        $track.CornerRadius = [System.Windows.CornerRadius]::new(7)
        $trackBrush = New-Object System.Windows.Media.LinearGradientBrush
        $trackBrush.StartPoint = [System.Windows.Point]::new(0,0)
        $trackBrush.EndPoint   = [System.Windows.Point]::new(1,1)
        $trackBrush.GradientStops.Add([System.Windows.Media.GradientStop]::new(
            [System.Windows.Media.ColorConverter]::ConvertFromString("#8b6dff"), 0))
        $trackBrush.GradientStops.Add([System.Windows.Media.GradientStop]::new(
            [System.Windows.Media.ColorConverter]::ConvertFromString("#6d4eea"), 1))
        $track.Background = $trackBrush
        $thumb = New-Object System.Windows.Controls.Border
        $thumb.Width  = 10; $thumb.Height = 10
        $thumb.CornerRadius = [System.Windows.CornerRadius]::new(5)
        $thumb.Background = [System.Windows.Media.SolidColorBrush]::new([System.Windows.Media.Colors]::White)
        $thumb.HorizontalAlignment = 'Right'
        $thumb.Margin = [System.Windows.Thickness]::new(0,0,1,0)
        $track.Child = $thumb
        [System.Windows.Controls.Grid]::SetColumn($track, 1)
        $row.Children.Add($track) | Out-Null

        $c['PanelActiveBadges'].Children.Add($row) | Out-Null
    }
    $script:SetupScoreActiveIds = @($activeTests | Where-Object { $_.CheckboxName } | ForEach-Object { $_.CheckboxName })
    $script:SetupScoreReady = $true
    Sync-ScoreAvailability -DeferSave
    Update-HomeScore
}

# ─── Tweak-drift detection ──────────────────────────────────────────────────────
# Windows Update (and some driver reinstalls) can silently revert a subset of these
# registry tweaks after they were applied. The undo stack itself doesn't help here since
# it clears when the app closes (README: "session undo stack clears when you close the
# app") - this persists which tweaks the user has told us to keep active across sessions,
# so we can flag it when live state no longer matches.
$script:AppliedStatePath = "$env:LOCALAPPDATA\StreamReady\applied_state_oss.json"   # this edition's own file (the paid app keeps applied_state.json)

function Save-AppliedTweakState {
    param([string[]]$Names)
    if (-not $Names -or @($Names).Count -eq 0) { return }
    try {
        $existing = if (Test-Path $script:AppliedStatePath) {
            @(Get-Content $script:AppliedStatePath -Raw -EA Stop | ConvertFrom-Json)
        } else { @() }
        $merged = @($existing + @($Names)) | Select-Object -Unique
        $dir = Split-Path $script:AppliedStatePath
        if (-not (Test-Path $dir)) { New-Item $dir -ItemType Directory -Force | Out-Null }
        $merged | ConvertTo-Json | Set-Content -Path $script:AppliedStatePath -Encoding UTF8
    } catch { Write-SR "Could not persist applied-tweak state: $_" 'WARN' }
}

function Remove-AppliedTweakState {
    param([string[]]$Names)
    if (-not $Names -or -not (Test-Path $script:AppliedStatePath)) { return }
    try {
        $existing  = @(Get-Content $script:AppliedStatePath -Raw -EA Stop | ConvertFrom-Json)
        $remaining = @($existing | Where-Object { $_ -notin $Names })
        ConvertTo-Json -InputObject $remaining | Set-Content -Path $script:AppliedStatePath -Encoding UTF8
    } catch { Write-SR "Could not update applied-tweak state: $_" 'WARN' }
}

# Returns the checkbox names that were previously applied (per the persisted state) but
# whose Test-* companion now reports inactive. Only covers the tweaks in $script:BadgeTests
# that have a CheckboxName - persisted names outside that set are stored (for forward
# compatibility as more Test-* companions are added) but silently skipped here, not
# claimed as verified.
function Get-DriftedTweaks {
    try {
        if (-not (Test-Path $script:AppliedStatePath)) { return @() }
        $applied = @(Get-Content $script:AppliedStatePath -Raw -EA Stop | ConvertFrom-Json)
        if (-not $applied) { return @() }
        $checkable = $script:BadgeTests | Where-Object { $_.CheckboxName -and $_.CheckboxName -in $applied }
        $drifted = foreach ($test in $checkable) {
            $active = try { & $test.Fn } catch { $false }
            if (-not $active) { $test.CheckboxName }
        }
        return @($drifted)
    } catch { return @() }
}

