# ─── Shared restore-point helper - used before every Apply so a failure always gets
# a clear, specific, user-facing reason instead of a silent generic skip ────────────
$script:LastRestorePointOk = $null
function New-StreamReadyRestorePoint {
    param([string]$Description = "StreamReady Before Tweaks", [switch]$AllowEnable)
    try {
        if ($AllowEnable) { Enable-ComputerRestore -Drive "C:\" -EA SilentlyContinue }
        Checkpoint-Computer -Description $Description -RestorePointType "MODIFY_SETTINGS" -EA Stop
        Write-SR "Restore point created successfully" 'OK'
        $script:LastRestorePointOk = $true
        return @{ Ok = $true; Message = "Restore point created." }
    } catch {
        $exMsg = $_.Exception.Message
        Write-SR "Restore point creation failed: $exMsg" 'WARN'
        if ($exMsg -match 'disabled|turned off|not enabled') {
            $friendly = "System Restore is turned off on this PC, so no restore point was created before this change. To turn it on: search Windows for 'Create a restore point' > System Protection tab > select drive C: > Configure > Turn on system protection."
        } elseif ($exMsg -match '24 hours|one.*recent|frequency') {
            $friendly = "A restore point from within the last 24 hours already exists, so Windows didn't create a new one - your existing one still covers this change."
        } else {
            $friendly = "Could not create a System Restore point ($exMsg). Continuing without one - you can create one manually by searching Windows for 'Create a restore point'."
        }
        $script:LastRestorePointOk = $false
        return @{ Ok = $false; Message = $friendly }
    }
}

# ─── Shared apply-batch engine - used by both "Apply Selected" and the Dashboard's
# "Reapply" button for drifted tweaks, so both go through one tested code path ─────────
function Invoke-TweakBatch {
    param([string[]]$Names)
    $Names = @($Names)
    if ($Names.Count -eq 0) { return }

    Working 5 "Creating restore point..."
    $rp = New-StreamReadyRestorePoint -Description "StreamReady Before Tweaks"
    if (-not $rp.Ok -and $rp.Message -notmatch '^A restore point from within') {
        [System.Windows.MessageBox]::Show($rp.Message, "StreamReady - Restore Point", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Warning) | Out-Null
    }

    $undoBatch = [ordered]@{}
    $script:PartialNotes = @{}
    $total = $Names.Count; $i = 0
    $successCount = 0; $skipCount = 0; $failCount = 0
    $skipped = [System.Collections.Generic.List[string]]::new()
    $failed  = [System.Collections.Generic.List[string]]::new()
    Write-SR "Applying $total tweak$(if($total -ne 1){'s'})" 'INFO'

    foreach ($name in $Names) {
        $i++
        $label = if ($c[$name]) { $c[$name].Content } else { $name }
        Working ([int]($i / $total * 95)) "Applying: $label..."
        Write-SR "[$i/$total] $label" 'APPLY'
        try {
            if (-not $dispatch.ContainsKey($name) -or -not $dispatch[$name]) {
                $skipCount++; $skipped.Add($label)
                Write-SR "$label skipped - not applicable to this PC" 'WARN'
                if ($c[$name]) { try { $c[$name].IsChecked = $false } catch {} }
                continue
            }
            $pre = $null
            if (Get-Command Get-TweakOriginalState -ErrorAction SilentlyContinue) {
                try { $pre = Get-TweakOriginalState $name } catch {
                    if ($script:UndoSpecs.ContainsKey($name)) {
                        $failCount++; $failed.Add($label); $script:PartialNotes[$name] = 'notapplied'
                        Write-SR "$label was not applied: its current value could not be read exactly ($($_.Exception.Message))" 'FAIL'
                        if ($c[$name]) { try { $c[$name].IsChecked = $false } catch {} }
                        continue
                    }
                    Write-SR "Could not record the original state of $label, using the built-in undo: $($_.Exception.Message)" 'WARN'
                }
            }
            $undo = & $dispatch[$name]
            if ($undo -and $name -eq 'ChkGpuNvNpiProfile') { $undo = New-ManualRecoveryUndo $undo }
            if ($undo -and $pre) { $undo = New-TweakRestoreUndo $name $pre; Save-UndoRecord $name $pre }
            if ($undo) {
                $undoBatch[$name] = $undo
                $successCount++
            } else {
                $skipCount++
                $skipped.Add($label)
                Write-SR "$label skipped - precondition not met (see log above)" 'WARN'
            }
        } catch {
            $failCount++
            $failed.Add($label)
            Write-SR "$label failed: $_" 'FAIL'
            $c['LogText'].Text = "Warning: $label failed - $_"
            Invoke-PartialRecovery $name $pre $label
        }
        if ($c[$name]) { try { $c[$name].IsChecked = $false } catch {} }
    }

    if ($undoBatch.Count -gt 0) {
        $script:UndoStack.Push($undoBatch)
        $c['BtnUndoLast'].IsEnabled = $true
        $c['BtnUndoLast'].Content   = "↩  Undo Last Batch ($($undoBatch.Count) tweak$(if($undoBatch.Count -ne 1){'s'}))"
        Save-AppliedTweakState -Names @($undoBatch.Keys)
    }

    Update-Count
    # keep a record of this batch for the What changed and History pages (additive, the engine itself is unchanged).
    # The stack holds a hashtable copy of the batch, so keep that object.
    $script:LastBatchResult = @{ Time = [datetime]::Now; Names = @($Names); Batch = $(if ($undoBatch.Count -gt 0) { $script:UndoStack.Peek() } else { $undoBatch }); Failed = @($failed); Skipped = @($skipped) }
    $parts = [System.Collections.Generic.List[string]]::new()
    if ($successCount -gt 0) { $parts.Add("$successCount applied") }
    if ($skipCount -gt 0)    { $parts.Add("$skipCount skipped") }
    if ($failCount -gt 0)    { $parts.Add("$failCount failed") }
    $summary = $parts -join ", "

    if ($skipCount -gt 0) { Write-SR "Skipped: $($skipped -join ', ')" 'WARN' }
    if ($failCount -gt 0) { Write-SR "Failed: $($failed -join ', ')" 'FAIL' }

    if ($failCount -eq 0 -and $skipCount -eq 0) {
        Done "$summary."
        Write-SR "All done! $summary." 'SECTION'
    } elseif ($successCount -gt 0) {
        Set-Progress 100 "$summary - check log for details." "#f0b545"
        Write-SR "Batch finished with issues: $summary." 'SECTION'
    } else {
        Fail "$summary - check log for details."
        Write-SR "Batch finished with issues: $summary." 'SECTION'
    }
}

# ─── Apply All Selected ────────────────────────────────────────────────────────
$c['BtnApplyAll'].Add_Click({
    $selected = @($tweakBoxes | Where-Object { $c[$_].IsChecked })
    if ($selected.Count -eq 0) { return }
    Write-SR "StreamReady - Applying Selected Tweaks" 'SECTION'
    $script:ScoreBeforeBatch = Get-SetupScore
    Invoke-TweakBatch -Names $selected
})

# ─── Reapply drifted tweaks (Dashboard drift banner) ───────────────────────────
$c['BtnReapplyDrifted'].Add_Click({
    $names = @($script:_DriftedTweaks)
    if ($script:SrSettings -and $script:SrSettings.safeMode) {
        $keep = @($names | Where-Object { (Get-TweakRisk $_) -eq 'S' })
        if ($keep.Count -lt $names.Count) { $c['LogText'].Text = 'Safe Mode is on, so only the Safe settings were reapplied. Turn Safe Mode off in Settings to reapply the rest.' }
        $names = $keep
    }
    if ($names.Count -eq 0) { return }
    Write-SR "StreamReady - Reapplying $($names.Count) Drifted Tweak$(if($names.Count -ne 1){'s'})" 'SECTION'
    $c['BannerDriftDetected'].Visibility = 'Collapsed'
    $script:LastBatchResult = $null
    $script:LastRestorePointOk = $null
    $script:UndoSaveFailed = $false
    $script:SrApplying = $true
    $script:ScoreBeforeBatch = Get-SetupScore
    try { Invoke-TweakBatch -Names $names } finally { $script:SrApplying = $false }
    Complete-Batch $script:LastBatchResult $names $false
})

# ─── Undo Last Batch ───────────────────────────────────────────────────────────
$c['BtnUndoLast'].Add_Click({
    if ($script:UndoStack.Count -eq 0) { return }
    $script:HomeLastLoad = [datetime]::MinValue
    $scoreBeforeUndo = Get-SetupScore
    $batch = $script:UndoStack.Pop()
    $total = $batch.Count; $i = 0
    Write-SR "StreamReady - Undoing Last Batch ($total tweak$(if($total -ne 1){'s'}))" 'SECTION'
    Working 10 "Undoing $total tweak$(if($total -ne 1){'s'})..."
    $undoKeys = @($batch.Keys)
    [array]::Reverse($undoKeys)
    $okKeys = @(); $failKeys = @()
    foreach ($key in $undoKeys) {
        $i++
        # Undo batch keys are either a real checkbox name (looked up in $c for its label)
        # or a synthetic '__Name__'-wrapped key for undo entries with no checkbox behind
        # them (AMD/Intel CPU tweaks, WiFi mode, etc.) - any future
        # synthetic key MUST use this '__...__' convention or it will silently fall
        # through to $c[$key] and show a blank label instead of crashing.
        $label = if ($key.StartsWith('__')) { $key.Trim('_') }
                 elseif ($c[$key])          { $c[$key].Content }
                 else                       { $key }
        Working ([int]($i / $total * 95)) "Undoing: $label..."
        Write-SR "[$i/$total] Reversing: $label" 'UNDO'
        try { & $batch[$key]; $okKeys += $key } catch { $failKeys += $key; Write-SR "Undo failed for $label`: $_" 'FAIL' }
    }
    # only the reversals that worked leave the batch; failed ones stay (same batch object) so they can be retried
    foreach ($k in $okKeys) { $batch.Remove($k) }
    Remove-AppliedTweakState -Names @($okKeys)
    Load-ActiveBadges
    Set-ScoreChange $script:CurrentEntry $scoreBeforeUndo (Get-SetupScore)
    $script:LastUndoFailed = @($failKeys)
    if ($failKeys.Count -gt 0) { $script:UndoStack.Push($batch) }
    if ($script:UndoStack.Count -eq 0) {
        $c['BtnUndoLast'].IsEnabled = $false
        $c['BtnUndoLast'].Content   = "↩  Undo Last Batch"
    } else {
        $n = ($script:UndoStack.Peek()).Count
        $c['BtnUndoLast'].Content = "↩  Undo Last Batch ($n tweak$(if($n -ne 1){'s'}))"
    }
    if ($failKeys.Count -gt 0) {
        $msg = "Undo incomplete - $($okKeys.Count) reversed, $($failKeys.Count) could not be undone. They stay in the list so you can try again."
        Fail $msg
        Write-SR $msg 'FAIL'
    } else {
        $msg = "Undo complete - $total tweak$(if($total -ne 1){'s'}) reversed."
        Done $msg
        Write-SR $msg 'SECTION'
    }
})
#endregion Apply Engine

#region Dashboard Handlers

function Load-Dashboard {
    $script:DashboardLoaded = $true

    # Identity labels - model name / capacity never change during a session, so these are
    # set once here rather than on every metrics tick. The live numbers (temp/load/usage/
    # ping) are handled separately by Update-DashboardMetrics, called immediately below and
    # then repeated on a timer so the stat tiles actually show a moving trend, not one
    # static sample per Dashboard visit.
    try {
        $cpu = Get-CachedCim Win32_Processor | Select-Object -First 1
        $cpuName = ($cpu.Name -replace '\(R\)|\(TM\)|CPU|@.*','').Trim()
        $c['LblDashCpuLabel'].Text = "CPU · $cpuName"
        $c['LblDashCpuSub'].Text   = "$([math]::Round($cpu.MaxClockSpeed/1000,1)) GHz · $($cpu.NumberOfCores) cores"
    } catch { $c['LblDashCpuLabel'].Text = "CPU" }

    $gpuName = if ($script:GpuName -ne "No discrete GPU detected") {
        ($script:GpuName -replace 'NVIDIA GeForce|AMD Radeon','').Trim()
    } else { "None detected" }
    $c['LblDashGpuLabel'].Text = "GPU · $gpuName"

    try {
        $ramGB = [math]::Round(((Get-CachedCim Win32_PhysicalMemory | Measure-Object Capacity -Sum).Sum / 1GB))
        $c['LblDashRamLabel'].Text = "RAM · ${ramGB}GB"
    } catch { $c['LblDashRamLabel'].Text = "RAM" }

    Update-DashboardMetrics
    if (Get-Command Start-DashboardMetricsTimer -ErrorAction SilentlyContinue) { Start-DashboardMetricsTimer }

    # Timer resolution status
    $timerTaskExists = Test-SrTaskExists 'StreamReady_TimerRes'
    $c['BannerTimerActive'].Visibility  = if ($timerTaskExists) { 'Visible' } else { 'Collapsed' }
    $c['BannerTimerDefault'].Visibility = if ($timerTaskExists) { 'Collapsed' } else { 'Visible' }

    # Active badges (defined in Task 14)
    if (Get-Command Load-ActiveBadges -ErrorAction SilentlyContinue) { Load-ActiveBadges }


    # Tweak drift check - flags tweaks that were applied in a previous session but whose
    # Test-* companion now reports inactive (typically reset by a Windows Update)
    $script:_DriftedTweaks = Get-DriftedTweaks
    if ($script:_DriftedTweaks.Count -gt 0) {
        $driftLabels = $script:_DriftedTweaks | ForEach-Object { if ($c[$_]) { $c[$_].Content } else { $_ } }
        $c['LblDriftTitle'].Text  = "⚠ $($script:_DriftedTweaks.Count) tweak$(if($script:_DriftedTweaks.Count -ne 1){'s'}) reset since last applied"
        $c['LblDriftDetail'].Text = "$($driftLabels -join ', ') - likely reverted by a Windows Update."
        $c['BannerDriftDetected'].Visibility = 'Visible'
    } else {
        $c['BannerDriftDetected'].Visibility = 'Collapsed'
    }

    # The health report (storage, drivers, display, clock) is slow, so it is loaded when My PC or the System page opens (Ensure-SystemDetails), not here.
}

# Async ping. Three fix attempts on the previous Test-Connection-in-a-runspace approach
# (explicit default session state, defensive try/catch, skip-if-in-flight) didn't resolve
# it, which points at the PowerShell cmdlet/runspace layer itself being unreliable in this
# compiled-exe host - so this cuts that layer out entirely and calls .NET's own async ping
# API directly (System.Net.NetworkInformation.Ping, part of the base framework, no cmdlet
# resolution involved at all). Simpler and inherently more reliable for exactly this reason.
function Start-DashboardPing {
    if ($script:_PingHandle -and -not $script:_PingHandle.IsCompleted) { return }
    if ($script:_PingTimer -and $script:_PingTimer.IsEnabled) { $script:_PingTimer.Stop() }
    if ($script:_Pinger) { try { $script:_Pinger.Dispose() } catch {} }

    try {
        $script:_Pinger = New-Object System.Net.NetworkInformation.Ping
        $script:_PingHandle = $script:_Pinger.SendPingAsync('8.8.8.8', 2000)
    } catch {
        $c['LblDashPing'].Text = "-"
        Write-SR "Dashboard ping failed to start: $($_.Exception.Message)" 'WARN'
        return
    }

    $script:_PingTimer = New-Object System.Windows.Threading.DispatcherTimer
    $script:_PingTimer.Interval = [TimeSpan]::FromMilliseconds(200)
    $script:_PingTimer.Add_Tick({
        if ($script:_PingHandle.IsCompleted) {
            $script:_PingTimer.Stop()
            try {
                $reply = $script:_PingHandle.GetAwaiter().GetResult()
                if ($reply.Status -eq [System.Net.NetworkInformation.IPStatus]::Success) {
                    $ms = $reply.RoundtripTime
                    $c['LblDashPing'].Text = "${ms}ms"
                    $colour = if ($ms -lt 50) { "#56dd92" } else { "#edecf3" }
                    $c['LblDashPing'].Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString($colour)
                    if (Get-Command Update-Sparkline -ErrorAction SilentlyContinue) {
                        Update-Sparkline -Key 'ping' -Value $ms -Polyline $c['SparkPing']
                    }
                } else {
                    $c['LblDashPing'].Text = "timeout"
                    $c['LblDashPing'].Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#edecf3")
                }
            } catch {
                $c['LblDashPing'].Text = "-"
                Write-SR "Dashboard ping failed: $($_.Exception.Message)" 'WARN'
            } finally {
                try { $script:_Pinger.Dispose() } catch {}
            }
        }
    })
    $script:_PingTimer.Start()
}

# Live stat-tile values (temp/load/usage/ping) + their sparklines. Called once immediately
# when the Dashboard loads, then repeated on a timer (started/stopped alongside the
# Dashboard section itself) so the tiles show an actual moving trend instead of a single
# static sample per visit.
function Update-DashboardMetrics {
    # CPU - real package temperature when a hardware-monitor tool exposes it, otherwise
    # the always-available LoadPercentage (a plain WMI property, not a perf counter, so
    # cheap enough to poll repeatedly).
    try {
        $cpuTemp = Get-CpuTemp
        $fastLoad = if ($null -eq $cpuTemp) { Get-CpuLoadFast } else { $null }
        $cpu = $null
        if ($null -eq $cpuTemp -and $null -eq $fastLoad) { $cpu = Get-CachedCim Win32_Processor -Live -TtlSeconds 3 | Select-Object -First 1 }   # slow (about 1 s), only if the fast reading is not available
        if ($null -ne $cpuTemp) {
            $c['LblDashCpu'].Text = "$cpuTemp°C"
            Update-Sparkline -Key 'cpu' -Value $cpuTemp -Polyline $c['SparkCpu']
        } elseif ($null -ne $fastLoad) {
            $c['LblDashCpu'].Text = "$fastLoad%"
            Update-Sparkline -Key 'cpu' -Value $fastLoad -Polyline $c['SparkCpu']
        } elseif ($null -ne $cpu.LoadPercentage) {
            $c['LblDashCpu'].Text = "$($cpu.LoadPercentage)%"
            Update-Sparkline -Key 'cpu' -Value $cpu.LoadPercentage -Polyline $c['SparkCpu']
        } else {
            # LoadPercentage isn't populated on every system - fall back to computing real
            # load from raw perf counters (needs one extra tick to produce its first value).
            $computedLoad = Get-CpuLoadPercent
            if ($null -ne $computedLoad) {
                $c['LblDashCpu'].Text = "$computedLoad%"
                Update-Sparkline -Key 'cpu' -Value $computedLoad -Polyline $c['SparkCpu']
            } else {
                $c['LblDashCpu'].Text = "N/A"
            }
        }
    } catch {}

    # GPU temperature (nvidia-smi, or LibreHardwareMonitor/OpenHardwareMonitor for AMD).
    try {
        $gpuTemp = Get-GpuTemp
        if ($null -ne $gpuTemp) {
            $c['LblDashGpu'].Text = "$gpuTemp°C"
            Update-Sparkline -Key 'gpu' -Value $gpuTemp -Polyline $c['SparkGpu']
        } else {
            $c['LblDashGpu'].Text = "N/A"
        }
    } catch {}
    # RAM - live usage % (Win32_OperatingSystem's Total/FreePhysicalMemory are plain
    # properties, not a perf counter, so cheap enough to poll repeatedly).
    try {
        $ramSpeed = (Get-CachedCim Win32_PhysicalMemory -TtlSeconds 3 | Select-Object -First 1).ConfiguredClockSpeed
        $os       = Get-CachedCim Win32_OperatingSystem -TtlSeconds 3
        $usedPct  = [math]::Round((($os.TotalVisibleMemorySize - $os.FreePhysicalMemory) / $os.TotalVisibleMemorySize) * 100)
        $c['LblDashRam'].Text    = "$usedPct%"
        $c['LblDashRamSub'].Text = if ($ramSpeed -and $ramSpeed -gt 0) { "@ $ramSpeed MHz" } else { "" }
        Update-Sparkline -Key 'ram' -Value $usedPct -Polyline $c['SparkRam']
    } catch { $c['LblDashRam'].Text = "Unknown" }

    if (Get-Command Start-DashboardPing -ErrorAction SilentlyContinue) { Start-DashboardPing }
}

function Start-DashboardMetricsTimer {
    if ($script:_DashMetricsTimer -and $script:_DashMetricsTimer.IsEnabled) { return }
    $script:_DashMetricsTimer = New-Object System.Windows.Threading.DispatcherTimer
    $script:_DashMetricsTimer.Interval = [TimeSpan]::FromSeconds(4)
    $script:_DashMetricsTimer.Add_Tick({ Update-DashboardMetrics })
    $script:_DashMetricsTimer.Start()
}
function Stop-DashboardMetricsTimer {
    if ($script:_DashMetricsTimer) { $script:_DashMetricsTimer.Stop() }
}

# Dashboard quick preset buttons
$c['BtnDashPresetGaming'].Add_Click({
