#region Gaming Handlers
# ─── Presets ───────────────────────────────────────────────────────────────────
# ─── Shared preset building blocks ─────────────────────────────────────────────
# The "safe" core: strong gaming/latency performance with no visible usability
# loss and no security tradeoff. Base of every preset.
function Get-SafeGamingTweakSet {
    @(
        'ChkGameMode','ChkHighPerf','ChkHwGpu','ChkMouseFix','ChkXboxDvr','ChkFSO','ChkStickyKeys',
        'ChkQoS','ChkMMCSS','ChkNetworkThrottle','ChkNaglesAlgo','ChkPowerThrottle','ChkGamesMMCSS',
        'ChkVRR','ChkWindowedGameOpt','ChkTimerRes',
        'ChkAudioLatency','ChkUsbSuspend','ChkNicLatency',
        'ChkCoreParkingDisable','ChkWin32Priority','ChkAhciLpmOff','ChkTcpGameTweaks','ChkNicIntMod','ChkPcieAspm','ChkNtfsOpt',
        'ChkNicPowerSaving','ChkNicEeeDisable'
    )
}
# Ticks the GPU-vendor-specific checkboxes for whichever set matches the detected vendor.
function Select-GpuVendorTweaks {
    param([string[]]$NvidiaTweaks, [string[]]$AmdTweaks)
    if ($script:GpuVendor -eq "nvidia") {
        foreach ($n in $NvidiaTweaks) { if ($c[$n]) { $c[$n].IsChecked = $true } }
    } elseif ($script:GpuVendor -eq "amd") {
        foreach ($n in $AmdTweaks) { if ($c[$n]) { $c[$n].IsChecked = $true } }
    }
}
$script:GpuVendorSafeTweaks = @{ Nvidia = @('ChkGpuNvULL','ChkGpuNvThreadedOpt','ChkNvidiaShaderCache'); Amd = @('ChkGpuAmdAntiLag') }

# ─── Gaming Preset: best safe performance, zero usability impact ──────────────
$c['BtnPresetGaming'].Add_Click({
    foreach ($n in $tweakBoxes) { if ($c[$n]) { try { $c[$n].IsChecked = $false } catch {} } }
    foreach ($n in (Get-PresetIds 'gaming')) { if ($c[$n]) { $c[$n].IsChecked = $true } }
    Update-Count
    $c['LogText'].Text = "Gaming Preset selected - review ticks, then hit Apply Selected."
})

# ─── Streaming Preset: best OBS + gaming tweaks, zero usability impact ────────
$c['BtnPresetStreaming'].Add_Click({
    foreach ($n in $tweakBoxes) { if ($c[$n]) { try { $c[$n].IsChecked = $false } catch {} } }
    foreach ($n in (Get-PresetIds 'streaming')) { if ($c[$n]) { $c[$n].IsChecked = $true } }
    Update-Count
    $c['LogText'].Text = "Streaming Preset selected - review ticks, then hit Apply Selected."
})
$c['BtnSelectAll'].Add_Click({
    foreach ($n in $tweakBoxes) {
        if ($n -eq 'ChkAutoHDR' -or -not $c[$n]) { continue }
        if (($n -like 'ChkGpuNv*' -or $n -eq 'ChkNvidiaShaderCache') -and $script:GpuVendor -ne 'nvidia') { continue }
        if ($n -like 'ChkGpuAmd*' -and $script:GpuVendor -ne 'amd') { continue }
        try { $c[$n].IsChecked = $true } catch {}
    }
    Update-Count
})
$c['BtnDeselectAll'].Add_Click({
    foreach ($n in $tweakBoxes) { if ($c[$n]) { try { $c[$n].IsChecked = $false } catch {} } }
    Update-Count
})

# ─── Profile Save / Load: persist or restore a tick selection (never applies anything
# itself - same "tick for review, then Apply Selected" model as every preset) ─────────
$c['BtnSaveProfile'].Add_Click({
    $selected = @($tweakBoxes | Where-Object { $c[$_] -and $c[$_].IsChecked })
    if ($selected.Count -eq 0) { Fail "No tweaks selected - tick some tweaks first."; return }
    $dlg = New-Object Microsoft.Win32.SaveFileDialog
    $dlg.Filter   = "StreamReady Profile (*.streamready.json)|*.streamready.json|All files (*.*)|*.*"
    $dlg.FileName = "MyProfile.streamready.json"
    $dir = "$env:LOCALAPPDATA\StreamReady\Profiles"
    if (-not (Test-Path $dir)) { New-Item $dir -ItemType Directory -Force | Out-Null }
    $dlg.InitialDirectory = $dir
    if ($dlg.ShowDialog() -ne $true) { return }
    try {
        @{ Tweaks = $selected } | ConvertTo-Json | Set-Content -Path $dlg.FileName -Encoding UTF8
        Done "Profile saved - $($selected.Count) tweak$(if($selected.Count -ne 1){'s'})."
        Write-SR "Profile saved to $($dlg.FileName) ($($selected.Count) tweaks)" 'OK'
    } catch {
        Fail "Could not save profile: $_"
        Write-SR "Profile save failed: $_" 'FAIL'
    }
})
$c['BtnLoadProfile'].Add_Click({
    $dlg = New-Object Microsoft.Win32.OpenFileDialog
    $dlg.Filter = "StreamReady Profile (*.streamready.json)|*.streamready.json|All files (*.*)|*.*"
    $dir = "$env:LOCALAPPDATA\StreamReady\Profiles"
    if (Test-Path $dir) { $dlg.InitialDirectory = $dir }
    if ($dlg.ShowDialog() -ne $true) { return }
    try {
        $data     = Get-Content -Path $dlg.FileName -Raw | ConvertFrom-Json
        $wanted   = @($data.Tweaks)
        $names    = @($wanted | Where-Object { $_ -in $tweakBoxes })
        if ($names.Count -eq 0) { Fail "Profile has no recognised tweaks (may be from a different StreamReady version)."; return }
        foreach ($n in $tweakBoxes) { if ($c[$n]) { try { $c[$n].IsChecked = $false } catch {} } }
        foreach ($n in $names) { if ($c[$n]) { $c[$n].IsChecked = $true } }
        Update-Count
        $skipped = $wanted.Count - $names.Count
        $msg = "Profile loaded - $($names.Count) tweak$(if($names.Count -ne 1){'s'}) selected."
        if ($skipped -gt 0) { $msg += " ($skipped not recognised, skipped.)" }
        Done $msg
        Write-SR "Profile loaded from $($dlg.FileName): $($names.Count) applied, $skipped skipped - review ticks, then hit Apply Selected." 'OK'
    } catch {
        Fail "Could not load profile: $_"
        Write-SR "Profile load failed: $_" 'FAIL'
    }
})
#endregion Gaming Handlers

#region System Handlers
# ─── System Info ───────────────────────────────────────────────────────────────
function Load-SysInfo {
    try { $c['TxtCpu'].Text = "CPU: " + (Get-CachedCim Win32_Processor).Name } catch { $c['TxtCpu'].Text = "CPU: Unknown" }
    try { $c['TxtRam'].Text = "RAM: " + [math]::Round((Get-CimInstance Win32_ComputerSystem).TotalPhysicalMemory/1GB,1) + " GB" } catch { $c['TxtRam'].Text = "RAM: Unknown" }
    try { $c['TxtGpu'].Text = "GPU: " + (Get-CachedCim Win32_VideoController | Select-Object -First 1).Name } catch { $c['TxtGpu'].Text = "GPU: Unknown" }
    try { $c['TxtOs'].Text  = "OS: "  + (Get-CimInstance Win32_OperatingSystem).Caption } catch { $c['TxtOs'].Text = "OS: Unknown" }
    try { $plan = powercfg -getactivescheme; $pn = if ($plan -match "\((.+)\)") { $matches[1] } else { $plan }; $c['TxtPowerPlan'].Text = "Power Plan: $pn" } catch { $c['TxtPowerPlan'].Text = "Power Plan: Unknown" }
    try { $up = (Get-Date) - (Get-CimInstance Win32_OperatingSystem).LastBootUpTime; $c['TxtUptime'].Text = "Uptime: $([int]$up.TotalHours)h $($up.Minutes)m" } catch { $c['TxtUptime'].Text = "Uptime: Unknown" }
}
# System details are read the first time My PC, the System page or the Network page opens (they used to be read before the window was usable).
$script:SysBasicLoaded = $false; $script:NetInfoLoaded = $false
function Ensure-SysBasic { if (-not $script:SysBasicLoaded) { $script:SysBasicLoaded = $true; try { Load-SysInfo } catch {}; try { Load-Startup } catch {} } }
function Ensure-NetInfo { if (-not $script:NetInfoLoaded) { $script:NetInfoLoaded = $true; try { Load-NetInfo } catch {} } }
function Ensure-SystemDetails {
    Ensure-SysBasic
    if (Get-Command Load-HealthReport -ErrorAction SilentlyContinue) { try { Load-HealthReport } catch {} }
}

# ---- background preparation: small steps that run only when the window has nothing else to do --------------------------
$script:IdleQueue = [System.Collections.Generic.Queue[scriptblock]]::new()
$script:IdleStop = $false
function Invoke-NextIdleStep {
    if ($script:IdleStop -or $script:IdleQueue.Count -eq 0) { return }
    [void]$window.Dispatcher.BeginInvoke([System.Windows.Threading.DispatcherPriority]::ApplicationIdle, [Action]{
        if ($script:IdleStop) { return }
        if ($script:SrPage -eq 'PageApplying') { $tm = New-Object System.Windows.Threading.DispatcherTimer; $tm.Interval = [TimeSpan]::FromSeconds(1); $tm.Add_Tick({ param($s2, $e2) $s2.Stop(); Invoke-NextIdleStep }); $tm.Start(); return }   # never compete with an Apply
        $s = $null; if ($script:IdleQueue.Count -gt 0) { $s = $script:IdleQueue.Dequeue() }
        if ($s) { try { & $s } catch { try { Write-SR "Background preparation step failed: $($_.Exception.Message)" 'WARN' } catch {} } }
        Invoke-NextIdleStep
    })
}
function Start-StartupPrefetch {
    $steps = @(
        { Ensure-SysBasic },
        { Initialize-ProAreas -Deferred },
        { if (-not $script:TableBuilt) { Refresh-TablePage } },
        { Complete-ProConvert 'everything' },
        { Complete-ProConvert 'gaming' }, { Complete-ProConvert 'graphics' }, { Complete-ProConvert 'network' }, { Complete-ProConvert 'privacy' },
        { Complete-ProConvert 'tweaks' }, { Complete-ProConvert 'updates' }, { Complete-ProConvert 'system' }, { Complete-ProConvert 'games' },
        { Complete-ProConvert 'hardware' }, { Complete-ProConvert 'downloads' },
        { Ensure-NetInfo },
        { [void](Get-DriverHealthInfo) },
        { [void](Get-StorageInfo) },
        { [void](Get-CpuThrottleStatus) },
        { Load-HealthReport }
    )
    foreach ($st in $steps) { $script:IdleQueue.Enqueue($st) }
    Invoke-NextIdleStep
}
function Load-Startup {
    $c['StartupList'].Items.Clear()
    foreach ($p in @("HKCU:\Software\Microsoft\Windows\CurrentVersion\Run","HKLM:\Software\Microsoft\Windows\CurrentVersion\Run")) {
        try {
            $scope = if ($p -match "HKCU") { "User" } else { "System" }
            (Get-ItemProperty $p -EA Stop).PSObject.Properties | Where-Object { $_.Name -notmatch "^PS" } | ForEach-Object { $c['StartupList'].Items.Add("[$scope] $($_.Name)") }
        } catch {}
    }
    if ($c['StartupList'].Items.Count -eq 0) { $c['StartupList'].Items.Add("No startup programs found.") }
}
function Load-NetInfo {
    try { $a = Get-NetAdapter | Where-Object { $_.Status -eq 'Up' } | Select-Object -First 1; $c['TxtAdapter'].Text = "Adapter: $($a.Name) ($($a.LinkSpeed))" } catch { $c['TxtAdapter'].Text = "Adapter: Unknown" }
    try { $dns = (Get-DnsClientServerAddress -AddressFamily IPv4 | Where-Object { $_.ServerAddresses } | Select-Object -First 1).ServerAddresses -join ", "; $c['TxtDns'].Text = "DNS: $dns" } catch { $c['TxtDns'].Text = "DNS: Unknown" }

    # Async ping via a background runspace, same pattern as the Dashboard's own ping
    # (below) - this used to run Test-Connection synchronously right in the window's
    # Add_Loaded handler, blocking first paint on every launch (worse if ICMP is
    # filtered, which times out over several seconds).
    $c['TxtPing'].Text = "Ping (8.8.8.8): checking..."
    if ($script:_NetPingTimer -and $script:_NetPingTimer.IsEnabled) { $script:_NetPingTimer.Stop() }
    if ($script:_NetPingPs) { try { $script:_NetPingPs.Dispose() } catch {} }
    if ($script:_NetPingRs) { try { $script:_NetPingRs.Close(); $script:_NetPingRs.Dispose() } catch {} }

    $script:_NetPingRs = [runspacefactory]::CreateRunspace([initialsessionstate]::CreateDefault())
    $script:_NetPingRs.Open()
    $script:_NetPingPs = [powershell]::Create().AddScript({
        try { (Test-Connection 8.8.8.8 -Count 1 -EA Stop).ResponseTime } catch { $null }
    })
    $script:_NetPingPs.Runspace = $script:_NetPingRs
    $script:_NetPingHandle = $script:_NetPingPs.BeginInvoke()
    $script:_NetPingTimer  = New-Object System.Windows.Threading.DispatcherTimer
    $script:_NetPingTimer.Interval = [TimeSpan]::FromMilliseconds(200)
    $script:_NetPingTimer.Add_Tick({
        if ($script:_NetPingHandle.IsCompleted) {
            $script:_NetPingTimer.Stop()
            try {
                $ping = $script:_NetPingPs.EndInvoke($script:_NetPingHandle)
                if ($null -ne $ping) {
                    $col = if ($ping -lt 50) { "#56dd92" } elseif ($ping -lt 100) { "#f0b545" } else { "#ff6b6b" }
                    $c['TxtPing'].Text = "Ping (8.8.8.8): ${ping}ms"
                    $c['TxtPing'].Foreground = $col
                } else {
                    $c['TxtPing'].Text = "Ping: Failed"
                    $c['TxtPing'].Foreground = "#ff6b6b"
                }
            } catch {
                $c['TxtPing'].Text = "Ping: Failed"
                $c['TxtPing'].Foreground = "#ff6b6b"
            } finally {
                $script:_NetPingPs.Dispose()
                $script:_NetPingRs.Close(); $script:_NetPingRs.Dispose()
            }
        }
    })
    $script:_NetPingTimer.Start()
}

