$c['BtnCleanTemp'].Add_Click({ Invoke-UndoToolClick 'BtnCleanTemp' {
    Working 10 "Cleaning temp files..."; $freed = 0; $i = 0
    $cleanPaths = @(
        $env:TEMP, $env:TMP,
        "$env:SystemRoot\Temp", "$env:LOCALAPPDATA\Temp",
        "$env:SystemRoot\Prefetch",
        "$env:SystemRoot\SoftwareDistribution\Download"
    )
    foreach ($p in $cleanPaths) {
        $i++; Working ([int]($i / $cleanPaths.Count * 90)) "Cleaning $p..."
        if (Test-Path $p) {
            $b = (Get-ChildItem $p -Recurse -Force -EA SilentlyContinue | Measure-Object Length -Sum).Sum
            Remove-Item "$p\*" -Recurse -Force -EA SilentlyContinue
            $after = (Get-ChildItem $p -Recurse -Force -EA SilentlyContinue | Measure-Object Length -Sum).Sum
            $freed += [math]::Max(0, $b - $after)
        }
    }
    Done "Cleaned $([math]::Round($freed/1MB,1)) MB (Temp, Prefetch, WU cache)."
} })
