$c['BtnPagefileOpt'].Add_Click({ Invoke-UndoToolClick 'BtnPagefileOpt' {
    # A fixed small initial pagefile size (the old behaviour here) causes mid-load
    # expansion spikes under heavy memory pressure - this has been observed to cause
    # hard freezes in some games (e.g. Escape from Tarkov). System-managed lets
    # Windows size and grow the pagefile itself, which avoids that failure mode.
    Working 20 "Setting pagefile to System managed..."
    try {
        $cs = Get-CimInstance Win32_ComputerSystem

        # Capture prior state before changing anything, so undo can restore it exactly
        # (auto-managed, a specific fixed size, or no explicit setting at all) rather
        # than guessing - matching the pattern every other Apply-* in this file uses.
        $prevAuto    = [bool]$cs.AutomaticManagedPagefile
        $prevPf      = Get-CimInstance Win32_PageFileSetting -EA SilentlyContinue | Select-Object -First 1
        $prevExisted = $null -ne $prevPf
        $prevName    = if ($prevPf) { $prevPf.Name } else { 'C:\pagefile.sys' }
        $prevInitial = if ($prevPf) { $prevPf.InitialSize } else { 0 }
        $prevMax     = if ($prevPf) { $prevPf.MaximumSize } else { 0 }

        if ($prevAuto) {
            Done "Pagefile is already set to System managed - nothing to change."
            Write-SR "Pagefile already System managed, no change made" 'OK'
            return
        }

        $cs | Set-CimInstance -Property @{ AutomaticManagedPagefile = $true } -EA SilentlyContinue
        Done "Pagefile set to System managed - reboot to apply."
        Write-SR "Pagefile set to System managed" 'OK'

        $nameEsc = $prevName -replace $script:SqPattern, '$&$&'
        $undoScript =
            if ($prevExisted) {
                "try {`n" +
                "    (Get-CimInstance Win32_ComputerSystem) | Set-CimInstance -Property @{ AutomaticManagedPagefile = `$false } -EA SilentlyContinue`n" +
                "    `$p = Get-CimInstance Win32_PageFileSetting -EA SilentlyContinue | Where-Object { `$_.Name -eq '$nameEsc' } | Select-Object -First 1`n" +
                "    if (`$p) { `$p | Set-CimInstance -Property @{ InitialSize = $prevInitial; MaximumSize = $prevMax } -EA SilentlyContinue }`n" +
                "    else { New-CimInstance -ClassName Win32_PageFileSetting -Property @{ Name = '$nameEsc'; InitialSize = $prevInitial; MaximumSize = $prevMax } -EA SilentlyContinue | Out-Null }`n" +
                "} catch {}`n" +
                "Write-SR 'UNDO: Pagefile size restored to previous fixed values (reboot to apply)' 'UNDO'"
            } else {
                "Write-SR 'UNDO: Pagefile was already System managed before this change - nothing to restore' 'UNDO'"
            }
        $script:UndoStack.Push(@{ '__PagefileOpt__' = [scriptblock]::Create($undoScript) })
        $c['BtnUndoLast'].IsEnabled = $true
        $c['BtnUndoLast'].Content   = "↩  Undo Last Batch (Pagefile)"
    } catch {
        Fail "Pagefile change failed: $_"
    }
} })

