using System;
using System.Runtime.InteropServices;
public class MemHelper {
    [DllImport("ntdll.dll")] public static extern int NtSetSystemInformation(int InfoClass, IntPtr Info, int Length);
    public static void FlushStandby() {
        IntPtr val = Marshal.AllocHGlobal(4);
        Marshal.WriteInt32(val, 4); // MemoryPurgeStandbyList
        NtSetSystemInformation(80, val, 4);
        Marshal.FreeHGlobal(val);
    }
}
'@ -EA SilentlyContinue
        [MemHelper]::FlushStandby()
        $freeGB = [math]::Round((Get-CimInstance Win32_OperatingSystem).FreePhysicalMemory / 1MB, 1)
