# ── LSA secret storage ──────────────────────────────────────────────────────────
# Autologon's password used to be written as plaintext to the Winlogon registry key
# (HKLM:\...\Winlogon!DefaultPassword) - readable by any local admin or process, and
# collected via an unmasked VisualBasic InputBox visible on screen while typing.
# Sysinternals' own Autologon.exe avoids both problems: it stores the password as an
# LSA secret (Winlogon transparently reads the DefaultPassword LSA secret if the
# registry value is absent) and uses a masked password field. This mirrors that.
function Register-LsaSecretType {
    if (([System.Management.Automation.PSTypeName]'StreamReadyLsa').Type) { return }
    Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;
public class StreamReadyLsa {
    [StructLayout(LayoutKind.Sequential)]
    public struct LSA_UNICODE_STRING {
        public ushort Length;
        public ushort MaximumLength;
        public IntPtr Buffer;
    }
    [StructLayout(LayoutKind.Sequential)]
    public struct LSA_OBJECT_ATTRIBUTES {
        public int Length;
        public IntPtr RootDirectory;
        public IntPtr ObjectName;
        public uint Attributes;
        public IntPtr SecurityDescriptor;
        public IntPtr SecurityQualityOfService;
    }
    [DllImport("advapi32.dll", SetLastError = true)]
    public static extern uint LsaOpenPolicy(ref LSA_UNICODE_STRING SystemName, ref LSA_OBJECT_ATTRIBUTES ObjectAttributes, int AccessMask, out IntPtr PolicyHandle);

    [DllImport("advapi32.dll", SetLastError = true, EntryPoint = "LsaStorePrivateData")]
    public static extern uint LsaStorePrivateDataSet(IntPtr PolicyHandle, ref LSA_UNICODE_STRING KeyName, ref LSA_UNICODE_STRING PrivateData);

    [DllImport("advapi32.dll", SetLastError = true, EntryPoint = "LsaStorePrivateData")]
    public static extern uint LsaStorePrivateDataDelete(IntPtr PolicyHandle, ref LSA_UNICODE_STRING KeyName, IntPtr PrivateData);

    [DllImport("advapi32.dll", SetLastError = true)]
    public static extern int LsaNtStatusToWinError(uint status);

    [DllImport("advapi32.dll")]
    public static extern uint LsaClose(IntPtr PolicyHandle);

    public const int POLICY_CREATE_SECRET = 0x0020;
}
'@
}

function New-LsaUnicodeString {
    param([string]$Value)
    $s = New-Object StreamReadyLsa+LSA_UNICODE_STRING
    if ([string]::IsNullOrEmpty($Value)) {
        $s.Buffer = [IntPtr]::Zero; $s.Length = 0; $s.MaximumLength = 0
    } else {
        $s.Buffer = [System.Runtime.InteropServices.Marshal]::StringToHGlobalUni($Value)
        $s.Length = [uint16]($Value.Length * 2)
        $s.MaximumLength = [uint16](($Value.Length + 1) * 2)
    }
    return $s
}

function Open-LsaPolicyHandle {
    $sysName = New-Object StreamReadyLsa+LSA_UNICODE_STRING
    $oa      = New-Object StreamReadyLsa+LSA_OBJECT_ATTRIBUTES
    $oa.Length = [System.Runtime.InteropServices.Marshal]::SizeOf($oa)
    $handle  = [IntPtr]::Zero
    $status  = [StreamReadyLsa]::LsaOpenPolicy([ref]$sysName, [ref]$oa, [StreamReadyLsa]::POLICY_CREATE_SECRET, [ref]$handle)
    if ($status -ne 0) {
        throw "LsaOpenPolicy failed (Win32 error $([StreamReadyLsa]::LsaNtStatusToWinError($status)))"
    }
    return $handle
}

function Set-LsaSecret {
    param([Parameter(Mandatory)][string]$Name, [Parameter(Mandatory)][AllowEmptyString()][string]$Value)
    Register-LsaSecretType
    $handle = Open-LsaPolicyHandle
    try {
        $keyName = New-LsaUnicodeString -Value $Name
        $data    = New-LsaUnicodeString -Value $Value
        try {
            $status = [StreamReadyLsa]::LsaStorePrivateDataSet($handle, [ref]$keyName, [ref]$data)
            if ($status -ne 0) {
                throw "LsaStorePrivateData failed (Win32 error $([StreamReadyLsa]::LsaNtStatusToWinError($status)))"
            }
        } finally {
            if ($keyName.Buffer -ne [IntPtr]::Zero) { [System.Runtime.InteropServices.Marshal]::ZeroFreeGlobalAllocUnicode($keyName.Buffer) }
            if ($data.Buffer    -ne [IntPtr]::Zero) { [System.Runtime.InteropServices.Marshal]::ZeroFreeGlobalAllocUnicode($data.Buffer) }
        }
    } finally {
        [StreamReadyLsa]::LsaClose($handle) | Out-Null
    }
}

function Remove-LsaSecret {
    param([Parameter(Mandatory)][string]$Name)
    Register-LsaSecretType
    $handle = Open-LsaPolicyHandle
    try {
        $keyName = New-LsaUnicodeString -Value $Name
        try {
            [StreamReadyLsa]::LsaStorePrivateDataDelete($handle, [ref]$keyName, [IntPtr]::Zero) | Out-Null
        } finally {
            if ($keyName.Buffer -ne [IntPtr]::Zero) { [System.Runtime.InteropServices.Marshal]::ZeroFreeGlobalAllocUnicode($keyName.Buffer) }
        }
    } finally {
        [StreamReadyLsa]::LsaClose($handle) | Out-Null
    }
}

# Masked-input replacement for the old unmasked VisualBasic InputBox pair. Returns
# @{ User = ...; Pass = ... } or $null if cancelled.
function Show-AutologinDialog {
    $xaml = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="StreamReady - Auto Login Setup" Width="440"
        SizeToContent="Height" WindowStartupLocation="CenterScreen" ResizeMode="NoResize"
        Background="#08080e" FontFamily="Segoe UI">
  <Grid Margin="32,28,32,28">
    <Grid.RowDefinitions>
      <RowDefinition Height="Auto"/><RowDefinition Height="Auto"/>
      <RowDefinition Height="Auto"/><RowDefinition Height="Auto"/>
      <RowDefinition Height="Auto"/><RowDefinition Height="Auto"/>
      <RowDefinition Height="Auto"/><RowDefinition Height="Auto"/>
    </Grid.RowDefinitions>
    <TextBlock Grid.Row="0" Text="Auto Login Setup" FontSize="18" FontWeight="Bold" Foreground="White" Margin="0,0,0,4"/>
    <TextBlock Grid.Row="1" TextWrapping="Wrap" FontSize="11.5" Foreground="#8b8b9c" Margin="0,0,0,16"
               Text="Signs this Windows account in automatically at every startup, skipping the lock screen. Your password is stored as an encrypted Windows LSA secret (not plaintext), but anyone with physical or admin access to this PC can still sign in without it."/>
    <TextBlock Grid.Row="2" Text="Username" FontSize="11" Foreground="#8b8b9c" Margin="0,0,0,4"/>
    <TextBox Grid.Row="3" x:Name="TxtALUser" Text="$env:USERNAME"
             Background="#0d0d16" Foreground="White" CaretBrush="White"
             BorderBrush="#28242f" BorderThickness="1" Padding="10,8" FontSize="13" Margin="0,0,0,12"/>
    <TextBlock Grid.Row="4" Text="Password (leave blank only if this account truly has no password)" FontSize="11" Foreground="#8b8b9c" Margin="0,0,0,4"/>
    <PasswordBox Grid.Row="5" x:Name="PwdALPass"
             Background="#0d0d16" Foreground="White" CaretBrush="White"
             BorderBrush="#28242f" BorderThickness="1" Padding="10,8" FontSize="13" Margin="0,0,0,16"/>
    <Button Grid.Row="6" x:Name="BtnALConfirm" Content="Enable Auto Login"
            Background="#7c5cff" Foreground="White" BorderThickness="0"
            Padding="0,10" FontSize="14" FontWeight="Bold" Cursor="Hand" Margin="0,0,0,6"/>
    <Button Grid.Row="7" x:Name="BtnALCancel" Content="Cancel"
            Background="#15131f" Foreground="#8b8b9c" BorderThickness="0"
            Padding="0,8" FontSize="13" Cursor="Hand"/>
  </Grid>
</Window>
"@
    $reader = [System.Xml.XmlReader]::Create((New-Object System.IO.StringReader $xaml))
    $win    = [System.Windows.Markup.XamlReader]::Load($reader)
    $txtUser = $win.FindName('TxtALUser')
    $pwdPass = $win.FindName('PwdALPass')
    $btnOk   = $win.FindName('BtnALConfirm')
    $btnCan  = $win.FindName('BtnALCancel')

    $script:_alResult = $null
    $btnCan.Add_Click({ $win.Close() })
    $btnOk.Add_Click({
        $u = $txtUser.Text.Trim()
        if (-not $u) { return }
        $script:_alResult = @{ User = $u; Pass = $pwdPass.SecurePassword }
        $win.Close()
    })
    $win.ShowDialog() | Out-Null
    return $script:_alResult
}

$c['BtnSetupAutologin'].Add_Click({ Invoke-UndoToolClick 'BtnSetupAutologin' {
    Write-SR "StreamReady - Auto Login Setup" 'SECTION'
    $result = Show-AutologinDialog
    if (-not $result) { Fail "Auto login cancelled."; return }

    $user = $result.User
    $bstr = [System.Runtime.InteropServices.Marshal]::SecureStringToBSTR($result.Pass)
    try {
        $pass = [System.Runtime.InteropServices.Marshal]::PtrToStringBSTR($bstr)
    } finally {
        [System.Runtime.InteropServices.Marshal]::ZeroFreeBSTR($bstr)
    }

    $p = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Winlogon"
    Write-SR "Setting Winlogon AutoAdminLogon for user: $user" 'REG'
    try {
        Set-ItemProperty $p "AutoAdminLogon"  "1"    -Type String -ErrorAction Stop
        Set-ItemProperty $p "DefaultUsername" $user  -Type String -ErrorAction Stop
        # Remove any plaintext DefaultPassword left by an older StreamReady version (or
        # manual setup) now that the password lives in an LSA secret instead.
        Remove-ItemProperty $p "DefaultPassword" -ErrorAction SilentlyContinue
        Set-LsaSecret -Name "DefaultPassword" -Value $pass
        Done "Auto Login configured for: $user"
        Write-SR "Auto login set (password stored as an LSA secret, not plaintext) - PC will sign in automatically at startup" 'OK'
    } catch {
        Fail "Auto login setup failed: $_"
        Write-SR "Auto login setup failed: $_" 'FAIL'
    } finally {
        $pass = $null
    }
} })

$c['BtnDisableAutologin'].Add_Click({ Invoke-UndoToolClick 'BtnDisableAutologin' {
    Write-SR "StreamReady - Disabling Auto Login" 'SECTION'
    $p = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Winlogon"
    try {
        Set-ItemProperty $p "AutoAdminLogon" "0" -Type String -ErrorAction Stop
        Remove-ItemProperty $p "DefaultPassword" -ErrorAction SilentlyContinue
        Remove-LsaSecret -Name "DefaultPassword"
        Done "Auto Login disabled - sign-in will be required at startup again."
        Write-SR "Auto login disabled and stored credential cleared" 'OK'
    } catch {
        Fail "Could not disable auto login: $_"
        Write-SR "Disable auto login failed: $_" 'FAIL'
    }
} })
#endregion System Handlers

#region Network Handlers
# ─── Network Tab ───────────────────────────────────────────────────────────────
$c['BtnRefreshNet'].Add_Click({ Load-NetInfo; Done "Network info refreshed." })

# ─── Regional Latency Test ──────────────────────────────────────────────────────
# Fixed, publicly-documented regional endpoints (Hetzner's public speedtest servers -
# provided by Hetzner specifically for this kind of public speed/latency testing) rather
# than anycast DNS like 1.1.1.1/8.8.8.8 (resolves to your *nearest* PoP regardless of
# region, so it can't distinguish regions) or live game-server IPs (undocumented/unstable
# and not appropriate to ping directly). This is a rough regional reference, not a
# specific game's ping - the UI copy says so.
# $script:_RegionPingTargets is read from inside Add_Tick below, which runs as a async
# callback after this handler has already returned - must be script-scoped (a plain local
# variable would be empty by then; see Apply-ServicesManual for the same issue solved via
# GetNewClosure() instead, used here via $script: scope to match this file's existing
# async-ping pattern in Load-Dashboard).
$script:_RegionPingTargets = [ordered]@{
    'TxtPingUSEast' = @{ Label='US East'; HostName='ash-speed.hetzner.com' }
    'TxtPingUSWest' = @{ Label='US West'; HostName='hil-speed.hetzner.com' }
    'TxtPingEU'     = @{ Label='EU';      HostName='nbg1-speed.hetzner.com' }
    'TxtPingAsia'   = @{ Label='Asia';    HostName='sin-speed.hetzner.com' }
}
$c['BtnTestRegionalPing'].Add_Click({
    if ($script:_RegionPingTimer -and $script:_RegionPingTimer.IsEnabled) { $script:_RegionPingTimer.Stop() }
    if ($script:_RegionPingPs) { try { $script:_RegionPingPs.Dispose() } catch {} }
    if ($script:_RegionPingRs) { try { $script:_RegionPingRs.Close(); $script:_RegionPingRs.Dispose() } catch {} }

    foreach ($ctrl in $script:_RegionPingTargets.Keys) {
        $c[$ctrl].Text = "$($script:_RegionPingTargets[$ctrl].Label): testing..."
        $c[$ctrl].Foreground = "#8b8b9c"
    }

    $script:_RegionPingRs = [runspacefactory]::CreateRunspace([initialsessionstate]::CreateDefault())
    $script:_RegionPingRs.Open()
    $script:_RegionPingPs = [powershell]::Create().AddScript({
        param($targets)
        $out = @{}
        foreach ($key in $targets.Keys) {
            try {
                $r = Test-Connection $targets[$key].HostName -Count 1 -ErrorAction Stop
                $out[$key] = "$($r.ResponseTime)ms"
            } catch { $out[$key] = "timeout" }
        }
        return $out
    }).AddArgument($script:_RegionPingTargets)
    $script:_RegionPingPs.Runspace = $script:_RegionPingRs
    $script:_RegionPingHandle = $script:_RegionPingPs.BeginInvoke()
    $script:_RegionPingTimer  = New-Object System.Windows.Threading.DispatcherTimer
    $script:_RegionPingTimer.Interval = [TimeSpan]::FromMilliseconds(300)
    $script:_RegionPingTimer.Add_Tick({
        if (-not $script:_RegionPingHandle.IsCompleted) { return }
        $script:_RegionPingTimer.Stop()
        try {
            $results = $script:_RegionPingPs.EndInvoke($script:_RegionPingHandle)
            foreach ($ctrl in $script:_RegionPingTargets.Keys) {
                $label = $script:_RegionPingTargets[$ctrl].Label
                $val   = $results[$ctrl]
                $c[$ctrl].Text = "${label}: $val"
                $c[$ctrl].Foreground = if ($val -match '^\d+ms$' -and [int]($val -replace 'ms','') -lt 100) { "#56dd92" }
                                       elseif ($val -eq 'timeout') { "#8b8b9c" }
                                       else { "#edecf3" }
            }
        } catch {
            foreach ($ctrl in $script:_RegionPingTargets.Keys) { $c[$ctrl].Text = "$($script:_RegionPingTargets[$ctrl].Label): error" }
        } finally {
            $script:_RegionPingPs.Dispose()
            $script:_RegionPingRs.Close(); $script:_RegionPingRs.Dispose()
        }
    })
    $script:_RegionPingTimer.Start()
})

# ─── Raw DNS-over-UDP query (async) ────────────────────────────────────────────────
# Measures how long an actual DNS lookup takes against a specific server - not just an
# ICMP ping to its IP, which is a different thing (a resolver can be fast to ping but
# slow to actually answer a query, or vice versa; this is what sites like
# dnsspeedtest.online measure). Deliberately not the Resolve-DnsName cmdlet: that needs
# the DnsClient module to resolve, the same class of problem that made Test-Connection
# unreliable in this compiled-exe host earlier. This hand-builds a minimal single-question
# A-record query packet and sends/receives it directly over a UDP socket instead - no
# cmdlet or module involved. Returns a handle immediately (async); poll .Task.IsCompleted.
function Start-DnsQuery {
    param([string]$ServerIP, [string]$Hostname = 'google.com')
    $result = @{ Udp = $null; Task = $null; Stopwatch = $null; TxHi = 0; TxLo = 0; Done = $false; Result = $null }
    try {
        $udp = New-Object System.Net.Sockets.UdpClient
        $udp.Connect($ServerIP, 53)

        $txId   = Get-Random -Minimum 1 -Maximum 65534
        $txHi   = [byte](($txId -shr 8) -band 0xFF)
        $txLo   = [byte]($txId -band 0xFF)
        # Header: ID(2) + flags(2, standard query/recursion desired) + QDCOUNT=1,
        # ANCOUNT=0, NSCOUNT=0, ARCOUNT=0 (2 bytes each)
        $header = [byte[]]@($txHi,$txLo, 0x01,0x00, 0x00,0x01, 0x00,0x00, 0x00,0x00, 0x00,0x00)
        $qname  = New-Object System.Collections.Generic.List[byte]
        foreach ($label in $Hostname.Split('.')) {
            $labelBytes = [System.Text.Encoding]::ASCII.GetBytes($label)
            $qname.Add([byte]$labelBytes.Length)
            $qname.AddRange([byte[]]$labelBytes)
        }
        $qname.Add([byte]0)                      # root terminator
        $tail = [byte[]]@(0x00,0x01, 0x00,0x01)   # QTYPE=A, QCLASS=IN
        $packet = $header + $qname.ToArray() + $tail

        $sw = [System.Diagnostics.Stopwatch]::StartNew()
        $udp.Send($packet, $packet.Length) | Out-Null
        $result.Udp = $udp
        $result.Task = $udp.ReceiveAsync()
        $result.Stopwatch = $sw
        $result.TxHi = $txHi
        $result.TxLo = $txLo
    } catch { }
    return $result
}

# Polls a Start-DnsQuery handle: returns elapsed ms once a valid reply (matching
# transaction ID) arrives, $null if it errored/timed out, or $false if still waiting and
# hasn't exceeded TimeoutMs yet (caller should check again next tick). $Handle is a
# hashtable (passed by reference), so the result is cached onto it once determined - this
# function gets called every tick for every target including ones that already finished on
# an earlier tick, and without caching, re-reading an unstopped Stopwatch on each of those
# repeat calls would report a larger, wrong elapsed time every time.
function Get-DnsQueryResult {
    param($Handle, [int]$TimeoutMs = 2000)
    if ($Handle.Done) { return $Handle.Result }

    if (-not $Handle.Task) {
        $Handle.Done = $true
        return $Handle.Result
    }
    if (-not $Handle.Task.IsCompleted) {
        if ($Handle.Stopwatch.ElapsedMilliseconds -gt $TimeoutMs) {
            try { $Handle.Udp.Close() } catch {}
            $Handle.Stopwatch.Stop()
            $Handle.Done = $true
            return $Handle.Result
        }
        return $false
    }

    $Handle.Stopwatch.Stop()
    try {
        $reply = $Handle.Task.GetAwaiter().GetResult()
        $buf   = $reply.Buffer
        if ($buf.Length -ge 2 -and $buf[0] -eq $Handle.TxHi -and $buf[1] -eq $Handle.TxLo) {
            $Handle.Result = [int]$Handle.Stopwatch.ElapsedMilliseconds
        }
    } catch {
    } finally {
        try { $Handle.Udp.Close() } catch {}
        $Handle.Done = $true
    }
    return $Handle.Result
}

# ─── DNS Speed Test ──────────────────────────────────────────────────────────────
# Same four providers as the manual "Change DNS Provider" buttons above - "Use Fastest"
# applies the winner via the same Set-DNS those buttons call. Deliberately doesn't include
# the currently-configured DNS as a comparison point (see note below, where the target
# list is built) since on most setups that's the router itself and would always "win" on
# a meaningless sub-1ms local-network hop. $script:_DnsSpeedTargets is read from inside
# Add_Tick below, which runs as an async callback after this handler has already returned
# - must be script-scoped, same reasoning as $script:_RegionPingTargets above.
$script:_DnsSpeedProviders = [ordered]@{
    'Cloudflare'    = @{ Label = 'Cloudflare';    TestIP = '1.1.1.1';        Servers = @('1.1.1.1','1.0.0.1') }
    'Google'        = @{ Label = 'Google';        TestIP = '8.8.8.8';        Servers = @('8.8.8.8','8.8.4.4') }
    'Quad9'         = @{ Label = 'Quad9';         TestIP = '9.9.9.9';        Servers = @('9.9.9.9','149.112.112.112') }
    'OpenDNS'       = @{ Label = 'OpenDNS';       TestIP = '208.67.222.222'; Servers = @('208.67.222.222','208.67.220.220') }
    'CleanBrowsing' = @{ Label = 'CleanBrowsing'; TestIP = '185.228.168.9';  Servers = @('185.228.168.9','185.228.169.9') }
    'NextDNS'       = @{ Label = 'NextDNS';       TestIP = '45.90.28.0';     Servers = @('45.90.28.0','45.90.30.0') }
    'Mullvad'       = @{ Label = 'Mullvad';       TestIP = '194.242.2.2';    Servers = @('194.242.2.2') }
    'ControlD'      = @{ Label = 'ControlD';      TestIP = '76.76.2.0';      Servers = @('76.76.2.0','76.223.122.150') }
    'AdGuard'       = @{ Label = 'AdGuard';       TestIP = '94.140.14.14';   Servers = @('94.140.14.14','94.140.15.15') }
}
# Skipped from the full benchmark list the user pulled from a DNS-speed-comparison site:
# China-only resolvers (AliDNS/DNSPod/360 - irrelevant outside China), ISP-locked ones
# (Comcast Xfinity), academic/national networks (Switch, Restena, IIJ, DNS4EU), and ones
# needing registration (FlashStart) - not a good fit for a general-audience one-click test.
$script:_FastestDns = $null

$c['BtnDnsSpeedTest'].Add_Click({
    if ($script:_DnsSpeedTimer -and $script:_DnsSpeedTimer.IsEnabled) { $script:_DnsSpeedTimer.Stop() }
    if ($script:_DnsSpeedHandles) {
        foreach ($h in $script:_DnsSpeedHandles.Values) { if ($h.Udp) { try { $h.Udp.Close() } catch {} } }
    }

    $c['BtnUseFastestDns'].Visibility = 'Collapsed'
    $script:_FastestDns = $null

    # Deliberately NOT including the currently-configured DNS here - on most home setups
    # that's the router itself (e.g. 192.168.1.1) acting as a caching resolver, which
    # would always "win" with a sub-1ms local-network hop and make the comparison between
    # the actual external providers meaningless.
    $script:_DnsSpeedTargets = [ordered]@{}
    foreach ($key in $script:_DnsSpeedProviders.Keys) { $script:_DnsSpeedTargets[$key] = $script:_DnsSpeedProviders[$key] }

    $c['PanelDnsResults'].Children.Clear()
    foreach ($key in $script:_DnsSpeedTargets.Keys) {
        $row = New-Object System.Windows.Controls.TextBlock
        $row.Text       = "$($script:_DnsSpeedTargets[$key].Label): testing..."
        $row.Foreground = [System.Windows.Media.SolidColorBrush][System.Windows.Media.ColorConverter]::ConvertFromString("#8b8b9c")
        $row.FontSize   = 12
        $row.Margin     = [System.Windows.Thickness]::new(0,3,0,3)
        $c['PanelDnsResults'].Children.Add($row) | Out-Null
    }

    # Launch every target's DNS query at once (they run concurrently, not one after
    # another) - each has its own 2s timeout, so the whole test takes ~2s even in the
    # worst case regardless of how many providers are in the list.
    $script:_DnsSpeedHandles = @{}
    foreach ($key in $script:_DnsSpeedTargets.Keys) {
        $script:_DnsSpeedHandles[$key] = Start-DnsQuery -ServerIP $script:_DnsSpeedTargets[$key].TestIP
    }

    $script:_DnsSpeedTimer  = New-Object System.Windows.Threading.DispatcherTimer
    $script:_DnsSpeedTimer.Interval = [TimeSpan]::FromMilliseconds(100)
    $script:_DnsSpeedTimer.Add_Tick({
        $results = @{}
        $stillWaiting = $false
        foreach ($key in $script:_DnsSpeedTargets.Keys) {
            $r = Get-DnsQueryResult -Handle $script:_DnsSpeedHandles[$key]
            if ($r -eq $false) { $stillWaiting = $true; continue }
            $results[$key] = $r
        }
        if ($stillWaiting) { return }
        $script:_DnsSpeedTimer.Stop()

        # Fastest (lowest ms) first; anything that timed out (no result) sorts last.
        $ordered = $script:_DnsSpeedTargets.Keys | Sort-Object { if ($null -ne $results[$_]) { $results[$_] } else { [int]::MaxValue } }
        $fastestKey = $ordered | Where-Object { $null -ne $results[$_] } | Select-Object -First 1

        $c['PanelDnsResults'].Children.Clear()
        foreach ($key in $ordered) {
            $ms    = $results[$key]
            $label = $script:_DnsSpeedTargets[$key].Label
            $row = New-Object System.Windows.Controls.TextBlock
            $row.FontSize = 12
            $row.Margin   = [System.Windows.Thickness]::new(0,3,0,3)
            if ($null -eq $ms) {
                $row.Text       = "${label}: timeout"
                $row.Foreground = [System.Windows.Media.SolidColorBrush][System.Windows.Media.ColorConverter]::ConvertFromString("#5f5f70")
            } elseif ($key -eq $fastestKey) {
                $row.Text       = "★ ${label}: ${ms}ms - fastest"
                $row.FontWeight = 'Bold'
                $row.Foreground = [System.Windows.Media.SolidColorBrush][System.Windows.Media.ColorConverter]::ConvertFromString("#56dd92")
            } else {
                $row.Text       = "${label}: ${ms}ms"
                $row.Foreground = [System.Windows.Media.SolidColorBrush][System.Windows.Media.ColorConverter]::ConvertFromString("#edecf3")
            }
            $c['PanelDnsResults'].Children.Add($row) | Out-Null
        }

        if ($fastestKey) {
            $script:_FastestDns = $script:_DnsSpeedTargets[$fastestKey]
            $c['BtnUseFastestDns'].Content    = "Use Fastest - $($script:_DnsSpeedTargets[$fastestKey].Label)"
            $c['BtnUseFastestDns'].Visibility = 'Visible'
        }
    })
    $script:_DnsSpeedTimer.Start()
})
$c['BtnUseFastestDns'].Add_Click({ Invoke-UndoToolClick 'BtnUseFastestDns' {
    if (-not $script:_FastestDns) { return }
    Set-DNS $script:_FastestDns.Servers
    $c['BtnUseFastestDns'].Visibility = 'Collapsed'
} })

$c['BtnFlushDns'].Add_Click(  {
    Working 50 "Flushing DNS..."
    Write-SR "Running: ipconfig /flushdns" 'NET'
    ipconfig /flushdns | Out-Null
    Done "DNS cache flushed."; Load-NetInfo
})
$c['BtnWinsock'].Add_Click(   { Invoke-UndoToolClick 'BtnWinsock' {
    Working 50 "Resetting Winsock..."
    Write-SR "Running: netsh winsock reset" 'NET'
    netsh winsock reset | Out-Null
    Done "Winsock reset - reboot required."
