} })
$c['BtnNetReset'].Add_Click({ Invoke-UndoToolClick 'BtnNetReset' {
    Write-SR "StreamReady - Full Network Reset" 'SECTION'
    Working 25 "Flushing DNS...";     Write-SR "Running: ipconfig /flushdns" 'NET';         ipconfig /flushdns | Out-Null
    Working 50 "Resetting Winsock..."; Write-SR "Running: netsh winsock reset" 'NET';        netsh winsock reset | Out-Null
    Working 75 "Resetting IP stack..."; Write-SR "Running: netsh int ip reset" 'NET';        netsh int ip reset | Out-Null
    Done "Full network reset - reboot required."
    Write-SR "Full network stack reset - reboot required" 'WARN'
} })
$c['BtnResetWU'].Add_Click({ Invoke-UndoToolClick 'BtnResetWU' {
    Write-SR "StreamReady - Resetting Windows Update Cache" 'SECTION'
    Working 20 "Stopping WU services..."
    @("wuauserv","cryptSvc","bits","msiserver") | ForEach-Object {
        Write-SR "Stopping service: $_" 'SVC'
        Stop-Service $_ -Force -EA SilentlyContinue
    }
    Working 50 "Clearing cache..."
    Write-SR "Deleting: $env:SystemRoot\SoftwareDistribution" 'INFO'
    Remove-Item "$env:SystemRoot\SoftwareDistribution" -Recurse -Force -EA SilentlyContinue
    Write-SR "Deleting: $env:SystemRoot\System32\catroot2" 'INFO'
    Remove-Item "$env:SystemRoot\System32\catroot2" -Recurse -Force -EA SilentlyContinue
    Working 80 "Restarting services..."
    @("wuauserv","cryptSvc","bits","msiserver") | ForEach-Object {
        Write-SR "Starting service: $_" 'SVC'
        Start-Service $_ -EA SilentlyContinue
    }
    Done "Windows Update cache cleared."
} })
function Set-DNS { param([string[]]$s)
    Working 40 "Setting DNS to $($s[0])..."
    Write-SR "Changing DNS servers to: $($s -join ' / ')" 'NET'
    try {
        Get-NetAdapterFrozen | Where-Object { $_.Status -eq 'Up' } | ForEach-Object {
            Write-SR "Updating adapter: $($_.Name)" 'NET'
            Set-DnsClientServerAddress -InterfaceIndex $_.ifIndex -ServerAddresses $s
        }
        Done "DNS set to: $($s -join ' / ')"
        Write-SR "DNS updated successfully on all active adapters" 'OK'
        Load-NetInfo
    } catch {
        Fail "DNS failed: $_"
        Write-SR "DNS change failed: $_" 'FAIL'
    }
}
$c['BtnDnsCloudflare'].Add_Click( { Invoke-UndoToolClick 'BtnDnsCloudflare' { Set-DNS @("1.1.1.1","1.0.0.1") } })
$c['BtnDnsGoogle'].Add_Click(     { Invoke-UndoToolClick 'BtnDnsGoogle' { Set-DNS @("8.8.8.8","8.8.4.4") } })
$c['BtnDnsQuad9'].Add_Click(      { Invoke-UndoToolClick 'BtnDnsQuad9' { Set-DNS @("9.9.9.9","149.112.112.112") } })
$c['BtnDnsOpenDNS'].Add_Click(    { Invoke-UndoToolClick 'BtnDnsOpenDNS' { Set-DNS @("208.67.222.222","208.67.220.220") } })
$c['BtnDnsDefault'].Add_Click({ Invoke-UndoToolClick 'BtnDnsDefault' {
    Working 40 "Resetting DNS to DHCP..."
    Write-SR "Resetting all active adapters to DHCP DNS" 'NET'
    try {
        Get-NetAdapterFrozen | Where-Object { $_.Status -eq 'Up' } | ForEach-Object {
            Write-SR "Resetting adapter: $($_.Name)" 'NET'
            Set-DnsClientServerAddress -InterfaceIndex $_.ifIndex -ResetServerAddresses
        }
        Done "DNS reset to DHCP."
        Write-SR "DNS reset to automatic (DHCP) on all adapters" 'OK'
        Load-NetInfo
    } catch {
        Fail "DNS reset failed: $_"
        Write-SR "DNS reset failed: $_" 'FAIL'
    }
} })
#endregion Network Handlers

#region Updates Handlers
# ─── Updates Tab ───────────────────────────────────────────────────────────────
# Windows Update helpers: every step is logged, failures stop the handler, and success is only
# reported after the registry values and the service are read back and are what was intended.
function Remove-SrRegValue {
    param($Path, $Name)
    if ($null -ne (Get-ItemProperty -Path $Path -Name $Name -ErrorAction SilentlyContinue)) {
        Remove-ItemProperty -Path $Path -Name $Name -ErrorAction Stop
        Write-SR "Removed $Path\$Name" 'REG'
    }
}
function Set-SrWuService {
    Write-SR "Setting wuauserv startup to Automatic and starting it" 'SVC'
    Set-Service wuauserv -StartupType Automatic -ErrorAction Stop
    Start-Service wuauserv -ErrorAction Stop
}
function Get-SrWuProblems {
    param([switch]$SecurityOnly)
    $wu = "HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate"
    $au = "$wu\AU"
    $p  = [System.Collections.Generic.List[string]]::new()
    if ((Get-RegVal $au 'NoAutoUpdate') -eq 1) { $p.Add('NoAutoUpdate is still 1') }
    if ((Get-RegVal $au 'AUOptions')    -eq 1) { $p.Add('AUOptions is still 1 (never check for updates)') }
    $svc = Get-Service wuauserv -ErrorAction SilentlyContinue
    if (-not $svc) { $p.Add('the Windows Update service was not found') }
    else {
        if ($svc.StartType -eq 'Disabled') { $p.Add('the Windows Update service is still Disabled') }
        if ($svc.Status -ne 'Running')     { $p.Add("the Windows Update service is $($svc.Status)") }
    }
    if ($SecurityOnly) {
        if ((Get-RegVal $wu 'DeferFeatureUpdates') -ne 1)              { $p.Add('DeferFeatureUpdates is not 1') }
        if ((Get-RegVal $wu 'DeferFeatureUpdatesPeriodInDays') -ne 365) { $p.Add('DeferFeatureUpdatesPeriodInDays is not 365') }
        if ((Get-RegVal $wu 'DeferQualityUpdates') -ne 0)              { $p.Add('DeferQualityUpdates is not 0') }
    } else {
        foreach ($n in 'DeferFeatureUpdates','DeferFeatureUpdatesPeriodInDays','DeferQualityUpdates','DeferQualityUpdatesPeriodInDays') {
            if ($null -ne (Get-RegVal $wu $n)) { $p.Add("$n is still set") }
        }
    }
    return $p.ToArray()
}

$c['BtnWUDefault'].Add_Click({ Invoke-UndoToolClick 'BtnWUDefault' {
    Working 40 "Restoring default WU..."
    Write-SR "Restoring Windows Update to default (automatic) policy" 'APPLY'
    try {
        $wu = "HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate"
        $au = "$wu\AU"
        foreach ($n in 'DeferFeatureUpdates','DeferFeatureUpdatesPeriodInDays','DeferQualityUpdates','DeferQualityUpdatesPeriodInDays') { Remove-SrRegValue $wu $n }
        foreach ($n in 'NoAutoUpdate','AUOptions') { Remove-SrRegValue $au $n }
        Set-SrWuService
        $problems = @(Get-SrWuProblems)
        if ($problems.Count -gt 0) {
            Fail "Windows Update was not fully restored: $($problems -join '; ')"
            return
        }
        Done "Windows Update restored to default."
        Write-SR "Windows Update policy restored to automatic (read back and confirmed)" 'OK'
    } catch {
        Fail "Could not restore Windows Update: $_"
    }
} })
$c['BtnWUSecurity'].Add_Click({ Invoke-UndoToolClick 'BtnWUSecurity' {
    Working 40 "Setting Security Only policy..."
    Write-SR "Applying Security-Only Windows Update policy (feature updates deferred 365 days)" 'APPLY'
    try {
        $wu = "HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate"
        $au = "$wu\AU"
        if (-not (Test-Path $wu)) { New-Item $wu -Force -ErrorAction Stop | Out-Null }
        Set-RegLogged $wu "DeferFeatureUpdates"             1
        Set-RegLogged $wu "DeferFeatureUpdatesPeriodInDays" 365
        Set-RegLogged $wu "DeferQualityUpdates"             0
        foreach ($n in 'NoAutoUpdate','AUOptions') { Remove-SrRegValue $au $n }
        Set-SrWuService
        $problems = @(Get-SrWuProblems -SecurityOnly)
        if ($problems.Count -gt 0) {
            Fail "Security Only was not fully applied: $($problems -join '; ')"
            return
        }
        Done "Security Only policy set."
        Write-SR "Feature updates are deferred for 1 year and quality updates are left on (read back and confirmed). Windows still decides which patches to install." 'OK'
    } catch {
        Fail "Could not apply Security Only: $_"
    }
} })
$c['BtnWUDisable'].Add_Click({ Invoke-UndoToolClick 'BtnWUDisable' {
    Working 40 "Disabling Windows Update..."
    Write-SR "Disabling Windows Update entirely (NOT recommended for internet-connected PCs)" 'WARN'
    $p = "HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate\AU"
    if (-not (Test-Path $p)) { New-Item $p -Force | Out-Null }
    Set-RegLogged $p "NoAutoUpdate" 1
    Set-RegLogged $p "AUOptions"    1
    Write-SR "Stopping and disabling wuauserv service" 'SVC'
    Stop-Service wuauserv -Force -EA SilentlyContinue
    Set-Service wuauserv -StartupType Disabled -EA SilentlyContinue
    Done "Windows Update disabled."
    Write-SR "Windows Update disabled - remember to re-enable before going online long-term" 'WARN'
} })
