#region USB Polling Rate Handler
function Get-HidusbfExe {
    # Download HIDUSBF from its community GitHub mirror and return the exe path.
    # Pinned to a specific commit (not a moving branch) so the file's SHA256 is
    # predictable and can be verified before anything from the zip is run. The zip is
    # unpacked in a staging folder, checked, and only then moved into the cache.
    $toolRoot = "$env:ProgramData\StreamReady-OSS"
    $dest     = "$toolRoot\tools\HIDUSBF"
    if (-not (Initialize-ProtectedDir $toolRoot)) { return $null }
    try {
        if (-not (Test-Path -LiteralPath $dest)) { New-Item $dest -ItemType Directory -ErrorAction Stop | Out-Null }
        $cached = Get-TrustedToolExe $dest
        if ($cached) { return $cached }
        if (@(Get-ChildItem -LiteralPath $dest -Force -ErrorAction Stop).Count -gt 0) {
            Write-SR "Cached HIDUSBF copy could not be verified - clearing it and downloading again" 'WARN'
            Get-ChildItem -LiteralPath $dest -Force | Remove-Item -Recurse -Force -ErrorAction Stop
        }
    } catch { Write-SR "HIDUSBF cache check failed: $_" 'FAIL'; return $null }

    $pinnedCommit   = "8bfc7608d9a22e6adeaf35fb125d19da858af83a"
    $expectedSha256 = "F895C5935C6363AFA00B20557B6096CEF2B29DAA97C1B399DCEB85E5AF855229"
    $dlUrl = "https://raw.githubusercontent.com/LordOfMice/hidusbf/$pinnedCommit/hidusbf.zip"
    $stage = "$toolRoot\staging\hidusbf-$([guid]::NewGuid().ToString('N'))"
    Write-SR "Downloading HIDUSBF..." 'INFO'
    try {
        New-Item $stage -ItemType Directory -Force -ErrorAction Stop | Out-Null
        $zipPath = "$stage\hidusbf.zip"
        $xDir    = "$stage\x"
        Invoke-WebRequest -Uri $dlUrl -OutFile $zipPath -UseBasicParsing -TimeoutSec 120 -ErrorAction Stop

        $actualSha256 = (Get-FileHash -Path $zipPath -Algorithm SHA256 -ErrorAction Stop).Hash
        if ($actualSha256 -ne $expectedSha256) {
            Write-SR "HIDUSBF download failed SHA256 verification (expected $expectedSha256, got $actualSha256) - not running it." 'FAIL'
            return $null
        }

        Expand-Archive -Path $zipPath -DestinationPath $xDir -Force -ErrorAction Stop
        $exe = Get-ChildItem $xDir -Filter "*.exe" -Recurse -ErrorAction Stop | Select-Object -First 1
        if (-not $exe) { Write-SR "No .exe found in HIDUSBF zip." 'FAIL'; return $null }
        $rel = $exe.FullName.Substring($xDir.Length + 1)
        if (-not (Confirm-DownloadedExeTrust -Path $exe.FullName -FriendlyName "HIDUSBF")) {
            Write-SR "HIDUSBF run cancelled (signature check not accepted)" 'FAIL'
            return $null
        }
        foreach ($child in (Get-ChildItem -LiteralPath $xDir -Force)) {
            Move-Item -LiteralPath $child.FullName -Destination $dest -Force -ErrorAction Stop
        }
        $final = Join-Path $dest $rel
        Save-ToolRecord -Dir $dest -ExePath $final
        Write-SR "HIDUSBF downloaded and SHA256-verified to $final" 'OK'
        return $final
    } catch {
        Write-SR "Failed to download HIDUSBF: $_" 'FAIL'
        try { Get-ChildItem -LiteralPath $dest -Force -ErrorAction SilentlyContinue | Remove-Item -Recurse -Force -ErrorAction SilentlyContinue } catch {}
        return $null
    } finally {
        Remove-Item -LiteralPath $stage -Recurse -Force -ErrorAction SilentlyContinue
    }
}
$c['BtnUsbPollingDownload'].Add_Click({ Invoke-UndoToolClick 'BtnUsbPollingDownload' {
    Working 20 "Downloading HIDUSBF..."
    $exe = Get-HidusbfExe
    if ($exe -and (Test-Path $exe)) {
        Working 90 "Launching HIDUSBF..."
        Start-Process $exe
        $c['LblUsbPollingStatus'].Text = "HIDUSBF launched - select your device and set polling rate, then click Install Service."
        Done "HIDUSBF ready."
    } else {
        $c['LblUsbPollingStatus'].Text = "Download failed - check your internet connection and try again."
        Fail "Could not download HIDUSBF."
    }
} })
#endregion USB Polling Rate Handler

#region Discrete GPU Preference Handler
# Per-app "force discrete GPU" preference - HKCU:\Software\Microsoft\DirectX\UserGpuPreferences,
# one value per exe path, data "GpuPreference=2;" (2 = high performance/discrete GPU,
# 1 = power saving/integrated, 0 = system default). Fixes hybrid-GPU laptops defaulting
# a game to the weaker integrated GPU instead of the discrete one.
$script:GpuPrefRegPath      = "HKCU:\Software\Microsoft\DirectX\UserGpuPreferences"
$script:GpuPrefSelectedPath = $null

function Get-GpuPrefApps {
    if (-not (Test-Path $script:GpuPrefRegPath)) { return @() }
    $props = Get-ItemProperty -Path $script:GpuPrefRegPath -EA SilentlyContinue
    if (-not $props) { return @() }
    $props.PSObject.Properties |
        Where-Object { $_.Name -notmatch '^PS(Path|ParentPath|ChildName|Provider)$' -and $_.Value -match 'GpuPreference=2' } |
        ForEach-Object { $_.Name }
}

function Update-GpuPrefList {
    $c['LstGpuPrefApps'].Items.Clear()
    foreach ($p in (Get-GpuPrefApps)) { $c['LstGpuPrefApps'].Items.Add($p) | Out-Null }
}

$c['BtnGpuPrefBrowse'].Add_Click({
    $dlg = New-Object Microsoft.Win32.OpenFileDialog
    $dlg.Filter = "Executable (*.exe)|*.exe"
    $dlg.Title  = "Select a game's .exe"
    if ($dlg.ShowDialog()) {
        $script:GpuPrefSelectedPath    = $dlg.FileName
        $c['LblGpuPrefStatus'].Text    = "Selected: $($dlg.FileName)"
        $c['BtnGpuPrefApply'].IsEnabled = $true
    }
})

$c['BtnGpuPrefApply'].Add_Click({ Invoke-UndoToolClick 'BtnGpuPrefApply' {
    if (-not $script:GpuPrefSelectedPath) { return }
    try {
        if (-not (Test-Path $script:GpuPrefRegPath)) { New-Item -Path $script:GpuPrefRegPath -Force | Out-Null }
        Set-ItemProperty -Path $script:GpuPrefRegPath -Name $script:GpuPrefSelectedPath -Value 'GpuPreference=2;' -Type String -EA Stop
        Write-SR "Discrete GPU preference set for: $($script:GpuPrefSelectedPath)" 'OK'
        $c['LblGpuPrefStatus'].Text = "Discrete GPU forced for: $($script:GpuPrefSelectedPath)"
        Update-GpuPrefList
        Done "Discrete GPU preference applied - takes effect next time the game launches."
    } catch {
        Fail "Could not set GPU preference: $_"
    }
} })

$c['BtnGpuPrefRemove'].Add_Click({ Invoke-UndoToolClick 'BtnGpuPrefRemove' {
    $selected = $c['LstGpuPrefApps'].SelectedItem
    if (-not $selected) { $c['LblGpuPrefStatus'].Text = "Select a game from the list first."; return }
    try {
        Remove-ItemProperty -Path $script:GpuPrefRegPath -Name $selected -EA Stop
        Write-SR "Discrete GPU preference removed for: $selected" 'OK'
        $c['LblGpuPrefStatus'].Text = "Removed preference for: $selected"
        Update-GpuPrefList
        Done "Preference removed."
    } catch {
        Fail "Could not remove GPU preference: $_"
    }
} })

$c['LstGpuPrefApps'].Add_SelectionChanged({
    $c['BtnGpuPrefRemove'].IsEnabled = ($null -ne $c['LstGpuPrefApps'].SelectedItem)
})
#endregion Discrete GPU Preference Handler

#region Downloads Tab Handlers
function Install-WingetApp {
    param([string]$WingetId, [string]$AppName)
    Working 20 "Installing $AppName via Winget..."
    Write-SR "Installing $AppName ($WingetId)" 'APPLY'
    try {
        $p = Start-Process winget -ArgumentList "install --id $WingetId --silent --accept-package-agreements --accept-source-agreements" -Wait -PassThru -WindowStyle Hidden
        if ($p.ExitCode -eq 0) {
            Done "$AppName installed."
            Write-SR "$AppName installed successfully" 'OK'
        } else {
            Fail "$AppName install returned exit code $($p.ExitCode) - it may already be installed or Winget encountered an error."
            Write-SR "$AppName install exit code: $($p.ExitCode)" 'WARN'
        }
    } catch {
        Fail "Failed to start Winget for ${AppName}: $_"
    }
}

