#region Sidebar Navigation Handler
$c['SideNav'].Add_SelectionChanged({
    $selected = $c['SideNav'].SelectedItem
    if (-not $selected) { return }
    $tag = $selected.Tag
    # Hide all content sections
    @('SecDashboard','SecGaming','SecPrivacy','SecTweaks','SecNetwork','SecUpdates','SecSystem','SecDownloads') | ForEach-Object {
        if ($c[$_]) { $c[$_].Visibility = 'Collapsed' }
    }
    # Show selected section
    if ($c[$tag]) { $c[$tag].Visibility = 'Visible' }
    # The live-metrics sampler only makes sense while the Dashboard is actually visible -
    # stop it on every navigation away, Load-Dashboard restarts it when navigating back.
    if ($tag -ne 'SecDashboard' -and (Get-Command Stop-DashboardMetricsTimer -ErrorAction SilentlyContinue)) {
        Stop-DashboardMetricsTimer
    }
    # Load section data on first visit
    switch ($tag) {
        'SecDashboard' {
            # Refresh every visit, not just the first - badges/health/ping/timer status
            # are live state that changes as the user applies tweaks elsewhere in the app.
            if ($script:SkipSideNavLoad) { $script:SkipSideNavLoad = $false }
            elseif (Get-Command Load-Dashboard -ErrorAction SilentlyContinue) {
                Load-Dashboard
            }
        }
    }
})
#endregion Sidebar Navigation Handler

#region Gaming Sub-tab Navigation
function Switch-GamTab {
    param([string]$TabName)
    $map = @{
        'BtnGamTabTweaks'   = 'GamPanTweaks'
        'BtnGamTabGpu'      = 'GamPanGpu'
    }
    foreach ($tab in $map.Keys) {
        $isActive = ($tab -eq $TabName)
        # Panel visibility
        $c[$map[$tab]].Visibility = if ($isActive) { 'Visible' } else { 'Collapsed' }
        # Tab visual state: $c[$tab] is Border; .Child is StackPanel
        # StackPanel.Children[0] = TextBlock (label text); [1] = Rectangle (underline indicator)
        $sp  = $c[$tab].Child
        $txt = $sp.Children[0]
        $ind = $sp.Children[1]
        $txt.Foreground = if ($isActive) { '#a78bff' } else { '#767685' }
        $ind.Visibility = if ($isActive) { 'Visible' } else { 'Collapsed' }
    }
}
$c['BtnGamTabTweaks'].Add_MouseLeftButtonDown({   Switch-GamTab 'BtnGamTabTweaks'  })
$c['BtnGamTabGpu'].Add_MouseLeftButtonDown({      Switch-GamTab 'BtnGamTabGpu'     })
#endregion Gaming Sub-tab Navigation
#region v7 Shell: Simple / Pro switch, Home, goals
# Everything in this region only changes the SHELL around the existing controls. The goal pages,
# plan and search rows are mirror switches bound two-way to the real Chk checkboxes, so the
# existing Apply engine, Undo stack, presets and profile code are untouched. Nothing in here
# applies a tweak: goals and "Get my PC ready" only tick Safe checkboxes for review.

# ---- settings file (first-run flag, last mode) --------------------------------------------
$script:SrSettingsDir  = Join-Path $env:LOCALAPPDATA 'StreamReady'
$script:SrSettingsPath = Join-Path $script:SrSettingsDir 'settings.json'
$script:SrSettings     = @{ mode = 'simple' }

# ---- small WPF builders --------------------------------------------------------------------
$script:BrushConv = [System.Windows.Media.BrushConverter]::new()
function Br { param([string]$Hex) $script:BrushConv.ConvertFromString($Hex) }
function New-Text {
    param([string]$Text, [double]$Size = 13, [string]$Color = '#c9c7d6', [string]$Weight = 'Normal')
    $t = New-Object System.Windows.Controls.TextBlock
    $t.Text = $Text; $t.FontSize = $Size; $t.Foreground = (Br $Color)
    $t.TextWrapping = 'Wrap'
    if ($Weight -ne 'Normal') { $t.FontWeight = [System.Windows.FontWeights]::$Weight }
    return $t
}
function New-RiskBadge {
    param([string]$Risk)
    switch ($Risk) {
        'S' { $label = 'Safe';     $fg = '#56dd92'; $bg = '#1456dd92'; $bd = '#6656dd92' }
        'A' { $label = 'Advanced'; $fg = '#ff6b6b'; $bg = '#14ff6b6b'; $bd = '#66ff6b6b' }
        default { $label = 'Careful'; $fg = '#f0b545'; $bg = '#14f0b545'; $bd = '#66f0b545' }
    }
    $b = New-Object System.Windows.Controls.Border
    $b.Background = (Br $bg); $b.BorderBrush = (Br $bd); $b.BorderThickness = [System.Windows.Thickness]::new(1)
    $b.CornerRadius = [System.Windows.CornerRadius]::new(10)
    $b.Padding = [System.Windows.Thickness]::new(9,1,9,2)
    $b.Margin = [System.Windows.Thickness]::new(0,0,10,0)
    $b.Child = (New-Text $label 12 $fg 'SemiBold')
    $b.ToolTip = switch ($Risk) { 'S' { 'Lower-risk starting setting. Read its effect and check the available Undo.' } 'A' { 'Advanced: may affect stability, security or recovery. Read it before you keep it switched on.' } default { 'Can affect Windows features, services or power use. Read the trade-off and recovery steps.' } }
    return $b
}

# Is this a laptop? (battery present - same test the Laptop preset uses). Read-only, cached.
$script:IsLaptopCache = $null
function Test-IsLaptop {
    if ($null -eq $script:IsLaptopCache) {
        $script:IsLaptopCache = $false
        try { $script:IsLaptopCache = [bool](Get-CimInstance Win32_Battery -ErrorAction Stop | Select-Object -First 1) } catch {}
    }
    return $script:IsLaptopCache
}

# Label -> test lookup, so a goal row can say "Already on" for the settings that have a Test-*.
function Test-TweakAlreadyOn {
    param([string]$Id)
    try {
        $bt = $script:BadgeTests | Where-Object { $_.CheckboxName -eq $Id } | Select-Object -First 1
        if ($bt) { return [bool](& $bt.Fn) }
    } catch {}
    return $false
}

# One row: toggle (mirror of the real checkbox) + plain name + description + risk badge.
function New-TweakRow {
    param([string]$Id, [switch]$NoLock)
    $real = $c[$Id]; $info = $script:TweakInfo[$Id]
    if (-not $real -or -not $info) { return $null }
    $card = New-Object System.Windows.Controls.Border
    $card.Background = (Br '#0d0d16'); $card.BorderBrush = (Br '#28242f')
    $card.BorderThickness = [System.Windows.Thickness]::new(1)
    $card.CornerRadius = [System.Windows.CornerRadius]::new(8)
    $card.Padding = [System.Windows.Thickness]::new(14,10,14,10)
    $card.Margin = [System.Windows.Thickness]::new(0,0,0,8)
    $card.ToolTip = "Original name: $($info.Tech)"
    $g = New-Object System.Windows.Controls.Grid
    $c0 = New-Object System.Windows.Controls.ColumnDefinition; $c0.Width = [System.Windows.GridLength]::Auto
    $c1 = New-Object System.Windows.Controls.ColumnDefinition; $c1.Width = [System.Windows.GridLength]::new(1, [System.Windows.GridUnitType]::Star)
    $g.ColumnDefinitions.Add($c0); $g.ColumnDefinitions.Add($c1)
    $mirror = New-Object System.Windows.Controls.CheckBox
    $mirror.Style = $window.FindResource('Chk')
    $mirror.VerticalAlignment = 'Top'
    $mirror.Margin = [System.Windows.Thickness]::new(0,2,14,0)
    $bind = New-Object System.Windows.Data.Binding 'IsChecked'
    $bind.Source = $real
    $bind.Mode = [System.Windows.Data.BindingMode]::TwoWay
    [void]$mirror.SetBinding([System.Windows.Controls.Primitives.ToggleButton]::IsCheckedProperty, $bind)
    [System.Windows.Controls.Grid]::SetColumn($mirror, 0)
    $g.Children.Add($mirror) | Out-Null
    $sp = New-Object System.Windows.Controls.StackPanel
    $sp.Children.Add((New-Text $info.Name 14 '#edecf3' 'SemiBold')) | Out-Null
    $sp.Children.Add((New-Text $info.Desc 13 '#c9c7d6')) | Out-Null
    if (-not $NoLock -and $script:SrSettings.safeMode -and $info.Risk -ne 'S') { $mirror.IsEnabled = $false; $card.Opacity = 0.6; $sp.Children.Add((New-Text 'Safe Mode is on, so this stays off. Turn Safe Mode off in Settings to choose it.' 12 '#f0b545')) | Out-Null }
    $meta = New-Object System.Windows.Controls.StackPanel
    $meta.Orientation = 'Horizontal'; $meta.Margin = [System.Windows.Thickness]::new(0,6,0,0)
    $meta.Children.Add((New-RiskBadge $info.Risk)) | Out-Null
    if (Test-TweakAlreadyOn $Id) {
        $meta.Children.Add((New-Text 'Already on' 12 '#56dd92')) | Out-Null
    }
    $sp.Children.Add($meta) | Out-Null
    [System.Windows.Controls.Grid]::SetColumn($sp, 1)
    $g.Children.Add($sp) | Out-Null
    $card.Child = $g
    return $card
}

