# Safe, applicable checkbox names for a goal. Only ids the risk map marks Safe are ever returned.

# Ticks (never unticks, never applies) the given ids. Returns how many were newly ticked.
function Select-SafeIds {
    param([string[]]$Ids)
    $n = 0
    foreach ($id in @($Ids)) {
        if ((Get-TweakRisk $id) -ne 'S') { continue }          # belt and braces: Safe only
        if ($c[$id] -and -not $c[$id].IsChecked) { $c[$id].IsChecked = $true; $n++ }
    }
    return $n
}

