        if ($pair[1] -eq $script:SrMode) {
            $g = New-Object System.Windows.Media.LinearGradientBrush
            $g.StartPoint = [System.Windows.Point]::new(0,0); $g.EndPoint = [System.Windows.Point]::new(1,1)
            $g.GradientStops.Add([System.Windows.Media.GradientStop]::new([System.Windows.Media.ColorConverter]::ConvertFromString('#8b6dff'), 0))
            $g.GradientStops.Add([System.Windows.Media.GradientStop]::new([System.Windows.Media.ColorConverter]::ConvertFromString('#6d4eea'), 1))
            $b.Background = $g; $b.Foreground = (Br '#FFFFFF')
        } else {
            $b.Background = (Br 'Transparent'); $b.Foreground = (Br '#8b8b9c')
        }
    }
}

function Stop-HomeSync {
