# ---- Home ----------------------------------------------------------------------------------
function ConvertTo-PlainUi { param([string]$s)
    if ($null -eq $s) { return '' }
    return (($s -replace [string][char]0xB7, '-') -replace [string][char]0xB0, ' ' -replace '[^\x20-\x7E]', '').Trim()
}

function Sync-HomeTiles {
    try {
        $cpuName = (ConvertTo-PlainUi $c['LblDashCpuLabel'].Text) -replace '^CPU\s*-\s*', ''
        $gpuName = (ConvertTo-PlainUi $c['LblDashGpuLabel'].Text) -replace '^GPU\s*-\s*', ''
        $ramName = (ConvertTo-PlainUi $c['LblDashRamLabel'].Text) -replace '^RAM\s*-\s*', ''
        $cv = ConvertTo-PlainUi $c['LblDashCpu'].Text
        $c['HomeCpuVal'].Text  = if ($cv -match '%') { "$($cv -replace '%','')% load" } else { $cv }
        $c['HomeCpuName'].Text = $cpuName
        $c['HomeCpuSub'].Text  = ConvertTo-PlainUi $c['LblDashCpuSub'].Text
        $gv = ConvertTo-PlainUi $c['LblDashGpu'].Text
        $c['HomeGpuVal'].Text  = if ($gv -match '^\d+\s*C$') { $gv } elseif ($gv -eq 'N/A') { 'No reading' } else { $gv }
        if ($gpuName -match 'None detected') {
            if (-not $script:HomeGpuFallback) {
                $script:HomeGpuFallback = 'Integrated graphics'
                try { $vc = Get-CachedCim Win32_VideoController | Select-Object -First 1; if ($vc.Name) { $script:HomeGpuFallback = [string]$vc.Name } } catch {}
            }
            $gpuName = $script:HomeGpuFallback
        }
        $c['HomeGpuName'].Text = $gpuName
        $c['HomeGpuSub'].Text  = if ($gv -eq 'N/A') { 'Temperature not available' } else { '' }
        $c['HomeRamVal'].Text  = ConvertTo-PlainUi $c['LblDashRam'].Text
        $c['HomeRamName'].Text = "$ramName installed"
        $c['HomeRamSub'].Text  = (ConvertTo-PlainUi $c['LblDashRamSub'].Text) -replace '^@\s*', 'Runs at '
        $pv = ConvertTo-PlainUi $c['LblDashPing'].Text
        $c['HomePingVal'].Text  = $pv -replace '^(\d+)ms$', '$1 ms'
        $c['HomePingName'].Text = 'Round trip to a test server'
        $c['HomePingSub'].Text  = "to $(ConvertTo-PlainUi $c['LblDashPingSub'].Text)"
        $c['HomeSparkCpu'].Points  = $c['SparkCpu'].Points
        $c['HomeSparkGpu'].Points  = $c['SparkGpu'].Points
        $c['HomeSparkRam'].Points  = $c['SparkRam'].Points
        $c['HomeSparkPing'].Points = $c['SparkPing'].Points
    } catch {}
}

# Illustrative setup score = share of the checkable gaming settings that are already on.
# Re-uses the list Load-ActiveBadges already built, so it adds no extra system queries.
# One score calculation, using the status checks already completed by Load-ActiveBadges.
# Explicit ActiveIds is also useful to callers projecting choices; it never runs a status query.
# Only known setting IDs can be persisted. The list is bounded and never accepts objects as IDs.
function Get-ValidUnavailableIds {
    param($Value)
    if (-not ($Value -is [array])) { return }
    $seen = @{}; $checked = 0
    foreach ($id in $Value) {
        if (++$checked -gt 256 -or $seen.Count -ge 128) { break }
        if ($id -isnot [string] -or $id.Length -gt 80 -or $id -notmatch '^Chk[A-Za-z0-9]+$') { continue }
        if ($script:TweakInfo -and $script:TweakInfo.ContainsKey($id) -and $c[$id] -and -not $seen.ContainsKey($id)) {
            $seen[$id] = $true; $id
        }
    }
}

function Get-ScoreLeftOutText {
    param([int]$Count)
    if ($Count -eq 1) { return '1 setting was left out because it is not available on this PC.' }
    if ($Count -gt 1) { return "$Count settings were left out because they are not available on this PC." }
    return ''
}

# A bool false is an applicable-but-off result only for these capability-aware probes.
# Other probes prove applicability when on, but missing default registry values do not prove hardware support.
function Test-ScoreCapabilityProbe {
    param([string]$Id)
    return ($Id -in @('ChkNaglesAlgo','ChkNicPowerSaving','ChkNicEeeDisable','ChkGpuAmdAntiLag'))
}

function Sync-ScoreAvailability {
    param([switch]$DeferSave)
    if (-not $script:SrSettings) { return }
    $old = @(Get-ValidUnavailableIds $script:SrSettings.unavailable)
    $new = @($old | Where-Object { $_ -notin $script:SetupScoreApplicableIds })
    $script:SrSettings.unavailable = $new
    if (($old -join '|') -ne ($new -join '|')) {
        if ($DeferSave -and $window) {
            if (-not $script:ScoreSavePending) {
                $script:ScoreSavePending = $true
                [void]$window.Dispatcher.BeginInvoke([System.Windows.Threading.DispatcherPriority]::ApplicationIdle,[Action]{
                    $script:ScoreSavePending = $false; Save-SrSettings
                })
            }
        } else { Save-SrSettings }
    }
}

# Called only by classified batch outcomes. A generic null, cancelled action, failed operation or Safe Mode lock is not evidence.
function Register-SettingOutcome {
    param([string]$Id,[string]$Reason)
    if (-not $script:SrSettings -or -not $script:TweakInfo.ContainsKey($Id) -or -not $c[$Id]) { return }
    $old = @(Get-ValidUnavailableIds $script:SrSettings.unavailable)
    if ($Reason -eq 'Succeeded') {
        $new = @($old | Where-Object { $_ -ne $Id })
        $script:SetupScoreNotApplicableIds = @($script:SetupScoreNotApplicableIds | Where-Object { $_ -ne $Id })
    } elseif ($Reason -in @('MissingTarget','Precondition','Protected','NotApplicable')) {
        $new = @(Get-ValidUnavailableIds (@($old) + @($Id)))
        # A pre-Apply probe must not immediately overrule a newer, authoritative skip.
        $script:SetupScoreApplicableIds = @($script:SetupScoreApplicableIds | Where-Object { $_ -ne $Id })
    } else { return }
    $script:SrSettings.unavailable = $new
    if (($old -join '|') -ne ($new -join '|')) { Save-SrSettings }
}

function Get-SetupScorePercent {
    param([int]$On,[int]$Total)
    if ($Total -le 0) { return 0 }
    return [int][math]::Round(100.0 * [math]::Min([math]::Max($On,0),$Total) / $Total)
}


function Get-SetupScore {
    param([string[]]$ActiveIds)
    $ready = $PSBoundParameters.ContainsKey('ActiveIds') -or $script:SetupScoreReady
    if (-not $ready) { return @{ Ready=$false; Score=0; On=0; Total=0; OnIds=@(); OffIds=@(); ExcludedCount=0 } }
    if (-not $PSBoundParameters.ContainsKey('ActiveIds')) { $ActiveIds = @($script:SetupScoreActiveIds) }
    $candidates = @($script:BadgeTests | Where-Object {
        $_.CheckboxName -and $c[$_.CheckboxName] -and $script:TweakInfo.ContainsKey($_.CheckboxName) -and
        -not ($_.CheckboxName -like 'ChkGpuNv*' -and $script:GpuVendor -ne 'nvidia') -and
        -not ($_.CheckboxName -like 'ChkGpuAmd*' -and $script:GpuVendor -ne 'amd')
    } | ForEach-Object { $_.CheckboxName } | Select-Object -Unique)
    $learned = @(Get-ValidUnavailableIds $script:SrSettings.unavailable | Where-Object { $_ -notin $script:SetupScoreApplicableIds })
    $excluded = @($candidates | Where-Object { $_ -in $script:SetupScoreNotApplicableIds -or $_ -in $learned })
    $eligible = @($candidates | Where-Object { $_ -notin $excluded })
    $onIds = @($eligible | Where-Object { $_ -in $ActiveIds })
    $offIds = @($eligible | Where-Object { $_ -notin $ActiveIds })
    return @{ Ready=$true; Score=(Get-SetupScorePercent $onIds.Count $eligible.Count); On=$onIds.Count; Total=$eligible.Count; OnIds=$onIds; OffIds=$offIds; ExcludedCount=$excluded.Count }
}

function Update-HomeScore {
    $state = Get-SetupScore
    foreach ($prefix in @('Home','Scan')) {
        $button = $c[('Btn'+$prefix+'Score')]
        if (-not $button) { continue }
        $hasScore = ($state.Ready -and $state.Total -gt 0)
        $c[($prefix+'ScoreNum')].Text = if ($hasScore) { [string]$state.Score } else { '-' }
        $c[($prefix+'ScoreTitle')].Text = if (-not $state.Ready) { 'Checking...' } elseif (-not $hasScore) { 'Nothing to score on this PC' } elseif ($state.Score -ge 70) { 'Looking good' } elseif ($state.Score -ge 35) { 'A good starting point' } else { 'Easy wins ahead' }
        $c[($prefix+'ScoreSub')].Text = if ($hasScore) { "$($state.On) of $($state.Total) settings on`r`nNot a speed score" } elseif ($state.Ready) { "No applicable settings were found.`r`nNot a speed score" } else { 'Not a speed score' }
        $c[($prefix+'RingArc')].StrokeDashArray = [System.Windows.Media.DoubleCollection]::new([double[]]@((26.7 * $state.Score / 100.0),100))
        $button.IsEnabled = ($hasScore -and $state.OffIds.Count -gt 0)
        $c[($prefix+'ScoreLink')].Text = if ($hasScore -and $state.OffIds.Count -eq 0) { 'Everything we check is on' } elseif ($hasScore) { 'See what to change' } else { '' }
        $c[($prefix+'ScoreExcluded')].Text = Get-ScoreLeftOutText $state.ExcludedCount
        $c[($prefix+'ScoreExcluded')].Visibility = if ($state.ExcludedCount -gt 0) { 'Visible' } else { 'Collapsed' }
        [System.Windows.Automation.AutomationProperties]::SetName($button, $(if ($hasScore) { "Setup score $($state.Score) out of 100. $($c[($prefix+'ScoreLink')].Text)" } elseif ($state.Ready) { 'Nothing to score on this PC' } else { 'Setup score: checking' }))
    }
}

function Get-ScoreProjection {
    param($State)
    $safe = @($State.OffIds | Where-Object { (Get-TweakRisk $_) -eq 'S' })
    $optional = @($State.OffIds | Where-Object { (Get-TweakRisk $_) -ne 'S' })
    $safeState = Get-SetupScore -ActiveIds (@($State.OnIds) + $safe)
    $allState = Get-SetupScore -ActiveIds (@($State.OnIds) + @($State.OffIds))
    return @{ Safe=$safe; Optional=$optional; SafeScore=$safeState.Score; AllScore=$allState.Score }
}

$script:ScoreReturnPage = 'PageHome'
function Show-RaiseScorePage {
    $state = Get-SetupScore
    if (-not $state.Ready -or $state.OffIds.Count -eq 0) { return }
    $script:ScoreReturnPage = if ($script:SrPage -eq 'PageScan') { 'PageScan' } else { 'PageHome' }
    $projection = Get-ScoreProjection $state
    $intro = if ($projection.Safe.Count -eq 0) { "Your score is $($state.Score). No Safe items are left off." }
        elseif ($projection.SafeScore -eq 100) { "Your score is $($state.Score). Switching on the $($projection.Safe.Count) Safe items can take it to 100." }
        else { "Switching on the $($projection.Safe.Count) Safe items can take your score from $($state.Score) to about $($projection.SafeScore)." }
    if ($projection.Optional.Count -gt 0) { $intro += " The $($projection.Optional.Count) optional Careful or Advanced items can take it to $($projection.AllScore). Read each one first." }
    if ($state.ExcludedCount -gt 0) { $intro += ' ' + (Get-ScoreLeftOutText $state.ExcludedCount) }
    $intro += ' This counts settings, not speed. Nothing changes until you press Apply.'
    if ($script:SrSettings.safeMode -and $projection.Optional.Count -gt 0) { $intro += ' Safe Mode locks the non-Safe items.' }
    Show-GoalPage -Key 'score' -Title 'Raise your score' -Intro $intro -Ids $projection.Safe -Links @() -Optional $projection.Optional
    $c['BtnGoalBack'].Content = if ($script:ScoreReturnPage -eq 'PageScan') { 'Back to Your PC' } else { 'Back to Home' }
}

function Return-FromScorePage {
    if ($script:GoalKey -eq 'score' -and $script:SrPage -eq 'PageGoal') { Show-SimplePage $script:ScoreReturnPage; Update-HomeScore }
    else { Show-SimplePage 'PageHome' }
}

# Only compare observed status checks with the same denominator; never infer success from a checkbox tick.
function Set-ScoreChange {
    param($Entry,$Before,$After)
    if ($Entry) { $Entry.Remove('ScoreBefore'); $Entry.Remove('ScoreAfter') }
    if (-not $Entry -or -not $Before -or -not $After -or -not $Before.Ready -or -not $After.Ready) { return }
    $afterIds = @($After.OnIds) + @($After.OffIds)
    $common = @((@($Before.OnIds) + @($Before.OffIds)) | Where-Object { $_ -in $afterIds } | Select-Object -Unique)
    if ($common.Count -eq 0) { return }
    # Rebase both observations on the same applicable IDs, so learning a skip cannot manufacture a drop.
    $Entry.ScoreBefore = Get-SetupScorePercent @($common | Where-Object { $_ -in $Before.OnIds }).Count $common.Count
    $Entry.ScoreAfter = Get-SetupScorePercent @($common | Where-Object { $_ -in $After.OnIds }).Count $common.Count
}


function Enter-Home {
    $stale = (([datetime]::Now - $script:HomeLastLoad).TotalSeconds -gt 60)
    if ($stale -and (Get-Command Load-Dashboard -ErrorAction SilentlyContinue)) {
        Load-Dashboard
        $script:HomeLastLoad = [datetime]::Now
    } elseif (Get-Command Start-DashboardMetricsTimer -ErrorAction SilentlyContinue) {
        Start-DashboardMetricsTimer
    }
    $laptop = Test-IsLaptop
    $c['HomeSubtitle'].Text = if ($laptop) { 'Laptop' } else { 'Desktop' }
    $c['HomeFixSub'].Text = if ($laptop) { 'A gentle starting set for your laptop. You see the list and choose what to add.' } else { 'A gentle starting set for your PC. You see the list and choose what to add.' }
    Build-HomePresets
    Sync-HomeTiles
    Update-HomeScore
    try { $script:HomeTimer.Start() } catch {}
}
$script:HomeTimer.Add_Tick({ Sync-HomeTiles })

function Build-HomeGoals {
    $c['HomeGoals'].Children.Clear()
    foreach ($g in $script:SrGoals) {
        $btn = New-Object System.Windows.Controls.Button
        $btn.Style = $window.FindResource('BtnCard')
        $btn.Tag = $g.Key
        $btn.MinHeight = 88
        $grid = New-Object System.Windows.Controls.Grid
        $a = New-Object System.Windows.Controls.ColumnDefinition; $a.Width = [System.Windows.GridLength]::new(36)
        $b = New-Object System.Windows.Controls.ColumnDefinition; $b.Width = [System.Windows.GridLength]::new(1, [System.Windows.GridUnitType]::Star)
        $grid.ColumnDefinitions.Add($a); $grid.ColumnDefinitions.Add($b)
        $cv = New-Object System.Windows.Controls.Canvas
        $cv.Width = 26; $cv.Height = 27; $cv.VerticalAlignment = 'Top'; $cv.HorizontalAlignment = 'Left'; $cv.Margin = [System.Windows.Thickness]::new(0,2,0,0)
        $p = New-Object System.Windows.Shapes.Path
        $p.Data = [System.Windows.Media.Geometry]::Parse($g.Icon)
        $p.Stroke = (Br '#a78bff'); $p.StrokeThickness = 1.7
        $p.StrokeStartLineCap = 'Round'; $p.StrokeEndLineCap = 'Round'; $p.StrokeLineJoin = 'Round'
        $cv.Children.Add($p) | Out-Null
        [System.Windows.Controls.Grid]::SetColumn($cv, 0)
        $grid.Children.Add($cv) | Out-Null
        $sp = New-Object System.Windows.Controls.StackPanel
        $sp.Children.Add((New-Text $g.Title 15 '#edecf3' 'SemiBold')) | Out-Null
        $sp.Children.Add((New-Text $g.Sub 12 '#8b8b9c')) | Out-Null
        if ($g.Locked) {
            $tag = New-Object System.Windows.Controls.Border
            $tag.Background = (Br '#1A7C5CFF'); $tag.BorderBrush = (Br '#597C5CFF'); $tag.BorderThickness = [System.Windows.Thickness]::new(1)
            $tag.CornerRadius = [System.Windows.CornerRadius]::new(9); $tag.Padding = [System.Windows.Thickness]::new(8,1,8,2)
            $tag.HorizontalAlignment = 'Left'; $tag.Margin = [System.Windows.Thickness]::new(0,6,0,0)
            $tag.Child = (New-Text 'Paid version' 11 '#a78bff' 'SemiBold')
            $sp.Children.Add($tag) | Out-Null
        }
        [System.Windows.Controls.Grid]::SetColumn($sp, 1)
        $grid.Children.Add($sp) | Out-Null
        $btn.Content = $grid
        $btn.Add_Click({ param($s, $e) Invoke-Goal ([string]$s.Tag) })
        $c['HomeGoals'].Children.Add($btn) | Out-Null
    }
}

function Add-ProLinks {
    param($Panel, $Links)
    foreach ($l in @($Links)) {
        $b = New-Object System.Windows.Controls.Button
        $b.Style = $window.FindResource('BtnGray')
        $b.Content = "Open in Pro: $($l[0])"
        $b.Height = 36; $b.HorizontalAlignment = 'Left'; $b.Margin = [System.Windows.Thickness]::new(0,0,0,8)
        $b.Tag = "$($l[1])|$($l[2])"
        $b.Add_Click({ param($s, $e) $p = ([string]$s.Tag).Split('|'); Open-ProArea $p[0] $p[1] })
        $Panel.Children.Add($b) | Out-Null
    }
}



# ---- first run ------------------------------------------------------------------------------
function Add-ScanRow {
    param([string]$Label, [string]$Value, [string]$Note)
    $card = New-Object System.Windows.Controls.Border
    $card.Background = (Br '#0d0d16'); $card.BorderBrush = (Br '#28242f'); $card.BorderThickness = [System.Windows.Thickness]::new(1)
    $card.CornerRadius = [System.Windows.CornerRadius]::new(8); $card.Padding = [System.Windows.Thickness]::new(14,9,14,9)
    $card.Margin = [System.Windows.Thickness]::new(0,0,0,8)
    $sp = New-Object System.Windows.Controls.StackPanel
    $sp.Children.Add((New-Text $Label 12 '#a78bff' 'SemiBold')) | Out-Null
    $sp.Children.Add((New-Text $Value 14 '#edecf3' 'SemiBold')) | Out-Null
    if ($Note) { $sp.Children.Add((New-Text $Note 12 '#8b8b9c')) | Out-Null }
    $card.Child = $sp
    $c['ScanList'].Children.Add($card) | Out-Null
}

function Show-ScanPage {
    Update-HomeScore
    $c['ScanList'].Children.Clear()
    $laptop = Test-IsLaptop
    Add-ScanRow 'TYPE OF PC' $(if ($laptop) { 'Laptop' } else { 'Desktop' }) $(if ($laptop) { 'A battery was found, so I will suggest gentle, cool-running settings.' } else { 'No battery was found, so this looks like a desktop.' })
    try {
        $cpu = Get-CachedCim Win32_Processor | Select-Object -First 1
        $nm = ($cpu.Name -replace '\(R\)|\(TM\)|CPU|@.*', '').Trim()
        Add-ScanRow 'PROCESSOR' "$nm" "$($cpu.NumberOfCores) cores, $($cpu.NumberOfLogicalProcessors) threads."
    } catch { Add-ScanRow 'PROCESSOR' 'Could not read' '' }
    $gn = if ($script:GpuName -and $script:GpuName -ne 'No discrete GPU detected') { $script:GpuName } else { 'No separate graphics card found' }
    Add-ScanRow 'GRAPHICS' $gn $(switch ($script:GpuVendor) { 'nvidia' { 'Nvidia graphics: I can suggest matching Nvidia options.' } 'amd' { 'AMD graphics: I can suggest matching AMD options.' } default { 'Only graphics options that fit your PC are suggested.' } })
    try {
        $gb = [math]::Round(((Get-CachedCim Win32_PhysicalMemory | Measure-Object Capacity -Sum).Sum / 1GB))
        Add-ScanRow 'MEMORY' "$gb GB" $(if ($gb -ge 16) { 'Plenty for most games.' } elseif ($gb -ge 8) { 'Enough for most games.' } else { 'On the small side, so fewer background apps help.' })
    } catch { Add-ScanRow 'MEMORY' 'Could not read' '' }
    try {
        $d = @(Get-PhysicalDisk -ErrorAction Stop | Select-Object -First 3 | ForEach-Object {
            $t = if ($_.BusType -eq 'NVMe') { 'NVMe SSD' } elseif ($_.MediaType -eq 'SSD') { 'SSD' } elseif ($_.MediaType -eq 'HDD') { 'Hard drive' } else { 'Drive' }
            "$t, $([math]::Round($_.Size / 1GB)) GB" })
        if ($d.Count -gt 0) { Add-ScanRow 'STORAGE' ($d -join ' and ') 'Fast storage means quicker loading.' }
    } catch {}
    try {
        $ds = Get-DisplayStatus
        if ($ds.CurrentHz -gt 0) { Add-ScanRow 'SCREEN' "$($ds.CurrentHz) Hz" $(if ($ds.AtMax) { 'Already at the best refresh rate for this screen.' } else { "This screen can go up to $($ds.MaxHz) Hz. You can change it in Pro, Gaming tools." }) }
    } catch {}
    try {
        $na = Get-NetworkAdapterStatus
        Add-ScanRow 'INTERNET' $(if ($na.OnWifi) { 'WiFi' } elseif ($na.HasEthernet) { 'Cable' } else { 'Not connected' }) $(if ($na.OnWifi) { 'A cable is steadier for games, if you can use one.' } else { '' })
    } catch {}
    $c['ScanIntro'].Text = 'This check only reads your PC. Nothing was changed. I use it to suggest settings that fit.'
    Show-SimplePage 'PageScan'
}

function Show-PlanPage {
    $script:PlanIds = Get-GoalIds 'recommended'
    $laptop = Test-IsLaptop
    $c['PlanTitle'].Text = 'Here is what I suggest.'
    $c['PlanIntro'].Text = if ($laptop) { "These suit your laptop. The Safe ones are switched on. Optional extras start switched off. Change anything you like, then press Get my PC ready." } else { "These suit your PC. The Safe ones are switched on. Optional extras start switched off. Change anything you like, then press Get my PC ready." }
    $c['PlanMore'].Text = ''
    $extras = @(Get-GoalCandidates 'recommended' | Where-Object { $_ -notin $script:PlanIds })
    $groups = @()
    if ($script:PlanIds.Count -gt 0) { $groups += @{ Title = 'Safe starting items'; Sub = 'Switched on for you.'; Ids = @($script:PlanIds); On = $true; Links = $false } }
    if ($extras.Count -gt 0) { $groups += @{ Title = 'Optional Careful changes. Read the effects and recovery notes before choosing.'; Sub = 'These start switched off.'; Ids = $extras; On = $false; Links = $true } }
    $script:PlanState = Build-ChoiceList -Panel $c['PlanList'] -Groups $groups -Ctx 'recommended'
    $script:ActiveState = $script:PlanState
    Show-SimplePage 'PagePlan'
}

$script:PlanIds = @(); $script:PlanState = $null
$c['BtnScanBack'].Add_Click({ Show-SimplePage 'PageWelcome' })
$c['BtnScanNext'].Add_Click({ Show-PlanPage })
$c['BtnPlanSkip'].Add_Click({ Complete-Welcome; Show-SimplePage 'PageHome' })
$c['BtnPlanGo'].Add_Click({
    $ids = Get-ChoiceOn $script:PlanState
    [void](Add-ChosenIds $ids)
    Complete-Welcome; Update-Count
    Show-SimplePage 'PageBasket'
})

function Complete-Welcome {
    $script:SrSettings.welcomeDone = $true
    Save-SrSettings
}

# ---- search --------------------------------------------------------------------------------
# ---- handlers ------------------------------------------------------------------------------
$c['BtnModeSimple'].Add_Click({ Set-UiMode 'simple' })
$c['BtnModePro'].Add_Click({ Set-UiMode 'pro' })
$c['BtnHelp'].Add_Click({ Show-SimplePage 'PageHelp' })
$c['BtnGoalBack'].Add_Click({ Return-FromScorePage })
$c['BtnScoreInfo'].Add_Click({
    $c['HomeScoreExplain'].Visibility = if ($c['HomeScoreExplain'].Visibility -eq 'Visible') { 'Collapsed' } else { 'Visible' }
})
$c['BtnFixMatters'].Add_Click({
    $ids = Get-GoalIds 'recommended'
    $opt = @(Get-GoalCandidates 'recommended' | Where-Object { $_ -notin $ids })
    Write-SR "Fix what matters most opened: $(@($ids).Count) Safe item(s) and $($opt.Count) optional extra(s) listed (nothing ticked, nothing applied)" 'INFO'
    $c['LogText'].Text = 'Look through the list, then press Add to review list. Nothing changes until you press Apply.'
    Show-GoalPage -Key 'recommended' -Title 'Your recommended starting set' -Intro 'These Safe items suit your PC and are switched on. Switch off anything you do not want, then press Add to review list.' -Ids $ids -Links @() -Recommended (Test-IsLaptop) -Optional $opt
})
$c['BtnWelcomeStart'].Add_Click({ Show-ScanPage })
$c['BtnListAdd'].Add_Click({ Invoke-ListAdd })
$c['BtnListBack'].Add_Click({ Return-FromScorePage })
$c['BtnHomeScore'].Add_Click({ Show-RaiseScorePage })
$c['BtnScanScore'].Add_Click({ Show-RaiseScorePage })
$c['BtnPresetBack'].Add_Click({ Show-SimplePage 'PageHome' })
$c['ChkPresetAck'].Add_Checked({ Update-ChoiceCount $script:ActiveState })
$c['ChkPresetAck'].Add_Unchecked({ Update-ChoiceCount $script:ActiveState })
$c['TxtSearch'].Add_TextChanged({
    $t = $c['TxtSearch'].Text
    $c['TxtSearchHint'].Visibility = if ($t.Length -gt 0) { 'Collapsed' } else { 'Visible' }
    if ($t.Trim().Length -ge 2) { Show-SearchResults $t }
    elseif ($t.Trim().Length -eq 1 -and $script:SrPage -eq 'PageSearch') { $c['SearchTitle'].Text = 'Keep typing'; $c['SearchSub'].Text = 'Type at least two letters to search.'; $c['SearchItems'].Children.Clear() }
    elseif ($t.Length -eq 0 -and $script:SrPage -eq 'PageSearch') { Set-UiMode $script:SrMode }
})

# Called once from the deferred start-up block, after the existing data loads have finished.
function Initialize-ShellUi {
    $script:SrSettings = Read-SrSettings
    Sync-ScoreAvailability -DeferSave
    $script:HomeLastLoad = [datetime]::Now
    Build-HomeGoals
    Initialize-Stage2
    # The start mode is decided here, once. A first run (no welcomeDone flag) is always Simple, whatever an old settings file says,
    # so the switch, the navigation and the page agree from the first frame. Later runs honour the saved mode.
    if (-not $script:SrSettings.welcomeDone) { $script:SrSettings.mode = 'simple' }
    $script:SrMode = $script:SrSettings.mode
    Set-ModeButtons
    if (-not $script:SrSettings.welcomeDone) {
        Show-SimplePage 'PageWelcome'
    } elseif ($script:SrMode -eq 'pro') {
        Set-UiMode 'pro'
    } else {
        Show-SimplePage 'PageHome'
    }
}

#endregion v7 Shell


#region v7 Stage 2: nav row, review basket, apply and results, history, tweak table, My PC, settings, palette
# Same rule as stage 1: this only changes the shell. The batch engine (Invoke-TweakBatch), the Undo handler and
# every Apply- function are the original code. Apply from the basket page raises the original BtnApplyAll click.

# ---- settings (extends the stage 1 file: safeMode, largeText, remind) ----------------------------
function Read-SrSettings {
    $d = @{ welcomeDone = $false; mode = 'simple'; safeMode = $false; largeText = $false; unavailable = @() }
    try {
        if (Test-Path $script:SrSettingsPath) {
            $raw = Get-Content $script:SrSettingsPath -Raw -EA Stop
            if ($raw.Length -gt 65536) { return $d }
            $j = $raw | ConvertFrom-Json -EA Stop
            if ($j -isnot [pscustomobject]) { return $d }
            $d.unavailable = @(Get-ValidUnavailableIds $j.unavailable)
            foreach ($k in @('welcomeDone','safeMode','largeText')) { if ($null -ne $j.$k) { $d[$k] = [bool]$j.$k } }
            if ($j.mode -eq 'pro') { $d.mode = 'pro' }
        }
    } catch {}
    return $d
}
function Save-SrSettings {
    try {
        if (-not (Test-Path $script:SrSettingsDir)) { New-Item $script:SrSettingsDir -ItemType Directory -Force | Out-Null }
        $s = $script:SrSettings
        # read-modify-write: keys this edition does not own (for example the paid app's reminder preference) are kept as they are
        $out = [ordered]@{}
        try {
            if (Test-Path -LiteralPath $script:SrSettingsPath) {
                $old = Get-Content -LiteralPath $script:SrSettingsPath -Raw -EA Stop | ConvertFrom-Json
                if ($old) { foreach ($p in $old.PSObject.Properties) { $out[$p.Name] = $p.Value } }
            }
        } catch {}
        $out['welcomeDone'] = [bool]$s.welcomeDone; $out['mode'] = [string]$s.mode; $out['safeMode'] = [bool]$s.safeMode; $out['largeText'] = [bool]$s.largeText
        $out['unavailable'] = @(Get-ValidUnavailableIds $s.unavailable)
        $out | ConvertTo-Json | Set-Content -LiteralPath $script:SrSettingsPath -Encoding UTF8
    } catch { Write-SR "Could not save settings: $($_.Exception.Message)" 'WARN' }
}
$script:SrSettings = @{ welcomeDone = $false; mode = 'simple'; safeMode = $false; largeText = $false; unavailable = @() }

# ---- risk helpers ----------------------------------------------------------------------------------
function Get-SelectedNames { return @($tweakBoxes | Where-Object { $c[$_] -and $c[$_].IsChecked }) }
function Get-RiskCounts {
    param([string[]]$Names)
    $r = @{ S = 0; C = 0; A = 0 }
    foreach ($n in @($Names)) { switch (Get-TweakRisk $n) { 'S' { $r.S++ } 'A' { $r.A++ } default { $r.C++ } } }
    return $r
}
function Get-PlainName { param([string]$Id)
    if ($script:TweakInfo.ContainsKey($Id)) { return $script:TweakInfo[$Id].Name }
    if ($c[$Id] -and $c[$Id].Content) { return [string]$c[$Id].Content }
    return $Id
}
$script:AreaNames = @{ G = 'Gaming and streaming'; U = 'Graphics card'; P = 'Privacy and clean-up'; W = 'Windows'; D = 'Updates' }
# Settings that only start working after a restart (used for the "Restart later / Restart now" banner).
$script:RebootIds = @('ChkHwGpu','ChkVbsDisable','ChkBcdTweaks','ChkDisableFastStartup','ChkNicIntMod','ChkDisableMultiplaneOverlay',
    'ChkAhciLpmOff','ChkPcieAspm','ChkDisableIPv6','ChkSetUtcTime','ChkDisablePageExec','ChkNicPowerSaving','ChkNicEeeDisable','ChkDetailedBSOD','ChkMemCompDisable')
# Power-hungry settings that the Laptop preset leaves out (used by "Only for my PC" on a laptop).
$script:LaptopHostile = @('ChkHighPerf','ChkUltPerf','ChkTimerRes','ChkCoreParkingDisable','ChkUsbSuspend','ChkPcieAspm','ChkAhciLpmOff','ChkNicPowerSaving','ChkNicEeeDisable','ChkPowerThrottle')
function Test-ForMyPc { param([string]$Id)
    if ($Id -like 'ChkGpuNv*' -or $Id -eq 'ChkNvidiaShaderCache') { return ($script:GpuVendor -eq 'nvidia') }
    if ($Id -like 'ChkGpuAmd*') { return ($script:GpuVendor -eq 'amd') }
    if ((Test-IsLaptop) -and ($Id -in $script:LaptopHostile)) { return $false }
    return $true
}

# ---- Safe Mode: Careful and Advanced boxes cannot be ticked ---------------------------------------
$script:SafeGuard = $false
function Test-SafeModeGuard {
    param($Chk)
    if (-not $script:SrSettings.safeMode -or $script:SafeGuard) { return }
    $id = [string]$Chk.Name
    if ((Get-TweakRisk $id) -ne 'S') {
        $script:SafeGuard = $true
        try { $Chk.IsChecked = $false } finally { $script:SafeGuard = $false }
        $c['LogText'].Text = "Safe Mode is on, so '$(Get-PlainName $id)' stays off. Turn Safe Mode off in Settings to use it."
    }
}
foreach ($n in $tweakBoxes) { if ($c[$n]) { $c[$n].Add_Checked({ param($s, $e) Test-SafeModeGuard $s }) } }

# ---- navigation (replaces the stage 1 versions) ------------------------------------------------------
$script:SrPages = @('PageScan','PagePlan','PageWelcome','PageHome','PageGoal','PagePreset','PageProArea','PageSearch','PageHelp','PageBasket','PageApplying','PageResult','PageHistory','PageMyPc','PageSettings','PageTable','PagePaid')
$script:SrPageNav = @{ PageHome = 'BtnNavHome'; PageGoal = 'BtnNavHome'; PagePreset = 'BtnNavHome'; PageMyPc = 'BtnNavMyPc'; PageHistory = 'BtnNavHistory'; PageResult = 'BtnNavHistory'; PageApplying = 'BtnNavHistory'; PageSettings = 'BtnNavSettings' }
function Set-NavActive {
    param([string]$Active)
    foreach ($n in @('BtnNavHome','BtnNavMyPc','BtnNavHistory','BtnNavSettings')) {
        $b = $c[$n]
        if ($n -eq $Active) { $b.BorderBrush = (Br '#7c5cff'); $b.Foreground = (Br '#edecf3') }
        else { $b.BorderBrush = (Br 'Transparent'); $b.Foreground = (Br '#8b8b9c') }
    }
}
function Show-SimplePage {
    param([string]$Name)
    $c['ProHost'].Visibility    = 'Collapsed'
    $c['SimpleHost'].Visibility = 'Visible'
    # Home, goal, preset and welcome pages only exist in Simple: showing one of them always puts the mode back to Simple
    if ($Name -in @('PageScan','PagePlan','PageWelcome','PageHome','PageGoal','PagePreset') -and $script:SrMode -ne 'simple') { $script:SrMode = 'simple'; $script:SrSettings.mode = 'simple' }
    Set-ModeButtons
    foreach ($p in $script:SrPages) { $c[$p].Visibility = if ($p -eq $Name) { 'Visible' } else { 'Collapsed' } }
    $script:SrPage = $Name
    try { $c['SimpleScroll'].ScrollToTop() } catch {}
    $c['ActionBar'].Visibility = if ($Name -in @('PageScan','PagePlan','PageWelcome','PageGoal','PagePreset')) { 'Visible' } else { 'Collapsed' }
    $c['BarList'].Visibility    = if ($Name -in @('PageGoal','PagePreset')) { 'Visible' } else { 'Collapsed' }
    $c['BarWelcome'].Visibility = if ($Name -eq 'PageWelcome') { 'Visible' } else { 'Collapsed' }
    $c['BarScan'].Visibility = if ($Name -eq 'PageScan') { 'Visible' } else { 'Collapsed' }
    $c['BarPlan'].Visibility = if ($Name -eq 'PagePlan') { 'Visible' } else { 'Collapsed' }
    Set-NavActive $(if ($script:SrPageNav.ContainsKey($Name)) { $script:SrPageNav[$Name] } else { '' })
    $showProNav = ($script:SrMode -eq 'pro' -and $Name -notin @('PageWelcome','PageScan','PagePlan'))
    $c['ProNav'].Visibility = if ($showProNav) { 'Visible' } else { 'Collapsed' }
    $c['NavRow'].Visibility = if ($showProNav -or $Name -in @('PageWelcome','PageScan','PagePlan')) { 'Collapsed' } else { 'Visible' }
    if ($script:ProBuilt) {
        $pk = switch ($Name) { 'PageTable' { 'everything' } 'PageProArea' { $script:ProAreaKey } 'PageMyPc' { 'mypc' } 'PageHistory' { 'history' } 'PageResult' { 'history' } 'PageApplying' { 'history' } 'PageSettings' { 'settings' } default { '' } }
        Set-ProNavActive $pk
    }
    Update-BottomBarState
    if ($Name -ne 'PageProArea' -and (Get-Command Stop-DashboardMetricsTimer -ErrorAction SilentlyContinue) -and $Name -ne 'PageHome') { Stop-DashboardMetricsTimer }
    if ($Name -eq 'PageHome') { Enter-Home } else { Stop-HomeSync }
    switch ($Name) {
        'PageBasket'   { Refresh-BasketPage }
        'PageHistory'  { Refresh-HistoryPage }
        'PageMyPc'     { Refresh-MyPcPage }
        'PageSettings' { Refresh-SettingsPage }
        'PageTable'    { Refresh-TablePage }
    }
}
# ---- goals: Safe items are ticked, other related items are offered (never ticked) ----------------------
function Get-GoalCandidates {
    param([string]$Key)
    $ids = @()
    switch ($Key) {
        'play'        { $ids = @(Get-SafeGamingTweakSet) }
        'stream'      { $ids = @(Get-SafeGamingTweakSet) + @('ChkObsPriority','ChkSoundDucking','ChkNoAutoRestart') }
        'internet'    { $ids = @('ChkDeliveryOpt','ChkDisableDeliveryWU','ChkQoS','ChkNetworkThrottle','ChkNaglesAlgo','ChkTcpGameTweaks','ChkNicLatency') }
        'clean'       { $ids = @('ChkVisualPerf','ChkFastShutdown','ChkDisableExplorerFolderDiscovery','ChkStartMenuRec','ChkConsumer','ChkSetDisplayPerf') }
        'privacy'     { $ids = @('ChkAds','ChkActivityHistory','ChkPs7Tele','ChkBingSearch','ChkConsumer','ChkDisableCrossDevice','ChkTelemetry','ChkLocation','ChkCopilot','ChkWidgets') }
        'recommended' { $ids = @(Get-SafeGamingTweakSet) }
    }
    if ($Key -in @('play','stream','recommended')) {
        if ($script:GpuVendor -eq 'nvidia') { $ids += @($script:GpuVendorSafeTweaks.Nvidia) }
        elseif ($script:GpuVendor -eq 'amd') { $ids += @($script:GpuVendorSafeTweaks.Amd) }
    }
    $out = [System.Collections.Generic.List[string]]::new()
    foreach ($id in $ids) {
        if ($id -and $c[$id] -and ($id -in $tweakBoxes) -and -not $out.Contains($id) -and ((Get-TweakRisk $id) -ne 'A')) { $out.Add($id) }
    }
    return @($out)
}
# Only these are ever ticked for the user.
function Get-GoalIds {
    param([string]$Key)
    return @(Get-GoalCandidates $Key | Where-Object { (Get-TweakRisk $_) -eq 'S' })
}

# Message box wrapper used by the preset dialogs (the same call as [System.Windows.MessageBox]::Show).
$script:PresetMsg = New-Object psobject
Add-Member -InputObject $script:PresetMsg -MemberType ScriptMethod -Name Show -Value {
    param($Text, $Title, $Buttons, $Image)
    return [System.Windows.MessageBox]::Show($Text, $Title, $Buttons, $Image)
}

# ---- choice lists (round 2): every suggested item is a visible row with its own switch ------------------------------
# The switches on these pages are local. Nothing is ticked in the real list until the user presses the page's
# button (Add to review basket / Get my PC ready), and even then nothing is applied: Apply stays on the basket page.
$script:ChoiceStates = @{}
$script:ChoiceSeq = 0
$script:ActiveState = $null
$script:PresetKey = ''

function Get-ItemReason {
    param([string]$Id, [string]$Ctx = '')
    $lap = Test-IsLaptop
    if ($Id -like 'ChkGpuNv*' -or $Id -eq 'ChkNvidiaShaderCache') { return 'Suggested because your PC has Nvidia graphics.' }
    if ($Id -like 'ChkGpuAmd*') { return 'Suggested because your PC has AMD graphics.' }
    switch ($Id) {
        'ChkObsPriority'   { return 'Gives your streaming program a fair share of the processor.' }
        'ChkSoundDucking'  { return 'Stops Windows turning your game or stream sound down on its own.' }
        'ChkNoAutoRestart' { return 'Requests no automatic update restart while a user is signed in.' }
        'ChkHighPerf'      { return $(if ($lap) { 'Keeps the processor busy, which drains a laptop battery faster.' } else { 'Keeps the processor ready, which suits a desktop plugged into the wall.' }) }
        'ChkUltPerf'       { return $(if ($lap) { 'Uses a lot of power, so it is not a good fit for a laptop.' } else { 'Selects Ultimate Performance when available. It may use more power.' }) }
    }
    switch -Wildcard ($Ctx) {
        'internet'  { return 'Can help with lag spikes and ping.' }
        'clean'     { return 'Makes Windows feel lighter.' }
        'privacy'   { return 'Limits what Windows collects or shows.' }
        'stream'    { return 'Helps your game and your stream share the PC.' }
        'game'      { return 'Helps one game run its best.' }
        'score'     { return 'This setting is counted in your setup score and its last check was off.' }
        'preset:*'  {
            $p = $Ctx.Substring(7)
            switch ($p) {
                'gaming'      { return 'Part of the Gaming preset: smoother games.' }
                'streaming'   { return 'Part of the Streaming preset: a game and a stream side by side.' }
                default       { return 'Part of this preset. Read what it changes before you keep it.' }
            }
        }
    }
    if ($Id -in @(Get-SafeGamingTweakSet)) { return $(if ($lap) { 'Helps games run smoothly.' } else { 'Helps games run smoothly on a desktop.' }) }
    return 'Read what this setting changes and how to reverse it.'
}

function New-ChoiceRow {
    param([string]$Id, [bool]$On, [string]$Ctx, [string]$StateKey)
    $info = $script:TweakInfo[$Id]
    if (-not $info -or -not $c[$Id]) { return $null }
    $risk = $info.Risk
    $locked = ($script:SrSettings.safeMode -and $risk -ne 'S')
    $card = New-Object System.Windows.Controls.Border
    $card.Background = (Br '#0d0d16'); $card.BorderBrush = (Br '#28242f')
    $card.BorderThickness = [System.Windows.Thickness]::new(1)
    $card.CornerRadius = [System.Windows.CornerRadius]::new(8)
    $card.Padding = [System.Windows.Thickness]::new(14,10,14,10)
    $card.Margin = [System.Windows.Thickness]::new(0,0,0,8)
    $card.ToolTip = "Original name: $($info.Tech)"
    if ($locked) { $card.Opacity = 0.6 }
    $g = New-Object System.Windows.Controls.Grid
    $c0 = New-Object System.Windows.Controls.ColumnDefinition; $c0.Width = [System.Windows.GridLength]::Auto
    $c1 = New-Object System.Windows.Controls.ColumnDefinition; $c1.Width = [System.Windows.GridLength]::new(1, [System.Windows.GridUnitType]::Star)
    $g.ColumnDefinitions.Add($c0); $g.ColumnDefinitions.Add($c1)
    $cb = New-Object System.Windows.Controls.CheckBox
    $cb.Style = $window.FindResource('Chk')
    $cb.VerticalAlignment = 'Top'
    $cb.Margin = [System.Windows.Thickness]::new(0,2,14,0)
    $cb.Tag = $Id
    $cb.Uid = $StateKey
    $cb.IsChecked = ($On -and -not $locked)
    $cb.IsEnabled = (-not $locked)
    [System.Windows.Controls.Grid]::SetColumn($cb, 0)
    $g.Children.Add($cb) | Out-Null
    $sp = New-Object System.Windows.Controls.StackPanel
    $sp.Children.Add((New-Text $info.Name 14 '#edecf3' 'SemiBold')) | Out-Null
    $sp.Children.Add((New-Text $info.Desc 13 '#c9c7d6')) | Out-Null
    $sp.Children.Add((New-Text (Get-ItemReason $Id $Ctx) 12 '#a78bff')) | Out-Null
    if ($locked) { $sp.Children.Add((New-Text 'Safe Mode is on, so this stays off. Turn Safe Mode off in Settings to choose it.' 12 '#f0b545')) | Out-Null }
    $meta = New-Object System.Windows.Controls.StackPanel
    $meta.Orientation = 'Horizontal'; $meta.Margin = [System.Windows.Thickness]::new(0,6,0,0)
    $meta.Children.Add((New-RiskBadge $risk)) | Out-Null
    if (Test-TweakAlreadyOn $Id) { $meta.Children.Add((New-Text 'Already on' 12 '#56dd92')) | Out-Null }
    if ($Id -in $script:RebootIds) { $meta.Children.Add((New-Text '  Restart needed' 12 '#f0b545')) | Out-Null }
    $sp.Children.Add($meta) | Out-Null
    $sp.Children.Add((New-Text "Original name: $($info.Tech)" 11 '#6b6b7c')) | Out-Null
    [System.Windows.Controls.Grid]::SetColumn($sp, 1)
    $g.Children.Add($sp) | Out-Null
    $card.Child = $g
    $h = { param($s, $e) Update-ChoiceCount $script:ChoiceStates[[string]$s.Uid] }
    $cb.Add_Checked($h); $cb.Add_Unchecked($h)
    return @{ Card = $card; Box = $cb }
}

function New-LinkButton {
    param([string]$Text, [string]$Uid)
    $b = New-Object System.Windows.Controls.Button
    $b.Style = $window.FindResource('BtnLink'); $b.Content = $Text; $b.Uid = $Uid
    $b.Margin = [System.Windows.Thickness]::new(0,0,14,6)
    return $b
}

# Groups: @{ Title; Sub; Ids; On; Links } in display order. Returns the state (boxes, counts text).
function Build-ChoiceList {
    param($Panel, $Groups, [string]$Ctx, [string]$Button = '', [string]$ButtonFormat = '')
    $Panel.Children.Clear()
    $script:ChoiceSeq++
    $key = "S$($script:ChoiceSeq)"
    $counts = New-Text '' 13 '#edecf3' 'SemiBold'
    $counts.Margin = [System.Windows.Thickness]::new(2,0,0,10)
    $state = @{ Key = $key; Boxes = [System.Collections.Generic.List[object]]::new(); Groups = @(); Count = $counts; Button = $Button; ButtonFormat = $ButtonFormat; ShowAdvanced = $false; LinkAll = $null; LinkClear = $null }
    $script:ChoiceStates[$key] = $state
    $Panel.Children.Add($counts) | Out-Null
    $gi = 0
    foreach ($grp in $Groups) {
        $ids = @($grp.Ids | Where-Object { $_ })
        if ($ids.Count -eq 0) { continue }
        $head = New-Text $grp.Title 15 '#edecf3' 'SemiBold'
        $head.Margin = [System.Windows.Thickness]::new(2,6,0,2)
        $Panel.Children.Add($head) | Out-Null
        if ($grp.Sub) { $sub = New-Text $grp.Sub 12 '#8b8b9c'; $sub.Margin = [System.Windows.Thickness]::new(2,0,0,6); $Panel.Children.Add($sub) | Out-Null }
        $gBoxes = [System.Collections.Generic.List[object]]::new()
        if ($grp.Links) {
            $lp = New-Object System.Windows.Controls.StackPanel; $lp.Orientation = 'Horizontal'
            $la = New-LinkButton 'Select all extras' "$key|$gi|all"
            $lc = New-LinkButton 'Clear extras' "$key|$gi|clear"
            $la.Add_Click({ param($s, $e) Set-ChoiceGroup ([string]$s.Uid) })
            $lc.Add_Click({ param($s, $e) Set-ChoiceGroup ([string]$s.Uid) })
            $lp.Children.Add($la) | Out-Null; $lp.Children.Add($lc) | Out-Null
            $Panel.Children.Add($lp) | Out-Null
            $state.LinkAll = $la; $state.LinkClear = $lc
        }
        foreach ($id in $ids) {
            $row = New-ChoiceRow -Id $id -On ([bool]$grp.On) -Ctx $Ctx -StateKey $key
            if (-not $row) { continue }
            $Panel.Children.Add($row.Card) | Out-Null
            $state.Boxes.Add($row.Box); $gBoxes.Add($row.Box)
            if ((Get-TweakRisk $id) -eq 'A') { $state.ShowAdvanced = $true }
        }
        $state.Groups += ,$gBoxes
        $gi++
    }
    if ($state.Boxes.Count -eq 0) {
        $t = New-Text 'Nothing is suggested for this PC here.' 13 '#8b8b9c'
        $Panel.Children.Add($t) | Out-Null
    }
    Update-ChoiceCount $state
    return $state
}

function Set-ChoiceGroup {
    param([string]$Uid)
    $p = $Uid.Split('|')
    $st = $script:ChoiceStates[$p[0]]
    if (-not $st) { return }
    $on = ($p[2] -eq 'all')
    foreach ($cb in $st.Groups[[int]$p[1]]) { if ($cb.IsEnabled) { $cb.IsChecked = $on } }
    if ($on -and $script:SrSettings.safeMode) { $c['LogText'].Text = 'Safe Mode is on, so Careful extras stay off. Turn Safe Mode off in Settings to choose them.' }
}

function Get-ChoiceOn {
    param($State)
    if (-not $State) { return @() }
    return @($State.Boxes | Where-Object { $_.IsChecked } | ForEach-Object { [string]$_.Tag })
}

function Update-ChoiceCount {
    param($State)
    if (-not $State) { return }
    $on = Get-ChoiceOn $State
    $r = Get-RiskCounts $on
    $State.Count.Text = if ($State.ShowAdvanced) { "Switched on here: $($r.S) Safe, $($r.C) Careful, $($r.A) Advanced. These are local choices. Some may already be in your review list." } else { "Switched on here: $($r.S) Safe, $($r.C) Careful. These are local choices. Some may already be in your review list." }
    if ($State.Button -and $c[$State.Button]) {
        $n = $on.Count
        if ($State.ButtonFormat) { $c[$State.Button].Content = ($State.ButtonFormat -f $n) }
        $ok = ($n -gt 0)
        $needAck = ($State.Key -eq $script:ActiveState.Key -and $script:SrPage -eq 'PagePreset' -and $c['PresetWarn'].Visibility -eq 'Visible' -and -not $c['ChkPresetAck'].IsChecked)
        if ($needAck) { $ok = $false }
        $c[$State.Button].IsEnabled = $ok
        if ($State.Key -eq $script:ActiveState.Key -and $script:SrPage -eq 'PagePreset') { $c['LblListHint'].Text = if ($needAck) { 'Switch on "I understand" in the box above to use this button.' } else { 'Only what is switched on is added. Nothing changes until you press Apply.' } }
    }
}

# Ticks the chosen ids in the real list. Never applies. Advanced ids only when -AllowAdvanced (presets).
function Add-ChosenIds {
    param([string[]]$Ids, [switch]$AllowAdvanced)
    $n = 0
    foreach ($id in @($Ids)) {
        $risk = Get-TweakRisk $id
        if ($risk -eq 'A' -and -not $AllowAdvanced) { continue }
        if ($script:SrSettings.safeMode -and $risk -ne 'S') { continue }
        if ($c[$id] -and -not $c[$id].IsChecked) { $c[$id].IsChecked = $true; if ($c[$id].IsChecked) { $n++ } }
    }
    return $n
}

function Show-GoalPage {
    param([string]$Key, [string]$Title, [string]$Intro, [string[]]$Ids, $Links, [bool]$Recommended = $false, [string[]]$Optional = @())
    $c['BtnGoalBack'].Content = 'Back to Home'
    $c['GoalTitle'].Text = $Title
    $c['GoalIntro'].Text = $Intro
    $c['GoalRecBadge'].Visibility = if ($Recommended) { 'Visible' } else { 'Collapsed' }
    $c['GoalItems'].Children.Clear()
    $c['GoalOptional'].Children.Clear()
    $c['GoalOptTitle'].Visibility = 'Collapsed'
    $c['GoalLinks'].Children.Clear()
    $ctx = switch ($Key) { 'play' { 'play' } 'stream' { 'stream' } 'internet' { 'internet' } 'clean' { 'clean' } 'privacy' { 'privacy' } 'game' { 'game' } 'score' { 'score' } default { 'recommended' } }
    $groups = @()
    if (@($Ids).Count -gt 0) { $groups += @{ Title = 'Safe starting items'; Sub = 'Switched on for you. Switch off anything you do not want.'; Ids = @($Ids); On = $true; Links = $false } }
    else { $t = New-Text 'No Safe items are suggested for this goal, so nothing is switched on for you.' 13 '#8b8b9c'; $t.Margin = [System.Windows.Thickness]::new(0,0,0,12); $c['GoalItems'].Children.Add($t) | Out-Null }
    $opt = @($Optional | Where-Object { $_ })
    if ($opt.Count -gt 0) { $groups += @{ Title = $(if ($Key -eq 'score') { 'Optional Careful or Advanced changes. Read each item first.' } else { 'Optional Careful changes. Read the effects and recovery notes before choosing.' }); Sub = 'These start switched off. Switch on only what you want.'; Ids = $opt; On = $false; Links = $true } }
    $script:ActiveState = Build-ChoiceList -Panel $c['GoalItems'] -Groups $groups -Ctx $ctx -Button 'BtnListAdd' -ButtonFormat 'Add to review list ({0})'
    $c['BtnListAdd'].Visibility = if ($script:ActiveState.Boxes.Count -gt 0) { 'Visible' } else { 'Collapsed' }
    $script:GoalKey = $Key
    Add-ProLinks $c['GoalLinks'] $Links
    Show-SimplePage 'PageGoal'
}
$script:GoalKey = ''
function Invoke-Goal {
    param([string]$Key)
    $g = $script:SrGoals | Where-Object { $_.Key -eq $Key } | Select-Object -First 1
    if (-not $g) { return }
    if ($g.Locked) { Show-PaidPage; return }     # paid-only goal: show the calm information page, change nothing
    $ids = Get-GoalIds $Key
    $opt = @(Get-GoalCandidates $Key | Where-Object { $_ -notin $ids })
    Write-SR "Goal '$($g.Title)' opened: $(@($ids).Count) Safe item(s) and $($opt.Count) optional extra(s) listed (nothing ticked, nothing applied)" 'INFO'
    $c['LogText'].Text = "Look through the list, then press Add to review list. Nothing changes until you press Apply."
    $rec = $false
    Show-GoalPage -Key $Key -Title $g.Title -Intro $g.Intro -Ids $ids -Links $g.Links -Recommended $rec -Optional $opt
}

# ---- Quick presets -------------------------------------------------------------------------------------------
$script:SrPresets = @(
    @{ Key='gaming';      Title='Gaming';      Promise='A gaming settings list. Review power use and other trade-offs.';           Tags=@() }
    @{ Key='streaming';   Title='Streaming';   Promise='Keeps your game and your stream in balance.';      Tags=@() }
)

function Get-PresetIds {
    param([string]$Key)
    $ids = @()
    switch ($Key) {
        'gaming'      { $ids = @(Get-SafeGamingTweakSet) }
        'streaming'   { $ids = @(Get-SafeGamingTweakSet) + @('ChkObsPriority','ChkSoundDucking') }
    }
    $tbl = $script:GpuVendorSafeTweaks
    if ($script:GpuVendor -eq 'nvidia') { $ids += @($tbl.Nvidia) } elseif ($script:GpuVendor -eq 'amd') { $ids += @($tbl.Amd) }
    $out = [System.Collections.Generic.List[string]]::new()
    foreach ($id in $ids) { if ($id -and $c[$id] -and -not $out.Contains($id)) { $out.Add($id) } }
    return @($out)
}

function Build-HomePresets {
    $c['HomePresets'].Children.Clear()
    foreach ($p in $script:SrPresets) {
        $ids = Get-PresetIds $p.Key
        $r = Get-RiskCounts $ids
        $btn = New-Object System.Windows.Controls.Button
        $btn.Style = $window.FindResource('BtnCard'); $btn.Tag = $p.Key; $btn.MinHeight = 120; $btn.VerticalContentAlignment = 'Top'
        $sp = New-Object System.Windows.Controls.StackPanel
        $sp.Children.Add((New-Text $p.Title 15 '#edecf3' 'SemiBold')) | Out-Null
        $sp.Children.Add((New-Text $p.Promise 12 '#c9c7d6')) | Out-Null
        $cnt = New-Text "$($r.S) Safe, $($r.C) Careful, $($r.A) Advanced" 11 '#8b8b9c'; $cnt.Margin = [System.Windows.Thickness]::new(0,6,0,0)
        $sp.Children.Add($cnt) | Out-Null
        $tags = @($p.Tags)
        if (@($ids | Where-Object { $_ -in $script:RebootIds }).Count -gt 0) { $tags += 'Restart needed' }
        if ($tags.Count -gt 0) { $tg = New-Text ($tags -join '  |  ') 11 '#f0b545'; $sp.Children.Add($tg) | Out-Null }
        $btn.Content = $sp
        $btn.Add_Click({ param($s, $e) Show-PresetPage ([string]$s.Tag) })
        $c['HomePresets'].Children.Add($btn) | Out-Null
    }
}

function Show-PresetPage {
    param([string]$Key)
    $p = $script:SrPresets | Where-Object { $_.Key -eq $Key } | Select-Object -First 1
    if (-not $p) { return }
    $script:PresetKey = $Key
    $ids = Get-PresetIds $Key
    $c['PresetTitle'].Text = "$($p.Title) preset"
    $laptop = Test-IsLaptop
    $c['PresetIntro'].Text = "$($p.Promise) This is a preview. Nothing is switched on in your review list until you press Add to review list."
    if ($script:SrSettings.safeMode) { $c['PresetIntro'].Text += ' Safe Mode is on, so only the Safe items are switched on. The rest are greyed and cannot be switched on.' }
    $c['PresetWarn'].Visibility = 'Collapsed'
    $c['PresetWarnText'].Text = ''
    $c['ChkPresetAck'].IsChecked = $false
    $groups = @()
    $s = @($ids | Where-Object { (Get-TweakRisk $_) -eq 'S' }); $cc = @($ids | Where-Object { (Get-TweakRisk $_) -eq 'C' }); $a = @($ids | Where-Object { (Get-TweakRisk $_) -eq 'A' })
    $safe = [bool]$script:SrSettings.safeMode
    if ($s.Count -gt 0)  { $groups += @{ Title = 'Safe items'; Sub = ''; Ids = $s; On = $true; Links = $false } }
    if ($cc.Count -gt 0) { $groups += @{ Title = 'Careful items'; Sub = $(if ($safe) { 'Safe Mode is on, so these stay off and cannot be switched on.' } else { 'Read each trade-off. Some changes need manual recovery.' }); Ids = $cc; On = $true; Links = $false } }
    if ($a.Count -gt 0)  { $groups += @{ Title = 'Advanced items (experts only)'; Sub = $(if ($safe) { 'Safe Mode is on, so these stay off and cannot be switched on.' } else { 'Bigger changes. Read each one before you keep it switched on.' }); Ids = $a; On = $true; Links = $false } }
    $script:ActiveState = Build-ChoiceList -Panel $c['PresetList'] -Groups $groups -Ctx "preset:$Key" -Button 'BtnListAdd' -ButtonFormat 'Add to review list ({0})'
    $c['BtnListAdd'].Visibility = 'Visible'
    Write-SR "Preset preview '$($p.Title)': $($ids.Count) item(s) listed (nothing ticked, nothing applied)" 'INFO'
    Show-SimplePage 'PagePreset'
    Update-ChoiceCount $script:ActiveState
}

function Confirm-PresetBox {
    param([string]$Text, [string]$Title)
    $r = $script:PresetMsg.Show($Text, $Title, [System.Windows.MessageBoxButton]::OKCancel, [System.Windows.MessageBoxImage]::Warning)
    return ($r -eq [System.Windows.MessageBoxResult]::OK)
}

# The page button: ticks what is switched on, then opens the review basket. Never applies.
function Invoke-ListAdd {
    $st = $script:ActiveState
    if (-not $st) { return }
    $ids = Get-ChoiceOn $st
    if ($script:SrPage -eq 'PagePreset') {
        $new = Add-ChosenIds $ids -AllowAdvanced
        Write-SR "Preset '$($script:PresetKey)': $($ids.Count) item(s) switched on, $new newly ticked in the review list (nothing applied)" 'INFO'
    } else {
        $new = Add-ChosenIds $ids -AllowAdvanced:($script:GoalKey -eq 'score')
        Write-SR "Goal '$($script:GoalKey)': $($ids.Count) item(s) switched on, $new newly ticked in the review list (nothing applied)" 'INFO'
    }
    Update-Count
    $c['LogText'].Text = "$new newly added, $($ids.Count - $new) already in your review list. Review list now: $(@(Get-SelectedNames).Count). Nothing changes until you press Apply."
    Show-SimplePage 'PageBasket'
}

# ---- review basket ----------------------------------------------------------------------------------------
function Update-BasketUi {
    param($N, $S, $C2, $A)
    if ($null -eq $N) {
        $sel = Get-SelectedNames; $r = Get-RiskCounts $sel
        $N = $sel.Count; $A = $r.A
    }
    $c['BtnOpenBasket'].Content   = if ($N -gt 0) { "Review and apply ($N)" } else { 'Review and apply' }
    $c['BtnOpenBasket'].IsEnabled = ($N -gt 0)
    $c['BasketAdvBox'].Visibility = if ($A -gt 0) { 'Visible' } else { 'Collapsed' }
    if ($A -eq 0 -and $c['ChkAdvAck'].IsChecked) { $c['ChkAdvAck'].IsChecked = $false }
    $c['BtnBasketApply'].IsEnabled = ($N -gt 0 -and ($A -eq 0 -or [bool]$c['ChkAdvAck'].IsChecked))
    Update-BottomBarState
}
function Refresh-BasketPage {
    $sel = Get-SelectedNames
    $r = Get-RiskCounts $sel
    $c['BasketItems'].Children.Clear()
    foreach ($id in $sel) {
        $card = New-Object System.Windows.Controls.Border
        $card.Background = (Br '#0d0d16'); $card.BorderBrush = (Br '#28242f'); $card.BorderThickness = [System.Windows.Thickness]::new(1)
        $card.CornerRadius = [System.Windows.CornerRadius]::new(8); $card.Padding = [System.Windows.Thickness]::new(14,9,10,9)
        $card.Margin = [System.Windows.Thickness]::new(0,0,0,6)
        $g = New-Object System.Windows.Controls.Grid
        foreach ($w in @('*','Auto','Auto')) {
            $cd = New-Object System.Windows.Controls.ColumnDefinition
            $cd.Width = if ($w -eq '*') { [System.Windows.GridLength]::new(1, [System.Windows.GridUnitType]::Star) } else { [System.Windows.GridLength]::Auto }
            $g.ColumnDefinitions.Add($cd)
        }
        $sp = New-Object System.Windows.Controls.StackPanel
        $sp.Children.Add((New-Text (Get-PlainName $id) 14 '#edecf3' 'SemiBold')) | Out-Null
        if ($script:TweakInfo.ContainsKey($id)) { $sp.Children.Add((New-Text $script:TweakInfo[$id].Desc 12 '#8b8b9c')) | Out-Null }
        [System.Windows.Controls.Grid]::SetColumn($sp, 0); $g.Children.Add($sp) | Out-Null
        $bd = New-RiskBadge (Get-TweakRisk $id); $bd.VerticalAlignment = 'Center'
        [System.Windows.Controls.Grid]::SetColumn($bd, 1); $g.Children.Add($bd) | Out-Null
        $rm = New-Object System.Windows.Controls.Button
        $rm.Style = $window.FindResource('BtnGray'); $rm.Content = 'Remove'; $rm.Height = 30; $rm.Tag = $id
        $rm.Add_Click({ param($s, $e) $c[[string]$s.Tag].IsChecked = $false; Refresh-BasketPage })
        [System.Windows.Controls.Grid]::SetColumn($rm, 2); $g.Children.Add($rm) | Out-Null
        $card.Child = $g
        $c['BasketItems'].Children.Add($card) | Out-Null
    }
    $c['BasketTotals'].Text = "$($sel.Count) selected: $($r.S) Safe, $($r.C) Careful, $($r.A) Advanced"
    $c['BasketEmpty'].Visibility = if ($sel.Count -eq 0) { 'Visible' } else { 'Collapsed' }
    Update-BasketUi $sel.Count $r.S $r.C $r.A
}

# ---- apply (original engine) + progress + results ---------------------------------------------------------
$script:SrApplying = $false
$script:LastBatchResult = $null
$script:SrHistory = [System.Collections.Generic.List[hashtable]]::new()
$script:CurrentEntry = $null
function Update-ApplyingPage {
    param($V, $M)
    try { $c['ApplyProgress'].Value = [double]$V; $c['ApplyStep'].Text = [string]$M } catch {}
    # the engine runs on the UI thread, so let WPF paint between steps
    try { $window.Dispatcher.Invoke([Action]{}, [System.Windows.Threading.DispatcherPriority]::Render) } catch {}
}
function Start-ApplyFromBasket {
    $sel = Get-SelectedNames
    if ($sel.Count -eq 0) { return }
    $r = Get-RiskCounts $sel
    if ($r.A -gt 0 -and -not $c['ChkAdvAck'].IsChecked) { return }
    if (-not (Confirm-UndoIrreversibleTweaks $sel)) { return }
    $script:SrApplying = $true
    $script:LastBatchResult = $null
    $script:LastRestorePointOk = $null
    $script:UndoSaveFailed = $false
    Show-SimplePage 'PageApplying'
    Update-ApplyingPage 0 'Starting...'
    try {
        $c['BtnApplyAll'].RaiseEvent([System.Windows.RoutedEventArgs]::new([System.Windows.Controls.Button]::ClickEvent))
    } catch { Write-SR "Apply failed: $($_.Exception.Message)" 'FAIL' }
    finally { $script:SrApplying = $false }
    Complete-Batch $script:LastBatchResult $sel $false
}
function Complete-Batch {
    param($Res, [string[]]$Selected, [bool]$Fake)
    $script:HomeLastLoad = [datetime]::MinValue
    $done = @(); $failed = @(); $skipped = @()
    $batch = $null
    if ($Res) {
        $batch = $Res.Batch
        $done = @($Res.Batch.Keys)
        foreach ($n in @($Selected)) {
            if ($n -in $done) { continue }
            $lbl = if ($c[$n]) { [string]$c[$n].Content } else { $n }
            if ($lbl -in @($Res.Failed)) { $failed += $n } else { $skipped += $n }
        }
    } else { $skipped = @($Selected) }
    $entry = @{ Time = [datetime]::Now; Names = @($Selected); Done = $done; Failed = $failed; Skipped = $skipped; Batch = $batch; Undone = @{}; Fake = $Fake; Aborted = ((-not $Res) -and (-not $Fake)); RestoreOk = $script:LastRestorePointOk; Partial = $script:PartialNotes; SaveWarn = $script:UndoSaveFailed }
    if ($done.Count -gt 0 -or $failed.Count -gt 0 -or $entry.Aborted) { $script:SrHistory.Add($entry) }
    if (-not $Fake) { Load-ActiveBadges }
    Set-ScoreChange $entry $script:ScoreBeforeBatch (Get-SetupScore)
    $script:ScoreBeforeBatch = $null
    $script:CurrentEntry = $entry
    Show-SimplePage 'PageResult'
    Refresh-ResultPage
}
function Test-BatchOnStack { param($Batch)
    if (-not $Batch) { return $false }
    foreach ($b in $script:UndoStack.ToArray()) { if ([object]::ReferenceEquals($b, $Batch)) { return $true } }
    return $false
}
function Get-EntryActive { param($E)
    return ($E.Batch -and $E.Batch.Count -gt 0 -and (Test-BatchOnStack $E.Batch))
}
function Update-UndoButton {
    # mirrors the original engine's button text so the bottom bar stays correct after a per-item undo
    $items = @($script:UndoStack.ToArray() | Where-Object { $_.Count -gt 0 })
    if ($items.Count -ne $script:UndoStack.Count) {
        $script:UndoStack.Clear()
        for ($i = $items.Count - 1; $i -ge 0; $i--) { $script:UndoStack.Push($items[$i]) }
    }
    if ($script:UndoStack.Count -eq 0) { $c['BtnUndoLast'].IsEnabled = $false; $c['BtnUndoLast'].Content = 'Undo Last Batch' }
    else {
        $n = ($script:UndoStack.Peek()).Count
        $c['BtnUndoLast'].IsEnabled = $true
        $c['BtnUndoLast'].Content = "Undo Last Batch ($n change$(if($n -ne 1){'s'}))"
    }
}
# Per-item undo: runs the saved undo record of that one setting (the same record the batch Undo uses).
$script:LastUndoFailed = @()
function Undo-BatchItem {
    param($Entry, [string]$Name)
    $script:HomeLastLoad = [datetime]::MinValue
    if (-not $Entry.Batch -or -not $Entry.Batch.Contains($Name)) { return }
    try {
        Write-SR "Reversing: $(Get-PlainName $Name)" 'UNDO'
        & $Entry.Batch[$Name]
    } catch {
        Write-SR "Undo failed for $(Get-PlainName $Name): $_" 'FAIL'
        Fail $(if ($Name -eq 'ChkGpuNvNpiProfile') { "$(Get-PlainName $Name) needs manual recovery. Follow the steps written in the log. It stays in the list." } else { "Could not undo $(Get-PlainName $Name). It stays in the list so you can try again." })
        return
    }
    $Entry.Batch.Remove($Name)
    $Entry.Undone[$Name] = $true
    if (-not $Entry.Fake) { $scoreBeforeUndo = Get-SetupScore; Load-ActiveBadges; Set-ScoreChange $Entry $scoreBeforeUndo (Get-SetupScore) }
    if (-not $Entry.Fake) { Remove-AppliedTweakState -Names @($Name) }
    Update-UndoButton
    Done "Undone: $(Get-PlainName $Name)."
}
function Undo-WholeBatch {
    param($Entry)
    $script:HomeLastLoad = [datetime]::MinValue
    if (-not (Get-EntryActive $Entry)) { return }
    $top = $script:UndoStack.Peek()
    if ([object]::ReferenceEquals($top, $Entry.Batch) -and -not $Entry.Fake) {
        $before = @($Entry.Batch.Keys)
        $c['BtnUndoLast'].RaiseEvent([System.Windows.RoutedEventArgs]::new([System.Windows.Controls.Button]::ClickEvent))
        foreach ($k in $before) { if ($k -notin @($script:LastUndoFailed)) { $Entry.Undone[$k] = $true } }
    } else {
        $revKeys = @($Entry.Batch.Keys); [array]::Reverse($revKeys)
        foreach ($k in $revKeys) { Undo-BatchItem $Entry $k }
    }
    Update-UndoButton
}
function Refresh-ResultPage {
    $e = $script:CurrentEntry
    if (-not $e) { return }
    $c['ResultScoreChange'].Text = if ($e.ContainsKey('ScoreBefore') -and $e.ScoreBefore -ne $e.ScoreAfter) { "Setup score: $($e.ScoreBefore) to $($e.ScoreAfter)" } else { '' }
    $c['ResultScoreChange'].Visibility = if ($c['ResultScoreChange'].Text) { 'Visible' } else { 'Collapsed' }

    $c['ResultItems'].Children.Clear()
    if ($e.Batch -and -not $e.Fake) { foreach ($k in @($e.Done)) { if (-not $e.Batch.Contains($k) -and -not $e.Undone.ContainsKey($k)) { $e.Undone[$k] = $true } } }
    $nDone = $e.Done.Count; $nSkip = $e.Skipped.Count; $nFail = $e.Failed.Count
    $rpNote = if ($e.RestoreOk -eq $true) { ' A restore point was made first.' } elseif ($e.RestoreOk -eq $false) { ' No restore point could be made first. Undo still puts back the saved originals.' } else { '' }
    $abNote = $(if ($e.Aborted) { ' The run stopped early, so nothing below is confirmed. See the log.' } else { '' }) + $(if ($e.SaveWarn) { ' Some originals could not be saved to disk, so Undo works only until you close the app.' } else { '' })
    $c['ResultSummary'].Text = "$nDone done, $nSkip not applied, $nFail could not be applied.$rpNote$abNote"
    $c['BtnResultHome'].Content = if ($script:SrMode -eq 'pro') { 'Back to Pro' } else { 'Back to Home' }
    foreach ($id in $e.Names) {
        $state = if ($e.Undone.ContainsKey($id)) { 'Undone' } elseif ($id -in $e.Done) { 'Done' } elseif ($id -in $e.Failed) { 'Failed' } else { 'Skipped' }
        if ($state -eq 'Undone' -and $script:ManualPending.ContainsKey($id)) { $state = 'Manual' }
        $col = switch ($state) { 'Done' { '#56dd92' } 'Undone' { '#a78bff' } default { '#f0b545' } }
        $card = New-Object System.Windows.Controls.Border
        $card.Background = (Br '#0d0d16'); $card.BorderBrush = (Br '#28242f'); $card.BorderThickness = [System.Windows.Thickness]::new(1)
        $card.CornerRadius = [System.Windows.CornerRadius]::new(8); $card.Padding = [System.Windows.Thickness]::new(14,9,10,9)
        $card.Margin = [System.Windows.Thickness]::new(0,0,0,6)
        $g = New-Object System.Windows.Controls.Grid
        foreach ($w in @('*','Auto','Auto')) {
            $cd = New-Object System.Windows.Controls.ColumnDefinition
            $cd.Width = if ($w -eq '*') { [System.Windows.GridLength]::new(1, [System.Windows.GridUnitType]::Star) } else { [System.Windows.GridLength]::Auto }
            $g.ColumnDefinitions.Add($cd)
        }
        $sp = New-Object System.Windows.Controls.StackPanel
        $sp.Children.Add((New-Text (Get-PlainName $id) 14 '#edecf3' 'SemiBold')) | Out-Null
        $note = switch ($state) {
            'Done'    { if ($id -eq 'ChkGpuNvNpiProfile') { 'Temporarily unavailable: undo for this tweak has not been verified on real NVIDIA hardware yet.' } elseif (Undo-Engine-HasSpec $id) { 'Applied. Your original state is saved, and Undo puts it back.' } else { 'Applied. Undo goes back to the Windows default, not always your exact earlier value.' } }
            'Undone'  { if (Undo-Engine-HasSpec $id) { 'Put back to the original state.' } else { 'Undo ran (Windows default or manual recovery).' } }
            'Manual'  { 'Undo only showed the steps. Follow them in the log to put it back yourself.' }
            'Failed'  { Get-PartialRowNote $e $id }
            default   { if ($e.Aborted) { 'Not applied: the run stopped early. See the log.' } else { 'Not applied: it does not fit this PC or something was missing. See the log.' } }
        }
        $sp.Children.Add((New-Text $note 12 '#8b8b9c')) | Out-Null
        [System.Windows.Controls.Grid]::SetColumn($sp, 0); $g.Children.Add($sp) | Out-Null
        $chip = New-Text $(switch ($state) { 'Failed' { 'Could not apply' } 'Manual' { 'Manual steps needed' } default { $state } }) 13 $col 'SemiBold'
        $chip.VerticalAlignment = 'Center'; $chip.Margin = [System.Windows.Thickness]::new(10,0,12,0)
        [System.Windows.Controls.Grid]::SetColumn($chip, 1); $g.Children.Add($chip) | Out-Null
        if ($state -eq 'Done' -and (Get-EntryActive $e)) {
            $u = New-Object System.Windows.Controls.Button
            $u.Style = $window.FindResource('BtnGray'); $u.Content = 'Undo'; $u.Height = 30; $u.Tag = $id
            $u.Add_Click({ param($s, $ev) Undo-BatchItem $script:CurrentEntry ([string]$s.Tag); Refresh-ResultPage })
            [System.Windows.Controls.Grid]::SetColumn($u, 2); $g.Children.Add($u) | Out-Null
        }
        $card.Child = $g
        $c['ResultItems'].Children.Add($card) | Out-Null
    }
    $needReboot = @($e.Done | Where-Object { $_ -in $script:RebootIds -and -not $e.Undone.ContainsKey($_) })
    $c['RebootBanner'].Visibility = if ($needReboot.Count -gt 0) { 'Visible' } else { 'Collapsed' }
    if ($needReboot.Count -gt 0) { $c['RebootText'].Text = "Needs a restart: $((@($needReboot | ForEach-Object { Get-PlainName $_ }) -join ', ')). Save your work first." }
    $c['ResultNote'].Text = 'Recovery varies by item: saved originals, session recovery, defaults or manual steps. Read the item note.'
    $c['BtnResultUndoAll'].IsEnabled = (Get-EntryActive $e)
}

# ---- history ----------------------------------------------------------------------------------------------
function Refresh-HistoryPage {
    Update-UndoButton
    try { Sync-ToolBatches } catch {}
    $c['HistoryItems'].Children.Clear()
    $c['BtnHistoryUndoLast'].IsEnabled = $c['BtnUndoLast'].IsEnabled
    Add-UndoPendingCard
    $entries = @($script:SrHistory)
    [array]::Reverse($entries)
    foreach ($e in $entries) {
        $card = New-Object System.Windows.Controls.Border
        $card.Background = (Br '#0d0d16'); $card.BorderBrush = (Br '#28242f'); $card.BorderThickness = [System.Windows.Thickness]::new(1)
        $card.CornerRadius = [System.Windows.CornerRadius]::new(10); $card.Padding = [System.Windows.Thickness]::new(16,12,16,10)
        $card.Margin = [System.Windows.Thickness]::new(0,0,0,10)
        $sp = New-Object System.Windows.Controls.StackPanel
        $active = Get-EntryActive $e
        $head = New-Object System.Windows.Controls.DockPanel
        $head.LastChildFill = $false
        if ($active) {
            $ub = New-Object System.Windows.Controls.Button
            $ub.Style = $window.FindResource('BtnGray'); $ub.Content = 'Undo this batch'; $ub.Height = 32; $ub.Tag = [string]$script:SrHistory.IndexOf($e)
            $ub.Add_Click({ param($s, $ev) Undo-WholeBatch $script:SrHistory[[int]$s.Tag]; Refresh-HistoryPage })
            [System.Windows.Controls.DockPanel]::SetDock($ub, 'Right'); $head.Children.Add($ub) | Out-Null
        }
        $nTot = $e.Done.Count + $e.Undone.Count
        $t = New-Text ("{0}  -  {1} change{2}" -f $e.Time.ToString('HH:mm'), $e.Names.Count, $(if ($e.Names.Count -ne 1) { 's' } else { '' })) 14 '#edecf3' 'SemiBold'
        [System.Windows.Controls.DockPanel]::SetDock($t, 'Left'); $head.Children.Add($t) | Out-Null
        $sp.Children.Add($head) | Out-Null
        $sub = if ($active) { 'Still active. You can undo single items or the whole batch.' } else { Get-HistorySubtitle $e }
        $sp.Children.Add((New-Text $sub 12 '#8b8b9c')) | Out-Null
        foreach ($id in $e.Names) {
            $state = if ($e.Undone.ContainsKey($id) -or ($id -in $e.Done -and -not $active)) { 'Undone' } elseif ($id -in $e.Done) { 'Done' } elseif ($id -in $e.Failed) { 'Failed' } else { 'Skipped' }
            if ($state -eq 'Undone' -and $script:ManualPending.ContainsKey($id)) { $state = 'Manual' }
            $row = New-Object System.Windows.Controls.DockPanel
            $row.LastChildFill = $false; $row.Margin = [System.Windows.Thickness]::new(0,6,0,0)
            if ($state -eq 'Done') {
                $u = New-Object System.Windows.Controls.Button
                $u.Style = $window.FindResource('BtnGray'); $u.Content = 'Undo'; $u.Height = 28; $u.Padding = [System.Windows.Thickness]::new(12,0,12,0); $u.Tag = "$($script:SrHistory.IndexOf($e))|$id"
                $u.Add_Click({ param($s, $ev) $p = ([string]$s.Tag).Split('|'); Undo-BatchItem $script:SrHistory[[int]$p[0]] $p[1]; Refresh-HistoryPage })
                [System.Windows.Controls.DockPanel]::SetDock($u, 'Right'); $row.Children.Add($u) | Out-Null
            }
            $col = switch ($state) { 'Done' { '#56dd92' } 'Undone' { '#a78bff' } default { '#f0b545' } }
            $st = New-Text $(switch ($state) { 'Failed' { 'Could not apply' } 'Manual' { 'Manual steps needed' } default { $state } }) 12 $col 'SemiBold'; $st.Width = 130; $st.VerticalAlignment = 'Center'
            [System.Windows.Controls.DockPanel]::SetDock($st, 'Right'); $row.Children.Add($st) | Out-Null
            $nm = New-Text (Get-PlainName $id) 13 '#c9c7d6'; $nm.VerticalAlignment = 'Center'
            [System.Windows.Controls.DockPanel]::SetDock($nm, 'Left'); $row.Children.Add($nm) | Out-Null
            $sp.Children.Add($row) | Out-Null
        }
        $card.Child = $sp
        $c['HistoryItems'].Children.Add($card) | Out-Null
    }
    $c['HistoryEmpty'].Visibility = if ($entries.Count -eq 0 -and $c['HistoryItems'].Children.Count -eq 0) { 'Visible' } else { 'Collapsed' }
    # Only settings this edition really holds a saved original for are listed (read from its own engine store, never from shared metadata).
    $keptNames = @()
    try {
        if (-not $script:UndoEngineReady) { Initialize-UndoEngine }
        $sess = @($script:SrHistory | ForEach-Object { $_.Done } | ForEach-Object { $_ })
        $keptNames = @(@(Undo-Engine-List | Where-Object { $_['kind'] -eq 'tweak' -and $_['status'] -ne 'restored' -and [string]$_['tweakId'] -notin $sess } | ForEach-Object { [string]$_['tweakId'] } | Select-Object -Unique) | ForEach-Object { Get-PlainName ([string]$_) })
    } catch {}
    $c['HistoryKept'].Text = if ($keptNames.Count -gt 0) { "Saved originals from earlier sessions: $($keptNames -join ', '). Use the Saved originals card above to put them back. A setting without a saved original is not listed here." } else { '' }
    if ($script:ToolEvents.Count -gt 0) {
        $card = New-Object System.Windows.Controls.Border
        $card.Background = (Br '#0d0d16'); $card.BorderBrush = (Br '#28242f'); $card.BorderThickness = [System.Windows.Thickness]::new(1)
        $card.CornerRadius = [System.Windows.CornerRadius]::new(10); $card.Padding = [System.Windows.Thickness]::new(16,12,16,10)
        $card.Margin = [System.Windows.Thickness]::new(0,0,0,10)
        $sp = New-Object System.Windows.Controls.StackPanel
        $sp.Children.Add((New-Text 'Tool actions and other messages (this session)' 14 '#edecf3' 'SemiBold')) | Out-Null
        $sp.Children.Add((New-Text 'Actions you ran directly from a Pro page, repairs, and messages from failed attempts. Use the Undo button at the bottom for tools that can be undone.' 12 '#8b8b9c')) | Out-Null
        $evs = @($script:ToolEvents); [array]::Reverse($evs)
        foreach ($ev in @($evs | Select-Object -First 25)) {
            $row = New-Object System.Windows.Controls.DockPanel; $row.LastChildFill = $false; $row.Margin = [System.Windows.Thickness]::new(0,6,0,0)
            $st = New-Text $(if ($ev.Ok) { 'Done' } else { 'Not done' }) 12 $(if ($ev.Ok) { '#56dd92' } else { '#f0b545' }) 'SemiBold'; $st.Width = 70; $st.VerticalAlignment = 'Top'
            [System.Windows.Controls.DockPanel]::SetDock($st, 'Right'); $row.Children.Add($st) | Out-Null
            $nt = New-Text "$($ev.Time.ToString('HH:mm'))  $($ev.Message)" 13 '#c9c7d6'; [System.Windows.Controls.DockPanel]::SetDock($nt, 'Left'); $row.Children.Add($nt) | Out-Null
            $sp.Children.Add($row) | Out-Null
        }
        $card.Child = $sp
        $c['HistoryItems'].Children.Add($card) | Out-Null
    }
}

# ---- My PC (read-only; copies what the dashboard and health report already collected) ----------------------
function Add-InfoRow {
    param($Panel, [string]$Text, $Brush = $null)
    $t = New-Text $Text 13 '#c9c7d6'
    if ($Brush) { $t.Foreground = $Brush }
    $t.Margin = [System.Windows.Thickness]::new(0,3,0,3)
    $Panel.Children.Add($t) | Out-Null
}
function Add-InfoCard {
    param([string]$Title, $Rows)
    $card = New-Object System.Windows.Controls.Border
    $card.Background = (Br '#0d0d16'); $card.BorderBrush = (Br '#28242f'); $card.BorderThickness = [System.Windows.Thickness]::new(1)
    $card.CornerRadius = [System.Windows.CornerRadius]::new(10); $card.Padding = [System.Windows.Thickness]::new(16,12,16,12)
    $card.Margin = [System.Windows.Thickness]::new(0,0,0,10)
    $sp = New-Object System.Windows.Controls.StackPanel
    $sp.Children.Add((New-Text $Title 15 '#edecf3' 'SemiBold')) | Out-Null
    foreach ($r in $Rows) { Add-InfoRow $sp $r.Text $r.Brush }
    $card.Child = $sp
    $c['MyPcItems'].Children.Add($card) | Out-Null
}
function Refresh-MyPcPage {
    Ensure-SystemDetails
    if (([datetime]::Now - $script:HomeLastLoad).TotalSeconds -gt 60 -and (Get-Command Load-Dashboard -ErrorAction SilentlyContinue)) {
        Load-Dashboard; $script:HomeLastLoad = [datetime]::Now
    }
    Stop-HomeSync
    $c['MyPcItems'].Children.Clear()
    $sys = @(); foreach ($n in @('TxtCpu','TxtGpu','TxtRam','TxtOs','TxtPowerPlan','TxtUptime')) { $sys += @{ Text = (ConvertTo-PlainUi $c[$n].Text); Brush = $null } }
    Add-InfoCard 'Your PC' $sys
    $health = @()
    foreach ($n in @('LblHealthRam','LblHealthDisplay','LblHealthNetwork','LblHealthStorage','LblHealthRebar','LblHealthCpu','LblHealthPagefile','LblHealthGpuTemp','LblHealthDrivers')) {
        $health += @{ Text = (ConvertTo-PlainUi $c[$n].Text); Brush = $c[$n].Foreground }
    }
    Add-InfoCard 'Health report' $health
    $act = @(@{ Text = (ConvertTo-PlainUi $c['LblActiveOptHeader'].Text); Brush = $null })
    foreach ($row in $c['PanelActiveBadges'].Children) { try { $act += @{ Text = ('On: ' + $row.Children[0].Text); Brush = (Br '#56dd92') } } catch {} }
    Add-InfoCard 'Active settings' $act
    $misc = @(@{ Text = $(if ($c['BannerTimerActive'].Visibility -eq 'Visible') { 'Timer resolution: 0.5 ms (active)' } else { 'Timer resolution: 15.6 ms (Windows default)' }); Brush = $null })
    if ($c['BannerDriftDetected'].Visibility -eq 'Visible') { $misc += @{ Text = ((ConvertTo-PlainUi $c['LblDriftTitle'].Text) + ': ' + (ConvertTo-PlainUi $c['LblDriftDetail'].Text)); Brush = (Br '#f0b545') } }
    Add-InfoCard 'Also' $misc
}

# ---- settings page ------------------------------------------------------------------------------------------
$script:SrLoadingSettings = $false
function Set-LargeText {
    param([bool]$On)
    try {
        if ($On) { $c['RootGrid'].LayoutTransform = [System.Windows.Media.ScaleTransform]::new(1.15, 1.15) }
        else { $c['RootGrid'].LayoutTransform = [System.Windows.Media.Transform]::Identity }
    } catch {}
}
function Refresh-SettingsPage {
    $script:SrLoadingSettings = $true
    try {
        $c['ChkSetLarge'].IsChecked  = [bool]$script:SrSettings.largeText
        $c['ChkSetSafe'].IsChecked   = [bool]$script:SrSettings.safeMode
    } finally { $script:SrLoadingSettings = $false }
}
$c['ChkSetLarge'].Add_Click({ if ($script:SrLoadingSettings) { return }; $script:SrSettings.largeText = [bool]$c['ChkSetLarge'].IsChecked; Set-LargeText $script:SrSettings.largeText; Save-SrSettings })
$c['ChkSetSafe'].Add_Click({
    if ($script:SrLoadingSettings) { return }
    $script:SrSettings.safeMode = [bool]$c['ChkSetSafe'].IsChecked
    if ($script:SrSettings.safeMode) {
        $script:SafeGuard = $true
        try { foreach ($n in $tweakBoxes) { if ($c[$n] -and $c[$n].IsChecked -and (Get-TweakRisk $n) -ne 'S') { $c[$n].IsChecked = $false } } } finally { $script:SafeGuard = $false }
        Update-Count
        $c['SettingsNote'].Text = 'Safe Mode is on. Careful and Advanced settings were switched off and are locked.'
    } else { $c['SettingsNote'].Text = 'Safe Mode is off.' }
    Save-SrSettings
})

# ---- Pro tweak table ----------------------------------------------------------------------------------------
$script:TblRisk = 'All'; $script:TblArea = 'All'; $script:TblMine = $false
$script:TableRowMap = @{}
$script:TableBuilt = $false
$script:StatusIds = @($script:BadgeTests | Where-Object { $_.CheckboxName } | ForEach-Object { $_.CheckboxName })
function Get-TweakStatus { param([string]$Id)
    if ($Id -notin $script:StatusIds) { return 'Unknown' }
    if (Test-TweakAlreadyOn $Id) { return 'On' } else { return 'Off' }
}
function Build-TableRows {
    $c['TableRows'].Children.Clear()
    $script:TableRowMap = @{}
    $ids = @($script:TweakInfo.Keys | Where-Object { $c[$_] } | Sort-Object @{ Expression = { 'GUPWD'.IndexOf($script:TweakInfo[$_].Area) } }, @{ Expression = { $script:TweakInfo[$_].Name } })
    foreach ($id in $ids) {
        $info = $script:TweakInfo[$id]
        $g = New-Object System.Windows.Controls.Grid
        $g.Margin = [System.Windows.Thickness]::new(0)
        foreach ($w in @(60, '*', 92, 70, 150)) {
            $cd = New-Object System.Windows.Controls.ColumnDefinition
            $cd.Width = if ($w -eq '*') { [System.Windows.GridLength]::new(1, [System.Windows.GridUnitType]::Star) } else { [System.Windows.GridLength]::new([double]$w) }
            $g.ColumnDefinitions.Add($cd)
        }
        $mirror = New-Object System.Windows.Controls.CheckBox
        $mirror.Style = $window.FindResource('Chk'); $mirror.VerticalAlignment = 'Center'; $mirror.Margin = [System.Windows.Thickness]::new(14,0,0,0)
        $bind = New-Object System.Windows.Data.Binding 'IsChecked'
        $bind.Source = $c[$id]; $bind.Mode = [System.Windows.Data.BindingMode]::TwoWay
        [void]$mirror.SetBinding([System.Windows.Controls.Primitives.ToggleButton]::IsCheckedProperty, $bind)
        [System.Windows.Controls.Grid]::SetColumn($mirror, 0); $g.Children.Add($mirror) | Out-Null
        $sp = New-Object System.Windows.Controls.StackPanel
        $sp.Margin = [System.Windows.Thickness]::new(0,6,8,6)
        $sp.Children.Add((New-Text $info.Name 13 '#edecf3' 'SemiBold')) | Out-Null
        $sp.Children.Add((New-Text $info.Tech 11 '#5f5f70')) | Out-Null
        [System.Windows.Controls.Grid]::SetColumn($sp, 1); $g.Children.Add($sp) | Out-Null
        $bd = New-RiskBadge $info.Risk; $bd.VerticalAlignment = 'Center'
        [System.Windows.Controls.Grid]::SetColumn($bd, 2); $g.Children.Add($bd) | Out-Null
        $st = New-Text 'Unknown' 12 '#8b8b9c'; $st.VerticalAlignment = 'Center'
        [System.Windows.Controls.Grid]::SetColumn($st, 3); $g.Children.Add($st) | Out-Null
        $ar = New-Text $script:AreaNames[$info.Area] 12 '#8b8b9c'; $ar.VerticalAlignment = 'Center'
        [System.Windows.Controls.Grid]::SetColumn($ar, 4); $g.Children.Add($ar) | Out-Null
        $line = New-Object System.Windows.Controls.Border
        $line.BorderBrush = (Br '#1c1a28'); $line.BorderThickness = [System.Windows.Thickness]::new(0,0,0,1)
        $line.ToolTip = $info.Desc
        $line.Child = $g
        $c['TableRows'].Children.Add($line) | Out-Null
        $script:TableRowMap[$id] = @{ Row = $line; Switch = $mirror; Status = $st; Hay = ("$($info.Name) $($info.Desc) $($info.Tech) $id").ToLowerInvariant() }
    }
    $script:TableBuilt = $true
}
function Update-TableStatus {
    foreach ($id in $script:TableRowMap.Keys) {
        $s = Get-TweakStatus $id
        $t = $script:TableRowMap[$id].Status
        $t.Text = $s
        $t.Foreground = (Br $(switch ($s) { 'On' { '#56dd92' } 'Off' { '#c9c7d6' } default { '#8b8b9c' } }))
    }
}
function Set-TableFilterButtons {
    foreach ($b in $c['TableFilters'].Children) {
        $on = $false
        switch -Regex ([string]$b.Tag) {
            '^risk:(.+)$' { $on = ($Matches[1] -eq $script:TblRisk) }
            '^area:(.+)$' { $on = ($Matches[1] -eq $script:TblArea) }
            '^mine$'      { $on = $script:TblMine }
        }
        if ($on) { $b.Background = (Br '#1A7C5CFF'); $b.Foreground = (Br '#a78bff') } else { $b.Background = (Br '#12121d'); $b.Foreground = (Br '#8b8b9c') }
    }
}
function Build-TableFilterButtons {
    $c['TableFilters'].Children.Clear()
    $defs = @(@('risk:All','All risks'), @('risk:S','Safe'), @('risk:C','Careful'), @('risk:A','Advanced'),
              @('area:All','All areas'), @('area:G','Gaming'), @('area:U','Graphics'), @('area:P','Privacy'), @('area:W','Windows'), @('area:D','Updates'),
              @('mine','Only for my PC'))
    foreach ($d in $defs) {
        $b = New-Object System.Windows.Controls.Button
        $b.Style = $window.FindResource('BtnSmall'); $b.Content = $d[1]; $b.Tag = $d[0]; $b.Height = 30; $b.Padding = [System.Windows.Thickness]::new(12,0,12,0)
        $b.Margin = [System.Windows.Thickness]::new(0,0,6,6); $b.FontSize = 12
        $b.Add_Click({ param($s, $e)
            $t = [string]$s.Tag
            if ($t -match '^risk:(.+)$') { $script:TblRisk = $Matches[1] }
            elseif ($t -match '^area:(.+)$') { $script:TblArea = $Matches[1] }
            elseif ($t -eq 'mine') { $script:TblMine = -not $script:TblMine }
            Apply-TableFilter
        })
        $c['TableFilters'].Children.Add($b) | Out-Null
    }
}
function Apply-TableFilter {
    $q = $c['TxtTableSearch'].Text.Trim().ToLowerInvariant()
    $shown = 0
    foreach ($id in $script:TableRowMap.Keys) {
        $m = $script:TableRowMap[$id]; $info = $script:TweakInfo[$id]
        $ok = $true
        if ($q -and -not $m.Hay.Contains($q)) { $ok = $false }
        if ($script:TblRisk -ne 'All' -and $info.Risk -ne $script:TblRisk) { $ok = $false }
        if ($script:TblArea -ne 'All' -and $info.Area -ne $script:TblArea) { $ok = $false }
        if ($script:TblMine -and -not (Test-ForMyPc $id)) { $ok = $false }
        $m.Row.Visibility = if ($ok) { 'Visible' } else { 'Collapsed' }
        if ($ok) { $shown++ }
        # Safe Mode locks Careful and Advanced switches
        $locked = ($script:SrSettings.safeMode -and $info.Risk -ne 'S')
        $m.Switch.IsEnabled = -not $locked
        $m.Row.Opacity = if ($locked) { 0.5 } else { 1 }
    }
    $c['TableCount'].Text = "Showing $shown of $($script:TableRowMap.Count)" + $(if ($script:SrSettings.safeMode) { '. Safe Mode locks Careful and Advanced.' } else { '' })
    Set-TableFilterButtons
}
function Refresh-TablePage {
    if (-not $script:TableBuilt) { Build-TableFilterButtons; Build-TableRows }
    Update-TableStatus
    Apply-TableFilter
}

# ---- command palette (Ctrl+K) ---------------------------------------------------------------------------------
$script:PalShown = @()
function Show-Palette {
    $script:PalAll = $null
    $c['PaletteHost'].Visibility = 'Visible'
    $c['TxtPalette'].Text = ''
    Update-Palette ''
    [void]$c['TxtPalette'].Focus()
}
function Hide-Palette { $c['PaletteHost'].Visibility = 'Collapsed' }
function Invoke-PaletteSelection {
    $i = $c['LstPalette'].SelectedIndex
    if ($i -lt 0 -or $i -ge $script:PalShown.Count) { return }
    $a = $script:PalShown[$i].Action
    Hide-Palette
    & $a
}
$c['TxtPalette'].Add_TextChanged({ Update-Palette $c['TxtPalette'].Text })
$c['TxtPalette'].Add_PreviewKeyDown({
    param($s, $e)
    switch ($e.Key) {
        'Escape' { Hide-Palette; $e.Handled = $true }
        'Return' { Invoke-PaletteSelection; $e.Handled = $true }
        'Down'   { if ($c['LstPalette'].SelectedIndex -lt $c['LstPalette'].Items.Count - 1) { $c['LstPalette'].SelectedIndex++ }; $e.Handled = $true }
        'Up'     { if ($c['LstPalette'].SelectedIndex -gt 0) { $c['LstPalette'].SelectedIndex-- }; $e.Handled = $true }
    }
})
$c['LstPalette'].Add_MouseDoubleClick({ Invoke-PaletteSelection })
$c['PaletteHost'].Add_MouseLeftButtonDown({ param($s, $e) if ($e.OriginalSource -eq $c['PaletteHost']) { Hide-Palette } })
# Ctrl+K opens the palette (replaces the stage 1 "focus search" shortcut)
$window.Add_PreviewKeyDown({
    param($s, $e)
    if ($e.Key -eq [System.Windows.Input.Key]::K -and (([System.Windows.Input.Keyboard]::Modifiers -band [System.Windows.Input.ModifierKeys]::Control) -ne 0)) {
        Show-Palette; $e.Handled = $true
    }
})

# ---- dialogs: About, Jargon Buster, paid page ---------------------------------------------------------
$script:LastDialog = $null
function New-DialogWindow {
    param([string]$Title, [double]$Width, [double]$Height)
    $win = New-Object System.Windows.Window
    $win.Title = $Title; $win.Width = $Width; $win.Height = $Height
    $win.Background = (Br '#08080e'); $win.FontFamily = [System.Windows.Media.FontFamily]::new('Segoe UI')
    $win.WindowStartupLocation = 'CenterOwner'
    try { $win.Owner = $window } catch {}
    $win.ResizeMode = 'CanResize'
    return $win
}
function Show-PaidPage { Show-SimplePage 'PagePaid' }
function Show-AboutWindow {
    $w = New-DialogWindow 'About StreamReady' 520 520
    $root = New-Object System.Windows.Controls.StackPanel
    $head = New-Object System.Windows.Controls.StackPanel; $head.Orientation = 'Horizontal'
    $logo = New-Object System.Windows.Controls.Border
    $logo.Width = 40; $logo.Height = 40; $logo.CornerRadius = [System.Windows.CornerRadius]::new(9)
    $gb = New-Object System.Windows.Media.LinearGradientBrush; $gb.StartPoint = [System.Windows.Point]::new(0,0); $gb.EndPoint = [System.Windows.Point]::new(1,1)
    $gb.GradientStops.Add([System.Windows.Media.GradientStop]::new([System.Windows.Media.ColorConverter]::ConvertFromString('#a78bff'), 0))
    $gb.GradientStops.Add([System.Windows.Media.GradientStop]::new([System.Windows.Media.ColorConverter]::ConvertFromString('#6d4eea'), 1))
    $logo.Background = $gb
    $lt = New-Text 'S' 20 '#FFFFFF' 'Black'; $lt.HorizontalAlignment = 'Center'; $lt.VerticalAlignment = 'Center'; $logo.Child = $lt
    $head.Children.Add($logo) | Out-Null
    $ht = New-Object System.Windows.Controls.StackPanel; $ht.Margin = [System.Windows.Thickness]::new(14,0,0,0)
    $ht.Children.Add((New-Text 'StreamReady' 22 '#edecf3' 'Bold')) | Out-Null
    $ht.Children.Add((New-Text 'Open Source Edition v1.0.0' 13 '#8b8b9c')) | Out-Null
    $head.Children.Add($ht) | Out-Null
    $root.Children.Add($head) | Out-Null
    $p1 = New-Text 'MIT Licensed - free and open source.' 14 '#edecf3'; $p1.Margin = [System.Windows.Thickness]::new(0,18,0,10); $root.Children.Add($p1) | Out-Null
    $p2 = New-Text 'It changes Windows settings (registry values, services and Windows features). StreamReady tries to make a System Restore point before a batch of settings (it can fail). Each setting saves its original first, so Undo Last Batch or History can put it back, also after a restart. Tools that act immediately have their own recorded originals where possible. Some things cannot be put back automatically (deleted files, external repairs); the app says so first.' 13 '#c9c7d6'
    $p2.Margin = [System.Windows.Thickness]::new(0,0,0,10); $root.Children.Add($p2) | Out-Null
    $p3 = New-Text 'Simple view: pick a goal, review your list, apply. Pro view: every setting in its own area. Safe Mode locks everything except Safe settings, and History and Undo lists each batch with an Undo for each setting that has a saved original.' 13 '#c9c7d6'
    $p3.Margin = [System.Windows.Thickness]::new(0,0,0,10); $root.Children.Add($p3) | Out-Null
    $p4 = New-Object System.Windows.Controls.TextBox
    $p4.Text = 'https://github.com/StreamReadyDev/streamready-oss'; $p4.IsReadOnly = $true; $p4.Background = (Br '#12121d'); $p4.BorderBrush = (Br '#28242f'); $p4.Foreground = (Br '#a78bff'); $p4.FontSize = 13; $p4.Padding = [System.Windows.Thickness]::new(8,6,8,6)
    $root.Children.Add($p4) | Out-Null
    $row = New-Object System.Windows.Controls.StackPanel; $row.Orientation = 'Horizontal'; $row.Margin = [System.Windows.Thickness]::new(0,22,0,0)
    $ok = New-Object System.Windows.Controls.Button
    $ok.Style = $window.FindResource('BtnPrimary'); $ok.Content = 'Close'; $ok.Height = 38; $ok.Width = 110; $ok.Margin = [System.Windows.Thickness]::new(0,0,10,0)
    $ok.Add_Click({ $script:LastDialog.Close() })
    $row.Children.Add($ok) | Out-Null
    $pb = New-Object System.Windows.Controls.Button
    $pb.Style = $window.FindResource('BtnGray'); $pb.Content = 'What the paid version adds'; $pb.Height = 38; $pb.Margin = [System.Windows.Thickness]::new(0)
    $pb.Add_Click({ $script:LastDialog.Close(); Show-SimplePage 'PagePaid' })
    $row.Children.Add($pb) | Out-Null
    $root.Children.Add($row) | Out-Null
    $wrap = New-Object System.Windows.Controls.Border; $wrap.Padding = [System.Windows.Thickness]::new(28,24,28,20); $wrap.Background = (Br '#08080e'); $wrap.Child = $root
    $w.Content = $wrap
    $script:LastDialog = $w
    [void]$w.ShowDialog(); $script:LastDialog = $null
}
$script:Glossary = @(
    @('Restore point','A saved copy of your Windows settings. If something goes wrong, Windows can go back to it.'),
    @('Undo','Puts a setting back to the value it had before StreamReady changed it.'),
    @('Registry','The place where Windows keeps most of its settings. Most tweaks change a value here.'),
    @('Administrator','A Windows account level that is allowed to change system-wide settings.'),
    @('Latency','Delay. Lower latency means actions (a click, a key) show up sooner.'),
    @('Input lag','The delay between pressing a button and seeing the result on screen.'),
    @('Ping','How long a message takes to reach a server and come back. Lower is better for online games.'),
    @('FPS','Frames per second: how many pictures per second your game draws.'),
    @('Stutter','Short freezes or uneven movement in a game, even when FPS looks fine.'),
    @('CPU','The processor. It does most of the thinking in your PC.'),
    @('GPU','The graphics card or graphics chip. It draws the picture.'),
    @('RAM','Short-term memory. Games and apps keep what they are using right now in it.'),
    @('SSD / NVMe','Fast storage drives. Games load quicker from them than from an old hard drive.'),
    @('Driver','Software that lets Windows talk to a piece of hardware, such as your graphics card.'),
    @('Game Mode','A Windows feature that gives your game priority over background tasks.'),
    @('HAGS','Hardware-accelerated GPU scheduling: lets the graphics card manage its own memory work. Needs a restart.'),
    @('VRR','Variable refresh rate: the screen changes its speed to match the game, so motion looks smoother.'),
    @('Refresh rate (Hz)','How many times per second your screen updates.'),
    @('IRQ / interrupt','A signal from a device asking the CPU for attention.'),
    @('MMCSS','A Windows service that shares CPU time between media and game tasks.'),
    @('Timer resolution','How finely Windows keeps time. A finer timer can make some games feel more precise but uses more power.'),
    @('Telemetry','Usage and error data Windows sends to Microsoft.'),
    @('DNS','The phone book of the internet. It turns names like example.com into addresses.'),
    @('Delivery Optimization','A Windows feature that can share downloaded updates with other PCs.'),
    @('Fullscreen optimizations','A Windows feature that changes how fullscreen games are drawn.'),
    @('Power plan','A Windows profile that decides how much speed or battery saving you get.'),
    @('Safe / Careful / Advanced','Safe: normal setting, nothing usually goes wrong. Careful: a few PCs or apps may behave differently. Advanced: can affect stability or security.')
)
function Show-JargonBuster {
    $w = New-DialogWindow 'Jargon Buster' 640 560
    $g = New-Object System.Windows.Controls.Grid
    $r1 = New-Object System.Windows.Controls.RowDefinition; $r1.Height = [System.Windows.GridLength]::Auto
    $r2 = New-Object System.Windows.Controls.RowDefinition; $r2.Height = [System.Windows.GridLength]::new(1, [System.Windows.GridUnitType]::Star)
    $g.RowDefinitions.Add($r1); $g.RowDefinitions.Add($r2)
    $top = New-Object System.Windows.Controls.StackPanel
    $top.Children.Add((New-Text 'Jargon Buster' 22 '#edecf3' 'Bold')) | Out-Null
    $sub = New-Text 'Plain-English meanings. Type to search.' 13 '#8b8b9c'; $sub.Margin = [System.Windows.Thickness]::new(0,2,0,10); $top.Children.Add($sub) | Out-Null
    $tb = New-Object System.Windows.Controls.TextBox
    $tb.Background = (Br '#0d0d16'); $tb.Foreground = (Br '#edecf3'); $tb.CaretBrush = (Br '#edecf3'); $tb.BorderBrush = (Br '#28242f')
    $tb.FontSize = 14; $tb.Padding = [System.Windows.Thickness]::new(10,7,10,7); $tb.Margin = [System.Windows.Thickness]::new(0,0,0,10)
    $top.Children.Add($tb) | Out-Null
    [System.Windows.Controls.Grid]::SetRow($top, 0); $g.Children.Add($top) | Out-Null
    $sv = New-Object System.Windows.Controls.ScrollViewer; $sv.VerticalScrollBarVisibility = 'Auto'
    $list = New-Object System.Windows.Controls.StackPanel
    $sv.Content = $list
    [System.Windows.Controls.Grid]::SetRow($sv, 1); $g.Children.Add($sv) | Out-Null
    $fill = {
        param([string]$q)
        $list.Children.Clear()
        $q = $q.Trim().ToLowerInvariant()
        foreach ($t in $script:Glossary) {
            if ($q -and -not ($t[0].ToLowerInvariant().Contains($q) -or $t[1].ToLowerInvariant().Contains($q))) { continue }
            $card = New-Object System.Windows.Controls.Border
            $card.Background = (Br '#0d0d16'); $card.BorderBrush = (Br '#28242f'); $card.BorderThickness = [System.Windows.Thickness]::new(1)
            $card.CornerRadius = [System.Windows.CornerRadius]::new(8); $card.Padding = [System.Windows.Thickness]::new(14,9,14,9); $card.Margin = [System.Windows.Thickness]::new(0,0,0,6)
            $sp = New-Object System.Windows.Controls.StackPanel
            $sp.Children.Add((New-Text $t[0] 14 '#a78bff' 'SemiBold')) | Out-Null
            $sp.Children.Add((New-Text $t[1] 13 '#c9c7d6')) | Out-Null
            $card.Child = $sp
            $list.Children.Add($card) | Out-Null
        }
    }
    & $fill ''
    $tb.Add_TextChanged({ & $fill $tb.Text }.GetNewClosure())
    $wrap = New-Object System.Windows.Controls.Border; $wrap.Padding = [System.Windows.Thickness]::new(20,16,20,16); $wrap.Background = (Br '#08080e'); $wrap.Child = $g
    $w.Content = $wrap
    $script:LastDialog = $w
    [void]$w.ShowDialog(); $script:LastDialog = $null
}
