$c['BtnRestartNow'].Add_Click({
    $a = [System.Windows.MessageBox]::Show("Your PC will restart in 15 seconds.`n`nSave your work now. Click OK to restart, or Cancel to wait.", 'StreamReady - Restart now', 'OKCancel', 'Warning')
    if ($a -eq 'OK') { Write-SR 'Restart requested by the user' 'INFO'; Start-Process shutdown.exe -ArgumentList '/r','/t','15','/c','StreamReady: restart to finish applying changes' }
})
$c['BtnUndoLast'].Add_Click({
    # runs after the original handler: keep the result and history pages in step
    Update-UndoButton
    if ($script:SrPage -eq 'PageResult') { Refresh-ResultPage } elseif ($script:SrPage -eq 'PageHistory') { Refresh-HistoryPage }
})
$c['BtnHistoryUndoLast'].Add_Click({
    if ($c['BtnUndoLast'].IsEnabled) { $c['BtnUndoLast'].RaiseEvent([System.Windows.RoutedEventArgs]::new([System.Windows.Controls.Button]::ClickEvent)) }
    Refresh-HistoryPage
})
$c['BtnMyPcRefresh'].Add_Click({
    try { Load-SysInfo } catch {}
    try { $c['BtnRefreshHealth'].RaiseEvent([System.Windows.RoutedEventArgs]::new([System.Windows.Controls.Button]::ClickEvent)) } catch {}
    $script:HomeLastLoad = [datetime]::MinValue
    Refresh-MyPcPage
})
$c['BtnSetJargon'].Add_Click({ Show-JargonBuster })
$c['BtnSetPaid'].Add_Click({ Show-SimplePage 'PagePaid' })
$c['BtnSetWelcome'].Add_Click({ Show-SimplePage 'PageWelcome' })
$c['BtnHelpWelcome'].Add_Click({ Show-SimplePage 'PageWelcome' })
$c['BtnHelpPaid'].Add_Click({ Show-SimplePage 'PagePaid' })
$c['BtnPaidBack'].Add_Click({ Show-Back })
$c['BtnSetAbout'].Add_Click({ Show-AboutWindow })
$c['BtnHelpJargon'].Add_Click({ Show-JargonBuster })
$c['BtnHelpBack'].Add_Click({ Show-Back })
$c['BtnSearchClose'].Add_Click({ $c['TxtSearch'].Text = ''; Show-Back })
$c['TxtTableSearch'].Add_TextChanged({
    $c['TxtTableHint'].Visibility = if ($c['TxtTableSearch'].Text.Length -gt 0) { 'Collapsed' } else { 'Visible' }
    if ($script:TableBuilt) { Apply-TableFilter }
})
$c['ChkAdvAck'].Add_Unchecked({ Update-BasketUi })

# The preset buttons tick their lists directly; the Safe Mode guard on every checkbox already blocks Careful and
# Advanced ticks, and these handlers (run after the original ones) tell the user why the list is shorter.
foreach ($pb in @('BtnPresetGaming','BtnPresetStreaming')) {
    if ($c[$pb]) { $c[$pb].Add_Click({ if ($script:SrSettings.safeMode) { $c['LogText'].Text = 'Safe Mode is on, so only the Safe settings of this preset were selected.' } }) }
}

