function Initialize-Stage2 {
    $s = $script:SrSettings
    if ($s.largeText) { Set-LargeText $true }
    $c['NavPcText'].Text = "$(if (Test-IsLaptop) { 'Laptop' } else { 'Desktop' })"
    Set-NavActive 'BtnNavHome'
}

#region v7 Round 2: Pro areas (one left navigation, no separate old-style panels)
# The original v6 cards (every button, list, status label and setting) are moved, not rewritten, into these area pages.
# Each tweak checkbox is swapped for a switch row bound to the real checkbox, and each button gets an action card with
# a plain title, one line of help, a tag and the original name. Every handler keeps working because the controls are the same objects.

$script:ProAreas = @(
    @{ Key='everything'; Title='Everything';             Intro='Search, filter and review every setting in one list.' }
    @{ Key='gaming';     Title='Gaming and speed';       Intro='Settings that help games run smoothly and respond quickly.' }
    @{ Key='graphics';   Title='Graphics';               Intro='Screen refresh rate, which graphics card a game uses, and graphics card options.' }
    @{ Key='network';    Title='Internet and network';   Intro='Check your connection, test ping, choose a DNS provider and fix network problems.' }
    @{ Key='privacy';    Title='Privacy';                Intro='Choose what Windows can collect, share and show you.' }
    @{ Key='tweaks';     Title='Windows tweaks';         Intro='Tidy the taskbar and File Explorer and tune how Windows behaves.' }
    @{ Key='updates';    Title='Updates and apps';       Intro='Decide how Windows Update behaves, and install free apps in one go.' }
    @{ Key='system';     Title='System and storage';     Intro='Health check, clean-up tools, start-up programs, drives and repairs.' }
    @{ Key='downloads';  Title='Downloads';              Intro='Install well-known monitoring and checking tools.' }
)
