function Get-AsciiText { param([string]$s) if ($null -eq $s) { return '' }; return (($s -replace '[^\x20-\x7E]', '') -replace '\s+', ' ').Trim() }

function Remove-FromParent {
    param($El)
    $p = $El.Parent
    if ($p -is [System.Windows.Controls.Panel]) { $p.Children.Remove($El) }
    elseif ($p -is [System.Windows.Controls.Decorator]) { $p.Child = $null }
    elseif ($p -is [System.Windows.Controls.ContentControl]) { $p.Content = $null }
}

# All logical descendants of an element, depth first, as an array (so it is safe to change the tree afterwards).
function Get-LogicalDescendants {
    param($Root)
    $out = [System.Collections.Generic.List[object]]::new()
    $stack = [System.Collections.Generic.Stack[object]]::new()
    $stack.Push($Root)
    while ($stack.Count -gt 0) {
        $e = $stack.Pop()
        $kids = [System.Collections.Generic.List[object]]::new()
        $en = [System.Windows.LogicalTreeHelper]::GetChildren($e).GetEnumerator()
        while ($en.MoveNext()) { $k = $en.Current; if ($k -is [System.Windows.DependencyObject]) { $kids.Add($k) } }
        for ($i = $kids.Count - 1; $i -ge 0; $i--) { $stack.Push($kids[$i]) }
        if (-not [object]::ReferenceEquals($e, $Root)) { $out.Add($e) }
    }
    return @($out)
}
function Get-CardsIn {
    param($Root)
    $card = $window.FindResource('Card')
    return @(Get-LogicalDescendants $Root | Where-Object { $_ -is [System.Windows.Controls.Border] -and $_.Style -eq $card })
}
function Get-CardHeading {
    param($Card)
    $tb = @(Get-LogicalDescendants $Card | Where-Object { $_ -is [System.Windows.Controls.TextBlock] } | Select-Object -First 1)
    if ($tb.Count -gt 0) { return [string]$tb[0].Text }
    return ''
}
function Find-CardByHeading {
    param([string]$Like)
    $scan = if ($script:CardScan) { $script:CardScan } else { @(Get-CardsIn $window.Content) }
    foreach ($b in $scan) { if ((Get-CardHeading $b) -like $Like) { return $b } }
    return $null
}

# The mirror row used on Pro pages: the shared tweak row plus the original name, kept in step with Safe Mode.
function New-ProTweakRow {
    param([string]$Id)
    $row = New-TweakRow $Id -NoLock
    if (-not $row) { return $null }
    $info = $script:TweakInfo[$Id]
    $sp = $row.Child.Children[1]
    $row.Background = (Br 'Transparent'); $row.BorderBrush = (Br '#1c1a26'); $row.BorderThickness = [System.Windows.Thickness]::new(0,0,0,1)
    $row.CornerRadius = [System.Windows.CornerRadius]::new(0); $row.Margin = [System.Windows.Thickness]::new(0); $row.Padding = [System.Windows.Thickness]::new(2,9,2,9)
    $metaRow = @($sp.Children | Where-Object { $_ -is [System.Windows.Controls.StackPanel] -and $_.Orientation -eq 'Horizontal' } | Select-Object -First 1)[0]
    $onTxt = @($metaRow.Children | Where-Object { $_ -is [System.Windows.Controls.TextBlock] -and $_.Text -eq 'Already on' } | Select-Object -First 1)[0]
    if (-not $onTxt) { $onTxt = New-Text 'Already on' 12 '#56dd92'; $onTxt.Visibility = 'Collapsed'; $metaRow.Children.Add($onTxt) | Out-Null }
    $sp.Children.Add((New-Text "Original name: $($info.Tech)" 11 '#6b6b7c')) | Out-Null
    if ($Id -in $script:RebootIds) { $sp.Children[$sp.Children.Count - 2].Children.Add((New-Text '  Restart needed' 12 '#f0b545')) | Out-Null }
    $note = New-Text 'Safe Mode is on, so this stays off. Turn Safe Mode off in Settings to choose it.' 12 '#f0b545'
    $note.Visibility = 'Collapsed'
    $sp.Children.Insert(2, $note)
    $script:PendingMirror[$Id] = @{ Id = $Id; Card = $row; Switch = $row.Child.Children[0]; Note = $note; On = $onTxt }
    return $row
}
# Called whenever Safe Mode changes (and after the rows are built).
function Update-MirrorLocks {
    Update-ImmediateLocks
    $safe = [bool]$script:SrSettings.safeMode
    foreach ($m in $script:MirrorRows) {
        $locked = ($safe -and (Get-TweakRisk $m.Id) -ne 'S')
        $m.Switch.IsEnabled = (-not $locked)
        $m.Card.Opacity = if ($locked) { 0.6 } else { 1.0 }
        $m.Note.Visibility = if ($locked) { 'Visible' } else { 'Collapsed' }
    }
}

# Plain title, help, tags and original name around one control. The control itself stays the real one.
function New-ActionCard {
    param($Ctl, $Cap, [string]$AreaKey)
    $orig = if ($Ctl -is [System.Windows.Controls.ContentControl] -and $Ctl.Content -is [string]) { Get-AsciiText ([string]$Ctl.Content) } else { '' }
    $parent = $Ctl.Parent
    $idx = -1; $gr = $null; $gc = $null; $grs = 1; $gcs = 1; $dock = $null
    if ($parent -is [System.Windows.Controls.Panel]) {
        $idx = $parent.Children.IndexOf($Ctl)
        if ($parent -is [System.Windows.Controls.Grid]) { $gr = [System.Windows.Controls.Grid]::GetRow($Ctl); $gc = [System.Windows.Controls.Grid]::GetColumn($Ctl); $grs = [System.Windows.Controls.Grid]::GetRowSpan($Ctl); $gcs = [System.Windows.Controls.Grid]::GetColumnSpan($Ctl) }
        if ($parent -is [System.Windows.Controls.DockPanel]) { $dock = [System.Windows.Controls.DockPanel]::GetDock($Ctl) }
    }
    $card = New-Object System.Windows.Controls.Border
    $card.Background = (Br '#0d0d16'); $card.BorderBrush = (Br '#28242f'); $card.BorderThickness = [System.Windows.Thickness]::new(1)
    $card.CornerRadius = [System.Windows.CornerRadius]::new(8); $card.Padding = [System.Windows.Thickness]::new(14,10,14,10)
    $card.Margin = [System.Windows.Thickness]::new(0,0,10,8)
    if ($parent -is [System.Windows.Controls.WrapPanel]) { $card.Width = 330 }
    $gridSiblings = @()
    if ($parent -is [System.Windows.Controls.Grid]) { $gridSiblings = @($parent.Children | Where-Object { -not [object]::ReferenceEquals($_, $Ctl) -and [System.Windows.Controls.Grid]::GetRow($_) -eq $gr }) }
    $sp = New-Object System.Windows.Controls.StackPanel
    $sp.Children.Add((New-Text $Cap.T 14 '#edecf3' 'SemiBold')) | Out-Null
    $sp.Children.Add((New-Text $Cap.D 13 '#c9c7d6')) | Out-Null
    $meta = New-Object System.Windows.Controls.StackPanel; $meta.Orientation = 'Horizontal'; $meta.Margin = [System.Windows.Thickness]::new(0,6,0,6)
    $meta.Children.Add((New-RiskBadge $Cap.R)) | Out-Null
    if ($Cap.I) { $meta.Children.Add((New-Text 'Applies immediately' 12 '#f0b545')) | Out-Null }
    $sp.Children.Add($meta) | Out-Null
    $lockNote = New-Text $script:SafeLockNoteText 12 '#f0b545'; $lockNote.Visibility = 'Collapsed'
    $sp.Children.Add($lockNote) | Out-Null
    Remove-FromParent $Ctl
    $Ctl.Margin = [System.Windows.Thickness]::new(0,0,0,6)
    $Ctl.HorizontalAlignment = 'Left'
    # plain styles: red only for real dangers (Advanced), neutral for Careful, the normal primary look for Safe
    if ($Ctl -is [System.Windows.Controls.Button]) { $Ctl.Style = $window.FindResource($(switch ($Cap.R) { 'S' { 'BtnPrimary' } 'A' { 'BtnAccent' } default { 'BtnGray' } })); $Ctl.Height = 34; $Ctl.Padding = [System.Windows.Thickness]::new(16,0,16,0) }
    if ($Ctl -is [System.Windows.Controls.ContentControl] -and $Ctl.Content -is [string]) { $Ctl.Content = $Cap.T }
    $sp.Children.Add($Ctl) | Out-Null
    if ($orig) { $sp.Children.Add((New-Text "Original label: $orig" 11 '#6b6b7c')) | Out-Null }
    $card.Child = $sp
    if ($parent -is [System.Windows.Controls.Panel]) {
        if ($idx -lt 0 -or $idx -gt $parent.Children.Count) { $idx = $parent.Children.Count }
        $parent.Children.Insert($idx, $card)
        if ($parent -is [System.Windows.Controls.Grid]) {
            foreach ($sib in $gridSiblings) { $sib.Visibility = 'Collapsed' }
            [System.Windows.Controls.Grid]::SetRow($card, $gr); [System.Windows.Controls.Grid]::SetColumn($card, 0); [System.Windows.Controls.Grid]::SetRowSpan($card, $grs)
            [System.Windows.Controls.Grid]::SetColumnSpan($card, [Math]::Max(1, $parent.ColumnDefinitions.Count))
        }
        if ($parent -is [System.Windows.Controls.DockPanel]) { [System.Windows.Controls.DockPanel]::SetDock($card, $dock) }
    } elseif ($parent -is [System.Windows.Controls.Decorator]) { $parent.Child = $card }
    elseif ($parent -is [System.Windows.Controls.ContentControl]) { $parent.Content = $card }
    # when code shows or hides the button (for example the Use fastest DNS button), the card follows it
    $b = New-Object System.Windows.Data.Binding 'Visibility'; $b.Source = $Ctl; $b.Mode = [System.Windows.Data.BindingMode]::OneWay
    [void]$card.SetBinding([System.Windows.UIElement]::VisibilityProperty, $b)
    $areaTitle = ($script:ProAreas | Where-Object { $_.Key -eq $AreaKey } | Select-Object -First 1).Title
    $script:ProIndex.Add(@{ Name = [string]$Ctl.Name; Title = $Cap.T; Desc = $Cap.D; Orig = $orig; AreaKey = $AreaKey; AreaTitle = $areaTitle; Card = $card })
    $script:ProCardByName[[string]$Ctl.Name] = $card
    if ([string]$Ctl.Name -eq 'BtnWUSecurity') {
        $meta.Children.Add((New-Text '  Recommended' 12 '#56dd92' 'SemiBold')) | Out-Null
        $pp = $card.Parent
        if ($pp -is [System.Windows.Controls.Panel]) { $pp.Children.Remove($card); $pp.Children.Insert(0, $card) }
    }
    if ([string]$Ctl.Name -eq 'BtnWUDisable') { $meta.Children.Add((New-Text '  Not recommended' 12 '#ff6b6b' 'SemiBold')) | Out-Null }
    if ($Cap.I -and $Ctl -is [System.Windows.Controls.Button]) {
        $script:ImmediateCtls.Add(@{ Ctl = $Ctl; Risk = $Cap.R; Note = $lockNote; Locked = $false; WasEnabled = $true; Card = $card })
        $Ctl.Add_IsEnabledChanged({ param($s, $e) Test-ImmediateRelock $s })
        $Ctl.Add_Click({ try { Sync-ToolBatches } catch {} })
    }
    return $card
}

# Restyles everything inside one container in place.
function Convert-ProContainer {
    param($Root, [string]$AreaKey)
    if ($Root -is [System.Windows.FrameworkElement] -and $Root.Tag -eq 'pro-converted') { return }
    # 1. card headings
    foreach ($card in @(Get-CardsIn $Root)) {
        $hd = @(Get-LogicalDescendants $card | Where-Object { $_ -is [System.Windows.Controls.TextBlock] } | Select-Object -First 1)
        if ($hd.Count -eq 0) { continue }
        $h = $hd[0]; $orig = [string]$h.Text
        $title = $null
        foreach ($k in $script:CardTitles.Keys) { if ($orig -like $k) { $title = $script:CardTitles[$k]; break } }
        if (-not $title) { continue }
        $h.Text = $title; $h.FontSize = 15; $h.FontWeight = [System.Windows.FontWeights]::SemiBold; $h.Foreground = (Br '#edecf3')
        $par = $h.Parent
        if ($par -is [System.Windows.Controls.Panel]) {
            $i = $par.Children.IndexOf($h)
            $g = New-Text "Original name: $(Get-AsciiText $orig)" 11 '#6b6b7c'; $g.Margin = [System.Windows.Thickness]::new(0,0,0,8)
            $par.Children.Insert($i + 1, $g)
            if ($AreaKey -eq 'games') {
                $cn = New-Text 'This changes the game''s own settings files. Some anti-cheat systems may flag edited files, so check the game''s rules first. Restore puts your backup back.' 12 '#f0b545'; $cn.Margin = [System.Windows.Thickness]::new(0,0,0,8)
                $par.Children.Insert($i + 2, $cn)
            }
        }
    }
    foreach ($tbx in @(Get-LogicalDescendants $Root | Where-Object { $_ -is [System.Windows.Controls.TextBlock] -and ([string]$_.Text) -like 'Finds the highest refresh rate supported*' })) { $tbx.Visibility = 'Collapsed' }
    # 2. setting checkboxes become switch rows bound to the real checkbox (safe to run again after a failure)
    foreach ($cb in @(Get-LogicalDescendants $Root | Where-Object { $_ -is [System.Windows.Controls.CheckBox] -and $_.Name -and ($_.Name -in $tweakBoxes) })) {
        $p = $cb.Parent
        if ($p -isnot [System.Windows.Controls.Panel]) { continue }
        $id = [string]$cb.Name
        $have = @($p.Children | Where-Object { $_ -is [System.Windows.Controls.Border] -and $_.Tag -eq "mirror:$id" } | Select-Object -First 1)
        if ($have.Count -eq 0) {
            $row = New-ProTweakRow $id
            if (-not $row) { continue }
            $row.Tag = "mirror:$id"
            $i = $p.Children.IndexOf($cb)
            $p.Children.Insert($i, $row)
        }
        $cb.Visibility = 'Collapsed'
        $at = $p.Children.IndexOf($cb)
        $nx = if ($at + 1 -lt $p.Children.Count) { $p.Children[$at + 1] } else { $null }
        if ($nx -is [System.Windows.Controls.TextBlock] -and $nx.Style -eq $window.FindResource('Desc')) { $nx.Visibility = 'Collapsed' }
        if (-not ($script:MirrorRows | Where-Object { $_.Id -eq $id })) { if ($script:PendingMirror.ContainsKey($id)) { $script:MirrorRows.Add($script:PendingMirror[$id]) } }
    }
    # 3. buttons and lists get action cards
    foreach ($ctl in @(Get-LogicalDescendants $Root | Where-Object { ($_ -is [System.Windows.Controls.Button] -or $_ -is [System.Windows.Controls.ListBox]) -and $_.Name -and $script:ProCaps.ContainsKey([string]$_.Name) })) {
        $n = [string]$ctl.Name
        if ($n -in @('BtnRefreshHealth','BtnReapplyDrifted','BtnUndoLast','BtnApplyAll')) { continue }
        if ($script:ProCardByName.ContainsKey($n)) { continue }
        $cap = $script:ProCaps[$n]
        if ($ctl -is [System.Windows.Controls.ListBox]) {
            $p = $ctl.Parent
            if ($p -is [System.Windows.Controls.Panel]) {
                $i = $p.Children.IndexOf($ctl)
                $t = New-Text "$($cap.T). $($cap.D)" 13 '#c9c7d6'; $t.Margin = [System.Windows.Thickness]::new(0,0,0,6)
                $p.Children.Insert($i, $t)
                $script:ProIndex.Add(@{ Name = $n; Title = $cap.T; Desc = $cap.D; Orig = ''; AreaKey = $AreaKey; AreaTitle = (($script:ProAreas | Where-Object { $_.Key -eq $AreaKey } | Select-Object -First 1).Title); Card = $t })
                $script:ProCardByName[$n] = $t
            }
            continue
        }
        $cardX = New-ActionCard $ctl $cap $AreaKey
        if ($n -eq 'BtnWUDisable' -and $cardX.Parent -is [System.Windows.Controls.Panel]) {
            $pp = $cardX.Parent; $ix = $pp.Children.IndexOf($cardX); $pp.Children.Remove($cardX)
            $ex = New-Object System.Windows.Controls.Expander
            $ex.Header = 'Not recommended: switch Windows Update off (open to see)'; $ex.Foreground = (Br '#ff6b6b'); $ex.IsExpanded = $false; $ex.Margin = [System.Windows.Thickness]::new(0,8,0,8)
            $ex.Content = $cardX; $pp.Children.Insert($ix, $ex)
        }
    }
}

function Add-ProSection {
    param([string]$ElName, [string]$AreaKey)
    $el = $c[$ElName]
    if (-not $el) { return }
    Remove-FromParent $el
    $el.Visibility = 'Visible'; $el.Margin = [System.Windows.Thickness]::new(0)
    if ($el -is [System.Windows.Controls.Border] -and $el.Child -is [System.Windows.FrameworkElement]) { $el.Child.Margin = [System.Windows.Thickness]::new(0) }
    $script:ProPanels[$AreaKey].Children.Add($el) | Out-Null
}
function Add-ProCard {
    param($Card, [string]$AreaKey)
    if (-not $Card) { return }
    Remove-FromParent $Card
    $script:ProPanels[$AreaKey].Children.Add($Card) | Out-Null
}

function Build-ProNav {
    $nav = $c['ProNavList']; $nav.Children.Clear()
    $hd = New-Text 'AREAS' 11 '#a78bff' 'Bold'; $hd.Margin = [System.Windows.Thickness]::new(8,0,0,8)
    $nav.Children.Add($hd) | Out-Null
    $entries = @()
    foreach ($a in $script:ProAreas) { $entries += ,@($a.Key, $a.Title) }
    $entries += ,@('-', '')
    $entries += ,@('mypc', 'My PC'); $entries += ,@('history', 'History and Undo'); $entries += ,@('settings', 'Settings')
    foreach ($e in $entries) {
        if ($e[0] -eq '-') { $sep = New-Object System.Windows.Controls.Separator; $sep.Style = $window.FindResource('Sep'); $sep.Margin = [System.Windows.Thickness]::new(0,8,0,8); $nav.Children.Add($sep) | Out-Null; continue }
        $b = New-Object System.Windows.Controls.Button
        $b.Style = $window.FindResource('BtnNav'); $b.Tag = $e[0]
        $b.BorderThickness = [System.Windows.Thickness]::new(3,0,0,0); $b.Padding = [System.Windows.Thickness]::new(12,4,8,4); $b.Margin = [System.Windows.Thickness]::new(0,0,0,1)
        $t = New-Text $e[1] 13 '#c9c7d6' 'SemiBold'; $t.Width = 176; $t.TextWrapping = 'NoWrap'; $t.TextAlignment = 'Left'
        $b.Content = $t; $b.HorizontalAlignment = 'Stretch'
        $b.Add_Click({ param($s, $e2) Invoke-ProNav ([string]$s.Tag) })
        $nav.Children.Add($b) | Out-Null
    }
}
function Invoke-ProNav {
    param([string]$Key)
    switch ($Key) {
        'mypc'     { Show-SimplePage 'PageMyPc' }
        'history'  { Show-SimplePage 'PageHistory' }
        'settings' { Show-SimplePage 'PageSettings' }
        default    { Show-ProArea $Key }
    }
}
function Set-ProNavActive {
    param([string]$Key)
    if ($script:ProNavLastKey -eq $Key -and $script:ProNavLastKey) { }
    foreach ($b in @($c['ProNavList'].Children | Where-Object { $_ -is [System.Windows.Controls.Button] })) {
        $on = ([string]$b.Tag -eq $Key)
        $b.BorderBrush = if ($on) { (Br '#7c5cff') } else { (Br 'Transparent') }
        $b.Background = if ($on) { (Br '#1A7C5CFF') } else { (Br 'Transparent') }
        $b.Content.Foreground = if ($on) { (Br '#edecf3') } else { (Br '#c9c7d6') }
    }
}
$script:ProNavLastKey = ''

function Build-PresetCardsInto {
    param($Panel)
    $Panel.Children.Clear()
    foreach ($p in $script:SrPresets) {
        $ids = Get-PresetIds $p.Key
        $r = Get-RiskCounts $ids
        $btn = New-Object System.Windows.Controls.Button
        $btn.Style = $window.FindResource('BtnCard'); $btn.Tag = $p.Key; $btn.MinHeight = 120; $btn.VerticalContentAlignment = 'Top'
        $sp = New-Object System.Windows.Controls.StackPanel
        $sp.Children.Add((New-Text $p.Title 15 '#edecf3' 'SemiBold')) | Out-Null
        $sp.Children.Add((New-Text $p.Promise 12 '#c9c7d6')) | Out-Null
        $cnt = New-Text "$($r.S) Safe, $($r.C) Careful, $($r.A) Advanced" 11 '#8b8b9c'; $cnt.Margin = [System.Windows.Thickness]::new(0,6,0,0)
        $sp.Children.Add($cnt) | Out-Null
        $tags = @($p.Tags)
        if (@($ids | Where-Object { $_ -in $script:RebootIds }).Count -gt 0) { $tags += 'Restart needed' }
        if ($tags.Count -gt 0) { $sp.Children.Add((New-Text ($tags -join '  |  ') 11 '#f0b545')) | Out-Null }
        $btn.Content = $sp
        $btn.Add_Click({ param($s, $e) Show-PresetPage ([string]$s.Tag) })
        $Panel.Children.Add($btn) | Out-Null
    }
}

# The Pro pages are built in two parts. The core (pages, moved cards, navigation) is quick. Turning each area's old controls into the new rows and
# cards is the slow part (about 3 seconds in all), so it is done one area at a time: when an area is first opened, or in background idle steps after
# start-up. Without -Deferred everything is finished before returning (search, the palette and Open-ProCard need all of it).
$script:ProConvPending = [System.Collections.Generic.List[string]]::new()
function Complete-ProConvert {
    param([string]$Key)
    if (-not $script:ProConvPending.Contains($Key)) { return }
    if ($Key -eq 'everything') { $root = $c['ProToolbar'] } else { $root = $script:ProPanels[$Key] }
    if (-not $root) { [void]$script:ProConvPending.Remove($Key); return }
    Convert-ProContainer $root $Key; $root.Tag = 'pro-converted'
    [void]$script:ProConvPending.Remove($Key)
    Update-MirrorLocks
}
function Initialize-ProAreas {
    param([switch]$Deferred)
    if ($script:ProBuilt -and ($Deferred -or $script:ProConvPending.Count -eq 0)) { return }
    try {
        if (-not $script:ProBuilt) { $script:CardScan = @(Get-CardsIn $window.Content); Initialize-ProAreasCore; $script:ProBuilt = $true }
        if (-not $Deferred) { foreach ($pk in @($script:ProConvPending)) { Complete-ProConvert $pk } }
    }
    catch {
        Write-SR "Could not build the Pro pages: $($_.Exception.Message)" 'FAIL'
        $c['LogText'].Text = "The Pro pages could not be built ($($_.Exception.Message)). Try opening Pro again."
        throw
    }
    finally { $script:CardScan = $null }
}
function Initialize-ProAreasCore {
    $host2 = $c['PageProArea']
    foreach ($a in $script:ProAreas) {
        if ($a.Key -eq 'everything') { continue }
        if ($script:ProPanels.ContainsKey($a.Key)) { continue }
        $sp = New-Object System.Windows.Controls.StackPanel
        $sp.Visibility = 'Collapsed'
        $t = New-Text $a.Title 28 '#edecf3' 'SemiBold'
        $i = New-Text $a.Intro 14 '#c9c7d6'; $i.Margin = [System.Windows.Thickness]::new(0,4,0,14)
        $sp.Children.Add($t) | Out-Null; $sp.Children.Add($i) | Out-Null
        # "Recommended for your PC" strip (shown only when this area has recommended Safe items)
        if ($script:ProAreaTag.ContainsKey($a.Key)) {
            $strip = New-Object System.Windows.Controls.Border
            $strip.Background = (Br '#12101f'); $strip.BorderBrush = (Br '#597C5CFF'); $strip.BorderThickness = [System.Windows.Thickness]::new(1)
            $strip.CornerRadius = [System.Windows.CornerRadius]::new(8); $strip.Padding = [System.Windows.Thickness]::new(14,10,14,10); $strip.Margin = [System.Windows.Thickness]::new(0,0,0,14)
            $dp = New-Object System.Windows.Controls.DockPanel
            $sb = New-Object System.Windows.Controls.Button; $sb.Style = $window.FindResource('BtnPrimary'); $sb.Height = 34; $sb.Padding = [System.Windows.Thickness]::new(16,0,16,0)
            $sb.Content = 'Add to review list'; $sb.Tag = $a.Key; $sb.Margin = [System.Windows.Thickness]::new(14,0,0,0)
            [System.Windows.Controls.DockPanel]::SetDock($sb, 'Right')
            $sb.Add_Click({ param($s, $e) Add-ProStripItems ([string]$s.Tag) })
            $st = New-Text '' 13 '#c9c7d6'
            $dp.Children.Add($sb) | Out-Null; $dp.Children.Add($st) | Out-Null
            $strip.Child = $dp; $strip.Visibility = 'Collapsed'
            $sp.Children.Add($strip) | Out-Null
            $script:ProStrips[$a.Key] = @{ Strip = $strip; Text = $st; Button = $sb }
        }
        $host2.Children.Add($sp) | Out-Null
        $script:ProPanels[$a.Key] = $sp
    }
    # take the cards that belong elsewhere out of the gaming section first
    $selTools = Find-CardByHeading 'SELECTION TOOLS'
    $wifiCard = Find-CardByHeading 'WIFI GAMING MODE'
    $dispCard = Find-CardByHeading 'DISPLAY REFRESH RATE'
    $usbCard  = Find-CardByHeading 'USB HID POLLING*'
    $gpuApp   = Find-CardByHeading 'FORCE DISCRETE GPU*'
    $intelCard = Find-CardByHeading 'INTEL HYBRID CPU*'
    $amdCard  = Find-CardByHeading 'AMD LAUNCHER PRIORITY*'
    # Everything: toolbar above the table (selection tools, old preset buttons, preset cards)
    $tb = $c['ProToolbar']
    if (-not $script:ProToolbarBuilt) {
    $lbl = New-Text 'Quick presets' 15 '#edecf3' 'SemiBold'; $lbl.Margin = [System.Windows.Thickness]::new(2,4,0,6)
    $tb.Children.Add($lbl) | Out-Null
    $pg = New-Object System.Windows.Controls.Primitives.UniformGrid; $pg.Columns = 4; $pg.Margin = [System.Windows.Thickness]::new(0,0,-10,10)
    $c['ProToolbarPresets'] = $pg
    $tb.Children.Add($pg) | Out-Null
    $ql = New-Text 'Quick select (ticks the list straight away, nothing is applied)' 13 '#c9c7d6'; $ql.Margin = [System.Windows.Thickness]::new(2,4,0,6)
    $tb.Children.Add($ql) | Out-Null
    $qw = New-Object System.Windows.Controls.WrapPanel; $qw.Margin = [System.Windows.Thickness]::new(0,0,0,10)
    $qmap = @(@('BtnDashPresetGaming','Gaming'), @('BtnDashPresetStreaming','Streaming'))
    $oldPresetGrid = if ($c['BtnDashPresetGaming']) { $c['BtnDashPresetGaming'].Parent } else { $null }
    foreach ($q in $qmap) {
        $b = $c[$q[0]]; if (-not $b) { continue }
        Remove-FromParent $b
        $b.Content = $q[1]; $b.Width = 120; $b.Height = 32; $b.Margin = [System.Windows.Thickness]::new(0,0,8,6)
        $qw.Children.Add($b) | Out-Null
    }
    $qw.Visibility = 'Collapsed'; $ql.Visibility = 'Collapsed'
    $tb.Children.Add($qw) | Out-Null
    if ($oldPresetGrid) {
        $oldPresetGrid.Visibility = 'Collapsed'
        $pp = $oldPresetGrid.Parent
        if ($pp -is [System.Windows.Controls.Panel]) { $ix = $pp.Children.IndexOf($oldPresetGrid); if ($ix -gt 0 -and $pp.Children[$ix - 1] -is [System.Windows.Controls.TextBlock]) { $pp.Children[$ix - 1].Visibility = 'Collapsed' } }
    }
    if ($selTools) { Remove-FromParent $selTools; $tb.Children.Add($selTools) | Out-Null }
    foreach ($ob in @('BtnPresetGaming','BtnPresetStreaming')) { if ($c[$ob]) { $c[$ob].Visibility = 'Collapsed' } }
    $script:ProToolbarBuilt = $true
    }
    # moves
    Add-ProSection 'SecGaming' 'gaming'
    foreach ($pn in @('GamPanTweaks','GamPanGpu')) { if ($c[$pn]) { $c[$pn].Visibility = 'Visible' } }
    Add-ProCard $dispCard 'graphics'; Add-ProCard $gpuApp 'graphics'
    if ($c['GamPanGpu']) { Add-ProSection 'GamPanGpu' 'graphics' }
    Add-ProCard $wifiCard 'network'
    Add-ProSection 'SecNetwork' 'network'
    Add-ProSection 'SecPrivacy' 'privacy'
    Add-ProSection 'SecTweaks' 'tweaks'
    Add-ProSection 'SecUpdates' 'updates'
    Add-ProSection 'SecSystem' 'system'
    Add-ProSection 'SecDashboard' 'system'
    $dashStack = if ($c['SecDashboard'] -and $c['SecDashboard'].Child -is [System.Windows.Controls.StackPanel]) { $c['SecDashboard'].Child } else { $null }
    if ($dashStack -and $dashStack.Children.Count -ge 3) {
        $dashStack.Children[0].Visibility = 'Collapsed'   # old heading and version label
        $dashStack.Children[1].Visibility = 'Collapsed'   # old CPU / GPU / RAM / ping tiles (Home has the live tiles)
        $lastG = $dashStack.Children[$dashStack.Children.Count - 1]
        if ($lastG -is [System.Windows.Controls.Grid]) { foreach ($ch in @($lastG.Children)) { if ([System.Windows.Controls.Grid]::GetColumn($ch) -eq 2) { $ch.Visibility = 'Collapsed' } } }
    }
    Add-ProCard $usbCard 'gaming'; Add-ProCard $intelCard 'gaming'; Add-ProCard $amdCard 'gaming'
    Add-ProSection 'SecDownloads' 'downloads'
    foreach ($tab in @('BtnGamTabTweaks','BtnGamTabGpu')) { if ($c[$tab]) { $c[$tab].Visibility = 'Collapsed' } }
    # the old preset heading in the dashboard is now empty, so hide it
    # restyle: the cards in every area, the toolbar and the Everything selection tools
    # (the conversion itself is done per area by Complete-ProConvert)
    $script:ProConvPending.Clear()
    foreach ($key in @($script:ProPanels.Keys)) { if ($script:ProPanels[$key].Tag -ne 'pro-converted') { [void]$script:ProConvPending.Add([string]$key) } }
    if ($tb.Tag -ne 'pro-converted') { [void]$script:ProConvPending.Add('everything') }
    Build-ProNav
    Update-ImmediateLocks
    foreach ($hold in @('SideNav')) { if ($c[$hold]) { Remove-FromParent $c[$hold]; $c[$hold].Visibility = 'Collapsed'; $c['ProNavList'].Children.Add($c[$hold]) | Out-Null } }
    if ($window.FindName('ContentArea')) { Remove-FromParent $window.FindName('ContentArea'); $window.FindName('ContentArea').Visibility = 'Collapsed'; $c['PageProArea'].Children.Add($window.FindName('ContentArea')) | Out-Null }
    Update-MirrorLocks
}

function Get-ProStripIds {
    param([string]$Key)
    $tag = $script:ProAreaTag[$Key]
    return @(Get-GoalIds 'recommended' | Where-Object { $script:TweakInfo.ContainsKey($_) -and $script:TweakInfo[$_].Area -eq $tag })
}
function Add-ProStripItems {
    param([string]$Key)
    $ids = Get-ProStripIds $Key
    $n = Add-ChosenIds $ids
    Update-Count
    $c['LogText'].Text = "$n newly added, $($ids.Count - $n) already in your review list. Review list now: $(@(Get-SelectedNames).Count). Nothing changes until you press Apply."
    Write-SR "Area '$Key': $($ids.Count) recommended Safe item(s) added to the review list, $n newly ticked (nothing applied)" 'INFO'
    Update-ProStrip $Key
}
function Update-ProStrip {
    param([string]$Key)
    if (-not $script:ProStrips.ContainsKey($Key)) { return }
    $s = $script:ProStrips[$Key]
    $ids = Get-ProStripIds $Key
    $kind = if (Test-IsLaptop) { 'laptop' } else { 'PC' }
    if ($ids.Count -gt 0) {
        $pending = @($ids | Where-Object { $c[$_] -and -not $c[$_].IsChecked }).Count
        $s.Strip.Visibility = 'Visible'
        $s.Text.Text = "Recommended for your ${kind}: $($ids.Count) Safe setting$(if($ids.Count -ne 1){'s'}) in this area. $(if ($pending -eq 0) { 'They are already in your review list.' } else { 'Nothing is added until you press the button.' })"
        $s.Button.IsEnabled = ($pending -gt 0)
    } else { $s.Strip.Visibility = 'Collapsed' }
}

function Show-ProArea {
    param([string]$Key)
    Initialize-ProAreas -Deferred
    if (-not $Key) { $Key = 'everything' }
    try { Complete-ProConvert $Key } catch { $c['LogText'].Text = "The Pro pages could not be built ($($_.Exception.Message)). Try opening Pro again."; Write-SR "Could not build the Pro page '$Key': $($_.Exception.Message)" 'FAIL'; throw }
    $script:ProAreaKey = $Key
    if ($Key -eq 'everything') {
        $pg = $c['ProToolbarPresets']; if ($pg) { Build-PresetCardsInto $pg }
        Show-SimplePage 'PageTable'
        return
    }
    foreach ($k in $script:ProPanels.Keys) { $script:ProPanels[$k].Visibility = if ($k -eq $Key) { 'Visible' } else { 'Collapsed' } }
    Show-SimplePage 'PageProArea'
    if ($Key -eq 'network') { Ensure-NetInfo } elseif ($Key -eq 'system') { Ensure-SystemDetails }
    Update-ProStrip $Key
    Update-MirrorStatus $Key
    Update-ImmediateLocks
    try {
        if ($Key -eq 'system' -and (Get-Command Load-Dashboard -ErrorAction SilentlyContinue)) { Load-Dashboard }
        elseif ($Key -ne 'system' -and (Get-Command Stop-DashboardMetricsTimer -ErrorAction SilentlyContinue)) { Stop-DashboardMetricsTimer }
    } catch {}
    Set-ProNavActive $Key
}
function Open-ProCard {
    param([string]$Name)
    Initialize-ProAreas
    $i = $script:ProIndex | Where-Object { $_.Name -eq $Name } | Select-Object -First 1
    if (-not $i) { return }
    Set-UiMode 'pro' -Area $i.AreaKey
    try { $q = [System.Windows.LogicalTreeHelper]::GetParent($i.Card); while ($q) { if ($q -is [System.Windows.Controls.Expander]) { $q.IsExpanded = $true }; $q = [System.Windows.LogicalTreeHelper]::GetParent($q) } } catch {}
    try { $window.UpdateLayout(); $i.Card.BringIntoView() } catch {}
}

# ---- navigation overrides ---------------------------------------------------------------------------------------
function Set-UiMode {
    param([string]$Mode, [string]$Area = '')
    $script:SrMode = $Mode
    $script:SrSettings.mode = $Mode
    $script:SrSettings.welcomeDone = $true     # choosing a mode yourself counts as having seen the welcome
    Set-ModeButtons
    if ($Mode -eq 'pro') { Show-ProArea $(if ($Area) { $Area } elseif ($script:ProAreaKey) { $script:ProAreaKey } else { 'everything' }) }
    else { Show-SimplePage 'PageHome' }
    Save-SrSettings
}
function Open-ProArea {
    param([string]$Tag, [string]$GamTab = '')
    $key = if ($script:SecToArea.ContainsKey($Tag)) { $script:SecToArea[$Tag] } else { $Tag }
    if ($GamTab -eq 'BtnGamTabGpu') { $key = 'graphics' }
    Set-UiMode 'pro' -Area $key
}
function Show-Back { if ($script:SrMode -eq 'pro') { Show-ProArea $script:ProAreaKey } else { Set-UiMode 'simple' } }
#endregion v7 Round 2: Pro areas

function Test-IsUnder {
    param($El, $Root)
    $p = $El
    while ($p) { if ($p -eq $Root) { return $true }; $p = [System.Windows.LogicalTreeHelper]::GetParent($p) }
    return $false
}

# ---- search: area pages and action cards, by plain words and by original names ------------------------------------
function Get-PaletteItems {
    Initialize-ProAreas
    $items = [System.Collections.Generic.List[hashtable]]::new()
    $act = @(
        @('Go to Home', 'Simple view', { Set-UiMode 'simple' }),
        @('Go to Pro', 'Every setting, in one list', { Set-UiMode 'pro' -Area 'everything' }),
        @('My PC', 'Page', { Show-SimplePage 'PageMyPc' }),
        @('History and Undo', 'Page', { Show-SimplePage 'PageHistory' }),
        @('Settings', 'Page', { Show-SimplePage 'PageSettings' }),
        @('Review list', 'Page', { Show-SimplePage 'PageBasket' }),
        @('Undo last batch', 'Action', { if ($c['BtnUndoLast'].IsEnabled) { $c['BtnUndoLast'].RaiseEvent([System.Windows.RoutedEventArgs]::new([System.Windows.Controls.Button]::ClickEvent)) } else { $c['LogText'].Text = 'Nothing to undo yet.' } }),
        @('Help', 'Page', { Show-SimplePage 'PageHelp' }),
        @('Jargon Buster', 'Plain-English glossary', { Show-JargonBuster }),
        @('What the paid version adds', 'Page', { Show-SimplePage 'PagePaid' }),
        @('About StreamReady', 'Version and support', { Show-AboutWindow })
    )
    foreach ($a in $act) { $items.Add(@{ Text = $a[0]; Hint = $a[1]; Extra = ''; Action = $a[2] }) }
    foreach ($a in $script:ProAreas) { $k = $a.Key; $items.Add(@{ Text = "Open area: $($a.Title)"; Hint = 'Pro area'; Extra = $a.Intro; Action = [scriptblock]::Create("Set-UiMode 'pro' -Area '$k'") }) }
    foreach ($i in @($script:ProIndex | Where-Object { Test-ProCardAvailable $_.Card })) { $nm = $i.Name; $items.Add(@{ Text = $i.Title; Hint = "$($i.AreaTitle) - tool"; Extra = "$($i.Desc) $($i.Orig) $($i.Name)"; Action = [scriptblock]::Create("Open-ProCard '$nm'") }) }
    foreach ($g in $script:SrGoals) { $key = $g.Key; $items.Add(@{ Text = "Goal: $($g.Title)"; Hint = 'Shows the list before anything is added'; Extra = $g.Sub; Action = [scriptblock]::Create("Set-UiMode 'simple'; Invoke-Goal '$key'") }) }
    foreach ($p in $script:SrPresets) { $key = $p.Key; $items.Add(@{ Text = "Preset: $($p.Title)"; Hint = 'Preview before anything is added'; Extra = $p.Promise; Action = [scriptblock]::Create("Set-UiMode 'simple'; Show-PresetPage '$key'") }) }
    foreach ($id in ($script:TweakInfo.Keys | Sort-Object { $script:TweakInfo[$_].Name })) {
        $i = $script:TweakInfo[$id]
        $items.Add(@{ Text = $i.Name; Hint = "$($script:AreaNames[$i.Area]) - $(switch ($i.Risk) { 'S' { 'Safe' } 'A' { 'Advanced' } default { 'Careful' } })"; Extra = "$($i.Desc) $($i.Tech) $id"
            Action = [scriptblock]::Create("Set-UiMode 'pro' -Area 'everything'; `$script:TblRisk = 'All'; `$script:TblArea = 'All'; `$script:TblMine = `$false; `$c['TxtTableSearch'].Text = '$($i.Name -replace "'", "''")'") })
    }
    return @($items)
}
function Update-Palette {
    param([string]$Q)
    $q = $Q.Trim().ToLowerInvariant()
    if (-not $script:PalAll) { $script:PalAll = Get-PaletteItems }
    $hits = @($script:PalAll | Where-Object { -not $q -or $_.Text.ToLowerInvariant().Contains($q) -or $_.Hint.ToLowerInvariant().Contains($q) -or ([string]$_.Extra).ToLowerInvariant().Contains($q) } | Select-Object -First 12)
    $script:PalShown = $hits
    $c['LstPalette'].Items.Clear()
    foreach ($h in $hits) { [void]$c['LstPalette'].Items.Add("$($h.Text)    -    $($h.Hint)") }
    if ($hits.Count -gt 0) { $c['LstPalette'].SelectedIndex = 0 }
}

function Show-SearchResults {
    param([string]$Query)
    $q = $Query.Trim().ToLowerInvariant()
    Initialize-ProAreas
    $hits = @($script:TweakInfo.GetEnumerator() | Where-Object {
        $_.Value.Name.ToLowerInvariant().Contains($q) -or $_.Value.Desc.ToLowerInvariant().Contains($q) -or
        $_.Value.Tech.ToLowerInvariant().Contains($q) -or $_.Key.ToLowerInvariant().Contains($q) } |
        Sort-Object { $_.Value.Name } | Select-Object -First 40)
    $areaHits = @($script:ProAreas | Where-Object { $_.Title.ToLowerInvariant().Contains($q) -or $_.Intro.ToLowerInvariant().Contains($q) })
    $toolHits = @($script:ProIndex | Where-Object { (Test-ProCardAvailable $_.Card) -and ($_.Title.ToLowerInvariant().Contains($q) -or $_.Desc.ToLowerInvariant().Contains($q) -or $_.Orig.ToLowerInvariant().Contains($q) -or $_.Name.ToLowerInvariant().Contains($q)) } | Select-Object -First 15)
    $c['SearchTitle'].Text = "Results for '$Query'"
    $total = $hits.Count + $areaHits.Count + $toolHits.Count
    $c['SearchSub'].Text = if ($total -eq 0) { 'Nothing matched. Try a shorter word, for example mouse, battery or network. You can also press Ctrl+K to search pages and actions.' } elseif ($hits.Count -eq 0) { 'No settings matched, but some tools and areas did. Click one to open it.' } else { "$($hits.Count) setting$(if($hits.Count -ne 1){'s'}), $($areaHits.Count) area$(if($areaHits.Count -ne 1){'s'}) and $($toolHits.Count) tool$(if($toolHits.Count -ne 1){'s'}) found. Switch on the settings you want, then open your review list." }
    $c['SearchItems'].Children.Clear()
    if ($areaHits.Count + $toolHits.Count -gt 0) {
        $hd = New-Text 'Pro areas and tools' 15 '#edecf3' 'SemiBold'; $hd.Margin = [System.Windows.Thickness]::new(2,0,0,6); $c['SearchItems'].Children.Add($hd) | Out-Null
        foreach ($a in $areaHits) {
            $b = New-Object System.Windows.Controls.Button; $b.Style = $window.FindResource('BtnGray'); $b.Content = "Open area: $($a.Title)"; $b.Tag = $a.Key; $b.HorizontalAlignment = 'Left'; $b.Margin = [System.Windows.Thickness]::new(0,0,0,6); $b.Height = 34
            $b.Add_Click({ param($s, $e) $c['TxtSearch'].Text = ''; Set-UiMode 'pro' -Area ([string]$s.Tag) })
            $c['SearchItems'].Children.Add($b) | Out-Null
        }
        foreach ($t in $toolHits) {
            $b = New-Object System.Windows.Controls.Button; $b.Style = $window.FindResource('BtnGray'); $b.Tag = $t.Name; $b.HorizontalAlignment = 'Stretch'; $b.HorizontalContentAlignment = 'Left'; $b.Margin = [System.Windows.Thickness]::new(0,0,0,6)
            $sp = New-Object System.Windows.Controls.StackPanel
            $sp.Children.Add((New-Text $t.Title 13 '#edecf3' 'SemiBold')) | Out-Null
            $sp.Children.Add((New-Text "$($t.AreaTitle): $($t.Desc)" 12 '#8b8b9c')) | Out-Null
            $b.Content = $sp; $b.Padding = [System.Windows.Thickness]::new(12,6,12,6)
            $b.Add_Click({ param($s, $e) $c['TxtSearch'].Text = ''; Open-ProCard ([string]$s.Tag) })
            $c['SearchItems'].Children.Add($b) | Out-Null
        }
    }
    if ($hits.Count -gt 0) { $h2 = New-Text 'Settings' 15 '#edecf3' 'SemiBold'; $h2.Margin = [System.Windows.Thickness]::new(2,10,0,6); $c['SearchItems'].Children.Add($h2) | Out-Null }
    foreach ($h in $hits) { $r = New-TweakRow $h.Key; if ($r) { $c['SearchItems'].Children.Add($r) | Out-Null } }
    Show-SimplePage 'PageSearch'
}
$c['ChkSetSafe'].Add_Click({ if ($script:ProBuilt) { Update-MirrorLocks } })
try {
    $script:ContentDpd = [System.ComponentModel.DependencyPropertyDescriptor]::FromProperty([System.Windows.Controls.ContentControl]::ContentProperty, [System.Windows.Controls.Button])
    $script:ContentHook = [EventHandler]{ try { Sync-ToolBatches } catch {} }
    $script:ContentDpd.AddValueChanged($c['BtnUndoLast'], $script:ContentHook)
    $window.Add_Closed({ try { $script:ContentDpd.RemoveValueChanged($c['BtnUndoLast'], $script:ContentHook) } catch {} })
} catch {}
$c['BtnUndoLast'].Add_Click({ if ($script:ProBuilt -and $script:SrPage -eq 'PageProArea') { Update-MirrorStatus $script:ProAreaKey } })

#region v7 Round 3: safety and recovery fixes
# ---- Safe Mode gate for immediate actions (R2-02) ---------------------------------------------------------------
$script:ImmediateCtls = [System.Collections.Generic.List[hashtable]]::new()
$script:SafeLockNoteText = 'Safe Mode is on. Turn it off in Settings to use this.'
function Update-ImmediateLocks {
    $safe = [bool]$script:SrSettings.safeMode
    foreach ($m in $script:ImmediateCtls) {
        $ctl = $m.Ctl
        if ($safe -and $m.Risk -ne 'S') {
            if (-not $m.Locked) { $m.WasEnabled = [bool]$ctl.IsEnabled; $m.Locked = $true }
            $ctl.IsEnabled = $false
            $ctl.ToolTip = $script:SafeLockNoteText
            $m.Note.Visibility = 'Visible'
        } else {
            if ($m.Locked) { $m.Locked = $false; $ctl.IsEnabled = $m.WasEnabled; $ctl.ToolTip = $null }
            $m.Note.Visibility = 'Collapsed'
        }
    }
}
# some tools enable a button later (for example Apply after Analyse): while Safe Mode locks it, keep it locked
function Test-ImmediateRelock {
    param($Ctl)
    foreach ($m in $script:ImmediateCtls) {
        if ([object]::ReferenceEquals($m.Ctl, $Ctl) -and $m.Locked -and $Ctl.IsEnabled) { $m.WasEnabled = $true; $Ctl.IsEnabled = $false }
    }
}
function Get-ImmediateReport {
    return @($script:ImmediateCtls | ForEach-Object { @{ Name = [string]$_.Ctl.Name; Risk = $_.Risk; Enabled = [bool]$_.Ctl.IsEnabled; Locked = [bool]$_.Locked } })
}

# ---- recent tool actions for History (R2-06, R2-08) ---------------------------------------------------------------
$script:ToolEvents = [System.Collections.Generic.List[hashtable]]::new()
function Add-ToolEvent {
    param([string]$Message, [bool]$Ok)
    if ($script:SrApplying -or [string]::IsNullOrWhiteSpace($Message)) { return }
    if ($script:ToolEvents.Count -ge 60) { $script:ToolEvents.RemoveAt(0) }
    $script:ToolEvents.Add(@{ Time = [datetime]::Now; Message = $Message; Ok = $Ok })
}

# ---- partial Apply failure: roll back, or keep the original so Undo still works (R2-01) -----------------------------
$script:PartialNotes = @{}
function Invoke-PartialRecovery {
    param([string]$Name, $Pre, [string]$Label)
    if (-not $Pre) { $script:PartialNotes[$Name] = 'none'; return }
    try {
        if ((Read-UndoStore).ContainsKey($Name)) {
            # an earlier application is already recorded: keep that record, it is the true original
            $script:PartialNotes[$Name] = 'saved'
            Write-SR "$Label stopped part-way. The original saved earlier is kept so Undo can still put it back." 'WARN'
            return
        }
        Restore-TweakState $Pre
        $script:PartialNotes[$Name] = 'rolled'
        Write-SR "$Label stopped part-way. Your original setting was put back." 'OK'
    } catch {
        try {
            Save-UndoRecord $Name $Pre
            Save-AppliedTweakState -Names @($Name)
            $script:PartialNotes[$Name] = 'saved'
            Write-SR "$Label stopped part-way and could not be put back automatically. The original is saved so you can Undo it from History." 'WARN'
        } catch { $script:PartialNotes[$Name] = 'none'; Write-SR "$Label stopped part-way and the original could not be kept: $($_.Exception.Message)" 'FAIL' }
    }
}
function New-ManualRecoveryUndo {
    param($Inner)
    return { & $Inner; throw 'Recovery for this setting is manual. Follow the steps written in the log.' }.GetNewClosure()
}

# ---- validated, safer undo store (R2-04, R2-05, R2-13) -------------------------------------------------------------
$script:UndoSaveFailed = $false
function Read-UndoStore {
    $store = @{}
    try {
        if (Test-Path -LiteralPath $script:UndoRecordPath) {
            $raw = Get-Content -LiteralPath $script:UndoRecordPath -Raw -ErrorAction Stop
            if ($raw -and $raw.Trim()) {
                try {
                    $j = $raw | ConvertFrom-Json -ErrorAction Stop
                    if ($j) { foreach ($p in $j.PSObject.Properties) { $store[$p.Name] = $p.Value } }
                } catch {
                    # never replace an unreadable store: keep a copy and start a fresh one
                    $keep = "$($script:UndoRecordPath).unreadable-$(Get-Date -Format 'yyyyMMdd-HHmmss')"
                    Copy-Item -LiteralPath $script:UndoRecordPath -Destination $keep -ErrorAction SilentlyContinue
                    Write-SR "The saved undo records could not be read. A copy was kept at $keep" 'WARN'
                }
            }
        }
    } catch { Write-SR "Could not read the saved undo records: $($_.Exception.Message)" 'WARN' }
    return $store
}
function Write-UndoStore {
    param($Store)
    try {
        $dir = Split-Path $script:UndoRecordPath
        if (-not (Test-Path $dir)) { New-Item $dir -ItemType Directory -Force | Out-Null }
        $tmp = "$($script:UndoRecordPath).tmp"
        $Store | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath $tmp -Encoding UTF8 -ErrorAction Stop
        $null = Get-Content -LiteralPath $tmp -Raw -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop   # must read back
        Move-Item -LiteralPath $tmp -Destination $script:UndoRecordPath -Force -ErrorAction Stop
        return $true
    } catch {
        $script:UndoSaveFailed = $true
        Write-SR "Could not save the undo records: $($_.Exception.Message)" 'WARN'
        return $false
    }
}
# true only when the record matches StreamReady's own list exactly
function Test-UndoRecordValid {
    param([string]$Name, $Rec)
    try {
        if (-not $Rec -or -not $script:UndoSpecs.ContainsKey($Name)) { return $false }
        if ([string]$Rec.Tweak -ne $Name) { return $false }
        $specs = @($script:UndoSpecs[$Name]); $items = @($Rec.Items)
        if ($items.Count -ne $specs.Count) { return $false }
        for ($i = 0; $i -lt $specs.Count; $i++) {
            $p = $specs[$i].Split('|'); $it = $items[$i]
            if ([string]$it.Key -ne $p[0] -or [string]$it.Name -ne $p[1]) { return $false }
            $tok = if ($p.Count -gt 2) { $p[2] } else { '' }
            if ([string]$it.Token -ne $tok) { return $false }
            $wantKind = if ($tok) { 'Token' } else { 'Value' }
            if ([string]$it.Kind -ne $wantKind) { return $false }
            if ($it.ValueExisted -and [string]$it.Type -notin @('DWord','QWord','String','ExpandString','Binary','MultiString')) { return $false }
            if ($it.CreatedRoot) {
                $root = [string]$it.CreatedRoot
                if (-not ($it.Key -eq $root -or ([string]$it.Key).StartsWith($root + '\'))) { return $false }
            }
        }
        return $true
    } catch { return $false }
}
function Restore-TweakState {
    param($Rec)
    $name = [string]$Rec.Tweak
    if (-not (Test-UndoRecordValid $name $Rec)) {
        throw "Refused: the saved record for '$name' does not match StreamReady's own list, so nothing was changed."
    }
    $errs = @()
    $items = @($Rec.Items)
    [array]::Reverse($items)
    foreach ($it in $items) {
        try { Restore-RegItemState $it } catch { $errs += "$($it.Key)\$($it.Name): $($_.Exception.Message)" }
    }
    if ($errs.Count -gt 0) { throw ("Could not restore: " + ($errs -join '; ')) }
    Remove-UndoRecord $name
}
function Get-TweakOriginalState {
    param([string]$Name)
    if (-not $script:UndoSpecs.ContainsKey($Name)) { return $null }
    $existing = (Read-UndoStore)[$Name]
    if ($existing) {
        if (Test-UndoRecordValid $Name $existing) { return $existing }
        # keep the odd record under another name, never reuse it
        $s = Read-UndoStore
        $s["$Name.rejected-$(Get-Date -Format 'yyyyMMddHHmmss')"] = $existing
        $s.Remove($Name)
        [void](Write-UndoStore $s)
        Write-SR "A saved record for '$Name' did not match StreamReady's own list. It was set aside and not used." 'WARN'
    }
    $items = @()
    foreach ($spec in $script:UndoSpecs[$Name]) {
        $p = $spec.Split('|')
        $items += , (Get-RegItemState -Key $p[0] -Name $p[1] -Token $(if ($p.Count -gt 2) { $p[2] } else { '' }))
    }
    return @{ Tweak = $Name; Time = (Get-Date).ToString('s'); Items = $items }
}
function Undo-PersistedTweak {
    param([string]$Name)
    $s = Read-UndoStore
    if (-not $s.ContainsKey($Name)) { return $false }
    try {
        Write-SR "Reversing (saved original values): $Name" 'UNDO'
        Restore-TweakState $s[$Name]
        Remove-AppliedTweakState -Names @($Name)
        Write-SR "Undone from saved record: $Name" 'OK'
        return $true
    } catch {
        Write-SR "Undo failed for $Name`: $($_.Exception.Message)" 'FAIL'
        $c['LogText'].Text = "Could not undo $(Get-PlainName $Name): $($_.Exception.Message)"
        return $false
    }
}
# token undo: a read or delete that is refused is an error, not a silent success
function Restore-RegItemState {
    param($R)
    $key = [string]$R.Key; $name = [string]$R.Name
    if ($R.Kind -eq 'Token') {
        $cur = $null
        if ((Test-Path -LiteralPath $key) -and (@((Get-Item -LiteralPath $key).GetValueNames()) -contains $name)) {
            $cur = (Get-ItemProperty -LiteralPath $key -Name $name -ErrorAction Stop).$name
        }
        if ($null -eq $cur) { $cur = '' }
        $tok = [regex]::Escape([string]$R.Token)
        if ($R.TokenExisted) {
            if ($cur -match "$tok=\d+") { $cur = $cur -replace "$tok=\d+", ("{0}={1}" -f $R.Token, $R.TokenValue) }
            else { $cur = $cur + ("{0}={1};" -f $R.Token, $R.TokenValue) }
        } else { $cur = $cur -replace "$tok=\d+;?", '' }
        if ([string]::IsNullOrEmpty($cur) -and -not ($R.ValueExisted -and [string]$R.Data -eq '')) {
            if ((Test-Path -LiteralPath $key) -and (@((Get-Item -LiteralPath $key).GetValueNames()) -contains $name)) {
                Remove-ItemProperty -LiteralPath $key -Name $name -ErrorAction Stop
                if (@((Get-Item -LiteralPath $key).GetValueNames()) -contains $name) { throw "The value $name could not be removed." }
            }
        } else {
            if (-not (Test-Path -LiteralPath $key)) { New-Item -Path $key -Force | Out-Null }
            Set-ItemProperty -LiteralPath $key -Name $name -Value $cur -Type String -ErrorAction Stop
        }
    }
    elseif ($R.ValueExisted) {
        if (-not (Test-Path -LiteralPath $key)) { New-Item -Path $key -Force | Out-Null }
        $type = [string]$R.Type
        $data = $R.Data
        switch ($type) {
            'DWord'       { $data = [int][long]$data }
            'QWord'       { $data = [long]$data }
            'Binary'      { $data = [Convert]::FromBase64String([string]$data) }
            'MultiString' { $data = [string[]]@($data) }
            default       { $data = [string]$data }
        }
        Set-ItemProperty -LiteralPath $key -Name $name -Value $data -Type $type -ErrorAction Stop
    }
    else {
        if (Test-Path -LiteralPath $key) {
            if (@((Get-Item -LiteralPath $key).GetValueNames()) -contains $name) { Remove-ItemProperty -LiteralPath $key -Name $name -ErrorAction Stop }
        }
    }
    if ($R.CreatedRoot) { Remove-EmptyCreatedKeys $key ([string]$R.CreatedRoot) }
}

# ---- Pro row status badges stay current (R2-07) -------------------------------------------------------------------
function Update-MirrorStatus {
    param([string]$AreaKey)
    $root = if ($AreaKey -eq 'everything') { $c['PageTable'] } elseif ($script:ProPanels.ContainsKey($AreaKey)) { $script:ProPanels[$AreaKey] } else { $null }
    foreach ($m in $script:MirrorRows) {
        if (-not $m.On) { continue }
        if ($root -and -not (Test-IsUnder $m.Card $root)) { continue }
        $m.On.Visibility = if (Test-TweakAlreadyOn $m.Id) { 'Visible' } else { 'Collapsed' }
    }
}

# ---- search never points at a control that is not available right now (R2-11) --------------------------------------
function Test-ProCardAvailable {
    param($Card)
    $p = $Card
    while ($p -is [System.Windows.FrameworkElement]) {
        if ([object]::ReferenceEquals($p, $c['PageProArea']) -or [object]::ReferenceEquals($p, $c['PageTable'])) { return $true }
        $par = [System.Windows.LogicalTreeHelper]::GetParent($p)
        if ([object]::ReferenceEquals($par, $c['PageProArea'])) { return $true }   # the area panel itself is shown when its page opens
        if ($p.Visibility -ne 'Visible') { return $false }
        $p = $par
    }
    return $true
}
#endregion v7 Round 3: safety and recovery fixes

#region v7 Round 4: recovery, store safety, history links
$script:UndoReadFailed = $false
$script:StaleRecords = @{}
$script:ManualPending = @{}
$script:ManualInner = @{}

# ---- registry state capture and restore, now including REG_NONE (R3-03) and strict existence checks (R3-09) ----------
function Get-RegItemState {
    param([string]$Key, [string]$Name, [string]$Token = '')
    $r = @{ Kind = $(if ($Token) { 'Token' } else { 'Value' }); Key = $Key; Name = $Name; Token = $Token
            KeyExisted = $false; CreatedRoot = $null; ValueExisted = $false; Type = $null; Data = $null; TokenExisted = $false; TokenValue = $null }
    $r.KeyExisted = [bool](Test-Path -LiteralPath $Key)
    if (-not $r.KeyExisted) {
        $cur = $Key; $root = $Key
        while ($true) {
            $parent = Split-Path -Path $cur -Parent
            if (-not $parent -or (Test-Path -LiteralPath $parent)) { break }
            $root = $parent; $cur = $parent
        }
        $r.CreatedRoot = $root
    } else {
        $k = Get-Item -LiteralPath $Key
        if (@($k.GetValueNames()) -contains $Name) {
            $r.ValueExisted = $true
            $kind = $k.GetValueKind($Name)
            $r.Type = [string]$kind
            $v = $k.GetValue($Name, $null, [Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames)
            $r.Data = if ($kind -eq [Microsoft.Win32.RegistryValueKind]::Binary -or $kind -eq [Microsoft.Win32.RegistryValueKind]::None) { [Convert]::ToBase64String([byte[]]$v) } else { $v }
        }
    }
    if ($Token -and $r.ValueExisted -and ([string]$r.Data) -match ([regex]::Escape($Token) + '=(\d+)')) { $r.TokenExisted = $true; $r.TokenValue = $Matches[1] }
    return $r
}
function Set-RegNoneValue {
    param([string]$Key, [string]$Name, [byte[]]$Bytes)
    if ($Key -match '^HKCU:\\(.*)$') { $hive = [Microsoft.Win32.Registry]::CurrentUser }
    elseif ($Key -match '^HKLM:\\(.*)$') { $hive = [Microsoft.Win32.Registry]::LocalMachine }
    else { throw "Unsupported registry path: $Key" }
    $sk = $hive.CreateSubKey($Matches[1])
    try { $sk.SetValue($Name, $Bytes, [Microsoft.Win32.RegistryValueKind]::None) } finally { $sk.Close() }
}
# existence check that reports a real error instead of answering "not there"
function Test-RegKeyStrict {
    param([string]$Key)
    try { $null = Get-Item -LiteralPath $Key -ErrorAction Stop; return $true }
    catch [System.Management.Automation.ItemNotFoundException] { return $false }
}
function Restore-RegItemState {
    param($R)
    $key = [string]$R.Key; $name = [string]$R.Name
    if ($R.Kind -eq 'Token') {
        $cur = $null
        $keyThere = Test-RegKeyStrict $key
        if ($keyThere -and (@((Get-Item -LiteralPath $key -ErrorAction Stop).GetValueNames()) -contains $name)) {
            $cur = (Get-ItemProperty -LiteralPath $key -Name $name -ErrorAction Stop).$name
        }
        if ($null -eq $cur) { $cur = '' }
        $tok = [regex]::Escape([string]$R.Token)
        if ($R.TokenExisted) {
            if ($cur -match "$tok=\d+") { $cur = $cur -replace "$tok=\d+", ("{0}={1}" -f $R.Token, $R.TokenValue) }
            else { $cur = $cur + ("{0}={1};" -f $R.Token, $R.TokenValue) }
        } else { $cur = $cur -replace "$tok=\d+;?", '' }
        if ([string]::IsNullOrEmpty($cur) -and -not ($R.ValueExisted -and [string]$R.Data -eq '')) {
            if ($keyThere -and (@((Get-Item -LiteralPath $key -ErrorAction Stop).GetValueNames()) -contains $name)) {
                Remove-ItemProperty -LiteralPath $key -Name $name -ErrorAction Stop
                if (@((Get-Item -LiteralPath $key -ErrorAction Stop).GetValueNames()) -contains $name) { throw "The value $name could not be removed." }
            }
        } else {
            if (-not $keyThere) { New-Item -Path $key -Force | Out-Null }
            Set-ItemProperty -LiteralPath $key -Name $name -Value $cur -Type String -ErrorAction Stop
            $back = (Get-ItemProperty -LiteralPath $key -Name $name -ErrorAction Stop).$name
            if ([string]$back -ne [string]$cur) { throw "The value $name did not read back as expected." }
        }
    }
    elseif ($R.ValueExisted) {
        if (-not (Test-RegKeyStrict $key)) { New-Item -Path $key -Force | Out-Null }
        $type = [string]$R.Type
        $data = $R.Data
        if ($type -eq 'None') { Set-RegNoneValue $key $name ([Convert]::FromBase64String([string]$data)) }
        else {
            switch ($type) {
                'DWord'       { $data = [int][long]$data }
                'QWord'       { $data = [long]$data }
                'Binary'      { $data = [Convert]::FromBase64String([string]$data) }
                'MultiString' { $data = [string[]]@($data) }
                default       { $data = [string]$data }
            }
            Set-ItemProperty -LiteralPath $key -Name $name -Value $data -Type $type -ErrorAction Stop
        }
    }
    else {
        if (Test-RegKeyStrict $key) {
            if (@((Get-Item -LiteralPath $key -ErrorAction Stop).GetValueNames()) -contains $name) { Remove-ItemProperty -LiteralPath $key -Name $name -ErrorAction Stop }
        }
    }
    if ($R.CreatedRoot) { Remove-EmptyCreatedKeys $key ([string]$R.CreatedRoot) }
}

# ---- undo store: read errors are not "empty", writes are verified and unique (R3-04, R3-05) -----------------------------
function Read-UndoStore {
    $script:UndoReadFailed = $false
    $store = @{}
    if (-not (Test-Path -LiteralPath $script:UndoRecordPath)) { return $store }
    $raw = $null
    try { $raw = Get-Content -LiteralPath $script:UndoRecordPath -Raw -ErrorAction Stop }
    catch { $script:UndoReadFailed = $true; Write-SR "Could not read the saved undo records. Nothing will be written over them: $($_.Exception.Message)" 'WARN'; return $store }
    if (-not $raw -or -not $raw.Trim()) { return $store }
    try {
        $j = $raw | ConvertFrom-Json -ErrorAction Stop
        if ($j) { foreach ($p in $j.PSObject.Properties) { $store[$p.Name] = $p.Value } }
    } catch {
        $keep = "$($script:UndoRecordPath).unreadable-$(Get-Date -Format 'yyyyMMdd-HHmmss')"
        $copied = $false
        try { Copy-Item -LiteralPath $script:UndoRecordPath -Destination $keep -ErrorAction Stop; $copied = (Test-Path -LiteralPath $keep) } catch {}
        if ($copied) { Write-SR "The saved undo records were unreadable. A backup copy was kept at $keep" 'WARN' }
        else { $script:UndoReadFailed = $true; Write-SR 'The saved undo records were unreadable and a backup copy could not be made, so the file is left as it is.' 'WARN' }
    }
    return $store
}
function Write-UndoStore {
    param($Store)
    $tmp = "$($script:UndoRecordPath).$PID.tmp"
    try {
        $dir = Split-Path $script:UndoRecordPath
        if (-not (Test-Path $dir)) { New-Item $dir -ItemType Directory -Force | Out-Null }
        $Store | ConvertTo-Json -Depth 8 | Set-Content -LiteralPath $tmp -Encoding UTF8 -ErrorAction Stop
        $back = Get-Content -LiteralPath $tmp -Raw -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop
        $want = @($Store.Keys | Sort-Object); $got = @($back.PSObject.Properties.Name | Sort-Object)
        if (($want -join '|') -ne ($got -join '|')) { throw 'The saved file did not contain the expected records.' }
        Move-Item -LiteralPath $tmp -Destination $script:UndoRecordPath -Force -ErrorAction Stop
        return $true
    } catch {
        $script:UndoSaveFailed = $true
        Write-SR "Could not save the undo records: $($_.Exception.Message)" 'WARN'
        try { if (Test-Path -LiteralPath $tmp) { Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue } } catch {}
        return $false
    }
}
function Save-UndoRecord {
    param([string]$Name, $Rec)
    $s = Read-UndoStore
    if ($script:UndoReadFailed) { $script:UndoSaveFailed = $true; return $false }
    $s[$Name] = $Rec
    return (Write-UndoStore $s)
}
function Remove-UndoRecord {
    param([string]$Name)
    $s = Read-UndoStore
    if ($script:UndoReadFailed) { return $false }
    if (-not $s.ContainsKey($Name)) { return $true }
    $s.Remove($Name)
    return (Write-UndoStore $s)
}

# ---- record validation, tightened (R3-03, R3-06) ----------------------------------------------------------------------
function Test-UndoRecordValid {
    param([string]$Name, $Rec)
    try {
        if (-not $Rec -or -not $script:UndoSpecs.ContainsKey($Name)) { return $false }
        if ([string]$Rec.Tweak -ne $Name) { return $false }
        $specs = @($script:UndoSpecs[$Name]); $items = @($Rec.Items)
        if ($items.Count -ne $specs.Count) { return $false }
        for ($i = 0; $i -lt $specs.Count; $i++) {
            $p = $specs[$i].Split('|'); $it = $items[$i]
            if ([string]$it.Key -ne $p[0] -or [string]$it.Name -ne $p[1]) { return $false }
            $tok = if ($p.Count -gt 2) { $p[2] } else { '' }
            if ([string]$it.Token -ne $tok) { return $false }
            $wantKind = if ($tok) { 'Token' } else { 'Value' }
            if ([string]$it.Kind -ne $wantKind) { return $false }
            foreach ($f in @('KeyExisted','ValueExisted','TokenExisted')) { if ($it.$f -isnot [bool]) { return $false } }
            $root = [string]$it.CreatedRoot
            if ($it.KeyExisted) { if ($root) { return $false } }
            else {
                if (-not $root) { return $false }
                if (-not ($it.Key -eq $root -or ([string]$it.Key).StartsWith($root + '\'))) { return $false }
                if ($it.ValueExisted) { return $false }
            }
            if ($it.ValueExisted) {
                $ty = [string]$it.Type
                if ($ty -notin @('DWord','QWord','String','ExpandString','Binary','MultiString','None')) { return $false }
                if ($ty -in @('Binary','None')) { try { $null = [Convert]::FromBase64String([string]$it.Data) } catch { return $false } }
                if ($ty -in @('DWord','QWord') -and ([string]$it.Data) -notmatch '^-?\d+$') { return $false }
            } else {
                if ($it.Type -or ($null -ne $it.Data -and [string]$it.Data -ne '')) { return $false }
            }
            if ($it.Kind -eq 'Token') {
                if ($it.ValueExisted -and [string]$it.Type -ne 'String') { return $false }
                if ($it.TokenExisted) {
                    if (-not $it.ValueExisted) { return $false }
                    if ([string]$it.TokenValue -notmatch '^\d{1,10}$') { return $false }
                } elseif ($null -ne $it.TokenValue -and [string]$it.TokenValue -ne '') { return $false }
            } else {
                if ($it.TokenExisted -or ($null -ne $it.TokenValue -and [string]$it.TokenValue -ne '')) { return $false }
            }
        }
        return $true
    } catch { return $false }
}
function Restore-TweakState {
    param($Rec)
    $name = [string]$Rec.Tweak
    if (-not (Test-UndoRecordValid $name $Rec)) {
        throw "Refused: the saved record for '$name' does not match StreamReady's own list. This recovery attempt changed no values; earlier changes may remain."
    }
    $errs = @()
    $items = @($Rec.Items)
    [array]::Reverse($items)
    foreach ($it in $items) {
        try { Restore-RegItemState $it } catch { $errs += "$($it.Key)\$($it.Name): $($_.Exception.Message)" }
    }
    if ($errs.Count -gt 0) { throw ("Could not restore: " + ($errs -join '; ')) }
    if (-not (Remove-UndoRecord $name)) {
        $script:StaleRecords[$name] = $true
        Write-SR "The setting '$name' was put back, but its saved record could not be cleared. It will not be reused in this session." 'WARN'
        $c['LogText'].Text = "The setting was put back, but its saved record could not be cleared from disk."
    }
}
function Get-TweakOriginalState {
    param([string]$Name)
    if (-not $script:UndoSpecs.ContainsKey($Name)) { return $null }
    $store = Read-UndoStore
    $existing = $store[$Name]
    if ($existing -and -not $script:StaleRecords.ContainsKey($Name)) {
        if (Test-UndoRecordValid $Name $existing) { return $existing }
        $s = Read-UndoStore
        $kept = $false
        if (-not $script:UndoReadFailed) {
            $s["$Name.rejected-$(Get-Date -Format 'yyyyMMddHHmmss')"] = $existing
            $s.Remove($Name)
            $kept = Write-UndoStore $s
        }
        Write-SR "A saved record for '$Name' did not match StreamReady's own list and was not used. $(if ($kept) { 'It was kept under another name.' } else { 'It could not be moved aside on disk.' })" 'WARN'
    }
    $items = @()
    foreach ($spec in $script:UndoSpecs[$Name]) {
        $p = $spec.Split('|')
        $items += , (Get-RegItemState -Key $p[0] -Name $p[1] -Token $(if ($p.Count -gt 2) { $p[2] } else { '' }))
    }
    return @{ Tweak = $Name; Time = (Get-Date).ToString('s'); Items = $items }
}

# ---- partial Apply failure (R3-02, R3-10) ---------------------------------------------------------------------------------
function Invoke-PartialRecovery {
    param([string]$Name, $Pre, [string]$Label)
    if (-not $Pre) { $script:PartialNotes[$Name] = 'none'; Write-SR "$Label stopped part-way. No saved original exists for it, so it cannot be put back automatically." 'WARN'; return }
    $store = Read-UndoStore
    if (-not $script:UndoReadFailed -and $store.ContainsKey($Name) -and -not $script:StaleRecords.ContainsKey($Name)) {
        $script:PartialNotes[$Name] = 'saved'
        Write-SR "$Label stopped part-way. The original saved earlier is kept so Undo can still put it back." 'WARN'
        return
    }
    try {
        Restore-TweakState $Pre
        $script:PartialNotes[$Name] = 'rolled'
        Write-SR "$Label stopped part-way. Your original setting was put back." 'OK'
    } catch {
        $saved = $false
        try { $saved = ((Save-UndoRecord $Name $Pre) -eq $true) } catch {}
        if ($saved) {
            try { Save-AppliedTweakState -Names @($Name) } catch {}
            $script:PartialNotes[$Name] = 'saved'
            Write-SR "$Label stopped part-way and could not be put back automatically. The original is saved so you can Undo it from History." 'WARN'
        } else {
            # the disk copy failed: keep the original in a session entry so Undo Last Batch still has it
            $script:UndoStack.Push([ordered]@{ $Name = (New-TweakRestoreUndo $Name $Pre) })
            $n = ($script:UndoStack.Peek()).Count
            $c['BtnUndoLast'].IsEnabled = $true; $c['BtnUndoLast'].Content = "Undo Last Batch ($n change$(if($n -ne 1){'s'}))"
            $script:PartialNotes[$Name] = 'session'
            Write-SR "$Label stopped part-way. The original could not be saved to disk, so it is kept only until you close StreamReady. Use Undo Last Batch." 'WARN'
        }
    }
}
function New-ManualRecoveryUndo {
    param($Inner, [string]$Name = 'ChkGpuNvNpiProfile')
    $script:ManualInner[$Name] = $Inner
    return [scriptblock]::Create("Invoke-ManualRecovery '$Name'")
}
# manual-only recovery: show the steps, mark it as needing the person, and let the stack move on (R3-13)
function Invoke-ManualRecovery {
    param([string]$Name)
    $inner = $script:ManualInner[$Name]
    if ($inner) { & $inner }
    $script:ManualPending[$Name] = $true
    $c['LogText'].Text = "$(Get-PlainName $Name) needs manual recovery. The steps are in the log. StreamReady cannot restore it by itself."
}

# ---- tool actions linked to their Undo (R3-11) ------------------------------------------------------------------------------
function Get-PlainName { param([string]$Id)
    if ($Id.StartsWith('__')) { return (($Id.Trim('_')) -creplace '([a-z])([A-Z])', '$1 $2') }
    if ($script:TweakInfo.ContainsKey($Id)) { return $script:TweakInfo[$Id].Name }
    if ($c[$Id] -and $c[$Id].Content) { return [string]$c[$Id].Content }
    return $Id
}
function Sync-ToolBatches {
    foreach ($b in $script:UndoStack.ToArray()) {
        if (-not $b -or $b.Count -eq 0) { continue }
        $known = $false
        foreach ($e in $script:SrHistory) { if ([object]::ReferenceEquals($e.Batch, $b)) { $known = $true; break } }
        if ($known) { continue }
        $keys = @($b.Keys)
        $script:SrHistory.Add(@{ Time = [datetime]::Now; Names = $keys; Done = $keys; Failed = @(); Skipped = @(); Batch = $b; Undone = @{}; Fake = $false; Aborted = $false; RestoreOk = $null; Partial = @{}; SaveWarn = $false; Tool = $true })
    }
}
function Add-ToolEvent {
    param([string]$Message, [bool]$Ok)
    if ($script:SrApplying -or [string]::IsNullOrWhiteSpace($Message)) { return }
    if ($script:ToolEvents.Count -ge 60) { $script:ToolEvents.RemoveAt(0) }
    $script:ToolEvents.Add(@{ Time = [datetime]::Now; Message = $Message; Ok = $Ok })
    try { Sync-ToolBatches } catch {}
}

# ---- Safe Mode lock that does not touch eligibility (R3-07) ---------------------------------------------------------------
function Update-ImmediateLocks {
    $safe = [bool]$script:SrSettings.safeMode
    foreach ($m in $script:ImmediateCtls) {
        $ctl = $m.Ctl
        if ($safe -and $m.Risk -ne 'S') {
            $ctl.IsHitTestVisible = $false; $ctl.Focusable = $false; $ctl.IsTabStop = $false; $ctl.Opacity = 0.45
            if ($m.Card) { $m.Card.ToolTip = $script:SafeLockNoteText }
            $m.Locked = $true; $m.Note.Visibility = 'Visible'
        } else {
            $ctl.IsHitTestVisible = $true; $ctl.Focusable = $true; $ctl.IsTabStop = $true; $ctl.Opacity = 1.0
            if ($m.Card) { $m.Card.ToolTip = $null }
            $m.Locked = $false; $m.Note.Visibility = 'Collapsed'
        }
    }
}
function Test-ImmediateRelock { param($Ctl) }
function Get-ImmediateReport {
    return @($script:ImmediateCtls | ForEach-Object { @{ Name = [string]$_.Ctl.Name; Risk = $_.Risk; Enabled = [bool]($_.Ctl.IsEnabled -and $_.Ctl.IsHitTestVisible); Locked = [bool]$_.Locked } })
}

# ---- bottom bar says only what is true on each page (visual QA d, i) ---------------------------------------------------------
function Update-BottomBarState {
    $page = $script:SrPage
    $n = @(Get-SelectedNames).Count
    $c['BottomBar'].Visibility = if ($page -in @('PageWelcome','PageScan','PagePlan')) { 'Collapsed' } else { 'Visible' }
    $show = $true
    if ($page -in @('PageBasket','PageApplying')) { $show = $false }
    elseif ($page -in @('PageResult','PageHistory','PageMyPc','PageSettings') -and $n -eq 0) { $show = $false }
    $c['BtnOpenBasket'].Visibility = if ($show) { 'Visible' } else { 'Collapsed' }
    $c['BtnOpenBasket'].Content = if ($page -in @('PageResult','PageHistory','PageMyPc','PageSettings')) { "Back to review list ($n)" } elseif ($n -gt 0) { "Review and apply ($n)" } else { 'Review and apply' }
}
function Get-HistorySubtitle {
    param($E)
    $notes = @(); if ($E.Partial) { $notes = @($E.Partial.Values) }
    if ($notes -contains 'session') { return 'This attempt stopped part-way. The original is kept only until you close StreamReady. Use Undo Last Batch now.' }
    if ($notes -contains 'saved') { return 'This attempt stopped part-way. A saved original is available in the list below.' }
    if ($notes -contains 'none') { return 'This attempt stopped part-way. Some changes may remain and there is no automatic undo. Use your restore point if you need to go back.' }
    if ($E.Aborted) { return 'This attempt did not finish. Check whether changes remain.' }
    if ($notes -contains 'rolled' -and $E.Done.Count -eq 0) { return 'This attempt stopped part-way and the original was put back.' }
    if ($E.Done.Count -eq 0) { return 'Nothing was applied by this attempt.' }
    return 'Undone or no longer reversible.'
}
#endregion v7 Round 4

#region v7 Round 5: central Safe Mode lock, strict capture, recovery provenance
$script:PreHistorical = @{}
$script:RecoveryBatches = [System.Collections.Generic.List[object]]::new()

# ---- ONE place decides whether a tool can be used: its own eligibility AND not locked by Safe Mode (R4-01) -------------
# The lock sits on the tool's card. A disabled parent makes the button report IsEnabled = false (UI Automation included),
# while the button keeps its own enabled value untouched, so turning Safe Mode off restores it exactly.
function Update-ImmediateLocks {
    $safe = [bool]$script:SrSettings.safeMode
    foreach ($m in $script:ImmediateCtls) {
        $locked = ($safe -and $m.Risk -ne 'S')
        $m.Locked = $locked
        if ($m.Card) {
            $m.Card.IsEnabled = (-not $locked)
            $m.Card.Opacity = if ($locked) { 0.45 } else { 1.0 }
            $m.Card.ToolTip = if ($locked) { $script:SafeLockNoteText } else { $null }
        }
        $m.Note.Visibility = if ($locked) { 'Visible' } else { 'Collapsed' }
    }
}
function Get-ImmediateReport {
    return @($script:ImmediateCtls | ForEach-Object { @{ Name = [string]$_.Ctl.Name; Risk = $_.Risk; Enabled = [bool]$_.Ctl.IsEnabled; Locked = [bool]$_.Locked; OwnEnabled = [bool]$_.Ctl.GetValue([System.Windows.UIElement]::IsEnabledProperty) } })
}

# ---- capture reads fail loudly instead of looking like "absent" (R4-12) ----------------------------------------------------
function Test-RegKeyStrict {
    param([string]$Key)
    try { $null = Get-Item -LiteralPath $Key -ErrorAction Stop; return $true }
    catch [System.Management.Automation.ItemNotFoundException] { return $false }
}
function Get-RegItemState {
    param([string]$Key, [string]$Name, [string]$Token = '')
    $r = @{ Kind = $(if ($Token) { 'Token' } else { 'Value' }); Key = $Key; Name = $Name; Token = $Token
            KeyExisted = $false; CreatedRoot = $null; ValueExisted = $false; Type = $null; Data = $null; TokenExisted = $false; TokenValue = $null }
    $r.KeyExisted = Test-RegKeyStrict $Key
    if (-not $r.KeyExisted) {
        $cur = $Key; $root = $Key
        while ($true) {
            $parent = Split-Path -Path $cur -Parent
            if (-not $parent -or (Test-RegKeyStrict $parent)) { break }
            $root = $parent; $cur = $parent
        }
        $r.CreatedRoot = $root
    } else {
        $k = Get-Item -LiteralPath $Key -ErrorAction Stop
        if (@($k.GetValueNames()) -contains $Name) {
            $r.ValueExisted = $true
            $kind = $k.GetValueKind($Name)
            $r.Type = [string]$kind
            $v = $k.GetValue($Name, $null, [Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames)
            $r.Data = if ($kind -eq [Microsoft.Win32.RegistryValueKind]::Binary -or $kind -eq [Microsoft.Win32.RegistryValueKind]::None) { [Convert]::ToBase64String([byte[]]$v) } else { $v }
        }
    }
    # token rows are edited as text, so only a plain string original can be put back exactly
    if ($Token -and $r.ValueExisted -and $r.Type -ne 'String') { throw "The existing value $Name is of type $($r.Type), which cannot be put back exactly after a token change. Nothing was changed." }
    if ($Token -and $r.ValueExisted -and ([string]$r.Data) -match ([regex]::Escape($Token) + '=(\d+)')) { $r.TokenExisted = $true; $r.TokenValue = $Matches[1] }
    return $r
}
function Remove-EmptyCreatedKeys {
    param([string]$Key, [string]$Root)
    $cur = $Key
    while ($true) {
        if (Test-RegKeyStrict $cur) {
            $k = Get-Item -LiteralPath $cur -ErrorAction Stop
            if (@($k.GetValueNames()).Count -gt 0 -or @($k.GetSubKeyNames()).Count -gt 0) { break }
            Remove-Item -LiteralPath $cur -ErrorAction Stop
        }
        if ($cur -eq $Root) { break }
        $cur = Split-Path -Path $cur -Parent
        if (-not $cur) { break }
    }
}

# ---- stale record quarantine that survives a restart (R4-05) --------------------------------------------------------------
function Get-StaleFile { return "$($script:UndoRecordPath).stale" }
function Get-StaleNames { try { $f = Get-StaleFile; if (Test-Path -LiteralPath $f) { return @(Get-Content -LiteralPath $f -ErrorAction Stop | Where-Object { $_ }) } } catch {}; return @() }
function Add-StaleName { param([string]$Name) try { Add-Content -LiteralPath (Get-StaleFile) -Value $Name -Encoding ASCII -ErrorAction Stop; return $true } catch { return $false } }
function Clear-StaleName {
    param([string]$Name)
    try { $f = Get-StaleFile; if (Test-Path -LiteralPath $f) { $left = @(Get-StaleNames | Where-Object { $_ -ne $Name }); if ($left.Count -gt 0) { Set-Content -LiteralPath $f -Value $left -Encoding ASCII } else { Remove-Item -LiteralPath $f -Force } } } catch {}
}
function Restore-TweakState {
    param($Rec)
    $name = [string]$Rec.Tweak
    if (-not (Test-UndoRecordValid $name $Rec)) {
        throw "Refused: the saved record for '$name' does not match StreamReady's own list. This recovery attempt changed no values; earlier changes may remain."
    }
    $errs = @()
    $items = @($Rec.Items)
    [array]::Reverse($items)
    foreach ($it in $items) {
        try { Restore-RegItemState $it } catch { $errs += "$($it.Key)\$($it.Name): $($_.Exception.Message)" }
    }
    if ($errs.Count -gt 0) { throw ("Could not restore: " + ($errs -join '; ')) }
    if (-not (Remove-UndoRecord $name)) {
        $script:StaleRecords[$name] = $true
        $marked = Add-StaleName $name
        Write-SR "The setting '$name' was put back, but its saved record could not be cleared. $(if ($marked) { 'It is marked as used up and will not be reused, even after a restart.' } else { 'It will not be reused in this session, but the file should be removed by hand.' })" 'WARN'
        $c['LogText'].Text = 'The setting was put back, but its saved record could not be cleared from disk.'
    } else { Clear-StaleName $name }
}
function Get-TweakOriginalState {
    param([string]$Name)
    $script:PreHistorical.Remove($Name)
    if (-not $script:UndoSpecs.ContainsKey($Name)) { return $null }
    $store = Read-UndoStore
    $existing = $store[$Name]
    $stale = ($script:StaleRecords.ContainsKey($Name) -or ((Get-StaleNames) -contains $Name))
    if ($existing -and -not $stale) {
        if (Test-UndoRecordValid $Name $existing) { $script:PreHistorical[$Name] = $true; return $existing }
        $s = Read-UndoStore
        $kept = $false
        if (-not $script:UndoReadFailed) {
            $s["$Name.rejected-$(Get-Date -Format 'yyyyMMddHHmmss')"] = $existing
            $s.Remove($Name)
            $kept = Write-UndoStore $s
        }
        Write-SR "A saved record for '$Name' did not match StreamReady's own list and was not used. $(if ($kept) { 'It was kept under another name.' } else { 'It could not be moved aside on disk.' })" 'WARN'
    }
    $items = @()
    foreach ($spec in $script:UndoSpecs[$Name]) {
        $p = $spec.Split('|')
        $items += , (Get-RegItemState -Key $p[0] -Name $p[1] -Token $(if ($p.Count -gt 2) { $p[2] } else { '' }))
    }
    return @{ Tweak = $Name; Time = (Get-Date).ToString('s'); Items = $items }
}

# ---- partial failure with known provenance (R4-04, R4-11) ----------------------------------------------------------------
function Invoke-PartialRecovery {
    param([string]$Name, $Pre, [string]$Label)
    if (-not $Pre) { $script:PartialNotes[$Name] = 'none'; Write-SR "$Label stopped part-way. No saved original exists for it, so it cannot be put back automatically." 'WARN'; return }
    $pushSession = {
        param($why)
        $batch = [ordered]@{ $Name = (New-TweakRestoreUndo $Name $Pre) }
        $script:RecoveryBatches.Add($batch)
        $script:UndoStack.Push($batch)
        $n = $batch.Count
        $c['BtnUndoLast'].IsEnabled = $true; $c['BtnUndoLast'].Content = "Undo Last Batch ($n change$(if($n -ne 1){'s'}))"
        $script:PartialNotes[$Name] = 'session'
        Write-SR "$Label stopped part-way. $why" 'WARN'
    }
    $store = Read-UndoStore
    $readOk = -not $script:UndoReadFailed
    if ($script:PreHistorical.ContainsKey($Name)) {
        # Pre is an older saved original, not a snapshot of the state before this attempt: never roll back to it by guessing
        if ($readOk -and $store.ContainsKey($Name) -and -not $script:StaleRecords.ContainsKey($Name)) {
            $script:PartialNotes[$Name] = 'saved'
            Write-SR "$Label stopped part-way. The original saved earlier is kept so Undo can still put it back." 'WARN'
        } else { & $pushSession 'The saved records could not be read, so the original from before is kept only until you close StreamReady. Use Undo Last Batch.' }
        return
    }
    try {
        Restore-TweakState $Pre
        $script:PartialNotes[$Name] = 'rolled'
        Write-SR "$Label stopped part-way. Your original setting was put back." 'OK'
    } catch {
        $saved = $false
        try { $saved = ((Save-UndoRecord $Name $Pre) -eq $true) } catch {}
        if ($saved) {
            try { Save-AppliedTweakState -Names @($Name) } catch {}
            $script:PartialNotes[$Name] = 'saved'
            Write-SR "$Label stopped part-way and could not be put back automatically. The original is saved so you can Undo it from History." 'WARN'
        } else { & $pushSession 'The original could not be saved to disk, so it is kept only until you close StreamReady. Use Undo Last Batch.' }
    }
}
# live state, not a snapshot: a saved or session original is "pending" only while it still exists
function Test-RecoveryPending {
    param([string]$Name, [string]$Kind)
    if ($Kind -eq 'session') { foreach ($b in $script:UndoStack.ToArray()) { if ($b -and $b.Contains($Name)) { return $true } }; return $false }
    if ($Kind -eq 'saved') { $s = Read-UndoStore; return ($s.ContainsKey($Name) -and (Test-UndoRecordValid $Name $s[$Name])) }
    return $false
}
function Get-HistorySubtitle {
    param($E)
    $pairs = @(); if ($E.Partial) { $pairs = @($E.Partial.GetEnumerator()) }
    $pendS = @($pairs | Where-Object { $_.Value -eq 'session' -and (Test-RecoveryPending $_.Key 'session') }).Count
    $pendV = @($pairs | Where-Object { $_.Value -eq 'saved' -and (Test-RecoveryPending $_.Key 'saved') }).Count
    $none = @($pairs | Where-Object { $_.Value -eq 'none' }).Count
    $rolled = @($pairs | Where-Object { $_.Value -eq 'rolled' }).Count
    $doneBack = @($pairs | Where-Object { $_.Value -in @('session','saved') }).Count -gt 0 -and $pendS -eq 0 -and $pendV -eq 0
    if ($pendS -gt 0) { return 'This attempt stopped part-way. The original is kept only until you close StreamReady. Use Undo Last Batch now.' }
    if ($pendV -gt 0) { return 'This attempt stopped part-way. A saved original is available in the list below.' }
    if ($none -gt 0) { return 'This attempt stopped part-way. Some changes may remain and there is no automatic undo. Use your restore point if you need to go back.' }
    if ($doneBack) { return 'This attempt stopped part-way. The saved original has since been put back.' }
    if (@($pairs | Where-Object { $_.Value -eq 'notapplied' }).Count -gt 0 -and $E.Done.Count -eq 0) { return 'Nothing was applied: the current value could not be read exactly, so nothing was changed.' }
    if ($E.Aborted) { return 'This attempt did not finish. Check whether changes remain.' }
    if ($rolled -gt 0 -and $E.Done.Count -eq 0) { return 'This attempt stopped part-way and the original was put back.' }
    if ($E.Done.Count -eq 0) { return 'Nothing was applied by this attempt.' }
    return 'Undone or no longer reversible.'
}

# ---- tool batches are linked when they are pushed, not when History is opened (R4-09) --------------------------------------
function Sync-ToolBatches {
    if ($script:SrApplying) { return }
    foreach ($b in $script:UndoStack.ToArray()) {
        if (-not $b -or $b.Count -eq 0) { continue }
        $skip = $false
        foreach ($r in $script:RecoveryBatches) { if ([object]::ReferenceEquals($r, $b)) { $skip = $true; break } }
        if ($skip) { continue }
        $known = $false
        foreach ($e in $script:SrHistory) { if ([object]::ReferenceEquals($e.Batch, $b)) { $known = $true; break } }
        if ($known) { continue }
        $keys = @($b.Keys)
        $script:SrHistory.Add(@{ Time = [datetime]::Now; Names = $keys; Done = $keys; Failed = @(); Skipped = @(); Batch = $b; Undone = @{}; Fake = $false; Aborted = $false; RestoreOk = $null; Partial = @{}; SaveWarn = $false; Tool = $true })
    }
}
#endregion v7 Round 5

#region v7 Round 6: record generations, honest recovery state, tool batches at click time
$script:RecoveryConfirmed = @{}
$script:SessionBatchOf = @{}

# ---- one rule for "can this saved record still be used" (R5-02, R5-03) --------------------------------------------------------
# A used-up marker belongs to one generation of a record (a hash of its content). A fresh record has a new generation,
# so an old marker never blocks it. If the marker file cannot be read, nothing is trusted.
function Get-RecordGen {
    param($Rec)
    try {
        function Flat($o) {
            if ($null -eq $o) { return '' }
            if ($o -is [string] -or $o.GetType().IsPrimitive) { return [string]$o }
            if ($o -is [System.Collections.IDictionary]) { return '{' + ((@($o.Keys | Sort-Object) | ForEach-Object { "$_=" + (Flat $o[$_]) }) -join ',') + '}' }
            if ($o -is [System.Collections.IEnumerable]) { return '[' + ((@($o) | ForEach-Object { Flat $_ }) -join ',') + ']' }
            return '{' + ((@($o.PSObject.Properties | Sort-Object Name) | ForEach-Object { "$($_.Name)=" + (Flat $_.Value) }) -join ',') + '}'
        }
        $sha = [System.Security.Cryptography.SHA256]::Create()
        return ([BitConverter]::ToString($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes((Flat $Rec)))) -replace '-', '').Substring(0, 24)
    } catch { return 'unknown' }
}
function Get-StaleEntries {
    $f = Get-StaleFile
    if (-not (Test-Path -LiteralPath $f)) { return , @() }
    try { return , @(Get-Content -LiteralPath $f -ErrorAction Stop | Where-Object { $_ }) } catch { return $null }
}
function Add-StaleName {
    param([string]$Name, [string]$Gen)
    try { Add-Content -LiteralPath (Get-StaleFile) -Value "$Name|$Gen" -Encoding ASCII -ErrorAction Stop; return $true } catch { return $false }
}
function Clear-StaleName {
    param([string]$Name)
    try {
        $f = Get-StaleFile
        if (Test-Path -LiteralPath $f) {
            $left = @(Get-Content -LiteralPath $f -ErrorAction Stop | Where-Object { $_ -and $_ -ne $Name -and -not $_.StartsWith("$Name|") })
            if ($left.Count -gt 0) { Set-Content -LiteralPath $f -Value $left -Encoding ASCII } else { Remove-Item -LiteralPath $f -Force }
        }
    } catch {}
}
function Test-RecordConsumed {
    param([string]$Name, $Rec)
    $gen = Get-RecordGen $Rec
    if ($script:StaleRecords.ContainsKey($Name) -and $script:StaleRecords[$Name] -eq $gen) { return $true }
    $entries = Get-StaleEntries
    if ($null -eq $entries) { return $true }              # marker unreadable: do not trust the record
    return (($entries -contains "$Name|$gen") -or ($entries -contains $Name))
}
function Test-RecordUsable { param([string]$Name, $Rec) return ((Test-UndoRecordValid $Name $Rec) -and -not (Test-RecordConsumed $Name $Rec)) }

function Save-UndoRecord {
    param([string]$Name, $Rec)
    $s = Read-UndoStore
    if ($script:UndoReadFailed) { $script:UndoSaveFailed = $true; return $false }
    $s[$Name] = $Rec
    $ok = Write-UndoStore $s
    if ($ok) { $script:StaleRecords.Remove($Name); Clear-StaleName $Name }     # a committed fresh record replaces any old marker
    return $ok
}
function Restore-TweakState {
    param($Rec)
    $name = [string]$Rec.Tweak
    if (-not (Test-UndoRecordValid $name $Rec)) {
        throw "Refused: the saved record for '$name' does not match StreamReady's own list. This recovery attempt changed no values; earlier changes may remain."
    }
    $gen = Get-RecordGen $Rec
    $errs = @()
    $items = @($Rec.Items)
    [array]::Reverse($items)
    foreach ($it in $items) {
        try { Restore-RegItemState $it } catch { $errs += "$($it.Key)\$($it.Name): $($_.Exception.Message)" }
    }
    if ($errs.Count -gt 0) { throw ("Could not restore: " + ($errs -join '; ')) }
    $script:RecoveryConfirmed[$name] = $true
    if (-not (Remove-UndoRecord $name)) {
        $script:StaleRecords[$name] = $gen
        $marked = Add-StaleName $name $gen
        Write-SR "The setting '$name' was put back, but its saved record could not be cleared. $(if ($marked) { 'It is marked as used up and will not be offered or reused, even after a restart.' } else { 'It will not be reused in this session, but the file should be removed by hand.' })" 'WARN'
        $c['LogText'].Text = 'The setting was put back, but its saved record could not be cleared from disk.'
    } else { Clear-StaleName $name }
}
function Get-TweakOriginalState {
    param([string]$Name)
    $script:PreHistorical.Remove($Name)
    if (-not $script:UndoSpecs.ContainsKey($Name)) { return $null }
    $store = Read-UndoStore
    $existing = $store[$Name]
    if ($existing) {
        if (-not (Test-UndoRecordValid $Name $existing)) {
            $s = Read-UndoStore
            $kept = $false
            if (-not $script:UndoReadFailed) {
                $s["$Name.rejected-$(Get-Date -Format 'yyyyMMddHHmmss')"] = $existing
                $s.Remove($Name)
                $kept = Write-UndoStore $s
            }
            Write-SR "A saved record for '$Name' did not match StreamReady's own list (or an older kind that cannot be put back exactly) and was not used. $(if ($kept) { 'It was kept under another name.' } else { 'It could not be moved aside on disk.' })" 'WARN'
        } elseif (-not (Test-RecordConsumed $Name $existing)) { $script:PreHistorical[$Name] = $true; return $existing }
    }
    $items = @()
    foreach ($spec in $script:UndoSpecs[$Name]) {
        $p = $spec.Split('|')
        $items += , (Get-RegItemState -Key $p[0] -Name $p[1] -Token $(if ($p.Count -gt 2) { $p[2] } else { '' }))
    }
    return @{ Tweak = $Name; Time = (Get-Date).ToString('s'); Items = $items }
}
function Undo-PersistedTweak {
    param([string]$Name)
    $s = Read-UndoStore
    if ($script:UndoReadFailed -or -not $s.ContainsKey($Name)) { return $false }
    if (-not (Test-RecordUsable $Name $s[$Name])) {
        Write-SR "The saved record for $Name is used up or not usable, so Undo did nothing." 'WARN'
        $c['LogText'].Text = "The saved record for $(Get-PlainName $Name) is used up or not usable, so nothing was changed."
        return $false
    }
    try {
        Write-SR "Reversing (saved original values): $Name" 'UNDO'
        Restore-TweakState $s[$Name]
        Remove-AppliedTweakState -Names @($Name)
        Write-SR "Undone from saved record: $Name" 'OK'
        return $true
    } catch {
        Write-SR "Undo failed for $Name`: $($_.Exception.Message)" 'FAIL'
        $c['LogText'].Text = "Could not undo $(Get-PlainName $Name): $($_.Exception.Message)"
        return $false
    }
}

# ---- partial failure: the recovery is linked to the batch that holds it, and "recovered" must be confirmed (R5-04) -----------
function Invoke-PartialRecovery {
    param([string]$Name, $Pre, [string]$Label)
    $script:RecoveryConfirmed.Remove($Name); $script:SessionBatchOf.Remove($Name)
    if (-not $Pre) { $script:PartialNotes[$Name] = 'none'; Write-SR "$Label stopped part-way. No saved original exists for it, so it cannot be put back automatically." 'WARN'; return }
    $pushSession = {
        param($why)
        $batch = [ordered]@{ $Name = (New-TweakRestoreUndo $Name $Pre) }
        $script:UndoStack.Push($batch)
        $stored = $script:UndoStack.Peek()      # the stack keeps its own hashtable, so identity is taken from there
        $script:RecoveryBatches.Add($stored); $script:SessionBatchOf[$Name] = $stored
        $n = $batch.Count
        $c['BtnUndoLast'].IsEnabled = $true; $c['BtnUndoLast'].Content = "Undo Last Batch ($n change$(if($n -ne 1){'s'}))"
        $script:PartialNotes[$Name] = 'session'
        Write-SR "$Label stopped part-way. $why" 'WARN'
    }
    $store = Read-UndoStore
    $readOk = -not $script:UndoReadFailed
    if ($script:PreHistorical.ContainsKey($Name)) {
        if ($readOk -and $store.ContainsKey($Name) -and (Test-RecordUsable $Name $store[$Name])) {
            $script:PartialNotes[$Name] = 'saved'
            Write-SR "$Label stopped part-way. The original saved earlier is kept so Undo can still put it back." 'WARN'
        } else { & $pushSession 'The saved records could not be read, so the original from before is kept only until you close StreamReady. Use Undo Last Batch.' }
        return
    }
    try {
        Restore-TweakState $Pre
        $script:PartialNotes[$Name] = 'rolled'
        Write-SR "$Label stopped part-way. Your original setting was put back." 'OK'
    } catch {
        $saved = $false
        try { $saved = ((Save-UndoRecord $Name $Pre) -eq $true) } catch {}
        if ($saved) {
            try { Save-AppliedTweakState -Names @($Name) } catch {}
            $script:PartialNotes[$Name] = 'saved'
            Write-SR "$Label stopped part-way and could not be put back automatically. The original is saved so you can Undo it from History." 'WARN'
        } else { & $pushSession 'The original could not be saved to disk, so it is kept only until you close StreamReady. Use Undo Last Batch.' }
    }
}
# 'pending' | 'resolved' | 'unknown' | 'unavailable'
function Get-RecoveryState {
    param([string]$Name, [string]$Kind)
    if ($Kind -eq 'session') {
        $b = $script:SessionBatchOf[$Name]
        if ($b) { foreach ($x in $script:UndoStack.ToArray()) { if ([object]::ReferenceEquals($x, $b)) { return 'pending' } } }
        if ($script:RecoveryConfirmed.ContainsKey($Name)) { return 'resolved' }
        return 'unavailable'
    }
    if ($Kind -eq 'saved') {
        $s = Read-UndoStore
        if ($script:UndoReadFailed) { return 'unknown' }
        if ($s.ContainsKey($Name) -and (Test-RecordUsable $Name $s[$Name])) { return 'pending' }
        if ($script:RecoveryConfirmed.ContainsKey($Name)) { return 'resolved' }
        return 'unavailable'
    }
    return 'unavailable'
}
function Get-PartialRowNote {
    param($E, [string]$Id)
    $pn = if ($E.Partial) { $E.Partial[$Id] } else { $null }
    switch ($pn) {
        'rolled'     { return 'Stopped part-way. Your original setting was put back.' }
        'notapplied' { if ($script:PartialDetail -and $script:PartialDetail[$Id]) { return [string]$script:PartialDetail[$Id] }; return 'Not applied: StreamReady could not read the current value exactly, so it changed nothing.' }
        'none'       { return 'Stopped part-way. No saved original exists for this setting, so it cannot be put back automatically. Check it by hand.' }
        { $_ -in @('saved','session') } {
            switch (Get-RecoveryState $Id $pn) {
                'pending'     { return $(if ($pn -eq 'session') { 'Stopped part-way. The original is kept only until you close StreamReady. Use Undo Last Batch.' } else { 'Stopped part-way. The original is saved so you can Undo it from History.' }) }
                'resolved'    { return 'Stopped part-way. The saved original has since been put back.' }
                'unknown'     { return 'Stopped part-way. The saved records cannot be read right now, so the state of the recovery is unknown.' }
                default       { return 'Stopped part-way. The saved original is no longer available. Check this setting by hand.' }
            }
        }
        default { return 'This change failed. Open Log for the error.' }
    }
}
function Get-HistorySubtitle {
    param($E)
    $pairs = @(); if ($E.Partial) { $pairs = @($E.Partial.GetEnumerator()) }
    $states = @($pairs | Where-Object { $_.Value -in @('session','saved') } | ForEach-Object { Get-RecoveryState $_.Key $_.Value })
    $none = @($pairs | Where-Object { $_.Value -eq 'none' }).Count
    $rolled = @($pairs | Where-Object { $_.Value -eq 'rolled' }).Count
    if ($states -contains 'pending') { return $(if (@($pairs | Where-Object { $_.Value -eq 'session' }).Count -gt 0) { 'This attempt stopped part-way. The original is kept only until you close StreamReady. Use Undo Last Batch now.' } else { 'This attempt stopped part-way. A saved original is available in the list below.' }) }
    if ($states -contains 'unknown') { return 'This attempt stopped part-way. The saved records cannot be read right now, so the state of the recovery is unknown.' }
    if ($states -contains 'unavailable') { return 'This attempt stopped part-way and the saved original is no longer available. Check the setting by hand.' }
    if ($none -gt 0) { return 'This attempt stopped part-way. Some changes may remain and there is no automatic undo. Use your restore point if you need to go back.' }
    if ($states -contains 'resolved') { return 'This attempt stopped part-way. The saved original has since been put back.' }
    if (@($pairs | Where-Object { $_.Value -eq 'notapplied' }).Count -gt 0 -and $E.Done.Count -eq 0) { return 'Nothing was applied: the current value could not be read exactly, so nothing was changed.' }
    if ($E.Aborted) { return 'This attempt did not finish. Check whether changes remain.' }
    if ($rolled -gt 0 -and $E.Done.Count -eq 0) { return 'This attempt stopped part-way and the original was put back.' }
    if ($E.Done.Count -eq 0) { return 'Nothing was applied by this attempt.' }
    return 'Undone or no longer reversible.'
}
#endregion v7 Round 6
#region UndoEngine generated BEGIN (do not edit here: edit undo-engine\ and run Build-UndoEngine.ps1)
$script:UndoEdition = 'Free'      # free edition: its own store folder, no paid only specs
# ---- core.ps1 ----
# StreamReady undo engine: core (record envelope, provider registry, capture/restore orchestration, persistence, validator).
# Plain function definitions and variable assignments only. Dot-source safe, no side effects at load time (the only
# assignments are empty tables created if they do not exist yet). ASCII only.
#
# Public functions (all global, none of them throws):
#   Undo-Engine-InitSpecs                       build v2 specs for the legacy registry tweaks ($script:UndoSpecs)
#   Undo-Engine-HasSpec <id>                    does a tweak or tool have a v2 spec
#   Undo-Engine-Begin -Id <name> -Kind tweak|tool [-BatchId <guid>]
#                                               capture ALL items, Prepare, validate and save the record BEFORE Apply.
#                                               Returns @{ ok; none; notApplicable; reused; record; error; failedWhat }.
#                                               An id with no spec is refused (ok=$false); a spec that declares no items is an explicit
#                                               "nothing to record" (none=$true).
#   Undo-Engine-Finish -Record <rec> [-Reused]  after Apply: nothing changed -> record removed (outcome 'unchanged'); otherwise PostApply
#                                               hooks, then status 'applied' saved. Returns @{ outcome; persisted }.
#   Undo-Engine-MarkApplied / Undo-Engine-IfUnchanged   (kept for callers that need the two halves)
#   Undo-Engine-ApplyFailed -Record <rec> -Reason <text>   Apply threw part-way: restore from the record now.
#   Undo-Engine-Restore -Id <recordId> | -Record <rec> [-WithNewer]
#                                               reverse item order, Verify before and after, per item result. A newer pending record that
#                                               touches the same resource blocks the restore (blockedBy) unless -WithNewer restores those first.
#                                               A result with needsUser=$true means manual steps remain; the record is KEPT (status 'manual').
#   Undo-Engine-Acknowledge -Id <recordId>      the user did the manual steps: remove a 'manual' record.
#   Undo-Engine-List [-TweakId <name>]          pending records (not restored, not used up)
#   Undo-Engine-Describe / IrreversibleText / ToolRun / ImportLegacy / FrozenAdapters / Store-Recover
# Helpers providers may use: Undo-Now, Undo-Hash-File, Undo-Files-Dir, Undo-Log, ConvertTo-UndoPlain, Undo-Result.

if (-not $script:UndoProviders)   { $script:UndoProviders   = @{} }
if (-not $script:UndoTweakSpecs)  { $script:UndoTweakSpecs  = @{} }
if (-not $script:UndoToolSpecs)   { $script:UndoToolSpecs   = @{} }
if (-not $script:UndoUsedMem)     { $script:UndoUsedMem     = @{} }
if (-not $script:UndoFrozen)      { $script:UndoFrozen      = @{} }
if (-not $script:UndoPlans)       { $script:UndoPlans       = @{} }
# providers whose read-only Capture is also a safety check at ACTION time: it is run again, with the saved params, when an existing
# original is reused (a second Apply). A failing capture (for example "the helper is running") stops the Apply. A provider can also
# put GuardOnReuse = $true in its registration.
if (-not $script:UndoGuardOnReuse) { $script:UndoGuardOnReuse = @('ScheduledTask') }
$script:UndoSchema = 2
$script:UndoStoreReadFailed = $false
$script:UndoLastError = $null
$script:UndoSeqLast = [int64]0
if (-not $script:UndoRestoredNow)   { $script:UndoRestoredNow   = @{} }    # record id -> tweak id: restored by a cascade this session
if (-not $script:UndoRestoredNames) { $script:UndoRestoredNames = @{} }    # tweak id -> $true
$script:UndoMySid = $null

# ---- small helpers -----------------------------------------------------------------------------------------------------
function Undo-Now { return ([datetime]::UtcNow.ToString('o')) }
function Undo-NewId { return ([guid]::NewGuid().ToString()) }
function Undo-Log {
    param([string]$Message, [string]$Level = 'INFO')
    try {
        if (Get-Command Write-SR -ErrorAction SilentlyContinue) { Write-SR $Message $Level }
        else { Write-Verbose "[$Level] $Message" }
    } catch {}
}
function Undo-Result {
    param([bool]$Ok, [string]$Message = '', [bool]$Partial = $false, $Details = @())
    return @{ ok = $Ok; partial = $Partial; message = $Message; details = @($Details) }
}
function ConvertTo-UndoPlain {
    param($O)
    if ($null -eq $O) { return $null }
    if ($O -is [string] -or $O -is [bool] -or $O -is [decimal] -or $O.GetType().IsPrimitive) { return $O }
    if ($O -is [datetime]) { return $O.ToString('o') }
    if ($O -is [System.Collections.IDictionary]) {
        $h = @{}
        foreach ($k in @($O.Keys)) { $h[[string]$k] = ConvertTo-UndoPlain $O[$k] }
        return $h
    }
    if ($O -is [System.Management.Automation.PSCustomObject]) {
        $h = @{}
        foreach ($p in $O.PSObject.Properties) { $h[$p.Name] = ConvertTo-UndoPlain $p.Value }
        return $h
    }
    if ($O -is [System.Collections.IEnumerable]) {
        $l = New-Object System.Collections.ArrayList
        foreach ($x in $O) { [void]$l.Add((ConvertTo-UndoPlain $x)) }
        return , ($l.ToArray())
    }
    return [string]$O
}
function Undo-Hash-File {
    param([string]$Path)
    try { return ((Get-FileHash -LiteralPath $Path -Algorithm SHA256 -ErrorAction Stop).Hash) } catch { return $null }
}
function Undo-ParamsKey {
    # normalised text of a params table, used to compare a saved record with its spec (keys starting with _ are ignored)
    param($P)
    $h = ConvertTo-UndoPlain $P
    if ($null -eq $h -or $h -isnot [hashtable]) { return '' }
    $parts = foreach ($k in @($h.Keys | Where-Object { -not ([string]$_).StartsWith('_') } | Sort-Object)) {
        $v = $h[$k]
        if ($v -is [array]) { $v = ($v | ForEach-Object { [string]$_ }) -join ',' }
        "$k=$v"
    }
    return ($parts -join ';')
}
function Undo-Canon {
    # canonical text of any plain value (sorted keys). Used to prove that a saved record reads back identical.
    param($O)
    if ($null -eq $O) { return '~' }
    if ($O -is [string]) { return ('s:' + $O) }
    if ($O -is [bool]) { return ('b:' + [string]$O) }
    if ($O.GetType().IsPrimitive -or $O -is [decimal]) { return ('n:' + ([string]$O)) }
    if ($O -is [System.Collections.IDictionary]) { return ('{' + ((@($O.Keys | Sort-Object) | ForEach-Object { "$_=" + (Undo-Canon $O[$_]) }) -join ',') + '}') }
    if ($O -is [System.Management.Automation.PSCustomObject]) { return ('{' + ((@($O.PSObject.Properties | Sort-Object Name) | ForEach-Object { "$($_.Name)=" + (Undo-Canon $_.Value) }) -join ',') + '}') }
    if ($O -is [System.Collections.IEnumerable]) { return ('[' + ((@($O) | ForEach-Object { Undo-Canon $_ }) -join ',') + ']') }
    return ('o:' + [string]$O)
}
function Undo-Digest {
    param([string]$Text)
    $sha = [System.Security.Cryptography.SHA256]::Create()
    return ([BitConverter]::ToString($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes($Text))) -replace '-', '')
}

# ---- store location (ProgramData, folder locked down when Initialize-ProtectedDir exists) --------------------------------
function Undo-RootName {
    # the two editions never share a store: the free edition keeps its originals below ProgramData\StreamReady-OSS (the folder the free app already uses)
    if ($script:UndoEdition -eq 'Free') { return 'StreamReady-OSS' }
    return 'StreamReady'
}
function Undo-Dir {
    if ($script:UndoV2Dir) { return $script:UndoV2Dir }
    return (Join-Path (Join-Path $env:ProgramData (Undo-RootName)) 'undo')
}
function Undo-StoreFile { return (Join-Path (Undo-Dir) 'undo_records_v2.json') }
function Undo-UsedFile  { return (Join-Path (Undo-Dir) 'used_ids.txt') }
function Undo-FilesRoot {
    if ($script:UndoFilesRootOverride) { return $script:UndoFilesRootOverride }
    return (Join-Path (Join-Path $env:ProgramData (Undo-RootName)) 'undo-files')
}
function Undo-Dir-Untrusted {
    # $null when the folder is safe to keep originals in, otherwise the reason. Checked on EVERY use, not only when it is created:
    # no link on the path, and (production folders) nobody but SYSTEM, administrators and TrustedInstaller can write or own it.
    param([string]$Path)
    try {
        $cur = $Path
        while ($cur -and $cur.Length -gt 3 -and (Test-Path -LiteralPath $cur)) {
            $it = Get-Item -LiteralPath $cur -Force -ErrorAction Stop
            if ($it.Attributes -band [IO.FileAttributes]::ReparsePoint) { return "$cur is a link" }
            $parent = Split-Path -Parent $cur
            if (-not $parent -or $parent -eq $cur) { break }
            $cur = $parent
        }
        $checkAcl = (-not $script:UndoV2Dir -and -not $script:UndoFilesRootOverride) -or $script:UndoForceAclCheck
        if (-not $checkAcl) { return $null }
        $acl = Get-Acl -LiteralPath $Path -ErrorAction Stop
        $trusted = @('S-1-5-18', 'S-1-5-32-544', 'S-1-3-0', 'S-1-5-80-956008885-3418522649-1831038044-1853292631-2271478464')
        $ownerSid = $acl.GetOwner([System.Security.Principal.SecurityIdentifier]).Value
        if ($trusted -notcontains $ownerSid) { return "$Path is owned by another account" }
        $writeMask = [System.Security.AccessControl.FileSystemRights]::WriteData -bor [System.Security.AccessControl.FileSystemRights]::AppendData -bor [System.Security.AccessControl.FileSystemRights]::WriteAttributes -bor [System.Security.AccessControl.FileSystemRights]::WriteExtendedAttributes -bor [System.Security.AccessControl.FileSystemRights]::Delete -bor [System.Security.AccessControl.FileSystemRights]::DeleteSubdirectoriesAndFiles -bor [System.Security.AccessControl.FileSystemRights]::ChangePermissions -bor [System.Security.AccessControl.FileSystemRights]::TakeOwnership
        foreach ($rule in @($acl.GetAccessRules($true, $true, [System.Security.Principal.SecurityIdentifier]))) {
            if ($rule.AccessControlType -ne [System.Security.AccessControl.AccessControlType]::Allow) { continue }
            $sid = $rule.IdentityReference.Value
            if ($trusted -contains $sid) { continue }
            if (($rule.FileSystemRights -band $writeMask) -ne 0) { return "$Path can be written by $sid" }
        }
        return $null
    } catch { return "$Path could not be checked ($($_.Exception.Message))" }
}
function Undo-Store-Trust {
    # $null when the saved originals may be read and used, otherwise the plain reason. Run before ANY record, marker or reuse is
    # consumed (read, reuse, restore), not only before a write: the folder, its StreamReady parent (production), and the store and
    # marker files themselves (no link, nobody untrusted can write or own them).
    try {
        $d = Undo-Dir
        if (-not (Test-Path -LiteralPath $d)) { return $null }
        $why = Undo-Dir-Untrusted $d
        if ($why) { return $why }
        $prod = (-not $script:UndoV2Dir) -and (-not $script:UndoFilesRootOverride)
        if ($prod -or $script:UndoForceParentCheck) {
            $par = Split-Path -Parent $d
            if ($par -and (Test-Path -LiteralPath $par)) { $why = Undo-Dir-Untrusted $par; if ($why) { return $why } }
        }
        foreach ($f in @((Undo-StoreFile), (Undo-UsedFile))) {
            if (Test-Path -LiteralPath $f) { $why = Undo-Dir-Untrusted $f; if ($why) { return $why } }
        }
        return $null
    } catch { return "the folder could not be checked ($($_.Exception.Message))" }
}
function Undo-EnsureDir {
    param([string]$Path)
    try {
        if (-not (Test-Path -LiteralPath $Path)) {
            $prod = (-not $script:UndoV2Dir) -and (-not $script:UndoFilesRootOverride)
            if ($prod -and (Get-Command Initialize-ProtectedDir -ErrorAction SilentlyContinue)) {
                $root = Join-Path $env:ProgramData (Undo-RootName)
                # also when the folder already exists (made by an older build with ordinary permissions): the app's own routine either
                # accepts it as locked down or, when it holds no saved originals, re-creates it locked down; one that holds originals is
                # never cleared and stays untrusted (the user is told)
                if (-not (Initialize-ProtectedDir $root)) { throw "the protected folder $root could not be created or locked down" }
            }
            New-Item -ItemType Directory -Path $Path -Force -ErrorAction Stop | Out-Null
        }
        $why = Undo-Dir-Untrusted $Path
        if ($why) { $script:UndoLastError = "The folder for saved originals is not safe to use: $why"; return $false }
        return $true
    } catch { $script:UndoLastError = $_.Exception.Message; return $false }
}
function Undo-Files-Dir {
    # folder for the file backups of one record; created on demand; never reused for another record (rule 5)
    param([string]$RecordId)
    $d = Join-Path (Undo-FilesRoot) $RecordId
    if (Undo-EnsureDir (Undo-FilesRoot)) { [void](Undo-EnsureDir $d) }
    return $d
}

# ---- used-up ids (a record that was restored but could not be removed from disk is never offered again) -------------------
function Undo-Used-Test {
    param([string]$Id)
    if ($script:UndoUsedMem.ContainsKey($Id)) { return $true }
    try {
        $f = Undo-UsedFile
        if (Test-Path -LiteralPath $f) {
            $lines = @(Get-Content -LiteralPath $f -ErrorAction Stop)
            if ($lines -contains $Id) { return $true }
        }
        return $false
    } catch { return $true }   # unreadable marker file: do not trust the record
}
function Undo-Used-Add {
    param([string]$Id)
    $script:UndoUsedMem[$Id] = $true
    try { if (Undo-EnsureDir (Undo-Dir)) { Add-Content -LiteralPath (Undo-UsedFile) -Value $Id -Encoding ASCII -ErrorAction Stop; return $true } } catch {}
    return $false
}

# ---- store lock: every read-modify-write of the record file runs under one named mutex (two windows cannot lose a record) ---
function Undo-Store-Locked {
    # runs $Body under the store lock and returns what it returns; returns $false (and sets UndoLastError) when the lock is not obtained
    param([scriptblock]$Body)
    $m = $null; $owned = $false
    try {
        $name = 'SRUndoStore-' + (Undo-Digest ((Undo-StoreFile).ToLowerInvariant())).Substring(0, 24)
        try { $m = New-Object System.Threading.Mutex($false, "Global\$name") } catch { $m = New-Object System.Threading.Mutex($false, "Local\$name") }
        $waitMs = 15000; if ($script:UndoLockWaitMs) { $waitMs = [int]$script:UndoLockWaitMs }
        try { $owned = $m.WaitOne($waitMs) } catch [System.Threading.AbandonedMutexException] { $owned = $true }
        if (-not $owned) { $script:UndoLastError = 'another StreamReady window is saving undo records; try again in a moment'; return $false }
        return (& $Body)
    } catch { $script:UndoLastError = $_.Exception.Message; return $false }
    finally { if ($m) { try { if ($owned) { $m.ReleaseMutex() } } catch {}; try { $m.Dispose() } catch {} } }
}

# ---- store read/write (read errors are not "empty", writes are verified, same rules as the schema 1 store) ----------------
function Undo-Store-Read {
    # returns @{ ok; state = 'absent'|'ok'|'damaged'|'unreadable'; records = @{ id = plain record }; error }
    # A store that exists but is blank, is not JSON, or has no records table is DAMAGED, never an empty baseline: Apply is blocked
    # until the user starts a new list on purpose (Undo-Store-Recover), and the damaged file is always kept.
    $script:UndoStoreReadFailed = $false
    $f = Undo-StoreFile
    $recs = @{}
    $trustWhy = Undo-Store-Trust
    if ($trustWhy) {
        $script:UndoStoreReadFailed = $true
        return @{ ok = $false; state = 'untrusted'; records = $recs; error = "The folder for saved originals is not safe to use ($trustWhy), so StreamReady will not read or use what is in it. Nothing was changed." }
    }
    if (-not (Test-Path -LiteralPath $f)) { return @{ ok = $true; state = 'absent'; records = $recs; error = $null } }
    $raw = $null
    try { $raw = Get-Content -LiteralPath $f -Raw -ErrorAction Stop }
    catch {
        $script:UndoStoreReadFailed = $true
        return @{ ok = $false; state = 'unreadable'; records = $recs; error = "Could not read the saved undo records: $($_.Exception.Message)" }
    }
    if (-not $raw -or -not $raw.Trim()) {
        $script:UndoStoreReadFailed = $true
        return @{ ok = $false; state = 'damaged'; records = $recs; error = 'The saved undo records file is empty, so StreamReady cannot tell what the original settings were. It was kept untouched. Open History and choose "Start a new undo list" if you accept that.' }
    }
    try {
        $j = $raw | ConvertFrom-Json -ErrorAction Stop
        $plain = ConvertTo-UndoPlain $j
        if (-not ($plain -is [hashtable] -and $plain.ContainsKey('records') -and $plain['records'] -is [hashtable])) { throw 'the file has no records table' }
        foreach ($k in @($plain['records'].Keys)) { if (-not (Undo-Used-Test $k)) { $recs[$k] = $plain['records'][$k] } }
        return @{ ok = $true; state = 'ok'; records = $recs; error = $null }
    } catch {
        $script:UndoStoreReadFailed = $true
        $keep = "$f.damaged-$([datetime]::Now.ToString('yyyyMMdd-HHmmss'))"
        $copied = $false
        try { Copy-Item -LiteralPath $f -Destination $keep -ErrorAction Stop; $copied = (Test-Path -LiteralPath $keep) } catch {}
        return @{ ok = $false; state = 'damaged'; records = @{}; error = "The saved undo records are damaged ($($_.Exception.Message)), so StreamReady cannot tell what the original settings were.$(if ($copied) { " A copy was kept at $keep." } else { '' }) Nothing was changed. Open History and choose ""Start a new undo list"" if you accept that." }
    }
}
function Undo-Store-Recover {
    # explicit user decision: set a damaged or unreadable store file aside (never deleted) so a new list can start
    try {
        $f = Undo-StoreFile
        if (-not (Test-Path -LiteralPath $f)) { return @{ ok = $true; message = 'There was nothing to set aside.'; kept = $null } }
        $r = Undo-Store-Read
        if ($r.ok) { return @{ ok = $false; message = 'The saved undo records are fine, so nothing was set aside.'; kept = $null } }
        $keep = "$f.set-aside-$([datetime]::Now.ToString('yyyyMMdd-HHmmss'))"
        Move-Item -LiteralPath $f -Destination $keep -ErrorAction Stop
        $script:UndoStoreReadFailed = $false
        return @{ ok = $true; message = "The old file was kept as $keep. A new undo list starts now."; kept = $keep }
    } catch { return @{ ok = $false; message = "Could not set the file aside: $($_.Exception.Message)"; kept = $null } }
}
function Undo-Store-Write {
    # records = hashtable id -> record. temp file, read back, compare every record with its saved copy, then move.
    param([hashtable]$Records)
    $f = Undo-StoreFile
    $tmp = "$f.$PID.tmp"
    try {
        if (-not (Undo-EnsureDir (Undo-Dir))) { throw $(if ($script:UndoLastError) { $script:UndoLastError } else { "could not create $(Undo-Dir)" }) }
        $doc = @{ schema = $script:UndoSchema; savedAt = (Undo-Now); records = $Records }
        $json = $doc | ConvertTo-Json -Depth 60
        Set-Content -LiteralPath $tmp -Value $json -Encoding UTF8 -ErrorAction Stop
        $back = ConvertTo-UndoPlain (Get-Content -LiteralPath $tmp -Raw -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop)
        if ($back -isnot [hashtable] -or $back['records'] -isnot [hashtable]) { throw 'the saved file has no records table' }
        $want = @($Records.Keys | Sort-Object); $got = @($back['records'].Keys | Sort-Object)
        if (($want -join '|') -ne ($got -join '|')) { throw 'the saved file did not contain the expected records' }
        foreach ($k in $want) {
            # a record must come back exactly as it went in (deep trees used to be cut off silently by the serializer depth)
            if ((Undo-Digest (Undo-Canon (ConvertTo-UndoPlain $Records[$k]))) -ne (Undo-Digest (Undo-Canon $back['records'][$k]))) { throw "record $k did not read back identical (too deeply nested or not JSON safe)" }
        }
        Move-Item -LiteralPath $tmp -Destination $f -Force -ErrorAction Stop
        return $true
    } catch {
        $script:UndoLastError = $_.Exception.Message
        Undo-Log "Could not save the undo records: $($_.Exception.Message)" 'WARN'
        try { if (Test-Path -LiteralPath $tmp) { Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue } } catch {}
        return $false
    }
}
function Undo-Store-Put {
    param($Record)
    $rec = $Record
    return [bool](Undo-Store-Locked {
        $r = Undo-Store-Read
        if (-not $r.ok) { $script:UndoLastError = $r.error; return $false }
        $r.records[[string]$rec['id']] = $rec
        return (Undo-Store-Write $r.records)
    })
}
function Undo-Store-Remove {
    param([string]$Id)
    $rid = $Id
    $ok = [bool](Undo-Store-Locked {
        $r = Undo-Store-Read
        if (-not $r.ok) { return $false }
        if (-not $r.records.ContainsKey($rid)) { return $true }
        $r.records.Remove($rid)
        return (Undo-Store-Write $r.records)
    })
    if (-not $ok) { [void](Undo-Used-Add $Id) }
    return $ok
}

# ---- specs ----------------------------------------------------------------------------------------------------------------
function Undo-Spec-Get {
    param([string]$Id)
    if ($script:UndoTweakSpecs.ContainsKey($Id)) { return $script:UndoTweakSpecs[$Id] }
    if ($script:UndoToolSpecs.ContainsKey($Id))  { return $script:UndoToolSpecs[$Id] }
    return $null
}
function Undo-Engine-HasSpec { param([string]$Id) return ($null -ne (Undo-Spec-Get $Id)) }
function Undo-Engine-InitSpecs {
    # turns the legacy registry table ($script:UndoSpecs: 'Name' = @('HKLM:\key|Value[|Token]', ...)) into v2 specs so the
    # 67 existing registry tweaks use the same record type. Idempotent. Does not touch the legacy table.
    try {
        if (-not $script:UndoSpecs) { return 0 }
        $n = 0
        foreach ($name in @($script:UndoSpecs.Keys)) {
            if ($script:UndoTweakSpecs.ContainsKey($name)) { continue }
            $items = @()
            foreach ($row in @($script:UndoSpecs[$name])) {
                $p = ([string]$row).Split('|')
                $params = @{ Key = $p[0]; Name = $p[1] }
                if ($p.Count -gt 2 -and $p[2]) { $params['Token'] = $p[2] }
                $items += , @{ Type = 'Registry'; Params = $params }
            }
            $script:UndoTweakSpecs[$name] = @{ Items = $items; Irreversible = @(); Legacy = $true }
            $n++
        }
        return $n
    } catch { return 0 }
}
function Undo-Spec-Expand {
    # evaluates scriptblocks in a spec item and returns a list of plain params tables (one per instance). Never throws;
    # returns @{ ok; list; error }
    param($SpecItem)
    $out = New-Object System.Collections.ArrayList
    try {
        $p = $SpecItem.Params
        if ($p -is [scriptblock]) {
            foreach ($one in @(& $p)) { if ($null -ne $one) { [void]$out.Add((ConvertTo-UndoPlain $one)) } }
            return @{ ok = $true; list = @($out.ToArray()); error = $null }
        }
        $h = @{}
        foreach ($k in @($p.Keys)) {
            $v = $p[$k]
            if ($v -is [scriptblock]) { $v = @(& $v); if ($v.Count -eq 1) { $v = $v[0] } }
            $h[[string]$k] = ConvertTo-UndoPlain $v
        }
        [void]$out.Add($h)
        return @{ ok = $true; list = @($out.ToArray()); error = $null }
    } catch {
        return @{ ok = $false; list = @(); error = "could not work out what to record: $($_.Exception.Message)" }
    }
}
function Undo-Spec-IsStatic {
    param($SpecItem)
    if ($SpecItem.Params -is [scriptblock]) { return $false }
    foreach ($k in @($SpecItem.Params.Keys)) { if ($SpecItem.Params[$k] -is [scriptblock]) { return $false } }
    return $true
}

# ---- provider calls (defensive: a provider must not throw, but nothing here relies on that) ---------------------------------
function Undo-Provider-Get {
    param([string]$Type)
    if ($script:UndoProviders.ContainsKey($Type)) { return $script:UndoProviders[$Type] }
    return $null
}
function Undo-Provider-Call {
    param([string]$Type, [string]$Fn, $Arg, [string]$ArgName)
    $prov = Undo-Provider-Get $Type
    if (-not $prov -or -not $prov[$Fn]) { return $null }
    $cmd = [string]$prov[$Fn]
    if (-not (Get-Command $cmd -ErrorAction SilentlyContinue)) { return $null }
    try {
        if ($ArgName -eq 'Params') { return (& $cmd -Params $Arg) }
        return (& $cmd -Item $Arg)
    } catch {
        return @{ _threw = $true; ok = $false; error = $_.Exception.Message; message = $_.Exception.Message; matches = $false; valid = $false; reason = $_.Exception.Message; diff = $_.Exception.Message }
    }
}

# ---- resources: what a record touches, so two records that touch the same thing are undone in reverse order ----------------
function Undo-Sid-Valid {
    # $true for any well formed account SID (S-1-5-21 local, Microsoft and domain accounts, S-1-12-1 Entra ID accounts, S-1-5-18 and so on).
    # Never a prefix test: the shape is checked and then the system's own SID parser must accept it.
    param([string]$Sid)
    if ([string]::IsNullOrWhiteSpace($Sid) -or $Sid -notmatch '^S-1-[0-9]{1,10}(-[0-9]{1,10}){1,15}$') { return $false }
    try { $o = New-Object System.Security.Principal.SecurityIdentifier($Sid); return ($o.Value -eq $Sid) } catch { return $false }
}
function Undo-My-Sid-Ok { return (Undo-Sid-Valid (Undo-My-Sid)) }
function Undo-My-Sid {
    if (-not $script:UndoMySid) { try { $script:UndoMySid = [string][System.Security.Principal.WindowsIdentity]::GetCurrent().User.Value } catch { $script:UndoMySid = 'none' } }
    return $script:UndoMySid
}
function Undo-Reg-Canon {
    # one spelling for a registry location: hive long names and Registry:: forms, trailing backslash, case. HKCU is written as
    # HKU\<SID of the account that owns the item> (the item's recorded SID, else the signed-in account), so two accounts never overlap
    param([string]$Key, [string]$Sid = '')
    $k = ([string]$Key).Trim().Replace('/', '\')
    $k = $k -replace '(?i)^microsoft\.powershell\.core\\', ''
    $k = $k -replace '(?i)^registry::', ''
    $k = $k -replace '(?i)^hkey_local_machine', 'HKLM:' -replace '(?i)^hkey_current_user', 'HKCU:' -replace '(?i)^hkey_users', 'HKU:'
    $k = $k -replace '(?i)^(HKLM|HKCU|HKU|HKCR):?(?=\\|$)', '$1:'
    $k = $k.TrimEnd('\').ToLowerInvariant()
    if ($k -match '^hkcu:(\\.*)?$') { $rest = [string]$Matches[1]; $sx = $(if ($Sid) { $Sid } else { Undo-My-Sid }); $k = 'hku:\' + $sx.ToLowerInvariant() + $rest }
    return $k
}
function Undo-Item-Resources {
    param($It)
    $t = [string]$It['type']; $p = $It['params']; $out = @()
    try {
        switch ($t) {
            'Registry'      { $us = ''; try { $us = [string]$It['state']['userSid'] } catch {}; $out += ("reg|$(Undo-Reg-Canon $p['Key'] $us)|$($p['Name'])").ToLowerInvariant() }
            'RegistryTree'  { $us = ''; try { $us = [string]$It['state']['userSid'] } catch {}; $out += ("regtree|$(Undo-Reg-Canon $p['Key'] $us)").ToLowerInvariant() }
            'Service'       { $out += ("svc|$($p['Name'])").ToLowerInvariant(); $out += ("reg|$(Undo-Reg-Canon ('HKLM:\SYSTEM\CurrentControlSet\Services\' + [string]$p['Name']))|start").ToLowerInvariant() }
            'ScheduledTask' { $out += ("task|$($p['Name'])").ToLowerInvariant() }
            'NetAdapterDns' { $out += 'dns|all' }
            'PowerScheme'   { $out += 'power|scheme' }
            'PageFile'      { $out += 'pagefile' }
            'DisplayMode'   { $out += 'display' }
            'FirewallRule'  { $out += ("fw|$($p['Name'])").ToLowerInvariant() }
            'LsaSecret'     { $out += ("lsa|$($p['Name'])").ToLowerInvariant() }
            'Hibernation'   { $out += 'hibernate' }
            'MMAgent'       { $out += 'mmagent' }
            'PreferenceSet' { $out += 'defender|exclusions' }
            'NicAdvanced'   {
                $gs = @()
                foreach ($a in @($It['state']['adapters'])) { if ($a -is [hashtable] -and $a['guid']) { $gs += ([string]$a['guid']).Trim('{}').ToLowerInvariant() } }
                if ($gs.Count -eq 0) { $gs = @('*') }
                foreach ($g in $gs) {
                    if ([string]$p['Mode'] -in @('TcpPrimary', 'TcpAll') -and $g -ne '*') {
                        # the Nagle and the TCP game tweaks write the same interface values: one resource each, whatever the mode
                        foreach ($vn in @('TcpAckFrequency', 'TCPNoDelay', 'TcpDelAckTicks')) { $out += ("reg|$(Undo-Reg-Canon ('HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces\{' + $g + '}'))|$vn").ToLowerInvariant() }
                    } else { $out += "nic|$g|$([string]$p['Mode'])|$([string]$p['DisplayMatch'])" }
                }
            }
            'FileSnapshot'  {
                $ps = @($p['Paths']); if ($ps.Count -eq 0 -or -not $ps[0]) { $ps = @($p['Path']) }
                foreach ($x in $ps) { if ($x) { $out += ("file|$x").ToLowerInvariant() } }
            }
            'Bcd'           { $bid = [string]$p['Identifier']; try { if ($It['state']['resolvedId']) { $bid = [string]$It['state']['resolvedId'] } } catch {}; foreach ($e in @($p['Elements'])) { $out += ("bcd|$bid|$e").ToLowerInvariant() } }
            'WindowsFeature' { foreach ($n in @($It['state']['items'].Keys)) { $out += ("feature|$n").ToLowerInvariant() } }
            'WingetPackage' { foreach ($i in @($p['Ids'])) { if ($i) { $out += ("winget|$i").ToLowerInvariant() } } }
            'EnvVar'        { $out += ("env|$($p['Scope'])|$($p['Name'])").ToLowerInvariant() }
            'UserRegistry'  { $us = ''; try { $us = [string]$It['state']['userSid'] } catch {}; if (-not $us) { $us = Undo-My-Sid }; $out += ("reg|$(Undo-Reg-Canon ('HKU:\' + $us + '\' + [string]$p['SubPath']))|$($p['Name'])").ToLowerInvariant() }
            'GpuDriverProperty' { $out += ("gpuprop|$($p['Vendor'])|$($p['Name'])").ToLowerInvariant() }
            'DriverProfile' { $out += ("driverprofile|$($p['Scope'])").ToLowerInvariant() }
            'ApplicationRecovery' { $out += ("apprecovery|$($p['Product'])").ToLowerInvariant() }
            'RestorePointRef' { $out += 'restorepoint' }
            'RegistryGuard' { $out += ("regguard|$($p['Key'])|$($p['Name'])").ToLowerInvariant() }
            default         { $out += ("$t|$(Undo-ParamsKey $p)").ToLowerInvariant() }
        }
    } catch { $out += ("$t|$(Undo-ParamsKey $p)").ToLowerInvariant() }
    return @($out | Select-Object -Unique)
}
# every provider type that has its own resource key (a unit test checks that each registered type is in this list)
$script:UndoResourceTypes = @('Registry','RegistryTree','Service','ScheduledTask','NetAdapterDns','PowerScheme','PageFile','DisplayMode','FirewallRule','LsaSecret','Hibernation','MMAgent','PreferenceSet','NicAdvanced','FileSnapshot','Bcd','WindowsFeature','WingetPackage','EnvVar','UserRegistry','GpuDriverProperty','DriverProfile','ApplicationRecovery','RestorePointRef','RegistryGuard')
function Undo-Record-Resources {
    param($Rec)
    $all = @()
    foreach ($it in @($Rec['items'])) { $all += @(Undo-Item-Resources $it) }
    return @($all | Select-Object -Unique)
}
function Undo-Resources-Overlap {
    param([string[]]$A, [string[]]$B)
    foreach ($x in @($A)) {
        foreach ($y in @($B)) {
            if ($x -eq $y) { return $true }
            # a registry tree owns every value below it
            $xs = $x.Split('|'); $ys = $y.Split('|')
            if ($xs[0] -eq 'regtree' -and ($ys[0] -eq 'reg' -or $ys[0] -eq 'regtree')) { if ($ys[1] -eq $xs[1] -or $ys[1].StartsWith($xs[1] + '\')) { return $true } }
            if ($ys[0] -eq 'regtree' -and ($xs[0] -eq 'reg' -or $xs[0] -eq 'regtree')) { if ($xs[1] -eq $ys[1] -or $xs[1].StartsWith($ys[1] + '\')) { return $true } }
        }
    }
    return $false
}
function Undo-Next-Seq {
    $t = [int64][datetime]::UtcNow.Ticks
    if ($t -le $script:UndoSeqLast) { $t = $script:UndoSeqLast + 1 }
    $script:UndoSeqLast = $t
    return $t
}
function Undo-Engine-Blockers {
    # pending records that are NEWER than this one and touch the same resource: they must be undone first
    param($Record)
    $out = @()
    try {
        $st = Undo-Store-Read
        if (-not $st.ok) { return @() }
        $mine = @(Undo-Record-Resources $Record)
        $seq = [int64]0; try { $seq = [int64]$Record['seq'] } catch {}
        foreach ($o in @($st.records.Values)) {
            if ([string]$o['id'] -eq [string]$Record['id'] -or $o['status'] -eq 'restored') { continue }
            # a 'manual' record has had everything restored that can be; what is left is the user's own steps, so it never blocks an older record
            if ($o['status'] -eq 'manual') { continue }
            $os = [int64]0; try { $os = [int64]$o['seq'] } catch {}
            if ($os -le $seq) { continue }
            $theirs = @(Undo-Record-Resources $o)
            if (Undo-Resources-Overlap $mine $theirs) { $out += , $o }
        }
    } catch {}
    return @($out | Sort-Object { [int64]$_['seq'] } -Descending)
}

# ---- capture ------------------------------------------------------------------------------------------------------------
function Undo-Capture-Items {
    # captures every item of a spec. returns @{ ok; items; error; failedWhat }
    param([string]$Id, $Spec, [string]$RecordId)
    $items = New-Object System.Collections.ArrayList
    $idx = 0
    foreach ($si in @($Spec.Items)) {
        $type = [string]$si.Type
        $prov = Undo-Provider-Get $type
        if (-not $prov) { return @{ ok = $false; items = @(); error = "no provider for $type"; failedWhat = $type } }
        $exp = Undo-Spec-Expand $si
        if (-not $exp.ok) { return @{ ok = $false; items = @(); error = $exp.error; failedWhat = $type } }
        foreach ($params in @($exp.list)) {
            $idx++
            $pp = @{}
            foreach ($k in @($params.Keys)) { $pp[$k] = $params[$k] }
            $pp['_recordId'] = $RecordId
            $pp['_index'] = $idx
            $pp['_filesDir'] = (Join-Path (Undo-FilesRoot) $RecordId)
            $cap = Undo-Provider-Call $type 'Capture' $pp 'Params'
            if ($null -eq $cap) { return @{ ok = $false; items = @(); error = "the $type provider did not answer"; failedWhat = $type } }
            if (-not $cap.ok) {
                $what = if ($params.ContainsKey('Name')) { "$type $($params['Name'])" } elseif ($params.ContainsKey('Key')) { "$type $($params['Key'])" } else { $type }
                return @{ ok = $false; items = @(); error = [string]$cap.error; failedWhat = $what }
            }
            $item = ConvertTo-UndoPlain $cap
            $item['restored'] = $false
            $item['restoreMessage'] = $null
            if ($si.SkipWhenManual) { $item['skipWhenManual'] = $true }
            if ($si.SwitchOffWhenManual) { $item['switchOffWhenManual'] = $true }
            [void]$items.Add($item)
        }
    }
    return @{ ok = $true; items = @($items.ToArray()); error = $null; failedWhat = $null }
}

function Undo-Irreversible-Plain {
    param($Spec)
    $out = @()
    foreach ($x in @($Spec.Irreversible)) {
        if ($null -eq $x) { continue }
        $out += , @{ what = [string]$x.What; why = [string]$x.Why; bestRecovery = [string]$x.BestRecovery; warn = [bool]$x.Warn }
    }
    return $out
}
function Undo-Engine-IrreversibleText {
    param([string]$Id)
    try {
        $spec = Undo-Spec-Get $Id
        if (-not $spec) { return '' }
        $lines = @()
        foreach ($x in @($spec.Irreversible)) {
            if ($null -eq $x) { continue }
            $t = [string]$x.What
            if ($x.Why) { $t += ". $($x.Why)" }
            if ($x.BestRecovery) { $t += " $($x.BestRecovery)" }
            $lines += $t.Trim()
        }
        return ($lines -join ' ')
    } catch { return '' }
}

# ---- validation of a saved record ---------------------------------------------------------------------------------------
function Undo-Record-Validate {
    param($Rec)
    try {
        if ($null -eq $Rec -or $Rec -isnot [hashtable]) { return @{ valid = $false; reason = 'not a record' } }
        if ([int]$Rec['schema'] -ne $script:UndoSchema) { return @{ valid = $false; reason = 'unknown schema' } }
        if ([string]$Rec['id'] -notmatch '^[0-9a-fA-F-]{36}$') { return @{ valid = $false; reason = 'bad id' } }
        $tid = [string]$Rec['tweakId']
        if ($tid -notmatch '^[A-Za-z0-9_.-]{1,80}$') { return @{ valid = $false; reason = 'bad name' } }
        if ($Rec['status'] -notin @('captured', 'applied', 'restored', 'partial', 'failed', 'manual')) { return @{ valid = $false; reason = 'bad status' } }
        $spec = Undo-Spec-Get $tid
        if (-not $spec) { return @{ valid = $false; reason = "no spec for $tid" } }
        $items = @($Rec['items'])
        if ($items.Count -lt 1) { return @{ valid = $false; reason = 'the record holds no items' } }
        $staticKeys = @{}
        $dynTypes = @{}
        foreach ($si in @($spec.Items)) {
            if (Undo-Spec-IsStatic $si) {
                $pk = Undo-ParamsKey $si.Params
                $staticKeys["$($si.Type)|$pk"] = $true
            } else { $dynTypes[[string]$si.Type] = $true }
        }
        # every static spec item must be present
        $have = @{}
        foreach ($it in $items) { $have["$($it['type'])|$(Undo-ParamsKey $it['params'])"] = $true }
        foreach ($k in @($staticKeys.Keys)) { if (-not $have.ContainsKey($k)) { return @{ valid = $false; reason = 'a recorded item is missing' } } }
        # item count and types must equal what the SPEC says it records: every static item exactly once; a spec with only static
        # items must match in order and number (a record that dropped a part, or added one, is refused)
        $gotKeys = @($items | ForEach-Object { if ($_ -is [hashtable]) { "$($_['type'])|$(Undo-ParamsKey $_['params'])" } else { 'bad|item' } })
        foreach ($k in @($staticKeys.Keys)) { if (@($gotKeys | Where-Object { $_ -eq $k }).Count -ne 1) { return @{ valid = $false; reason = 'a part of the original is missing or repeated' } } }
        if ($dynTypes.Count -eq 0) {
            $wantKeys = @($spec.Items | ForEach-Object { "$($_.Type)|$(Undo-ParamsKey $_.Params)" })
            if (($wantKeys -join "`n") -ne ($gotKeys -join "`n")) { return @{ valid = $false; reason = 'the recorded parts are not the parts this change records' } }
        }
        if ($Rec.ContainsKey('manifest')) {
            # what was captured at the start (type and parameters of every instance): a dynamic record may not lose or gain an instance
            if ((@($Rec['manifest']) -join "`n") -ne ($gotKeys -join "`n")) { return @{ valid = $false; reason = 'the recorded parts differ from the list made when the original was saved' } }
        }
        foreach ($it in $items) {
            if ($it -isnot [hashtable]) { return @{ valid = $false; reason = 'bad item' } }
            $type = [string]$it['type']
            if (-not (Undo-Provider-Get $type)) { return @{ valid = $false; reason = "unknown provider $type" } }
            if ($it['params'] -isnot [hashtable]) { return @{ valid = $false; reason = 'bad item params' } }
            if ($null -eq $it['state']) { return @{ valid = $false; reason = 'item has no state' } }
            $key = "$type|$(Undo-ParamsKey $it['params'])"
            if (-not $staticKeys.ContainsKey($key) -and -not $dynTypes.ContainsKey($type)) { return @{ valid = $false; reason = "unexpected $type item" } }
            if (-not $staticKeys.ContainsKey($key)) {
                # a dynamic item must match one dynamic spec item of its type: same parameter names, the values the spec fixes
                # (non scriptblock values) unchanged, and the 'Allow' patterns for the rest
                $okDyn = $false
                foreach ($ds in @($spec.Items | Where-Object { [string]$_.Type -eq $type -and -not (Undo-Spec-IsStatic $_) })) {
                    $good = $true
                    if ($ds.Params -isnot [scriptblock]) {
                        $specKeys = @($ds.Params.Keys | ForEach-Object { [string]$_ })
                        foreach ($ik in @($it['params'].Keys)) { if (-not ([string]$ik).StartsWith('_') -and $specKeys -notcontains [string]$ik) { $good = $false; break } }
                        if ($good) {
                            foreach ($sk in $specKeys) {
                                $sv = $ds.Params[$sk]
                                if ($sv -is [scriptblock]) { continue }
                                $a = Undo-Canon (ConvertTo-UndoPlain $sv); $b = Undo-Canon $it['params'][$sk]
                                if ($a -ne $b) { $good = $false; break }
                            }
                        }
                    }
                    if ($good -and $ds.Allow) {
                        foreach ($an in @($ds.Allow.Keys)) {
                            $val = [string]$it['params'][$an]
                            if ($val -notmatch [string]$ds.Allow[$an]) { $good = $false; break }
                        }
                    }
                    if ($good) { $okDyn = $true; break }
                }
                if (-not $okDyn) { return @{ valid = $false; reason = "a $type item is outside what this tool may change" } }
            }
            $prov = Undo-Provider-Get $type
            if ($prov['Validate'] -and (Get-Command ([string]$prov['Validate']) -ErrorAction SilentlyContinue)) {
                $v = $null
                try { $v = & ([string]$prov['Validate']) -Item $it } catch { $v = @{ valid = $false; reason = $_.Exception.Message } }
                if ($v -and -not $v.valid) { return @{ valid = $false; reason = [string]$v.reason } }
            }
        }
        return @{ valid = $true; reason = $null }
    } catch { return @{ valid = $false; reason = $_.Exception.Message } }
}

# ---- begin / finish / failed ---------------------------------------------------------------------------------------------
function Undo-Record-ForeignUser {
    # $true when a saved original holds a user-hive item that belongs to a different Windows account than the signed-in one
    param($Rec)
    try {
        foreach ($it in @($Rec['items'])) {
            $s = $it['state']
            if ($s -is [hashtable] -and $s['userSid'] -and [string]$s['userSid'] -ne (Undo-My-Sid)) { return $true }      # any item type that records an account
        }
    } catch {}
    return $false
}
function Undo-Engine-Begin {
    param([Parameter(Mandatory)][string]$Id, [string]$Kind = 'tweak', [string]$BatchId = '')
    try {
        $spec = Undo-Spec-Get $Id
        if (-not $spec) {
            # no spec means no undo: fail closed. (A spec that declares no items is a reviewed "nothing to record" and is handled below.)
            return @{ ok = $false; none = $false; notApplicable = $false; reused = $false; record = $null; error = 'StreamReady has no undo specification for this item'; failedWhat = 'the undo specification' }
        }
        if (@($spec.Items).Count -eq 0) { return @{ ok = $true; none = $true; notApplicable = $false; reused = $false; record = $null; error = $null; failedWhat = $null } }
        $store = Undo-Store-Read
        if (-not $store.ok) {
            return @{ ok = $false; none = $false; notApplicable = $false; reused = $false; record = $null; error = $store.error; failedWhat = 'the saved undo records' }
        }
        # a tweak keeps ONE record that holds the true original; a second Apply reuses it. A tool click always gets its own record.
        if ($Kind -eq 'tweak') {
            $mine = @($store.records.Values | Where-Object { $_['tweakId'] -eq $Id -and $_['status'] -ne 'restored' -and -not (Undo-Record-ForeignUser $_) } | Sort-Object { $_['capturedAt'] })
            foreach ($old in $mine) {
                $val = Undo-Record-Validate $old
                if (-not $val.valid) {
                    # a record that fails the safety check is never used and never silently replaced: capturing now would record the
                    # already-changed settings as "the original". It stays untouched; this change is blocked until the user reviews it.
                    Undo-Log "A saved record for '$Id' did not pass the safety check ($($val.reason)) and was kept aside." 'WARN'
                    return @{ ok = $false; none = $false; notApplicable = $false; reused = $false; invalidSaved = $true; invalidId = [string]$old['id']; record = $null; error = "an earlier saved original for this change cannot be used by this version of StreamReady ($($val.reason)). It is kept untouched. Applying again would save today's already-changed settings as the original, so this change is blocked. Open History to review it."; failedWhat = 'an earlier saved original that cannot be used' }
                }
                if ($old['status'] -eq 'captured') {
                    # crashed between capture and Apply: if nothing differs it is harmless, capture a fresh one
                    $allSame = $true
                    foreach ($it in @($old['items'])) {
                        $v = Undo-Provider-Call ([string]$it['type']) 'Verify' $it 'Item'
                        if (-not $v -or -not $v.matches) { $allSame = $false; break }
                    }
                    if ($allSame) { [void](Undo-Store-Remove ([string]$old['id'])); continue }
                }
                # ownership evidence of what an earlier run CREATED (files) must not be overwritten by a second run: undo the first run first
                foreach ($it in @($old['items'])) {
                    if ($it['state'] -is [hashtable] -and $it['state'].ContainsKey('createdManifest') -and $null -ne $it['state']['createdManifest']) {
                        return @{ ok = $false; none = $false; notApplicable = $false; reused = $true; record = $null; error = 'this was already applied and the files it created are recorded; undo it first, then apply it again'; failedWhat = 'the earlier run (undo it first)' }
                    }
                }
                # action-time guard for reused originals (no recapture of the original, but the provider's own safety checks still run)
                foreach ($it in @($old['items'])) {
                    $ty = [string]$it['type']
                    $pv = Undo-Provider-Get $ty
                    if (($script:UndoGuardOnReuse -contains $ty) -or ($pv -and $pv['GuardOnReuse'])) {
                        $gp = @{}
                        foreach ($gk in @($it['params'].Keys)) { $gp[$gk] = $it['params'][$gk] }
                        $gc = Undo-Provider-Call $ty 'Capture' $gp 'Params'
                        if ($null -eq $gc -or -not $gc.ok) {
                            return @{ ok = $false; none = $false; notApplicable = $false; reused = $true; record = $null; error = $(if ($gc) { [string]$gc.error } else { "the $ty provider did not answer" }); failedWhat = "the current state of $ty (not safe to replace while it is in use)" }
                        }
                    }
                }
                # progress of an earlier, partly finished Undo must not survive a new Apply: reopen every item (the true first original
                # stays; "already back" is decided again at the next Undo by Verify) and save that BEFORE Apply
                $reopened = $false
                foreach ($it in @($old['items'])) {
                    if ($it['restored'] -eq $true -or $it['manual'] -eq $true -or $it['restoreMessage']) { $it['restored'] = $false; $it['manual'] = $false; $it['restoreMessage'] = $null; $reopened = $true }
                }
                if ($old['status'] -ne 'applied') { $old['status'] = 'applied'; $reopened = $true }
                if (-not $old['seq']) { $old['seq'] = (Undo-Next-Seq); $reopened = $true }
                if (-not $old['resources']) { $old['resources'] = @(Undo-Record-Resources $old); $reopened = $true }
                if ($reopened -and -not (Undo-Store-Put $old)) {
                    return @{ ok = $false; none = $false; notApplicable = $false; reused = $true; record = $null; error = "the saved original could not be updated on disk ($script:UndoLastError)"; failedWhat = 'the saved undo records' }
                }
                Undo-Freeze-Adapters $Id $old
                $script:UndoPlans[$Id] = $old
                return @{ ok = $true; none = $false; notApplicable = $false; reused = $true; record = $old; error = $null; failedWhat = $null }
            }
        }
        $rid = Undo-NewId
        if ($script:UndoRestoredNames.ContainsKey($Id)) { $script:UndoRestoredNames.Remove($Id) }
        $cap = Undo-Capture-Items -Id $Id -Spec $spec -RecordId $rid
        if (-not $cap.ok) {
            return @{ ok = $false; none = $false; notApplicable = $false; reused = $false; record = $null; error = $cap.error; failedWhat = $cap.failedWhat }
        }
        if (@($cap.items).Count -eq 0) {
            # the spec found nothing to change on this PC (no matching adapter, device or selection). Apply must NOT run.
            Undo-Freeze-Plan $Id @() $true
            return @{ ok = $false; none = $false; notApplicable = $true; reused = $false; record = $null; error = 'there is nothing to change on this PC for this item'; failedWhat = $null }
        }
        # providers with a Prepare hook (for example FileSnapshot: durable file backups) get one call after ALL captures and
        # before the record is committed. A failed Prepare stops the tweak exactly like a failed capture.
        foreach ($pi in @($cap.items)) {
            $pv = Undo-Provider-Get ([string]$pi['type'])
            if ($pv -and $pv['Prepare'] -and (Get-Command ([string]$pv['Prepare']) -ErrorAction SilentlyContinue)) {
                $pr = $null
                try { $pr = & ([string]$pv['Prepare']) $pi } catch { $pr = @{ ok = $false; message = $_.Exception.Message } }
                if ($pr -and -not $pr.ok) {
                    return @{ ok = $false; none = $false; notApplicable = $false; reused = $false; record = $null; error = [string]$pr.message; failedWhat = "the backup of $([string]$pi['type'])" }
                }
            }
        }
        $rec = @{
            schema = $script:UndoSchema; id = $rid; tweakId = $Id; kind = $Kind
            batchId = $(if ($BatchId) { $BatchId } else { Undo-NewId })
            capturedAt = (Undo-Now); seq = (Undo-Next-Seq); items = @($cap.items); status = 'captured'
            irreversible = @(Undo-Irreversible-Plain $spec)
        }
        $rec['resources'] = @(Undo-Record-Resources $rec)
        $rec['manifest'] = @(@($rec['items']) | ForEach-Object { "$($_['type'])|$(Undo-ParamsKey $_['params'])" })
        $val2 = Undo-Record-Validate $rec
        if (-not $val2.valid) {
            return @{ ok = $false; none = $false; notApplicable = $false; reused = $false; record = $null; error = "the recorded original did not pass the safety check ($($val2.reason))"; failedWhat = $Id }
        }
        if (-not (Undo-Store-Put $rec)) {
            return @{ ok = $false; none = $false; notApplicable = $false; reused = $false; record = $null; error = "the original could not be saved to disk ($script:UndoLastError)"; failedWhat = 'the saved undo records' }
        }
        Undo-Freeze-Adapters $Id $rec
        $script:UndoPlans[$Id] = $rec
        return @{ ok = $true; none = $false; notApplicable = $false; reused = $false; record = $rec; error = $null; failedWhat = $null }
    } catch {
        return @{ ok = $false; none = $false; notApplicable = $false; reused = $false; record = $null; error = $_.Exception.Message; failedWhat = $Id }
    }
}
# The adapters that were captured for a tweak or tool (InterfaceGuid list). The Apply code that acts on network adapters must use
# THIS plan instead of looking adapters up again, so it changes exactly the adapters that can be restored. The plan is "present"
# whenever the spec captures adapters, EVEN WHEN IT IS EMPTY (an empty plan means: change no adapter).
function Undo-Freeze-Plan {
    param([string]$Id, [string[]]$Guids, [bool]$Present)
    $script:UndoFrozen[$Id] = @{ present = $Present; guids = @($Guids | Where-Object { $_ } | Select-Object -Unique) }
}
function Undo-Freeze-Adapters {
    param([string]$Id, $Rec)
    try {
        $g = @(); $present = $false
        foreach ($it in @($Rec['items'])) {
            $st = $it['state']
            if ($st -is [hashtable] -and $st.ContainsKey('adapters')) { $present = $true; foreach ($a in @($st['adapters'])) { if ($a -is [hashtable] -and $a['guid']) { $g += ([string]$a['guid']).Trim('{}').ToLowerInvariant() } } }
        }
        Undo-Freeze-Plan $Id $g $present
    } catch { Undo-Freeze-Plan $Id @() $true }
}
function Undo-Engine-FrozenPlan {
    # $null when no adapter plan exists for this id; otherwise @{ present = $true; guids = @(...) } (guids may be empty)
    param([string]$Id)
    if ($script:UndoFrozen.ContainsKey($Id) -and $script:UndoFrozen[$Id].present) { return $script:UndoFrozen[$Id] }
    return $null
}
function Undo-Engine-PlanValues {
    # What the saved record says the action may touch: the values of one parameter of the captured items of one provider type
    # (for example the Defender folders). Apply code must use these instead of looking things up again. $null = no plan for this id.
    param([string]$Id, [string]$Type, [string]$Key)
    if (-not $script:UndoPlans.ContainsKey($Id)) { return $null }
    $out = @()
    foreach ($it in @($script:UndoPlans[$Id]['items'])) {
        if ([string]$it['type'] -ne $Type) { continue }
        foreach ($v in @($it['params'][$Key])) { if ($null -ne $v) { $out += [string]$v } }
    }
    return @($out)
}
function Undo-Engine-FrozenAdapters {
    # kept for callers that only want the list: the captured GUIDs (lower case, no braces) or $null when there is no plan
    param([string]$Id)
    $p = Undo-Engine-FrozenPlan $Id
    if ($p) { return @($p.guids) }
    return $null
}
function Undo-Engine-MarkApplied {
    param([Parameter(Mandatory)]$Record)
    try {
        if ($Record['status'] -eq 'captured' -or $Record['status'] -eq 'failed') { $Record['status'] = 'applied' }
        $Record['appliedAt'] = (Undo-Now)
        return (Undo-Store-Put $Record)
    } catch { return $false }
}
function Undo-Engine-AfterApplyHooks {
    # providers with an AfterApply hook (FileSnapshot: which files the action CREATED) get one call with each captured item right after
    # the action, also before a rollback. The mutated record is saved. Returns $true when every hook answered ok.
    param([Parameter(Mandatory)]$Record)
    $all = $true; $any = $false
    try {
        foreach ($it in @($Record['items'])) {
            $pv = Undo-Provider-Get ([string]$it['type'])
            if ($pv -and $pv['AfterApply'] -and (Get-Command ([string]$pv['AfterApply']) -ErrorAction SilentlyContinue)) {
                $any = $true
                $r = $null
                try { $r = & ([string]$pv['AfterApply']) $it } catch { $r = @{ ok = $false; message = $_.Exception.Message } }
                if ($r -and $r.ok -eq $false) { $all = $false; Undo-Log "AfterApply for $($it['type']) said: $($r.message)" 'WARN' }
            }
        }
        if ($any -and -not (Undo-Store-Put $Record)) { $all = $false; Undo-Log "The evidence from the AfterApply hooks could not be saved: $script:UndoLastError" 'WARN' }
    } catch { $all = $false }
    return $all
}
function Undo-Engine-PostApplyHooks {
    # providers with a PostApply hook (WingetPackage: what the action installed) get one call per item. A hook that answers
    # ok = $false, or throws, means the evidence is missing: returns $false (the record is then kept, never "unchanged" or "done").
    param([Parameter(Mandatory)]$Record)
    $all = $true
    try {
        foreach ($it in @($Record['items'])) {
            $pv = Undo-Provider-Get ([string]$it['type'])
            if ($pv -and $pv['PostApply'] -and (Get-Command ([string]$pv['PostApply']) -ErrorAction SilentlyContinue)) {
                $r = $null
                try { $r = & ([string]$pv['PostApply']) $it } catch { $r = @{ ok = $false; message = $_.Exception.Message } }
                if ($null -eq $r -or ($r -is [hashtable] -and $r['ok'] -eq $false) -or ($r.PSObject.Properties['ok'] -and $r.ok -eq $false)) { $all = $false; Undo-Log "PostApply for $($it['type']) did not produce its evidence: $($r.message)" 'WARN' }
            }
        }
    } catch { $all = $false }
    return $all
}
function Undo-Engine-IfUnchanged {
    # After an Apply that ended without changing anything (precondition not met, user cancelled, nothing found): if every item
    # still matches its captured state the NEW record is removed (nothing to undo) and $true is returned. A reused record
    # (the true original from an earlier Apply) is never removed. Returns $false when something differs or on any error.
    param([Parameter(Mandatory)]$Record, [bool]$Reused = $false)
    try {
        if ($Reused) { return $false }
        foreach ($it in @($Record['items'])) {
            # a provider whose Verify cannot see what its Apply changes (no VerifySeesApply flag) can never prove "nothing changed"
            $pv = Undo-Provider-Get ([string]$it['type'])
            if (-not $pv -or $pv['VerifySeesApply'] -ne $true) { return $false }
            $v = Undo-Provider-Call ([string]$it['type']) 'Verify' $it 'Item'
            if (-not $v -or -not $v.matches) { return $false }
        }
        return (Undo-Store-Remove ([string]$Record['id']))
    } catch { return $false }
}
function Undo-Engine-Finish {
    # After a successful Apply call: decide what really happened. 'unchanged' = every item still matches the original (the record is
    # removed, nothing to undo); 'changed' = something differs: providers with a PostApply hook record what the action added (for
    # example which programs it installed), then the record is saved as 'applied'. persisted=$false means the save failed.
    param([Parameter(Mandatory)]$Record, [bool]$Reused = $false)
    try {
        # order matters: AfterApply, then PostApply (they record what the action added), and only then the unchanged check
        $afterOk = Undo-Engine-AfterApplyHooks -Record $Record
        if (-not (Undo-Engine-PostApplyHooks -Record $Record)) { $afterOk = $false }
        if (-not $Reused -and $afterOk -and (Undo-Engine-IfUnchanged -Record $Record)) { return @{ outcome = 'unchanged'; persisted = $true } }
        $ok = Undo-Engine-MarkApplied -Record $Record
        if (-not $afterOk) {
            # a hook that records what the action added did not finish: the record stays, marked partial, and the caller says so
            $Record['status'] = 'partial'; $Record['afterApplyFailed'] = $true
            $ok = ((Undo-Store-Put $Record) -and $ok)
            return @{ outcome = 'changed'; persisted = [bool]$ok; afterApplyFailed = $true }
        }
        return @{ outcome = 'changed'; persisted = [bool]$ok }
    } catch { return @{ outcome = 'changed'; persisted = $false } }
}
function Undo-Engine-ApplyFailed {
    param([Parameter(Mandatory)]$Record, [string]$Reason = '', [bool]$Reused = $false)
    try {
        $hookOk = Undo-Engine-AfterApplyHooks -Record $Record      # record what the half-finished action created before anything is rolled back
        if (-not (Undo-Engine-PostApplyHooks -Record $Record)) { $hookOk = $false }   # also what it installed: attribution is decided BEFORE compensation
        if (-not $hookOk) {
            # we could not record what the half-finished action added, so a rollback cannot be called complete: keep the record as partial
            $Record['status'] = 'partial'; $Record['afterApplyFailed'] = $true
            $r0 = Undo-Engine-Restore -Record $Record -NoChain
            $Record['status'] = 'partial'; [void](Undo-Store-Put $Record)
            return @{ restored = $false; kept = $true; message = 'The change stopped part-way. StreamReady put back what it could, but could not confirm everything the change added, so the saved original is kept in History.' }
        }
        if ($Reused -or $Record['status'] -eq 'applied') {
            # the setting was already applied before this attempt (reused original): do not roll back to the true original on a
            # failed re-apply. Keep the record so Undo can still put the original back.
            $Record['status'] = 'applied'
            [void](Undo-Store-Put $Record)
            return @{ restored = $false; kept = $true; message = 'The original saved earlier is kept, so Undo can still put it back.' }
        }
        $r = Undo-Engine-Restore -Record $Record -NoChain
        if ($r.ok -and -not $r.needsUser) { return @{ restored = $true; kept = $false; message = 'Your original setting was put back.' } }
        if ($r.needsUser) { return @{ restored = $false; kept = $true; message = "The change stopped part-way. Part of it can only be put back by hand: $($r.message)" } }
        $Record['status'] = 'partial'
        [void](Undo-Store-Put $Record)
        return @{ restored = $false; kept = $true; message = 'The change stopped part-way and could not be put back automatically. The original is saved, so you can Undo it from History.' }
    } catch {
        return @{ restored = $false; kept = $true; message = "The change stopped part-way. The original is saved ($($_.Exception.Message))." }
    }
}

# ---- restore ----------------------------------------------------------------------------------------------------------
function Undo-Engine-Restore {
    param([string]$Id = '', $Record = $null, [switch]$WithNewer, [switch]$NoChain)
    $details = New-Object System.Collections.ArrayList
    try {
        if (-not $Record) {
            $st = Undo-Store-Read
            if (-not $st.ok) { return (Undo-Result $false $st.error) }
            if (-not $st.records.ContainsKey($Id)) {
                if ($script:UndoRestoredNow.ContainsKey($Id)) { $ok0 = Undo-Result $true 'That change was already undone together with another one.'; $ok0['alreadyDone'] = $true; return $ok0 }
                return (Undo-Result $false 'That saved original is no longer available.')
            }
            $Record = $st.records[$Id]
        }
        $trustWhy = Undo-Store-Trust
        if ($trustWhy) { return (Undo-Result $false "The folder for saved originals is not safe to use ($trustWhy), so nothing was restored from it.") }
        $val = Undo-Record-Validate $Record
        if (-not $val.valid) { return (Undo-Result $false "Refused: the saved record did not pass the safety check ($($val.reason)). Nothing was changed.") }
        if (-not $NoChain) {
            $blockers = @(Undo-Engine-Blockers $Record)
            if ($blockers.Count -gt 0) {
                if (-not $WithNewer) {
                    $names = ($blockers | ForEach-Object { [string]$_['tweakId'] }) -join ', '
                    $res = Undo-Result $false "A newer change also touches the same setting ($names). Undo that one first, so the settings end up exactly as they were."
                    $res['blockedBy'] = @($blockers | ForEach-Object { [string]$_['id'] })
                    $res['blockedByNames'] = @($blockers | ForEach-Object { [string]$_['tweakId'] })
                    return $res
                }
                foreach ($b in $blockers) {
                    $rb = Undo-Engine-Restore -Id ([string]$b['id']) -WithNewer
                    if (-not $rb.ok -or $rb.needsUser) { return (Undo-Result $false "The newer change $($b['tweakId']) had to be undone first and could not be: $($rb.message)") }
                    # remembered so a current-session Undo button for that change does not fail on a record that is already gone
                    $script:UndoRestoredNow[[string]$b['id']] = [string]$b['tweakId']; $script:UndoRestoredNames[[string]$b['tweakId']] = $true
                }
                # the record may have changed on disk while the newer ones were undone
                $st2 = Undo-Store-Read
                if ($st2.ok -and $st2.records.ContainsKey([string]$Record['id'])) { $Record = $st2.records[[string]$Record['id']] }
            }
        }
        $items = @($Record['items'])
        $failed = 0; $done = 0; $manual = @(); $manualSoFar = $false
        for ($i = $items.Count - 1; $i -ge 0; $i--) {
            $it = $items[$i]
            $type = [string]$it['type']
            $label = $type
            $d = Undo-Provider-Call $type 'Describe' $it 'Item'
            if ($d -is [string] -and $d) { $label = $d }
            if ($it['switchOffWhenManual'] -eq $true -and $manualSoFar) {
                # the stored password could not be put back. Automatic sign-in must never stay ON with the new password: when the original
                # had it on, switch it OFF; when the original had it off or absent the normal restore below puts that back.
                $on = $false
                try { $sx = $it['state']; if ($sx -and $sx['ValueExisted'] -and ([string]$sx['Data']).Trim() -eq '1') { $on = $true } } catch {}
                if ($on) {
                    $swMsg = 'Automatic sign-in was switched OFF, because the old password could not be put back. Set the password again to turn it back on.'
                    $swOk = $false
                    try { Set-ItemProperty -LiteralPath ([string]$it['params']['Key']) -Name ([string]$it['params']['Name']) -Value '0' -Type String -ErrorAction Stop; $swOk = $true } catch { $swMsg = "Automatic sign-in could not be switched off: $($_.Exception.Message). Turn it off in Windows settings, the old password could not be put back." }
                    $it['restoreMessage'] = $swMsg
                    if ($swOk) { $it['restored'] = $true; $done++ } else { $failed++ }
                    $manual += , @{ index = $i; text = $label; message = $swMsg }
                    [void]$details.Add(@{ index = $i; ok = $swOk; manual = $true; text = $label; message = $swMsg })
                    continue
                }
            }
            if ($it['skipWhenManual'] -eq $true -and $manualSoFar) {
                # this item only makes sense when the manual part could be put back (for example automatic sign-in without its password)
                $it['manual'] = $true; $it['restoreMessage'] = 'left as it is because the part before it needs your steps first'
                $manual += , @{ index = $i; text = $label; message = [string]$it['restoreMessage'] }
                [void]$details.Add(@{ index = $i; ok = $false; manual = $true; text = $label; message = [string]$it['restoreMessage'] })
                continue
            }
            if ($it['manual'] -eq $true -and $it['restored'] -ne $true) { $manualSoFar = $true; $manual += , @{ index = $i; text = $label; message = [string]$it['restoreMessage'] }; [void]$details.Add(@{ index = $i; ok = $false; manual = $true; text = $label; message = [string]$it['restoreMessage'] }); continue }
            if ($it['restored'] -eq $true) { $done++; [void]$details.Add(@{ index = $i; ok = $true; text = $label; message = 'already put back' }); continue }
            $ok = $false; $msg = ''
            $v0 = Undo-Provider-Call $type 'Verify' $it 'Item'
            if ($v0 -and $v0.matches) { $ok = $true; $msg = 'already back to the original' }
            else {
                $r = Undo-Provider-Call $type 'Restore' $it 'Item'
                $needsUser = $false; $it['deferred'] = $false
                if ($r) { foreach ($dd in @($r.details)) { if ($dd -and [string]$dd.status -eq 'UserActionRequired') { $needsUser = $true }; if ($dd -and [string]$dd.status -eq 'Deferred') { $it['deferred'] = $true } } }
                if ($needsUser) {
                    # no exact automatic undo exists for this item: say what the user must do, do not count it as put back
                    $manualSoFar = $true
                    $manual += , @{ index = $i; text = $label; message = [string]$r.message }
                    $it['manual'] = $true; $it['restoreMessage'] = [string]$r.message
                    [void]$details.Add(@{ index = $i; ok = $false; manual = $true; text = $label; message = [string]$r.message })
                    continue
                }
                if ($null -eq $r) { $msg = "the $type provider did not answer" }
                elseif (-not $r.ok) { $msg = [string]$r.message }
                else {
                    $v1 = Undo-Provider-Call $type 'Verify' $it 'Item'
                    if ($v1 -and $v1.matches) { $ok = $true; $msg = if ($r.message) { [string]$r.message } else { 'put back' } }
                    elseif ($r.partial) { $msg = if ($r.message) { [string]$r.message } else { 'only part of it could be put back' } }
                    else { $msg = "did not read back as the original: $(if ($v1) { $v1.diff } else { 'no answer from the check' })" }
                }
            }
            if ($ok) { $done++; $it['restored'] = $true; $it['restoreMessage'] = $msg } else { $failed++; $it['restoreMessage'] = $msg }
            [void]$details.Add(@{ index = $i; ok = $ok; text = $label; message = $msg })
        }
        if ($failed -eq 0 -and $manual.Count -gt 0) {
            # everything that CAN be put back was; the rest needs the user. The record is KEPT (status manual) with the evidence and the
            # steps until the user confirms, and the result says plainly that this is NOT a complete undo.
            $Record['status'] = 'manual'
            [void](Undo-Store-Put $Record)
            $todo = ($manual | ForEach-Object { "$($_.text): $($_.message)" }) -join ' '
            return @{ ok = $false; partial = $true; needsUser = $true; manual = @($manual); message = "Put back what could be put back. You need to do this yourself: $todo"; details = @($details.ToArray()) }
        }
        if ($failed -eq 0) {
            $Record['status'] = 'restored'
            $Record['restoredAt'] = (Undo-Now)
            if (-not (Undo-Store-Remove ([string]$Record['id']))) {
                Undo-Log 'The setting was put back, but its saved record could not be cleared from disk. It is marked as used up.' 'WARN'
            }
            return @{ ok = $true; partial = $false; needsUser = $false; message = 'Put back to the original.'; details = @($details.ToArray()) }
        }
        $Record['status'] = 'partial'
        [void](Undo-Store-Put $Record)   # keeps the items already done marked, so a retry only repeats the failed ones
        $first = @($details.ToArray() | Where-Object { -not $_.ok } | Select-Object -First 1)
        $why = if ($first.Count -gt 0) { "$($first[0].text): $($first[0].message)" } else { '' }
        return @{ ok = $false; partial = ($done -gt 0); needsUser = $false; message = "$failed of $($items.Count) parts could not be put back. $why".Trim(); details = @($details.ToArray()) }
    } catch {
        return @{ ok = $false; partial = $false; needsUser = $false; message = "Undo failed: $($_.Exception.Message)"; details = @($details.ToArray()) }
    }
}
function Undo-Engine-Acknowledge {
    # the user did the manual steps (or accepts the result): a 'manual' record is removed. Any other status is refused.
    param([string]$Id)
    try {
        $st = Undo-Store-Read
        if (-not $st.ok) { return (Undo-Result $false $st.error) }
        if (-not $st.records.ContainsKey($Id)) { return (Undo-Result $true 'Nothing to confirm.') }
        $recA = $st.records[$Id]
        $deferredOnly = $false
        if ($recA['status'] -eq 'partial') {
            $open = @(@($recA['items']) | Where-Object { $_['restored'] -ne $true })
            $deferredOnly = ($open.Count -gt 0 -and @($open | Where-Object { $_['deferred'] -ne $true }).Count -eq 0)
        }
        if ($recA['status'] -ne 'manual' -and -not $deferredOnly) { return (Undo-Result $false 'This item has not finished its Undo yet.') }
        if (Undo-Store-Remove $Id) { return (Undo-Result $true 'Confirmed and removed from the list.') }
        return (Undo-Result $false 'Could not update the saved list.')
    } catch { return (Undo-Result $false $_.Exception.Message) }
}

# ---- listing and History wording --------------------------------------------------------------------------------------
function Undo-Engine-InvalidList {
    # saved originals that exist but fail the safety check (old format, dropped parts, tampering): shown in History, never used
    $out = @()
    try {
        $st = Undo-Store-Read
        if (-not $st.ok) { return @() }
        foreach ($r in @($st.records.Values)) {
            if ($r['status'] -eq 'restored') { continue }
            $v = Undo-Record-Validate $r
            if (-not $v.valid) { $out += , @{ id = [string]$r['id']; tweakId = [string]$r['tweakId']; capturedAt = [string]$r['capturedAt']; status = [string]$r['status']; reason = [string]$v.reason } }
        }
    } catch {}
    return @($out)
}
function Undo-Engine-DiscardInvalid {
    # explicit user decision for ONE saved original that fails the safety check: a copy is written next to the store (never deleted),
    # then the record leaves the list so the change can be applied again. A record that is valid is refused.
    param([Parameter(Mandatory)][string]$Id)
    try {
        $st = Undo-Store-Read
        if (-not $st.ok) { return (Undo-Result $false $st.error) }
        if (-not $st.records.ContainsKey($Id)) { return (Undo-Result $false 'That saved original is no longer in the list.') }
        $rec = $st.records[$Id]
        if ((Undo-Record-Validate $rec).valid) { return (Undo-Result $false 'That saved original is fine, so it was not discarded.') }
        $keep = Join-Path (Undo-Dir) "invalid-$($Id)-$([datetime]::Now.ToString('yyyyMMdd-HHmmss')).json"
        ($rec | ConvertTo-Json -Depth 60) | Set-Content -LiteralPath $keep -Encoding UTF8 -ErrorAction Stop
        if (-not (Test-Path -LiteralPath $keep)) { return (Undo-Result $false 'A copy could not be kept, so nothing was discarded.') }
        if (-not (Undo-Store-Remove $Id)) { return (Undo-Result $false "Could not update the list ($script:UndoLastError).") }
        return (Undo-Result $true "The saved original was discarded. A copy was kept at $keep.")
    } catch { return (Undo-Result $false "Could not discard it: $($_.Exception.Message)") }
}
function Undo-Engine-List {
    param([string]$TweakId = '')
    try {
        $st = Undo-Store-Read
        if (-not $st.ok) { return @() }
        $all = @($st.records.Values | Where-Object { $_['status'] -ne 'restored' -and (-not $TweakId -or $_['tweakId'] -eq $TweakId) })
        $good = @()
        foreach ($r in $all) { $v = Undo-Record-Validate $r; if ($v.valid) { $good += , $r } }
        return @($good | Sort-Object { $_['capturedAt'] })
    } catch { return @() }
}
function Undo-Engine-Describe {
    # one line per item for the History page: what was recorded, and whether it is back
    param($Record)
    $lines = @()
    try {
        $n = 0
        foreach ($it in @($Record['items'])) {
            $n++
            $type = [string]$it['type']
            $d = Undo-Provider-Call $type 'Describe' $it 'Item'
            if (-not ($d -is [string]) -or -not $d) { $d = "$type item $n" }
            $state = if ($it['manual'] -eq $true -or ($it['params'] -is [hashtable] -and $it['params']['AllowNonExact'])) { 'no exact automatic undo; needs manual steps' } elseif ($it['restored'] -eq $true) { 'back to the original' } elseif ($it['restoreMessage']) { "could not be put back: $($it['restoreMessage'])" } else { 'can be put back' }
            $lines += "$d ($state)"
        }
    } catch {}
    return $lines
}

# ---- tools: one wrapper for the immediate tools ---------------------------------------------------------------------
function Undo-Engine-ToolRun {
    # Capture before, run the Apply scriptblock, roll back when it throws. Returns
    # @{ ok; none; notApplicable; applied; unchanged; result; error; undo (scriptblock for the undo stack, or $null); recordId; rolledBack; message }
    param([Parameter(Mandatory)][string]$ToolId, [Parameter(Mandatory)][scriptblock]$Apply)
    $b = Undo-Engine-Begin -Id $ToolId -Kind 'tool'
    if ($b.notApplicable) {
        return @{ ok = $false; none = $false; notApplicable = $true; applied = $false; unchanged = $false; result = $null; error = $b.error; undo = $null; recordId = $null; rolledBack = $false
                  message = 'Nothing to change here: nothing matching was found on this PC. Nothing was changed.' }
    }
    if (-not $b.ok) {
        return @{ ok = $false; none = $false; notApplicable = $false; notRecorded = $true; failedWhat = $b.failedWhat; applied = $false; unchanged = $false; result = $null; error = $b.error; undo = $null; recordId = $null; rolledBack = $false
                  message = "Not applied: could not record the original $($b.failedWhat) ($($b.error)). Nothing was changed." }
    }
    if ($b.none) {
        $res = $null
        try { $res = & $Apply } catch { return @{ ok = $false; none = $true; notApplicable = $false; applied = $false; unchanged = $false; result = $null; error = $_.Exception.Message; undo = $null; recordId = $null; rolledBack = $false; message = "Failed: $($_.Exception.Message)" } }
        return @{ ok = $true; none = $true; notApplicable = $false; applied = $true; unchanged = $false; result = $res; error = $null; undo = $null; recordId = $null; rolledBack = $false; message = '' }
    }
    $rec = $b.record
    $res = $null
    try { $res = & $Apply }
    catch {
        $f = Undo-Engine-ApplyFailed -Record $rec -Reason $_.Exception.Message
        return @{ ok = $false; none = $false; notApplicable = $false; applied = $false; unchanged = $false; result = $null; error = $_.Exception.Message; undo = $null; recordId = [string]$rec['id']; rolledBack = [bool]$f.restored; message = $f.message }
    }
    $fin = Undo-Engine-Finish -Record $rec
    if ($fin.outcome -eq 'unchanged') {
        return @{ ok = $true; none = $false; notApplicable = $false; applied = $true; unchanged = $true; result = $res; error = $null; undo = $null; recordId = $null; rolledBack = $false; message = '' }
    }
    $rid = [string]$rec['id']
    $undo = { Undo-Engine-ToolUndoRun $rid }.GetNewClosure()
    return @{ ok = $true; none = $false; notApplicable = $false; applied = $true; unchanged = $false; persistFailed = (-not $fin.persisted); evidenceMissing = [bool]$fin.afterApplyFailed; result = $res; error = $null; undo = $undo; recordId = $rid; rolledBack = $false; message = $(if ($fin.persisted) { '' } else { 'The change was made but its saved original could not be updated on disk; Undo still works until you close StreamReady.' }) }
}
function Undo-Engine-ToolUndoRun {
    # body of the scriptblock that goes on the undo stack: restores, or throws a plain message so the stack keeps it for retry.
    # A result that still needs the user's own steps does NOT throw (the stack must not jam) but is reported loudly, the record
    # stays in History as 'manual', and $script:UndoManualNeeded names it.
    param([string]$RecordId)
    $r = Undo-Engine-Restore -Id $RecordId
    if ($r.needsUser) {
        try { $tid = [string]((Undo-Store-Read).records[$RecordId]['tweakId']); if ($tid -and $script:ManualPending -is [hashtable]) { $script:ManualPending[$tid] = $true } } catch {}
        if (-not $script:UndoManualNeeded) { $script:UndoManualNeeded = @{} }
        $script:UndoManualNeeded[$RecordId] = [string]$r.message
        Undo-Log "UNDO (needs your steps): $($r.message)" 'WARN'
        return
    }
    if (-not $r.ok) { throw $r.message }
    Undo-Log "UNDO: $($r.message)" 'UNDO'
}

# ---- import of schema 1 records (undo_records.json), so records made by earlier builds keep working -------------------------
function Undo-Engine-ImportLegacy {
    # schema 1 record: @{ Tweak; Time; Items = @( @{ Key; Name; Kind; Token; KeyExisted; CreatedRoot; ValueExisted; Type; Data; TokenExisted; TokenValue } ) }.
    # The item shape equals the Registry provider state, so each one becomes a Registry item.
    # Returns @{ imported; rejected; skipped; durable }: durable is $true only when every intended record was written AND read back.
    # The caller may set the old file aside only when durable and rejected is 0.
    $res = @{ imported = 0; rejected = 0; skipped = 0; durable = $false }
    try {
        if (-not $script:UndoRecordPath -or -not (Test-Path -LiteralPath $script:UndoRecordPath)) { return $res }
        $marker = "$script:UndoRecordPath.v2imported"
        if (Test-Path -LiteralPath $marker) { return $res }
        $raw = Get-Content -LiteralPath $script:UndoRecordPath -Raw -ErrorAction Stop
        if (-not $raw -or -not $raw.Trim()) { return $res }
        $j = ConvertTo-UndoPlain ($raw | ConvertFrom-Json -ErrorAction Stop)
        if ($j -isnot [hashtable]) { return $res }
        [void](Undo-Engine-InitSpecs)
        $newRecs = @{}
        $existingFor = @{}
        $st = Undo-Store-Read
        if (-not $st.ok) { return $res }
        foreach ($o in @($st.records.Values)) { if ($o['status'] -ne 'restored') { $existingFor[[string]$o['tweakId']] = $true } }
        foreach ($name in @($j.Keys)) {
            if ($name -like '*.rejected-*') { $res.skipped++; continue }
            $leg = $j[$name]
            if ($leg -isnot [hashtable] -or -not $script:UndoTweakSpecs.ContainsKey($name)) { $res.rejected++; continue }
            if ($existingFor.ContainsKey($name)) { $res.skipped++; continue }
            if (Get-Command Test-UndoRecordValid -ErrorAction SilentlyContinue) { if (-not (Test-UndoRecordValid $name $leg)) { $res.rejected++; continue } }
            $rid = Undo-NewId
            $items = @()
            $idx = 0
            foreach ($li in @($leg['Items'])) {
                $idx++
                $params = @{ Key = [string]$li['Key']; Name = [string]$li['Name'] }
                if ($li['Token']) { $params['Token'] = [string]$li['Token'] }
                $params['_recordId'] = $rid; $params['_index'] = $idx
                try { if (([string]$params['Key']) -match '^HKCU:' -and $li -is [hashtable] -and (Undo-My-Sid-Ok)) { $li['userSid'] = (Undo-My-Sid) } } catch {}
                $items += , @{ type = 'Registry'; v = 1; params = $params; state = $li; ok = $true; error = $null; capturedAt = [string]$leg['Time']; restored = $false; restoreMessage = $null }
            }
            $rec = @{ schema = $script:UndoSchema; id = $rid; tweakId = $name; kind = 'tweak'; batchId = (Undo-NewId); capturedAt = (Undo-Now); seq = (Undo-Next-Seq); items = @($items); status = 'applied'; irreversible = @(); imported = $true }
            $rec['resources'] = @(Undo-Record-Resources $rec)
            if ((Undo-Record-Validate $rec).valid) { $newRecs[$rid] = $rec } else { $res.rejected++ }
        }
        if ($newRecs.Count -eq 0) { $res.durable = ($res.rejected -eq 0); return $res }
        $wrote = [bool](Undo-Store-Locked {
            $s2 = Undo-Store-Read
            if (-not $s2.ok) { return $false }
            foreach ($k in @($newRecs.Keys)) { $s2.records[$k] = $newRecs[$k] }
            if (-not (Undo-Store-Write $s2.records)) { return $false }
            $s3 = Undo-Store-Read
            if (-not $s3.ok) { return $false }
            foreach ($k in @($newRecs.Keys)) { if (-not $s3.records.ContainsKey($k)) { return $false } }
            return $true
        })
        if ($wrote) {
            $res.imported = $newRecs.Count; $res.durable = $true
            if ($res.rejected -eq 0) { try { Set-Content -LiteralPath $marker -Value (Undo-Now) -Encoding ASCII } catch {} }
        }
        return $res
    } catch { return $res }
}

# ---- providers\Registry.ps1 ----
# Registry provider: adapter around the app's existing Get-RegItemState / Restore-RegItemState, so the 67 registry tweaks
# and the new providers share one record type. Params: Key (HKLM:\ HKCU:\ HKU:\ path), Name (value name), Token (optional,
# for rows that edit one NAME=n token inside a text value). Plain functions, no top-level side effects except registration.

if (-not $script:UndoProviders) { $script:UndoProviders = @{} }
$script:UndoProviders['Registry'] = @{ Capture = 'Undo-Registry-Capture'; Restore = 'Undo-Registry-Restore'; Verify = 'Undo-Registry-Verify'; Describe = 'Undo-Registry-Describe'; Validate = 'Undo-Registry-Validate'; VerifySeesApply = $true; Version = 1 }

function _Registry_Text {
    param($V)
    if ($null -eq $V) { return '' }
    if ($V -is [array]) { return (($V | ForEach-Object { [string]$_ }) -join '|') }
    return [string]$V
}
function _Registry_SameState {
    param($A, $B)
    # A = captured, B = current. Compares what matters for "back to the original".
    if ([string]$A.Kind -eq 'Token') {
        if ([bool]$A.ValueExisted -ne [bool]$B.ValueExisted) { return $false }
        if ([bool]$A.TokenExisted -ne [bool]$B.TokenExisted) { return $false }
        if ($A.TokenExisted -and [string]$A.TokenValue -ne [string]$B.TokenValue) { return $false }
        return $true
    }
    if ([bool]$A.ValueExisted -ne [bool]$B.ValueExisted) { return $false }
    if (-not $A.ValueExisted) { return $true }
    if ([string]$A.Type -ne [string]$B.Type) { return $false }
    return ((_Registry_Text $A.Data) -eq (_Registry_Text $B.Data))
}
function Undo-Registry-Capture {
    param([hashtable]$Params)
    $out = @{ type = 'Registry'; v = 1; params = $Params; state = $null; ok = $false; error = $null; capturedAt = (Undo-Now) }
    try {
        $tok = if ($Params.ContainsKey('Token') -and $Params['Token']) { [string]$Params['Token'] } else { '' }
        $s = Get-RegItemState -Key ([string]$Params['Key']) -Name ([string]$Params['Name']) -Token $tok
        $out.state = ConvertTo-UndoPlain $s
        # a user hive item belongs to the Windows account that captured it: the SID is recorded and checked again at restore
        if (([string]$Params['Key']) -match '^HKCU:') {
            if (-not (Undo-My-Sid-Ok)) { throw 'StreamReady could not tell which Windows account this is, so it cannot tie a user setting to it' }
            $out.state['userSid'] = (Undo-My-Sid)
        }
        $out.ok = $true
    } catch { $out.error = "could not read $($Params['Key']) $($Params['Name']) exactly: $($_.Exception.Message)" }
    return $out
}
function _Registry_OtherUser {
    # $null when the item is not user scoped or belongs to the signed-in account; otherwise the plain refusal
    param($Item)
    try {
        if (([string]$Item['params']['Key']) -notmatch '^HKCU:') { return $null }
        $sid = [string]$Item['state']['userSid']
        if (-not $sid) { return 'this saved original is not tied to a Windows account, so it is not applied to this one' }
        if ($sid -ne (Undo-My-Sid)) { return 'this saved original belongs to a different Windows account, so it is not applied to this one. Sign in as that account and press Undo there' }
        return $null
    } catch { return 'the Windows account of this saved original could not be checked' }
}
function Undo-Registry-Restore {
    param($Item)
    $who = _Registry_OtherUser $Item
    if ($who) { return @{ ok = $false; partial = $false; message = "$($Item['params']['Key']) $($Item['params']['Name']): $who"; details = @() } }
    try {
        Restore-RegItemState (ConvertTo-UndoPlain $Item['state'])
        return @{ ok = $true; partial = $false; message = 'put back'; details = @() }
    } catch { return @{ ok = $false; partial = $false; message = "$($Item['params']['Key']) $($Item['params']['Name']): $($_.Exception.Message)"; details = @() } }
}
function Undo-Registry-Verify {
    param($Item)
    $who = _Registry_OtherUser $Item
    if ($who) { return @{ matches = $false; diff = $who } }
    try {
        $st = ConvertTo-UndoPlain $Item['state']
        $tok = if ($st['Token']) { [string]$st['Token'] } else { '' }
        $cur = Get-RegItemState -Key ([string]$st['Key']) -Name ([string]$st['Name']) -Token $tok
        if (_Registry_SameState $st $cur) { return @{ matches = $true; diff = '' } }
        $want = if ($st['ValueExisted']) { "$($st['Type']) $(_Registry_Text $st['Data'])" } else { 'absent' }
        $now = if ($cur.ValueExisted) { "$($cur.Type) $(_Registry_Text $cur.Data)" } else { 'absent' }
        return @{ matches = $false; diff = "$($st['Key']) $($st['Name']) is $now, original was $want" }
    } catch { return @{ matches = $false; diff = "could not read the value: $($_.Exception.Message)" } }
}
function Undo-Registry-Describe {
    param($Item)
    try {
        $st = ConvertTo-UndoPlain $Item['state']
        $where = "$($st['Key'])\$($st['Name'])"
        if ($st['Kind'] -eq 'Token') {
            $t = if ($st['TokenExisted']) { "$($st['Token'])=$($st['TokenValue'])" } else { "$($st['Token']) not set" }
            return "Registry setting $where, part $t"
        }
        if (-not $st['ValueExisted']) { return "Registry value $where did not exist" }
        $d = _Registry_Text $st['Data']
        if ($d.Length -gt 60) { $d = $d.Substring(0, 57) + '...' }
        return "Registry value $where was $d ($($st['Type']))"
    } catch { return 'Registry value' }
}
function Undo-Registry-Validate {
    param($Item)
    try {
        $p = $Item['params']; $st = $Item['state']
        $key = [string]$p['Key']; $name = [string]$p['Name']
        if ($key -notmatch '^(HKLM|HKCU|HKU):\\[^\x00-\x1f]{1,400}$') { return @{ valid = $false; reason = 'registry path not allowed' } }
        if ($key -match '(^|\\)\.\.(\\|$)') { return @{ valid = $false; reason = 'registry path not allowed' } }
        if ($name.Length -gt 255 -or $name -match '[\x00-\x1f]') { return @{ valid = $false; reason = 'value name not allowed' } }
        if ([string]$st['Key'] -ne $key -or [string]$st['Name'] -ne $name) { return @{ valid = $false; reason = 'state does not match its target' } }
        if ($key -match '^HKCU:' -and -not (Undo-Sid-Valid ([string]$st['userSid']))) { return @{ valid = $false; reason = 'a user setting is not tied to a valid Windows account (old format or damaged)' } }
        if ($p.ContainsKey('Token') -and $p['Token'] -and ([string]$p['Token']) -notmatch '^[A-Za-z0-9_.-]{1,40}$') { return @{ valid = $false; reason = 'token not allowed' } }
        if ($st['ValueExisted'] -and [string]$st['Type'] -notin @('DWord', 'QWord', 'String', 'ExpandString', 'Binary', 'MultiString', 'None')) { return @{ valid = $false; reason = 'value type not allowed' } }
        if ($st['CreatedRoot']) {
            $root = [string]$st['CreatedRoot']
            if (-not ($key -eq $root -or $key.StartsWith($root + '\'))) { return @{ valid = $false; reason = 'created key does not contain the target' } }
        }
        return @{ valid = $true; reason = $null }
    } catch { return @{ valid = $false; reason = $_.Exception.Message } }
}

# ---- providers\ApplicationRecovery.ps1 ----
if (-not $script:UndoProviders) { $script:UndoProviders = @{} }
# Explicit non-exact application recovery: never starts an installer or forces defaults.
function _ApplicationRecovery_Field { param($O,[string]$N,$D=$null) if($null -eq $O){return $D};if($O -is [Collections.IDictionary]){if($O.Contains($N)){return $O[$N]}}elseif($O.PSObject.Properties[$N]){return $O.$N};return $D }
function _ApplicationRecovery_Definition {
    param([string]$Product)
    switch($Product){
        'OneDrive' {return @{what='OneDrive uninstall';why='Reinstallation does not restore sign-in, sync state or a stopped process.';recovery='Use a verified original setup program or reinstall OneDrive, then sign in and check your sync folders.'}}
        'PhotoViewer' {return @{what='Protected image default choices';why='Windows may reject restored UserChoice hashes; registry values alone do not prove the previous default.';recovery='Open Default apps as the original user and select each saved previous image application.'}}
        'TimerProcess' {return @{what='Timer helper process state';why='The memory and timer request of a pre-existing process cannot be recreated exactly.';recovery='Stop only the owned task instance and restart the verified original helper if appropriate.'}}
        'ExternalTool' {return @{what='External tool changes';why='The external program can change state that this action does not capture.';recovery='Use its verified backup/export and confirm the original configuration before marking recovery complete.'}}
        'CacheCleanup' {return @{what='Deleted cache data';why='Deleted bytes cannot be reconstructed unless a verified file snapshot exists.';recovery='Restore the saved files, or let the owning application rebuild its cache.'}}
        default {throw 'Unknown application recovery capability.'}
    }
}
function _ApplicationRecovery_Inventory {
    param([string]$Product)
    $sid=[Security.Principal.WindowsIdentity]::GetCurrent().User.Value
    $out=@{userSid=$sid;files=@();associations=@()}
    if($Product -eq 'OneDrive'){
        foreach($p in @((Join-Path $env:SystemRoot 'SysWOW64\OneDriveSetup.exe'),(Join-Path $env:SystemRoot 'System32\OneDriveSetup.exe'),(Join-Path $env:LOCALAPPDATA 'Microsoft\OneDrive\OneDrive.exe'))){
            if($p -notmatch '^[A-Za-z]:\\' -or (New-Object IO.DriveInfo($p.Substring(0,3))).DriveType -eq [IO.DriveType]::Network){throw 'Application inventory needs a local path; no network location was read.'}
            $exists=[bool](Test-Path -LiteralPath $p -PathType Leaf -ErrorAction Stop)
            $f=@{path=$p;existed=$exists;version=$null;sha256=$null}
            if($exists){$f.version=(Get-Item -LiteralPath $p -ErrorAction Stop).VersionInfo.FileVersion;$f.sha256=(Get-FileHash -LiteralPath $p -Algorithm SHA256 -ErrorAction Stop).Hash}
            $out.files+=,$f
        }
    }
    if($Product -eq 'PhotoViewer'){
        foreach($ext in @('.jpg','.jpeg','.png','.bmp','.gif','.tiff','.tif')){
            $sub='Software\Microsoft\Windows\CurrentVersion\Explorer\FileExts\'+$ext+'\UserChoice'
            $k=[Microsoft.Win32.Registry]::CurrentUser.OpenSubKey($sub,$false)
            try{
                $out.associations+=,@{extension=$ext;existed=($null -ne $k);progId=$(if($k){[string]$k.GetValue('ProgId')}else{$null});hashWasPresent=$(if($k){@($k.GetValueNames()) -contains 'Hash'}else{$false})}
            }finally{if($k){$k.Dispose()}}
        }
    };return $out
}
function Undo-ApplicationRecovery-Capture {
    param([hashtable]$Params=@{})
    $r=@{type='ApplicationRecovery';v=1;params=$Params;state=$null;ok=$false;error=$null;capturedAt=[datetime]::UtcNow.ToString('o')}
    try{
        $def=_ApplicationRecovery_Definition ([string]$Params.Product)
        $r.state=@{product=[string]$Params.Product;capability='RequiresUserRecovery';automaticExactRestore=$false;what=$def.what;why=$def.why;bestRecovery=$def.recovery;inventory=(_ApplicationRecovery_Inventory ([string]$Params.Product))}
        if(-not(_ApplicationRecovery_Field $Params 'AllowNonExact' $false)){throw 'This action has no exact automatic Undo; it is blocked until its recovery limitation is accepted by the caller.'}
        $r.ok=$true
    }catch{$r.error=$_.Exception.Message};return $r
}
function Undo-ApplicationRecovery-Validate {
    param($Item)
    try{
        $d=_ApplicationRecovery_Definition ([string]$Item.params.Product)
        if($Item.type -ne 'ApplicationRecovery' -or [int]$Item.v -ne 1 -or $Item.ok -ne $true -or -not $Item.params.AllowNonExact){throw 'Invalid recovery capability envelope.'}
        if($Item.state.product -ne $Item.params.Product -or $Item.state.capability -ne 'RequiresUserRecovery' -or $Item.state.automaticExactRestore -ne $false){throw 'An application recovery cannot claim exact automatic restoration.'}
        if($Item.state.inventory.userSid -ne [Security.Principal.WindowsIdentity]::GetCurrent().User.Value){throw 'The original user is different.'}
        if($Item.state.product -eq 'PhotoViewer'){
            $allowed=@('.jpg','.jpeg','.png','.bmp','.gif','.tiff','.tif');$seen=@{}
            if(@($Item.state.inventory.associations).Count -ne $allowed.Count){throw 'Incomplete previous image choices.'}
            foreach($a in @($Item.state.inventory.associations)){
                if($a.extension -notin $allowed -or $seen.ContainsKey([string]$a.extension) -or $a.existed -isnot [bool] -or $a.hashWasPresent -isnot [bool]){throw 'Invalid saved image choice.'}
                $seen[[string]$a.extension]=$true
                if($a.progId -and (([string]$a.progId).Length -gt 1024 -or [string]$a.progId -match '[\x00-\x1F]')){throw 'Invalid previous image ProgID.'}
            }
        }
        return @{valid=$true;reason=''}
    }catch{return @{valid=$false;reason=$_.Exception.Message}}
}
function Undo-ApplicationRecovery-Verify {
    param($Item)
    try{
        $v=Undo-ApplicationRecovery-Validate $Item;if(-not $v.valid){throw $v.reason}
        return @{matches=$false;diff='User recovery is required; file or installer presence does not prove the original application state.'}
    }catch{return @{matches=$false;diff=$_.Exception.Message}}
}
function _ApplicationRecovery_AssociationText {
    param($Item)
    $parts=@()
    foreach($a in @($Item.state.inventory.associations)){
        $label=if($a.existed -and $a.progId){[string]$a.progId}else{'no saved user choice'}
        $parts+=([string]$a.extension+' -> '+$label)
    }
    return ('Saved image choices: '+($parts -join '; ')+'. Open Settings, Apps, Default apps as the original user and choose the application registered for each saved ProgID. UserChoice keys created by the tweak are protected by Windows and may remain until you select the defaults there; they are not claimed restored.')
}
function Undo-ApplicationRecovery-Restore {
    param($Item)
    try{
        $v=Undo-ApplicationRecovery-Validate $Item;if(-not $v.valid){throw $v.reason}
        $d=_ApplicationRecovery_Definition ([string]$Item.params.Product)
        return @{ok=$false;partial=$true;message=$(if($Item.params.Product -eq 'PhotoViewer'){_ApplicationRecovery_AssociationText $Item}else{$d.recovery});details=@(@{target=$Item.params.Product;ok=$false;status='UserActionRequired';message=$d.why})}
    }catch{return @{ok=$false;partial=$false;message=$_.Exception.Message;details=@()}}
}
function Undo-ApplicationRecovery-Describe {
    param($Item)
    try{$d=_ApplicationRecovery_Definition ([string]$Item.params.Product);if($Item.params.Product -eq 'PhotoViewer'){return (_ApplicationRecovery_AssociationText $Item)};return "$($d.what): manual recovery is required; no exact automatic Undo."}catch{return 'Application recovery requires user action.'}
}
$script:UndoProviders['ApplicationRecovery']=@{Capture='Undo-ApplicationRecovery-Capture';Restore='Undo-ApplicationRecovery-Restore';Verify='Undo-ApplicationRecovery-Verify';Describe='Undo-ApplicationRecovery-Describe';Validate='Undo-ApplicationRecovery-Validate';VerifySeesApply = $false; Version=1}

# ---- providers\Bcd.ps1 ----
# StreamReady undo engine - provider: Bcd (boot configuration data: individual elements of one boot entry)
# Plain function definitions plus one registration. Dot-source safe. ASCII only.
#
# Params (hashtable):
#   Identifier  boot entry, default '{current}' (an alias such as {current} or {default}, or an entry GUID in braces)
#   Elements    names of the elements this tweak changes, for example @('disabledynamictick','tscsyncpolicy')
#   StorePath   (optional) a BCD store FILE to operate on (bcdedit /store). Production leaves it empty (system store);
#               tests pass an exported copy. Use an explicit entry GUID with an offline store.
#   (the whole-store safety copy is NOT a parameter: Undo-Bcd-Prepare makes it inside the private record folder
#   _filesDir after all captures, for the system store only. The copy is for MANUAL recovery only; Restore never imports it.)
#
# Safety rules (the provider enforces these itself, independent of the core and of the spec):
#   - only the elements in _Bcd_AllowedValues can ever be written or deleted (the ones StreamReady changes), each with its
#     own list of legal values;
#   - Identifier must be {current}, {default} or a GUID;
#   - StorePath is refused unless a test sets $script:UndoBcdAllowStorePath;
#   - unknown parameter names are refused;
#   - identifiers are read WITHOUT relying on translated labels (the first line after a dashed header line), and a capture
#     with an empty entry list or an unresolved alias fails instead of recording a weak guard.
#
# State: identifier, resolvedId (what the alias pointed at), elements (name -> @{ existed; value }), ids (all entry
#   identifiers in the store, sorted), export (path + sha256 or $null).
# Restore changes ONLY the named elements, and only when the set of boot entries is the same as at capture and the
# identifier still points at the same entry. Otherwise it refuses and explains.

if ($null -eq $script:UndoProviders) { $script:UndoProviders = @{} }
$script:UndoProviders['Bcd'] = @{ Capture = 'Undo-Bcd-Capture'; Restore = 'Undo-Bcd-Restore'; Verify = 'Undo-Bcd-Verify'; Describe = 'Undo-Bcd-Describe'; Validate = 'Undo-Bcd-Validate'; Prepare = 'Undo-Bcd-Prepare'; VerifySeesApply = $true; Version = 1 }

function _Bcd_Now { return (Get-Date).ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ssZ') }

# element table as a list of @{Name;Value}; works for a hashtable (fresh capture) and for an object read back from JSON
function _Bcd_Pairs {
    param($E)
    $o = @()
    if ($E -is [System.Collections.IDictionary]) { foreach ($k in $E.Keys) { $o += , @{ Name = [string]$k; Value = $E[$k] } } }
    elseif ($null -ne $E) { foreach ($p in $E.PSObject.Properties) { $o += , @{ Name = [string]$p.Name; Value = $p.Value } } }
    return $o
}

function _Bcd_ValidElement { param($N) return ([string]$N -match '^[A-Za-z][A-Za-z0-9]{1,63}$') }
function _Bcd_ValidId { param($I) return ([string]$I -match '^\{[A-Za-z0-9\-]{1,40}\}$') }
function _Bcd_ValidValue { param($V) return ([string]$V -match '^[A-Za-z0-9_.{}\-]{1,128}$') }
function _Bcd_ValidGuidId { param($I) return ([string]$I -match '^\{[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}\}$') }

# the only boot elements StreamReady ever changes, with the (normalised, lower case) values that can be written back
function _Bcd_AllowedValues {
    return @{
        'disabledynamictick'   = '^(yes|no)$'
        'tscsyncpolicy'        = '^(default|legacy|enhanced)$'
        'hypervisorlaunchtype' = '^(off|auto|on|disabled)$'
        'bootmenupolicy'       = '^(legacy|standard)$'
    }
}
function _Bcd_ElementAllowed { param($N) return (_Bcd_AllowedValues).ContainsKey(([string]$N).ToLowerInvariant()) }
function _Bcd_ValueAllowed { param($N, $V) $re = (_Bcd_AllowedValues)[([string]$N).ToLowerInvariant()]; return [bool]($re -and ((_Bcd_NormValue $V) -match $re)) }
function _Bcd_IdentifierAllowed { param($I) return ([string]$I -in @('{current}', '{default}') -or (_Bcd_ValidGuidId $I)) }

function _Bcd_Run {
    param([string]$Store, [string[]]$Args2)
    $a = @()
    if ($Store) { $a += '/store'; $a += $Store }
    $a += $Args2
    $out = & bcdedit.exe @a 2>&1
    $code = $LASTEXITCODE
    return @{ code = $code; lines = @($out | ForEach-Object { [string]$_ }) }
}

function _Bcd_NormValue {
    param($V)
    $t = ([string]$V).Trim().ToLowerInvariant()
    if ($t -in @('yes', 'true', 'on')) { return 'yes' }
    if ($t -in @('no', 'false', 'off')) { return 'no' }
    return $t
}

# parses "name   value" lines of one entry; returns hashtable name(lower) -> value text
function _Bcd_ParseEntry {
    param([string[]]$Lines)
    $h = @{}
    foreach ($l in $Lines) {
        $m = [regex]::Match($l, '^(\S+)\s{2,}(\S.*?)\s*$')
        if ($m.Success) { $h[$m.Groups[1].Value.ToLowerInvariant()] = $m.Groups[2].Value }
    }
    return $h
}

# The identifier of every block is the value on the first non-empty line after a dashed header line. This does not depend on the
# translated word "identifier". Returns the braced ids in order.
function _Bcd_BlockIds {
    param([string[]]$Lines)
    $ids = New-Object System.Collections.ArrayList
    $afterDash = $false
    foreach ($l in $Lines) {
        if ($l -match '^-{4,}\s*$') { $afterDash = $true; continue }
        if (-not $afterDash) { continue }
        if (-not ([string]$l).Trim()) { continue }
        $afterDash = $false
        $m = [regex]::Match($l, '^\S+\s+(\{[^}\s]+\})\s*$')
        if ($m.Success) { [void]$ids.Add($m.Groups[1].Value.ToLowerInvariant()) }
    }
    return @($ids.ToArray())
}

function _Bcd_ReadEntry {
    param([string]$Store, [string]$Id)
    $r = _Bcd_Run $Store @('/enum', $Id, '/v')
    if ($r.code -ne 0) { throw "bcdedit could not read the boot entry $Id (exit code $($r.code)): $($r.lines -join ' ')" }
    $h = _Bcd_ParseEntry $r.lines
    $blockIds = @(_Bcd_BlockIds $r.lines)
    if ($blockIds.Count -ne 1) { throw "bcdedit did not return exactly one boot entry for $Id (found $($blockIds.Count)), so the entry cannot be identified" }
    $resolved = [string]$blockIds[0]
    if (-not (_Bcd_ValidGuidId $resolved)) { throw "the boot entry $Id did not resolve to an entry GUID (got '$resolved'), so it cannot be identified safely" }
    return @{ resolved = $resolved; values = $h }
}

function _Bcd_ListIds {
    param([string]$Store)
    $r = _Bcd_Run $Store @('/enum', 'all', '/v')
    if ($r.code -ne 0) { throw "bcdedit could not list the boot entries (exit code $($r.code)): $($r.lines -join ' ')" }
    $ids = @(_Bcd_BlockIds $r.lines | Sort-Object -Unique)
    if ($ids.Count -eq 0) { throw 'the list of boot entries could not be read (no entry identifiers were found), so the boot guard cannot be recorded' }
    return $ids
}

function Undo-Bcd-Capture {
    param($Params)
    $res = @{ type = 'Bcd'; v = 1; params = $Params; state = $null; ok = $false; error = $null; capturedAt = (_Bcd_Now) }
    try {
        if ($null -eq $Params) { throw 'no parameters' }
        $id = if ($Params.Identifier) { [string]$Params.Identifier } else { '{current}' }
        if (-not (_Bcd_IdentifierAllowed $id)) { throw 'the boot entry identifier is not one StreamReady uses' }
        $names = @($Params.Elements | ForEach-Object { [string]$_ })
        if ($names.Count -eq 0) { throw 'no elements were named' }
        foreach ($n in $names) { if (-not (_Bcd_ValidElement $n) -or -not (_Bcd_ElementAllowed $n)) { throw "element '$n' is not a boot setting StreamReady changes" } }
        foreach ($k in @($Params.Keys)) { if (([string]$k) -notin @('Identifier', 'Elements', 'StorePath') -and -not ([string]$k).StartsWith('_')) { throw "parameter '$k' is not allowed" } }
        $store = if ($Params.StorePath) { [string]$Params.StorePath } else { '' }
        if ($store -and -not $script:UndoBcdAllowStorePath) { throw 'an offline boot store is only allowed in tests' }
        if ($store -and -not (Test-Path -LiteralPath $store -PathType Leaf)) { throw 'the BCD store file does not exist' }
        $entry = _Bcd_ReadEntry $store $id
        $els = @{}
        foreach ($n in $names) {
            $k = $n.ToLowerInvariant()
            if ($entry.values.ContainsKey($k)) { $els[$n] = @{ existed = $true; value = [string]$entry.values[$k] } }
            else { $els[$n] = @{ existed = $false; value = $null } }
            if ($els[$n].existed -and (-not (_Bcd_ValidValue $els[$n].value) -or -not (_Bcd_ValueAllowed $n $els[$n].value))) { throw "the current value of '$n' ($($els[$n].value)) is not one of the values this tool can restore exactly (a translated boot value is not supported)" }
        }
        $state = @{ identifier = $id; resolvedId = $entry.resolved; elements = $els; ids = @(_Bcd_ListIds $store); store = $(if ($store) { 'file' } else { 'system' }); export = $null }
        $res.state = $state
        $res.ok = $true
    } catch { $res.error = "Could not record the original boot settings: $($_.Exception.Message)" }
    return $res
}

function Undo-Bcd-Validate {
    param($Item)
    try {
        if ($null -eq $Item -or [string]$Item.type -ne 'Bcd') { return @{ valid = $false; reason = 'not a Bcd record' } }
        $s = $Item.state
        if ($null -eq $s) { return @{ valid = $false; reason = 'no state' } }
        if (-not (_Bcd_IdentifierAllowed $s.identifier) -or -not (_Bcd_ValidGuidId $s.resolvedId)) { return @{ valid = $false; reason = 'boot entry identifier is not valid' } }
        $pid2 = if ($Item.params.Identifier) { [string]$Item.params.Identifier } else { '{current}' }
        if (-not (_Bcd_IdentifierAllowed $pid2)) { return @{ valid = $false; reason = 'the boot entry identifier is not one StreamReady uses' } }
        if ([string]$s.identifier -ne $pid2) { return @{ valid = $false; reason = 'identifier does not match the parameters' } }
        foreach ($pk in @(_Bcd_Pairs $Item.params | ForEach-Object { $_.Name })) { if ($pk -notin @('Identifier', 'Elements', 'StorePath') -and -not $pk.StartsWith('_')) { return @{ valid = $false; reason = "parameter '$pk' is not allowed" } } }
        if ($Item.params.StorePath -and -not $script:UndoBcdAllowStorePath) { return @{ valid = $false; reason = 'an offline boot store is not allowed' } }
        $allowed = @($Item.params.Elements | ForEach-Object { ([string]$_).ToLowerInvariant() })
        foreach ($a2 in $allowed) { if (-not (_Bcd_ElementAllowed $a2)) { return @{ valid = $false; reason = "element '$a2' is not a boot setting StreamReady changes" } } }
        $count = 0
        foreach ($p in (_Bcd_Pairs $s.elements)) {
            $count++
            if (-not (_Bcd_ValidElement $p.Name) -or ($allowed -notcontains $p.Name.ToLowerInvariant()) -or -not (_Bcd_ElementAllowed $p.Name)) { return @{ valid = $false; reason = "element '$($p.Name)' is not one this tweak owns" } }
            if ($p.Value.existed -isnot [bool]) { return @{ valid = $false; reason = 'existed must be true or false' } }
            if ($p.Value.existed -and (-not (_Bcd_ValidValue $p.Value.value) -or -not (_Bcd_ValueAllowed $p.Name $p.Value.value))) { return @{ valid = $false; reason = "value of '$($p.Name)' is not valid" } }
        }
        if ($count -eq 0) { return @{ valid = $false; reason = 'no elements' } }
        # the record must hold EXACTLY the elements the tweak owns: a dropped element would silently lose its original
        $haveN = (@(_Bcd_Pairs $s.elements | ForEach-Object { $_.Name.ToLowerInvariant() }) | Sort-Object -Unique) -join ','
        $wantN = ($allowed | Sort-Object -Unique) -join ','
        if ($haveN -ne $wantN) { return @{ valid = $false; reason = 'the recorded boot elements are not the ones this tweak owns' } }
        if (@($s.ids).Count -eq 0) { return @{ valid = $false; reason = 'the list of boot entries is empty' } }
        foreach ($i in @($s.ids)) { if (-not (_Bcd_ValidId $i)) { return @{ valid = $false; reason = 'a boot entry id is not valid' } } }
        if ($s.export) {
            $pth = [string]$s.export.path
            if (-not [System.IO.Path]::IsPathRooted($pth) -or $pth -match '\.\.' -or $pth -notmatch '\.bak$') { return @{ valid = $false; reason = 'safety copy path is not valid' } }
            if ($Item.params._recordId) { $rootDir = _Bcd_BackupRoot; if (-not ([IO.Path]::GetFullPath($pth)).StartsWith((Join-Path $rootDir ([string]$Item.params._recordId)) + '\', [StringComparison]::OrdinalIgnoreCase)) { return @{ valid = $false; reason = 'safety copy is outside the record folder' } } }
            if ([string]$s.export.sha256 -notmatch '^[0-9A-Fa-f]{64}$') { return @{ valid = $false; reason = 'safety copy hash is not valid' } }
        }
        return @{ valid = $true; reason = $null }
    } catch { return @{ valid = $false; reason = $_.Exception.Message } }
}

function _Bcd_BackupRoot {
    if (Get-Command Undo-FilesRoot -ErrorAction SilentlyContinue) { return ([IO.Path]::GetFullPath((Undo-FilesRoot)).TrimEnd('\')) }
    return ([IO.Path]::GetFullPath((Join-Path $env:ProgramData 'StreamReady\undo-files')).TrimEnd('\'))
}

# Called by the engine after ALL captures and before the record is saved: makes the whole-store safety copy (system store only)
# inside the private record folder. It never overwrites a file. A failure stops the tweak (the engine treats it like a failed capture).
function Undo-Bcd-Prepare {
    param($Item)
    try {
        $v = Undo-Bcd-Validate $Item
        if (-not $v.valid) { throw $v.reason }
        if ($Item.params.StorePath) { return @{ ok = $true; message = 'offline store: no safety copy needed' } }
        $id = [string]$Item.params._recordId
        if ($id -notmatch '^[0-9a-fA-F-]{36}$') { throw 'the engine did not give a record id for the safety copy' }
        $dir = [IO.Path]::GetFullPath([string]$Item.params._filesDir).TrimEnd('\')
        $expected = [IO.Path]::GetFullPath((Join-Path (_Bcd_BackupRoot) $id)).TrimEnd('\')
        if ($dir -ne $expected) { throw 'the safety copy folder is not the private record folder' }
        if (Get-Command Undo-EnsureDir -ErrorAction SilentlyContinue) { if (-not (Undo-EnsureDir (_Bcd_BackupRoot))) { throw 'the backup folder could not be created' } }
        [void][IO.Directory]::CreateDirectory($dir)
        $file = Join-Path $dir ('bcd-store-' + $Item.params._index + '.bak')
        if (Test-Path -LiteralPath $file) { throw 'a safety copy with this name already exists; it is never overwritten' }
        $ex = _Bcd_Run '' @('/export', $file)
        if ($ex.code -ne 0 -or -not (Test-Path -LiteralPath $file)) { throw "bcdedit /export failed: $($ex.lines -join ' ')" }
        $hash = (Get-FileHash -LiteralPath $file -Algorithm SHA256 -ErrorAction Stop).Hash
        $Item.state.export = @{ path = $file; sha256 = $hash; note = 'whole-store copy for manual recovery only; never imported automatically' }
        return @{ ok = $true; message = 'boot configuration safety copy saved' }
    } catch { return @{ ok = $false; message = "the safety copy of the boot configuration could not be made: $($_.Exception.Message)" } }
}

function Undo-Bcd-Describe {
    param($Item)
    try {
        $parts = @()
        foreach ($p in (_Bcd_Pairs $Item.state.elements)) { $parts += "$($p.Name): $(if ($p.Value.existed) { $p.Value.value } else { 'not set' })" }
        return "Boot setting ($($Item.state.identifier)) - " + ($parts -join ', ')
    } catch { return 'Boot setting (record could not be read)' }
}

function _Bcd_Store { param($Item) if ($Item.params.StorePath) { return [string]$Item.params.StorePath } return '' }

function Undo-Bcd-Verify {
    param($Item)
    try {
        $s = $Item.state
        $store = _Bcd_Store $Item
        $entry = _Bcd_ReadEntry $store ([string]$Item.params.Identifier)
        # the same identity guards as Restore: a changed set of boot entries or an alias that points elsewhere is NEVER an original match
        $idsNow = @(_Bcd_ListIds $store)
        $idsThen = @(@($s.ids) | ForEach-Object { [string]$_ } | Sort-Object -Unique)
        if (($idsNow -join '|') -ne ($idsThen -join '|')) { return @{ matches = $false; diff = 'the list of boot entries is not the same as when the original was recorded' } }
        if ([string]$entry.resolved -ne [string]$s.resolvedId) { return @{ matches = $false; diff = "$($Item.params.Identifier) now points at a different boot entry than when the original was recorded" } }
        $diff = New-Object System.Collections.ArrayList
        foreach ($p in (_Bcd_Pairs $s.elements)) {
            $k = $p.Name.ToLowerInvariant()
            $has = $entry.values.ContainsKey($k)
            if ($p.Value.existed) {
                if (-not $has) { [void]$diff.Add("$($p.Name) is not set, was $($p.Value.value)") }
                elseif ((_Bcd_NormValue $entry.values[$k]) -ne (_Bcd_NormValue $p.Value.value)) { [void]$diff.Add("$($p.Name) is $($entry.values[$k]), was $($p.Value.value)") }
            } elseif ($has) { [void]$diff.Add("$($p.Name) is set to $($entry.values[$k]), was not set") }
        }
        return @{ matches = ($diff.Count -eq 0); diff = ($diff.ToArray() -join '; ') }
    } catch { return @{ matches = $false; diff = "could not read the boot settings: $($_.Exception.Message)" } }
}

function Undo-Bcd-Restore {
    param($Item)
    $details = New-Object System.Collections.ArrayList
    $add = { param($part, $ok, $msg) [void]$details.Add(@{ part = $part; ok = $ok; message = $msg }) }
    try {
        $val = Undo-Bcd-Validate $Item
        if (-not $val.valid) { return @{ ok = $false; partial = $false; message = "Refused: the saved boot settings record is not valid ($($val.reason))."; details = @(); restartNeeded = $false } }
        $s = $Item.state
        $store = _Bcd_Store $Item
        $id = [string]$Item.params.Identifier
        # guard 1: the set of boot entries must be unchanged
        $idsNow = @(_Bcd_ListIds $store)
        $idsThen = @(@($s.ids) | ForEach-Object { [string]$_ } | Sort-Object -Unique)
        if (($idsNow -join '|') -ne ($idsThen -join '|')) {
            return @{ ok = $false; partial = $false; message = 'Refused: the list of boot entries on this PC is not the same as when the original settings were recorded, so nothing was changed. Fix this from Windows recovery options or restore the safety copy by hand.'; details = @(); restartNeeded = $false }
        }
        # guard 2: the identifier must still point at the same entry
        $entry = _Bcd_ReadEntry $store $id
        if ([string]$entry.resolved -ne [string]$s.resolvedId) {
            return @{ ok = $false; partial = $false; message = "Refused: $id now points at a different boot entry than when the original was recorded, so nothing was changed."; details = @(); restartNeeded = $false }
        }
        $target = [string]$s.resolvedId
        $failed = $false
        foreach ($p in (_Bcd_Pairs $s.elements)) {
            $name = $p.Name; $k = $name.ToLowerInvariant()
            $has = $entry.values.ContainsKey($k)
            if ($p.Value.existed) {
                if ($has -and (_Bcd_NormValue $entry.values[$k]) -eq (_Bcd_NormValue $p.Value.value)) { & $add $name $true 'already the original value'; continue }
                $r = _Bcd_Run $store @('/set', $target, $name, [string]$p.Value.value)
                if ($r.code -ne 0) { $failed = $true; & $add $name $false "bcdedit /set failed (exit code $($r.code)): $($r.lines -join ' ')" } else { & $add $name $true "set back to $($p.Value.value)" }
            } else {
                if (-not $has) { & $add $name $true 'was not set before and is not set now'; continue }
                $r = _Bcd_Run $store @('/deletevalue', $target, $name)
                if ($r.code -ne 0) { $failed = $true; & $add $name $false "bcdedit /deletevalue failed (exit code $($r.code)): $($r.lines -join ' ')" } else { & $add $name $true 'removed again (it was not set before)' }
            }
        }
        $v = Undo-Bcd-Verify $Item
        if (-not $v.matches) { $failed = $true; & $add 'verify' $false $v.diff }
        if ($failed) { return @{ ok = $false; partial = $true; message = "The boot settings could not be fully put back: $($v.diff)"; details = @($details.ToArray()); restartNeeded = $true } }
        return @{ ok = $true; partial = $false; message = 'The boot settings were put back to what they were before. Restart your PC to finish.'; details = @($details.ToArray()); restartNeeded = $true }
    } catch {
        return @{ ok = $false; partial = $false; message = "Could not put the boot settings back: $($_.Exception.Message)"; details = @($details.ToArray()); restartNeeded = $false }
    }
}

# ---- providers\DisplayMode.ps1 ----
# DisplayMode provider (group D). Params: Primary = $true (the primary display; the only case StreamReady uses).
# State: the full current display mode (width, height, bits per pixel, refresh rate, orientation, position, flags) and the
# display identity (DeviceID, device name). Restore: find the display by DeviceID (not by \\.\DISPLAYn, which can renumber), test
# the saved mode with CDS_TEST, then apply it with CDS_UPDATEREGISTRY. Test hook: $script:SRUndoDisplayTestOnly = $true makes
# Restore stop after the CDS_TEST step (nothing is changed on screen).
# The type is private to this provider (SRUndoDisplay) and does not use the application's own display type.

if (-not $script:UndoProviders) { $script:UndoProviders = @{} }
$script:UndoProviders['DisplayMode'] = @{ Capture = 'Undo-DisplayMode-Capture'; Restore = 'Undo-DisplayMode-Restore'; Verify = 'Undo-DisplayMode-Verify'; Describe = 'Undo-DisplayMode-Describe'; Validate = 'Undo-DisplayMode-Validate'; VerifySeesApply = $true; Version = 1 }

function _DisplayMode_Type {
    if (([System.Management.Automation.PSTypeName]'SRUndoDisplay').Type) { return }
    Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;
public class SRUndoDisplay {
    [StructLayout(LayoutKind.Sequential, CharSet=CharSet.Ansi)]
    public struct DEVMODE {
        [MarshalAs(UnmanagedType.ByValTStr, SizeConst=32)] public string dmDeviceName;
        public short dmSpecVersion, dmDriverVersion, dmSize, dmDriverExtra;
        public int   dmFields, dmPositionX, dmPositionY, dmDisplayOrientation, dmDisplayFixedOutput;
        public short dmColor, dmDuplex, dmYResolution, dmTTOption, dmCollate;
        [MarshalAs(UnmanagedType.ByValTStr, SizeConst=32)] public string dmFormName;
        public short dmLogPixels; public int dmBitsPerPel, dmPelsWidth, dmPelsHeight,
                     dmDisplayFlags, dmDisplayFrequency, dmICMMethod, dmICMIntent,
                     dmMediaType, dmDitherType, dmReserved1, dmReserved2, dmPanningWidth, dmPanningHeight;
    }
    [StructLayout(LayoutKind.Sequential, CharSet=CharSet.Ansi)]
    public struct DISPLAY_DEVICE {
        public int cb;
        [MarshalAs(UnmanagedType.ByValTStr, SizeConst=32)]  public string DeviceName;
        [MarshalAs(UnmanagedType.ByValTStr, SizeConst=128)] public string DeviceString;
        public int StateFlags;
        [MarshalAs(UnmanagedType.ByValTStr, SizeConst=128)] public string DeviceID;
        [MarshalAs(UnmanagedType.ByValTStr, SizeConst=128)] public string DeviceKey;
    }
    [DllImport("user32.dll", CharSet=CharSet.Ansi)] public static extern bool EnumDisplaySettings(string dev, int mode, ref DEVMODE dm);
    [DllImport("user32.dll", CharSet=CharSet.Ansi)] public static extern int ChangeDisplaySettingsEx(string dev, ref DEVMODE dm, IntPtr hwnd, int flags, IntPtr lParam);
    [DllImport("user32.dll", CharSet=CharSet.Ansi)] public static extern bool EnumDisplayDevices(string dev, uint n, ref DISPLAY_DEVICE dd, uint flags);
    public const int ENUM_CURRENT = -1; public const int CDS_UPDATEREGISTRY = 1; public const int CDS_TEST = 2;
    public const int ACTIVE = 1; public const int PRIMARY = 4;
}
'@
}
function _DisplayMode_Devices {
    _DisplayMode_Type
    $list = @(); $i = 0
    while ($true) {
        $dd = New-Object SRUndoDisplay+DISPLAY_DEVICE; $dd.cb = [Runtime.InteropServices.Marshal]::SizeOf($dd)
        if (-not [SRUndoDisplay]::EnumDisplayDevices($null, [uint32]$i, [ref]$dd, 0)) { break }
        if (($dd.StateFlags -band [SRUndoDisplay]::ACTIVE) -ne 0) {
            $list += , @{ name = [string]$dd.DeviceName; id = [string]$dd.DeviceID; primary = (($dd.StateFlags -band [SRUndoDisplay]::PRIMARY) -ne 0) }
        }
        $i++
    }
    return $list
}
function _DisplayMode_Current {
    param([string]$DeviceName)
    $m = New-Object SRUndoDisplay+DEVMODE; $m.dmSize = [Runtime.InteropServices.Marshal]::SizeOf($m)
    if (-not [SRUndoDisplay]::EnumDisplaySettings($DeviceName, [SRUndoDisplay]::ENUM_CURRENT, [ref]$m)) { throw "could not read the display mode of $DeviceName" }
    return $m
}
function _DisplayMode_Change {
    # the only place that changes the screen (tests replace this function)
    param([string]$DeviceName, $Mode, [int]$Flags)
    $m = $Mode
    return [SRUndoDisplay]::ChangeDisplaySettingsEx($DeviceName, [ref]$m, [IntPtr]::Zero, $Flags, [IntPtr]::Zero)
}
function _DisplayMode_ToState {
    param($Dev, $M)
    return @{ deviceName = [string]$Dev.name; deviceId = [string]$Dev.id; width = [int]$M.dmPelsWidth; height = [int]$M.dmPelsHeight
              bitsPerPel = [int]$M.dmBitsPerPel; frequency = [int]$M.dmDisplayFrequency; orientation = [int]$M.dmDisplayOrientation
              posX = [int]$M.dmPositionX; posY = [int]$M.dmPositionY; flags = [int]$M.dmDisplayFlags; fields = [int]$M.dmFields }
}
function Undo-DisplayMode-Capture {
    param([hashtable]$Params)
    $out = @{ type = 'DisplayMode'; v = 1; params = $Params; state = $null; ok = $false; error = $null; capturedAt = (Undo-Now) }
    try {
        $dev = @(_DisplayMode_Devices | Where-Object { $_.primary }) | Select-Object -First 1
        if (-not $dev) { throw 'no primary display was found' }
        $m = _DisplayMode_Current $dev.name
        $out.state = _DisplayMode_ToState $dev $m
        $out.ok = $true
    } catch { $out.error = "could not read the display mode: $($_.Exception.Message)" }
    return $out
}
function _DisplayMode_FindDevice {
    param([string]$Id, [string]$Name)
    $all = @(_DisplayMode_Devices)
    $hit = @($all | Where-Object { $_.id -eq $Id })
    if ($hit.Count -ge 1) {
        $same = @($hit | Where-Object { $_.name -eq $Name }); if ($same.Count -gt 0) { return $same[0] }
        return $hit[0]
    }
    return $null
}
function Undo-DisplayMode-Restore {
    param($Item)
    try {
        $st = ConvertTo-UndoPlain $Item['state']
        $dev = _DisplayMode_FindDevice ([string]$st['deviceId']) ([string]$st['deviceName'])
        if (-not $dev) { return @{ ok = $false; partial = $false; message = 'the display that was changed is not connected any more; open Windows display settings to pick a mode'; details = @() } }
        $m = _DisplayMode_Current $dev.name
        $cur = _DisplayMode_ToState $dev $m
        $same = ($cur.width -eq $st['width'] -and $cur.height -eq $st['height'] -and $cur.bitsPerPel -eq $st['bitsPerPel'] -and $cur.frequency -eq $st['frequency'] -and $cur.orientation -eq $st['orientation'] -and $cur.posX -eq $st['posX'] -and $cur.posY -eq $st['posY'])
        if ($same) { return @{ ok = $true; partial = $false; message = 'the display was already at its original mode'; details = @() } }
        $m.dmPelsWidth = [int]$st['width']; $m.dmPelsHeight = [int]$st['height']; $m.dmBitsPerPel = [int]$st['bitsPerPel']
        $m.dmDisplayFrequency = [int]$st['frequency']; $m.dmDisplayOrientation = [int]$st['orientation']
        $m.dmPositionX = [int]$st['posX']; $m.dmPositionY = [int]$st['posY']; $m.dmDisplayFlags = [int]$st['flags']
        $m.dmFields = [int]$st['fields']
        $t = _DisplayMode_Change $dev.name $m 2
        if ($t -ne 0) { return @{ ok = $false; partial = $false; message = "the monitor no longer offers the old mode ($($st['width'])x$($st['height']) at $($st['frequency']) Hz); open Windows display settings to pick one (Windows code $t)"; details = @() } }
        if ($script:SRUndoDisplayTestOnly) { return @{ ok = $true; partial = $false; message = 'test only: the old mode is accepted by the display, nothing was changed'; details = @() } }
        $r = _DisplayMode_Change $dev.name $m 1
        if ($r -ne 0) { return @{ ok = $false; partial = $false; message = "Windows did not accept the old display mode (code $r)"; details = @() } }
        return @{ ok = $true; partial = $false; message = "display set back to $($st['width'])x$($st['height']) at $($st['frequency']) Hz"; details = @() }
    } catch { return @{ ok = $false; partial = $false; message = "display mode: $($_.Exception.Message)"; details = @() } }
}
function Undo-DisplayMode-Verify {
    param($Item)
    try {
        $st = ConvertTo-UndoPlain $Item['state']
        $dev = _DisplayMode_FindDevice ([string]$st['deviceId']) ([string]$st['deviceName'])
        if (-not $dev) { return @{ matches = $false; diff = 'the display is not connected' } }
        $cur = _DisplayMode_ToState $dev (_DisplayMode_Current $dev.name)
        $diffs = @()
        foreach ($k in 'width', 'height', 'bitsPerPel', 'frequency', 'orientation', 'posX', 'posY') { if ([int]$cur[$k] -ne [int]$st[$k]) { $diffs += "$k is $($cur[$k]), was $($st[$k])" } }
        if ($diffs.Count -gt 0) { return @{ matches = $false; diff = ($diffs -join '; ') } }
        return @{ matches = $true; diff = '' }
    } catch { return @{ matches = $false; diff = "could not read the display mode: $($_.Exception.Message)" } }
}
function Undo-DisplayMode-Describe {
    param($Item)
    try { $s = $Item['state']; return "Screen mode: $($s['width'])x$($s['height']) at $($s['frequency']) Hz" } catch { return 'Screen mode' }
}
function Undo-DisplayMode-Validate {
    param($Item)
    try {
        $s = $Item['state']
        foreach ($k in 'width', 'height', 'bitsPerPel', 'frequency', 'orientation') {
            $v = 0
            if (-not [int]::TryParse([string]$s[$k], [ref]$v)) { return @{ valid = $false; reason = "$k is not a number" } }
        }
        if ([int]$s['width'] -lt 200 -or [int]$s['width'] -gt 20000 -or [int]$s['height'] -lt 200 -or [int]$s['height'] -gt 20000) { return @{ valid = $false; reason = 'resolution out of range' } }
        if ([int]$s['frequency'] -lt 20 -or [int]$s['frequency'] -gt 1000) { return @{ valid = $false; reason = 'refresh rate out of range' } }
        if ([int]$s['bitsPerPel'] -notin @(8, 16, 24, 32)) { return @{ valid = $false; reason = 'colour depth out of range' } }
        if ([string]$s['deviceName'] -notmatch '^\\\\\.\\DISPLAY\d{1,3}$') { return @{ valid = $false; reason = 'display name not allowed' } }
        return @{ valid = $true; reason = $null }
    } catch { return @{ valid = $false; reason = $_.Exception.Message } }
}

# ---- providers\DriverProfile.ps1 ----
if (-not $script:UndoProviders) { $script:UndoProviders = @{} }
# DriverProfile is a fail-closed boundary until a versioned DRS backend is available.
# No external importer, default reset, download or raw driver database write is used.
function _DriverProfile_Field { param($O,[string]$N,$D=$null) if($null -eq $O){return $D};if($O -is [Collections.IDictionary]){if($O.Contains($N)){return $O[$N]}}elseif($O.PSObject.Properties[$N]){return $O.$N};return $D }
function _DriverProfile_Canonical {
    param($O)
    if($null -eq $O){return 'null'}
    if($O -is [Collections.IDictionary]){
        $out=[ordered]@{};foreach($k in @($O.Keys | Sort-Object)){$out[[string]$k]=_DriverProfile_Canonical $O[$k]}
        return (ConvertTo-Json -InputObject $out -Depth 20 -Compress)
    }
    if($O -is [array]){return (ConvertTo-Json -InputObject @($O | ForEach-Object {_DriverProfile_Canonical $_}) -Depth 20 -Compress)}
    return (ConvertTo-Json -InputObject $O -Compress)
}
function _DriverProfile_Read {
    # A future native binding must return the complete typed/origin-aware profile graph,
    # driver fingerprint and application associations. This build has no verified binding.
    param($Params)
    throw 'Temporarily unavailable: undo for this tweak has not been verified on real NVIDIA hardware yet'
}
function _DriverProfile_Write {
    param($Original,$Params)
    throw 'No verified native driver-profile restore backend is installed. Do not use Restore Defaults as Undo.'
}
function _DriverProfile_ValidateGraph {
    param($State)
    if(-not $State.driverFingerprint -or $State.driverFingerprint.Length -gt 2048 -or [string]$State.driverFingerprint -match '[\x00-\x1F]'){throw 'Missing driver fingerprint.'}
    if($State.complete -ne $true -or $State.nativeFormat -ne 'TypedDrsV1'){throw 'The profile snapshot does not prove complete typed/origin coverage.'}
    if(@($State.profiles).Count -gt 10000){throw 'Too many profiles.'}
    $seen=@{}
    foreach($p in @($State.profiles)){
        if(-not $p.name -or ([string]$p.name).Length -gt 2048 -or [string]$p.name -match '[\x00-\x1F]' -or $seen.ContainsKey([string]$p.name)){throw 'Invalid or duplicate profile name.'};$seen[[string]$p.name]=$true
        if($p.predefined -isnot [bool]){throw 'Missing profile origin.'}
        $ids=@{}
        foreach($s in @($p.settings)){
            $id=[uint32]::Parse([string]$s.id)
            if($ids.ContainsKey([string]$id) -or $s.explicit -isnot [bool] -or $s.kind -notin @('Dword','String','Binary')){throw 'Invalid profile setting.'};$ids[[string]$id]=$true
            switch($s.kind){
                'Dword'{$null=[uint32]::Parse([string]$s.data)}
                'String'{if(([string]$s.data).Length -gt 1048576){throw 'Profile string too large.'}}
                'Binary'{$b=[Convert]::FromBase64String([string]$s.data);if($b.Length -gt 1048576){throw 'Profile binary value too large.'}}
            }
        }
        foreach($a in @($p.applications)){if([string]$a -match '[\x00-\x1F]' -or ([string]$a).Length -gt 32768){throw 'Invalid profile application association.'}}
    }
}
function Undo-DriverProfile-Capture {
    param([hashtable]$Params=@{})
    $r=@{type='DriverProfile';v=1;params=$Params;state=$null;ok=$false;error=$null;capturedAt=[datetime]::UtcNow.ToString('o')}
    try{
        if([string](_DriverProfile_Field $Params 'Scope' 'ControlledMerge') -notin @('ControlledMerge','FullDatabase')){throw 'Unsupported profile scope.'}
        $r.state=_DriverProfile_Read $Params;_DriverProfile_ValidateGraph $r.state;$r.ok=$true
    }catch{$r.error=$_.Exception.Message};return $r
}
function Undo-DriverProfile-Validate {
    param($Item)
    try{
        if($Item.type -ne 'DriverProfile' -or [int]$Item.v -ne 1 -or $Item.ok -ne $true){throw 'Invalid driver profile envelope.'}
        if([string](_DriverProfile_Field $Item.params 'Scope' 'ControlledMerge') -notin @('ControlledMerge','FullDatabase')){throw 'Invalid profile scope.'}
        _DriverProfile_ValidateGraph $Item.state;return @{valid=$true;reason=''}
    }catch{return @{valid=$false;reason=$_.Exception.Message}}
}
function Undo-DriverProfile-Verify {
    param($Item)
    try{
        $v=Undo-DriverProfile-Validate $Item;if(-not $v.valid){throw $v.reason}
        $now=_DriverProfile_Read $Item.params;_DriverProfile_ValidateGraph $now
        if($now.driverFingerprint -ne $Item.state.driverFingerprint){throw 'The graphics driver changed; the saved profile was not written.'}
        $same=(_DriverProfile_Canonical $now) -ceq (_DriverProfile_Canonical $Item.state)
        return @{matches=$same;diff=$(if($same){''}else{'Driver profile settings, explicit overrides or application associations differ.'})}
    }catch{return @{matches=$false;diff=$_.Exception.Message}}
}
function Undo-DriverProfile-Restore {
    param($Item)
    try{
        $v=Undo-DriverProfile-Validate $Item;if(-not $v.valid){throw $v.reason}
        $now=_DriverProfile_Read $Item.params;_DriverProfile_ValidateGraph $now
        if($now.driverFingerprint -ne $Item.state.driverFingerprint){throw 'The driver changed; automatic profile recovery was refused.'}
        if((_DriverProfile_Canonical $now) -ceq (_DriverProfile_Canonical $Item.state)){return @{ok=$true;partial=$false;message='Profiles are already original.';details=@()}}
        _DriverProfile_Write $Item.state $Item.params
        $check=Undo-DriverProfile-Verify $Item
        return @{ok=[bool]$check.matches;partial=$false;message=$(if($check.matches){'Saved original profiles restored.'}else{$check.diff});details=@(@{target='Driver profiles';ok=[bool]$check.matches})}
    }catch{return @{ok=$false;partial=$false;message=$_.Exception.Message;details=@()}}
}
function Undo-DriverProfile-Describe { param($Item) return 'Driver profiles: exact recovery requires a verified native profile snapshot; interactive imports are blocked when unavailable.' }
$script:UndoProviders['DriverProfile']=@{Capture='Undo-DriverProfile-Capture';Restore='Undo-DriverProfile-Restore';Verify='Undo-DriverProfile-Verify';Describe='Undo-DriverProfile-Describe';Validate='Undo-DriverProfile-Validate';VerifySeesApply = $false; Version=1}

# ---- providers\EnvVar.ps1 ----
# StreamReady undo engine - provider: EnvVar (a persistent environment variable, machine or user scope)
# Plain function definitions plus one registration. Dot-source safe. ASCII only.
#
# Params (hashtable):  Name (required), Scope ('Machine' or 'User', default 'Machine')
# State: existed, kind ('String' or 'ExpandString'), data (the RAW text exactly as stored, unexpanded)
# The value is read and written in the registry so that the type (String or ExpandString) and any %VARIABLE% text are
# kept exactly. After a restore a "settings changed" message is broadcast so Explorer and new programs re-read it.
# Programs that are already running keep their old environment until they are restarted.

if ($null -eq $script:UndoProviders) { $script:UndoProviders = @{} }
$script:UndoProviders['EnvVar'] = @{ Capture = 'Undo-EnvVar-Capture'; Restore = 'Undo-EnvVar-Restore'; Verify = 'Undo-EnvVar-Verify'; Describe = 'Undo-EnvVar-Describe'; Validate = 'Undo-EnvVar-Validate'; VerifySeesApply = $true; Version = 1 }

function _Env_Now { return (Get-Date).ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ssZ') }
function _Env_ValidName { param($N) return ([string]$N -match '^[A-Za-z_][A-Za-z0-9_.\-]{0,254}$') }
function _Env_Scope { param($P) if ($P -and $P.Scope) { return [string]$P.Scope } return 'Machine' }
function _Env_Key {
    param([string]$Scope)
    if ($Scope -eq 'Machine') { return 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Environment' }
    if ($Scope -eq 'User') { return 'HKCU:\Environment' }
    throw "unknown scope '$Scope'"
}

function _Env_Read {
    param([string]$Name, [string]$Scope)
    $key = _Env_Key $Scope
    $r = @{ existed = $false; kind = $null; data = $null }
    if (-not (Test-Path -LiteralPath $key)) { return $r }
    $k = Get-Item -LiteralPath $key -ErrorAction Stop
    if (@($k.GetValueNames()) -notcontains $Name) { return $r }
    $kind = [string]$k.GetValueKind($Name)
    if ($kind -notin @('String', 'ExpandString')) { throw "the stored type is $kind, which an environment variable should not have; it is not changed automatically" }
    $r.existed = $true
    $r.kind = $kind
    $r.data = [string]$k.GetValue($Name, $null, [Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames)
    return $r
}

function _Env_Broadcast {
    if (-not ('SrUndoEnvApi' -as [type])) {
        $src = @'
using System;
using System.Runtime.InteropServices;
public static class SrUndoEnvApi {
    [DllImport("user32.dll", CharSet = CharSet.Unicode, SetLastError = true)]
    public static extern IntPtr SendMessageTimeout(IntPtr hWnd, uint Msg, UIntPtr wParam, string lParam, uint fuFlags, uint uTimeout, out UIntPtr lpdwResult);
}
'@
        Add-Type -TypeDefinition $src -ErrorAction Stop
    }
    [UIntPtr]$res = [UIntPtr]::Zero
    $rc = [SrUndoEnvApi]::SendMessageTimeout([IntPtr]0xffff, 0x001A, [UIntPtr]::Zero, 'Environment', 0x0002, 3000, [ref]$res)
    return ($rc -ne [IntPtr]::Zero)
}

function Undo-EnvVar-Capture {
    param($Params)
    $res = @{ type = 'EnvVar'; v = 1; params = $Params; state = $null; ok = $false; error = $null; capturedAt = (_Env_Now) }
    try {
        if ($null -eq $Params -or -not (_Env_ValidName $Params.Name)) { throw 'the variable name is missing or has characters that are not allowed' }
        $scope = _Env_Scope $Params
        if ($scope -notin @('Machine', 'User')) { throw "scope '$scope' is not supported" }
        $st = _Env_Read ([string]$Params.Name) $scope
        $st.name = [string]$Params.Name
        $st.scope = $scope
        $res.state = $st
        $res.ok = $true
    } catch { $res.error = "Could not record the original environment variable '$($Params.Name)': $($_.Exception.Message)" }
    return $res
}

function Undo-EnvVar-Validate {
    param($Item)
    try {
        if ($null -eq $Item -or [string]$Item.type -ne 'EnvVar') { return @{ valid = $false; reason = 'not an EnvVar record' } }
        $s = $Item.state
        if ($null -eq $s) { return @{ valid = $false; reason = 'no state' } }
        if (-not (_Env_ValidName $s.name) -or [string]$s.name -ne [string]$Item.params.Name) { return @{ valid = $false; reason = 'name is not valid or does not match the parameters' } }
        if ([string]$s.scope -notin @('Machine', 'User') -or [string]$s.scope -ne (_Env_Scope $Item.params)) { return @{ valid = $false; reason = 'scope is not valid or does not match the parameters' } }
        if ($s.existed -isnot [bool]) { return @{ valid = $false; reason = 'existed must be true or false' } }
        if ($s.existed) {
            if ([string]$s.kind -notin @('String', 'ExpandString')) { return @{ valid = $false; reason = 'kind must be String or ExpandString' } }
            if ($null -eq $s.data) { return @{ valid = $false; reason = 'no data' } }
            if (([string]$s.data).Length -gt 32767) { return @{ valid = $false; reason = 'data is too long' } }
        }
        return @{ valid = $true; reason = $null }
    } catch { return @{ valid = $false; reason = $_.Exception.Message } }
}

function Undo-EnvVar-Describe {
    param($Item)
    try {
        $s = $Item.state
        if (-not $s.existed) { return "$($s.scope) environment variable $($s.name): not set" }
        $d = [string]$s.data
        if ($d.Length -gt 60) { $d = $d.Substring(0, 57) + '...' }
        return "$($s.scope) environment variable $($s.name) = $d"
    } catch { return 'Environment variable (record could not be read)' }
}

function Undo-EnvVar-Verify {
    param($Item)
    try {
        $s = $Item.state
        $cur = _Env_Read ([string]$s.name) ([string]$s.scope)
        if (-not $s.existed) { return @{ matches = (-not $cur.existed); diff = $(if ($cur.existed) { "the variable is set now, was not set" } else { '' }) } }
        if (-not $cur.existed) { return @{ matches = $false; diff = 'the variable is not set now, was set' } }
        $d = New-Object System.Collections.ArrayList
        if ($cur.kind -ne [string]$s.kind) { [void]$d.Add("type is $($cur.kind), was $($s.kind)") }
        if ($cur.data -cne [string]$s.data) { [void]$d.Add('the text is different') }
        return @{ matches = ($d.Count -eq 0); diff = ($d.ToArray() -join '; ') }
    } catch { return @{ matches = $false; diff = "could not read the variable: $($_.Exception.Message)" } }
}

function Undo-EnvVar-Restore {
    param($Item)
    $details = New-Object System.Collections.ArrayList
    $add = { param($part, $ok, $msg) [void]$details.Add(@{ part = $part; ok = $ok; message = $msg }) }
    try {
        $val = Undo-EnvVar-Validate $Item
        if (-not $val.valid) { return @{ ok = $false; partial = $false; message = "Refused: the saved environment variable record is not valid ($($val.reason))."; details = @() } }
        $s = $Item.state
        $name = [string]$s.name; $scope = [string]$s.scope
        $key = _Env_Key $scope
        $cur = _Env_Read $name $scope
        if ($s.existed) {
            $same = $cur.existed -and ($cur.kind -eq [string]$s.kind) -and ($cur.data -ceq [string]$s.data)
            if ($same) { & $add 'value' $true 'already the original value' }
            else {
                if (-not (Test-Path -LiteralPath $key)) { New-Item -Path $key -Force -ErrorAction Stop | Out-Null }
                Set-ItemProperty -LiteralPath $key -Name $name -Value ([string]$s.data) -Type ([string]$s.kind) -ErrorAction Stop
                & $add 'value' $true "set back ($($s.kind))"
            }
        } else {
            if ($cur.existed) { Remove-ItemProperty -LiteralPath $key -Name $name -ErrorAction Stop; & $add 'value' $true 'removed again (it was not set before)' }
            else { & $add 'value' $true 'was not set before and is not set now' }
        }
        $note = ''
        try { if (-not (_Env_Broadcast)) { $note = ' The change could not be announced to open programs; they will see it after they are restarted.' } } catch { $note = ' The change could not be announced to open programs; they will see it after they are restarted.' }
        $v = Undo-EnvVar-Verify $Item
        if (-not $v.matches) { & $add 'verify' $false $v.diff; return @{ ok = $false; partial = $true; message = "The environment variable could not be fully put back: $($v.diff)"; details = @($details.ToArray()) } }
        return @{ ok = $true; partial = $false; message = "The $scope environment variable $name was put back to what it was before. Programs that are already open will use it after they are restarted.$note"; details = @($details.ToArray()) }
    } catch {
        return @{ ok = $false; partial = $false; message = "Could not put the environment variable back: $($_.Exception.Message)"; details = @($details.ToArray()) }
    }
}

# ---- providers\FileSnapshot.ps1 ----
if (-not $script:UndoProviders) { $script:UndoProviders = @{} }
# File snapshots. Capture reads only. Prepare is a core pre-persist hook.
function _FileSnapshot_Field { param($O,[string]$N,$D=$null) if($null -eq $O){return $D};if($O -is [Collections.IDictionary]){if($O.Contains($N)){return $O[$N]}}elseif($O.PSObject.Properties[$N]){return $O.$N};return $D }
function _FileSnapshot_Hash { param([byte[]]$Bytes) $h=[Security.Cryptography.SHA256]::Create();try{return ([BitConverter]::ToString($h.ComputeHash($Bytes))).Replace('-','')}finally{$h.Dispose()} }
function _FileSnapshot_Path {
    param([string]$Path)
    if([string]::IsNullOrWhiteSpace($Path) -or $Path -notmatch '^[A-Za-z]:\\' -or $Path -match '[\x00-\x1F*?]' -or $Path.Substring(2).Contains(':')){throw 'A local literal absolute path is required.'}
    $p=[IO.Path]::GetFullPath($Path).TrimEnd('\');$drive=New-Object IO.DriveInfo($p.Substring(0,3));if($drive.DriveType -eq [IO.DriveType]::Network){throw 'Network snapshot paths are not supported.'};if($p.Length -le 3){throw 'A drive root is not a snapshot target.'};return $p
}
function _FileSnapshot_NoLinks {
    param([string]$Path)
    while($Path -and $Path.Length -gt 3){
        if(Test-Path -LiteralPath $Path -ErrorAction Stop){if((Get-Item -LiteralPath $Path -Force -ErrorAction Stop).Attributes -band [IO.FileAttributes]::ReparsePoint){throw "A link is not an allowed snapshot path: $Path"}}
        $Path=Split-Path -Path $Path -Parent
    }
}
function _FileSnapshot_Under { param([string]$Path,[string]$Root) return ($Path.Equals($Root,[StringComparison]::OrdinalIgnoreCase) -or $Path.StartsWith($Root.TrimEnd('\')+'\',[StringComparison]::OrdinalIgnoreCase)) }
function _FileSnapshot_Paths {
    param($Params)
    $paths=@(_FileSnapshot_Field $Params 'Paths' @());if(-not $paths.Count){$p=_FileSnapshot_Field $Params 'Path';if($p){$paths=@($p)}}
    if($paths.Count -lt 1 -or $paths.Count -gt 128){throw 'Specify one to 128 file targets.'}
    $out=@();foreach($p in $paths){$p=_FileSnapshot_Path $p;if($out -contains $p){throw 'Duplicate file target.'};$out+=,$p}
    foreach($p in $out){foreach($q in $out){if($p -ne $q -and (_FileSnapshot_Under $p $q)){throw 'Snapshot roots must not overlap.'}}};return ,$out
}
function _FileSnapshot_ReadStream {
    param([string]$Path,[string]$Name)
    if(-not $Name){return ,([IO.File]::ReadAllBytes($Path))}
    return ,([byte[]]@(Get-Content -LiteralPath $Path -Stream $Name -Encoding Byte -ErrorAction Stop))
}
function _FileSnapshot_WriteStream {
    param([string]$Path,[string]$Name,[byte[]]$Bytes)
    if(-not $Name){[IO.File]::WriteAllBytes($Path,$Bytes)}else{Set-Content -LiteralPath $Path -Stream $Name -Encoding Byte -Value $Bytes -Force -ErrorAction Stop}
}
function _FileSnapshot_BackupRoot { if(Get-Command Undo-FilesRoot -ErrorAction SilentlyContinue){return (Undo-FilesRoot)};return (Join-Path $env:ProgramData 'StreamReady\undo-files') }
function _FileSnapshot_BackupAncestors {
    $base=[IO.Path]::GetFullPath((_FileSnapshot_BackupRoot)).TrimEnd('\')
    $production=[IO.Path]::GetFullPath((Join-Path $env:ProgramData 'StreamReady\undo-files')).TrimEnd('\')
    # Overrides come from the in-process core test harness, never from a saved record.
    if($base -ne $production){return}
    foreach($path in @((Split-Path $base -Parent),$base)){
        _FileSnapshot_NoLinks $path
        if(-not(Test-Path -LiteralPath $path -PathType Container -ErrorAction Stop)){throw 'The protected backup root is not initialized.'}
        $acl=Get-Acl -LiteralPath $path -ErrorAction Stop
        if($acl.GetOwner([Security.Principal.SecurityIdentifier]).Value -notin @('S-1-5-32-544','S-1-5-18')){throw 'The backup ancestor has an untrusted owner.'}
        $write=[int]([Security.AccessControl.FileSystemRights]::Write -bor [Security.AccessControl.FileSystemRights]::Delete -bor [Security.AccessControl.FileSystemRights]::ChangePermissions -bor [Security.AccessControl.FileSystemRights]::TakeOwnership)
        foreach($r in $acl.Access){
            if($r.AccessControlType -eq 'Allow' -and $r.IdentityReference.Translate([Security.Principal.SecurityIdentifier]).Value -notin @('S-1-5-32-544','S-1-5-18') -and ([int]$r.FileSystemRights -band $write)){throw 'The backup ancestor is writable by an untrusted account.'}
        }
    }
}
function _FileSnapshot_SharedRoot {
    param($Params)
    $root=[string](_FileSnapshot_Field $Params 'SharedRoot' '')
    if(-not $root){
        foreach($p in (_FileSnapshot_Paths $Params)){
            foreach($leaf in @('StreamReady','StreamReady-OSS')){
                $candidate=Join-Path $env:ProgramData $leaf
                if($p -in @((Join-Path $candidate 'SetTimerRes.ps1'))){$root=$candidate}
            }
        }
    }
    if($root){
        $root=_FileSnapshot_Path $root
        if(-not(Test-Path -LiteralPath $root -PathType Container -ErrorAction Stop)){throw 'Initialize the protected helper root before capture; no helper change was made.'}
        if(-not(Get-Command Test-SrTreeTrusted -ErrorAction SilentlyContinue) -or -not(Test-SrTreeTrusted -Path $root)){throw 'The helper root is not trusted. It must not be cleared because that could erase recovery data.'}
        foreach($p in (_FileSnapshot_Paths $Params)){if(-not(_FileSnapshot_Under $p $root)){throw 'A shared-root file is outside the protected helper tree.'}}
    }
}
function _FileSnapshot_LockBackupDirectory {
    param([string]$Path,[bool]$New)
    $admins=New-Object Security.Principal.SecurityIdentifier('S-1-5-32-544')
    $system=New-Object Security.Principal.SecurityIdentifier('S-1-5-18')
    if($true){
        $acl=New-Object Security.AccessControl.DirectorySecurity
        $acl.SetOwner($admins);$acl.SetAccessRuleProtection($true,$false)
        foreach($sid in @($admins,$system)){
            $rule=New-Object Security.AccessControl.FileSystemAccessRule($sid,'FullControl','ContainerInherit,ObjectInherit','None','Allow')
            $acl.AddAccessRule($rule)
        }
        Set-Acl -LiteralPath $Path -AclObject $acl -ErrorAction Stop
    }
    $acl=Get-Acl -LiteralPath $Path -ErrorAction Stop
    if($acl.GetOwner([Security.Principal.SecurityIdentifier]).Value -notin @($admins.Value,$system.Value)){throw 'The backup folder has an untrusted owner.'}
    $write=[int]([Security.AccessControl.FileSystemRights]::Write -bor [Security.AccessControl.FileSystemRights]::Delete -bor [Security.AccessControl.FileSystemRights]::ChangePermissions -bor [Security.AccessControl.FileSystemRights]::TakeOwnership)
    foreach($r in $acl.Access){
        if($r.AccessControlType -eq 'Allow' -and $r.IdentityReference.Translate([Security.Principal.SecurityIdentifier]).Value -notin @($admins.Value,$system.Value) -and ([int]$r.FileSystemRights -band $write)){throw 'The backup directory permits writes by an untrusted account.'}
    }
}
function _FileSnapshot_Meta {
    param([string]$Path,[string]$Relative,[long]$Limit=524288000)
    _FileSnapshot_NoLinks $Path
    $it=Get-Item -LiteralPath $Path -Force -ErrorAction Stop
    $unsupported=512 -bor 1024 -bor 2048 -bor 4096 -bor 16384 -bor 32768 -bor 131072 -bor 262144 -bor 524288 -bor 1048576 -bor 4194304
    if([int]$it.Attributes -band $unsupported){throw 'Sparse, compressed, encrypted, offline or linked data needs a different backup method.'}
    if($it.PSObject.Properties['LinkType'] -and $it.LinkType -eq 'HardLink'){throw 'Hard-link topology cannot be restored by a file copy.'}
    $sections=[Security.AccessControl.AccessControlSections]::Access -bor [Security.AccessControl.AccessControlSections]::Owner -bor [Security.AccessControl.AccessControlSections]::Group
    $e=@{relative=$Relative;directory=[bool]$it.PSIsContainer;attributes=[int]$it.Attributes;creationUtc=$it.CreationTimeUtc.ToString('o');lastWriteUtc=$it.LastWriteTimeUtc.ToString('o');sddl=(Get-Acl -LiteralPath $Path -ErrorAction Stop).GetSecurityDescriptorSddlForm($sections);streams=@()}
    if(-not $it.PSIsContainer){
        foreach($s in @(Get-Item -LiteralPath $Path -Stream * -ErrorAction Stop)){
            $name=[string]$s.Stream;if($name -eq ':$DATA'){$read=$Path;$name=''}else{$read=$Path+':'+$name}
            if($name -match '[:\\/\x00-\x1F]'){throw 'Unsupported alternate stream name.'}
            if([long]$s.Length -gt $Limit){throw 'A stream exceeds the remaining snapshot budget.'}
            $data=_FileSnapshot_ReadStream $Path $name;$Limit-=$data.Length
            $e.streams+=,@{name=$name;length=[long]$data.Length;sha256=(_FileSnapshot_Hash $data);contentBase64=[Convert]::ToBase64String($data)}
        }
        if(@($e.streams | Where-Object {$_.name -eq ''}).Count -ne 1){throw 'The unnamed stream could not be captured.'}
    };return $e
}
function _FileSnapshot_Read {
    param($Params)
    $paths=_FileSnapshot_Paths $Params;$max=[long](_FileSnapshot_Field $Params 'MaxBytes' 524288000)
    if($max -lt 0 -or $max -gt 2147483648){throw 'Snapshot size limit is invalid.'}
    $roots=@();$total=0L;$count=0
    foreach($p in $paths){
        _FileSnapshot_NoLinks $p
        $r=@{path=$p;existed=[bool](Test-Path -LiteralPath $p -ErrorAction Stop);entries=@();missingParents=@()}
        if(-not $r.existed){
            $q=Split-Path $p -Parent
            while($q -and $q.Length -gt 3 -and -not(Test-Path -LiteralPath $q -ErrorAction Stop)){$r.missingParents+=,$q;$q=Split-Path $q -Parent}
        }else{
            $stack=New-Object 'Collections.Generic.Stack[string]';$stack.Push($p)
            while($stack.Count){
                $f=$stack.Pop();$rel=if($f -eq $p){''}else{$f.Substring($p.Length+1)}
                $e=_FileSnapshot_Meta $f $rel ($max-$total);$count++;if($count -gt 20000){throw 'Too many files for this snapshot.'}
                foreach($s in $e.streams){$total+=[long]$s.length;if($total -gt $max){throw 'Snapshot exceeds its size limit.'}}
                $r.entries+=,$e
                if($e.directory){foreach($child in @(Get-ChildItem -LiteralPath $f -Force -ErrorAction Stop)){$stack.Push($child.FullName)}}
            };$r.entries=@($r.entries | Sort-Object relative)
        };$roots+=,$r
    };return @{roots=$roots;totalBytes=$total}
}
function _FileSnapshot_SddlNorm {
    # Verdict only: the auto-inherited (AI) and auto-inheritance-required (AR) DACL control flags are bookkeeping that Windows sets on its own
    # when a descriptor is applied; they do not change who can access the file. Everything else (owner, group, protected flag, every ACE in order) stays exact.
    param([string]$Sddl)
    if(-not $Sddl){return ''}
    return [regex]::Replace($Sddl,'D:((?:P|AR|AI|NO_ACCESS_CONTROL)*)',{param($m) 'D:'+$(if($m.Groups[1].Value -match 'P'){'P'}else{''})},'None')
}
function _FileSnapshot_Comparable {
    param($State)
    $parts=@();foreach($r in @($State.roots)){
        $parts+=("$($r.path.ToLowerInvariant())|$($r.existed)")
        foreach($e in @($r.entries)){$parts+=("$($e.relative)|$($e.directory)|$($e.attributes)|$(_FileSnapshot_SddlNorm $e.sddl)|$($e.creationUtc)|$($e.lastWriteUtc)");foreach($s in @($e.streams)){$parts+=("$($s.name)|$($s.length)|$($s.sha256)")}}
    };return ($parts -join [Environment]::NewLine)
}
function _FileSnapshot_Bytes {
    param($Stream,$Params)
    $backup=[string](_FileSnapshot_Field $Stream 'backupPath' '')
    if($backup){
        $id=[guid]::Parse([string](_FileSnapshot_Field $Params '_recordId'))
        $expected=[IO.Path]::GetFullPath((Join-Path (_FileSnapshot_BackupRoot) $id.ToString())).TrimEnd('\')
        if([string](_FileSnapshot_Field $Params '_filesDir') -ne $expected){throw 'Unexpected record backup directory.'}
        $path=_FileSnapshot_Path $backup
        if((Split-Path $path -Parent) -ne $expected -or (Split-Path $path -Leaf) -notmatch '^file-\d+-\d+\.bin$'){throw 'Backup path is outside the record blob namespace.'}
        _FileSnapshot_NoLinks $path;$bytes=[IO.File]::ReadAllBytes($path)
    }else{
        $base64=_FileSnapshot_Field $Stream 'contentBase64'
        if($null -eq $base64){throw 'File backup data is missing.'}
        $bytes=[Convert]::FromBase64String([string]$base64)
    }
    if($bytes.Length -ne [long]$Stream.length -or (_FileSnapshot_Hash $bytes) -ne $Stream.sha256){throw 'A file backup failed its length or hash check.'}
    return ,$bytes
}
function Undo-FileSnapshot-Capture {
    param([hashtable]$Params=@{})
    $r=@{type='FileSnapshot';v=1;params=$Params;state=$null;ok=$false;error=$null;capturedAt=[datetime]::UtcNow.ToString('o')}
    try{_FileSnapshot_SharedRoot $Params;$r.state=_FileSnapshot_Read $Params;$r.ok=$true}catch{$r.error="Could not record the original files: $($_.Exception.Message)"};return $r
}
function _FileSnapshot_EntryIdentity {
    param($Entry)
    return (_FileSnapshot_Hash ([Text.Encoding]::UTF8.GetBytes(([string]$Entry.directory+'|'+[string]$Entry.creationUtc+'|'+[string]$Entry.attributes+'|'+[string]$Entry.sddl))))
}
function _FileSnapshot_EntryFingerprint {
    param($Entry)
    $parts=@([string]$Entry.directory,[string]$Entry.attributes,[string]$Entry.sddl,[string]$Entry.creationUtc,[string]$Entry.lastWriteUtc)
    foreach($s in @($Entry.streams | Sort-Object name)){$parts+=([string]$s.name+'|'+[string]$s.length+'|'+[string]$s.sha256)}
    return (_FileSnapshot_Hash ([Text.Encoding]::UTF8.GetBytes(($parts -join [Environment]::NewLine))))
}
function _FileSnapshot_ValidateCreated {
    param($Item)
    if(-not $Item.state.ContainsKey('createdManifest')){return}
    $manifest=@($Item.state.createdManifest)
    if($manifest.Count -ne @($Item.state.roots).Count){throw 'Created-file manifest has the wrong roots.'}
    for($i=0;$i -lt $manifest.Count;$i++){
        $m=$manifest[$i];$root=$Item.state.roots[$i]
        if($m.path -ne $root.path -or @($m.entries).Count -gt 20000){throw 'Created-file manifest changed target.'}
        $seen=@{}
        foreach($e in @($m.entries)){
            $rel=[string]$e.relative
            if($rel -match '(^|\\)\.\.?($|\\)|[/:\x00-\x1F*?]|^\\' -or $seen.ContainsKey($rel)){throw 'Unsafe created-file relative path.'}
            if(@($root.entries | Where-Object {$_.relative -eq $rel}).Count){throw 'An original file cannot be marked created.'}
            $seen[$rel]=$true
            if($e.directory -isnot [bool] -or [string]$e.fingerprint -notmatch '^[0-9A-Fa-f]{64}$' -or [string]$e.identityFingerprint -notmatch '^[0-9A-Fa-f]{64}$'){throw 'Invalid created-file evidence.'}
            $path=if($rel){Join-Path $root.path $rel}else{$root.path}
            if(-not(_FileSnapshot_Under (_FileSnapshot_Path $path) $root.path)){throw 'Created file escaped its snapshot root.'}
        }
    }
}
function Undo-FileSnapshot-AfterApply {
    # Core must call and persist this after a synchronous action, also before rollback of a failed action.
    param($Item)
    try{
        $v=Undo-FileSnapshot-Validate $Item;if(-not $v.valid){throw $v.reason}
        if($Item.state.ContainsKey('createdManifest')){throw 'A completed creation manifest must not be overwritten by reapply.'}
        $now=_FileSnapshot_Read $Item.params;$manifest=@()
        for($i=0;$i -lt @($Item.state.roots).Count;$i++){
            $root=$Item.state.roots[$i];$entries=@()
            foreach($entry in @($now.roots[$i].entries)){
                if(-not @($root.entries | Where-Object {$_.relative -eq $entry.relative}).Count){
                    $entries+=,@{relative=$entry.relative;directory=[bool]$entry.directory;fingerprint=(_FileSnapshot_EntryFingerprint $entry);identityFingerprint=(_FileSnapshot_EntryIdentity $entry)}
                }
            };$manifest+=,@{path=$root.path;entries=$entries}
        }
        $Item.state['createdManifest']=$manifest;_FileSnapshot_ValidateCreated $Item
        return @{ok=$true;message='Created file names and fingerprints recorded.'}
    }catch{return @{ok=$false;message=$_.Exception.Message}}
}
function _FileSnapshot_RemoveCreated {
    param($Item,$Root)
    if(-not $Item.state.ContainsKey('createdManifest')){return}
    $manifest=@($Item.state.createdManifest | Where-Object {$_.path -eq $Root.path})
    if($manifest.Count -ne 1){throw 'Missing created-file manifest root.'}
    $errors=@()
    foreach($e in @($manifest[0].entries | Sort-Object @{Expression={$_.relative.Length};Descending=$true})){
        try{
            $path=if($e.relative){Join-Path $Root.path $e.relative}else{$Root.path}
            _FileSnapshot_NoLinks $path
            if(-not(Test-Path -LiteralPath $path -ErrorAction Stop)){continue}
            $current=Get-Item -LiteralPath $path -Force -ErrorAction Stop
            if([bool]$current.PSIsContainer -ne [bool]$e.directory){throw 'Created target changed file type; it was preserved.'}
            if($e.directory){
                $meta=_FileSnapshot_Meta $path $e.relative 0
                if((_FileSnapshot_EntryIdentity $meta) -ne $e.identityFingerprint){throw 'Created directory identity changed; it was preserved.'}
                if(@(Get-ChildItem -LiteralPath $path -Force -ErrorAction Stop).Count){throw 'Created directory holds unknown later data; it was preserved.'}
            }else{
                $meta=_FileSnapshot_Meta $path $e.relative ([long](_FileSnapshot_Field $Item.params 'MaxBytes' 524288000))
                if((_FileSnapshot_EntryFingerprint $meta) -ne $e.fingerprint){throw 'Created file changed after the action; it was preserved.'}
            }
            # Never recurse: remove only an unchanged recorded file or empty recorded directory.
            Remove-Item -LiteralPath $path -Force -ErrorAction Stop
        }catch{$errors+=,$_.Exception.Message}
    };return $errors
}
function Undo-FileSnapshot-Validate {
    param($Item)
    try{
        if($Item.type -ne 'FileSnapshot' -or [int]$Item.v -ne 1 -or $Item.ok -ne $true){throw 'Invalid file snapshot envelope.'}
        $paths=_FileSnapshot_Paths $Item.params;if(@($Item.state.roots).Count -ne $paths.Count){throw 'Snapshot targets do not match the plan.'}
        $bytes=0L
        for($i=0;$i -lt $paths.Count;$i++){
            $r=$Item.state.roots[$i];if($r.path -ne $paths[$i] -or $r.existed -isnot [bool]){throw 'Snapshot target changed.'}
            if(-not $r.existed -and @($r.entries).Count){throw 'An absent target has entries.'};$seen=@{}
            foreach($e in @($r.entries)){
                $rel=[string]$e.relative
                if($rel.Contains('/') -or $rel -match '(^|\\)\.\.?($|\\)|^[\\/]|:|[\x00-\x1F*?]' -or $seen.ContainsKey($rel)){throw 'Unsafe or duplicate relative path.'};$seen[$rel]=$true
                if($e.directory -isnot [bool]){throw 'Invalid file type.'}
                $attr=[int]$e.attributes;if($attr -band (64 -bor 512 -bor 1024 -bor 2048 -bor 4096 -bor 16384 -bor 32768 -bor 131072 -bor 262144 -bor 524288 -bor 1048576 -bor 4194304)){throw 'Unsupported file attributes.'}
                if($e.sddl){$sd=New-Object Security.AccessControl.RawSecurityDescriptor([string]$e.sddl)}
                $null=[datetime]::Parse([string]$e.creationUtc);$null=[datetime]::Parse([string]$e.lastWriteUtc);$names=@{}
                foreach($s in @($e.streams)){
                    if([string]$s.name -match '[:\\/\x00-\x1F]' -or $names.ContainsKey([string]$s.name)){throw 'Invalid stream name.'};$names[[string]$s.name]=$true
                    $data=_FileSnapshot_Bytes $s $Item.params
                    if($data.Length -ne [long]$s.length -or (_FileSnapshot_Hash $data) -ne $s.sha256){throw 'A file backup failed its hash check.'};$bytes+=$data.Length
                }
                if(-not $e.directory -and -not $names.ContainsKey('')){throw 'Missing unnamed stream.'}
            }
            if($r.existed -and -not $seen.ContainsKey('')){throw 'Missing snapshot root.'}
            foreach($parent in @($r.missingParents)){$q=_FileSnapshot_Path $parent;if(-not(_FileSnapshot_Under (Split-Path $r.path -Parent) $q)){throw 'Invalid created parent.'}}
        }
        _FileSnapshot_ValidateCreated $Item
        if($bytes -gt [long](_FileSnapshot_Field $Item.params 'MaxBytes' 524288000)){throw 'Backup exceeds size limit.'};return @{valid=$true;reason=''}
    }catch{return @{valid=$false;reason=$_.Exception.Message}}
}
function Undo-FileSnapshot-Prepare {
    # Core calls this after ALL read-only captures and before committing the record.
    param($Item)
    try{
        $v=Undo-FileSnapshot-Validate $Item;if(-not $v.valid){throw $v.reason}
        $dir=[string](_FileSnapshot_Field $Item.params '_filesDir');$id=[string](_FileSnapshot_Field $Item.params '_recordId')
        if($id -notmatch '^[0-9a-fA-F-]{36}$' -or -not $dir){throw 'The core must supply the record backup directory.'}
        $parsedId=[guid]::Parse($id);$index=[int](_FileSnapshot_Field $Item.params '_index' 0);if($index -lt 0){throw 'Invalid backup item index.'}
        $dir=_FileSnapshot_Path $dir
        $expected=[IO.Path]::GetFullPath((Join-Path (_FileSnapshot_BackupRoot) $id)).TrimEnd('\')
        if($dir -ne $expected){throw 'Backup path is outside the record store.'}
        _FileSnapshot_NoLinks $dir
        if(Get-Command Undo-EnsureDir -ErrorAction SilentlyContinue){if(-not(Undo-EnsureDir (_FileSnapshot_BackupRoot))){throw 'The backup root could not be initialized.'}}
        _FileSnapshot_BackupAncestors
        foreach($r in @($Item.state.roots)){if(_FileSnapshot_Under $dir $r.path){throw 'Apply could erase its own backup; isolate the helper first.'}}
        $newDir=-not(Test-Path -LiteralPath $dir -ErrorAction Stop);[void][IO.Directory]::CreateDirectory($dir);_FileSnapshot_LockBackupDirectory $dir $newDir;$n=0
        foreach($r in @($Item.state.roots)){foreach($e in @($r.entries)){foreach($s in @($e.streams)){
            $n++;if(_FileSnapshot_Field $s 'backupPath'){continue};$path=Join-Path $dir ("file-{0}-{1}.bin" -f $index,$n)
            $data=_FileSnapshot_Bytes $s $Item.params
            $stream=New-Object IO.FileStream($path,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::None)
            try{$stream.Write($data,0,$data.Length);$stream.Flush($true)}finally{$stream.Dispose()}
            if((_FileSnapshot_Hash ([IO.File]::ReadAllBytes($path))) -ne $s.sha256){throw 'Durable backup did not verify.'};$s['backupPath']=$path;$s.Remove('contentBase64')
        }}}
        return @{ok=$true;message='File backups saved without replacing an existing backup.'}
    }catch{return @{ok=$false;message=$_.Exception.Message}}
}
function Undo-FileSnapshot-Verify {
    param($Item)
    try{
        $v=Undo-FileSnapshot-Validate $Item;if(-not $v.valid){throw $v.reason}
        $same=(_FileSnapshot_Comparable (_FileSnapshot_Read $Item.params)) -ceq (_FileSnapshot_Comparable $Item.state)
        return @{matches=$same;diff=$(if($same){''}else{'File bytes, metadata, security or existence differ from the saved original.'})}
    }catch{return @{matches=$false;diff=$_.Exception.Message}}
}
function Undo-FileSnapshot-Restore {
    param($Item)
    $details=@()
    try{
        $v=Undo-FileSnapshot-Validate $Item;if(-not $v.valid){throw $v.reason}
        foreach($r in @($Item.state.roots)){
            foreach($e in @($r.entries)){
                foreach($s in @($e.streams)){
                    $backup=_FileSnapshot_Field $s 'backupPath'
                    if($backup){
                        _FileSnapshot_BackupAncestors
                        $expected=[string](_FileSnapshot_Field $Item.params '_filesDir')
                        if(-not $expected -or -not(_FileSnapshot_Under (_FileSnapshot_Path $backup) (_FileSnapshot_Path $expected))){throw 'Unsafe backup path.'}
                        _FileSnapshot_NoLinks $backup
                        if((_FileSnapshot_Hash ([IO.File]::ReadAllBytes($backup))) -ne $s.sha256){throw 'Durable backup hash mismatch.'}
                    }
                }
            }
        }
        foreach($r in @($Item.state.roots)){
            try{
                _FileSnapshot_NoLinks $r.path
                foreach($entry in @($r.entries)){ $target=if($entry.relative){Join-Path $r.path $entry.relative}else{$r.path};_FileSnapshot_NoLinks $target }
                $creationErrors=@(_FileSnapshot_RemoveCreated $Item $r)
                if(-not $r.existed -and $creationErrors.Count){throw ($creationErrors -join '; ')}
                if(-not $r.existed){
                    if(Test-Path -LiteralPath $r.path -ErrorAction Stop){
                        $x=Get-Item -LiteralPath $r.path -Force -ErrorAction Stop
                        if($x.PSIsContainer -and @(Get-ChildItem -LiteralPath $r.path -Force -ErrorAction Stop).Count){throw 'Created folder is not empty; unknown files were left untouched.'}
                        Remove-Item -LiteralPath $r.path -Force -ErrorAction Stop
                    }
                    foreach($p in @($r.missingParents)){
                        if(Test-Path -LiteralPath $p -ErrorAction Stop){_FileSnapshot_NoLinks $p;if(@(Get-ChildItem -LiteralPath $p -Force -ErrorAction Stop).Count){break};Remove-Item -LiteralPath $p -Force -ErrorAction Stop}
                    }
                }else{
                    foreach($e in @($r.entries | Sort-Object {($_.relative -split '\\').Count})){
                        $p=if($e.relative){Join-Path $r.path $e.relative}else{$r.path}
                        if($e.directory){[void][IO.Directory]::CreateDirectory($p)}else{
                            [void][IO.Directory]::CreateDirectory((Split-Path $p -Parent))
                            if(Test-Path -LiteralPath $p -ErrorAction Stop){if((Get-Item -LiteralPath $p -Force -ErrorAction Stop).PSIsContainer){throw 'A file is now a directory.'};[IO.File]::SetAttributes($p,[IO.FileAttributes]::Normal)}
                            foreach($s in @($e.streams)){_FileSnapshot_WriteStream $p ([string]$s.name) (_FileSnapshot_Bytes $s $Item.params)}
                            foreach($extra in @(Get-Item -LiteralPath $p -Stream * -ErrorAction Stop)){if($extra.Stream -ne ':$DATA' -and @($e.streams.name) -notcontains $extra.Stream){Remove-Item -LiteralPath $p -Stream $extra.Stream -ErrorAction Stop}}
                        }
                    }
                    foreach($e in @($r.entries | Sort-Object {($_.relative -split '\\').Count} -Descending)){
                        $p=if($e.relative){Join-Path $r.path $e.relative}else{$r.path}
                        $acl=Get-Acl -LiteralPath $p -ErrorAction Stop;$acl.SetSecurityDescriptorSddlForm($e.sddl);Set-Acl -LiteralPath $p -AclObject $acl -ErrorAction Stop
                        $x=Get-Item -LiteralPath $p -Force -ErrorAction Stop;$x.CreationTimeUtc=[datetime]::Parse($e.creationUtc).ToUniversalTime();$x.LastWriteTimeUtc=[datetime]::Parse($e.lastWriteUtc).ToUniversalTime()
                        [IO.File]::SetAttributes($p,[IO.FileAttributes][int]$e.attributes)
                    }
                }
                if($creationErrors.Count){throw ($creationErrors -join '; ')}
                $details+=,@{path=$r.path;ok=$true;message='Original file data restored.'}
            }catch{$details+=,@{path=$r.path;ok=$false;message=$_.Exception.Message}}
        }
        $check=Undo-FileSnapshot-Verify $Item;$ok=$check.matches -and @($details | Where-Object {-not $_.ok}).Count -eq 0
        return @{ok=$ok;partial=(@($details | Where-Object {$_.ok}).Count -gt 0 -and -not $ok);message=$(if($ok){'Files put back to their original state.'}else{$check.diff});details=$details}
    }catch{return @{ok=$false;partial=$false;message=$_.Exception.Message;details=$details}}
}
function Undo-FileSnapshot-Describe { param($Item) try{return "Saved files and folders: $(@($Item.state.roots).Count) target(s)."}catch{return 'Saved file state.'} }
$script:UndoProviders['FileSnapshot']=@{Capture='Undo-FileSnapshot-Capture';Restore='Undo-FileSnapshot-Restore';Verify='Undo-FileSnapshot-Verify';Describe='Undo-FileSnapshot-Describe';Validate='Undo-FileSnapshot-Validate';Prepare='Undo-FileSnapshot-Prepare';AfterApply='Undo-FileSnapshot-AfterApply';VerifySeesApply = $false; Version=1}

# ---- providers\FirewallRule.ps1 ----
# FirewallRule provider (group D). Params: Name (the rule NAME, not the display name).
# State: existed flag plus every property that StreamReady could have changed (enabled, action, profile, direction and the
# port, address, program and service filters). Restore: delete a rule that did not exist, or put the captured properties back.
# Uses only the NetSecurity cmdlets that ship with Windows. Never throws.

if (-not $script:UndoProviders) { $script:UndoProviders = @{} }
$script:UndoProviders['FirewallRule'] = @{ Capture = 'Undo-FirewallRule-Capture'; Restore = 'Undo-FirewallRule-Restore'; Verify = 'Undo-FirewallRule-Verify'; Describe = 'Undo-FirewallRule-Describe'; Validate = 'Undo-FirewallRule-Validate'; VerifySeesApply = $true; Version = 1 }

function _FirewallRule_Join {
    param($V)
    if ($null -eq $V) { return '' }
    return ((@($V) | ForEach-Object { [string]$_ }) -join ',')
}
function _FirewallRule_Read {
    # returns @{ existed; props } or throws on a real read error. A missing rule is not an error.
    param([string]$Name)
    $rule = @(Get-NetFirewallRule -Name $Name -ErrorAction SilentlyContinue)
    if ($rule.Count -eq 0) { return @{ existed = $false; props = $null } }
    $r = $rule[0]
    $pf = Get-NetFirewallPortFilter -AssociatedNetFirewallRule $r -ErrorAction Stop
    $af = Get-NetFirewallAddressFilter -AssociatedNetFirewallRule $r -ErrorAction Stop
    $apf = Get-NetFirewallApplicationFilter -AssociatedNetFirewallRule $r -ErrorAction Stop
    $sf = Get-NetFirewallServiceFilter -AssociatedNetFirewallRule $r -ErrorAction Stop
    $itf = Get-NetFirewallInterfaceTypeFilter -AssociatedNetFirewallRule $r -ErrorAction Stop
    $props = @{
        DisplayName = [string]$r.DisplayName; Description = [string]$r.Description
        Enabled = [string]$r.Enabled; Direction = [string]$r.Direction; Action = [string]$r.Action; Profile = [string]$r.Profile
        Protocol = (_FirewallRule_Join $pf.Protocol); LocalPort = (_FirewallRule_Join $pf.LocalPort); RemotePort = (_FirewallRule_Join $pf.RemotePort)
        LocalAddress = (_FirewallRule_Join $af.LocalAddress); RemoteAddress = (_FirewallRule_Join $af.RemoteAddress)
        Program = [string]$apf.Program; Service = [string]$sf.Service
        Group = [string]$r.Group; EdgeTraversal = [string]$r.EdgeTraversalPolicy; InterfaceType = (_FirewallRule_Join $itf.InterfaceType)
        Authentication = [string]$r.Authentication; Encryption = [string]$r.Encryption
    }
    return @{ existed = $true; props = $props }
}
function Undo-FirewallRule-Capture {
    param([hashtable]$Params)
    $out = @{ type = 'FirewallRule'; v = 1; params = $Params; state = $null; ok = $false; error = $null; capturedAt = (Undo-Now) }
    try {
        $n = [string]$Params['Name']
        if (-not $n) { throw 'no rule name' }
        $cur = _FirewallRule_Read $n
        $out.state = @{ name = $n; existed = $cur.existed; props = $cur.props }
        $out.ok = $true
    } catch { $out.error = "could not read the firewall rule $($Params['Name']): $($_.Exception.Message)" }
    return $out
}
function _FirewallRule_Split { param([string]$S) if (-not $S) { return @() }; return @($S.Split(',')) }
function Undo-FirewallRule-Restore {
    param($Item)
    try {
        $st = ConvertTo-UndoPlain $Item['state']
        $n = [string]$st['name']
        $cur = _FirewallRule_Read $n
        if (-not $st['existed']) {
            if ($cur.existed) { Remove-NetFirewallRule -Name $n -ErrorAction Stop }
            return @{ ok = $true; partial = $false; message = 'the rule StreamReady added was removed'; details = @() }
        }
        $p = $st['props']
        # a rule whose direction changed cannot be edited in place: remove it and make it again
        if ($cur.existed -and $cur.props.Direction -ne $p['Direction']) { Remove-NetFirewallRule -Name $n -ErrorAction Stop; $cur = @{ existed = $false; props = $null } }
        $args = @{
            DisplayName = [string]$p['DisplayName']; Enabled = [string]$p['Enabled']; Action = [string]$p['Action']
            Profile = (_FirewallRule_Split ([string]$p['Profile']) | ForEach-Object { $_.Trim() })
        }
        if ($p['Description']) { $args['Description'] = [string]$p['Description'] }
        if ($p['Protocol'] -and $p['Protocol'] -ne 'Any') { $args['Protocol'] = [string]$p['Protocol'] }
        if ($p['LocalPort'] -and $p['LocalPort'] -ne 'Any') { $args['LocalPort'] = (_FirewallRule_Split ([string]$p['LocalPort'])) }
        if ($p['RemotePort'] -and $p['RemotePort'] -ne 'Any') { $args['RemotePort'] = (_FirewallRule_Split ([string]$p['RemotePort'])) }
        if ($p['LocalAddress']) { $args['LocalAddress'] = (_FirewallRule_Split ([string]$p['LocalAddress'])) }
        if ($p['RemoteAddress']) { $args['RemoteAddress'] = (_FirewallRule_Split ([string]$p['RemoteAddress'])) }
        if ($p['Program'] -and $p['Program'] -ne 'Any') { $args['Program'] = [string]$p['Program'] }
        if ($p['Service'] -and $p['Service'] -ne 'Any') { $args['Service'] = [string]$p['Service'] }
        if ($p['EdgeTraversal']) { $args['EdgeTraversalPolicy'] = [string]$p['EdgeTraversal'] }
        if ($p['InterfaceType']) { $args['InterfaceType'] = (_FirewallRule_Split ([string]$p['InterfaceType'])) }
        if ($p['Authentication']) { $args['Authentication'] = [string]$p['Authentication'] }
        if ($p['Encryption']) { $args['Encryption'] = [string]$p['Encryption'] }
        if ($cur.existed) {
            # fields that must be reset to "Any" when the original had none of them
            if (-not ($p['LocalPort'] -and $p['LocalPort'] -ne 'Any')) { $args['LocalPort'] = 'Any' }
            if (-not ($p['RemotePort'] -and $p['RemotePort'] -ne 'Any')) { $args['RemotePort'] = 'Any' }
            if (-not ($p['Program'] -and $p['Program'] -ne 'Any')) { $args['Program'] = 'Any' }
            if (-not ($p['Service'] -and $p['Service'] -ne 'Any')) { $args['Service'] = 'Any' }
            # Set-NetFirewallRule selects rules with -DisplayName, so the new display name goes in -NewDisplayName
            $args['NewDisplayName'] = $args['DisplayName']; $args.Remove('DisplayName')
            Set-NetFirewallRule -Name $n @args -ErrorAction Stop
        } else {
            if ($p['Group']) { $args['Group'] = [string]$p['Group'] }       # a group can only be given when a rule is created
            New-NetFirewallRule -Name $n -Direction ([string]$p['Direction']) @args -ErrorAction Stop | Out-Null
        }
        return @{ ok = $true; partial = $false; message = 'the firewall rule was put back'; details = @() }
    } catch { return @{ ok = $false; partial = $false; message = "firewall rule $($Item['params']['Name']): $($_.Exception.Message)"; details = @() } }
}
function Undo-FirewallRule-Verify {
    param($Item)
    try {
        $st = ConvertTo-UndoPlain $Item['state']
        $cur = _FirewallRule_Read ([string]$st['name'])
        if ([bool]$st['existed'] -ne [bool]$cur.existed) {
            return @{ matches = $false; diff = $(if ($cur.existed) { "rule $($st['name']) exists but did not before" } else { "rule $($st['name']) is missing but existed before" }) }
        }
        if (-not $st['existed']) { return @{ matches = $true; diff = '' } }
        $diffs = @()
        foreach ($k in 'Enabled', 'Direction', 'Action', 'Profile', 'Protocol', 'LocalPort', 'RemotePort', 'LocalAddress', 'RemoteAddress', 'Program', 'Service', 'Group', 'EdgeTraversal', 'InterfaceType', 'Authentication', 'Encryption') {
            $a = [string]$st['props'][$k]; $b = [string]$cur.props[$k]
            if ($a -ne $b) { $diffs += "$k is '$b', was '$a'" }
        }
        if ($diffs.Count -gt 0) { return @{ matches = $false; diff = "rule $($st['name']): $($diffs -join '; ')" } }
        return @{ matches = $true; diff = '' }
    } catch { return @{ matches = $false; diff = "could not read the firewall rule: $($_.Exception.Message)" } }
}
function Undo-FirewallRule-Describe {
    param($Item)
    try {
        $st = ConvertTo-UndoPlain $Item['state']
        if (-not $st['existed']) { return "Firewall rule $($st['name']) did not exist" }
        $p = $st['props']
        return "Firewall rule $($st['name']): $($p['Action']) $($p['Direction']) $($p['Protocol']) $($p['LocalPort']), $(if ($p['Enabled'] -eq 'True') { 'on' } else { 'off' })"
    } catch { return 'Firewall rule' }
}
function Undo-FirewallRule-Validate {
    param($Item)
    try {
        $n = [string]$Item['params']['Name']
        if ($n -notmatch '^[A-Za-z0-9_.@{}() -]{1,120}$') { return @{ valid = $false; reason = 'firewall rule name not allowed' } }
        if ([string]$Item['state']['name'] -ne $n) { return @{ valid = $false; reason = 'state does not match its rule' } }
        if ($Item['state']['existed']) {
            $p = $Item['state']['props']
            if ($p -isnot [hashtable]) { return @{ valid = $false; reason = 'bad rule properties' } }
            if ([string]$p['Action'] -notin @('Allow', 'Block', 'NotConfigured')) { return @{ valid = $false; reason = 'action not allowed' } }
            if ([string]$p['Direction'] -notin @('Inbound', 'Outbound')) { return @{ valid = $false; reason = 'direction not allowed' } }
            if ([string]$p['Enabled'] -notin @('True', 'False')) { return @{ valid = $false; reason = 'enabled flag not allowed' } }
            if ([string]$p['Program'] -and [string]$p['Program'] -match '[\x00-\x1f"<>|]') { return @{ valid = $false; reason = 'program path not allowed' } }
            foreach ($pk in 'LocalPort', 'RemotePort') { if ([string]$p[$pk] -and [string]$p[$pk] -notmatch '^(Any|RPC|RPC-EPMap|IPHTTPSIn|IPHTTPSOut|Teredo|\d{1,5}(-\d{1,5})?)(,(RPC|RPC-EPMap|IPHTTPSIn|IPHTTPSOut|Teredo|\d{1,5}(-\d{1,5})?))*$') { return @{ valid = $false; reason = "$pk not allowed" } } }
            foreach ($ak in 'LocalAddress', 'RemoteAddress') { if ([string]$p[$ak] -and [string]$p[$ak] -notmatch '^[0-9A-Za-z:./,*-]{1,300}$') { return @{ valid = $false; reason = "$ak not allowed" } } }
            if ([string]$p['Protocol'] -and [string]$p['Protocol'] -notmatch '^(Any|TCP|UDP|ICMPv4|ICMPv6|\d{1,3})$') { return @{ valid = $false; reason = 'protocol not allowed' } }
            if ([string]$p['Service'] -and [string]$p['Service'] -notmatch '^[A-Za-z0-9_.*-]{1,100}$') { return @{ valid = $false; reason = 'service not allowed' } }
            if ([string]$p['Group'] -and [string]$p['Group'] -match '[\x00-\x1f"<>|]') { return @{ valid = $false; reason = 'group not allowed' } }
            if ([string]$p['EdgeTraversal'] -and [string]$p['EdgeTraversal'] -notin @('Block', 'Allow', 'DeferToUser', 'DeferToApp')) { return @{ valid = $false; reason = 'edge traversal not allowed' } }
        }
        return @{ valid = $true; reason = $null }
    } catch { return @{ valid = $false; reason = $_.Exception.Message } }
}

# ---- providers\GpuDriverProperty.ps1 ----
# ==============================================================================
# Undo Provider: GpuDriverProperty
# Scope: Per-GPU driver class properties under display class {4d36e968-e325-11ce-bfc1-08002be10318}
# Implements strict spec binding (UE-1-01), unique PnP hardware identity (UE-1-05),
# shared resolution rule across Capture/Restore/Verify (UE-1-05), typed data comparison (UE-1-05),
# retains vanished devices as partial failure instead of false success (UE-1-05),
# requires present device and coverage for every matched key (UE-R3-2-01),
# supports safe delete on updated driver and UserActionRequired on value change (UE-R3-2-02),
# and guards against silently reusing stale originals across driver updates (UE-R3-2-02).
# Windows PowerShell 5.1 compatible, dot-source safe, pure ASCII
# ==============================================================================

if (-not $script:UndoProviders) { $script:UndoProviders = @{} }
$script:UndoProviders['GpuDriverProperty'] = @{
    Capture         = 'Undo-GpuDriverProperty-Capture'
    Restore         = 'Undo-GpuDriverProperty-Restore'
    Verify          = 'Undo-GpuDriverProperty-Verify'
    Describe        = 'Undo-GpuDriverProperty-Describe'
    Validate        = 'Undo-GpuDriverProperty-Validate'
    VerifySeesApply = $true
    GuardOnReuse    = $true
    Version         = 2
}

function _GpuDriverProperty_NormPath {
    param([string]$Path)
    if ([string]::IsNullOrEmpty($Path)) { return '' }
    $p = $Path.Trim().Replace('/', '\')
    if ($p -match 'HKEY_LOCAL_MACHINE\\(.*)$') {
        $p = 'HKLM:\' + $Matches[1]
    } elseif ($p -match 'HKEY_CURRENT_USER\\(.*)$') {
        $p = 'HKCU:\' + $Matches[1]
    } elseif ($p -match 'HKEY_USERS\\(.*)$') {
        $p = 'HKU:\' + $Matches[1]
    }
    return $p.TrimEnd('\')
}

function _GpuDriverProperty_TestPath {
    param([string]$Path)
    if ([string]::IsNullOrWhiteSpace($Path)) { return @{ ok = $true; exists = $false; error = $null } }
    $local:ErrorActionPreference = 'Stop'
    $errBefore = $error.Count
    try {
        $exists = [bool](Test-Path -LiteralPath $Path -ErrorAction Stop)
        if ($error.Count -gt $errBefore) {
            $msg = if ($error.Count -gt 0 -and $error[0]) { $error[0].ToString() } else { "Error probing '$Path'" }
            return @{ ok = $false; exists = $false; error = $msg }
        }
        return @{ ok = $true; exists = $exists; error = $null }
    } catch {
        return @{ ok = $false; exists = $false; error = [string]$_.Exception.Message }
    }
}

function _GpuDriverProperty_ConvertDataFromType {
    param($RawData, [string]$Type)
    if ($null -eq $RawData) { return $null }
    switch ($Type) {
        'DWord'       { return [int][long]$RawData }
        'QWord'       { return [long]$RawData }
        'Binary'      { return [Convert]::FromBase64String([string]$RawData) }
        'None'        { return [Convert]::FromBase64String([string]$RawData) }
        'MultiString' { return [string[]]@($RawData) }
        default       { return [string]$RawData }
    }
}

function _GpuDriverProperty_DeleteValue {
    param([string]$KeyPath, [string]$ValueName)
    if ($KeyPath -match '^(HKLM|HKCU|HKU):\\(.*)$') {
        $hive = $Matches[1]
        $sub = $Matches[2]
        $baseKey = switch ($hive) {
            'HKLM' { [Microsoft.Win32.Registry]::LocalMachine }
            'HKCU' { [Microsoft.Win32.Registry]::CurrentUser }
            'HKU'  { [Microsoft.Win32.Registry]::Users }
        }
        $rk = $baseKey.OpenSubKey($sub, $true)
        if ($rk) {
            try {
                $targetVal = if ($ValueName -eq '(default)') { '' } else { $ValueName }
                $rk.DeleteValue($targetVal, $false)
            } finally {
                $rk.Close()
            }
        }
    } else {
        $prop = if ([string]::IsNullOrEmpty($ValueName)) { '(default)' } else { $ValueName }
        Remove-ItemProperty -LiteralPath $KeyPath -Name $prop -ErrorAction SilentlyContinue
    }
}

function _GpuDriverProperty_GetPnpInstanceId {
    param(
        [string]$SubkeyIndex,
        $Props,
        [string]$ClassPath = ''
    )
    if ($null -eq $Props) { return $null }

    # 1. Check if subkey property has DeviceInstanceID or PnpInstanceId (common on fixtures and drivers)
    if ($Props.PSObject.Properties['PnpInstanceId'] -and -not [string]::IsNullOrEmpty($Props.PnpInstanceId)) {
        return [string]$Props.PnpInstanceId
    }
    if ($Props.PSObject.Properties['DeviceInstanceID'] -and -not [string]::IsNullOrEmpty($Props.DeviceInstanceID)) {
        return [string]$Props.DeviceInstanceID
    }

    # 2. Try looking up in HKLM:\SYSTEM\CurrentControlSet\Enum\PCI (only for real display class)
    $isRealClass = ($ClassPath -match '^HKLM:\\SYSTEM\\CurrentControlSet\\Control\\Class\\\{4d36e968-e325-11ce-bfc1-08002be10318\}$')
    if ($isRealClass -or [string]::IsNullOrEmpty($ClassPath)) {
        try {
            $driverTag = "{4d36e968-e325-11ce-bfc1-08002be10318}\$SubkeyIndex"
            $enumPci = 'HKLM:\SYSTEM\CurrentControlSet\Enum\PCI'
            $tpEnum = _GpuDriverProperty_TestPath $enumPci
            if ($tpEnum.ok -and $tpEnum.exists) {
                foreach ($devKey in (Get-ChildItem -LiteralPath $enumPci -ErrorAction Stop)) {
                    foreach ($instKey in (Get-ChildItem -LiteralPath $devKey.PSPath -ErrorAction Stop)) {
                        $drvProp = try { Get-ItemProperty -LiteralPath $instKey.PSPath -Name Driver -ErrorAction Stop } catch { $null }
                        $drv = if ($drvProp) { $drvProp.Driver } else { $null }
                        if ($drv -and $drv -like "*$driverTag*") {
                            return "PCI\$($devKey.PSChildName)\$($instKey.PSChildName)"
                        }
                    }
                }
            }
        } catch {}
    }

    # 3. Fallback eliminated in production (UE-R2-2-02): return null if unique PnP ID cannot be proven
    return $null
}

function _GpuDriverProperty_ResolveSubkey {
    param(
        $Device,
        [string]$ClassPath
    )
    $local:ErrorActionPreference = 'Stop'
    $tpClass = _GpuDriverProperty_TestPath $ClassPath
    if (-not $tpClass.ok) {
        return @{ path = $null; error = "ClassPath probe failed: $($tpClass.error)" }
    }
    if (-not $tpClass.exists) { return $null }

    $subNames = try {
        $classItem = Get-Item -LiteralPath $ClassPath -ErrorAction Stop
        $classItem.GetSubKeyNames()
    } catch {
        return @{ path = $null; error = "Failed to enumerate ClassPath: $($_.Exception.Message)" }
    }

    $pnpTarget = [string]$Device.PnpInstanceId
    if ([string]::IsNullOrEmpty($pnpTarget)) { return $null }

    $targetSubkey = $null

    # 1. Check direct path first
    $origIndex = [string]$Device.DeviceIndex
    $directPath = "$ClassPath\$origIndex"
    $tpDirect = _GpuDriverProperty_TestPath $directPath
    if (-not $tpDirect.ok) {
        return @{ path = $null; error = "DirectPath probe failed: $($tpDirect.error)" }
    }
    if ($tpDirect.exists) {
        try {
            $props = Get-ItemProperty -LiteralPath $directPath -ErrorAction Stop
            if ($props) {
                $curPnp = _GpuDriverProperty_GetPnpInstanceId $origIndex $props $ClassPath
                if ($curPnp -and $curPnp -eq $pnpTarget) {
                    $targetSubkey = $directPath
                }
            }
        } catch {}
    }

    # 2. Scan all subkeys for exact PnpInstanceId if not at direct index
    if (-not $targetSubkey) {
        foreach ($subName in $subNames) {
            if ($subName -notmatch '^\d{4}$') { continue }
            $subPath = "$ClassPath\$subName"
            $tpSub = _GpuDriverProperty_TestPath $subPath
            if ($tpSub.ok -and $tpSub.exists) {
                try {
                    $props = Get-ItemProperty -LiteralPath $subPath -ErrorAction Stop
                    if ($props) {
                        $curPnp = _GpuDriverProperty_GetPnpInstanceId $subName $props $ClassPath
                        if ($curPnp -and $curPnp -eq $pnpTarget) {
                            $targetSubkey = $subPath
                            break
                        }
                    }
                } catch {}
            }
        }
    }

    if (-not $targetSubkey) { return $null }

    # 3. Check driver compatibility on the resolved device (UE-R2-2-02)
    $incompatible = $false
    $incompatReason = $null
    try {
        $liveProps = Get-ItemProperty -LiteralPath $targetSubkey -ErrorAction Stop
        if ($liveProps) {
            if ($Device.DriverVersion -and $liveProps.DriverVersion -and $liveProps.DriverVersion -ne $Device.DriverVersion) {
                $incompatible = $true
                $incompatReason = "Driver version changed from '$($Device.DriverVersion)' to '$($liveProps.DriverVersion)'"
            } elseif ($Device.ProviderName -and $liveProps.ProviderName -and $liveProps.ProviderName -ne $Device.ProviderName) {
                $incompatible = $true
                $incompatReason = "Driver provider changed from '$($Device.ProviderName)' to '$($liveProps.ProviderName)'"
            }
        }
    } catch {
        return @{ path = $null; error = "Cannot read driver properties at '$targetSubkey': $($_.Exception.Message)" }
    }

    return @{
        path         = $targetSubkey
        incompatible = $incompatible
        reason       = $incompatReason
    }
}

function Undo-GpuDriverProperty-Validate {
    param([hashtable]$Item)
    if (-not $Item) { return @{ valid = $false; reason = 'Item record is null' } }
    if ($Item.type -ne 'GpuDriverProperty') { return @{ valid = $false; reason = "Type mismatch: expected GpuDriverProperty, got '$($Item.type)'" } }
    if (-not $Item.params) { return @{ valid = $false; reason = 'Missing spec params' } }
    if ([string]::IsNullOrEmpty($Item.params.Name)) { return @{ valid = $false; reason = 'Missing spec params.Name' } }
    if (-not $Item.state) { return @{ valid = $false; reason = 'Item state is missing' } }

    $st = $Item.state
    # UE-1-01: PropertyName and Vendor must equal immutable spec params
    if ([string]$st.propertyName -ne [string]$Item.params.Name) {
        return @{ valid = $false; reason = "Refused: state.propertyName '$($st.propertyName)' does not match spec params.Name '$($Item.params.Name)'" }
    }
    if ($Item.params.Vendor -and [string]$st.vendor -ne [string]$Item.params.Vendor) {
        return @{ valid = $false; reason = "Refused: state.vendor '$($st.vendor)' does not match spec params.Vendor '$($Item.params.Vendor)'" }
    }

    # UE-1-01: ClassPath must be strictly within Display Class or throwaway test fixture
    $classPath = [string]$st.classPath
    $isRealClass = ($classPath -match '^HKLM:\\SYSTEM\\CurrentControlSet\\Control\\Class\\\{4d36e968-e325-11ce-bfc1-08002be10318\}$')
    $isTestFixture = ($classPath -match '^HKLM:\\SOFTWARE\\SRUndoTest-')
    if (-not ($isRealClass -or $isTestFixture)) {
        return @{ valid = $false; reason = "Refused: classPath '$classPath' is outside display adapter class" }
    }

    # UE-R3-2-01: Devices array must not be null or empty
    if ($null -eq $st.devices -or @($st.devices).Count -lt 1) {
        return @{ valid = $false; reason = 'Refused: devices array must contain at least one device' }
    }
    # UE-R3-2-01: FrozenTargets must not be null or empty, and must match devices count
    if ($null -eq $st.frozenTargets -or @($st.frozenTargets).Count -lt 1) {
        return @{ valid = $false; reason = 'Refused: frozenTargets array must contain at least one target' }
    }
    if (@($st.devices).Count -ne @($st.frozenTargets).Count) {
        return @{ valid = $false; reason = 'Refused: devices count does not match frozenTargets count (missing matched key coverage)' }
    }

    $seenIndices = [System.Collections.Generic.HashSet[string]]::new()
    $seenPnpIds = [System.Collections.Generic.HashSet[string]]::new()
    $frozenSet = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($ft in @($st.frozenTargets)) {
        if ([string]::IsNullOrEmpty($ft)) { return @{ valid = $false; reason = 'Refused: empty target in frozenTargets' } }
        $frozenSet.Add([string]$ft) | Out-Null
    }

    foreach ($dev in $st.devices) {
        if ($dev -is [string]) { return @{ valid = $false; reason = 'Device cannot be a string' } }
        if ($null -eq $dev.DeviceIndex -or $dev.DeviceIndex -notmatch '^\d{4}$') {
            return @{ valid = $false; reason = "Invalid DeviceIndex '$($dev.DeviceIndex)'" }
        }
        if ($seenIndices.Contains($dev.DeviceIndex)) {
            return @{ valid = $false; reason = "Duplicate DeviceIndex '$($dev.DeviceIndex)'" }
        }
        $seenIndices.Add($dev.DeviceIndex) | Out-Null

        # UE-R2-2-02: Require unique present PnpInstanceId, reject fallback
        if ([string]::IsNullOrEmpty($dev.PnpInstanceId) -or $dev.PnpInstanceId -like 'DISPLAY_FALLBACK*') {
            return @{ valid = $false; reason = "Refused: device '$($dev.DeviceIndex)' lacks unique PnpInstanceId" }
        }
        if ($seenPnpIds.Contains($dev.PnpInstanceId)) {
            return @{ valid = $false; reason = "Duplicate PnpInstanceId '$($dev.PnpInstanceId)'" }
        }
        $seenPnpIds.Add($dev.PnpInstanceId) | Out-Null

        $expectedSubkey = "$classPath\$($dev.DeviceIndex)"
        if ([string]$dev.SubkeyPath -ne $expectedSubkey) {
            return @{ valid = $false; reason = "Refused: dev.SubkeyPath '$($dev.SubkeyPath)' does not match expected '$expectedSubkey'" }
        }
        if (-not $frozenSet.Contains([string]$dev.SubkeyPath)) {
            return @{ valid = $false; reason = "Refused: dev.SubkeyPath '$($dev.SubkeyPath)' is not in frozenTargets" }
        }

        # Bind device back to declared vendor
        if ($st.vendor -eq 'nvidia') {
            $isNv = ($dev.MatchingDeviceId -match 'VEN_10DE' -or $dev.PnpInstanceId -match 'VEN_10DE' -or $dev.DriverDesc -match 'NVIDIA')
            if (-not $isNv) {
                return @{ valid = $false; reason = "Refused: device '$($dev.DeviceIndex)' does not match declared vendor nvidia" }
            }
        } elseif ($st.vendor -eq 'amd') {
            $isAmd = ($dev.MatchingDeviceId -match 'VEN_1002' -or $dev.PnpInstanceId -match 'VEN_1002' -or $dev.DriverDesc -match 'AMD|Radeon')
            if (-not $isAmd) {
                return @{ valid = $false; reason = "Refused: device '$($dev.DeviceIndex)' does not match declared vendor amd" }
            }
        }

        # UE-R2-2-04: ValueExisted must be a boolean
        if ($dev.ValueExisted -isnot [bool]) {
            return @{ valid = $false; reason = "ValueExisted must be a boolean on device '$($dev.DeviceIndex)'" }
        }

        if ($dev.ValueExisted) {
            if ($dev.Type -notin @('String', 'ExpandString', 'DWord', 'QWord', 'Binary', 'MultiString', 'None')) {
                return @{ valid = $false; reason = "Invalid registry data type '$($dev.Type)' on GPU device" }
            }
        }
    }

    return @{ valid = $true; reason = $null }
}

function Undo-GpuDriverProperty-Capture {
    param([hashtable]$Params)
    try {
        if (-not $Params) { throw 'Params hashtable is required' }
        $vendor = [string]$Params.Vendor
        $propName = [string]$Params.Name
        if ([string]::IsNullOrEmpty($propName)) { throw 'Parameter Name is required' }

        $classPath = if ($Params.ClassPath) { [string]$Params.ClassPath } else {
            'HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4d36e968-e325-11ce-bfc1-08002be10318}'
        }

        $devices = [System.Collections.Generic.List[hashtable]]::new()
        $frozenTargets = [System.Collections.Generic.List[string]]::new()
        $matchedSubkeys = [System.Collections.Generic.List[string]]::new()
        $skippedSubkeys = [System.Collections.Generic.List[string]]::new()

        $tpClass = _GpuDriverProperty_TestPath $classPath
        if (-not $tpClass.ok) {
            return @{
                type        = 'GpuDriverProperty'
                v           = 2
                params      = $Params
                state       = $null
                ok          = $false
                error       = "Error probing display class path '$classPath': $($tpClass.error)"
                capturedAt  = (Get-Date).ToUniversalTime().ToString('o')
            }
        }

        if ($tpClass.exists) {
            $subNames = try {
                $classItem = Get-Item -LiteralPath $classPath -ErrorAction Stop
                $classItem.GetSubKeyNames()
            } catch {
                return @{
                    type        = 'GpuDriverProperty'
                    v           = 2
                    params      = $Params
                    state       = $null
                    ok          = $false
                    error       = "Error enumerating display class path '$classPath': $($_.Exception.Message)"
                    capturedAt  = (Get-Date).ToUniversalTime().ToString('o')
                }
            }
            foreach ($subName in $subNames) {
                if ($subName -notmatch '^\d{4}$') { continue }

                $subPath = "$classPath\$subName"
                $tpSub = _GpuDriverProperty_TestPath $subPath
                if (-not $tpSub.ok) {
                    return @{
                        type        = 'GpuDriverProperty'
                        v           = 2
                        params      = $Params
                        state       = $null
                        ok          = $false
                        error       = "Error probing display subkey '$subPath': $($tpSub.error)"
                        capturedAt  = (Get-Date).ToUniversalTime().ToString('o')
                    }
                }
                if (-not $tpSub.exists) { continue }

                $desc = $null
                $matchingId = $null
                $version = $null
                $date = $null
                $provider = $null

                try {
                    $props = Get-ItemProperty -LiteralPath $subPath -ErrorAction Stop
                    if ($props) {
                        $desc = [string]$props.DriverDesc
                        $matchingId = [string]$props.MatchingDeviceId
                        $version = [string]$props.DriverVersion
                        $date = [string]$props.DriverDate
                        $provider = [string]$props.ProviderName
                    }
                } catch {}

                # Vendor matching filter
                $matched = $false
                if ($vendor -eq 'nvidia') {
                    if ($desc -match 'NVIDIA' -or $matchingId -match 'VEN_10DE') { $matched = $true }
                } elseif ($vendor -eq 'amd') {
                    if ($desc -match 'AMD|Radeon' -or $matchingId -match 'VEN_1002') { $matched = $true }
                } elseif ($vendor -eq 'any' -or [string]::IsNullOrEmpty($vendor)) {
                    if ($desc) { $matched = $true }
                }

                if ($matched) {
                    $matchedSubkeys.Add($subName)

                    $pnpId = _GpuDriverProperty_GetPnpInstanceId $subName $props $classPath
                    if (-not $pnpId) {
                        # UE-R3-2-01: Record matching subkey skipped for lack of PnP ID
                        $skippedSubkeys.Add($subName)
                        continue
                    }

                    $k = Get-Item -LiteralPath $subPath -ErrorAction Stop
                    $valExisted = @($k.GetValueNames()) -contains $propName
                    $type = $null
                    $data = $null
                    if ($valExisted) {
                        $kind = $k.GetValueKind($propName)
                        $type = [string]$kind
                        $v = $k.GetValue($propName, $null, [Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames)
                        $data = if ($kind -eq [Microsoft.Win32.RegistryValueKind]::Binary -or $kind -eq [Microsoft.Win32.RegistryValueKind]::None) {
                            [Convert]::ToBase64String([byte[]]$v)
                        } else {
                            $v
                        }
                    }

                    $devices.Add(@{
                        DeviceIndex      = $subName
                        PnpInstanceId    = $pnpId
                        DriverDesc       = $desc
                        MatchingDeviceId = $matchingId
                        DriverVersion    = $version
                        DriverDate       = $date
                        ProviderName     = $provider
                        SubkeyPath       = "$classPath\$subName"
                        ValueExisted     = $valExisted
                        Type             = $type
                        Data             = $data
                    })
                    $frozenTargets.Add("$classPath\$subName")
                }
            }
        }

        # UE-R3-2-01: If any matching display-class key was skipped for lack of PnP ID, refuse capture
        if ($skippedSubkeys.Count -gt 0) {
            $skippedList = $skippedSubkeys -join ', '
            return @{
                type        = 'GpuDriverProperty'
                v           = 2
                params      = $Params
                state       = $null
                ok          = $false
                error       = "Matching display adapter subkey(s) ($skippedList) lack a unique PnP instance ID; cannot safely record original state."
                capturedAt  = (Get-Date).ToUniversalTime().ToString('o')
            }
        }

        # UE-R3-2-01: If no compatible devices were found, tweak is not applicable
        if ($devices.Count -eq 0) {
            $vLabel = if ($vendor -and $vendor -ne 'any') { $vendor } else { 'display' }
            return @{
                type        = 'GpuDriverProperty'
                v           = 2
                params      = $Params
                state       = $null
                ok          = $false
                error       = "No compatible $vLabel GPU device found (tweak not applicable on this system)"
                capturedAt  = (Get-Date).ToUniversalTime().ToString('o')
            }
        }

        # UE-R4-2-02: Derive Apply footprint using the same detection the app's Apply uses
        $detectedApplyTarget = $null
        if (Get-Command 'Get-GpuDriverSubkey' -ErrorAction SilentlyContinue -and ($classPath -notmatch 'SRUndoTest')) {
            try { $detectedApplyTarget = _GpuDriverProperty_NormPath (Get-GpuDriverSubkey -Vendor $vendor) } catch {}
        }
        if (-not $detectedApplyTarget) {
            $scanNames = if ($subNames) { $subNames } else {
                try {
                    $classItem = Get-Item -LiteralPath $classPath -ErrorAction Stop
                    $classItem.GetSubKeyNames()
                } catch { @() }
            }
            foreach ($subName in $scanNames) {
                if ($subName -notmatch '^\d{4}$') { continue }
                $subPath = "$classPath\$subName"
                $descProp = try { Get-ItemProperty -LiteralPath $subPath -Name DriverDesc -ErrorAction Stop } catch { $null }
                $desc = if ($descProp) { $descProp.DriverDesc } else { $null }
                if ($vendor -eq 'nvidia' -and $desc -match 'NVIDIA') { $detectedApplyTarget = $subPath; break }
                if ($vendor -eq 'amd'    -and $desc -match 'AMD|Radeon') { $detectedApplyTarget = $subPath; break }
                if (($vendor -eq 'any' -or [string]::IsNullOrEmpty($vendor)) -and $desc) { $detectedApplyTarget = $subPath; break }
            }
        }
        if ($detectedApplyTarget) {
            $detectedApplyTarget = _GpuDriverProperty_NormPath $detectedApplyTarget
        }

        # Check for cached $script:GpuSubkey or $global:GpuSubkey
        $cachedSubkey = if (Test-Path 'variable:script:GpuSubkey') { $script:GpuSubkey } else { $null }
        if (-not $cachedSubkey -and (Test-Path 'variable:global:GpuSubkey')) { $cachedSubkey = $global:GpuSubkey }
        $normCached = if ($cachedSubkey) { _GpuDriverProperty_NormPath $cachedSubkey } else { $null }
        $normClass = _GpuDriverProperty_NormPath $classPath

        # If a cached Apply target is active and belongs to this class/scope, verify it matches live detection
        if ($normCached -and ($normCached.StartsWith("$normClass\", [System.StringComparison]::OrdinalIgnoreCase) -or $normCached -eq $normClass)) {
            if ($detectedApplyTarget -and $normCached -ne $detectedApplyTarget) {
                return @{
                    type        = 'GpuDriverProperty'
                    v           = 2
                    params      = $Params
                    state       = $null
                    ok          = $false
                    error       = "GPU configuration changed since application startup: cached Apply target '$cachedSubkey' does not match detected target '$detectedApplyTarget'. Refusing capture to prevent writing outside captured footprint."
                    capturedAt  = (Get-Date).ToUniversalTime().ToString('o')
                }
            }
        }

        # Determine the effective Apply footprint and require captured devices to cover it
        $activeApplyTarget = if ($Params.ApplyTarget) {
            _GpuDriverProperty_NormPath ([string]$Params.ApplyTarget)
        } elseif ($normCached -and ($normCached.StartsWith("$normClass\", [System.StringComparison]::OrdinalIgnoreCase) -or $normCached -eq $normClass)) {
            $normCached
        } else {
            $detectedApplyTarget
        }

        $normFrozen = @($frozenTargets | ForEach-Object { _GpuDriverProperty_NormPath $_ })
        if ($activeApplyTarget -and -not ($normFrozen -contains $activeApplyTarget)) {
            return @{
                type        = 'GpuDriverProperty'
                v           = 2
                params      = $Params
                state       = $null
                ok          = $false
                error       = "Apply target '$activeApplyTarget' is not covered by captured devices ($($frozenTargets -join ', ')). Refusing capture."
                capturedAt  = (Get-Date).ToUniversalTime().ToString('o')
            }
        }

        # UE-R3-2-02: Guard on reuse: refuse silently reusing a stale original from an older driver
        if (Get-Command 'Undo-Store-Read' -ErrorAction SilentlyContinue) {
            try {
                $stRead = Undo-Store-Read
                if ($stRead -and $stRead.ok -and $stRead.records) {
                    foreach ($rec in $stRead.records.Values) {
                        if ($rec['status'] -notin @('applied', 'partial', 'manual')) { continue }
                        foreach ($it in @($rec['items'])) {
                            if ($it['type'] -eq 'GpuDriverProperty' -and $it['state']) {
                                $stOld = $it['state']
                                if ($stOld.vendor -eq $vendor -and $stOld.propertyName -eq $propName) {
                                    foreach ($oldDev in @($stOld.devices)) {
                                        foreach ($curDev in $devices) {
                                            if ($oldDev.PnpInstanceId -eq $curDev.PnpInstanceId) {
                                                if ($oldDev.DriverVersion -and $curDev.DriverVersion -and $oldDev.DriverVersion -ne $curDev.DriverVersion) {
                                                    return @{
                                                        type        = 'GpuDriverProperty'
                                                        v           = 2
                                                        params      = $Params
                                                        state       = $null
                                                        ok          = $false
                                                        error       = "GPU driver changed since you applied this (driver version was '$($oldDev.DriverVersion)', now '$($curDev.DriverVersion)'). Cannot silently reuse stale original from another driver; undo or confirm the earlier change in History first."
                                                        capturedAt  = (Get-Date).ToUniversalTime().ToString('o')
                                                    }
                                                }
                                                if ($oldDev.ProviderName -and $curDev.ProviderName -and $oldDev.ProviderName -ne $curDev.ProviderName) {
                                                    return @{
                                                        type        = 'GpuDriverProperty'
                                                        v           = 2
                                                        params      = $Params
                                                        state       = $null
                                                        ok          = $false
                                                        error       = "GPU driver changed since you applied this (driver provider was '$($oldDev.ProviderName)', now '$($curDev.ProviderName)'). Cannot silently reuse stale original from another driver; undo or confirm the earlier change in History first."
                                                        capturedAt  = (Get-Date).ToUniversalTime().ToString('o')
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            } catch {}
        }

        return @{
            type        = 'GpuDriverProperty'
            v           = 2
            params      = $Params
            state       = @{
                vendor        = $vendor
                propertyName  = $propName
                classPath     = $classPath
                applyTarget   = $activeApplyTarget
                devices       = @($devices)
                frozenTargets = @($frozenTargets)
            }
            ok          = $true
            error       = $null
            capturedAt  = (Get-Date).ToUniversalTime().ToString('o')
        }
    } catch {
        return @{
            type        = 'GpuDriverProperty'
            v           = 2
            params      = $Params
            state       = $null
            ok          = $false
            error       = [string]$_.Exception.Message
            capturedAt  = (Get-Date).ToUniversalTime().ToString('o')
        }
    }
}

function Undo-GpuDriverProperty-Restore {
    param([hashtable]$Item)
    try {
        $val = Undo-GpuDriverProperty-Validate -Item $Item
        if (-not $val.valid) {
            return @{ ok = $false; partial = $false; message = "Validation failed: $($val.reason)"; details = @() }
        }

        # UE-1-01: Recompute target parameter from spec params
        $propName = [string]$Item.params.Name
        $classPath = if ($Item.params.ClassPath) { [string]$Item.params.ClassPath } else {
            'HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4d36e968-e325-11ce-bfc1-08002be10318}'
        }

        $st = $Item.state
        $details = [System.Collections.Generic.List[hashtable]]::new()
        $allOk = $true
        $hasMissingDevices = $false
        $hasFailedDevices = $false
        $manualDevices = [System.Collections.Generic.List[hashtable]]::new()
        $restoredCount = 0

        foreach ($dev in $st.devices) {
            # Check if device was already marked restored in previous run
            if ($dev.Restored -eq $true) {
                $resDev = _GpuDriverProperty_ResolveSubkey -Device $dev -ClassPath $classPath
                if ($resDev -and $resDev.error) {
                    $hasFailedDevices = $true
                    $allOk = $false
                    $details.Add(@{
                        deviceIndex   = $dev.DeviceIndex
                        pnpInstanceId = $dev.PnpInstanceId
                        driverDesc    = $dev.DriverDesc
                        ok            = $false
                        action        = 'failed'
                        message       = "Error resolving device subkey: $($resDev.error)"
                    })
                    continue
                }
                if ($resDev -and $resDev.path) {
                    $targetSubkey = $resDev.path
                    try {
                        $tpCheck = _GpuDriverProperty_TestPath $targetSubkey
                        if (-not $tpCheck.ok) {
                            $hasFailedDevices = $true
                            $allOk = $false
                            $details.Add(@{
                                deviceIndex   = $dev.DeviceIndex
                                pnpInstanceId = $dev.PnpInstanceId
                                driverDesc    = $dev.DriverDesc
                                subkeyPath    = $targetSubkey
                                ok            = $false
                                action        = 'failed'
                                message       = "Error probing target subkey: $($tpCheck.error)"
                            })
                            continue
                        }
                        if ($tpCheck.exists) {
                            $k = Get-Item -LiteralPath $targetSubkey -ErrorAction Stop
                            $hasVal = (@($k.GetValueNames()) -contains $propName)
                            $isGood = if ($dev.ValueExisted) { $hasVal } else { -not $hasVal }
                            if ($isGood) {
                                $restoredCount++
                                $details.Add(@{
                                    deviceIndex   = $dev.DeviceIndex
                                    pnpInstanceId = $dev.PnpInstanceId
                                    driverDesc    = $dev.DriverDesc
                                    subkeyPath    = $targetSubkey
                                    ok            = $true
                                    action        = 'already_restored'
                                    message       = "Already restored on device '$($dev.DeviceIndex)'"
                                })
                                continue
                            }
                        }
                    } catch {
                        $hasFailedDevices = $true
                        $allOk = $false
                    }
                }
            }

            # UE-R2-2-02: Use unified resolver
            $resDev = _GpuDriverProperty_ResolveSubkey -Device $dev -ClassPath $classPath

            if ($resDev -and $resDev.error) {
                $hasFailedDevices = $true
                $allOk = $false
                $details.Add(@{
                    deviceIndex   = $dev.DeviceIndex
                    pnpInstanceId = $dev.PnpInstanceId
                    driverDesc    = $dev.DriverDesc
                    ok            = $false
                    action        = 'failed'
                    message       = "Error resolving device subkey: $($resDev.error)"
                })
                continue
            }

            # UE-1-05 & UE-R2-2-02: Vanished devices must NOT report success! Must retain record for retry.
            if (-not $resDev -or -not $resDev.path) {
                $hasMissingDevices = $true
                $allOk = $false
                $details.Add(@{
                    deviceIndex   = $dev.DeviceIndex
                    pnpInstanceId = $dev.PnpInstanceId
                    driverDesc    = $dev.DriverDesc
                    ok            = $false
                    action        = 'skipped_vanished'
                    message       = "Adapter '$($dev.DriverDesc)' ($($dev.PnpInstanceId)) was not found in display class. Original retained for retry."
                })
                continue
            }

            $targetSubkey = $resDev.path

            # UE-R3-2-02: Incompatible driver replacement detected
            if ($resDev.incompatible) {
                if (-not $dev.ValueExisted) {
                    # Captured original was absent: safe to delete tweak on newer driver
                    try {
                        $tp = _GpuDriverProperty_TestPath $targetSubkey
                        if (-not $tp.ok) {
                            $allOk = $false
                            $hasFailedDevices = $true
                            $details.Add(@{
                                deviceIndex   = $dev.DeviceIndex
                                pnpInstanceId = $dev.PnpInstanceId
                                driverDesc    = $dev.DriverDesc
                                subkeyPath    = $targetSubkey
                                ok            = $false
                                action        = 'failed'
                                message       = "Error probing key '$targetSubkey' on updated driver: $($tp.error)"
                            })
                        } elseif (-not $tp.exists) {
                            $dev['Restored'] = $true
                            $restoredCount++
                            $details.Add(@{
                                deviceIndex   = $dev.DeviceIndex
                                pnpInstanceId = $dev.PnpInstanceId
                                driverDesc    = $dev.DriverDesc
                                subkeyPath    = $targetSubkey
                                ok            = $true
                                action        = 'already_absent'
                                message       = "Property '$propName' was already absent on updated driver"
                            })
                        } else {
                            $k = Get-Item -LiteralPath $targetSubkey -ErrorAction Stop
                            if (@($k.GetValueNames()) -contains $propName) {
                                _GpuDriverProperty_DeleteValue $targetSubkey $propName
                                $dev['Restored'] = $true
                                $restoredCount++
                                $details.Add(@{
                                    deviceIndex   = $dev.DeviceIndex
                                    pnpInstanceId = $dev.PnpInstanceId
                                    driverDesc    = $dev.DriverDesc
                                    subkeyPath    = $targetSubkey
                                    ok            = $true
                                    action        = 'deleted_value'
                                    message       = "Deleted created property '$propName' on updated driver (driver changed since you applied this: $($resDev.reason))"
                                })
                            } else {
                                $dev['Restored'] = $true
                                $restoredCount++
                                $details.Add(@{
                                    deviceIndex   = $dev.DeviceIndex
                                    pnpInstanceId = $dev.PnpInstanceId
                                    driverDesc    = $dev.DriverDesc
                                    subkeyPath    = $targetSubkey
                                    ok            = $true
                                    action        = 'already_absent'
                                    message       = "Property '$propName' was already absent on updated driver"
                                })
                            }
                        }
                    } catch {
                        $allOk = $false
                        $hasFailedDevices = $true
                        $details.Add(@{
                            deviceIndex   = $dev.DeviceIndex
                            pnpInstanceId = $dev.PnpInstanceId
                            driverDesc    = $dev.DriverDesc
                            subkeyPath    = $targetSubkey
                            ok            = $false
                            action        = 'failed'
                            message       = "Error deleting '$propName' on updated driver: $($_.Exception.Message)"
                        })
                    }
                } else {
                    # Captured original had a value: unsafe to overwrite newer driver setting automatically.
                    $allOk = $false
                    $dev['Manual'] = $true
                    $manualDevices.Add(@{
                        deviceIndex   = $dev.DeviceIndex
                        pnpInstanceId = $dev.PnpInstanceId
                        driverDesc    = $dev.DriverDesc
                        subkeyPath    = $targetSubkey
                        message       = "GPU driver changed since you applied this ($($resDev.reason)). Original value was '$($dev.Data)' ($($dev.Type)) at '$targetSubkey\$propName'. To restore manually, verify if this setting applies to your updated driver and set '$propName' in registry."
                    })
                }
                continue
            }

            try {
                $tp = _GpuDriverProperty_TestPath $targetSubkey
                if (-not $tp.ok) {
                    $allOk = $false
                    $hasFailedDevices = $true
                    $details.Add(@{
                        deviceIndex   = $dev.DeviceIndex
                        pnpInstanceId = $dev.PnpInstanceId
                        driverDesc    = $dev.DriverDesc
                        subkeyPath    = $targetSubkey
                        ok            = $false
                        action        = 'failed'
                        message       = "Error probing key '$targetSubkey': $($tp.error)"
                    })
                } elseif ($dev.ValueExisted) {
                    if (-not $tp.exists) {
                        New-Item -Path (Split-Path $targetSubkey -Parent) -Name (Split-Path $targetSubkey -Leaf) -Force -ErrorAction Stop | Out-Null
                    }
                    $typedData = _GpuDriverProperty_ConvertDataFromType $dev.Data $dev.Type
                    Set-ItemProperty -LiteralPath $targetSubkey -Name $propName -Value $typedData -Type $dev.Type -ErrorAction Stop
                    $dev['Restored'] = $true
                    $restoredCount++
                    $details.Add(@{
                        deviceIndex   = $dev.DeviceIndex
                        pnpInstanceId = $dev.PnpInstanceId
                        driverDesc    = $dev.DriverDesc
                        subkeyPath    = $targetSubkey
                        ok            = $true
                        action        = 'restored_value'
                        message       = "Restored value '$propName' ($($dev.Type))"
                    })
                } else {
                    if (-not $tp.exists) {
                        $dev['Restored'] = $true
                        $restoredCount++
                        $details.Add(@{
                            deviceIndex   = $dev.DeviceIndex
                            pnpInstanceId = $dev.PnpInstanceId
                            driverDesc    = $dev.DriverDesc
                            subkeyPath    = $targetSubkey
                            ok            = $true
                            action        = 'already_absent'
                            message       = "Property '$propName' was already absent"
                        })
                    } else {
                        $k = Get-Item -LiteralPath $targetSubkey -ErrorAction Stop
                        if (@($k.GetValueNames()) -contains $propName) {
                            _GpuDriverProperty_DeleteValue $targetSubkey $propName
                            $dev['Restored'] = $true
                            $restoredCount++
                            $details.Add(@{
                                deviceIndex   = $dev.DeviceIndex
                                pnpInstanceId = $dev.PnpInstanceId
                                driverDesc    = $dev.DriverDesc
                                subkeyPath    = $targetSubkey
                                ok            = $true
                                action        = 'deleted_value'
                                message       = "Deleted created property '$propName'"
                            })
                        } else {
                            $dev['Restored'] = $true
                            $restoredCount++
                            $details.Add(@{
                                deviceIndex   = $dev.DeviceIndex
                                pnpInstanceId = $dev.PnpInstanceId
                                driverDesc    = $dev.DriverDesc
                                subkeyPath    = $targetSubkey
                                ok            = $true
                                action        = 'already_absent'
                                message       = "Property '$propName' was already absent"
                            })
                        }
                    }
                }
            } catch {
                $allOk = $false
                $hasFailedDevices = $true
                $details.Add(@{
                    deviceIndex   = $dev.DeviceIndex
                    pnpInstanceId = $dev.PnpInstanceId
                    driverDesc    = $dev.DriverDesc
                    subkeyPath    = $targetSubkey
                    ok            = $false
                    action        = 'failed'
                    message       = "Error restoring '$propName': $($_.Exception.Message)"
                })
            }
        }

        # UE-R4-2-03: Mixed manual and retryable outcomes
        $hasRetryableFailure = ($hasMissingDevices -or $hasFailedDevices)

        if ($manualDevices.Count -gt 0) {
            if ($hasRetryableFailure) {
                # Sibling devices are still missing or failed: do NOT emit UserActionRequired to core yet
                # Keep item in partial state so missing/failed devices remain retryable.
                foreach ($m in $manualDevices) {
                    $details.Add(@{
                        deviceIndex   = $m.deviceIndex
                        pnpInstanceId = $m.pnpInstanceId
                        driverDesc    = $m.driverDesc
                        subkeyPath    = $m.subkeyPath
                        ok            = $false
                        action        = 'manual_driver_changed'
                        message       = $m.message
                    })
                }
                $retryMsg = if ($hasMissingDevices) { "one or more devices are missing and retained for retry" } else { "one or more devices failed to restore" }
                $mMsgs = @($manualDevices | ForEach-Object { $_.message }) -join '; '
                return @{
                    ok      = $false
                    partial = $true
                    message = "GPU driver property '$propName' restore incomplete: $retryMsg. Note: manual steps for updated driver will be required once retryable devices recover ($mMsgs)."
                    details = @($details)
                }
            } else {
                # All retryable devices succeeded (or were already restored)!
                # Now emit UserActionRequired so core marks item as manual and prompts the user.
                foreach ($m in $manualDevices) {
                    $details.Add(@{
                        deviceIndex   = $m.deviceIndex
                        pnpInstanceId = $m.pnpInstanceId
                        driverDesc    = $m.driverDesc
                        subkeyPath    = $m.subkeyPath
                        status        = 'UserActionRequired'
                        ok            = $false
                        action        = 'manual_driver_changed'
                        message       = $m.message
                    })
                }
                $userSteps = @($manualDevices | ForEach-Object { $_.message }) -join '; '
                return @{
                    ok      = $false
                    partial = ($restoredCount -gt 0)
                    message = $userSteps
                    details = @($details)
                }
            }
        }

        $ver = Undo-GpuDriverProperty-Verify -Item $Item
        $finalOk = ($allOk -and $ver.matches -and -not $hasMissingDevices -and -not $hasFailedDevices)
        $partial = (-not $finalOk)

        $msg = if ($finalOk) {
            "GPU driver property '$propName' restored successfully across all matching devices."
        } elseif ($hasMissingDevices) {
            "GPU driver property '$propName' restore incomplete: one or more devices are missing and were retained for retry."
        } else {
            "GPU driver property '$propName' restore incomplete: $($ver.diff)"
        }

        return @{
            ok      = $finalOk
            partial = $partial
            message = $msg
            details = @($details)
        }
    } catch {
        return @{
            ok      = $false
            partial = $false
            message = "Unexpected error during restore: $($_.Exception.Message)"
            details = @()
        }
    }
}

function Undo-GpuDriverProperty-Verify {
    param([hashtable]$Item)
    try {
        $val = Undo-GpuDriverProperty-Validate -Item $Item
        if (-not $val.valid) { return @{ matches = $false; diff = "Validation error: $($val.reason)" } }

        $propName = [string]$Item.params.Name
        $classPath = if ($Item.params.ClassPath) { [string]$Item.params.ClassPath } else {
            'HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4d36e968-e325-11ce-bfc1-08002be10318}'
        }

        $st = $Item.state
        $diffs = [System.Collections.Generic.List[string]]::new()
        $matches = $true

        foreach ($dev in $st.devices) {
            # UE-R2-2-02: Use unified resolver
            $resDev = _GpuDriverProperty_ResolveSubkey -Device $dev -ClassPath $classPath

            if ($resDev -and $resDev.error) {
                $matches = $false
                $diffs.Add("$($dev.DeviceIndex): error resolving device subkey: $($resDev.error)")
                continue
            }

            # UE-1-05 & UE-R2-2-02: If device is vanished, Verify must NOT report matches=true!
            if (-not $resDev -or -not $resDev.path) {
                $matches = $false
                $diffs.Add("Device '$($dev.DriverDesc)' ($($dev.PnpInstanceId)) is missing")
                continue
            }

            # UE-R3-2-02 & UE-R4-2-06 & UE-R5-2-01: Handle driver replacement
            if ($resDev.incompatible) {
                if (-not $dev.ValueExisted) {
                    # If captured original was absent, check if property is absent now
                    # UE-R4-2-06 & UE-R5-2-01: Fail closed on unreadable key; do NOT treat read error or non-terminating error as absence!
                    $targetSubkey = $resDev.path
                    try {
                        $tp = _GpuDriverProperty_TestPath $targetSubkey
                        if (-not $tp.ok) {
                            $matches = $false
                            $diffs.Add("$($dev.DeviceIndex): could not probe key '$targetSubkey': $($tp.error)")
                            continue
                        }
                        if (-not $tp.exists) {
                            # Confirmed absent
                            continue
                        }
                        $k = Get-Item -LiteralPath $targetSubkey -ErrorAction Stop
                        $hasVal = (@($k.GetValueNames()) -contains $propName)
                        if ($hasVal) {
                            $curVal = $k.GetValue($propName, $null, [Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames)
                            $matches = $false
                            $diffs.Add("$($dev.DeviceIndex): property '$propName' exists with value '$curVal' on updated driver, expected absent")
                        }
                    } catch {
                        $matches = $false
                        $diffs.Add("$($dev.DeviceIndex): could not read key '$targetSubkey': $($_.Exception.Message)")
                    }
                    continue
                } else {
                    $matches = $false
                    $diffs.Add("Device '$($dev.DriverDesc)': driver changed since you applied this ($($resDev.reason))")
                    continue
                }
            }

            $targetSubkey = $resDev.path
            try {
                $tp = _GpuDriverProperty_TestPath $targetSubkey
                if (-not $tp.ok) {
                    $matches = $false
                    $diffs.Add("$($dev.DeviceIndex): could not probe key '$targetSubkey': $($tp.error)")
                    continue
                }
                if (-not $tp.exists) {
                    if ($dev.ValueExisted) {
                        $matches = $false
                        $diffs.Add("$($dev.DeviceIndex): target key '$targetSubkey' does not exist")
                    }
                    continue
                }
                $k = Get-Item -LiteralPath $targetSubkey -ErrorAction Stop
                $hasVal = (@($k.GetValueNames()) -contains $propName)
            } catch {
                $matches = $false
                $diffs.Add("$($dev.DeviceIndex): could not read key '$targetSubkey': $($_.Exception.Message)")
                continue
            }

            if ($dev.ValueExisted) {
                if (-not $hasVal) {
                    $matches = $false
                    $diffs.Add("$($dev.DeviceIndex): property '$propName' is missing, expected '$($dev.Data)'")
                } else {
                    # UE-1-05: Compare exact registry type
                    $curKind = [string]$k.GetValueKind($propName)
                    if ($curKind -ne [string]$dev.Type) {
                        $matches = $false
                        $diffs.Add("$($dev.DeviceIndex): property '$propName' type is '$curKind', expected '$($dev.Type)'")
                    }

                    $curVal = $k.GetValue($propName, $null, [Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames)
                    $matchesVal = $false
                    switch ($curKind) {
                        'Binary' {
                            $curB64 = [Convert]::ToBase64String([byte[]]$curVal)
                            $matchesVal = [string]::Equals($curB64, [string]$dev.Data, [System.StringComparison]::Ordinal)
                        }
                        'None' {
                            $curB64 = [Convert]::ToBase64String([byte[]]$curVal)
                            $matchesVal = [string]::Equals($curB64, [string]$dev.Data, [System.StringComparison]::Ordinal)
                        }
                        'MultiString' {
                            $curArr = [string[]]@($curVal)
                            $expArr = [string[]]@($dev.Data)
                            if ($curArr.Length -eq $expArr.Length) {
                                $matchesVal = $true
                                for ($i = 0; $i -lt $curArr.Length; $i++) {
                                    if (-not ($curArr[$i] -ceq $expArr[$i])) {
                                        $matchesVal = $false
                                        break
                                    }
                                }
                            }
                        }
                        'DWord' {
                            $matchesVal = ([long]$curVal -eq [long]$dev.Data)
                        }
                        'QWord' {
                            $matchesVal = ([long]$curVal -eq [long]$dev.Data)
                        }
                        default {
                            $matchesVal = [string]::Equals([string]$curVal, [string]$dev.Data, [System.StringComparison]::Ordinal)
                        }
                    }
                    if (-not $matchesVal) {
                        $matches = $false
                        $diffs.Add("$($dev.DeviceIndex): property '$propName' = '$curVal', expected '$($dev.Data)'")
                    }
                }
            } else {
                if ($hasVal) {
                    $curVal = $k.GetValue($propName, $null, [Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames)
                    $matches = $false
                    $diffs.Add("$($dev.DeviceIndex): property '$propName' exists with value '$curVal', expected absent")
                }
            }
        }

        return @{
            matches = $matches
            diff    = if ($matches) { 'State matches original exactly.' } else { $diffs -join '; ' }
        }
    } catch {
        return @{ matches = $false; diff = "Verify failed: $($_.Exception.Message)" }
    }
}

function Undo-GpuDriverProperty-Describe {
    param([hashtable]$Item)
    if (-not $Item -or -not $Item.state) { return 'GPU driver setting: no details available.' }
    $count = if ($Item.state.devices) { @($Item.state.devices).Count } else { 0 }
    $prop = if ($Item.params -and $Item.params.Name) { $Item.params.Name } else { $Item.state.propertyName }
    $drvVer = if ($count -gt 0 -and $Item.state.devices[0].DriverVersion) { " (driver version $($Item.state.devices[0].DriverVersion))" } else { '' }
    return "GPU driver setting '$prop' on $count device(s)${drvVer}: original state recorded."
}

function Undo-GpuDriverProperty-CheckDriverCompatibility {
    param([hashtable]$Item)
    if (-not $Item -or -not $Item.state -or -not $Item.state.devices) {
        return @{ compatible = $true; reason = $null; message = $null }
    }
    $classPath = if ($Item.params.ClassPath) { [string]$Item.params.ClassPath } else {
        'HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4d36e968-e325-11ce-bfc1-08002be10318}'
    }
    foreach ($dev in $Item.state.devices) {
        $resDev = _GpuDriverProperty_ResolveSubkey -Device $dev -ClassPath $classPath
        if ($resDev -and $resDev.error) {
            return @{
                compatible = $false
                reason     = $resDev.error
                message    = "Cannot verify GPU driver compatibility: $($resDev.error)"
            }
        }
        if ($resDev -and $resDev.incompatible) {
            return @{
                compatible = $false
                reason     = $resDev.reason
                message    = "GPU driver changed since you applied this ($($resDev.reason))."
            }
        }
    }
    return @{ compatible = $true; reason = $null; message = $null }
}

# ---- providers\Hibernation.ps1 ----
# StreamReady undo engine - provider: Hibernation (hibernation on or off, file type, file size setting, stored values)
# Written by group A because ChkDisableHibernate (powercfg -h off) needs it. Plain function definitions plus one registration.
# Dot-source safe. ASCII only.
#
# Params (hashtable): none needed (an empty hashtable is fine).
# State: enabled (hibernate supported AND the hibernation file present), s4Supported, filePresent, fileType (0 none, 1 reduced,
#   2 full; HIBERFILE_TYPE from CallNtPowerInformation), hiberboot (fast startup available), registry (the three stored values
#   HibernateEnabled, HibernateEnabledDefault, HiberFileSizePercent under HKLM\SYSTEM\CurrentControlSet\Control\Power, each
#   @{ existed; data }), ramBytes, freeBytes (system drive), expectedBytes (estimate for the free space guard).
# Restore (only when hibernation was ON before): switch it on (after a free-space check), set the file type (reduced/full)
#   and size percent through powercfg, then put the three stored values back EXACTLY (including "did not exist").
# Verify compares: on/off, file type and fast-startup availability (when it was on before) and the three stored values.
# If hibernation was OFF before, nothing is changed and nothing is compared (the tweak had nothing to turn off).
# The state "hibernation file present but S4 not supported" is refused at capture (it cannot be put back exactly).
# Why not Test-Path C:\hiberfil.sys: the file is hidden/system and Test-Path says False even when it exists (verified on this PC).
# Capabilities are read with CallNtPowerInformation (powrprof.dll), which does not depend on the language of Windows.
#
# A test can replace the real backend with $script:UndoHibernationBackend (hashtable of scriptblocks:
# Caps, SetHibernate, SetSize, SetType, Reg, RegSet, Ram, Free).

if ($null -eq $script:UndoProviders) { $script:UndoProviders = @{} }
$script:UndoProviders['Hibernation'] = @{ Capture = 'Undo-Hibernation-Capture'; Restore = 'Undo-Hibernation-Restore'; Verify = 'Undo-Hibernation-Verify'; Describe = 'Undo-Hibernation-Describe'; Validate = 'Undo-Hibernation-Validate'; VerifySeesApply = $true; Version = 1 }

function _Hib_Now { return (Get-Date).ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ssZ') }
function _Hib_RegNames { return @('HibernateEnabled', 'HibernateEnabledDefault', 'HiberFileSizePercent') }
function _Hib_RegPath { return 'HKLM:\SYSTEM\CurrentControlSet\Control\Power' }

function _Hib_EnsureApi {
    if ('SrUndoHibApi' -as [type]) { return }
    $src = @'
using System;
using System.Runtime.InteropServices;
public static class SrUndoHibApi {
    [StructLayout(LayoutKind.Sequential)]
    public struct SYSTEM_POWER_CAPABILITIES {
        [MarshalAs(UnmanagedType.U1)] public bool PowerButtonPresent; [MarshalAs(UnmanagedType.U1)] public bool SleepButtonPresent; [MarshalAs(UnmanagedType.U1)] public bool LidPresent;
        [MarshalAs(UnmanagedType.U1)] public bool SystemS1; [MarshalAs(UnmanagedType.U1)] public bool SystemS2; [MarshalAs(UnmanagedType.U1)] public bool SystemS3; [MarshalAs(UnmanagedType.U1)] public bool SystemS4; [MarshalAs(UnmanagedType.U1)] public bool SystemS5;
        [MarshalAs(UnmanagedType.U1)] public bool HiberFilePresent; [MarshalAs(UnmanagedType.U1)] public bool FullWake; [MarshalAs(UnmanagedType.U1)] public bool VideoDimPresent; [MarshalAs(UnmanagedType.U1)] public bool ApmPresent; [MarshalAs(UnmanagedType.U1)] public bool UpsPresent; [MarshalAs(UnmanagedType.U1)] public bool ThermalControl; [MarshalAs(UnmanagedType.U1)] public bool ProcessorThrottle;
        public byte ProcessorMinThrottle; public byte ProcessorMaxThrottle; [MarshalAs(UnmanagedType.U1)] public bool FastSystemS4; [MarshalAs(UnmanagedType.U1)] public bool Hiberboot; [MarshalAs(UnmanagedType.U1)] public bool WakeAlarmPresent; [MarshalAs(UnmanagedType.U1)] public bool AoAc; [MarshalAs(UnmanagedType.U1)] public bool DiskSpinDown;
        public byte HiberFileType; [MarshalAs(UnmanagedType.U1)] public bool AoAcConnectivitySupported;
        [MarshalAs(UnmanagedType.ByValArray, SizeConst = 6)] public byte[] spare3;
        [MarshalAs(UnmanagedType.U1)] public bool SystemBatteriesPresent; [MarshalAs(UnmanagedType.U1)] public bool BatteriesAreShortTerm;
        [MarshalAs(UnmanagedType.ByValArray, SizeConst = 9)] public uint[] BatteryScale; public int AcOnLineWake; public int SoftLidWake; public int RtcWake; public int MinDeviceWakeState; public int DefaultLowLatencyWake;
    }
    [DllImport("powrprof.dll")] public static extern int CallNtPowerInformation(int level, IntPtr inBuf, int inLen, out SYSTEM_POWER_CAPABILITIES outBuf, int outLen);
    public static SYSTEM_POWER_CAPABILITIES Get() {
        SYSTEM_POWER_CAPABILITIES c;
        int rc = CallNtPowerInformation(4, IntPtr.Zero, 0, out c, Marshal.SizeOf(typeof(SYSTEM_POWER_CAPABILITIES)));
        if (rc != 0) throw new Exception("CallNtPowerInformation returned " + rc);
        return c;
    }
}
'@
    Add-Type -TypeDefinition $src -ErrorAction Stop
}

function _Hib_Backend {
    if ($script:UndoHibernationBackend) { return $script:UndoHibernationBackend }
    return @{
        Caps = {
            _Hib_EnsureApi
            $c = [SrUndoHibApi]::Get()
            return @{ s4 = [bool]$c.SystemS4; filePresent = [bool]$c.HiberFilePresent; fileType = [int]$c.HiberFileType; hiberboot = [bool]$c.Hiberboot }
        }
        SetHibernate = {
            param($on)
            $out = & powercfg.exe -h $(if ($on) { 'on' } else { 'off' }) 2>&1
            if ($LASTEXITCODE -ne 0) { throw "powercfg -h failed (exit code $LASTEXITCODE): $(($out | Out-String).Trim())" }
        }
        SetSize = {
            param($pct)
            $out = & powercfg.exe /h /size ([string]$pct) 2>&1
            if ($LASTEXITCODE -ne 0) { throw "powercfg /h /size failed (exit code $LASTEXITCODE): $(($out | Out-String).Trim())" }
        }
        SetType = {
            param($type)
            $word = if ([int]$type -eq 1) { 'reduced' } elseif ([int]$type -eq 2) { 'full' } else { throw "hibernation file type $type cannot be set" }
            $out = & powercfg.exe /h /type $word 2>&1
            if ($LASTEXITCODE -ne 0) { throw "powercfg /h /type failed (exit code $LASTEXITCODE): $(($out | Out-String).Trim())" }
        }
        Reg = {
            $o = @{}
            $key = Get-Item -LiteralPath (_Hib_RegPath) -ErrorAction Stop
            foreach ($n in (_Hib_RegNames)) {
                if (@($key.GetValueNames()) -contains $n) { $o[$n] = @{ existed = $true; data = [int64]$key.GetValue($n) } } else { $o[$n] = @{ existed = $false; data = $null } }
            }
            return $o
        }
        RegSet = {
            param($name, $existed, $data)
            if ($name -notin (_Hib_RegNames)) { throw "value '$name' is not one this provider owns" }
            if ($existed) { Set-ItemProperty -LiteralPath (_Hib_RegPath) -Name $name -Value ([int]$data) -Type DWord -ErrorAction Stop }
            else { Remove-ItemProperty -LiteralPath (_Hib_RegPath) -Name $name -ErrorAction SilentlyContinue }
        }
        Ram = { return [int64](Get-CimInstance Win32_ComputerSystem -ErrorAction Stop).TotalPhysicalMemory }
        Free = {
            $d = $env:SystemDrive.TrimEnd(':')
            return [int64](Get-PSDrive -Name $d -ErrorAction Stop).Free
        }
    }
}

function _Hib_Expected {
    param([int64]$Ram, [int]$Pct)
    $p = if ($Pct -gt 0) { $Pct } else { 75 }
    return [int64]([double]$Ram * $p / 100.0)
}

function Undo-Hibernation-Capture {
    param($Params)
    $res = @{ type = 'Hibernation'; v = 1; params = $Params; state = $null; ok = $false; error = $null; capturedAt = (_Hib_Now) }
    try {
        $B = _Hib_Backend
        $caps = & $B.Caps
        if (-not [bool]$caps.s4 -and [bool]$caps.filePresent) { throw 'Windows reports a hibernation file but no hibernate support; that state cannot be put back exactly' }
        $ram = [int64](& $B.Ram); $free = [int64](& $B.Free)
        $reg = & $B.Reg
        $pct = 0; if ($reg['HiberFileSizePercent'].existed) { $pct = [int]$reg['HiberFileSizePercent'].data }
        $regCopy = @{}
        foreach ($n in (_Hib_RegNames)) { $regCopy[$n] = @{ existed = [bool]$reg[$n].existed; data = $(if ($reg[$n].existed) { [int64]$reg[$n].data } else { $null }) } }
        $res.state = @{ enabled = [bool]($caps.s4 -and $caps.filePresent); s4Supported = [bool]$caps.s4; filePresent = [bool]$caps.filePresent; fileType = [int]$caps.fileType
                        hiberboot = [bool]$caps.hiberboot; registry = $regCopy; sizePercent = $pct; ramBytes = $ram; freeBytes = $free; expectedBytes = (_Hib_Expected $ram $pct) }
        $res.ok = $true
    } catch { $res.error = "Could not record the original hibernation state: $($_.Exception.Message)" }
    return $res
}

function Undo-Hibernation-Validate {
    param($Item)
    try {
        if ($null -eq $Item -or [string]$Item.type -ne 'Hibernation') { return @{ valid = $false; reason = 'not a Hibernation record' } }
        $s = $Item.state
        if ($null -eq $s) { return @{ valid = $false; reason = 'no state' } }
        foreach ($f in @('enabled', 's4Supported', 'filePresent', 'hiberboot')) { if ($s.$f -isnot [bool]) { return @{ valid = $false; reason = "$f must be true or false" } } }
        foreach ($f in @('fileType', 'sizePercent', 'ramBytes', 'freeBytes', 'expectedBytes')) { if ([string]$s.$f -notmatch '^\d{1,19}$') { return @{ valid = $false; reason = "$f must be a non-negative number" } } }
        if ([int]$s.sizePercent -gt 100) { return @{ valid = $false; reason = 'sizePercent out of range' } }
        if ([int]$s.fileType -gt 2) { return @{ valid = $false; reason = 'fileType out of range' } }
        if ($s.enabled -and [int]$s.fileType -eq 0) { return @{ valid = $false; reason = 'an enabled hibernation needs a file type' } }
        if ($null -eq $s.registry) { return @{ valid = $false; reason = 'the stored hibernation values were not recorded' } }
        $own = _Hib_RegNames
        $names = if ($s.registry -is [System.Collections.IDictionary]) { @($s.registry.Keys | ForEach-Object { [string]$_ }) } else { @($s.registry.PSObject.Properties | ForEach-Object { [string]$_.Name }) }
        foreach ($nm in $names) { if ($nm -notin $own) { return @{ valid = $false; reason = "value '$nm' is not one this provider owns" } } }
        foreach ($nm in $own) {
            if ($nm -notin $names) { return @{ valid = $false; reason = 'a stored hibernation value is missing from the record' } }
            $e = _Hib_RegEntry $s.registry $nm
            if ($e.existed -isnot [bool]) { return @{ valid = $false; reason = 'existed must be true or false' } }
            if ($e.existed -and ([string]$e.data -notmatch '^\d{1,10}$' -or [int64]$e.data -gt 4294967295)) { return @{ valid = $false; reason = 'a stored value is out of range' } }
        }
        return @{ valid = $true; reason = $null }
    } catch { return @{ valid = $false; reason = $_.Exception.Message } }
}

function _Hib_RegEntry {
    param($Reg, [string]$Name)
    if ($Reg -is [System.Collections.IDictionary]) { return $Reg[$Name] }
    return $Reg.$Name
}

function Undo-Hibernation-Describe {
    param($Item)
    try {
        $s = $Item.state
        if (-not $s.s4Supported) { return 'Hibernation: not supported on this PC' }
        $gb = [math]::Round(([double]$s.expectedBytes) / 1GB, 1)
        $type = if ([int]$s.fileType -eq 1) { 'reduced' } elseif ([int]$s.fileType -eq 2) { 'full' } else { 'unknown type' }
        return "Hibernation: $(if ($s.enabled) { "on, $type file (about $gb GB)" } else { 'off' })"
    } catch { return 'Hibernation (record could not be read)' }
}

function Undo-Hibernation-Verify {
    param($Item)
    try {
        $B = _Hib_Backend
        $s = $Item.state
        if (-not $s.s4Supported -or -not $s.enabled) { return @{ matches = $true; diff = '' } }   # it was off (or unsupported): nothing was owned
        $caps = & $B.Caps
        $diff = @()
        $now = [bool]($caps.s4 -and $caps.filePresent)
        if (-not $now) { $diff += 'hibernation is off, was on' }
        else {
            if ([int]$caps.fileType -ne [int]$s.fileType) { $diff += "hibernation file type is $($caps.fileType), was $($s.fileType)" }
            if ([bool]$caps.hiberboot -ne [bool]$s.hiberboot) { $diff += "fast startup availability is $($caps.hiberboot), was $($s.hiberboot)" }
        }
        $reg = & $B.Reg
        foreach ($n in (_Hib_RegNames)) {
            $o = _Hib_RegEntry $s.registry $n
            $c = $reg[$n]
            if ([bool]$c.existed -ne [bool]$o.existed) { $diff += "stored value $n is $(if ($c.existed) { 'present' } else { 'absent' }), was $(if ($o.existed) { 'present' } else { 'absent' })" }
            elseif ($o.existed -and [int64]$c.data -ne [int64]$o.data) { $diff += "stored value $n is $($c.data), was $($o.data)" }
        }
        return @{ matches = ($diff.Count -eq 0); diff = ($diff -join '; ') }
    } catch { return @{ matches = $false; diff = "could not read the hibernation state: $($_.Exception.Message)" } }
}

function Undo-Hibernation-Restore {
    param($Item)
    $details = New-Object System.Collections.ArrayList
    $add = { param($part, $ok, $msg) [void]$details.Add(@{ part = $part; ok = $ok; message = $msg }) }
    try {
        $val = Undo-Hibernation-Validate $Item
        if (-not $val.valid) { return @{ ok = $false; partial = $false; message = "Refused: the saved hibernation record is not valid ($($val.reason))."; details = @() } }
        $B = _Hib_Backend
        $s = $Item.state
        if (-not $s.s4Supported) { return @{ ok = $true; partial = $false; message = 'Hibernation is not supported on this PC, so there is nothing to put back.'; details = @() } }
        if (-not $s.enabled) {
            return @{ ok = $true; partial = $false; message = 'Hibernation was already off before, so it is left as it is.'; details = @() }
        }
        $caps = & $B.Caps
        $nowOn = [bool]($caps.s4 -and $caps.filePresent)
        if (-not $nowOn) {
            $free = [int64](& $B.Free)
            $need = [int64](_Hib_Expected ([int64]$s.ramBytes) ([int]$s.sizePercent))
            if ($free -lt ($need + 1GB)) {
                $needGb = [math]::Round($need / 1GB, 1); $freeGb = [math]::Round($free / 1GB, 1)
                return @{ ok = $false; partial = $false; message = "Hibernation was not switched back on: it needs about $needGb GB of free disk space and only $freeGb GB is free. Free some space and undo again."; details = @() }
            }
            try { & $B.SetHibernate $true; & $add 'hibernation' $true 'hibernation switched on; Windows recreates the hibernation file' } catch { return @{ ok = $false; partial = $false; message = "Could not switch hibernation back on: $($_.Exception.Message)"; details = @() } }
        } else { & $add 'hibernation' $true 'hibernation is already on' }

        $caps2 = & $B.Caps
        if ([int]$caps2.fileType -ne [int]$s.fileType) {
            try { & $B.SetType ([int]$s.fileType); & $add 'type' $true "hibernation file type set back to $(if ([int]$s.fileType -eq 1) { 'reduced' } else { 'full' })" } catch { & $add 'type' $false $_.Exception.Message }
        }
        $regNow = & $B.Reg
        $wantPct = _Hib_RegEntry $s.registry 'HiberFileSizePercent'
        if ($wantPct.existed -and [int]$wantPct.data -ge 40 -and [int64]$regNow['HiberFileSizePercent'].data -ne [int64]$wantPct.data) {
            try { & $B.SetSize ([int]$wantPct.data); & $add 'size' $true "hibernation file size setting put back to $($wantPct.data) percent" } catch { & $add 'size' $false $_.Exception.Message }
        }
        # the three stored values, exactly as they were (including "did not exist")
        $regNow = & $B.Reg
        foreach ($n in (_Hib_RegNames)) {
            $o = _Hib_RegEntry $s.registry $n; $c = $regNow[$n]
            $same = ([bool]$c.existed -eq [bool]$o.existed) -and (-not $o.existed -or [int64]$c.data -eq [int64]$o.data)
            if ($same) { continue }
            try { & $B.RegSet $n ([bool]$o.existed) $o.data; & $add "value:$n" $true "stored value $n put back" } catch { & $add "value:$n" $false "could not put the stored value $n back: $($_.Exception.Message)" }
        }
        $v = Undo-Hibernation-Verify $Item
        $anyFail = (@($details.ToArray() | Where-Object { -not $_.ok }).Count -gt 0)
        if ($v.matches -and -not $anyFail) { return @{ ok = $true; partial = $false; message = 'Hibernation was switched back on. Windows recreates the hibernation file, which uses disk space.'; details = @($details.ToArray()) } }
        return @{ ok = $false; partial = $true; message = "Hibernation could not be fully put back: $($v.diff)"; details = @($details.ToArray()) }
    } catch {
        return @{ ok = $false; partial = $false; message = "Could not put hibernation back: $($_.Exception.Message)"; details = @($details.ToArray()) }
    }
}

# ---- providers\LsaSecret.ps1 ----
# LsaSecret provider (group D). Params: Name (LSA secret name, for example 'DefaultPassword').
# State: only whether the secret EXISTED before. The secret VALUE is never read into a record and never written to disk.
# Restore: a secret that did not exist before is deleted; a secret that existed before cannot be put back (its old value was not
# stored on purpose), so Restore leaves it and says so in plain words. Verify cannot compare a value; for "existed before" it only
# checks the secret is still there. If the secret cannot be queried (access denied) the record says existence is unknown and
# Restore does not delete anything.

if (-not $script:UndoProviders) { $script:UndoProviders = @{} }
$script:UndoProviders['LsaSecret'] = @{ Capture = 'Undo-LsaSecret-Capture'; Restore = 'Undo-LsaSecret-Restore'; Verify = 'Undo-LsaSecret-Verify'; Describe = 'Undo-LsaSecret-Describe'; Validate = 'Undo-LsaSecret-Validate'; VerifySeesApply = $false; Version = 1 }

function _LsaSecret_Type {
    if (([System.Management.Automation.PSTypeName]'SRUndoLsa').Type) { return }
    Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;
public class SRUndoLsa {
    [StructLayout(LayoutKind.Sequential)] public struct LSA_UNICODE_STRING { public ushort Length; public ushort MaximumLength; public IntPtr Buffer; }
    [StructLayout(LayoutKind.Sequential)] public struct LSA_OBJECT_ATTRIBUTES { public int Length; public IntPtr RootDirectory; public IntPtr ObjectName; public uint Attributes; public IntPtr SecurityDescriptor; public IntPtr SecurityQualityOfService; }
    [DllImport("advapi32.dll")] public static extern uint LsaOpenPolicy(ref LSA_UNICODE_STRING SystemName, ref LSA_OBJECT_ATTRIBUTES ObjectAttributes, int AccessMask, out IntPtr PolicyHandle);
    [DllImport("advapi32.dll")] public static extern uint LsaRetrievePrivateData(IntPtr PolicyHandle, ref LSA_UNICODE_STRING KeyName, out IntPtr PrivateData);
    [DllImport("advapi32.dll", EntryPoint = "LsaStorePrivateData")] public static extern uint LsaStorePrivateDataSet(IntPtr PolicyHandle, ref LSA_UNICODE_STRING KeyName, ref LSA_UNICODE_STRING PrivateData);
    [DllImport("advapi32.dll", EntryPoint = "LsaStorePrivateData")] public static extern uint LsaStorePrivateDataDelete(IntPtr PolicyHandle, ref LSA_UNICODE_STRING KeyName, IntPtr PrivateData);
    [DllImport("advapi32.dll")] public static extern uint LsaFreeMemory(IntPtr Buffer);
    [DllImport("advapi32.dll")] public static extern uint LsaClose(IntPtr PolicyHandle);
}
'@
}
function _LsaSecret_Str {
    param([string]$S)
    $u = New-Object SRUndoLsa+LSA_UNICODE_STRING
    if ([string]::IsNullOrEmpty($S)) { $u.Buffer = [IntPtr]::Zero; $u.Length = 0; $u.MaximumLength = 0 }
    else { $u.Buffer = [Runtime.InteropServices.Marshal]::StringToHGlobalUni($S); $u.Length = [uint16]($S.Length * 2); $u.MaximumLength = [uint16](($S.Length + 1) * 2) }
    return $u
}
function _LsaSecret_Open {
    param([int]$Access)
    _LsaSecret_Type
    $sys = New-Object SRUndoLsa+LSA_UNICODE_STRING
    $oa = New-Object SRUndoLsa+LSA_OBJECT_ATTRIBUTES; $oa.Length = [Runtime.InteropServices.Marshal]::SizeOf($oa)
    $h = [IntPtr]::Zero
    $st = [SRUndoLsa]::LsaOpenPolicy([ref]$sys, [ref]$oa, $Access, [ref]$h)
    if ($st -ne 0) { throw ("LsaOpenPolicy status 0x{0:X8}" -f $st) }
    return $h
}
function _LsaSecret_Exists {
    # returns 'yes' | 'no' | 'unknown'
    param([string]$Name)
    $h = $null
    try {
        $h = _LsaSecret_Open 4      # POLICY_GET_PRIVATE_INFORMATION
        $k = _LsaSecret_Str $Name
        $data = [IntPtr]::Zero
        try {
            $st = [SRUndoLsa]::LsaRetrievePrivateData($h, [ref]$k, [ref]$data)
            if ($st -eq 0) { if ($data -ne [IntPtr]::Zero) { [void][SRUndoLsa]::LsaFreeMemory($data) }; return 'yes' }
            if ($st -eq 3221225524) { return 'no' }      # 0xC0000034 STATUS_OBJECT_NAME_NOT_FOUND
            return 'unknown'
        } finally { if ($k.Buffer -ne [IntPtr]::Zero) { [Runtime.InteropServices.Marshal]::FreeHGlobal($k.Buffer) } }
    } catch { return 'unknown' }
    finally { if ($h -and $h -ne [IntPtr]::Zero) { [void][SRUndoLsa]::LsaClose($h) } }
}
function _LsaSecret_Delete {
    param([string]$Name)
    $h = _LsaSecret_Open 32     # POLICY_CREATE_SECRET
    try {
        $k = _LsaSecret_Str $Name
        try { $st = [SRUndoLsa]::LsaStorePrivateDataDelete($h, [ref]$k, [IntPtr]::Zero); if ($st -ne 0 -and $st -ne 3221225524) { throw ("LsaStorePrivateData status 0x{0:X8}" -f $st) } }
        finally { if ($k.Buffer -ne [IntPtr]::Zero) { [Runtime.InteropServices.Marshal]::FreeHGlobal($k.Buffer) } }
    } finally { [void][SRUndoLsa]::LsaClose($h) }
}
function Undo-LsaSecret-Capture {
    param([hashtable]$Params)
    $out = @{ type = 'LsaSecret'; v = 1; params = $Params; state = $null; ok = $false; error = $null; capturedAt = (Undo-Now) }
    try {
        $n = [string]$Params['Name']
        if ($n -notmatch '^[A-Za-z0-9_.-]{1,64}$') { throw 'secret name not allowed' }
        $e = _LsaSecret_Exists $n
        $out.state = @{ name = $n; existed = $e }      # 'yes' | 'no' | 'unknown'; the value is never stored
        $out.ok = $true
    } catch { $out.error = "could not check the stored secret: $($_.Exception.Message)" }
    return $out
}
function Undo-LsaSecret-Restore {
    param($Item)
    try {
        $st = ConvertTo-UndoPlain $Item['state']
        $n = [string]$st['name']
        switch ([string]$st['existed']) {
            'no' {
                $cur = _LsaSecret_Exists $n
                if ($cur -eq 'yes') { _LsaSecret_Delete $n; $cur = _LsaSecret_Exists $n }
                if ($cur -eq 'no') { return @{ ok = $true; partial = $false; message = 'the stored secret StreamReady added was deleted'; details = @() } }
                # 'unknown' (the check failed) or still there: never proof that the new password is gone
                return @{ ok = $false; partial = $true; message = 'StreamReady could not confirm that the stored password it added is gone (Windows did not answer the check). Treat it as still stored: turn automatic sign-in off, or enter your password again in Windows settings.'; details = @(@{ status = 'UserActionRequired' }) }
            }
            'yes' {
                return @{ ok = $false; partial = $true; message = 'A stored password existed before and StreamReady does not keep a copy of any password, so it cannot be put back. Enter your password again to turn automatic sign-in back on.'; details = @(@{ status = 'UserActionRequired'; ok = $false; message = 'stored password cannot be restored' }) }
            }
            default {
                return @{ ok = $false; partial = $true; message = 'Windows did not let StreamReady check whether a stored password existed before, so nothing was deleted and the stored password may not be the old one. Enter your password again if automatic sign-in matters to you.'; details = @(@{ status = 'UserActionRequired'; ok = $false; message = 'stored password state unknown' }) }
            }
        }
    } catch { return @{ ok = $false; partial = $false; message = "stored secret: $($_.Exception.Message)"; details = @() } }
}
function Undo-LsaSecret-Verify {
    param($Item)
    try {
        $st = ConvertTo-UndoPlain $Item['state']
        $now = _LsaSecret_Exists ([string]$st['name'])
        switch ([string]$st['existed']) {
            'no'  { if ($now -eq 'no') { return @{ matches = $true; diff = '' } }; if ($now -eq 'yes') { return @{ matches = $false; diff = "the stored secret $($st['name']) exists but did not before" } }; return @{ matches = $false; diff = "it could not be checked whether the stored secret $($st['name']) is gone (unknown is not proof)" } }
            'yes' { return @{ matches = $false; diff = "the stored secret $($st['name']) cannot be compared with the old one (its value was not saved)" } }
            default { return @{ matches = $false; diff = "the stored secret $($st['name']) cannot be compared (its state before is unknown)" } }
        }
    } catch { return @{ matches = $false; diff = $_.Exception.Message } }
}
function Undo-LsaSecret-Describe {
    param($Item)
    try {
        $s = $Item['state']
        switch ([string]$s['existed']) { 'yes' { return "Stored Windows secret $($s['name']) existed (value not saved)" } 'no' { return "Stored Windows secret $($s['name']) did not exist" } default { return "Stored Windows secret $($s['name']): existence unknown" } }
    } catch { return 'Stored Windows secret' }
}
function Undo-LsaSecret-Validate {
    param($Item)
    try {
        if ([string]$Item['params']['Name'] -notmatch '^[A-Za-z0-9_.-]{1,64}$') { return @{ valid = $false; reason = 'secret name not allowed' } }
        if ([string]$Item['state']['name'] -ne [string]$Item['params']['Name']) { return @{ valid = $false; reason = 'state does not match its secret' } }
        if ([string]$Item['state']['existed'] -notin @('yes', 'no', 'unknown')) { return @{ valid = $false; reason = 'existence flag not allowed' } }
        return @{ valid = $true; reason = $null }
    } catch { return @{ valid = $false; reason = $_.Exception.Message } }
}

# ---- providers\MMAgent.ps1 ----
# StreamReady undo engine - provider: MMAgent (Windows memory management agent switches, for example memory compression)
# EXTRA provider written by group A because ChkMemCompDisable (Disable-MMAgent) needs it; it is not on the original list.
# Plain function definitions plus one registration. Dot-source safe. ASCII only.
#
# Params (hashtable): Switches = names this tweak changes (default @('MemoryCompression')). Allowed names:
#   MemoryCompression, PageCombining, ApplicationLaunchPrefetching, ApplicationPreLaunch
# State: values (all four switches as booleans, captured for the record), switches (the ones restore may change).
# Changes take effect after a restart (Microsoft documentation; not verifiable from the code), so restore reports restart needed.
#
# A test can replace the real backend with $script:UndoMMAgentBackend (hashtable of scriptblocks: Get, Set).

if ($null -eq $script:UndoProviders) { $script:UndoProviders = @{} }
$script:UndoProviders['MMAgent'] = @{ Capture = 'Undo-MMAgent-Capture'; Restore = 'Undo-MMAgent-Restore'; Verify = 'Undo-MMAgent-Verify'; Describe = 'Undo-MMAgent-Describe'; Validate = 'Undo-MMAgent-Validate'; VerifySeesApply = $true; Version = 1 }

function _MMA_Now { return (Get-Date).ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ssZ') }
function _MMA_Names { return @('MemoryCompression', 'PageCombining', 'ApplicationLaunchPrefetching', 'ApplicationPreLaunch') }
function _MMA_Switches { param($P) $s = @(); if ($P -and $P.Switches) { $s = @($P.Switches | ForEach-Object { [string]$_ }) }; if ($s.Count -eq 0) { $s = @('MemoryCompression') }; return $s }

function _MMA_Backend {
    if ($script:UndoMMAgentBackend) { return $script:UndoMMAgentBackend }
    return @{
        Get = {
            $a = Get-MMAgent -ErrorAction Stop
            return @{ MemoryCompression = [bool]$a.MemoryCompression; PageCombining = [bool]$a.PageCombining; ApplicationLaunchPrefetching = [bool]$a.ApplicationLaunchPrefetching; ApplicationPreLaunch = [bool]$a.ApplicationPreLaunch }
        }
        Set = {
            param($name, $on)
            $splat = @{ $name = $true; ErrorAction = 'Stop' }
            if ($on) { Enable-MMAgent @splat | Out-Null } else { Disable-MMAgent @splat | Out-Null }
        }
    }
}

function Undo-MMAgent-Capture {
    param($Params)
    $res = @{ type = 'MMAgent'; v = 1; params = $Params; state = $null; ok = $false; error = $null; capturedAt = (_MMA_Now) }
    try {
        $sw = _MMA_Switches $Params
        foreach ($n in $sw) { if ($n -notin (_MMA_Names)) { throw "switch '$n' is not supported" } }
        $B = _MMA_Backend
        $vals = & $B.Get
        $res.state = @{ values = @{ MemoryCompression = [bool]$vals.MemoryCompression; PageCombining = [bool]$vals.PageCombining; ApplicationLaunchPrefetching = [bool]$vals.ApplicationLaunchPrefetching; ApplicationPreLaunch = [bool]$vals.ApplicationPreLaunch }; switches = @($sw) }
        $res.ok = $true
    } catch { $res.error = "Could not record the original memory management settings: $($_.Exception.Message)" }
    return $res
}

function Undo-MMAgent-Validate {
    param($Item)
    try {
        if ($null -eq $Item -or [string]$Item.type -ne 'MMAgent') { return @{ valid = $false; reason = 'not an MMAgent record' } }
        $s = $Item.state
        if ($null -eq $s) { return @{ valid = $false; reason = 'no state' } }
        $own = _MMA_Switches $Item.params
        # the record must hold exactly the switches the spec owns: an empty or shortened list would make Undo do nothing and say it is done
        $saved = @($s.switches | ForEach-Object { [string]$_ } | Sort-Object -Unique)
        if ($saved.Count -eq 0) { return @{ valid = $false; reason = 'no switches were recorded' } }
        if (($saved -join ',') -ne (@($own | Sort-Object -Unique) -join ',')) { return @{ valid = $false; reason = 'the recorded switches do not match the parameters' } }
        foreach ($n in @($s.switches)) { if ([string]$n -notin (_MMA_Names) -or [string]$n -notin $own) { return @{ valid = $false; reason = "switch '$n' is not one this tweak owns" } } }
        foreach ($n in (_MMA_Names)) { if ($s.values.$n -isnot [bool]) { return @{ valid = $false; reason = "$n must be true or false" } } }
        return @{ valid = $true; reason = $null }
    } catch { return @{ valid = $false; reason = $_.Exception.Message } }
}

function Undo-MMAgent-Describe {
    param($Item)
    try {
        $parts = @(); foreach ($n in @($Item.state.switches)) { $parts += "$n $(if ($Item.state.values.$n) { 'on' } else { 'off' })" }
        return 'Windows memory management: ' + ($parts -join ', ')
    } catch { return 'Windows memory management (record could not be read)' }
}

function Undo-MMAgent-Verify {
    param($Item)
    try {
        $B = _MMA_Backend
        $now = & $B.Get
        $diff = @()
        foreach ($n in @($Item.state.switches)) { if ([bool]$now[$n] -ne [bool]$Item.state.values.$n) { $diff += "$n is $(if ($now[$n]) { 'on' } else { 'off' }), was $(if ($Item.state.values.$n) { 'on' } else { 'off' })" } }
        return @{ matches = ($diff.Count -eq 0); diff = ($diff -join '; ') }
    } catch { return @{ matches = $false; diff = "could not read the memory management settings: $($_.Exception.Message)" } }
}

function Undo-MMAgent-Restore {
    param($Item)
    $details = New-Object System.Collections.ArrayList
    $add = { param($part, $ok, $msg) [void]$details.Add(@{ part = $part; ok = $ok; message = $msg }) }
    try {
        $val = Undo-MMAgent-Validate $Item
        if (-not $val.valid) { return @{ ok = $false; partial = $false; message = "Refused: the saved memory management record is not valid ($($val.reason))."; details = @(); restartNeeded = $false } }
        $B = _MMA_Backend
        $now = & $B.Get
        $changed = $false
        foreach ($n in @($Item.state.switches)) {
            $want = [bool]$Item.state.values.$n
            if ([bool]$now[$n] -eq $want) { & $add $n $true 'already the original setting'; continue }
            try { & $B.Set $n $want; $changed = $true; & $add $n $true "set back to $(if ($want) { 'on' } else { 'off' })" } catch { & $add $n $false $_.Exception.Message }
        }
        $v = Undo-MMAgent-Verify $Item
        $anyFail = (@($details.ToArray() | Where-Object { -not $_.ok }).Count -gt 0)
        if ($v.matches -and -not $anyFail) {
            $m = if ($changed) { 'The memory management setting was put back. Restart your PC for it to take effect.' } else { 'The memory management setting was already the original, nothing to change.' }
            return @{ ok = $true; partial = $false; message = $m; details = @($details.ToArray()); restartNeeded = [bool]$changed }
        }
        return @{ ok = $false; partial = $true; message = "The memory management setting could not be fully put back: $($v.diff)"; details = @($details.ToArray()); restartNeeded = [bool]$changed }
    } catch {
        return @{ ok = $false; partial = $false; message = "Could not put the memory management setting back: $($_.Exception.Message)"; details = @($details.ToArray()); restartNeeded = $false }
    }
}

# ---- providers\NetAdapterDns.ps1 ----
# NetAdapterDns provider (group D). Params: Scope = 'Up' (adapters whose status is Up at capture time, the default) or 'All'.
# One item holds every adapter found, each identified by InterfaceGuid. For each adapter and each family (IPv4, IPv6) it records
# whether the DNS servers were typed in by hand (static) or came from DHCP, and the server list in order. The "static" flag is
# read from the interface registry value NameServer, because Get-DnsClientServerAddress does not say where the list came from.
# Restore: an adapter that was automatic is reset to automatic, one that was static gets its list back in the same order,
# an adapter that is gone is reported and skipped. Test hook: $script:SRUndoDnsRegBase (default HKLM:\SYSTEM\CurrentControlSet\Services).

if (-not $script:UndoProviders) { $script:UndoProviders = @{} }
$script:UndoProviders['NetAdapterDns'] = @{ Capture = 'Undo-NetAdapterDns-Capture'; Restore = 'Undo-NetAdapterDns-Restore'; Verify = 'Undo-NetAdapterDns-Verify'; Describe = 'Undo-NetAdapterDns-Describe'; Validate = 'Undo-NetAdapterDns-Validate'; VerifySeesApply = $true; Version = 1 }

function _NetAdapterDns_RegBase { if ($script:SRUndoDnsRegBase) { return $script:SRUndoDnsRegBase }; return 'HKLM:\SYSTEM\CurrentControlSet\Services' }
function _NetAdapterDns_StaticList {
    # returns @{ static = bool; list = string[] } for one family from the interface registry key
    param([string]$Guid, [string]$Family)
    $sub = if ($Family -eq 'v6') { 'Tcpip6' } else { 'Tcpip' }
    $k = Join-Path (_NetAdapterDns_RegBase) "$sub\Parameters\Interfaces\$Guid"
    $v = $null
    if (Test-Path -LiteralPath $k) { $v = (Get-ItemProperty -LiteralPath $k -ErrorAction Stop).NameServer }
    $list = @()
    if ($v) { $list = @(([string]$v) -split '[,\s;]+' | Where-Object { $_ }) }
    return @{ static = ($list.Count -gt 0); list = $list }
}
function _NetAdapterDns_Servers {
    param([int]$IfIndex, [string]$Family)
    $af = if ($Family -eq 'v6') { 'IPv6' } else { 'IPv4' }
    $a = @(Get-DnsClientServerAddress -InterfaceIndex $IfIndex -AddressFamily $af -ErrorAction Stop)
    $s = @()
    foreach ($x in $a) { $s += @($x.ServerAddresses) }
    return @($s | Where-Object { $_ })
}
function _NetAdapterDns_Adapters {
    param([string]$Scope)
    $list = @(Get-NetAdapter -ErrorAction Stop)
    if ($Scope -ne 'All') { $list = @($list | Where-Object { $_.Status -eq 'Up' }) }
    return $list
}
function _NetAdapterDns_Read {
    param([string]$Scope)
    $out = @()
    foreach ($ad in (_NetAdapterDns_Adapters $Scope)) {
        $g = [string]$ad.InterfaceGuid
        $s4 = _NetAdapterDns_StaticList $g 'v4'; $s6 = _NetAdapterDns_StaticList $g 'v6'
        $out += , @{
            guid = $g; name = [string]$ad.Name; desc = [string]$ad.InterfaceDescription; virtual = (-not [bool]$ad.HardwareInterface)
            v4 = @{ static = $s4.static; static_list = @($s4.list); servers = @(_NetAdapterDns_Servers ([int]$ad.ifIndex) 'v4') }
            v6 = @{ static = $s6.static; static_list = @($s6.list); servers = @(_NetAdapterDns_Servers ([int]$ad.ifIndex) 'v6') }
        }
    }
    return $out
}
function Undo-NetAdapterDns-Capture {
    param([hashtable]$Params)
    $out = @{ type = 'NetAdapterDns'; v = 1; params = $Params; state = $null; ok = $false; error = $null; capturedAt = (Undo-Now) }
    try {
        $scope = if ($Params.ContainsKey('Scope') -and $Params['Scope']) { [string]$Params['Scope'] } else { 'Up' }
        $out.state = @{ scope = $scope; adapters = @(_NetAdapterDns_Read $scope) }
        $out.ok = $true
    } catch { $out.error = "could not read the DNS settings of the network adapters: $($_.Exception.Message)" }
    return $out
}
function _NetAdapterDns_Find {
    param([string]$Guid)
    foreach ($ad in @(Get-NetAdapter -IncludeHidden -ErrorAction SilentlyContinue)) { if ([string]$ad.InterfaceGuid -eq $Guid) { return $ad } }
    return $null
}
function Undo-NetAdapterDns-Restore {
    param($Item)
    $notes = @(); $bad = 0; $deferred = @()
    try {
        $st = ConvertTo-UndoPlain $Item['state']
        foreach ($a in @($st['adapters'])) {
            $ad = _NetAdapterDns_Find ([string]$a['guid'])
            if (-not $ad) { $bad++; $deferred += [string]$a['name']; $notes += "adapter $($a['name']) is not connected now, so its DNS was NOT put back. Its saved original is kept: connect it and press Undo again, or give it up in History"; continue }
            try {
                $idx = [int]$ad.ifIndex
                $want4 = @($a['v4']['static_list']); $want6 = @($a['v6']['static_list'])
                $now4 = _NetAdapterDns_StaticList ([string]$a['guid']) 'v4'; $now6 = _NetAdapterDns_StaticList ([string]$a['guid']) 'v6'
                $needReset = ((-not $a['v4']['static']) -and $now4.static) -or ((-not $a['v6']['static']) -and $now6.static)
                if ($needReset) { Set-DnsClientServerAddress -InterfaceIndex $idx -ResetServerAddresses -ErrorAction Stop }
                # a reset may clear both families, so look again before setting the static ones
                $now4 = _NetAdapterDns_StaticList ([string]$a['guid']) 'v4'; $now6 = _NetAdapterDns_StaticList ([string]$a['guid']) 'v6'
                if ($a['v4']['static'] -and (($now4.list -join ',') -ne ($want4 -join ','))) { Set-DnsClientServerAddress -InterfaceIndex $idx -ServerAddresses $want4 -ErrorAction Stop }
                if ($a['v6']['static'] -and (($now6.list -join ',') -ne ($want6 -join ','))) { Set-DnsClientServerAddress -InterfaceIndex $idx -ServerAddresses $want6 -ErrorAction Stop }
            } catch { $bad++; $notes += "adapter $($a['name']): $($_.Exception.Message)" }
        }
        if ($script:SRUndoDnsCheck -and -not $script:SRUndoDnsSkipResolve) {      # opt-in only: the engine itself makes no network access
            $okName = $true
            try { $null = Resolve-DnsName -Name 'www.microsoft.com' -DnsOnly -QuickTimeout -ErrorAction Stop } catch { $okName = $false }
            if (-not $okName) { $notes += 'a test name lookup failed after the change; check the network, or set DNS to automatic in Settings' }
        }
        $det = @($notes); if ($deferred.Count -gt 0) { $det = @(@{ status = 'Deferred'; adapters = @($deferred) }) }
        return @{ ok = ($bad -eq 0); partial = ($bad -gt 0); message = $(if ($notes.Count -gt 0) { $notes -join '; ' } else { 'DNS servers put back' }); details = $det }
    } catch { return @{ ok = $false; partial = $false; message = "DNS restore failed: $($_.Exception.Message)"; details = @() } }
}
function Undo-NetAdapterDns-Verify {
    param($Item)
    try {
        $st = ConvertTo-UndoPlain $Item['state']
        $diffs = @()
        foreach ($a in @($st['adapters'])) {
            if (-not (_NetAdapterDns_Find ([string]$a['guid']))) { $diffs += "adapter $($a['name']) is not connected, so its DNS cannot be confirmed"; continue }   # never counted as matching
            foreach ($fam in 'v4', 'v6') {
                $now = _NetAdapterDns_StaticList ([string]$a['guid']) $fam
                if ([bool]$a[$fam]['static'] -ne [bool]$now.static) { $diffs += "$($a['name']) $fam is $(if ($now.static) { 'set by hand' } else { 'automatic' }), was $(if ($a[$fam]['static']) { 'set by hand' } else { 'automatic' })"; continue }
                if ($a[$fam]['static'] -and (($now.list -join ',') -ne (@($a[$fam]['static_list']) -join ','))) { $diffs += "$($a['name']) $fam servers are $($now.list -join ', '), were $(@($a[$fam]['static_list']) -join ', ')" }
            }
        }
        if ($diffs.Count -gt 0) { return @{ matches = $false; diff = ($diffs -join '; ') } }
        return @{ matches = $true; diff = '' }
    } catch { return @{ matches = $false; diff = "could not read the DNS settings: $($_.Exception.Message)" } }
}
function Undo-NetAdapterDns-Describe {
    param($Item)
    try {
        $st = ConvertTo-UndoPlain $Item['state']
        $parts = @()
        foreach ($a in @($st['adapters'])) {
            $v4 = if ($a['v4']['static']) { "set by hand: $(@($a['v4']['static_list']) -join ', ')" } else { "automatic ($(@($a['v4']['servers']) -join ', '))" }
            $parts += "$($a['name']) $v4"
        }
        if ($parts.Count -eq 0) { return 'DNS servers: no active network adapter' }
        return "DNS servers: $($parts -join '; ')"
    } catch { return 'DNS servers' }
}
function Undo-NetAdapterDns-Validate {
    param($Item)
    try {
        $st = $Item['state']
        if ([string]$st['scope'] -notin @('Up', 'All')) { return @{ valid = $false; reason = 'scope not allowed' } }
        foreach ($a in @($st['adapters'])) {
            if ([string]$a['guid'] -notmatch '^\{[0-9a-fA-F-]{36}\}$') { return @{ valid = $false; reason = 'adapter id not allowed' } }
            foreach ($fam in 'v4', 'v6') {
                foreach ($ip in @($a[$fam]['static_list'])) {
                    $o = $null
                    if (-not [System.Net.IPAddress]::TryParse([string]$ip, [ref]$o)) { return @{ valid = $false; reason = 'a DNS address is not an address' } }
                }
            }
        }
        return @{ valid = $true; reason = $null }
    } catch { return @{ valid = $false; reason = $_.Exception.Message } }
}

# ---- providers\NicAdvanced.ps1 ----
if (-not $script:UndoProviders) { $script:UndoProviders = @{} }
# Per-adapter originals. Native access is isolated for mock-only restore tests.
function _NicAdvanced_Field { param($O,[string]$N,$D=$null) if($null -eq $O){return $D};if($O -is [Collections.IDictionary]){if($O.Contains($N)){return $O[$N]}}elseif($O.PSObject.Properties[$N]){return $O.$N};return $D }
function _NicAdvanced_Canonical {
    param($Value)
    if($null -eq $Value){return $null}
    if($Value -is [Collections.IDictionary]){$o=[ordered]@{};foreach($k in @($Value.Keys | Sort-Object)){$o[[string]$k]=_NicAdvanced_Canonical $Value[$k]};return $o}
    if($Value -is [array]){return ,@($Value | ForEach-Object {_NicAdvanced_Canonical $_})}
    return $Value
}
function _NicAdvanced_Json { param($Value) return (ConvertTo-Json -InputObject (_NicAdvanced_Canonical $Value) -Depth 20 -Compress) }
function _NicAdvanced_Adapters {
    param([switch]$IncludeHidden)
    $out=@()
    $list=if($IncludeHidden){@(Get-NetAdapter -IncludeHidden -ErrorAction Stop)}else{@(Get-NetAdapter -ErrorAction Stop)}
    foreach($a in $list){
        $g=([guid]$a.InterfaceGuid).ToString()
        $w=@(Get-CimInstance Win32_NetworkAdapter -Filter ("GUID = '{"+$g+"}'") -ErrorAction Stop)
        if($w.Count -ne 1 -or -not $w[0].PNPDeviceID){if($IncludeHidden){continue};throw 'A selected adapter has no readable stable device identity.'}
        if(-not $a.DriverVersion){if($IncludeHidden){continue};throw 'A selected adapter has no readable driver version.'}
        $out+=,@{guid=$g;pnp=[string]$w[0].PNPDeviceID;name=[string]$a.Name;description=[string]$a.InterfaceDescription;up=([string]$a.Status -eq 'Up');driver=[string]$a.DriverVersion;native=$a}
    };return $out
}
function _NicAdvanced_Select {
    param($Params)
    $all=@(_NicAdvanced_Adapters);$mode=[string]$Params.Mode
    if($mode -eq 'TcpPrimary'){
        if(-not(Get-Command Get-ActiveAdapterIfacePath -ErrorAction SilentlyContinue)){throw 'The active-interface resolver is unavailable.'}
        $p=[string](Get-ActiveAdapterIfacePath)
        if($p -notmatch '\\Interfaces\\\{?([0-9a-fA-F-]{36})\}?$'){throw 'The active interface could not be identified unambiguously.'}
        $g=([guid]$Matches[1]).ToString();$picked=@($all | Where-Object {$_.guid -eq $g})
        if($picked.Count -ne 1){throw 'The active interface does not map to one stable device.'};return $picked
    }
    $ids=@(_NicAdvanced_Field $Params 'InterfaceGuids' @())
    if($ids.Count){$all=@($all | Where-Object {$ids -contains $_.guid -or $ids -contains ('{'+$_.guid+'}')});if($all.Count -ne @($ids | Select-Object -Unique).Count){throw 'A planned adapter disappeared before capture.'}}
    if(_NicAdvanced_Field $Params 'UpOnly' $false){$all=@($all | Where-Object {$_.up})}
    $exclude=[string](_NicAdvanced_Field $Params 'ExcludeDescription' '')
    if($exclude){$all=@($all | Where-Object {$_.description -notmatch $exclude})}
    return $all
}
function _NicAdvanced_ClassPath {
    param($Adapter)
    $base='SYSTEM\CurrentControlSet\Control\Class\{4d36e972-e325-11ce-bfc1-08002be10318}'
    $h=[Microsoft.Win32.RegistryKey]::OpenBaseKey([Microsoft.Win32.RegistryHive]::LocalMachine,[Microsoft.Win32.RegistryView]::Registry64)
    try{
        $root=$h.OpenSubKey($base,$false);if(-not $root){throw 'Network driver class is missing.'}
        try{
            $found=@()
            foreach($n in $root.GetSubKeyNames()){
                if($n -notmatch '^\d{4}$'){continue}
                $k=$root.OpenSubKey($n,$false)
                try{if($k -and [string]$k.GetValue('NetCfgInstanceId') -eq ('{'+$Adapter.guid+'}')){$found+=,($base+'\'+$n)}elseif($k -and [string]$k.GetValue('NetCfgInstanceId') -eq $Adapter.guid){$found+=,($base+'\'+$n)}}finally{if($k){$k.Dispose()}}
            }
            if($found.Count -ne 1){throw 'The network driver identity is missing or ambiguous.'};return $found[0]
        }finally{$root.Dispose()}
    }finally{$h.Dispose()}
}
function _NicAdvanced_RegRead {
    param([string]$Path,[string]$Name)
    $h=[Microsoft.Win32.RegistryKey]::OpenBaseKey([Microsoft.Win32.RegistryHive]::LocalMachine,[Microsoft.Win32.RegistryView]::Registry64)
    try{
        $k=$h.OpenSubKey($Path,$false)
        if(-not $k){return @{name=$Name;keyExisted=$false;existed=$false;kind=$null;data=$null}}
        try{
            $r=@{name=$Name;keyExisted=$true;existed=(@($k.GetValueNames()) -contains $Name);kind=$null;data=$null}
            if($r.existed){
                $r.kind=[string]$k.GetValueKind($Name);$v=$k.GetValue($Name,$null,[Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames)
                if($r.kind -in @('Binary','None')){$r.data=[Convert]::ToBase64String([byte[]]$v)}elseif($r.kind -in @('DWord','QWord')){$r.data=[string]$v}elseif($r.kind -eq 'MultiString'){$r.data=@([string[]]$v)}else{$r.data=[string]$v}
            };return $r
        }finally{$k.Dispose()}
    }finally{$h.Dispose()}
}
function _NicAdvanced_RegWrite {
    param([string]$Path,$Value)
    $h=[Microsoft.Win32.RegistryKey]::OpenBaseKey([Microsoft.Win32.RegistryHive]::LocalMachine,[Microsoft.Win32.RegistryView]::Registry64)
    try{
        $k=$h.OpenSubKey($Path,$true);if(-not $k){throw 'The recorded device key no longer exists.'}
        try{
            if(-not $Value.existed){$k.DeleteValue([string]$Value.name,$false);return}
            $d=$Value.data
            switch([string]$Value.kind){
                'Binary'{$d=[Convert]::FromBase64String([string]$d)}
                'None'{$d=[Convert]::FromBase64String([string]$d)}
                'DWord'{$d=[int][long]$d}
                'QWord'{$d=[long]$d}
                'MultiString'{$d=[string[]]@($d)}
                default{$d=[string]$d}
            }
            $k.SetValue([string]$Value.name,$d,[Microsoft.Win32.RegistryValueKind]([string]$Value.kind))
        }finally{$k.Dispose()}
    }finally{$h.Dispose()}
}
function _NicAdvanced_OffloadSupported { param($State,[string]$Family) if($State.ContainsKey($Family+'Supported')){return [bool]$State[$Family+'Supported']};return ($null -ne $State[$Family] -and $State[$Family].Count -gt 0) }
function _NicAdvanced_OffloadRead {
    param([string]$Name,[string]$Family)
    try{
        $data=@(if($Family -eq 'lso'){Get-NetAdapterLso -Name $Name -ErrorAction Stop}else{Get-NetAdapterRsc -Name $Name -ErrorAction Stop})
    }catch{
        $class=if($Family -eq 'lso'){'MSFT_NetAdapterLsoSettingData'}else{'MSFT_NetAdapterRscSettingData'}
        if($_.FullyQualifiedErrorId -match '^CmdletizationQuery_NotFound_Name,' -or ($_.Exception.Message -match ('No '+$class+' objects found'))){return @{supported=$false;flags=$null}}
        throw
    }
    if($data.Count -eq 0){return @{supported=$false;flags=$null}}
    if($data.Count -ne 1){throw 'Offload query returned an ambiguous adapter.'}
    $fields=if($Family -eq 'lso'){@('V1IPv4Enabled','IPv4Enabled','IPv6Enabled')}else{@('IPv4Enabled','IPv6Enabled')}
    $flags=@{};foreach($field in $fields){if(-not $data[0].PSObject.Properties[$field] -or $null -eq $data[0].$field){throw 'Offload flags could not be read exactly.'};$flags[$field]=[bool]$data[0].$field}
    return @{supported=$true;flags=$flags}
}
function _NicAdvanced_Read {
    param($Adapter,$Params)
    $mode=[string]$Params.Mode;$name=[WildcardPattern]::Escape($Adapter.name)
    switch($mode){
        {$_ -in @('TcpPrimary','TcpAll')} {
            $path='SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces\{'+$Adapter.guid+'}'
            $values=@();foreach($n in @('TcpAckFrequency','TCPNoDelay','TcpDelAckTicks')){$values+=,(_NicAdvanced_RegRead $path $n)}
            return @{values=$values}
        }
        'DriverPower' {return @{values=@((_NicAdvanced_RegRead (_NicAdvanced_ClassPath $Adapter) 'PnPCapabilities'))}}
        'Advanced' {
            $all=if(@(_NicAdvanced_Field $Params 'Properties' @()).Count){@(Get-NetAdapterAdvancedProperty -Name $name -AllProperties -ErrorAction Stop)}else{@(Get-NetAdapterAdvancedProperty -Name $name -ErrorAction Stop)}
            $requested=@(_NicAdvanced_Field $Params 'Properties' @())
            if($requested.Count){$selected=@($all | Where-Object {$requested -contains [string]$_.RegistryKeyword})}
            else{$pattern=[string](_NicAdvanced_Field $Params 'DisplayMatch' '');if(-not $pattern){throw 'No advanced-property selector.'};$selected=@($all | Where-Object {$_.DisplayName -match $pattern} | Select-Object -First 1)}
            $out=@();$path=_NicAdvanced_ClassPath $Adapter
            foreach($p in $selected){
                if(-not $p.RegistryKeyword){throw 'A selected property has no stable keyword.'}
                $out+=,@{keyword=[string]$p.RegistryKeyword;displayName=[string]$p.DisplayName;raw=@([string[]]$p.RegistryValue);backing=(_NicAdvanced_RegRead $path ([string]$p.RegistryKeyword))}
            };return @{properties=$out}
        }
        'Offload' {
            $l=_NicAdvanced_OffloadRead $name 'lso';$r=_NicAdvanced_OffloadRead $name 'rsc'
            $backing=@()
            if($l.supported -or $r.supported){
                $path=_NicAdvanced_ClassPath $Adapter;$keywords=@()
                if($l.supported){$keywords+=@('*LsoV1IPv4','*LsoV2IPv4','*LsoV2IPv6')}
                if($r.supported){$keywords+=@('*RscIPv4','*RscIPv6')}
                foreach($keyword in $keywords){$backing+=,(_NicAdvanced_RegRead $path $keyword)}
            }
            return @{lsoSupported=[bool]$l.supported;rscSupported=[bool]$r.supported;lso=$l.flags;rsc=$r.flags;backingValues=$backing}
        }
        'Binding' {
            $b=@(Get-NetAdapterBinding -Name $name -ComponentID ms_tcpip6 -ErrorAction Stop)
            if($b.Count -ne 1){throw 'The IPv6 binding could not be read exactly.'};return @{enabled=[bool]$b[0].Enabled}
        }
        'Power' {
            $p=Get-NetAdapterPowerManagement -Name $name -ErrorAction Stop;$saved=@{}
            $fields=@(_NicAdvanced_Field $Params 'PowerFields' @('ArpOffload','NSOffload'))
            $keywords=@{ArpOffload='*PMARPOffload';NSOffload='*PMNSOffload'};$backing=@();$path=_NicAdvanced_ClassPath $Adapter
            foreach($f in $fields){if(-not $keywords.ContainsKey([string]$f)){throw 'The raw power-setting mapping is not supported for exact recovery.'};$backing+=,(_NicAdvanced_RegRead $path $keywords[[string]$f]);if(-not $p.PSObject.Properties[[string]$f]){throw "Power setting is unavailable: $f"};$saved[[string]$f]=[string]$p.$f}
            return @{power=$saved;backingValues=$backing}
        }
        default {throw 'Unknown adapter capture mode.'}
    }
}
function _NicAdvanced_Write {
    param($Adapter,$Params,$State)
    $mode=[string]$Params.Mode;$name=[WildcardPattern]::Escape($Adapter.name)
    switch($mode){
        {$_ -in @('TcpPrimary','TcpAll')} {
            $path='SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces\{'+$Adapter.guid+'}'
            foreach($v in @($State.values)){if($v.keyExisted){_NicAdvanced_RegWrite $path $v}}
        }
        'DriverPower' {foreach($v in @($State.values)){_NicAdvanced_RegWrite (_NicAdvanced_ClassPath $Adapter) $v}}
        'Advanced' {
            $path=_NicAdvanced_ClassPath $Adapter
            $current=_NicAdvanced_Read $Adapter $Params
            foreach($p in @($State.properties)){
                if(@($current.properties | Where-Object {$_.keyword -eq $p.keyword}).Count -ne 1){throw 'The recorded keyword is not the selected live driver property.'}
                Set-NetAdapterAdvancedProperty -Name $name -RegistryKeyword ([WildcardPattern]::Escape([string]$p.keyword)) -RegistryValue ([string[]]@($p.raw)) -ErrorAction Stop
                _NicAdvanced_RegWrite $path $p.backing
            }
        }
        'Offload' {
            if(_NicAdvanced_OffloadSupported $State 'lso'){$l=@{};foreach($k in $State.lso.Keys){$l[$k]=[bool]$State.lso[$k]};Set-NetAdapterLso -Name $name @l -ErrorAction Stop}
            if(_NicAdvanced_OffloadSupported $State 'rsc'){$r=@{};foreach($k in $State.rsc.Keys){$r[$k]=[bool]$State.rsc[$k]};Set-NetAdapterRsc -Name $name @r -ErrorAction Stop}
            if(@($State.backingValues).Count){$path=_NicAdvanced_ClassPath $Adapter;foreach($v in @($State.backingValues)){_NicAdvanced_RegWrite $path $v}}
        }
        'Binding' {if($State.enabled){Enable-NetAdapterBinding -Name $name -ComponentID ms_tcpip6 -ErrorAction Stop}else{Disable-NetAdapterBinding -Name $name -ComponentID ms_tcpip6 -ErrorAction Stop}}
        'Power' {$p=@{};foreach($k in @($State.power.Keys)){if($State.power[$k] -ne 'Unsupported'){$p[$k]=[string]$State.power[$k]}};if($p.Count){Set-NetAdapterPowerManagement -Name $name @p -ErrorAction Stop};$path=_NicAdvanced_ClassPath $Adapter;foreach($v in @($State.backingValues)){_NicAdvanced_RegWrite $path $v}}
        default {throw 'Unknown adapter restore mode.'}
    }
}
function _NicAdvanced_TeredoPolicy {
    $h=[Microsoft.Win32.Registry]::LocalMachine.OpenSubKey('SOFTWARE\Policies\Microsoft\Windows\TCPIP\v6Transition',$false)
    try{return ($null -ne $h -and (@($h.GetValueNames()).Count -gt 0 -or @($h.GetSubKeyNames()).Count -gt 0))}finally{if($h){$h.Dispose()}}
}
function _NicAdvanced_TeredoConfig {
    param([string]$Store)
    $p=Get-NetTeredoConfiguration -PolicyStore $Store -ErrorAction Stop
    $out=@{}
    foreach($f in @('Type','ServerName','RefreshIntervalSeconds','ClientPort','ServerVirtualIP','DefaultQualified','ServerShunt')){
        $source=if($f -eq 'RefreshIntervalSeconds'){'RefreshInterval'}else{$f}
        if(-not $p.PSObject.Properties[$source] -or $null -eq $p.$source){throw "Teredo field is unavailable: $source"}
        if($f -in @('DefaultQualified','ServerShunt')){$out[$f]=[bool]$p.$source}else{$out[$f]=[string]$p.$source}
    };return $out
}
function _NicAdvanced_TeredoRegistry {
    $path='SYSTEM\CurrentControlSet\Services\iphlpsvc\Teredo'
    $h=[Microsoft.Win32.Registry]::LocalMachine.OpenSubKey($path,$false)
    try{
        $values=@();if($h){foreach($n in @($h.GetValueNames() | Sort-Object)){$values+=,(_NicAdvanced_RegRead $path $n)}}
        return @{existed=($null -ne $h);values=$values}
    }finally{if($h){$h.Dispose()}}
}
function _NicAdvanced_TeredoRead {
    if(_NicAdvanced_TeredoPolicy){throw 'Teredo is controlled by your organisation; no change was made.'}
    return @{persistent=(_NicAdvanced_TeredoConfig 'PersistentStore');active=(_NicAdvanced_TeredoConfig 'ActiveStore');registry=(_NicAdvanced_TeredoRegistry)}
}
function _NicAdvanced_TeredoRegistryWrite {
    param($Original)
    $path='SYSTEM\CurrentControlSet\Services\iphlpsvc\Teredo'
    $h=[Microsoft.Win32.Registry]::LocalMachine.OpenSubKey($path,$true)
    if(-not $h -and $Original.existed){$h=[Microsoft.Win32.Registry]::LocalMachine.CreateSubKey($path)}
    try{
        if($h){foreach($name in @($h.GetValueNames())){if(@($Original.values.name) -notcontains $name){$h.DeleteValue($name,$false)}}}
    }finally{if($h){$h.Dispose()}}
    foreach($value in @($Original.values)){_NicAdvanced_RegWrite $path $value}
    if(-not $Original.existed){
        $h=[Microsoft.Win32.Registry]::LocalMachine.OpenSubKey($path,$false)
        $empty=$false;try{if($h){$empty=(@($h.GetValueNames()).Count -eq 0 -and @($h.GetSubKeyNames()).Count -eq 0)}}finally{if($h){$h.Dispose()}}
        if($empty){[Microsoft.Win32.Registry]::LocalMachine.DeleteSubKey($path,$false)}
    }
}
function _NicAdvanced_TeredoSet { param([string]$Store,$Config) $p=@{};foreach($k in $Config.Keys){$p[$k]=$Config[$k]};Set-NetTeredoConfiguration -PolicyStore $Store @p -ErrorAction Stop | Out-Null }
function _NicAdvanced_TeredoWrite {
    param($State)
    if(_NicAdvanced_TeredoPolicy){throw 'Teredo is controlled by your organisation; it was left unchanged.'}
    _NicAdvanced_TeredoRegistryWrite $State.registry
    _NicAdvanced_TeredoSet 'PersistentStore' $State.persistent
    _NicAdvanced_TeredoSet 'ActiveStore' $State.active
    # The setters can materialize defaults. Replay original raw absence/type after reloading both stores.
    _NicAdvanced_TeredoRegistryWrite $State.registry
}
function _NicAdvanced_TeredoValidate {
    param($State)
    foreach($store in @('persistent','active')){
        $c=$State[$store];if($c -isnot [Collections.IDictionary] -or $c.Count -ne 7){throw 'Incomplete Teredo store.'}
        if($c.Type -notin @('Default','Disabled','Client','EnterpriseClient','Server','Automatic')){throw 'Unknown Teredo type.'}
        if([string]$c.ServerName -notmatch '^[A-Za-z0-9_.-]{1,253}$'){throw 'Invalid Teredo server name.'}
        if([string]$c.RefreshIntervalSeconds -notmatch '^\d{1,10}$' -or [long]$c.RefreshIntervalSeconds -gt [uint32]::MaxValue){throw 'Invalid Teredo refresh interval.'}
        if([string]$c.ClientPort -notmatch '^\d{1,5}$' -or [int]$c.ClientPort -gt 65535){throw 'Invalid Teredo port.'}
        $address=$null;if(-not [Net.IPAddress]::TryParse([string]$c.ServerVirtualIP,[ref]$address) -or $address.AddressFamily -ne [Net.Sockets.AddressFamily]::InterNetwork){throw 'Invalid Teredo virtual address.'}
        foreach($f in @('DefaultQualified','ServerShunt')){if($c[$f] -isnot [bool]){throw 'Invalid Teredo Boolean.'}}
        foreach($k in $c.Keys){if($k -notin @('Type','ServerName','RefreshIntervalSeconds','ClientPort','ServerVirtualIP','DefaultQualified','ServerShunt')){throw 'Unknown Teredo field.'}}
    }
    $r=$State.registry;if($r.existed -isnot [bool] -or @($r.values).Count -gt 64){throw 'Invalid Teredo registry original.'}
    if(-not $r.existed -and @($r.values).Count){throw 'Absent Teredo key has values.'}
    $seen=@{};foreach($v in @($r.values)){
        if([string]$v.name -notmatch '^[A-Za-z0-9_.-]{0,128}$' -or $seen.ContainsKey([string]$v.name) -or -not $v.existed -or -not $v.keyExisted){throw 'Invalid Teredo registry value.'}
        $seen[[string]$v.name]=$true;_NicAdvanced_ValidateValue $v @([string]$v.name)
    }
}
function Undo-NicAdvanced-Capture {
    param([hashtable]$Params=@{})
    $result=@{type='NicAdvanced';v=1;params=$Params;state=$null;ok=$false;error=$null;capturedAt=[datetime]::UtcNow.ToString('o')}
    try{
        if($Params.Mode -eq 'Teredo'){
            $result.state=@{teredo=(_NicAdvanced_TeredoRead);adapters=@()}
        }else{
            $out=@()
            foreach($a in @(_NicAdvanced_Select $Params)){
                $out+=,@{guid=$a.guid;pnp=$a.pnp;driver=$a.driver;capturedName=$a.name;settings=(_NicAdvanced_Read $a $Params)}
            };$result.state=@{adapters=$out}
        }
        $result.ok=$true;$valid=Undo-NicAdvanced-Validate $result;if(-not $valid.valid){throw $valid.reason}
    }catch{$result.ok=$false;$result.error="Could not record the original adapter settings: $($_.Exception.Message)"};return $result
}
function _NicAdvanced_ValidateValue {
    param($Value,$Names)
    if($Value.name -notin $Names -or $Value.existed -isnot [bool] -or $Value.keyExisted -isnot [bool]){throw 'Invalid driver value.'}
    if($Value.existed){
        if(-not $Value.keyExisted -or $Value.kind -notin @('String','ExpandString','MultiString','DWord','QWord','Binary','None')){throw 'Invalid driver value kind.'}
        switch($Value.kind){
            'DWord'{$n=[long]::Parse([string]$Value.data);if($n -lt [int]::MinValue -or $n -gt [int]::MaxValue){throw 'Invalid DWORD original.'}}
            'QWord'{$n=[long]::Parse([string]$Value.data)}
            {$_ -in @('String','ExpandString')}{if($Value.data -isnot [string]){throw 'Invalid registry string shape.'}}
            'MultiString'{if($Value.data -isnot [array] -or @($Value.data | Where-Object {$_ -isnot [string]}).Count){throw 'Invalid registry multi-string shape.'}}
            {$_ -in @('Binary','None')}{$d=[Convert]::FromBase64String([string]$Value.data);if($d.Length -gt 1048576){throw 'Driver value too large.'}}
        }
    }elseif($Value.kind -or $null -ne $Value.data){throw 'An absent value has data.'}
}
function _NicAdvanced_ValidateParams {
    param($Params)
    $mode=[string]$Params.Mode
    $allowed=@('Mode','InterfaceGuids','UpOnly','ExcludeDescription')
    switch($mode){
        'Advanced'{$allowed+=@('Properties','DisplayMatch')}
        'Power'{$allowed+='PowerFields'}
        'Teredo'{$allowed=@('Mode')}
    }
    foreach($key in $Params.Keys){if(-not ([string]$key).StartsWith('_') -and $key -notin $allowed){throw 'Unexpected adapter parameter.'}}
    if($mode -eq 'Advanced'){
        $props=@(_NicAdvanced_Field $Params 'Properties' @())
        $pattern=[string](_NicAdvanced_Field $Params 'DisplayMatch' '')
        if($props.Count -gt 128 -or ($props.Count -and $pattern)){throw 'Ambiguous advanced-property selector.'}
        foreach($keyword in $props){if([string]$keyword -notmatch '^[A-Za-z0-9_*.-]{1,128}$'){throw 'Invalid advanced-property selector.'}}
        if(-not $props.Count -and $pattern -notin @('Interrupt Moderation','Energy.?Efficient.?Ethernet|Green Ethernet|EEE','^Roaming Aggressiveness$','^Roaming Sensitivity$','^Preferred Band$','^802\.11n/ac Wireless Mode$')){throw 'Unknown advanced-property display selector.'}
    }
}
function Undo-NicAdvanced-Validate {
    param($Item)
    try{
        if($Item.type -ne 'NicAdvanced' -or [int]$Item.v -ne 1 -or $Item.ok -ne $true){throw 'Invalid adapter envelope.'}
        _NicAdvanced_ValidateParams $Item.params
        $mode=[string]$Item.params.Mode
        if($mode -notin @('TcpPrimary','TcpAll','DriverPower','Advanced','Offload','Binding','Power','Teredo')){throw 'Invalid adapter mode.'}
        if($mode -eq 'Teredo'){
            _NicAdvanced_TeredoValidate $Item.state.teredo
            return @{valid=$true;reason=''}
        }
        $planned=@(_NicAdvanced_Field $Item.params 'InterfaceGuids' @())
        if($planned.Count -and @($Item.state.adapters).Count -ne @($planned | Select-Object -Unique).Count){throw 'A planned adapter original is missing.'}
        if($mode -eq 'TcpPrimary' -and @($Item.state.adapters).Count -ne 1){throw 'The primary adapter original is missing.'}
        $seen=@{}
        foreach($a in @($Item.state.adapters)){
            $guid=[guid]::Parse([string]$a.guid)
            if($seen.ContainsKey([string]$a.guid) -or -not $a.pnp -or [string]$a.pnp -match '[\x00-\x1F]' -or ([string]$a.pnp).Length -gt 2048){throw 'Invalid or duplicate device identity.'};$seen[[string]$a.guid]=$true
            $ids=@(_NicAdvanced_Field $Item.params 'InterfaceGuids' @())
            if($ids.Count -and $ids -notcontains $a.guid -and $ids -notcontains ('{'+$a.guid+'}')){throw 'Device is outside the plan.'}
            $s=$a.settings
            switch($mode){
                {$_ -in @('TcpPrimary','TcpAll')} {
                    if(@($s.values).Count -ne 3){throw 'Missing TCP values.'}
                    $names=@();foreach($v in @($s.values)){_NicAdvanced_ValidateValue $v @('TcpAckFrequency','TCPNoDelay','TcpDelAckTicks');$names+=,$v.name}
                    if(@($names | Select-Object -Unique).Count -ne 3){throw 'Duplicate TCP values.'}
                }
                'DriverPower' {if(@($s.values).Count -ne 1){throw 'Missing device power value.'};_NicAdvanced_ValidateValue $s.values[0] @('PnPCapabilities')}
                'Advanced' {
                    foreach($p in @($s.properties)){
                        if([string]$p.keyword -notmatch '^[A-Za-z0-9_*.-]{1,128}$' -or @($p.raw).Count -gt 128){throw 'Invalid advanced keyword or value.'}
                        $requested=@(_NicAdvanced_Field $Item.params 'Properties' @())
                        if($requested.Count -and $requested -notcontains $p.keyword){throw 'Advanced keyword is outside the plan.'}
                        _NicAdvanced_ValidateValue $p.backing @([string]$p.keyword)
                    }
                }
                'Offload' {
                    $allowed=@()
                    foreach($family in @('lso','rsc')){
                        if($s.ContainsKey($family+'Supported') -and $s[$family+'Supported'] -isnot [bool]){throw 'Invalid offload capability flag.'}
                        $supported=_NicAdvanced_OffloadSupported $s $family
                        $fields=if($family -eq 'lso'){@('V1IPv4Enabled','IPv4Enabled','IPv6Enabled')}else{@('IPv4Enabled','IPv6Enabled')}
                        if($supported){
                            if($s[$family].Count -ne $fields.Count){throw 'Missing offload originals.'}
                            foreach($k in $s[$family].Keys){if($k -notin $fields -or $s[$family][$k] -isnot [bool]){throw 'Invalid offload field.'}}
                            if($family -eq 'lso'){$allowed+=@('*LsoV1IPv4','*LsoV2IPv4','*LsoV2IPv6')}else{$allowed+=@('*RscIPv4','*RscIPv6')}
                        }elseif($null -ne $s[$family]){throw 'Unsupported feature has flags.'}
                    }
                    if(@($s.backingValues).Count -ne $allowed.Count){throw 'Missing original offload overrides.'}
                    $names=@();foreach($v in @($s.backingValues)){_NicAdvanced_ValidateValue $v $allowed;$names+=,$v.name}
                    if(@($names | Select-Object -Unique).Count -ne $allowed.Count){throw 'Duplicate offload override.'}
                }
                'Binding' {if($s.enabled -isnot [bool]){throw 'Invalid binding state.'}}
                'Power' {
                    foreach($k in @($s.power.Keys)){
                        if($k -notin @('ArpOffload','NSOffload') -or $s.power[$k] -notin @('Enabled','Disabled','Unsupported')){throw 'Invalid power state.'}
                    }
                    if(-not $s.power.Count){throw 'Missing power originals.'}
                    $map=@{ArpOffload='*PMARPOffload';NSOffload='*PMNSOffload'}
                    $allowed=@($s.power.Keys | ForEach-Object {$map[$_]})
                    if(@($s.backingValues).Count -ne $allowed.Count){throw 'Missing raw power originals.'}
                    $unique=@();foreach($v in @($s.backingValues)){_NicAdvanced_ValidateValue $v $allowed;$unique+=,$v.name}
                    if(@($unique | Select-Object -Unique).Count -ne $allowed.Count){throw 'Duplicate raw power originals.'}
                }
            }
        }
        return @{valid=$true;reason=''}
    }catch{return @{valid=$false;reason=$_.Exception.Message}}
}
function _NicAdvanced_Resolve {
    param($Original)
    $matches=@(_NicAdvanced_Adapters -IncludeHidden | Where-Object {$_.guid -eq $Original.guid})
    if($matches.Count -ne 1){throw 'The recorded adapter is missing or ambiguous; its original is kept.'}
    $a=$matches[0]
    if($a.pnp -ne $Original.pnp -or $a.driver -ne $Original.driver){throw 'The adapter hardware or driver changed; it was left untouched.'}
    return $a
}
function _NicAdvanced_SettingsJson {
    param($Settings,[string]$Mode)
    if($Mode -eq 'Offload'){
        return (_NicAdvanced_Json @{lsoSupported=(_NicAdvanced_OffloadSupported $Settings 'lso');rscSupported=(_NicAdvanced_OffloadSupported $Settings 'rsc');lso=$Settings.lso;rsc=$Settings.rsc;backingValues=@($Settings.backingValues)})
    }
    if($Mode -eq 'Advanced'){
        $props=@();foreach($p in @($Settings.properties)){$props+=,@{keyword=$p.keyword;raw=@($p.raw);backing=$p.backing}}
        return (_NicAdvanced_Json @{properties=$props})
    }
    return (_NicAdvanced_Json $Settings)
}
function Undo-NicAdvanced-Verify {
    param($Item)
    try{
        $v=Undo-NicAdvanced-Validate $Item;if(-not $v.valid){throw $v.reason};$diff=@()
        if($Item.params.Mode -eq 'Teredo'){if((_NicAdvanced_Json (_NicAdvanced_TeredoRead)) -cne (_NicAdvanced_Json $Item.state.teredo)){$diff+=,'Teredo configuration differs.'}}
        else{foreach($old in @($Item.state.adapters)){
            try{$a=_NicAdvanced_Resolve $old;$now=_NicAdvanced_Read $a $Item.params;if((_NicAdvanced_SettingsJson $now ([string]$Item.params.Mode)) -cne (_NicAdvanced_SettingsJson $old.settings ([string]$Item.params.Mode))){$diff+=,("Adapter settings differ: "+$old.guid)}}catch{$diff+=,$_.Exception.Message}
        }}
        return @{matches=($diff.Count -eq 0);diff=($diff -join '; ')}
    }catch{return @{matches=$false;diff=$_.Exception.Message}}
}
function Undo-NicAdvanced-Restore {
    param($Item)
    $details=@()
    try{
        $v=Undo-NicAdvanced-Validate $Item;if(-not $v.valid){throw $v.reason}
        if($Item.params.Mode -eq 'Teredo'){_NicAdvanced_TeredoWrite $Item.state.teredo;$details+=,@{target='Teredo';ok=$true}}
        else{
            foreach($old in @($Item.state.adapters)){
                try{$a=_NicAdvanced_Resolve $old;_NicAdvanced_Write $a $Item.params $old.settings;$details+=,@{target=$old.guid;ok=$true;message='Saved configuration restored; a link reconnect may occur.'}}
                catch{$details+=,@{target=$old.guid;ok=$false;message=$_.Exception.Message}}
            }
        }
        $check=Undo-NicAdvanced-Verify $Item;$ok=$check.matches -and @($details | Where-Object {-not $_.ok}).Count -eq 0
        return @{ok=$ok;partial=(@($details | Where-Object {$_.ok}).Count -gt 0 -and -not $ok);message=$(if($ok){'Saved adapter settings restored.'}else{$check.diff});details=$details}
    }catch{return @{ok=$false;partial=$false;message=$_.Exception.Message;details=$details}}
}
function Undo-NicAdvanced-Describe { param($Item) try{return "Network adapter originals: $(@($Item.state.adapters).Count) device(s), $($Item.params.Mode)."}catch{return 'Saved network adapter settings.'} }
$script:UndoProviders['NicAdvanced']=@{Capture='Undo-NicAdvanced-Capture';Restore='Undo-NicAdvanced-Restore';Verify='Undo-NicAdvanced-Verify';Describe='Undo-NicAdvanced-Describe';Validate='Undo-NicAdvanced-Validate';VerifySeesApply = $false; Version=1}

# ---- providers\PageFile.ps1 ----
# PageFile provider (group D). Params: none needed (system wide).
# State: AutomaticManagedPagefile, ALL Win32_PageFileSetting rows (name, initial, maximum) and the raw PagingFiles registry value
# (REG_MULTI_SZ) of Session Manager\Memory Management. Restore: automatic on -> set it back on; automatic off -> turn it off,
# recreate every captured setting, and when there were no settings write the captured PagingFiles value back. Takes effect after
# a restart (the message says so). Test hooks: the _PageFile_* low level functions and $script:SRUndoPageRegKey.

if (-not $script:UndoProviders) { $script:UndoProviders = @{} }
$script:UndoProviders['PageFile'] = @{ Capture = 'Undo-PageFile-Capture'; Restore = 'Undo-PageFile-Restore'; Verify = 'Undo-PageFile-Verify'; Describe = 'Undo-PageFile-Describe'; Validate = 'Undo-PageFile-Validate'; VerifySeesApply = $true; Version = 1 }

function _PageFile_RegKey { if ($script:SRUndoPageRegKey) { return $script:SRUndoPageRegKey }; return 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management' }
function _PageFile_GetAuto { return [bool](Get-CimInstance Win32_ComputerSystem -ErrorAction Stop).AutomaticManagedPagefile }
function _PageFile_GetSettings {
    $out = @()
    foreach ($s in @(Get-CimInstance Win32_PageFileSetting -ErrorAction Stop)) { $out += , @{ name = [string]$s.Name; initial = [int]$s.InitialSize; maximum = [int]$s.MaximumSize } }
    return $out
}
function _PageFile_SetAuto { param([bool]$On) Get-CimInstance Win32_ComputerSystem -ErrorAction Stop | Set-CimInstance -Property @{ AutomaticManagedPagefile = $On } -ErrorAction Stop }
function _PageFile_SetSetting {
    param([string]$Name, [int]$Initial, [int]$Maximum)
    $e = @(Get-CimInstance Win32_PageFileSetting -ErrorAction Stop | Where-Object { $_.Name -eq $Name })
    if ($e.Count -gt 0) { $e[0] | Set-CimInstance -Property @{ InitialSize = $Initial; MaximumSize = $Maximum } -ErrorAction Stop }
    else { New-CimInstance -ClassName Win32_PageFileSetting -Property @{ Name = $Name; InitialSize = $Initial; MaximumSize = $Maximum } -ErrorAction Stop | Out-Null }
}
function _PageFile_RemoveSetting { param([string]$Name) Get-CimInstance Win32_PageFileSetting -ErrorAction Stop | Where-Object { $_.Name -eq $Name } | Remove-CimInstance -ErrorAction Stop }
function _PageFile_GetRaw {
    $k = _PageFile_RegKey
    $key = Get-Item -LiteralPath $k -ErrorAction Stop
    if (@($key.GetValueNames()) -notcontains 'PagingFiles') { return @{ existed = $false; data = @() } }
    return @{ existed = $true; data = @([string[]]$key.GetValue('PagingFiles')) }
}
function _PageFile_SetRaw {
    param($Raw)
    $k = _PageFile_RegKey
    if ($Raw.existed) { Set-ItemProperty -LiteralPath $k -Name PagingFiles -Value ([string[]]@($Raw.data)) -Type MultiString -ErrorAction Stop }
    else { if (@((Get-Item -LiteralPath $k).GetValueNames()) -contains 'PagingFiles') { Remove-ItemProperty -LiteralPath $k -Name PagingFiles -ErrorAction Stop } }
}
function _PageFile_DriveCheck {
    # $null when the drive of a paging file exists and has room for its initial size, otherwise the reason (checked BEFORE any write)
    param([string]$Name, [int]$InitialMb)
    try {
        $letter = $Name.Substring(0, 2)
        $di = New-Object System.IO.DriveInfo($letter)
        if (-not $di.IsReady) { return "drive $letter is not ready" }
        if ($di.DriveType -ne [System.IO.DriveType]::Fixed) { return "drive $letter is not a fixed drive" }
        if ($InitialMb -gt 0 -and ($di.AvailableFreeSpace / 1MB) -lt $InitialMb) { return "drive $letter has less than $InitialMb MB free" }
        return $null
    } catch { return "drive of $Name could not be checked ($($_.Exception.Message))" }
}
function Undo-PageFile-Capture {
    param([hashtable]$Params)
    $out = @{ type = 'PageFile'; v = 1; params = $Params; state = $null; ok = $false; error = $null; capturedAt = (Undo-Now) }
    try {
        $raw = _PageFile_GetRaw
        $out.state = @{ automatic = (_PageFile_GetAuto); settings = @(_PageFile_GetSettings); raw = @{ existed = $raw.existed; data = @($raw.data) } }
        $out.ok = $true
    } catch { $out.error = "could not read the paging file settings: $($_.Exception.Message)" }
    return $out
}
function Undo-PageFile-Restore {
    param($Item)
    try {
        $st = ConvertTo-UndoPlain $Item['state']
        $notes = @()
        $want = @($st['settings'])
        if (-not $st['automatic']) {
            foreach ($s in $want) { $why = _PageFile_DriveCheck ([string]$s['name']) ([int]$s['initial']); if ($why) { return @{ ok = $false; partial = $false; message = "paging file not put back, nothing was changed: $why"; details = @() } } }
        }
        if ($st['automatic']) {
            _PageFile_SetAuto $true
            try { _PageFile_SetRaw @{ existed = [bool]$st['raw']['existed']; data = @($st['raw']['data']) } } catch { $notes += "the raw paging file value could not be put back: $($_.Exception.Message)" }
        } else {
            _PageFile_SetAuto $false
            foreach ($s in $want) { _PageFile_SetSetting ([string]$s['name']) ([int]$s['initial']) ([int]$s['maximum']) }
            # settings that exist now but were not there before
            foreach ($c in @(_PageFile_GetSettings)) {
                if (@($want | Where-Object { $_['name'] -eq $c.name }).Count -eq 0) { try { _PageFile_RemoveSetting $c.name } catch { $notes += "could not remove $($c.name): $($_.Exception.Message)" } }
            }
            if ($want.Count -eq 0) { _PageFile_SetRaw @{ existed = [bool]$st['raw']['existed']; data = @($st['raw']['data']) } }
        }
        $msg = 'the paging file settings were put back; restart Windows to finish'
        if ($notes.Count -gt 0) { $msg += '; ' + ($notes -join '; ') }
        return @{ ok = ($notes.Count -eq 0); partial = ($notes.Count -gt 0); message = $msg; details = $notes }
    } catch { return @{ ok = $false; partial = $false; message = "paging file: $($_.Exception.Message)"; details = @() } }
}
function Undo-PageFile-Verify {
    param($Item)
    try {
        $st = ConvertTo-UndoPlain $Item['state']
        $diffs = @()
        if ([bool]$st['automatic'] -ne (_PageFile_GetAuto)) { $diffs += "automatic management is $(if ($st['automatic']) { 'off' } else { 'on' }), was $(if ($st['automatic']) { 'on' } else { 'off' })" }
        if (-not $st['automatic']) {
            $cur = @(_PageFile_GetSettings | Sort-Object { $_.name } | ForEach-Object { "$($_.name):$($_.initial):$($_.maximum)" })
            $was = @(@($st['settings']) | Sort-Object { $_['name'] } | ForEach-Object { "$($_['name']):$($_['initial']):$($_['maximum'])" })
            if (($cur -join '|') -ne ($was -join '|')) { $diffs += "paging files are '$($cur -join ', ')', were '$($was -join ', ')'" }
        }
        if ($diffs.Count -gt 0) { return @{ matches = $false; diff = ($diffs -join '; ') } }
        return @{ matches = $true; diff = '' }
    } catch { return @{ matches = $false; diff = "could not read the paging file settings: $($_.Exception.Message)" } }
}
function Undo-PageFile-Describe {
    param($Item)
    try {
        $st = $Item['state']
        if ($st['automatic']) { return 'Paging file: managed by Windows' }
        $s = @($st['settings'])
        if ($s.Count -eq 0) { return 'Paging file: none set (paging off)' }
        return 'Paging file: ' + ((@($s) | ForEach-Object { "$($_['name']) $($_['initial'])-$($_['maximum']) MB" }) -join '; ')
    } catch { return 'Paging file' }
}
function Undo-PageFile-Validate {
    param($Item)
    try {
        $st = $Item['state']
        foreach ($s in @($st['settings'])) {
            if ([string]$s['name'] -notmatch '^[A-Za-z]:\\[A-Za-z0-9_. \\-]{1,100}$') { return @{ valid = $false; reason = 'paging file path not allowed' } }
            if ([int]$s['initial'] -lt 0 -or [int]$s['maximum'] -lt 0 -or [int]$s['maximum'] -gt 4194304) { return @{ valid = $false; reason = 'paging file size out of range' } }
        }
        foreach ($l in @($st['raw']['data'])) { if ([string]$l -match '[\x00-\x1f]') { return @{ valid = $false; reason = 'raw value not allowed' } } }
        return @{ valid = $true; reason = $null }
    } catch { return @{ valid = $false; reason = $_.Exception.Message } }
}

# ---- providers\PowerScheme.ps1 ----
# StreamReady undo engine - provider: PowerScheme (active power plan, plans created by a tweak, per-plan power setting values)
# Plain function definitions plus one registration. Dot-source safe. ASCII only. Uses powrprof.dll (language independent,
# no text parsing of powercfg output).
#
# Params (hashtable), two scopes:
#   @{ Scope='Active'; DeleteDuplicatesOf='<guid>' }
#        Captures the active plan and the list of plans (guid + name). Restore switches back to the captured plan and, if
#        DeleteDuplicatesOf is given (for example the Ultimate Performance source plan e9a42b02-...), deletes ONLY the plans
#        whose ids were recorded as created by the tweak (state.created, filled by Undo-PowerScheme-AfterApply right after
#        Apply). A plan that has the same name but was not recorded is never deleted. Without a recorded list nothing is deleted.
#   @{ Scope='Setting'; Subgroup='<guid>'; Setting='<guid>'; Fields=@('AC','DC'); Scheme='Active' or '<guid>' }
#        Captures the stored AC/DC values of one power setting in one plan, and whether each value was explicitly stored
#        (registry ACSettingIndex/DCSettingIndex) or only inherited from the default. Restore writes the original
#        effective value back through the power API. LIMIT (verified on this PC): the plan registry keys are owned by
#        SYSTEM and Administrators have read-only access, so a value that was only inherited from the plan default cannot
#        be un-stored again; after restore it is stored in the plan with the same value as the default. This is reported
#        in the details and the spec lists it as a known irreversible detail.
#
# A test can replace the real backend by setting $script:UndoPowerSchemeBackend to a hashtable of scriptblocks (see
# _Pwr_Backend for the operation names). Nothing else in production sets that variable.

if ($null -eq $script:UndoProviders) { $script:UndoProviders = @{} }
$script:UndoProviders['PowerScheme'] = @{ Capture = 'Undo-PowerScheme-Capture'; Restore = 'Undo-PowerScheme-Restore'; Verify = 'Undo-PowerScheme-Verify'; Describe = 'Undo-PowerScheme-Describe'; Validate = 'Undo-PowerScheme-Validate'; AfterApply = 'Undo-PowerScheme-AfterApply'; VerifySeesApply = $true; Version = 1 }

function _Pwr_Now { return (Get-Date).ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ssZ') }

function _Pwr_IsGuid {
    param($G)
    return ([string]$G -match '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$')
}
function _Pwr_G {
    param($G)
    return ([guid][string]$G).ToString('D').ToLowerInvariant()
}

function _Pwr_EnsureApi {
    if ('SrUndoPwrApi' -as [type]) { return }
    $src = @'
using System;
using System.Runtime.InteropServices;
public static class SrUndoPwrApi {
    [DllImport("powrprof.dll")] public static extern uint PowerGetActiveScheme(IntPtr UserRootPowerKey, out IntPtr ActivePolicyGuid);
    [DllImport("powrprof.dll")] public static extern uint PowerSetActiveScheme(IntPtr UserRootPowerKey, ref Guid SchemeGuid);
    [DllImport("powrprof.dll")] public static extern uint PowerEnumerate(IntPtr RootPowerKey, IntPtr SchemeGuid, IntPtr SubGroupOfPowerSettingsGuid, uint AccessFlags, uint Index, byte[] Buffer, ref uint BufferSize);
    [DllImport("powrprof.dll")] public static extern uint PowerReadFriendlyName(IntPtr RootPowerKey, ref Guid SchemeGuid, IntPtr SubGroupOfPowerSettingsGuid, IntPtr PowerSettingGuid, byte[] Buffer, ref uint BufferSize);
    [DllImport("powrprof.dll")] public static extern uint PowerReadACValueIndex(IntPtr RootPowerKey, ref Guid SchemeGuid, ref Guid SubGroupOfPowerSettingsGuid, ref Guid PowerSettingGuid, out uint AcValueIndex);
    [DllImport("powrprof.dll")] public static extern uint PowerReadDCValueIndex(IntPtr RootPowerKey, ref Guid SchemeGuid, ref Guid SubGroupOfPowerSettingsGuid, ref Guid PowerSettingGuid, out uint DcValueIndex);
    [DllImport("powrprof.dll")] public static extern uint PowerWriteACValueIndex(IntPtr RootPowerKey, ref Guid SchemeGuid, ref Guid SubGroupOfPowerSettingsGuid, ref Guid PowerSettingGuid, uint AcValueIndex);
    [DllImport("powrprof.dll")] public static extern uint PowerWriteDCValueIndex(IntPtr RootPowerKey, ref Guid SchemeGuid, ref Guid SubGroupOfPowerSettingsGuid, ref Guid PowerSettingGuid, uint DcValueIndex);
    [DllImport("powrprof.dll")] public static extern uint PowerDeleteScheme(IntPtr RootPowerKey, ref Guid SchemeGuid);
    [DllImport("kernel32.dll")] public static extern IntPtr LocalFree(IntPtr hMem);
}
'@
    Add-Type -TypeDefinition $src -ErrorAction Stop
}

# ---- real backend ------------------------------------------------------------------------------------------------------
function _Pwr_RegBase { return 'HKLM:\SYSTEM\CurrentControlSet\Control\Power\User\PowerSchemes' }

function _Pwr_Real_GetActive {
    _Pwr_EnsureApi
    $p = [IntPtr]::Zero
    $rc = [SrUndoPwrApi]::PowerGetActiveScheme([IntPtr]::Zero, [ref]$p)
    if ($rc -ne 0) { throw "PowerGetActiveScheme failed (code $rc)" }
    try { return (([guid][System.Runtime.InteropServices.Marshal]::PtrToStructure($p, [type][guid])).ToString('D').ToLowerInvariant()) }
    finally { [void][SrUndoPwrApi]::LocalFree($p) }
}
function _Pwr_Real_SetActive {
    param([string]$Scheme)
    _Pwr_EnsureApi
    $g = [guid]$Scheme
    $rc = [SrUndoPwrApi]::PowerSetActiveScheme([IntPtr]::Zero, [ref]$g)
    if ($rc -ne 0) { throw "PowerSetActiveScheme failed (code $rc)" }
}
function _Pwr_Real_FriendlyName {
    param([string]$Scheme)
    _Pwr_EnsureApi
    $g = [guid]$Scheme
    $buf = New-Object byte[] 1024
    $sz = [uint32]1024
    $rc = [SrUndoPwrApi]::PowerReadFriendlyName([IntPtr]::Zero, [ref]$g, [IntPtr]::Zero, [IntPtr]::Zero, $buf, [ref]$sz)
    if ($rc -ne 0) { return $null }
    $n = [Math]::Max(0, [int]$sz - 2)
    return [System.Text.Encoding]::Unicode.GetString($buf, 0, $n)
}
function _Pwr_Real_List {
    _Pwr_EnsureApi
    $out = New-Object System.Collections.ArrayList
    for ($i = 0; $i -lt 256; $i++) {
        $buf = New-Object byte[] 16
        $sz = [uint32]16
        $rc = [SrUndoPwrApi]::PowerEnumerate([IntPtr]::Zero, [IntPtr]::Zero, [IntPtr]::Zero, [uint32]16, [uint32]$i, $buf, [ref]$sz)
        if ($rc -eq 259) { break }
        if ($rc -ne 0) { throw "PowerEnumerate failed (code $rc)" }
        $g = (New-Object guid (, $buf)).ToString('D').ToLowerInvariant()
        [void]$out.Add(@{ guid = $g; name = (_Pwr_Real_FriendlyName $g) })
    }
    return @($out.ToArray())
}
function _Pwr_Real_Read {
    param([string]$Scheme, [string]$Sub, [string]$Setting, [string]$Which)
    _Pwr_EnsureApi
    $s = [guid]$Scheme; $u = [guid]$Sub; $t = [guid]$Setting
    [uint32]$v = 0
    $rc = if ($Which -eq 'AC') { [SrUndoPwrApi]::PowerReadACValueIndex([IntPtr]::Zero, [ref]$s, [ref]$u, [ref]$t, [ref]$v) } else { [SrUndoPwrApi]::PowerReadDCValueIndex([IntPtr]::Zero, [ref]$s, [ref]$u, [ref]$t, [ref]$v) }
    if ($rc -ne 0) { throw "could not read the $Which value (code $rc)" }
    return [int64]$v
}
function _Pwr_Real_Write {
    param([string]$Scheme, [string]$Sub, [string]$Setting, [string]$Which, [int64]$Value)
    _Pwr_EnsureApi
    $s = [guid]$Scheme; $u = [guid]$Sub; $t = [guid]$Setting
    $rc = if ($Which -eq 'AC') { [SrUndoPwrApi]::PowerWriteACValueIndex([IntPtr]::Zero, [ref]$s, [ref]$u, [ref]$t, [uint32]$Value) } else { [SrUndoPwrApi]::PowerWriteDCValueIndex([IntPtr]::Zero, [ref]$s, [ref]$u, [ref]$t, [uint32]$Value) }
    if ($rc -ne 0) { throw "could not write the $Which value (code $rc)" }
}
function _Pwr_Real_IsExplicit {
    param([string]$Scheme, [string]$Sub, [string]$Setting, [string]$Which)
    $k = (_Pwr_RegBase) + '\' + $Scheme + '\' + $Sub + '\' + $Setting
    if (-not (Test-Path -LiteralPath $k)) { return $false }
    $item = Get-Item -LiteralPath $k -ErrorAction Stop
    return (@($item.GetValueNames()) -contains ($Which + 'SettingIndex'))
}
function _Pwr_Real_DeleteScheme {
    param([string]$Scheme)
    _Pwr_EnsureApi
    $g = [guid]$Scheme
    $rc = [SrUndoPwrApi]::PowerDeleteScheme([IntPtr]::Zero, [ref]$g)
    if ($rc -ne 0) { throw "PowerDeleteScheme failed (code $rc)" }
}

function _Pwr_Backend {
    if ($script:UndoPowerSchemeBackend) { return $script:UndoPowerSchemeBackend }
    return @{
        GetActive      = { _Pwr_Real_GetActive }
        SetActive      = { param($s) _Pwr_Real_SetActive $s }
        List           = { _Pwr_Real_List }
        Read           = { param($s, $u, $t, $w) _Pwr_Real_Read $s $u $t $w }
        Write          = { param($s, $u, $t, $w, $v) _Pwr_Real_Write $s $u $t $w $v }
        IsExplicit     = { param($s, $u, $t, $w) _Pwr_Real_IsExplicit $s $u $t $w }
        DeleteScheme   = { param($s) _Pwr_Real_DeleteScheme $s }
        FriendlyName   = { param($s) _Pwr_Real_FriendlyName $s }
    }
}

function _Pwr_Fields {
    param($Params)
    $f = @()
    foreach ($x in @($Params.Fields)) { if ([string]$x -in @('AC', 'DC')) { $f += [string]$x } }
    if ($f.Count -eq 0) { $f = @('AC', 'DC') }
    return @($f | Select-Object -Unique)
}

# ---- capture -----------------------------------------------------------------------------------------------------------
function _Pwr_ReadSettingState {
    param($B, [string]$Scheme, [string]$Sub, [string]$Setting, $Fields)
    $vals = @{}
    foreach ($w in $Fields) {
        $vals[$w] = @{ value = (& $B.Read $Scheme $Sub $Setting $w); explicit = [bool](& $B.IsExplicit $Scheme $Sub $Setting $w) }
    }
    return $vals
}

function Undo-PowerScheme-Capture {
    param($Params)
    $res = @{ type = 'PowerScheme'; v = 1; params = $Params; state = $null; ok = $false; error = $null; capturedAt = (_Pwr_Now) }
    try {
        if ($null -eq $Params) { throw 'no parameters' }
        $B = _Pwr_Backend
        $scope = [string]$Params.Scope
        # a creation id reported by an EARLIER Apply must never be taken for this one
        $script:UndoPowerCreatedGuid = $null
        if ($scope -eq 'Active') {
            if ($Params.DeleteDuplicatesOf -and -not (_Pwr_IsGuid $Params.DeleteDuplicatesOf)) { throw 'DeleteDuplicatesOf is not a GUID' }
            $schemes = @(& $B.List)
            $res.state = @{ scope = 'Active'; activeGuid = (& $B.GetActive); schemes = @($schemes | ForEach-Object { @{ guid = [string]$_.guid; name = [string]$_.name } }) }
        } elseif ($scope -eq 'Setting') {
            if (-not (_Pwr_IsGuid $Params.Subgroup) -or -not (_Pwr_IsGuid $Params.Setting)) { throw 'Subgroup and Setting must be GUIDs' }
            $active = (& $B.GetActive)
            $schemeParam = if ($Params.Scheme -and [string]$Params.Scheme -ne 'Active') { $Params.Scheme } else { $null }
            if ($schemeParam -and -not (_Pwr_IsGuid $schemeParam)) { throw 'Scheme must be Active or a GUID' }
            $scheme = if ($schemeParam) { _Pwr_G $schemeParam } else { $active }
            $sub = _Pwr_G $Params.Subgroup; $set = _Pwr_G $Params.Setting
            $fields = _Pwr_Fields $Params
            $res.state = @{ scope = 'Setting'; scheme = $scheme; schemeWasActive = ($scheme -eq $active); subgroup = $sub; setting = $set; fields = @($fields)
                            values = (_Pwr_ReadSettingState $B $scheme $sub $set $fields) }
        } else { throw "unknown scope '$scope'" }
        $res.ok = $true
    } catch { $res.error = "Could not record the original power plan state: $($_.Exception.Message)" }
    return $res
}

# Optional hook, called by the engine right AFTER Apply and before the record is marked applied: records the id of every plan
# that appeared since capture (the ones this tweak created) so Undo deletes exactly those and nothing else. Returns
# @{ ok; message }. The item is changed in place (state.created); the caller saves the record.
function Undo-PowerScheme-AfterApply {
    param($Item)
    try {
        $s = $Item.state
        if ([string]$s.scope -ne 'Active' -or -not $Item.params.DeleteDuplicatesOf) { return @{ ok = $true; message = 'nothing to record' } }
        # Only the FIRST call after the original was captured records plans. A second Apply that reuses the same record must not
        # pull plans the user made in between into the list (they would then be deleted by Undo).
        if ($null -ne $s.created) { return @{ ok = $true; message = 'the created plans were already recorded' } }
        $B = _Pwr_Backend
        $known = @($s.schemes | ForEach-Object { [string]$_.guid })
        # A new plan is owned by this tweak only with PROOF of creation: the id that the Apply code itself got back from the call that
        # made the copy ($script:UndoPowerCreatedGuid, set by the Apply right after it duplicated the plan; a plan the Apply merely
        # FOUND and reused never sets it). The plan must also be new since capture and still listed. "Active now" and "same name" are
        # NOT proof (a power program can make and activate a copy with the same name). Everything else that is new goes to
        # state.unattributed, is reported to the user and is never deleted. Without the id nothing is owned.
        $hint = [string]$script:UndoPowerCreatedGuid
        $script:UndoPowerCreatedGuid = $null
        $created = @(); $other = @()
        foreach ($x in @(& $B.List)) {
            $g = [string]$x.guid
            if ($known -contains $g) { continue }
            if ($hint -and $g -eq $hint) { $created += , @{ guid = $g; name = [string]$x.name } } else { $other += $g }
        }
        $s.created = @($created)
        $s.unattributed = @($other)
        return @{ ok = $true; message = "$($created.Count) created plan(s) recorded, $($other.Count) new plan(s) not attributed to this tweak" }
    } catch { return @{ ok = $false; message = "could not record the plans this tweak created: $($_.Exception.Message)" } }
}

function Undo-PowerScheme-Validate {
    param($Item)
    try {
        if ($null -eq $Item -or [string]$Item.type -ne 'PowerScheme') { return @{ valid = $false; reason = 'not a PowerScheme record' } }
        $s = $Item.state
        if ($null -eq $s) { return @{ valid = $false; reason = 'no state' } }
        if ([string]$s.scope -eq 'Active') {
            if (-not (_Pwr_IsGuid $s.activeGuid)) { return @{ valid = $false; reason = 'active plan id is not a GUID' } }
            foreach ($x in @($s.schemes)) { if (-not (_Pwr_IsGuid $x.guid)) { return @{ valid = $false; reason = 'a plan id is not a GUID' } } }
            if ($Item.params.DeleteDuplicatesOf -and -not (_Pwr_IsGuid $Item.params.DeleteDuplicatesOf)) { return @{ valid = $false; reason = 'DeleteDuplicatesOf is not a GUID' } }
            if ($null -ne $s.created) {
                if (-not $Item.params.DeleteDuplicatesOf) { return @{ valid = $false; reason = 'created plans are only allowed when the tweak copies a plan' } }
                $original = @($s.schemes | ForEach-Object { [string]$_.guid }) + [string]$s.activeGuid
                foreach ($c in @($s.created)) {
                    if (-not (_Pwr_IsGuid $c.guid)) { return @{ valid = $false; reason = 'a created plan id is not a GUID' } }
                    if ($original -contains [string]$c.guid) { return @{ valid = $false; reason = 'a created plan is one of the original plans' } }
                }
                if (@($s.created).Count -gt 4) { return @{ valid = $false; reason = 'too many created plans' } }
            }
            foreach ($u in @($s.unattributed | Where-Object { $null -ne $_ })) { if (-not (_Pwr_IsGuid $u)) { return @{ valid = $false; reason = 'an unattributed plan id is not a GUID' } } }
            if ($Item.params.Scope -and [string]$Item.params.Scope -ne 'Active') { return @{ valid = $false; reason = 'the record scope does not match the parameters' } }
            return @{ valid = $true; reason = $null }
        }
        if ([string]$s.scope -eq 'Setting') {
            if ([string]$Item.params.Scope -ne 'Setting') { return @{ valid = $false; reason = 'the record scope does not match the parameters' } }
            $wantF = (@(_Pwr_Fields $Item.params) | Sort-Object) -join ','; $haveF = (@($s.fields | ForEach-Object { [string]$_ }) | Sort-Object) -join ','
            if (-not $wantF -or $wantF -ne $haveF) { return @{ valid = $false; reason = 'the recorded fields do not match the parameters' } }
            foreach ($g in @($s.scheme, $s.subgroup, $s.setting)) { if (-not (_Pwr_IsGuid $g)) { return @{ valid = $false; reason = 'an id is not a GUID' } } }
            if ([string]$s.subgroup -ne (_Pwr_G $Item.params.Subgroup) -or [string]$s.setting -ne (_Pwr_G $Item.params.Setting)) { return @{ valid = $false; reason = 'setting ids do not match the parameters' } }
            if ($Item.params.Scheme -and [string]$Item.params.Scheme -ne 'Active') { if (-not (_Pwr_IsGuid $Item.params.Scheme) -or [string]$s.scheme -ne (_Pwr_G $Item.params.Scheme)) { return @{ valid = $false; reason = 'the plan id does not match the parameters' } } }
            foreach ($w in @($s.fields)) {
                if ([string]$w -notin @('AC', 'DC')) { return @{ valid = $false; reason = 'field must be AC or DC' } }
                $v = $s.values.$w
                if ($null -eq $v) { return @{ valid = $false; reason = "no value for $w" } }
                if ($v.explicit -isnot [bool]) { return @{ valid = $false; reason = 'explicit must be true or false' } }
                if ([string]$v.value -notmatch '^\d{1,10}$' -or [int64]$v.value -gt 4294967295) { return @{ valid = $false; reason = 'value out of range' } }
            }
            return @{ valid = $true; reason = $null }
        }
        return @{ valid = $false; reason = 'unknown scope' }
    } catch { return @{ valid = $false; reason = $_.Exception.Message } }
}

function Undo-PowerScheme-Describe {
    param($Item)
    try {
        $B = _Pwr_Backend
        $s = $Item.state
        if ([string]$s.scope -eq 'Active') {
            $n = $null; foreach ($x in @($s.schemes)) { if ([string]$x.guid -eq [string]$s.activeGuid) { $n = [string]$x.name } }
            if (-not $n) { $n = [string]$s.activeGuid }
            return "Active power plan: $n"
        }
        $parts = @()
        foreach ($w in @($s.fields)) { $v = $s.values.$w; $parts += "$w=$($v.value) ($(if ($v.explicit) { 'set in the plan' } else { 'plan default' }))" }
        return "Power plan setting $($s.setting) in plan $($s.scheme): $($parts -join ', ')"
    } catch { return 'Power plan setting (record could not be read)' }
}

function Undo-PowerScheme-Verify {
    param($Item)
    try {
        $B = _Pwr_Backend
        $s = $Item.state
        $diff = New-Object System.Collections.ArrayList
        $notes = New-Object System.Collections.ArrayList
        if ([string]$s.scope -eq 'Active') {
            $cur = & $B.GetActive
            if ($cur -ne [string]$s.activeGuid) { [void]$diff.Add("active plan is $cur, was $($s.activeGuid)") }
            if ($Item.params.DeleteDuplicatesOf) {
                if ($null -eq $s.created) { [void]$diff.Add('it was not recorded which power plan this tweak created, so a copy may remain') }
                else {
                    $existing = @(& $B.List | ForEach-Object { [string]$_.guid })
                    foreach ($c in @($s.created)) { if ($existing -contains [string]$c.guid) { [void]$diff.Add("a plan created by the tweak still exists: $($c.guid)") } }
                    foreach ($u in @($s.unattributed)) { if ($existing -contains [string]$u) { [void]$diff.Add("a new power plan appeared while the tweak ran ($u); StreamReady cannot prove it made it, so it is left alone") } }
                }
            }
        } else {
            $list = @(& $B.List | ForEach-Object { [string]$_.guid })
            if ($list -notcontains [string]$s.scheme) { return @{ matches = $false; diff = 'the power plan no longer exists' } }
            foreach ($w in @($s.fields)) {
                $o = $s.values.$w
                $exp = [bool](& $B.IsExplicit $s.scheme $s.subgroup $s.setting $w)
                $now = & $B.Read $s.scheme $s.subgroup $s.setting $w
                if ([int64]$now -ne [int64]$o.value) { [void]$diff.Add("$w is $now, was $($o.value)") }
                elseif ($exp -and -not [bool]$o.explicit) { [void]$notes.Add("$w has the same value as before, but Windows now stores it in the plan (this cannot be removed)") }
            }
        }
        $txt = ($diff.ToArray() -join '; ')
        if ($diff.Count -eq 0 -and $notes.Count -gt 0) { $txt = 'note: ' + ($notes.ToArray() -join '; ') }
        return @{ matches = ($diff.Count -eq 0); diff = $txt }
    } catch { return @{ matches = $false; diff = "could not read the power plan state: $($_.Exception.Message)" } }
}

function Undo-PowerScheme-Restore {
    param($Item)
    $details = New-Object System.Collections.ArrayList
    $add = { param($part, $ok, $msg) [void]$details.Add(@{ part = $part; ok = $ok; message = $msg }) }
    try {
        $val = Undo-PowerScheme-Validate $Item
        if (-not $val.valid) { return @{ ok = $false; partial = $false; message = "Refused: the saved power plan record is not valid ($($val.reason))."; details = @() } }
        $B = _Pwr_Backend
        $s = $Item.state
        $failed = $false; $partial = $false

        if ([string]$s.scope -eq 'Active') {
            $list = @(& $B.List)
            $guids = @($list | ForEach-Object { [string]$_.guid })
            $cur = & $B.GetActive
            if ($cur -ne [string]$s.activeGuid) {
                if ($guids -notcontains [string]$s.activeGuid) {
                    $failed = $true
                    & $add 'activePlan' $false 'the plan that was active before no longer exists, so the active plan was not changed'
                } else {
                    try { & $B.SetActive ([string]$s.activeGuid); & $add 'activePlan' $true 'switched back to the original power plan' }
                    catch { $failed = $true; & $add 'activePlan' $false $_.Exception.Message }
                }
            } else { & $add 'activePlan' $true 'the original power plan was already active' }

            $dd = $Item.params.DeleteDuplicatesOf
            if ($dd) {
                # Only a plan whose id was RECORDED as created by this tweak right after Apply (state.created) is ever deleted.
                # A plan that merely looks alike (same name, made later by the user) is never touched.
                $known = @($s.schemes | ForEach-Object { [string]$_.guid })
                if ($null -eq $s.created) {
                    $partial = $true
                    [void]$details.Add(@{ part = 'createdPlans'; ok = $false; status = 'UserActionRequired'; message = 'the engine did not record which plan this tweak created, so no plan was deleted; check Power Options for an extra Ultimate Performance copy and remove it if you do not want it' })
                } else {
                    foreach ($u in @($s.unattributed)) {
                        if (@($guids) -contains [string]$u) { $partial = $true; [void]$details.Add(@{ part = "plan:$u"; ok = $false; status = 'UserActionRequired'; message = "a power plan ($u) appeared while the tweak ran and was not proven to be the tweak's, so it was NOT deleted; remove it in Power Options if it is a stray copy" }) }
                    }
                    $activeNow = & $B.GetActive
                    $existing = @(& $B.List | ForEach-Object { [string]$_.guid })
                    foreach ($c in @($s.created)) {
                        $g = [string]$c.guid
                        if ($known -contains $g -or $g -eq [string]$s.activeGuid) { & $add "plan:$g" $false 'the recorded created plan is one of the original plans, so it was not deleted'; $partial = $true; continue }
                        if ($existing -notcontains $g) { & $add "plan:$g" $true 'the plan the tweak created is already gone'; continue }
                        if ($g -eq $activeNow) { $partial = $true; & $add "plan:$g" $false 'a plan created by the tweak is active now, so it was kept'; continue }
                        try { & $B.DeleteScheme $g; & $add "plan:$g" $true 'deleted the plan the tweak created' } catch { $partial = $true; & $add "plan:$g" $false $_.Exception.Message }
                    }
                }
            }
        } else {
            $guids = @(& $B.List | ForEach-Object { [string]$_.guid })
            if ($guids -notcontains [string]$s.scheme) {
                return @{ ok = $true; partial = $true; message = 'The power plan that was changed no longer exists, so there is nothing to put back.'; details = @() }
            }
            foreach ($w in @($s.fields)) {
                $o = $s.values.$w
                try {
                    & $B.Write $s.scheme $s.subgroup $s.setting $w ([int64]$o.value)
                    if ($o.explicit) { & $add $w $true "value $($o.value) written back" }
                    else { & $add $w $true "value $($o.value) written back; it equals the plan default, but Windows now keeps it stored in the plan (cannot be removed, no change in behaviour)" }
                } catch { $failed = $true; & $add $w $false $_.Exception.Message }
            }
            # make the plan pick the values up (this is what powercfg /setactive did for the tweak)
            try { if ((& $B.GetActive) -eq [string]$s.scheme) { & $B.SetActive ([string]$s.scheme); & $add 'reapply' $true 'the active plan was re-applied' } } catch { $partial = $true; & $add 'reapply' $false $_.Exception.Message }
        }

        $v = Undo-PowerScheme-Verify $Item
        if (-not $v.matches) { $failed = $true; & $add 'verify' $false $v.diff }
        if (-not $failed -and -not $partial) { return @{ ok = $true; partial = $false; message = 'The power plan settings were put back to what they were before.'; details = @($details.ToArray()) } }
        if (-not $failed) { return @{ ok = $true; partial = $true; message = 'The power plan settings were put back, with notes (see details).'; details = @($details.ToArray()) } }
        return @{ ok = $false; partial = $true; message = "The power plan settings could not be fully put back: $($v.diff)"; details = @($details.ToArray()) }
    } catch {
        return @{ ok = $false; partial = $false; message = "Could not put the power plan settings back: $($_.Exception.Message)"; details = @($details.ToArray()) }
    }
}

# ---- providers\PreferenceSet.ps1 ----
if (-not $script:UndoProviders) { $script:UndoProviders = @{} }
# Membership deltas preserve original and unrelated exclusions.
function _PreferenceSet_Field { param($O,[string]$N,$D=$null) if($null -eq $O){return $D};if($O -is [Collections.IDictionary]){if($O.Contains($N)){return $O[$N]}}elseif($O.PSObject.Properties[$N]){return $O.$N};return $D }
function _PreferenceSet_Key {
    param([string]$Path)
    if([string]::IsNullOrWhiteSpace($Path) -or $Path -notmatch '^[A-Za-z]:\\' -or $Path -match '[\x00-\x1F*?]' -or $Path.Substring(2).Contains(':')){throw 'A literal local exclusion path is required.'}
    $p=[IO.Path]::GetFullPath($Path).TrimEnd('\');if($p.Length -le 3){throw 'A whole drive cannot be managed as an exclusion.'};return $p.ToLowerInvariant()
}
function _PreferenceSet_Read {
    $p=Get-MpPreference -ErrorAction Stop
    if(-not $p.PSObject.Properties['ExclusionPath']){throw 'Defender did not return exclusion membership.'}
    if($p.PSObject.Properties['DisableLocalAdminMerge'] -and $p.DisableLocalAdminMerge){throw 'Policy controls local exclusions.'}
    $values=@($p.ExclusionPath | Where-Object {$null -ne $_})
    if(@($values | Where-Object {[string]$_ -match '^\s*N/A\b'}).Count){throw 'Defender exclusion membership is hidden; run as administrator.'}
    if($null -eq $p.ExclusionPath -or $values.Count -eq 0){
        $identity=[Security.Principal.WindowsIdentity]::GetCurrent()
        $principal=New-Object Security.Principal.WindowsPrincipal($identity)
        if(-not $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)){throw 'Administrator access is needed to read an empty exclusion list.'}
        $status=Get-MpComputerStatus -ErrorAction Stop
        if(-not $status -or -not $status.PSObject.Properties['AMServiceEnabled']){throw 'Defender status is unavailable; an empty list cannot be confirmed.'}
    }
    return @{visible=$true;values=@([string[]]$values)}
}
function _PreferenceSet_SafeScope {
    param([string]$Path)
    $key=_PreferenceSet_Key $Path
    $blocked=@($env:SystemRoot,$env:ProgramData,$env:USERPROFILE,$env:LOCALAPPDATA,$env:APPDATA,$env:TEMP,(Join-Path $env:SystemDrive 'Users'))
    if($env:USERPROFILE){$blocked+=,(Split-Path $env:USERPROFILE -Parent)}
    foreach($b in $blocked){if($b){$b=[IO.Path]::GetFullPath($b).TrimEnd('\').ToLowerInvariant();if($key -eq $b -or $key.StartsWith($b+'\')){return $false}}}
    foreach($b in @($env:ProgramFiles,[Environment]::GetEnvironmentVariable('ProgramFiles(x86)'))){if($b -and $key -eq $b.TrimEnd('\').ToLowerInvariant()){return $false}}
    return $true
}
function _PreferenceSet_SafeFolder {
    param([string]$Path)
    $key=_PreferenceSet_Key $Path;$drive=New-Object IO.DriveInfo($Path.Substring(0,3));if($drive.DriveType -eq [IO.DriveType]::Network){return $false};if(-not(_PreferenceSet_SafeScope $Path)){return $false};if(-not(Test-Path -LiteralPath $Path -PathType Container -ErrorAction Stop)){return $false}
    foreach($b in @($env:SystemRoot,$env:ProgramData,$env:USERPROFILE,$env:LOCALAPPDATA,$env:APPDATA,$env:TEMP,(Join-Path $env:SystemDrive 'Users'))){
        if(-not $b){continue};$b=[IO.Path]::GetFullPath($b).TrimEnd('\').ToLowerInvariant();if($key -eq $b -or $key.StartsWith($b+'\')){return $false}
    }
    foreach($b in @($env:ProgramFiles,[Environment]::GetEnvironmentVariable('ProgramFiles(x86)'))){if($b -and $key -eq $b.TrimEnd('\').ToLowerInvariant()){return $false}}
    $p=$Path;while($p -and $p.Length -gt 3){if((Get-Item -LiteralPath $p -Force -ErrorAction Stop).Attributes -band [IO.FileAttributes]::ReparsePoint){return $false};$p=Split-Path $p -Parent};return $true
}
function _PreferenceSet_GameFolders {
    $pfx=[Environment]::GetEnvironmentVariable('ProgramFiles(x86)');$raw=@()
    foreach($b in @($env:ProgramFiles,$pfx)){if($b){foreach($leaf in @('Steam','Epic Games','Riot Games','Electronic Arts','Battle.net')){$p=Join-Path $b $leaf;if($p -notmatch '^[A-Za-z]:\\' -or (New-Object IO.DriveInfo($p.Substring(0,3))).DriveType -eq [IO.DriveType]::Network){continue};if(Test-Path -LiteralPath $p -PathType Container -ErrorAction Stop){$raw+=,$p}}}}
    if($env:ProgramFiles){$raw+=,(Join-Path $env:ProgramFiles 'EA Games')};if($pfx){$raw+=,(Join-Path $pfx 'Activision')}
    $candidates=@();if($pfx){$candidates+=,(Join-Path $pfx 'Steam')};if($env:ProgramFiles){$candidates+=,(Join-Path $env:ProgramFiles 'Steam')}
    $steam=$candidates | Where-Object {$_ -match '^[A-Za-z]:\\' -and (New-Object IO.DriveInfo($_.Substring(0,3))).DriveType -ne [IO.DriveType]::Network} | Where-Object {Test-Path -LiteralPath (Join-Path $_ 'steamapps\libraryfolders.vdf') -ErrorAction Stop} | Select-Object -First 1
    if($steam){
        $text=Get-Content -LiteralPath (Join-Path $steam 'steamapps\libraryfolders.vdf') -Raw -ErrorAction Stop
        foreach($m in [regex]::Matches($text,'"path"\s+"([^"]+)"')){$p=$m.Groups[1].Value.Replace('\\','\');if($p -notmatch '^[A-Za-z]:\\' -or (New-Object IO.DriveInfo($p.Substring(0,3))).DriveType -eq [IO.DriveType]::Network){continue};if(Test-Path -LiteralPath (Join-Path $p 'steamapps') -PathType Container -ErrorAction Stop){$raw+=,$p}}
    }
    $seen=@{};foreach($p in $raw){if(_PreferenceSet_SafeFolder $p){$k=_PreferenceSet_Key $p;if(-not $seen.ContainsKey($k)){$seen[$k]=$true;[IO.Path]::GetFullPath($p).TrimEnd('\')}}}
}
function _PreferenceSet_Add { param([string]$Path) Add-MpPreference -ExclusionPath $Path -ErrorAction Stop }
function _PreferenceSet_Remove { param([string]$Path) Remove-MpPreference -ExclusionPath $Path -ErrorAction Stop }
function _PreferenceSet_Plan {
    param($Params)
    if($Params.Name -ne 'DefenderExclusionPath'){throw 'Unknown preference set.'}
    if([string](_PreferenceSet_Field $Params 'Operation' 'Add') -notin @('Add','Remove')){throw 'Unknown preference operation.'}
    if((_PreferenceSet_Field $Params 'Source' '') -eq 'GameFolders'){$members=@(_PreferenceSet_GameFolders)}else{$members=@(_PreferenceSet_Field $Params 'Members' @())}
    if($members.Count -gt 1024){throw 'Too many preference members.'}
    $seen=@{};foreach($p in $members){$k=_PreferenceSet_Key $p;if(-not $seen.ContainsKey($k)){$seen[$k]=$true;@{path=[string]$p;key=$k}}}
}
function Undo-PreferenceSet-Capture {
    param([hashtable]$Params=@{})
    $r=@{type='PreferenceSet';v=1;params=$Params;state=$null;ok=$false;error=$null;capturedAt=[datetime]::UtcNow.ToString('o')}
    try{
        $plan=@(_PreferenceSet_Plan $Params);$now=_PreferenceSet_Read;if(-not $now.visible){throw 'Preference membership is hidden.'}
        $members=@();foreach($p in $plan){$same=@($now.values | Where-Object {([string]$_).TrimEnd('\').ToLowerInvariant() -eq $p.key});$members+=,@{path=$p.path;key=$p.key;existed=($same.Count -gt 0);originalText=@($same)}}
        $r.state=@{members=$members;baseline=@($now.values)};$r.ok=$true
    }catch{$r.error="Could not record the original exclusion entries: $($_.Exception.Message)"};return $r
}
function Undo-PreferenceSet-Validate {
    param($Item)
    try{
        if($Item.type -ne 'PreferenceSet' -or [int]$Item.v -ne 1 -or $Item.ok -ne $true -or $Item.params.Name -ne 'DefenderExclusionPath'){throw 'Invalid preference envelope.'}
        if([string](_PreferenceSet_Field $Item.params 'Operation' 'Add') -notin @('Add','Remove')){throw 'Invalid preference operation.'}
        $explicit=@(_PreferenceSet_Field $Item.params 'Members' @());$seen=@{}
        if(@($Item.state.members).Count -gt 1024){throw 'Too many preference members.'}
        if($explicit.Count -and @($Item.state.members).Count -ne @($explicit | ForEach-Object {_PreferenceSet_Key $_} | Select-Object -Unique).Count){throw 'A planned preference member is missing.'}
        foreach($m in @($Item.state.members)){
            $k=_PreferenceSet_Key $m.path
            if($Item.params.Source -in @('GameFolders','ResolvedGameFolder') -and -not(_PreferenceSet_SafeScope $m.path)){throw 'A game-folder preference points at a blocked scope.'}
            if($k -ne $m.key -or $seen.ContainsKey($k) -or $m.existed -isnot [bool]){throw 'Invalid preference member.'};$seen[$k]=$true
            if($explicit.Count -and @($explicit | Where-Object {(_PreferenceSet_Key $_) -eq $k}).Count -ne 1){throw 'Preference path is outside the plan.'}
            if($m.existed -and -not @($m.originalText).Count){throw 'Missing original preference text.'}
            if(-not $m.existed -and @($m.originalText).Count){throw 'Absent preference has original text.'}
            foreach($s in @($m.originalText)){if(([string]$s).TrimEnd('\').ToLowerInvariant() -ne $k){throw 'Original membership differs.'}}
        };return @{valid=$true;reason=''}
    }catch{return @{valid=$false;reason=$_.Exception.Message}}
}
function Undo-PreferenceSet-Verify {
    param($Item)
    try{
        $v=Undo-PreferenceSet-Validate $Item;if(-not $v.valid){throw $v.reason};$now=_PreferenceSet_Read;if(-not $now.visible){throw 'Preference membership is hidden.'}
        $diff=@();foreach($m in @($Item.state.members)){
            $exists=@($now.values | Where-Object {([string]$_).TrimEnd('\').ToLowerInvariant() -eq $m.key}).Count -gt 0
            if($exists -ne $m.existed){$diff+=,("Exclusion membership differs: "+$m.path)}
        };return @{matches=($diff.Count -eq 0);diff=($diff -join '; ')}
    }catch{return @{matches=$false;diff=$_.Exception.Message}}
}
function Undo-PreferenceSet-Restore {
    param($Item)
    $details=@()
    try{
        $v=Undo-PreferenceSet-Validate $Item;if(-not $v.valid){throw $v.reason};$op=[string](_PreferenceSet_Field $Item.params 'Operation' 'Add')
        foreach($m in @($Item.state.members)){
            try{
                $now=_PreferenceSet_Read;if(-not $now.visible){throw 'Preference membership is hidden.'}
                $existing=@($now.values | Where-Object {([string]$_).TrimEnd('\').ToLowerInvariant() -eq $m.key})
                if($op -eq 'Add'){
                    if(-not $m.existed -and $existing.Count){foreach($p in $existing){_PreferenceSet_Remove $p}}
                    if($m.existed -and -not $existing.Count){throw 'A baseline exclusion disappeared outside this addition; it was not recreated.'}
                }else{
                    if($m.existed -and -not $existing.Count){foreach($p in @($m.originalText)){_PreferenceSet_Add $p}}
                    if(-not $m.existed -and $existing.Count){throw 'A later exclusion was added; it was left untouched.'}
                };$details+=,@{path=$m.path;ok=$true;message='Original membership restored or preserved.'}
            }catch{$details+=,@{path=$m.path;ok=$false;message=$_.Exception.Message}}
        }
        $check=Undo-PreferenceSet-Verify $Item;$ok=$check.matches -and @($details | Where-Object {-not $_.ok}).Count -eq 0
        return @{ok=$ok;partial=(@($details | Where-Object {$_.ok}).Count -gt 0 -and -not $ok);message=$(if($ok){'Original exclusion membership restored.'}else{$check.diff});details=$details}
    }catch{return @{ok=$false;partial=$false;message=$_.Exception.Message;details=$details}}
}
function Undo-PreferenceSet-Describe { param($Item) try{return "Saved exclusion membership for $(@($Item.state.members).Count) folder(s)."}catch{return 'Saved exclusion entries.'} }
$script:UndoProviders['PreferenceSet']=@{Capture='Undo-PreferenceSet-Capture';Restore='Undo-PreferenceSet-Restore';Verify='Undo-PreferenceSet-Verify';Describe='Undo-PreferenceSet-Describe';Validate='Undo-PreferenceSet-Validate';VerifySeesApply = $false; Version=1}

# ---- providers\RegistryGuard.ps1 ----
# RegistryGuard provider (group D). Params: Key (HKLM:\ or HKCU:\ path), Name (value name), Message (plain text shown when blocked).
# A guard records NOTHING and restores nothing: Capture FAILS (so the action is not made) when the value exists. It is used where the
# action would delete a value that must never be copied into the undo records (a password stored in plain text), so that the value is
# not destroyed without a copy. Capture is read only.

if (-not $script:UndoProviders) { $script:UndoProviders = @{} }
$script:UndoProviders['RegistryGuard'] = @{ Capture = 'Undo-RegistryGuard-Capture'; Restore = 'Undo-RegistryGuard-Restore'; Verify = 'Undo-RegistryGuard-Verify'; Describe = 'Undo-RegistryGuard-Describe'; Validate = 'Undo-RegistryGuard-Validate'; VerifySeesApply = $true; Version = 1 }

function _RegistryGuard_Exists {
    param([string]$Key, [string]$Name)
    try { $null = Get-Item -LiteralPath $Key -ErrorAction Stop } catch [System.Management.Automation.ItemNotFoundException] { return $false }
    $k = Get-Item -LiteralPath $Key -ErrorAction Stop
    return (@($k.GetValueNames()) -contains $Name)
}
function Undo-RegistryGuard-Capture {
    param([hashtable]$Params)
    $out = @{ type = 'RegistryGuard'; v = 1; params = $Params; state = $null; ok = $false; error = $null; capturedAt = (Undo-Now) }
    try {
        $k = [string]$Params['Key']; $n = [string]$Params['Name']
        if (_RegistryGuard_Exists $k $n) {
            $m = [string]$Params['Message']
            $out.error = $(if ($m) { $m } else { "A value that StreamReady will not copy exists ($n); remove it yourself first." })
            return $out
        }
        $out.state = @{ key = $k; name = $n; absent = $true }
        $out.ok = $true
    } catch { $out.error = "could not check $($Params['Key']): $($_.Exception.Message)" }
    return $out
}
function Undo-RegistryGuard-Restore { param($Item) return @{ ok = $true; partial = $false; message = 'nothing was recorded for this check'; details = @() } }
function Undo-RegistryGuard-Verify { param($Item) return @{ matches = $true; diff = '' } }
function Undo-RegistryGuard-Describe { param($Item) try { return "Checked that $($Item['state']['name']) was not stored in plain text" } catch { return 'Plain text value check' } }
function Undo-RegistryGuard-Validate {
    param($Item)
    try {
        $p = $Item['params']
        if ([string]$p['Key'] -notmatch '^(HKLM|HKCU):\\[^\x00-\x1f]{1,400}$') { return @{ valid = $false; reason = 'registry path not allowed' } }
        if ([string]$p['Name'] -notmatch '^[A-Za-z0-9_. -]{1,100}$') { return @{ valid = $false; reason = 'value name not allowed' } }
        return @{ valid = $true; reason = $null }
    } catch { return @{ valid = $false; reason = $_.Exception.Message } }
}

# ---- providers\RegistryTree.ps1 ----
# ==============================================================================
# Undo Provider: RegistryTree
# Scope: Full key tree capture and restore with flat node representation.
# Implements strict spec binding (UE-1-01), deep recursive verification (UE-1-04),
# fail-closed depth enforcement (UE-1-04), and depth-safe flat serialization (UE-1-09).
# Shared across all StreamReady tweak groups.
# Windows PowerShell 5.1 compatible, dot-source safe, pure ASCII
# ==============================================================================

if (-not $script:UndoProviders) { $script:UndoProviders = @{} }
$script:UndoProviders['RegistryTree'] = @{
    Capture  = 'Undo-RegistryTree-Capture'
    Restore  = 'Undo-RegistryTree-Restore'
    Verify   = 'Undo-RegistryTree-Verify'
    Describe = 'Undo-RegistryTree-Describe'
    Validate = 'Undo-RegistryTree-Validate'
    VerifySeesApply = $true; Version  = 2
}

function _RegistryTree_TestPath {
    param([string]$Path)
    if ([string]::IsNullOrWhiteSpace($Path)) { return @{ ok = $true; exists = $false; error = $null } }
    $local:ErrorActionPreference = 'Stop'
    $errBefore = $error.Count
    try {
        $exists = [bool](Test-Path -LiteralPath $Path -ErrorAction Stop)
        if ($error.Count -gt $errBefore) {
            $msg = if ($error.Count -gt 0 -and $error[0]) { $error[0].ToString() } else { "Error probing '$Path'" }
            return @{ ok = $false; exists = $false; error = $msg }
        }
        return @{ ok = $true; exists = $exists; error = $null }
    } catch {
        return @{ ok = $false; exists = $false; error = [string]$_.Exception.Message }
    }
}

function _RegistryTree_IsSidValid {
    param([string]$Sid)
    if ([string]::IsNullOrWhiteSpace($Sid)) { return $false }
    return ($Sid -match '^S-1-\d+(-\d+)+$')
}

function _RegistryTree_OtherUser {
    param($Item)
    try {
        $key = if ($Item.params -and $Item.params.Key) { [string]$Item.params.Key } else { [string]$Item.state.key }
        if ($key -notmatch '^HKCU:') { return $null }
        $sid = [string]$Item.state.userSid
        if (-not $sid) { return 'this saved original is not tied to a Windows account, so it is not applied to this one' }
        $mySid = if (Get-Command 'Undo-My-Sid' -ErrorAction SilentlyContinue) { Undo-My-Sid } else {
            try { [string][System.Security.Principal.WindowsIdentity]::GetCurrent().User.Value } catch { $null }
        }
        if ($sid -ne $mySid) { return 'this saved original belongs to a different Windows account, so it is not applied to this one. Sign in as that account and press Undo there' }
        return $null
    } catch { return 'the Windows account of this saved original could not be checked' }
}

function _RegistryTree_SetNoneValue {
    param([string]$KeyPath, [string]$ValName, [byte[]]$Bytes)
    $hive = $null
    $sub = $null
    if ($KeyPath -match '^HKCU:\\(.*)$') {
        $hive = [Microsoft.Win32.Registry]::CurrentUser
        $sub = $Matches[1]
    } elseif ($KeyPath -match '^HKLM:\\(.*)$') {
        $hive = [Microsoft.Win32.Registry]::LocalMachine
        $sub = $Matches[1]
    } elseif ($KeyPath -match '^HKU:\\([^\\]+)\\(.*)$') {
        $hive = [Microsoft.Win32.Registry]::Users
        $sub = "$($Matches[1])\$($Matches[2])"
    } else {
        throw "Unsupported registry path: $KeyPath"
    }
    $sk = $hive.CreateSubKey($sub)
    try {
        $sk.SetValue($ValName, $Bytes, [Microsoft.Win32.RegistryValueKind]::None)
    } finally {
        $sk.Close()
    }
}

function _RegistryTree_ConvertDataFromType {
    param($RawData, [string]$Type)
    if ($null -eq $RawData) { return $null }
    switch ($Type) {
        'DWord'       { return [int][long]$RawData }
        'QWord'       { return [long]$RawData }
        'Binary'      { return [Convert]::FromBase64String([string]$RawData) }
        'None'        { return [Convert]::FromBase64String([string]$RawData) }
        'MultiString' { return [string[]]@($RawData) }
        default       { return [string]$RawData }
    }
}

function _RegistryTree_DeleteValue {
    param([string]$KeyPath, [string]$ValueName)
    if ($KeyPath -match '^(HKLM|HKCU|HKU):\\(.*)$') {
        $hive = $Matches[1]
        $sub = $Matches[2]
        $baseKey = switch ($hive) {
            'HKLM' { [Microsoft.Win32.Registry]::LocalMachine }
            'HKCU' { [Microsoft.Win32.Registry]::CurrentUser }
            'HKU'  { [Microsoft.Win32.Registry]::Users }
        }
        $rk = $baseKey.OpenSubKey($sub, $true)
        if ($rk) {
            try {
                $targetVal = if ($ValueName -eq '(default)') { '' } else { $ValueName }
                $rk.DeleteValue($targetVal, $false)
            } finally {
                $rk.Close()
            }
        }
    } else {
        $prop = if ([string]::IsNullOrEmpty($ValueName)) { '(default)' } else { $ValueName }
        Remove-ItemProperty -LiteralPath $KeyPath -Name $prop -ErrorAction SilentlyContinue
    }
}

function _RegistryTree_FindCreatedRoot {
    param([string]$KeyPath)
    $cur = $KeyPath
    $root = $KeyPath
    while ($true) {
        $parent = Split-Path -Path $cur -Parent
        if (-not $parent) { break }
        $tpParent = _RegistryTree_TestPath $parent
        if (-not $tpParent.ok -or $tpParent.exists) { break }
        $root = $parent
        $cur = $parent
    }
    return $root
}

function _RegistryTree_CollectFlatNodes {
    param(
        [string]$RootPath,
        [string]$RelPath,
        [int]$CurrentDepth,
        [int]$MaxDepth,
        [System.Collections.Generic.List[hashtable]]$NodeList
    )
    if ($CurrentDepth -gt $MaxDepth) {
        throw "Registry tree depth at '$RelPath' exceeds MaxDepth limit of $MaxDepth"
    }

    $currentFullPath = if ($RelPath) { "$RootPath\$RelPath" } else { $RootPath }
    $tpNode = _RegistryTree_TestPath $currentFullPath
    if (-not $tpNode.ok) {
        throw "Error probing registry tree node '$currentFullPath': $($tpNode.error)"
    }
    if (-not $tpNode.exists) { return }

    $k = Get-Item -LiteralPath $currentFullPath -ErrorAction Stop
    $values = [System.Collections.Generic.List[hashtable]]::new()

    foreach ($name in @($k.GetValueNames())) {
        $kind = $k.GetValueKind($name)
        $type = [string]$kind
        $raw = $k.GetValue($name, $null, [Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames)
        $data = if ($kind -eq [Microsoft.Win32.RegistryValueKind]::Binary -or $kind -eq [Microsoft.Win32.RegistryValueKind]::None) {
            [Convert]::ToBase64String([byte[]]$raw)
        } else {
            $raw
        }
        $values.Add(@{
            name = $name
            type = $type
            data = $data
        })
    }

    $sddl = $null
    $hasCustomSecurity = $false
    try {
        $acl = Get-Acl -Path $k.PSPath -ErrorAction Stop
        if ($acl) {
            # UE-R2-2-10: Record custom security if protected or has explicit rules
            if ($acl.AreAccessRulesProtected) {
                $hasCustomSecurity = $true
                $sddl = $acl.GetSecurityDescriptorSddlForm([System.Security.AccessControl.AccessControlSections]::Owner -bor [System.Security.AccessControl.AccessControlSections]::Access)
            } else {
                $explicitRules = @($acl.GetAccessRules($true, $false, [System.Security.Principal.SecurityIdentifier]))
                if ($explicitRules.Count -gt 0) {
                    $hasCustomSecurity = $true
                    $sddl = $acl.GetSecurityDescriptorSddlForm([System.Security.AccessControl.AccessControlSections]::Owner -bor [System.Security.AccessControl.AccessControlSections]::Access)
                }
            }
        }
    } catch {
        # UE-R4-2-05: Unreadable security descriptor must fail closed during capture
        throw "Could not read security descriptor on '$currentFullPath': $($_.Exception.Message)"
    }

    $NodeList.Add(@{
        relPath           = $RelPath
        hasCustomSecurity = $hasCustomSecurity
        sddl              = $sddl
        values            = @($values)
    })

    foreach ($subName in $k.GetSubKeyNames()) {
        $childRel = if ($RelPath) { "$RelPath\$subName" } else { $subName }
        _RegistryTree_CollectFlatNodes $RootPath $childRel ($CurrentDepth + 1) $MaxDepth $NodeList
    }
}

function _RegistryTree_PruneCreatedKey {
    param([string]$KeyPath, [string]$RootPath)
    $tpKey = _RegistryTree_TestPath $KeyPath
    if (-not $tpKey.ok) {
        throw "Error probing key '$KeyPath': $($tpKey.error)"
    }
    if ($tpKey.exists) {
        Remove-Item -LiteralPath $KeyPath -Recurse -Force -ErrorAction Stop
    }

    if ($KeyPath -eq $RootPath) { return }

    # Safely walk parents up to RootPath, deleting only if empty
    $cur = Split-Path -Path $KeyPath -Parent
    while ($true) {
        if (-not $cur) { break }
        $tpCur = _RegistryTree_TestPath $cur
        if (-not $tpCur.ok -or -not $tpCur.exists) { break }
        try {
            $k = Get-Item -LiteralPath $cur -ErrorAction Stop
            if ($k) {
                # Never delete a parent that contains remaining values or subkeys
                if (@($k.GetValueNames()).Count -gt 0 -or @($k.GetSubKeyNames()).Count -gt 0) { break }
                Remove-Item -LiteralPath $cur -ErrorAction Stop
            }
        } catch {
            break
        }
        if ($cur -eq $RootPath) { break }
        $cur = Split-Path -Path $cur -Parent
    }
}

function Undo-RegistryTree-Validate {
    param([hashtable]$Item)
    if (-not $Item) { return @{ valid = $false; reason = 'Item record is null' } }
    if ($Item.type -ne 'RegistryTree') { return @{ valid = $false; reason = "Type mismatch: expected RegistryTree, got '$($Item.type)'" } }
    if (-not $Item.params -or [string]::IsNullOrEmpty($Item.params.Key)) {
        return @{ valid = $false; reason = 'Missing spec params.Key' }
    }
    if (-not $Item.state) { return @{ valid = $false; reason = 'Item state is missing' } }

    $specKey = [string]$Item.params.Key
    $stateKey = [string]$Item.state.key

    # UE-1-01: State target must equal immutable spec target
    if ($stateKey -ne $specKey) {
        return @{ valid = $false; reason = "Refused: state.key '$stateKey' does not match spec params.Key '$specKey'" }
    }

    # Restrict allowed hives
    if ($specKey -notmatch '^HK(LM|CU|U):\\') {
        return @{ valid = $false; reason = "Refused: registry hive in '$specKey' is not allowed (must be HKLM, HKCU, or HKU)" }
    }

    # UE-R4-2-01: HKCU trees must be bound to a valid Windows account SID
    if ($specKey -match '^HKCU:') {
        $sid = [string]$Item.state.userSid
        if (-not (_RegistryTree_IsSidValid $sid)) {
            return @{ valid = $false; reason = 'a user setting is not tied to a valid Windows account (old format or damaged)' }
        }
    }

    # Verify createdRoot containment if present
    if ($Item.state.createdRoot) {
        $cRoot = [string]$Item.state.createdRoot
        if ($specKey -ne $cRoot -and -not $specKey.StartsWith("$cRoot\", [System.StringComparison]::OrdinalIgnoreCase)) {
            return @{ valid = $false; reason = "Refused: createdRoot '$cRoot' is not an ancestor of '$specKey'" }
        }
    }

    # UE-R2-2-04: Validate boolean keyExisted
    if ($Item.state.keyExisted -isnot [bool]) {
        return @{ valid = $false; reason = 'keyExisted must be a boolean' }
    }

    # Validate nodes structure
    $nodes = $Item.state.nodes
    if ($Item.state.keyExisted) {
        if ($null -eq $nodes -or $nodes.Count -eq 0) {
            return @{ valid = $false; reason = 'Missing nodes array for existing key' }
        }

        $seenRelPaths = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
        $hasRoot = $false

        foreach ($node in $nodes) {
            if ($node -is [string]) { return @{ valid = $false; reason = 'Node cannot be a string' } }
            if ($null -eq $node.relPath) { return @{ valid = $false; reason = 'Node missing relPath' } }
            $rel = [string]$node.relPath
            if ($rel -match '(\.\.|^\/|^\\|\/$|\\$)') {
                return @{ valid = $false; reason = "Invalid relPath '$rel'" }
            }
            if ($seenRelPaths.Contains($rel)) {
                return @{ valid = $false; reason = "Duplicate node relPath '$rel'" }
            }
            $seenRelPaths.Add($rel) | Out-Null
            if ($rel -eq '') { $hasRoot = $true }

            if ($node.values) {
                $seenValNames = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
                foreach ($v in $node.values) {
                    if ($v -is [string]) { return @{ valid = $false; reason = 'Value cannot be a string' } }
                    if ($null -eq $v.name) { return @{ valid = $false; reason = 'Value missing name' } }
                    $vName = [string]$v.name
                    if ($seenValNames.Contains($vName)) {
                        return @{ valid = $false; reason = "Duplicate value name '$vName' in node '$rel'" }
                    }
                    $seenValNames.Add($vName) | Out-Null

                    if ($v.type -notin @('String', 'ExpandString', 'DWord', 'QWord', 'Binary', 'MultiString', 'None')) {
                        return @{ valid = $false; reason = "Invalid registry data type '$($v.type)' on value '$vName'" }
                    }
                }
            }
        }

        # UE-R2-2-04: Must contain a root node
        if (-not $hasRoot) {
            return @{ valid = $false; reason = 'Nodes array must contain a root node (relPath = "")' }
        }

        # UE-R2-2-04: Parent closure check
        foreach ($rel in $seenRelPaths) {
            if ($rel -ne '') {
                $parentRel = Split-Path $rel -Parent
                if ($parentRel -and -not $seenRelPaths.Contains($parentRel)) {
                    return @{ valid = $false; reason = "Missing parent node for '$rel'" }
                }
            }
        }
    }

    return @{ valid = $true; reason = $null }
}

function Undo-RegistryTree-Capture {
    param([hashtable]$Params)
    try {
        if (-not $Params) { throw 'Params hashtable is required' }
        $key = [string]$Params.Key
        if ([string]::IsNullOrEmpty($key)) { throw 'Parameter Key is required' }
        $maxDepth = if ($Params.MaxDepth) { [int]$Params.MaxDepth } else { 5 }

        # UE-R4-2-01: A user hive item belongs to the Windows account that captured it
        $userSid = $null
        if ($key -match '^HKCU:') {
            $isSidOk = if (Get-Command 'Undo-My-Sid-Ok' -ErrorAction SilentlyContinue) { Undo-My-Sid-Ok } else { $true }
            $mySid = if (Get-Command 'Undo-My-Sid' -ErrorAction SilentlyContinue) { Undo-My-Sid } else {
                try { [string][System.Security.Principal.WindowsIdentity]::GetCurrent().User.Value } catch { $null }
            }
            if (-not $isSidOk -or -not (_RegistryTree_IsSidValid $mySid)) {
                throw 'StreamReady could not tell which Windows account this is, so it cannot tie a user setting to it'
            }
            $userSid = $mySid
        }

        $tp = _RegistryTree_TestPath $key
        if (-not $tp.ok) {
            throw "Error probing registry tree key '$key': $($tp.error)"
        }
        $keyExisted = $tp.exists
        $createdRoot = $null
        $nodesList = [System.Collections.Generic.List[hashtable]]::new()

        if (-not $keyExisted) {
            $createdRoot = _RegistryTree_FindCreatedRoot $key
        } else {
            # Collect flat nodes recursively; throws if depth exceeds MaxDepth (UE-1-04)
            _RegistryTree_CollectFlatNodes $key '' 0 $maxDepth $nodesList
        }

        $st = @{
            key         = $key
            keyExisted  = $keyExisted
            createdRoot = $createdRoot
            maxDepth    = $maxDepth
            nodes       = @($nodesList)
        }
        if ($userSid) {
            $st['userSid'] = $userSid
        }

        return @{
            type        = 'RegistryTree'
            v           = 2
            params      = $Params
            state       = $st
            ok          = $true
            error       = $null
            capturedAt  = (Get-Date).ToUniversalTime().ToString('o')
        }
    } catch {
        return @{
            type        = 'RegistryTree'
            v           = 2
            params      = $Params
            state       = $null
            ok          = $false
            error       = [string]$_.Exception.Message
            capturedAt  = (Get-Date).ToUniversalTime().ToString('o')
        }
    }
}

function Undo-RegistryTree-Restore {
    param([hashtable]$Item)
    try {
        $val = Undo-RegistryTree-Validate -Item $Item
        if (-not $val.valid) {
            return @{ ok = $false; partial = $false; message = "Validation failed: $($val.reason)"; details = @() }
        }

        # UE-1-01: Derive target strictly from validated spec params
        $targetKey = [string]$Item.params.Key

        # UE-R4-2-01: Verify live user matches original capturing user
        $who = _RegistryTree_OtherUser $Item
        if ($who) {
            return @{ ok = $false; partial = $false; message = "$($targetKey): $who"; details = @() }
        }

        $st = $Item.state
        $details = [System.Collections.Generic.List[hashtable]]::new()

        if ($st.keyExisted) {
            $capturedRelPaths = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)

            # Restore each captured node
            foreach ($node in $st.nodes) {
                $rel = [string]$node.relPath
                $capturedRelPaths.Add($rel) | Out-Null
                $nodeFullPath = if ($rel) { "$targetKey\$rel" } else { $targetKey }

                $tpNode = _RegistryTree_TestPath $nodeFullPath
                if (-not $tpNode.ok) {
                    throw "Error probing subkey node '$nodeFullPath': $($tpNode.error)"
                }
                if (-not $tpNode.exists) {
                    New-Item -Path $nodeFullPath -Force -ErrorAction Stop | Out-Null
                }

                $k = Get-Item -LiteralPath $nodeFullPath -ErrorAction Stop

                # UE-R2-2-10 & UE-R4-2-05: Restore security descriptor if captured
                if ($node.hasCustomSecurity -and $node.sddl) {
                    try {
                        $sec = New-Object System.Security.AccessControl.RegistrySecurity
                        $sec.SetSecurityDescriptorSddlForm([string]$node.sddl)
                        Set-Acl -Path $k.PSPath -AclObject $sec -ErrorAction Stop
                    } catch {
                        throw "Failed to restore security descriptor on '$nodeFullPath': $($_.Exception.Message)"
                    }
                }

                $capturedValNames = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)

                if ($node.values) {
                    foreach ($v in $node.values) {
                        $valName = [string]$v.name
                        $capturedValNames.Add($valName) | Out-Null
                        if ($valName -eq '') { $capturedValNames.Add('(default)') | Out-Null }

                        if ($v.type -eq 'None') {
                            $bytes = if ($v.data) { [Convert]::FromBase64String([string]$v.data) } else { [byte[]]@() }
                            _RegistryTree_SetNoneValue $nodeFullPath $valName $bytes
                        } else {
                            $typedData = _RegistryTree_ConvertDataFromType $v.data $v.type
                            $propParam = if ([string]::IsNullOrEmpty($valName)) { '(default)' } else { $valName }
                            Set-ItemProperty -LiteralPath $nodeFullPath -Name $propParam -Value $typedData -Type $v.type -ErrorAction Stop
                        }
                    }
                }

                # Remove extra values on this node that were not captured
                foreach ($curValName in $k.GetValueNames()) {
                    if (-not $capturedValNames.Contains($curValName) -and -not ($curValName -eq '' -and $capturedValNames.Contains('(default)'))) {
                        if ($curValName -eq '') {
                            _RegistryTree_DeleteValue $nodeFullPath ''
                        } else {
                            Remove-ItemProperty -LiteralPath $nodeFullPath -Name $curValName -ErrorAction SilentlyContinue
                        }
                    }
                }
            }

            # Prune extra subkeys that were not captured
            $tpTarget = _RegistryTree_TestPath $targetKey
            if (-not $tpTarget.ok) {
                throw "Error probing target key '$targetKey': $($tpTarget.error)"
            }
            if ($tpTarget.exists) {
                try {
                    $targetItem = Get-Item -LiteralPath $targetKey -ErrorAction Stop
                    $targetNorm = $targetItem.Name
                    $allCurrentSubs = Get-ChildItem -LiteralPath $targetKey -Recurse -ErrorAction Stop
                    # Sort descending by depth so children are deleted before parents
                    $sortedSubs = @($allCurrentSubs) | Sort-Object { $_.PSPath.Length } -Descending
                    foreach ($sub in $sortedSubs) {
                        $subRel = $sub.Name.Substring($targetNorm.Length).TrimStart('\')
                        if (-not $capturedRelPaths.Contains($subRel)) {
                            Remove-Item -LiteralPath $sub.PSPath -Recurse -Force -ErrorAction SilentlyContinue
                        }
                    }
                } catch {}
            }

            $details.Add(@{
                key     = $targetKey
                ok      = $true
                action  = 'restored_tree'
                message = "Restored registry key tree '$targetKey' with all original nodes and values"
            })
        } else {
            # Key did not exist originally; prune if created
            $tpTarget = _RegistryTree_TestPath $targetKey
            if (-not $tpTarget.ok) {
                return @{ ok = $false; partial = $false; message = "Error probing key '$targetKey': $($tpTarget.error)"; details = @() }
            }
            if ($tpTarget.exists) {
                _RegistryTree_PruneCreatedKey $targetKey $st.createdRoot
                $details.Add(@{
                    key         = $targetKey
                    createdRoot = $st.createdRoot
                    ok          = $true
                    action      = 'pruned_created_tree'
                    message     = "Deleted created key '$targetKey' and pruned empty ancestors up to '$($st.createdRoot)'"
                })
            } else {
                $details.Add(@{
                    key     = $targetKey
                    ok      = $true
                    action  = 'already_absent'
                    message = "Key '$targetKey' was already absent"
                })
            }
        }

        $ver = Undo-RegistryTree-Verify -Item $Item
        $msg = if ($ver.matches) {
            "Registry tree '$targetKey' restored successfully."
        } else {
            "Registry tree '$targetKey' restored with verify differences: $($ver.diff)"
        }

        return @{
            ok      = $ver.matches
            partial = (-not $ver.matches)
            message = $msg
            details = @($details)
        }
    } catch {
        return @{
            ok      = $false
            partial = $false
            message = "Unexpected error during tree restore: $($_.Exception.Message)"
            details = @()
        }
    }
}

function Undo-RegistryTree-Verify {
    param([hashtable]$Item)
    try {
        $val = Undo-RegistryTree-Validate -Item $Item
        if (-not $val.valid) { return @{ matches = $false; diff = "Validation error: $($val.reason)" } }

        $targetKey = [string]$Item.params.Key

        # UE-R4-2-01: Verify live user matches original capturing user
        $who = _RegistryTree_OtherUser $Item
        if ($who) { return @{ matches = $false; diff = $who } }

        $st = $Item.state
        $tpTarget = _RegistryTree_TestPath $targetKey
        if (-not $tpTarget.ok) {
            return @{ matches = $false; diff = "Error probing target key '$targetKey': $($tpTarget.error)" }
        }
        $keyExists = $tpTarget.exists

        if (-not $st.keyExisted) {
            if ($keyExists) {
                return @{ matches = $false; diff = "Key '$targetKey' exists, expected absent." }
            }
            return @{ matches = $true; diff = 'State matches original exactly.' }
        }

        if (-not $keyExists) {
            return @{ matches = $false; diff = "Key '$targetKey' does not exist, expected tree to be restored." }
        }

        # UE-1-04: Recursively verify ALL nodes and child subkeys
        $diffs = [System.Collections.Generic.List[string]]::new()
        $capturedRelPaths = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)

        foreach ($node in $st.nodes) {
            $rel = [string]$node.relPath
            $capturedRelPaths.Add($rel) | Out-Null
            $nodeFullPath = if ($rel) { "$targetKey\$rel" } else { $targetKey }

            $tpNode = _RegistryTree_TestPath $nodeFullPath
            if (-not $tpNode.ok) {
                $diffs.Add("[$rel]: Error probing subkey: $($tpNode.error)")
                continue
            }
            if (-not $tpNode.exists) {
                $diffs.Add("Missing expected subkey node at '$rel'")
                continue
            }

            $k = Get-Item -LiteralPath $nodeFullPath -ErrorAction Stop
            $curNames = @($k.GetValueNames())
            $capturedValNames = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)

            if ($node.values) {
                foreach ($v in $node.values) {
                    $name = [string]$v.name
                    $capturedValNames.Add($name) | Out-Null

                    $curVal = $k.GetValue($name, $null, [Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames)
                    if ($null -eq $curVal) {
                        $diffs.Add("[$rel]: Missing expected value '$name'")
                        continue
                    }

                    # UE-1-04: Verify registry kind matches exactly
                    $curKind = [string]$k.GetValueKind($name)
                    if ($curKind -ne [string]$v.type) {
                        $diffs.Add("[$rel]: Type mismatch on '$name': current '$curKind', expected '$($v.type)'")
                    }

                    # UE-R2-2-03: Byte-exact and case-sensitive data verification
                    $matchesVal = $false
                    switch ($curKind) {
                        'Binary' {
                            $curB64 = [Convert]::ToBase64String([byte[]]$curVal)
                            $matchesVal = [string]::Equals($curB64, [string]$v.data, [System.StringComparison]::Ordinal)
                        }
                        'None' {
                            $curB64 = [Convert]::ToBase64String([byte[]]$curVal)
                            $matchesVal = [string]::Equals($curB64, [string]$v.data, [System.StringComparison]::Ordinal)
                        }
                        'MultiString' {
                            $curArr = [string[]]@($curVal)
                            $expArr = [string[]]@($v.data)
                            if ($curArr.Length -eq $expArr.Length) {
                                $matchesVal = $true
                                for ($i = 0; $i -lt $curArr.Length; $i++) {
                                    if (-not ($curArr[$i] -ceq $expArr[$i])) {
                                        $matchesVal = $false
                                        break
                                    }
                                }
                            }
                        }
                        'DWord' {
                            $matchesVal = ([long]$curVal -eq [long]$v.data)
                        }
                        'QWord' {
                            $matchesVal = ([long]$curVal -eq [long]$v.data)
                        }
                        default {
                            $matchesVal = [string]::Equals([string]$curVal, [string]$v.data, [System.StringComparison]::Ordinal)
                        }
                    }
                    if (-not $matchesVal) {
                        $diffs.Add("[$rel]: Value mismatch on '$name': current '$curVal', expected '$($v.data)'")
                    }
                }
            }

            # UE-R2-2-10 & UE-R4-2-05: Verify security descriptor if captured
            if ($node.hasCustomSecurity -and $node.sddl) {
                try {
                    $curAcl = Get-Acl -Path $k.PSPath -ErrorAction Stop
                    if ($null -eq $curAcl) {
                        $diffs.Add("[$rel]: Security descriptor could not be read (returned null)")
                    } elseif (-not $curAcl.AreAccessRulesProtected -and @($curAcl.GetAccessRules($true, $false, [System.Security.Principal.SecurityIdentifier])).Count -eq 0) {
                        $diffs.Add("[$rel]: Security descriptor mismatch: key has default inherited security, expected custom non-inherited security '$($node.sddl)'")
                    } else {
                        $curSddl = $curAcl.GetSecurityDescriptorSddlForm([System.Security.AccessControl.AccessControlSections]::Owner -bor [System.Security.AccessControl.AccessControlSections]::Access)
                        if ($curSddl -ne [string]$node.sddl) {
                            $diffs.Add("[$rel]: Security descriptor mismatch: current '$curSddl', expected '$($node.sddl)'")
                        }
                    }
                } catch {
                    $diffs.Add("[$rel]: Failed to read security descriptor: $($_.Exception.Message)")
                }
            }

            # Check for unexpected extra values
            foreach ($curValName in $curNames) {
                if (-not $capturedValNames.Contains($curValName)) {
                    $diffs.Add("[$rel]: Unexpected extra value '$curValName' present on key")
                }
            }
        }

        # Check for unexpected extra subkeys
        try {
            $targetItem = Get-Item -LiteralPath $targetKey -ErrorAction Stop
            $targetNorm = $targetItem.Name
            $allCurrentSubs = Get-ChildItem -LiteralPath $targetKey -Recurse -ErrorAction Stop
            foreach ($sub in $allCurrentSubs) {
                $subRel = $sub.Name.Substring($targetNorm.Length).TrimStart('\')
                if (-not $capturedRelPaths.Contains($subRel)) {
                    $diffs.Add("Unexpected extra subkey present at '$subRel'")
                }
            }
        } catch {
            $diffs.Add("Error enumerating subkeys under '$targetKey': $($_.Exception.Message)")
        }

        if ($diffs.Count -gt 0) {
            return @{ matches = $false; diff = ($diffs -join '; ') }
        }
        return @{ matches = $true; diff = 'State matches original exactly.' }
    } catch {
        return @{ matches = $false; diff = "Verify failed: $($_.Exception.Message)" }
    }
}

function Undo-RegistryTree-Describe {
    param([hashtable]$Item)
    if (-not $Item -or -not $Item.state) { return 'Registry tree: no details available.' }
    $st = $Item.state
    $targetKey = if ($Item.params -and $Item.params.Key) { $Item.params.Key } else { $st.key }
    if ($st.keyExisted) {
        $nodeCount = if ($st.nodes) { @($st.nodes).Count } else { 0 }
        return "Registry key tree '$targetKey' ($nodeCount nodes): original state recorded."
    } else {
        return "Registry key '$targetKey': originally absent; restore will remove if created."
    }
}

# ---- providers\ScheduledTask.ps1 ----
if (-not $script:UndoProviders) { $script:UndoProviders = @{} }
# Task definitions and security, without storing task credentials.
function _ScheduledTask_Field { param($O,[string]$N,$D=$null) if($null -eq $O){return $D};if($O -is [Collections.IDictionary]){if($O.Contains($N)){return $O[$N]}}elseif($O.PSObject.Properties[$N]){return $O.$N};return $D }
function _ScheduledTask_Target {
    param($Params)
    $name=[string]$Params.Name;$path=[string](_ScheduledTask_Field $Params 'TaskPath' (_ScheduledTask_Field $Params 'Path' '\'))
    if($name -notin @('StreamReady_TimerRes','RegIdleBackup') -and $name -notmatch '^SRUndoTest-p6-[A-Za-z0-9-]{1,64}$'){throw 'This task name is outside the provider allowlist.'}
    if($path -notmatch '^\\(?:[A-Za-z0-9 _.-]+\\)*$' -or $path -match '(^|\\)\.\.?\\'){throw 'Invalid task folder.'}
    if($name -eq 'RegIdleBackup' -and $path -ne '\Microsoft\Windows\Registry\'){throw 'Unexpected registry backup task path.'}
    if($name -in @('StreamReady_TimerRes') -and $path -ne '\'){throw 'Unexpected helper task path.'}
    return @{name=$name;path=$path}
}
function _ScheduledTask_Parse {
    param([string]$Text)
    $settings=New-Object Xml.XmlReaderSettings;$settings.DtdProcessing=[Xml.DtdProcessing]::Prohibit;$settings.XmlResolver=$null;$settings.MaxCharactersInDocument=1048576
    $reader=[Xml.XmlReader]::Create((New-Object IO.StringReader($Text)),$settings)
    try{$doc=New-Object Xml.XmlDocument;$doc.XmlResolver=$null;$doc.Load($reader);return $doc}finally{$reader.Dispose()}
}
function _ScheduledTask_Canonical {
    param([string]$Text)
    if(-not $Text){return ''}
    $doc=_ScheduledTask_Parse $Text
    foreach($node in @($doc.SelectNodes("//*[local-name()='RegistrationInfo']/*[local-name()='SecurityDescriptor']"))){[void]$node.ParentNode.RemoveChild($node)}
    return $doc.OuterXml
}
function _ScheduledTask_Hash {
    param([string]$Text)
    $h=[Security.Cryptography.SHA256]::Create()
    try{return ([BitConverter]::ToString($h.ComputeHash([Text.Encoding]::UTF8.GetBytes((_ScheduledTask_Canonical $Text))))).Replace('-','')}finally{$h.Dispose()}
}
function _ScheduledTask_AllowedXml {
    param([string]$Xml,[string]$Name)
    $doc=_ScheduledTask_Parse $Xml
    if($Name -eq 'RegIdleBackup'){return}
    if($doc.DocumentElement.LocalName -ne 'Task'){throw 'Not a task definition.'}
    $actions=@($doc.SelectNodes("//*[local-name()='Actions']/*"))
    if($actions.Count -ne 1 -or $actions[0].LocalName -ne 'Exec'){throw 'Only a single owned helper action can be restored.'}
    $command=$actions[0].SelectSingleNode("*[local-name()='Command']").InnerText
    $args=$actions[0].SelectSingleNode("*[local-name()='Arguments']").InnerText
    if($Name -like 'SRUndoTest-p6-*'){
        if($command -ne (Join-Path $env:SystemRoot 'System32\cmd.exe') -or $args -ne '/c exit 0'){throw 'Fixture tasks must use the harmless exit action.'}
    }else{
        if($command -ne (Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe')){throw 'The task does not use the owned helper host.'}
        $file='SetTimerRes.ps1'
        $paid=Join-Path $env:ProgramData ('StreamReady\'+$file);$free=Join-Path $env:ProgramData ('StreamReady-OSS\'+$file)
        $allowed=@()
        foreach($f in @($paid,$free)){
            $allowed+=('-NoProfile -NonInteractive -WindowStyle Hidden -ExecutionPolicy Bypass -File "'+$f+'"')
            $allowed+=('-NoProfile -WindowStyle Hidden -ExecutionPolicy Bypass -File "'+$f+'"')
        }
        if($allowed -notcontains $args){throw 'The task arguments differ from the supported helper action.'}
    }
}
function _ScheduledTask_Read {
    param($Target)
    $svc=New-Object -ComObject Schedule.Service
    try{
        $svc.Connect()
        try{$folder=$svc.GetFolder($(if ($Target.path.Length -gt 1) { $Target.path.TrimEnd([char]92) } else { $Target.path }))}catch{
            if($_.Exception.HResult -in @(-2147024894,-2147024893)){return @{existed=$false;xml=$null;sddl=$null;enabled=$null;running=$false;logonType=$null;userId=$null}}
            throw
        }
        try{
            $task=$null
            foreach($t in $folder.GetTasks(1)){if($t.Name -eq $Target.name){$task=$t;break}}
            if(-not $task){return @{existed=$false;xml=$null;sddl=$null;enabled=$null;running=$false;logonType=$null;userId=$null}}
            try{return @{existed=$true;xml=[string]$task.Xml;sddl=[string]$task.GetSecurityDescriptor(7);enabled=[bool]$task.Enabled;running=($task.GetInstances(0).Count -gt 0);logonType=[int]$task.Definition.Principal.LogonType;userId=[string]$task.Definition.Principal.UserId}}
            finally{[void][Runtime.InteropServices.Marshal]::FinalReleaseComObject($task)}
        }finally{[void][Runtime.InteropServices.Marshal]::FinalReleaseComObject($folder)}
    }finally{if($svc){[void][Runtime.InteropServices.Marshal]::FinalReleaseComObject($svc)}}
}
function _ScheduledTask_Write {
    param($Target,$Original)
    $svc=New-Object -ComObject Schedule.Service
    try{
        $svc.Connect();$folder=$svc.GetFolder($(if ($Target.path.Length -gt 1) { $Target.path.TrimEnd([char]92) } else { $Target.path }))
        try{
            $current=$null;foreach($t in $folder.GetTasks(1)){if($t.Name -eq $Target.name){$current=$t;break}}
            if($Target.name -eq 'RegIdleBackup'){
                if(-not $Original.existed){if($current){throw 'A system task appeared after capture; it was left untouched.'};return}
                if(-not $current){throw 'The original system task disappeared; its definition is not recreated.'}
                try{$current.Enabled=[bool]$Original.enabled}finally{[void][Runtime.InteropServices.Marshal]::FinalReleaseComObject($current)};return
            }
            if($current){try{_ScheduledTask_AllowedXml ([string]$current.Xml) $Target.name;$current.Stop(0)}finally{[void][Runtime.InteropServices.Marshal]::FinalReleaseComObject($current)}}
            if(-not $Original.existed){if($current){$folder.DeleteTask($Target.name,0)};return}
            $task=$folder.RegisterTask($Target.name,[string]$Original.xml,6,[string]$Original.userId,$null,[int]$Original.logonType,[string]$Original.sddl)
            try{
                $task.Enabled=[bool]$Original.enabled
                if($Original.running){[void]$task.Run($null)}
            }finally{[void][Runtime.InteropServices.Marshal]::FinalReleaseComObject($task)}
        }finally{[void][Runtime.InteropServices.Marshal]::FinalReleaseComObject($folder)}
    }finally{[void][Runtime.InteropServices.Marshal]::FinalReleaseComObject($svc)}
}
function Undo-ScheduledTask-Capture {
    param([hashtable]$Params=@{})
    $result=@{type='ScheduledTask';v=1;params=$Params;state=$null;ok=$false;error=$null;capturedAt=[datetime]::UtcNow.ToString('o')}
    try{
        $target=_ScheduledTask_Target $Params;$state=_ScheduledTask_Read $target
        if($state.existed){
            _ScheduledTask_AllowedXml $state.xml $target.name
            if($state.logonType -in @(1,6)){throw 'The existing task needs a password that cannot be saved for exact restoration.'}
            if($target.name -ne 'RegIdleBackup' -and $state.running -and -not(_ScheduledTask_Field $Params 'AllowRestartOriginal' $false)){throw 'Undo the previous run first. Its helper is still running and cannot be safely replaced.'}
            $state['xmlHash']=_ScheduledTask_Hash $state.xml
        }
        $result.state=$state;$result.ok=$true
    }catch{$result.error="Could not record the original task: $($_.Exception.Message)"};return $result
}
function Undo-ScheduledTask-Validate {
    param($Item)
    try{
        if($Item.type -ne 'ScheduledTask' -or [int]$Item.v -ne 1 -or $Item.ok -ne $true){throw 'Invalid task envelope.'}
        $t=_ScheduledTask_Target $Item.params;$s=$Item.state
        if($s.existed -isnot [bool] -or $s.running -isnot [bool]){throw 'Invalid task existence or running flag.'}
        if($s.existed){
            if($s.enabled -isnot [bool] -or $s.logonType -notin @(0,2,3,4,5)){throw 'Task credentials or enabled state cannot be restored.'}
            _ScheduledTask_AllowedXml $s.xml $t.name
            if((_ScheduledTask_Hash $s.xml) -ne $s.xmlHash){throw 'Task XML hash mismatch.'}
            $sd=New-Object Security.AccessControl.RawSecurityDescriptor([string]$s.sddl)
            if($t.name -ne 'RegIdleBackup' -and $s.running -and -not(_ScheduledTask_Field $Item.params 'AllowRestartOriginal' $false)){throw 'Unsafe original running task.'}
        }elseif($s.xml -or $s.sddl -or $s.running){throw 'An absent task has an original definition.'}
        return @{valid=$true;reason=''}
    }catch{return @{valid=$false;reason=$_.Exception.Message}}
}
function Undo-ScheduledTask-Verify {
    param($Item)
    try{
        $v=Undo-ScheduledTask-Validate $Item;if(-not $v.valid){throw $v.reason}
        $now=_ScheduledTask_Read (_ScheduledTask_Target $Item.params);$old=$Item.state
        $same=($now.existed -eq $old.existed)
        if($Item.params.Name -eq 'RegIdleBackup'){return @{matches=($same -and (-not $old.existed -or $now.enabled -eq $old.enabled));diff='Registry backup task enabled state differs.'}}
        if($same -and $old.existed){$same=((_ScheduledTask_Canonical $now.xml) -ceq (_ScheduledTask_Canonical $old.xml)) -and $now.sddl -eq $old.sddl -and $now.enabled -eq $old.enabled -and $now.running -eq $old.running}
        return @{matches=$same;diff=$(if($same){''}else{'Task definition, security, enabled state or running state differs.'})}
    }catch{return @{matches=$false;diff=$_.Exception.Message}}
}
function Undo-ScheduledTask-Restore {
    param($Item)
    try{
        $v=Undo-ScheduledTask-Validate $Item;if(-not $v.valid){throw $v.reason}
        $already=Undo-ScheduledTask-Verify $Item
        if($already.matches){return @{ok=$true;partial=$false;message='The task is already original.';details=@()}}
        _ScheduledTask_Write (_ScheduledTask_Target $Item.params) $Item.state
        $check=Undo-ScheduledTask-Verify $Item
        return @{ok=[bool]$check.matches;partial=$false;message=$(if($check.matches){'Original task restored.'}else{$check.diff});details=@(@{target=$Item.params.Name;ok=[bool]$check.matches})}
    }catch{return @{ok=$false;partial=$false;message=$_.Exception.Message;details=@()}}
}
function Undo-ScheduledTask-Describe { param($Item) try{return "Scheduled task $($Item.params.Name): $(if($Item.state.existed){'saved original definition'}else{'did not exist before'})."}catch{return 'Saved task state.'} }
$script:UndoProviders['ScheduledTask']=@{Capture='Undo-ScheduledTask-Capture';Restore='Undo-ScheduledTask-Restore';Verify='Undo-ScheduledTask-Verify';Describe='Undo-ScheduledTask-Describe';Validate='Undo-ScheduledTask-Validate';VerifySeesApply = $true; Version=1}

# ---- providers\Service.ps1 ----
# StreamReady undo engine - provider: Service (Windows services: start type, delayed start, running state)
# Plain function definitions plus one registration. Dot-source safe. ASCII only.
#
# Params (hashtable):
#   Name               (required) service name, for example 'SysMain'
#   RemoveIfCreated    (optional, default $false) if the service did NOT exist at capture and exists at restore, delete it
#                      (only for services a tool itself created; never set this for Windows services)
#   StopIfWasStopped   (optional, default $false) if the service was stopped at capture and is running at restore, stop it
#                      (for tools that start a service; Apply of group A tweaks only stops services, so this stays off)
#   StopIfCreated      (optional, default $false) if the service did NOT exist at capture and is running at restore, stop it (do not
#                      delete it: another item, for example a Windows capability, removes the component later)
#
# State (JSON safe): existed, startType (Boot|System|Automatic|Manual|Disabled), regStart (0-4), delayedRaw (0|1|null),
#   delayed (effective: only for Automatic), status (Running|Stopped|Other), runningDependents (names, parents first),
#   imagePath, displayName

if ($null -eq $script:UndoProviders) { $script:UndoProviders = @{} }
$script:UndoProviders['Service'] = @{ Capture = 'Undo-Service-Capture'; Restore = 'Undo-Service-Restore'; Verify = 'Undo-Service-Verify'; Describe = 'Undo-Service-Describe'; Validate = 'Undo-Service-Validate'; VerifySeesApply = $true; Version = 1 }

function _Svc_Now { return (Get-Date).ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ssZ') }

function _Svc_ValidName {
    param($Name)
    return ([string]$Name -match '^[A-Za-z0-9_.\-]{1,256}$')
}

function _Svc_RegKey {
    param([string]$Name)
    return ('HKLM:\SYSTEM\CurrentControlSet\Services\' + $Name)
}

function _Svc_StartName {
    param([int]$Start)
    switch ($Start) { 0 { 'Boot' } 1 { 'System' } 2 { 'Automatic' } 3 { 'Manual' } 4 { 'Disabled' } default { 'Unknown' } }
}

# all running services that depend on this one (whole tree), parents before dependents, no duplicates
function _Svc_RunningDependents {
    param($Svc)
    $seen = @{}
    $out = New-Object System.Collections.ArrayList
    $walk = $null
    $walk = {
        param($s)
        foreach ($d in @($s.DependentServices)) {
            if (-not $seen.ContainsKey($d.Name)) {
                $seen[$d.Name] = $true
                if ($d.Status -eq 'Running') { [void]$out.Add([string]$d.Name) }
                & $walk $d
            }
        }
    }
    & $walk $Svc
    return @($out.ToArray())
}

# every service that depends on this one (whole tree), whatever its state
function _Svc_AllDependents {
    param([string]$Name)
    $out = @(); $seen = @{}
    try {
        $queue = New-Object System.Collections.Queue
        $queue.Enqueue((Get-Service -Name $Name -ErrorAction Stop))
        while ($queue.Count -gt 0) {
            $s = $queue.Dequeue()
            foreach ($d in @($s.DependentServices)) { if (-not $seen.ContainsKey([string]$d.Name)) { $seen[[string]$d.Name] = $true; $out += [string]$d.Name; $queue.Enqueue($d) } }
        }
    } catch { }
    return $out
}

# Reads the current state of one service. Throws a plain error if it cannot be read exactly.
function _Svc_Read {
    param([string]$Name)
    $key = _Svc_RegKey $Name
    $r = @{ existed = $false; startType = $null; regStart = $null; delayedRaw = $null; delayed = $false; status = $null; runningDependents = @(); imagePath = $null; displayName = $null }
    if (-not (Test-Path -LiteralPath $key)) { return $r }
    $p = Get-ItemProperty -LiteralPath $key -ErrorAction Stop
    $type = 0
    if ($null -ne $p.Type) { $type = [int]$p.Type }
    if (($type -band 3) -ne 0) { throw "'$Name' is a driver, not a Windows service" }
    if ($null -eq $p.Start) { throw "service '$Name' has no Start value" }
    $r.existed = $true
    $r.regStart = [int]$p.Start
    $r.startType = _Svc_StartName $r.regStart
    if ($null -ne $p.DelayedAutostart) { $r.delayedRaw = [int]$p.DelayedAutostart }
    $r.delayed = (($r.regStart -eq 2) -and ($r.delayedRaw -eq 1))
    if ($null -ne $p.ImagePath) { $r.imagePath = [string]$p.ImagePath }
    $svc = $null
    try { $svc = Get-Service -Name $Name -ErrorAction Stop } catch { $svc = $null }
    if ($svc) {
        $r.displayName = [string]$svc.DisplayName
        if ($svc.Status -eq 'Running') { $r.status = 'Running' } elseif ($svc.Status -eq 'Stopped') { $r.status = 'Stopped' } else { $r.status = 'Other' }
        $r.runningDependents = @(_Svc_RunningDependents $svc)
    } else { $r.status = 'Other' }
    return $r
}

function Undo-Service-Capture {
    param($Params)
    $res = @{ type = 'Service'; v = 1; params = $Params; state = $null; ok = $false; error = $null; capturedAt = (_Svc_Now) }
    try {
        if ($null -eq $Params -or -not (_Svc_ValidName $Params.Name)) { throw 'the service name is missing or has characters that are not allowed' }
        $res.state = _Svc_Read ([string]$Params.Name)
        $res.state.name = [string]$Params.Name
        $res.ok = $true
    } catch { $res.error = "Could not record the original state of service '$($Params.Name)': $($_.Exception.Message)" }
    return $res
}

function Undo-Service-Validate {
    param($Item)
    try {
        if ($null -eq $Item -or [string]$Item.type -ne 'Service') { return @{ valid = $false; reason = 'not a Service record' } }
        $s = $Item.state
        if ($null -eq $s) { return @{ valid = $false; reason = 'no state' } }
        if (-not (_Svc_ValidName $s.name) -or [string]$s.name -ne [string]$Item.params.Name) { return @{ valid = $false; reason = 'service name is not valid or does not match the parameters' } }
        if ($s.existed -isnot [bool]) { return @{ valid = $false; reason = 'existed must be true or false' } }
        if ($s.existed) {
            if ($null -eq $s.regStart -or [int]$s.regStart -lt 0 -or [int]$s.regStart -gt 4) { return @{ valid = $false; reason = 'start type out of range' } }
            if ([string]$s.status -notin @('Running', 'Stopped', 'Other')) { return @{ valid = $false; reason = 'status not recognised' } }
            if ($null -ne $s.delayedRaw -and [int]$s.delayedRaw -notin @(0, 1)) { return @{ valid = $false; reason = 'delayed flag out of range' } }
            foreach ($d in @($s.runningDependents)) { if (-not (_Svc_ValidName $d)) { return @{ valid = $false; reason = 'a dependent service name is not valid' } } }
            if ($s.imagePath -and ([string]$s.imagePath).Length -gt 4096) { return @{ valid = $false; reason = 'image path too long' } }
        }
        return @{ valid = $true; reason = $null }
    } catch { return @{ valid = $false; reason = $_.Exception.Message } }
}

function Undo-Service-Describe {
    param($Item)
    try {
        $s = $Item.state
        if (-not $s.existed) { return "Windows service $($s.name): not installed" }
        $t = [string]$s.startType
        if ($s.delayed) { $t = 'Automatic (delayed start)' }
        $run = if ([string]$s.status -eq 'Running') { 'running' } elseif ([string]$s.status -eq 'Stopped') { 'stopped' } else { 'state unknown' }
        return "Windows service $($s.name): $t ($run)"
    } catch { return 'Windows service (record could not be read)' }
}

function Undo-Service-Verify {
    param($Item)
    try {
        $s = $Item.state
        $name = [string]$s.name
        $cur = _Svc_Read $name
        $diff = New-Object System.Collections.ArrayList
        $optRemove = ($Item.params -and $Item.params.RemoveIfCreated -eq $true)
        # StopIfCreated also means: a service that EXISTED but was stopped must not stay running after Undo (UE-R2-2-08)
        $optStopNew = ($Item.params -and $Item.params.StopIfCreated -eq $true)
        $optStop = ($Item.params -and ($Item.params.StopIfWasStopped -eq $true -or $Item.params.StopIfCreated -eq $true))
        if (-not $s.existed) {
            if ($cur.existed -and $optRemove) { [void]$diff.Add("service exists now but did not exist before") }
            elseif ($cur.existed -and $optStopNew -and $cur.status -eq 'Running') { [void]$diff.Add("service exists and is running now but did not exist before") }
            elseif ($cur.existed) { return @{ matches = $true; diff = 'service did not exist before and exists now; this record does not own it (RemoveIfCreated and StopIfCreated are not set), so it is left alone' } }
        } else {
            if (-not $cur.existed) { [void]$diff.Add('service no longer exists') }
            else {
                if ([int]$cur.regStart -ne [int]$s.regStart) { [void]$diff.Add("start type is $($cur.startType), was $($s.startType)") }
                elseif ([int]$s.regStart -eq 2 -and [bool]$cur.delayed -ne [bool]$s.delayed) { [void]$diff.Add("delayed start is $($cur.delayed), was $($s.delayed)") }
                # the raw delayed-start value: absent, 0 and 1 are three different stored states (Manual services can carry the flag too)
                $rawNow = if ($null -eq $cur.delayedRaw) { 'absent' } else { [string][int]$cur.delayedRaw }
                $rawWas = if ($null -eq $s.delayedRaw) { 'absent' } else { [string][int]$s.delayedRaw }
                if ($rawNow -ne $rawWas) { [void]$diff.Add("stored delayed-start value is $rawNow, was $rawWas") }
                if ([string]$s.status -eq 'Running' -and [int]$s.regStart -ne 4 -and $cur.status -ne 'Running') { [void]$diff.Add('service is not running, was running') }
                if ($optStop -and [string]$s.status -eq 'Stopped' -and $cur.status -eq 'Running') { [void]$diff.Add('service is running, was stopped') }
                # every dependent that was running when the original was recorded must be running again (unless it is gone or disabled now)
                if ([string]$s.status -eq 'Running' -and [int]$s.regStart -ne 4) {
                    foreach ($d in @($s.runningDependents)) {
                        if (-not (_Svc_ValidName $d)) { continue }
                        $dk = _Svc_RegKey ([string]$d)
                        # a dependent that is gone, disabled or unreadable is NOT an exact match (its original cannot be put back); Restore reports it as needing the user
                        if (-not (Test-Path -LiteralPath $dk)) { [void]$diff.Add("dependent service $d no longer exists, was running"); continue }
                        $dp = Get-ItemProperty -LiteralPath $dk -ErrorAction SilentlyContinue
                        if ($dp -and $null -ne $dp.Start -and [int]$dp.Start -eq 4) { [void]$diff.Add("dependent service $d is disabled now, was running"); continue }
                        $dsv = Get-Service -Name ([string]$d) -ErrorAction SilentlyContinue
                        if (-not $dsv) { [void]$diff.Add("dependent service $d cannot be read, was running") }
                        elseif ($dsv.Status -ne 'Running') { [void]$diff.Add("dependent service $d is not running, was running") }
                    }
                }
            }
        }
        return @{ matches = ($diff.Count -eq 0); diff = ($diff.ToArray() -join '; ') }
    } catch { return @{ matches = $false; diff = "could not read the service: $($_.Exception.Message)" } }
}

function _Svc_SetStart {
    param([string]$Name, [int]$RegStart, [bool]$Delayed)
    $tok = switch ($RegStart) { 2 { if ($Delayed) { 'delayed-auto' } else { 'auto' } } 3 { 'demand' } 4 { 'disabled' } default { $null } }
    if (-not $tok) { throw "start type $RegStart is not written by StreamReady (boot and system start types are never changed)" }
    $out = & sc.exe config $Name start= $tok 2>&1
    if ($LASTEXITCODE -ne 0) { throw "sc.exe config failed (exit code $LASTEXITCODE): $(($out | Out-String).Trim())" }
}

function Undo-Service-Restore {
    param($Item)
    $details = New-Object System.Collections.ArrayList
    $add = { param($part, $ok, $msg) [void]$details.Add(@{ part = $part; ok = $ok; message = $msg }) }
    try {
        $val = Undo-Service-Validate $Item
        if (-not $val.valid) { return @{ ok = $false; partial = $false; message = "Refused: the saved service record is not valid ($($val.reason))."; details = @() } }
        $s = $Item.state
        $name = [string]$s.name
        $optRemove = ($Item.params -and $Item.params.RemoveIfCreated -eq $true)
        $optStop = ($Item.params -and ($Item.params.StopIfWasStopped -eq $true -or $Item.params.StopIfCreated -eq $true))
        $cur = _Svc_Read $name

        if (-not $s.existed) {
            if (-not $cur.existed) { return @{ ok = $true; partial = $false; message = "Service $name did not exist before and does not exist now."; details = @() } }
            $optStopNew = ($Item.params -and $Item.params.StopIfCreated -eq $true)
            if (-not $optRemove) {
                if ($optStopNew -and $cur.status -eq 'Running') {
                    # the action that created this service (for example an optional component) removes it later; here it is only stopped
                    try { Stop-Service -Name $name -Force -ErrorAction Stop; (Get-Service -Name $name -ErrorAction Stop).WaitForStatus('Stopped', [TimeSpan]::FromSeconds(30)); return @{ ok = $true; partial = $false; message = "Service $name did not exist before; it was stopped (its component is removed by another step)."; details = @() } }
                    catch { return @{ ok = $false; partial = $false; message = "Service $name did not exist before and could not be stopped: $($_.Exception.Message)"; details = @() } }
                }
                return @{ ok = $true; partial = $true; message = "Service $name did not exist before but exists now. This record does not own it (no removal or stop was requested), so it was left alone."; details = @() }
            }
            try { if ($cur.status -eq 'Running') { Stop-Service -Name $name -Force -ErrorAction Stop } } catch { & $add 'stop' $false $_.Exception.Message }
            $out = & sc.exe delete $name 2>&1
            if ($LASTEXITCODE -ne 0) { return @{ ok = $false; partial = $false; message = "Could not remove service ${name}: $(($out | Out-String).Trim())"; details = @($details.ToArray()) } }
            return @{ ok = $true; partial = $false; message = "Service $name was removed (it was created after the original state was recorded)."; details = @($details.ToArray()) }
        }

        if (-not $cur.existed) {
            return @{ ok = $true; partial = $true; message = "Service $name no longer exists on this PC, so there is nothing to put back."; details = @() }
        }
        if ($s.imagePath -and $cur.imagePath -and ([string]$s.imagePath -ne [string]$cur.imagePath)) {
            & $add 'imagePath' $true 'the service program path has changed since it was recorded (for example by a Windows update); the start type is still restored'
        }

        # 1. start type and delayed flag
        $wantDelayed = (([int]$s.regStart -eq 2) -and ($s.delayedRaw -eq 1))
        $needCfg = ([int]$cur.regStart -ne [int]$s.regStart) -or (([int]$s.regStart -eq 2) -and ([bool]$cur.delayed -ne $wantDelayed))
        if ($needCfg) {
            try { _Svc_SetStart $name ([int]$s.regStart) $wantDelayed; & $add 'startType' $true "start type set to $($s.startType)$(if ($wantDelayed) { ' (delayed start)' })" }
            catch { & $add 'startType' $false $_.Exception.Message; return @{ ok = $false; partial = $false; message = "Could not put the start type of service $name back: $($_.Exception.Message)"; details = @($details.ToArray()) } }
        } else { & $add 'startType' $true 'start type was already the original' }

        # 1b. the raw delayed-start value: sc.exe writes 0/1 for Automatic; the original may have been absent, or carried by a Manual service
        $afterCfg = _Svc_Read $name
        $rawNow = if ($null -eq $afterCfg.delayedRaw) { 'absent' } else { [string][int]$afterCfg.delayedRaw }
        $rawWas = if ($null -eq $s.delayedRaw) { 'absent' } else { [string][int]$s.delayedRaw }
        if ($rawNow -ne $rawWas) {
            try {
                $rk = _Svc_RegKey $name
                if ($rawWas -eq 'absent') { Remove-ItemProperty -LiteralPath $rk -Name DelayedAutostart -ErrorAction Stop }
                else { Set-ItemProperty -LiteralPath $rk -Name DelayedAutostart -Value ([int]$s.delayedRaw) -Type DWord -ErrorAction Stop }
                & $add 'delayedRaw' $true "stored delayed-start value put back to $rawWas"
            } catch { & $add 'delayedRaw' $false "could not put the stored delayed-start value back: $($_.Exception.Message)" }
        }

        # 2. running state (never start a disabled service)
        $partial = $false
        $after = _Svc_Read $name
        if ([string]$s.status -eq 'Running' -and [int]$s.regStart -ne 4) {
            if ($after.status -ne 'Running') {
                try {
                    Start-Service -Name $name -ErrorAction Stop
                    (Get-Service -Name $name -ErrorAction Stop).WaitForStatus('Running', [TimeSpan]::FromSeconds(30))
                    & $add 'start' $true 'service started'
                } catch { $partial = $true; & $add 'start' $false "the start type was put back but the service could not be started now: $($_.Exception.Message)" }
            } else { & $add 'start' $true 'service was already running' }
            $live = @(_Svc_AllDependents $name)
            foreach ($d in @($s.runningDependents)) {
                if ($live -notcontains [string]$d) { $partial = $true; [void]$details.Add(@{ part = "dependent:$d"; ok = $false; status = 'UserActionRequired'; message = "the saved dependent service $d is not a dependent of $name on this PC any more, so it was not started" }); continue }
                $dkey = _Svc_RegKey ([string]$d)
                $dprop = if (Test-Path -LiteralPath $dkey) { Get-ItemProperty -LiteralPath $dkey -ErrorAction SilentlyContinue } else { $null }
                if (-not $dprop -or ($null -ne $dprop.Start -and [int]$dprop.Start -eq 4)) { $partial = $true; [void]$details.Add(@{ part = "dependent:$d"; ok = $false; status = 'UserActionRequired'; message = "dependent service $d is gone or disabled now, so it was not started" }); continue }
                try {
                    $ds = Get-Service -Name $d -ErrorAction Stop
                    if ($ds.Status -ne 'Running') { Start-Service -Name $d -ErrorAction Stop; $ds.WaitForStatus('Running', [TimeSpan]::FromSeconds(30)); & $add "dependent:$d" $true 'dependent service started' }
                } catch { $partial = $true; & $add "dependent:$d" $false "could not start dependent service ${d}: $($_.Exception.Message)" }
            }
        } elseif ($optStop -and [string]$s.status -eq 'Stopped' -and $after.status -eq 'Running') {
            try { Stop-Service -Name $name -Force -ErrorAction Stop; & $add 'stop' $true 'service stopped (it was stopped before)' } catch { $partial = $true; & $add 'stop' $false $_.Exception.Message }
        }

        $v = Undo-Service-Verify $Item
        if (-not $v.matches -and -not $partial) { $partial = $true; & $add 'verify' $false $v.diff }
        elseif (-not $v.matches) { & $add 'verify' $false $v.diff }
        $failedDetail = @($details.ToArray() | Where-Object { -not $_.ok }).Count
        $okAll = ($v.matches -and $failedDetail -eq 0)
        $msg = if ($okAll) { "Windows service $name was put back to what it was before." } elseif ($partial) { "Windows service $name was only partly put back: $($v.diff)" } else { "Windows service $name could not be fully put back: $($v.diff)" }
        return @{ ok = [bool]$okAll; partial = [bool]($partial -and -not $okAll); message = $msg; details = @($details.ToArray()) }
    } catch {
        return @{ ok = $false; partial = $false; message = "Could not put the service back: $($_.Exception.Message)"; details = @($details.ToArray()) }
    }
}

# ---- providers\UserRegistry.ps1 ----
# ==============================================================================
# Undo Provider: UserRegistry
# Scope: Interactive user registry settings under HKU:\<LogonUserSID>\...
# Handles elevation token mismatch by resolving interactive user SID and pruning empty created keys.
# Implements strict spec binding (UE-1-01) and typed verification.
# Windows PowerShell 5.1 compatible, dot-source safe, pure ASCII
# ==============================================================================

if (-not $script:UndoProviders) { $script:UndoProviders = @{} }
$script:UndoProviders['UserRegistry'] = @{
    Capture  = 'Undo-UserRegistry-Capture'
    Restore  = 'Undo-UserRegistry-Restore'
    Verify   = 'Undo-UserRegistry-Verify'
    Describe = 'Undo-UserRegistry-Describe'
    Validate = 'Undo-UserRegistry-Validate'
    VerifySeesApply = $true; Version  = 2
}

function _UserRegistry_TestPath {
    param([string]$Path)
    if ([string]::IsNullOrWhiteSpace($Path)) { return @{ ok = $true; exists = $false; error = $null } }
    $local:ErrorActionPreference = 'Stop'
    $errBefore = $error.Count
    try {
        $exists = [bool](Test-Path -LiteralPath $Path -ErrorAction Stop)
        if ($error.Count -gt $errBefore) {
            $msg = if ($error.Count -gt 0 -and $error[0]) { $error[0].ToString() } else { "Error probing '$Path'" }
            return @{ ok = $false; exists = $false; error = $msg }
        }
        return @{ ok = $true; exists = $exists; error = $null }
    } catch {
        return @{ ok = $false; exists = $false; error = [string]$_.Exception.Message }
    }
}

function _UserRegistry_ConvertDataFromType {
    param($RawData, [string]$Type)
    if ($null -eq $RawData) { return $null }
    switch ($Type) {
        'DWord'       { return [int][long]$RawData }
        'QWord'       { return [long]$RawData }
        'Binary'      { return [Convert]::FromBase64String([string]$RawData) }
        'None'        { return [Convert]::FromBase64String([string]$RawData) }
        'MultiString' { return [string[]]@($RawData) }
        default       { return [string]$RawData }
    }
}

function _UserRegistry_DeleteValue {
    param([string]$KeyPath, [string]$ValueName)
    if ($KeyPath -match '^(HKLM|HKCU|HKU):\\(.*)$') {
        $hive = $Matches[1]
        $sub = $Matches[2]
        $baseKey = switch ($hive) {
            'HKLM' { [Microsoft.Win32.Registry]::LocalMachine }
            'HKCU' { [Microsoft.Win32.Registry]::CurrentUser }
            'HKU'  { [Microsoft.Win32.Registry]::Users }
        }
        $rk = $baseKey.OpenSubKey($sub, $true)
        if ($rk) {
            try {
                $targetVal = if ($ValueName -eq '(default)') { '' } else { $ValueName }
                $rk.DeleteValue($targetVal, $false)
            } finally {
                $rk.Close()
            }
        }
    } else {
        $prop = if ([string]::IsNullOrEmpty($ValueName)) { '(default)' } else { $ValueName }
        Remove-ItemProperty -LiteralPath $KeyPath -Name $prop -ErrorAction SilentlyContinue
    }
}

function _UserRegistry_SetNoneValue {
    param([string]$KeyPath, [string]$ValName, [byte[]]$Bytes)
    if ($KeyPath -match '^HKLM:\\(.*)$') {
        $hive = [Microsoft.Win32.Registry]::LocalMachine
        $sub = $Matches[1]
    } elseif ($KeyPath -match '^HKCU:\\(.*)$') {
        $hive = [Microsoft.Win32.Registry]::CurrentUser
        $sub = $Matches[1]
    } elseif ($KeyPath -match '^HKU:\\([^\\]+)\\(.*)$') {
        $hive = [Microsoft.Win32.Registry]::Users
        $sub = "$($Matches[1])\$($Matches[2])"
    } else {
        throw "Unsupported registry path: $KeyPath"
    }
    $sk = $hive.CreateSubKey($sub)
    try {
        $targetVal = if ($ValName -eq '(default)') { '' } else { $ValName }
        $sk.SetValue($targetVal, $Bytes, [Microsoft.Win32.RegistryValueKind]::None)
    } finally {
        $sk.Close()
    }
}

function _UserRegistry_FindCreatedRoot {
    param([string]$KeyPath)
    $cur = $KeyPath
    $root = $KeyPath
    while ($true) {
        $parent = Split-Path -Path $cur -Parent
        if (-not $parent) { break }
        $tpParent = _UserRegistry_TestPath $parent
        if (-not $tpParent.ok -or $tpParent.exists) { break }
        $root = $parent
        $cur = $parent
    }
    return $root
}

function _UserRegistry_RemoveEmptyCreatedKeys {
    param([string]$KeyPath, [string]$RootPath)
    $cur = $KeyPath
    while ($true) {
        $tpCur = _UserRegistry_TestPath $cur
        if ($tpCur.ok -and $tpCur.exists) {
            try {
                $k = Get-Item -LiteralPath $cur -ErrorAction Stop
                if ($k) {
                    # Stop if key has values or subkeys
                    if (@($k.GetValueNames()).Count -gt 0 -or @($k.GetSubKeyNames()).Count -gt 0) { break }
                    Remove-Item -LiteralPath $cur -ErrorAction Stop
                }
            } catch {
                break
            }
        }
        if ($cur -eq $RootPath) { break }
        $cur = Split-Path -Path $cur -Parent
        if (-not $cur) { break }
    }
}

function _UserRegistry_IsSidValid {
    param([string]$Sid)
    if ([string]::IsNullOrWhiteSpace($Sid)) { return $false }
    return ($Sid -match '^S-1-\d+(-\d+)+$')
}

function _UserRegistry_ResolveSid {
    param([string]$ExplicitSid)
    if (-not [string]::IsNullOrEmpty($ExplicitSid)) { return $ExplicitSid }
    if (-not [string]::IsNullOrEmpty($script:LogonUserSID)) { return $script:LogonUserSID }

    try {
        $user = (Get-CimInstance Win32_ComputerSystem -ErrorAction SilentlyContinue).UserName
        if ($user) {
            $ntAccount = New-Object Security.Principal.NTAccount($user)
            return $ntAccount.Translate([Security.Principal.SecurityIdentifier]).Value
        }
    } catch {}

    try {
        return [System.Security.Principal.WindowsIdentity]::GetCurrent().User.Value
    } catch {
        return $null
    }
}

function Undo-UserRegistry-Validate {
    param([hashtable]$Item)
    if (-not $Item) { return @{ valid = $false; reason = 'Item record is null' } }
    if ($Item.type -ne 'UserRegistry') { return @{ valid = $false; reason = "Type mismatch: expected UserRegistry, got '$($Item.type)'" } }
    if (-not $Item.params) { return @{ valid = $false; reason = 'Missing spec params' } }
    if ([string]::IsNullOrEmpty($Item.params.Name)) { return @{ valid = $false; reason = 'Missing spec params.Name' } }
    if (-not $Item.state) { return @{ valid = $false; reason = 'Item state is missing' } }

    $st = $Item.state
    # UE-1-01: Name and SubPath must equal immutable spec params
    if ([string]$st.name -ne [string]$Item.params.Name) {
        return @{ valid = $false; reason = "Refused: state.name '$($st.name)' does not match spec params.Name '$($Item.params.Name)'" }
    }
    if ([string]$st.subPath -ne [string]$Item.params.SubPath) {
        return @{ valid = $false; reason = "Refused: state.subPath '$($st.subPath)' does not match spec params.SubPath '$($Item.params.SubPath)'" }
    }

    if ($Item.params.HiveOverride) {
        $expOverride = [string]$Item.params.HiveOverride
        if ([string]$st.hiveOverride -ne $expOverride) {
            return @{ valid = $false; reason = "Refused: state.hiveOverride does not match spec params.HiveOverride" }
        }
        if ($expOverride -notmatch '^HK(LM|CU|U):\\') {
            return @{ valid = $false; reason = "Refused: HiveOverride must start with HKLM, HKCU, or HKU" }
        }
        $expTargetKey = if ($Item.params.SubPath) { "$expOverride\$([string]$Item.params.SubPath)" } else { $expOverride }
        if ([string]$st.targetKey -ne $expTargetKey) {
            return @{ valid = $false; reason = "Refused: state.targetKey does not match recomputed path from spec" }
        }
    } else {
        if ([string]::IsNullOrEmpty($Item.params.SubPath)) {
            return @{ valid = $false; reason = 'Missing spec params.SubPath' }
        }

        # UE-R2-2-01: Validate state.userSid and targetKey format: must be HKU:\<SID>\<SubPath>
        if ([string]::IsNullOrEmpty($st.userSid)) {
            return @{ valid = $false; reason = 'Missing state.userSid' }
        }
        if (-not (_UserRegistry_IsSidValid ([string]$st.userSid))) {
            return @{ valid = $false; reason = "Refused: invalid SID format in state.userSid '$($st.userSid)'" }
        }
        if ($Item.params.UserSid -and [string]$st.userSid -ne [string]$Item.params.UserSid) {
            return @{ valid = $false; reason = "Refused: state.userSid '$($st.userSid)' does not match spec params.UserSid '$($Item.params.UserSid)'" }
        }

        if ([string]$st.targetKey -notmatch '^HKU:\\([^\\]+)\\(.*)$') {
            return @{ valid = $false; reason = "Refused: state.targetKey must be in HKU:\<SID>\<SubPath> format" }
        }
        $sidPart = $Matches[1]
        $subPart = $Matches[2]
        if (-not (_UserRegistry_IsSidValid $sidPart)) {
            return @{ valid = $false; reason = "Refused: invalid SID format in state.targetKey '$sidPart'" }
        }
        if ([string]$st.userSid -ne $sidPart) {
            return @{ valid = $false; reason = "Refused: state.userSid '$($st.userSid)' does not match targetKey SID '$sidPart'" }
        }
        if ($subPart -ne [string]$Item.params.SubPath) {
            return @{ valid = $false; reason = "Refused: subpath in targetKey '$subPart' does not match spec params.SubPath '$($Item.params.SubPath)'" }
        }
        if ([string]$st.targetKey -ne "HKU:\$sidPart\$([string]$Item.params.SubPath)") {
            return @{ valid = $false; reason = "Refused: state.targetKey does not match recomputed path from spec" }
        }
    }

    # Verify createdRoot containment if present
    if ($st.createdRoot) {
        $cRoot = [string]$st.createdRoot
        $tKey = [string]$st.targetKey
        if (-not $Item.params.HiveOverride) {
            $baseUserRoot = "HKU:\$sidPart"
            if ($cRoot -eq $baseUserRoot -or $cRoot -eq 'HKU:\' -or $cRoot -eq 'HKU:') {
                return @{ valid = $false; reason = "Refused: createdRoot cannot be the user root or HKU drive" }
            }
            if (-not $cRoot.StartsWith("$baseUserRoot\", [System.StringComparison]::OrdinalIgnoreCase)) {
                return @{ valid = $false; reason = "Refused: createdRoot '$cRoot' is not within user profile '$baseUserRoot'" }
            }
        }
        if ($tKey -ne $cRoot -and -not $tKey.StartsWith("$cRoot\", [System.StringComparison]::OrdinalIgnoreCase)) {
            return @{ valid = $false; reason = "Refused: createdRoot '$cRoot' is not an ancestor of '$tKey'" }
        }
    }

    if ($st.valueExisted) {
        if ($st.type -notin @('String', 'ExpandString', 'DWord', 'QWord', 'Binary', 'MultiString', 'None')) {
            return @{ valid = $false; reason = "Invalid registry data type '$($st.type)'" }
        }
    }

    return @{ valid = $true; reason = $null }
}

function Undo-UserRegistry-Capture {
    param([hashtable]$Params)
    try {
        if (-not $Params) { throw 'Params hashtable is required' }
        $subPath = [string]$Params.SubPath
        $name = [string]$Params.Name
        if ([string]::IsNullOrEmpty($name)) { throw 'Parameter Name is required' }

        $targetKey = $null
        $sid = $null
        $hiveOverride = $null

        if ($Params.HiveOverride) {
            $hiveOverride = [string]$Params.HiveOverride
            $targetKey = if ($subPath) { "$hiveOverride\$subPath" } else { $hiveOverride }
        } else {
            if ([string]::IsNullOrEmpty($subPath)) { throw 'Parameter SubPath is required when HiveOverride is not specified' }
            $sid = _UserRegistry_ResolveSid $Params.UserSid
            if (-not $sid) { throw 'Could not resolve logged-in user SID' }

            # Ensure HKU: PSDrive exists
            if (-not (Get-PSDrive HKU -ErrorAction SilentlyContinue)) {
                New-PSDrive -Name HKU -PSProvider Registry -Root HKEY_USERS -ErrorAction Stop | Out-Null
            }
            $targetKey = "HKU:\$sid\$subPath"
        }

        $tp = _UserRegistry_TestPath $targetKey
        if (-not $tp.ok) {
            throw "Error probing registry key '$targetKey': $($tp.error)"
        }
        $keyExisted = $tp.exists
        $createdRoot = $null
        $valExisted = $false
        $type = $null
        $data = $null

        if (-not $keyExisted) {
            $createdRoot = _UserRegistry_FindCreatedRoot $targetKey
        } else {
            $k = Get-Item -LiteralPath $targetKey -ErrorAction Stop
            if (@($k.GetValueNames()) -contains $name) {
                $valExisted = $true
                $kind = $k.GetValueKind($name)
                $type = [string]$kind
                $v = $k.GetValue($name, $null, [Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames)
                $data = if ($kind -eq [Microsoft.Win32.RegistryValueKind]::Binary -or $kind -eq [Microsoft.Win32.RegistryValueKind]::None) {
                    [Convert]::ToBase64String([byte[]]$v)
                } else {
                    $v
                }
            }
        }

        return @{
            type        = 'UserRegistry'
            v           = 2
            params      = $Params
            state       = @{
                subPath      = $subPath
                name         = $name
                targetKey    = $targetKey
                userSid      = $sid
                hiveOverride = $hiveOverride
                keyExisted   = $keyExisted
                createdRoot  = $createdRoot
                valueExisted = $valExisted
                type         = $type
                data         = $data
            }
            ok          = $true
            error       = $null
            capturedAt  = (Get-Date).ToUniversalTime().ToString('o')
        }
    } catch {
        return @{
            type        = 'UserRegistry'
            v           = 2
            params      = $Params
            state       = $null
            ok          = $false
            error       = [string]$_.Exception.Message
            capturedAt  = (Get-Date).ToUniversalTime().ToString('o')
        }
    }
}

function Undo-UserRegistry-Restore {
    param([hashtable]$Item)
    try {
        $val = Undo-UserRegistry-Validate -Item $Item
        if (-not $val.valid) {
            return @{ ok = $false; partial = $false; message = "Validation failed: $($val.reason)"; details = @() }
        }

        # UE-1-01 & UE-R2-2-01: Recompute target path from validated spec params and live user
        $targetKey = $null
        if ($Item.params.HiveOverride) {
            $subPath = [string]$Item.params.SubPath
            $hOverride = [string]$Item.params.HiveOverride
            $targetKey = if ($subPath) { "$hOverride\$subPath" } else { $hOverride }
        } else {
            $liveSid = _UserRegistry_ResolveSid $Item.params.UserSid
            if (-not $liveSid) {
                return @{ ok = $false; partial = $false; message = "Could not resolve live logged-on user SID"; details = @() }
            }
            if ($liveSid -ne [string]$Item.state.userSid) {
                return @{ ok = $false; partial = $false; message = "Refused: live logged-on user SID '$liveSid' differs from captured user SID '$($Item.state.userSid)'"; details = @() }
            }
            if (-not (Get-PSDrive HKU -ErrorAction SilentlyContinue)) {
                New-PSDrive -Name HKU -PSProvider Registry -Root HKEY_USERS -ErrorAction Stop | Out-Null
            }
            $tpHive = _UserRegistry_TestPath "HKU:\$liveSid"
            if (-not $tpHive.ok) {
                return @{ ok = $false; partial = $false; message = "Error probing user hive 'HKU:\$liveSid': $($tpHive.error)"; details = @() }
            }
            if (-not $tpHive.exists) {
                return @{ ok = $false; partial = $false; message = "Refused: user hive 'HKU:\$liveSid' is not loaded"; details = @() }
            }
            $targetKey = "HKU:\$liveSid\$([string]$Item.params.SubPath)"
        }
        $name = [string]$Item.params.Name
        $st = $Item.state
        $details = [System.Collections.Generic.List[hashtable]]::new()

        # Ensure HKU: drive if target starts with HKU:
        if ($targetKey -match '^HKU:\\' -and -not (Get-PSDrive HKU -ErrorAction SilentlyContinue)) {
            New-PSDrive -Name HKU -PSProvider Registry -Root HKEY_USERS -ErrorAction Stop | Out-Null
        }

        $tpTarget = _UserRegistry_TestPath $targetKey
        if (-not $tpTarget.ok) {
            return @{ ok = $false; partial = $false; message = "Error probing target key '$targetKey': $($tpTarget.error)"; details = @() }
        }

        if ($st.valueExisted) {
            if (-not $tpTarget.exists) {
                New-Item -Path $targetKey -Force -ErrorAction Stop | Out-Null
            }
            $typedData = _UserRegistry_ConvertDataFromType $st.data $st.type
            if ($st.type -eq 'None') {
                $bytes = if ($typedData) { [byte[]]$typedData } else { [byte[]]@() }
                _UserRegistry_SetNoneValue $targetKey $name $bytes
            } else {
                Set-ItemProperty -LiteralPath $targetKey -Name $name -Value $typedData -Type $st.type -ErrorAction Stop
            }
            $details.Add(@{
                targetKey = $targetKey
                name      = $name
                ok        = $true
                action    = 'restored_value'
                message   = "Restored value '$name' ($($st.type))"
            })
        } else {
            if ($tpTarget.exists) {
                $k = Get-Item -LiteralPath $targetKey -ErrorAction Stop
                if (@($k.GetValueNames()) -contains $name) {
                    _UserRegistry_DeleteValue $targetKey $name
                    $details.Add(@{
                        targetKey = $targetKey
                        name      = $name
                        ok        = $true
                        action    = 'deleted_value'
                        message   = "Deleted created property '$name'"
                    })
                } else {
                    $details.Add(@{
                        targetKey = $targetKey
                        name      = $name
                        ok        = $true
                        action    = 'already_absent'
                        message   = "Property '$name' was already absent"
                    })
                }
            } else {
                $details.Add(@{
                    targetKey = $targetKey
                    name      = $name
                    ok        = $true
                    action    = 'already_absent'
                    message   = "Property '$name' was already absent"
                })
            }
            # Prune empty keys if key was created by Apply
            if (-not $st.keyExisted -and $st.createdRoot) {
                _UserRegistry_RemoveEmptyCreatedKeys $targetKey $st.createdRoot
                $details.Add(@{
                    targetKey   = $targetKey
                    createdRoot = $st.createdRoot
                    ok          = $true
                    action      = 'pruned_empty_keys'
                    message     = "Pruned empty created parent keys up to '$($st.createdRoot)'"
                })
            }
        }

        $ver = Undo-UserRegistry-Verify -Item $Item
        $msg = if ($ver.matches) {
            "User registry property '$name' restored successfully."
        } else {
            "User registry property '$name' restore completed but verification reported: $($ver.diff)"
        }

        return @{
            ok      = $ver.matches
            partial = (-not $ver.matches)
            message = $msg
            details = @($details)
        }
    } catch {
        return @{
            ok      = $false
            partial = $false
            message = "Unexpected error during restore: $($_.Exception.Message)"
            details = @()
        }
    }
}

function Undo-UserRegistry-Verify {
    param([hashtable]$Item)
    try {
        $val = Undo-UserRegistry-Validate -Item $Item
        if (-not $val.valid) { return @{ matches = $false; diff = "Validation error: $($val.reason)" } }

        $targetKey = if ($Item.params.HiveOverride) {
            $subPath = [string]$Item.params.SubPath
            $hOverride = [string]$Item.params.HiveOverride
            if ($subPath) { "$hOverride\$subPath" } else { $hOverride }
        } else {
            $liveSid = _UserRegistry_ResolveSid $Item.params.UserSid
            if (-not $liveSid -or $liveSid -ne [string]$Item.state.userSid) {
                return @{ matches = $false; diff = "User SID mismatch: live '$liveSid' differs from captured '$($Item.state.userSid)'" }
            }
            $tpHive = _UserRegistry_TestPath "HKU:\$liveSid"
            if (-not $tpHive.ok) {
                return @{ matches = $false; diff = "Error probing user hive 'HKU:\$liveSid': $($tpHive.error)" }
            }
            if (-not $tpHive.exists) {
                return @{ matches = $false; diff = "User hive 'HKU:\$liveSid' is not loaded" }
            }
            "HKU:\$liveSid\$([string]$Item.params.SubPath)"
        }
        $name = [string]$Item.params.Name
        $st = $Item.state
        $tpKey = _UserRegistry_TestPath $targetKey
        if (-not $tpKey.ok) {
            return @{ matches = $false; diff = "Error probing target key '$targetKey': $($tpKey.error)" }
        }
        $keyExists = $tpKey.exists

        if ($st.valueExisted) {
            if (-not $keyExists) {
                return @{ matches = $false; diff = "Key '$targetKey' does not exist, expected value '$name' = '$($st.data)'" }
            }
            $k = Get-Item -LiteralPath $targetKey -ErrorAction Stop
            if (@($k.GetValueNames()) -notcontains $name) {
                return @{ matches = $false; diff = "Property '$name' is missing from '$targetKey', expected '$($st.data)'" }
            }
            $curKind = [string]$k.GetValueKind($name)
            if ($curKind -ne [string]$st.type) {
                return @{ matches = $false; diff = "Type mismatch on '$name': current '$curKind', expected '$($st.type)'" }
            }
            $curVal = $k.GetValue($name, $null, [Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames)
            $matchesVal = $false
            switch ($curKind) {
                'Binary' {
                    $curB64 = [Convert]::ToBase64String([byte[]]$curVal)
                    $matchesVal = [string]::Equals($curB64, [string]$st.data, [System.StringComparison]::Ordinal)
                }
                'None' {
                    $curB64 = [Convert]::ToBase64String([byte[]]$curVal)
                    $matchesVal = [string]::Equals($curB64, [string]$st.data, [System.StringComparison]::Ordinal)
                }
                'MultiString' {
                    $curArr = [string[]]@($curVal)
                    $expArr = [string[]]@($st.data)
                    if ($curArr.Length -eq $expArr.Length) {
                        $matchesVal = $true
                        for ($i = 0; $i -lt $curArr.Length; $i++) {
                            if (-not ($curArr[$i] -ceq $expArr[$i])) {
                                $matchesVal = $false
                                break
                            }
                        }
                    }
                }
                'DWord' {
                    $matchesVal = ([long]$curVal -eq [long]$st.data)
                }
                'QWord' {
                    $matchesVal = ([long]$curVal -eq [long]$st.data)
                }
                default {
                    $matchesVal = [string]::Equals([string]$curVal, [string]$st.data, [System.StringComparison]::Ordinal)
                }
            }
            if (-not $matchesVal) {
                return @{ matches = $false; diff = "Property '$name' = '$curVal', expected '$($st.data)'" }
            }
            return @{ matches = $true; diff = 'State matches original exactly.' }
        } else {
            if ($keyExists) {
                $k = Get-Item -LiteralPath $targetKey -ErrorAction Stop
                if (@($k.GetValueNames()) -contains $name) {
                    $curVal = $k.GetValue($name, $null, [Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames)
                    return @{ matches = $false; diff = "Property '$name' exists with value '$curVal', expected absent" }
                }
            }
            return @{ matches = $true; diff = 'State matches original exactly.' }
        }
    } catch {
        return @{ matches = $false; diff = "Verify failed: $($_.Exception.Message)" }
    }
}

function Undo-UserRegistry-Describe {
    param([hashtable]$Item)
    if (-not $Item -or -not $Item.state) { return 'User registry setting: no details available.' }
    $st = $Item.state
    $name = if ($Item.params -and $Item.params.Name) { $Item.params.Name } else { $st.name }
    $subPath = if ($Item.params -and $Item.params.SubPath) { $Item.params.SubPath } else { $st.subPath }
    $status = if ($st.valueExisted) { "original value '$($st.data)' ($($st.type))" } else { "originally absent" }
    return "User registry value '$name' under '$subPath': $status recorded."
}

# ---- providers\WindowsFeature.ps1 ----
# StreamReady undo engine - provider: WindowsFeature (Windows optional features and Windows capabilities)
# Plain function definitions plus one registration. Dot-source safe. ASCII only. Shared with the group D tools
# (Install WSL, Hyper-V, Sandbox, .NET, NFS, legacy media, OpenSSH).
#
# Params (hashtable):
#   Kind    'Feature' (default) or 'Capability'
#   Names   names or wildcard patterns, for example @('Microsoft-Hyper-V*') or @('OpenSSH.Server~~~~0.0.1.0').
#           Patterns are resolved ONCE, at capture time, and the resolved names are stored.
# State:   kind, items (name -> state). Feature states: Enabled, Disabled, DisabledWithPayloadRemoved, EnablePending,
#          DisablePending, Unknown. Capability states: Installed, NotPresent, Staged, Unknown.
# Capture REFUSES items that are not settled (EnablePending, DisablePending, Unknown): their earlier state could not be recreated
# after Windows finishes. States are compared exactly: Disabled and DisabledWithPayloadRemoved are different, Staged and NotPresent
# are different. A "payload removed" original is restored with Disable -Remove; a state that needs a download to recreate
# (payload present again after it was removed, or Staged) is reported as not restorable instead of being treated as equal.
# Restore moves every captured item back to its captured state (enable what was enabled before, disable what was disabled
# before), parents before children when enabling and children before parents when disabling (known parent table first, name
# convention second), with up to 3 passes.
# It reports "restart needed" when anything changed. Nothing is installed from the internet by this provider except what
# Windows itself fetches for a capability (reported plainly if that fails, for example when offline).
#
# A test can replace the real backend by setting $script:UndoWindowsFeatureBackend (a hashtable of scriptblocks:
# ListFeatures, SetFeature, ListCapabilities, SetCapability).

if ($null -eq $script:UndoProviders) { $script:UndoProviders = @{} }
$script:UndoProviders['WindowsFeature'] = @{ Capture = 'Undo-WindowsFeature-Capture'; Restore = 'Undo-WindowsFeature-Restore'; Verify = 'Undo-WindowsFeature-Verify'; Describe = 'Undo-WindowsFeature-Describe'; Validate = 'Undo-WindowsFeature-Validate'; VerifySeesApply = $true; Version = 1 }

function _WF_Now { return (Get-Date).ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ssZ') }
function _WF_ValidName { param($N) return ([string]$N -match '^[A-Za-z0-9][A-Za-z0-9.\-~_*?]{0,127}$') }
function _WF_ValidResolved { param($N) return ([string]$N -match '^[A-Za-z0-9][A-Za-z0-9.\-~_]{0,127}$') }
function _WF_FeatureStates { return @('Enabled', 'Disabled', 'DisabledWithPayloadRemoved', 'EnablePending', 'DisablePending', 'Unknown') }
function _WF_CapStates { return @('Installed', 'NotPresent', 'Staged', 'Unknown') }
function _WF_Kind { param($P) if ($P -and $P.Kind) { return [string]$P.Kind } return 'Feature' }

function _WF_Backend {
    if ($script:UndoWindowsFeatureBackend) { return $script:UndoWindowsFeatureBackend }
    return @{
        ListFeatures = {
            @(Get-WindowsOptionalFeature -Online -ErrorAction Stop | ForEach-Object { @{ name = [string]$_.FeatureName; state = [string]$_.State } })
        }
        # one named feature (about 1 second; the full list takes about 17 seconds on this PC); $null when Windows does not list it
        GetFeature = {
            param($name)
            $f = Get-WindowsOptionalFeature -Online -FeatureName $name -ErrorAction Stop
            if ($f) { return @{ name = [string]$f.FeatureName; state = [string]$f.State } }
            return $null
        }
        SetFeature = {
            param($name, $want)
            if ($want -eq 'Enabled') { $r = Enable-WindowsOptionalFeature -Online -FeatureName $name -NoRestart -ErrorAction Stop }
            elseif ($want -eq 'DisabledWithPayloadRemoved') { $r = Disable-WindowsOptionalFeature -Online -FeatureName $name -Remove -NoRestart -ErrorAction Stop }
            else { $r = Disable-WindowsOptionalFeature -Online -FeatureName $name -NoRestart -ErrorAction Stop }
            return @{ restartNeeded = [bool]($r -and $r.RestartNeeded) }
        }
        ListCapabilities = {
            param($pattern)
            @(Get-WindowsCapability -Online -ErrorAction Stop | Where-Object { $_.Name -like $pattern } | ForEach-Object { @{ name = [string]$_.Name; state = [string]$_.State } })
        }
        SetCapability = {
            param($name, $want)
            if ($want -eq 'Installed') { $r = Add-WindowsCapability -Online -Name $name -ErrorAction Stop } else { $r = Remove-WindowsCapability -Online -Name $name -ErrorAction Stop }
            return @{ restartNeeded = [bool]($r -and $r.RestartNeeded) }
        }
    }
}

# States are compared exactly (no merging of Disabled with DisabledWithPayloadRemoved or NotPresent with Staged).
function _WF_NormState {
    param([string]$S)
    return $S
}

# Known parent of each optional feature StreamReady touches (Windows gives no hierarchy). Used only to order the work.
function _WF_ParentTable {
    return @{
        'Microsoft-Hyper-V'                       = 'Microsoft-Hyper-V-All'
        'Microsoft-Hyper-V-Tools-All'             = 'Microsoft-Hyper-V-All'
        'Microsoft-Hyper-V-Hypervisor'            = 'Microsoft-Hyper-V'
        'Microsoft-Hyper-V-Services'              = 'Microsoft-Hyper-V'
        'Microsoft-Hyper-V-Management-Clients'    = 'Microsoft-Hyper-V-Tools-All'
        'Microsoft-Hyper-V-Management-PowerShell' = 'Microsoft-Hyper-V-Tools-All'
        'ClientForNFS-Infrastructure'             = 'ServicesForNFS-ClientOnly'
        'NFS-Administration'                      = 'ServicesForNFS-ClientOnly'
        'DirectPlay'                              = 'LegacyComponents'
        'WindowsMediaPlayer'                      = 'MediaPlayback'
        'Containers-DisposableClientVM'           = 'VirtualMachinePlatform'
    }
}
function _WF_Depth {
    param([string]$Name)
    $t = _WF_ParentTable
    $d = 0; $n = $Name
    while ($t.ContainsKey($n) -and $d -lt 10) { $d++; $n = $t[$n] }
    return $d
}

function _WF_Pairs {
    param($E)
    $o = @()
    if ($E -is [System.Collections.IDictionary]) { foreach ($k in $E.Keys) { $o += , @{ Name = [string]$k; Value = [string]$E[$k] } } }
    elseif ($null -ne $E) { foreach ($p in $E.PSObject.Properties) { $o += , @{ Name = [string]$p.Name; Value = [string]$p.Value } } }
    return $o
}

# current states for the names in a record: name -> state ('Missing' when Windows does not list it)
function _WF_CurrentStates {
    param($B, [string]$Kind, $Names)
    $cur = @{}
    if ($Kind -eq 'Capability') {
        foreach ($n in $Names) {
            $hit = @(& $B.ListCapabilities $n | Where-Object { $_.name -eq $n })
            $cur[$n] = $(if ($hit.Count -gt 0) { [string]$hit[0].state } else { 'Missing' })
        }
    } else {
        $all = $null
        foreach ($n in $Names) {
            $hit = $null; $asked = $false
            if ($B.ContainsKey('GetFeature')) {
                try { $hit = & $B.GetFeature $n; $asked = $true } catch { $asked = $false }
            }
            if ($asked) { $cur[$n] = $(if ($hit) { [string]$hit.state } else { 'Missing' }); continue }
            if ($null -eq $all) { $all = @{}; foreach ($f in @(& $B.ListFeatures)) { $all[[string]$f.name] = [string]$f.state } }
            $cur[$n] = $(if ($all.ContainsKey($n)) { $all[$n] } else { 'Missing' })
        }
    }
    return $cur
}

function Undo-WindowsFeature-Capture {
    param($Params)
    $res = @{ type = 'WindowsFeature'; v = 1; params = $Params; state = $null; ok = $false; error = $null; capturedAt = (_WF_Now) }
    try {
        if ($null -eq $Params) { throw 'no parameters' }
        $kind = _WF_Kind $Params
        if ($kind -notin @('Feature', 'Capability')) { throw "kind '$kind' is not supported" }
        $pats = @($Params.Names | ForEach-Object { [string]$_ })
        if ($pats.Count -eq 0) { throw 'no names were given' }
        foreach ($p in $pats) { if (-not (_WF_ValidName $p)) { throw "name '$p' is not valid" } }
        $B = _WF_Backend
        $items = @{}
        if ($kind -eq 'Feature') {
            $wild = @($pats | Where-Object { $_ -match '[*?]' })
            $fast = ($wild.Count -eq 0 -and $B.ContainsKey('GetFeature'))
            if ($fast) {
                foreach ($p in $pats) {
                    try { $f = & $B.GetFeature $p } catch { $fast = $false; break }
                    if ($f) { $items[[string]$f.name] = [string]$f.state }
                }
                if (-not $fast) { $items = @{} }
            }
            if (-not $fast) {
                $all = @(& $B.ListFeatures)
                foreach ($f in $all) { foreach ($p in $pats) { if ([string]$f.name -like $p) { $items[[string]$f.name] = [string]$f.state } } }
            }
        } else {
            foreach ($p in $pats) { foreach ($c in @(& $B.ListCapabilities $p)) { $items[[string]$c.name] = [string]$c.state } }
        }
        foreach ($k in @($items.Keys)) {
            if (-not (_WF_ValidResolved $k)) { throw "the resolved name '$k' has characters that are not allowed" }
            $stable = if ($kind -eq 'Feature') { @('Enabled', 'Disabled', 'DisabledWithPayloadRemoved') } else { @('Installed', 'NotPresent', 'Staged') }
            if ($items[$k] -notin $stable) { throw "'$k' is in the state '$($items[$k])' (waiting for a restart or not readable). Restart Windows and try again, so the original state is settled and can be put back exactly." }
        }
        $res.state = @{ kind = $kind; items = $items; matched = $items.Count }
        $res.ok = $true
    } catch { $res.error = "Could not record the original Windows feature state: $($_.Exception.Message)" }
    return $res
}

function Undo-WindowsFeature-Validate {
    param($Item)
    try {
        if ($null -eq $Item -or [string]$Item.type -ne 'WindowsFeature') { return @{ valid = $false; reason = 'not a WindowsFeature record' } }
        $s = $Item.state
        if ($null -eq $s) { return @{ valid = $false; reason = 'no state' } }
        $kind = [string]$s.kind
        if ($kind -notin @('Feature', 'Capability') -or $kind -ne (_WF_Kind $Item.params)) { return @{ valid = $false; reason = 'kind is not valid or does not match the parameters' } }
        $pats = @($Item.params.Names | ForEach-Object { [string]$_ })
        $allowed = if ($kind -eq 'Feature') { @('Enabled', 'Disabled', 'DisabledWithPayloadRemoved') } else { @('Installed', 'NotPresent', 'Staged') }
        $n = 0
        foreach ($p in (_WF_Pairs $s.items)) {
            $n++
            if (-not (_WF_ValidResolved $p.Name)) { return @{ valid = $false; reason = "name '$($p.Name)' is not valid" } }
            $own = $false; foreach ($pat in $pats) { if ($p.Name -like $pat) { $own = $true } }
            if (-not $own) { return @{ valid = $false; reason = "'$($p.Name)' is not one of the items this tweak owns" } }
            if ($p.Value -notin $allowed) { return @{ valid = $false; reason = "state '$($p.Value)' is not valid" } }
        }
        if ($n -gt 500) { return @{ valid = $false; reason = 'too many items' } }
        return @{ valid = $true; reason = $null }
    } catch { return @{ valid = $false; reason = $_.Exception.Message } }
}

function Undo-WindowsFeature-Describe {
    param($Item)
    try {
        $pairs = @(_WF_Pairs $Item.state.items)
        $what = if ([string]$Item.state.kind -eq 'Capability') { 'Windows capability' } else { 'Windows features' }
        if ($pairs.Count -eq 0) { return "$what ($(@($Item.params.Names) -join ', ')): none found on this PC" }
        $show = @($pairs | Select-Object -First 4 | ForEach-Object { "$($_.Name): $($_.Value)" })
        $more = if ($pairs.Count -gt 4) { " and $($pairs.Count - 4) more" } else { '' }
        return "$what - " + ($show -join ', ') + $more
    } catch { return 'Windows features (record could not be read)' }
}

function Undo-WindowsFeature-Verify {
    param($Item)
    try {
        $B = _WF_Backend
        $kind = [string]$Item.state.kind
        $pairs = @(_WF_Pairs $Item.state.items)
        $cur = _WF_CurrentStates $B $kind @($pairs | ForEach-Object { $_.Name })
        $diff = New-Object System.Collections.ArrayList
        foreach ($p in $pairs) {
            $now = $cur[$p.Name]
            if ((_WF_NormState $now) -ne (_WF_NormState $p.Value)) { [void]$diff.Add("$($p.Name) is $now, was $($p.Value)") }
        }
        return @{ matches = ($diff.Count -eq 0); diff = ($diff.ToArray() -join '; ') }
    } catch { return @{ matches = $false; diff = "could not read the Windows feature state: $($_.Exception.Message)" } }
}

function _WF_Order {
    param($Names, [bool]$ParentsFirst)
    # No hierarchy is available from Windows, so use the convention: a name ending in -All is the parent, then shorter names
    $sorted = @($Names | Sort-Object @{ Expression = { _WF_Depth $_ } }, @{ Expression = { if ($_ -match '-All$') { 0 } else { 1 } } }, @{ Expression = { $_.Length } }, @{ Expression = { $_ } })
    if (-not $ParentsFirst) { [array]::Reverse($sorted) }
    return $sorted
}

function Undo-WindowsFeature-Restore {
    param($Item)
    $details = New-Object System.Collections.ArrayList
    $add = { param($part, $ok, $msg) [void]$details.Add(@{ part = $part; ok = $ok; message = $msg }) }
    $restart = $false
    try {
        $val = Undo-WindowsFeature-Validate $Item
        if (-not $val.valid) { return @{ ok = $false; partial = $false; message = "Refused: the saved Windows feature record is not valid ($($val.reason))."; details = @(); restartNeeded = $false } }
        $B = _WF_Backend
        $kind = [string]$Item.state.kind
        $want = @{}
        foreach ($p in (_WF_Pairs $Item.state.items)) { $want[$p.Name] = $p.Value }
        if ($want.Count -eq 0) { return @{ ok = $true; partial = $false; message = 'No Windows features of this kind were found when the original state was recorded, so there is nothing to put back.'; details = @(); restartNeeded = $false } }

        $pending = @{}
        $exact = @{}
        for ($pass = 1; $pass -le 3; $pass++) {
            $cur = _WF_CurrentStates $B $kind @($want.Keys)
            $todoOn = @(); $todoOff = @()
            foreach ($n in $want.Keys) {
                $w = [string]$want[$n]; $c = [string]$cur[$n]
                if ($c -eq 'Missing') { continue }
                if ($c -in @('EnablePending', 'DisablePending')) { $pending[$n] = $c; continue }
                if ($c -eq $w) { continue }
                if ($w -in @('Enabled', 'Installed')) { $todoOn += $n }
                elseif ($w -eq 'Disabled' -and $c -eq 'DisabledWithPayloadRemoved') { $exact[$n] = 'the files of this feature were removed since it was recorded, and Windows cannot mark them present again without downloading and enabling it'; continue }
                elseif ($w -in @('Disabled', 'NotPresent', 'DisabledWithPayloadRemoved', 'Staged')) { $todoOff += $n }
            }
            if ($todoOn.Count -eq 0 -and $todoOff.Count -eq 0) { break }
            $progress = $false
            # turn things off first (children before parents), then on (parents before children)
            foreach ($n in (_WF_Order $todoOff $false)) {
                try {
                    $offState = if ($want[$n] -eq 'DisabledWithPayloadRemoved') { 'DisabledWithPayloadRemoved' } else { 'Disabled' }
                    $r = if ($kind -eq 'Capability') { & $B.SetCapability $n 'NotPresent' } else { & $B.SetFeature $n $offState }
                    if ($r.restartNeeded) { $restart = $true }
                    $progress = $true; & $add $n $true 'turned off again (it was off before)'
                } catch { if ($pass -eq 3) { & $add $n $false "could not turn it off: $($_.Exception.Message)" } }
            }
            foreach ($n in (_WF_Order $todoOn $true)) {
                try {
                    $r = if ($kind -eq 'Capability') { & $B.SetCapability $n 'Installed' } else { & $B.SetFeature $n 'Enabled' }
                    if ($r.restartNeeded) { $restart = $true }
                    $progress = $true; & $add $n $true 'turned on again (it was on before)'
                } catch { if ($pass -eq 3) { & $add $n $false "could not turn it on: $($_.Exception.Message)" } }
            }
            if (-not $progress -and $pass -ge 2) { break }
        }
        if ($details.Count -gt 0) { $restart = $true }
        foreach ($n in $exact.Keys) { & $add $n $false $exact[$n] }
        foreach ($n in $pending.Keys) { & $add $n $false "is waiting for a restart ($($pending[$n])), restart the PC and then undo again" }

        $v = Undo-WindowsFeature-Verify $Item
        $anyFail = (@($details.ToArray() | Where-Object { -not $_.ok }).Count -gt 0)
        if ($v.matches -and -not $anyFail) {
            $m = if ($details.Count -eq 0) { 'The Windows features were already the way they were before, nothing to change.' } else { 'The Windows features were put back to what they were before. Restart your PC to finish.' }
            return @{ ok = $true; partial = $false; message = $m; details = @($details.ToArray()); restartNeeded = [bool]$restart }
        }
        $why = if ($v.diff) { $v.diff } else { 'see details' }
        $hint = if ($kind -eq 'Capability') { ' If a capability could not be added, Windows needs an internet connection to download it.' } else { ' If a feature could not be turned on, Windows may need to download its files; connect to the internet and try again.' }
        return @{ ok = $false; partial = $true; message = "The Windows features could not be fully put back: $why.$hint"; details = @($details.ToArray()); restartNeeded = [bool]$restart }
    } catch {
        return @{ ok = $false; partial = $false; message = "Could not put the Windows features back: $($_.Exception.Message)"; details = @($details.ToArray()); restartNeeded = $false }
    }
}

# ---- providers\WingetPackage.ps1 ----
# WingetPackage provider (group D). Params: Ids = array of winget package ids that the tool may install (for example
# 'REALiX.HWiNFO').
# What the engine itself installed is decided from TWO listings: before the action (Capture) and after it (PostApply, called by the
# core when the action finished). A package counts as "installed by StreamReady" only when winget did not list it before, lists it
# after, AND exactly one NEW Add/Remove Programs entry carries the name winget shows for that package and its version (identity recorded). Restore removes only such packages, only while they are still
# at the version seen right after the install, and says plainly when a package was found that was already on the PC. It never removes a
# program that was installed before the click, and a program winget did not know before is NOT assumed to be new.
# No network access of its own: it only runs winget, which the app already uses. Test hooks: $script:SRUndoWingetExe,
# $script:SRUndoArpRoots (registry roots that hold the Add/Remove Programs entries).

if (-not $script:UndoProviders) { $script:UndoProviders = @{} }
$script:UndoProviders['WingetPackage'] = @{ Capture = 'Undo-WingetPackage-Capture'; Restore = 'Undo-WingetPackage-Restore'; Verify = 'Undo-WingetPackage-Verify'; Describe = 'Undo-WingetPackage-Describe'; Validate = 'Undo-WingetPackage-Validate'; PostApply = 'Undo-WingetPackage-PostApply'; VerifySeesApply = $false; Version = 1 }

function _WingetPackage_Exe {
    if ($script:SRUndoWingetExe) { return $script:SRUndoWingetExe }
    $c = Get-Command winget -ErrorAction SilentlyContinue
    if ($c) { return $c.Source }
    return $null
}
function _WingetPackage_Installed {
    # returns @{ ok; available; map = @{ id = version }; error }
    $exe = _WingetPackage_Exe
    if (-not $exe) { return @{ ok = $true; available = $false; map = @{}; error = $null } }
    $tmp = Join-Path $env:TEMP "SRUndo-winget-$([guid]::NewGuid().ToString('N')).json"
    try {
        $null = & $exe export -o $tmp --include-versions --accept-source-agreements --disable-interactivity 2>&1
        if (-not (Test-Path -LiteralPath $tmp)) {
            # winget can fail to export when no source is configured; treat as "could not read" so the tool is not run blind
            return @{ ok = $false; available = $true; map = @{}; error = 'winget could not list the installed programs' }
        }
        $j = Get-Content -LiteralPath $tmp -Raw -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop
        $map = @{}
        foreach ($src in @($j.Sources)) { foreach ($p in @($src.Packages)) { if ($p.PackageIdentifier) { $map[[string]$p.PackageIdentifier] = [string]$p.Version } } }
        return @{ ok = $true; available = $true; map = $map; error = $null }
    } catch { return @{ ok = $false; available = $true; map = @{}; error = $_.Exception.Message } }
    finally { try { if (Test-Path -LiteralPath $tmp) { Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue } } catch {} }
}
function _WingetPackage_ArpRoots {
    if ($script:SRUndoArpRoots) { return @($script:SRUndoArpRoots) }
    return @('HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall', 'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall', 'HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall')
}
function _WingetPackage_Arp {
    # the Add/Remove Programs entries: key path -> "DisplayName|DisplayVersion". A root that cannot be read is an error, not "empty".
    $map = @{}
    foreach ($root in (_WingetPackage_ArpRoots)) {
        if (-not (Test-Path -LiteralPath $root)) { continue }
        foreach ($k in @(Get-ChildItem -LiteralPath $root -ErrorAction Stop)) {
            $dn = ''; $dv = ''
            $pb = ''
            try { $dn = [string]$k.GetValue('DisplayName'); $dv = [string]$k.GetValue('DisplayVersion'); $pb = [string]$k.GetValue('Publisher') } catch {}
            $map[$k.Name] = "$dn|$dv|$pb"
        }
    }
    return $map
}
function _WingetPackage_ListName {
    # the program name winget shows for one package id (the column before the id in "winget list --id <id> -e"); $null when it
    # cannot be read. The name is what links the package to its own Add/Remove Programs entry.
    param([string]$Id)
    $exe = _WingetPackage_Exe
    if (-not $exe) { return $null }
    try {
        $lines = @(& $exe list --id $Id -e --accept-source-agreements --disable-interactivity 2>&1)
        foreach ($ln in $lines) {
            $cols = @(([string]$ln).Trim() -split '\s{2,}')
            $ix = [array]::IndexOf($cols, $Id)
            if ($ix -ge 1) { return [string]$cols[$ix - 1] }
        }
    } catch {}
    return $null
}
function _WingetPackage_Ids { param($P) $ids = @(); if ($P -and $P.ContainsKey('Ids')) { $ids = @($P['Ids'] | ForEach-Object { [string]$_ } | Where-Object { $_ }) }; return $ids }
function Undo-WingetPackage-Capture {
    param([hashtable]$Params)
    $out = @{ type = 'WingetPackage'; v = 1; params = $Params; state = $null; ok = $false; error = $null; capturedAt = (Undo-Now) }
    try {
        $ids = _WingetPackage_Ids $Params
        $inst = _WingetPackage_Installed
        if (-not $inst.ok) { throw $inst.error }
        $pk = @()
        foreach ($id in $ids) {
            $was = $inst.map.ContainsKey($id)
            $pk += , @{ id = $id; installed = $was; version = $(if ($was) { [string]$inst.map[$id] } else { '' }) }
        }
        $arp = _WingetPackage_Arp
        $out.state = @{ available = $inst.available; packages = @($pk); arpBefore = @($arp.Keys | Sort-Object); installedByEngine = @(); afterVersions = @{}; postApplyDone = $false }
        $out.ok = $true
    } catch { $out.error = "could not list the installed programs: $($_.Exception.Message)" }
    return $out
}
function Undo-WingetPackage-PostApply {
    # called by the core after the action finished (also after a failed action, before anything is rolled back). A package counts as
    # installed by StreamReady only when ALL of this holds for that package: winget did not list it before, lists it now, and exactly
    # ONE Add/Remove Programs entry that did not exist before carries the program name winget shows for that package id and the
    # version winget reports. The identity of that entry (key, name, version, publisher) is recorded. Anything else is ambiguous:
    # it is recorded as such and Undo gives manual steps, never an uninstall. A failure to produce this evidence is returned as
    # ok = false so the core keeps the record as incomplete.
    param($Item)
    try {
        $st = $Item['state']
        $inst = _WingetPackage_Installed
        if (-not $inst.ok) { $st['installedByEngine'] = @(); $st['postApplyDone'] = $false; $st['postApplyError'] = $inst.error; return @{ ok = $false; message = "could not list the installed programs after the change: $($inst.error)" } }
        $arpNow = _WingetPackage_Arp
        $before = @($st['arpBefore'])
        $newKeys = @($arpNow.Keys | Where-Object { $before -notcontains $_ })
        $mine = @(); $after = @{}; $own = @{}; $amb = @(); $claimed = @{}
        foreach ($p in @($st['packages'])) {
            $id = [string]$p['id']
            if ($p['installed']) { continue }
            if (-not $inst.map.ContainsKey($id)) { continue }
            $ver = [string]$inst.map[$id]
            $nm = _WingetPackage_ListName $id
            $hit = @()
            if ($nm) { foreach ($k in $newKeys) { $f = ([string]$arpNow[$k]).Split('|'); if ($f[0] -ieq $nm -and ([string]$f[1] -eq $ver -or -not $ver)) { $hit += $k } } }
            if ($hit.Count -eq 1 -and -not $claimed.ContainsKey($hit[0])) {
                $claimed[$hit[0]] = $id
                $f = ([string]$arpNow[$hit[0]]).Split('|')
                $mine += $id; $after[$id] = $ver
                $own[$id] = @{ key = [string]$hit[0]; name = [string]$f[0]; version = [string]$f[1]; publisher = [string]$f[2] }
            } else { $amb += $id }
        }
        # a key claimed by two packages proves neither
        foreach ($id in @($mine)) { }
        if ($amb.Count -gt 0) { $st['ambiguous'] = ($amb -join ',') }
        $st['installedByEngine'] = @($mine); $st['afterVersions'] = $after; $st['ownership'] = $own; $st['newArpCount'] = $newKeys.Count; $st['postApplyDone'] = $true
        return @{ ok = $true }
    } catch { try { $Item['state']['postApplyDone'] = $false; $Item['state']['postApplyError'] = $_.Exception.Message } catch {}; return @{ ok = $false; message = $_.Exception.Message } }
}
function Undo-WingetPackage-Restore {
    param($Item)
    try {
        $st = ConvertTo-UndoPlain $Item['state']
        $exe = _WingetPackage_Exe
        $notes = @(); $bad = 0; $removed = 0; $manual = @()
        $inst = _WingetPackage_Installed
        if (-not $inst.ok) { return @{ ok = $false; partial = $false; message = "could not list the installed programs: $($inst.error)"; details = @() } }
        $arpNow = $null
        $mine = @($st['installedByEngine'])
        $evidence = ($st['postApplyDone'] -eq $true)
        foreach ($p in @($st['packages'])) {
            $id = [string]$p['id']
            $now = $inst.map.ContainsKey($id)
            if ($p['installed']) {
                if (-not $now) { $notes += "$id was installed before and is not now; reinstall it with winget if you want it"; $bad++ }
                elseif ([string]$inst.map[$id] -ne [string]$p['version']) { $notes += "$id was updated from $($p['version']) to $($inst.map[$id]); the old version cannot be put back automatically"; $bad++ }
                continue
            }
            if (-not $now) { continue }          # not installed before, not installed now: nothing to undo
            $why = $null
            if (-not $evidence) { $why = "StreamReady could not record what the change installed, so it cannot prove that $id was installed by it" }
            elseif ($mine -notcontains $id) { $why = "$id was not listed by winget before the click but is now; StreamReady cannot prove it installed it" }
            elseif ([string]$inst.map[$id] -ne [string]$st['afterVersions'][$id]) { $why = "$id changed version since it was installed ($($st['afterVersions'][$id]) -> $($inst.map[$id]))" }
            else {
                # the recorded Add/Remove Programs entry must still be the same program
                if ($null -eq $arpNow) { $arpNow = _WingetPackage_Arp }
                $o = $st['ownership'][$id]
                $cur = if ($o -and $arpNow.ContainsKey([string]$o['key'])) { ([string]$arpNow[[string]$o['key']]).Split('|') } else { $null }
                if (-not $o -or -not $cur -or $cur[0] -ne [string]$o['name'] -or $cur[1] -ne [string]$o['version'] -or $cur[2] -ne [string]$o['publisher']) { $why = "the program entry recorded for $id is not the same any more" }
            }
            if ($why) { $manual += $id; $notes += "$why, so it was NOT removed. If you installed it for this tool and want it gone, remove it yourself in Windows Settings, Apps"; continue }
            if (-not $exe) { $notes += "$id was installed by this step but winget is not available to remove it"; $bad++; continue }
            $null = & $exe uninstall --id $id -e --silent --accept-source-agreements --disable-interactivity 2>&1
            $code = $LASTEXITCODE
            $after = _WingetPackage_Installed
            if ($after.ok -and -not $after.map.ContainsKey($id)) { $removed++ }
            else { $notes += "$id could not be removed (winget code $code)"; $bad++ }
        }
        $msg = if ($notes.Count -gt 0) { $notes -join '; ' } elseif ($removed -gt 0) { "$removed program(s) installed by this step were removed; files they saved for you are kept" } else { 'nothing needed removing' }
        if ($manual.Count -gt 0) { return @{ ok = $false; partial = $true; message = $msg; details = @(@{ status = 'UserActionRequired'; ids = @($manual) }) } }
        return @{ ok = ($bad -eq 0); partial = ($bad -gt 0 -and $removed -gt 0); message = $msg; details = $notes }
    } catch { return @{ ok = $false; partial = $false; message = "programs: $($_.Exception.Message)"; details = @() } }
}
function Undo-WingetPackage-Verify {
    param($Item)
    try {
        $st = ConvertTo-UndoPlain $Item['state']
        $inst = _WingetPackage_Installed
        if (-not $inst.ok) { return @{ matches = $false; diff = "could not list the installed programs: $($inst.error)" } }
        $mine = @($st['installedByEngine'])
        $diffs = @()
        foreach ($p in @($st['packages'])) {
            $id = [string]$p['id']; $now = $inst.map.ContainsKey($id)
            if ($p['installed']) {
                if (-not $now) { $diffs += "$id is not installed, was installed" }
                elseif ([string]$inst.map[$id] -ne [string]$p['version']) { $diffs += "$id is version $($inst.map[$id]), was $($p['version'])" }
            }
            elseif ($now -and ($mine -contains $id)) { $diffs += "$id is installed (it was installed by this step)" }
            elseif ($now) { $diffs += "$id is installed now and was not before; StreamReady cannot prove who installed it, so the original is not confirmed" }
        }
        if ($diffs.Count -gt 0) { return @{ matches = $false; diff = ($diffs -join '; ') } }
        return @{ matches = $true; diff = '' }
    } catch { return @{ matches = $false; diff = "could not list the installed programs: $($_.Exception.Message)" } }
}
function Undo-WingetPackage-Describe {
    param($Item)
    try {
        $pk = @($Item['state']['packages'])
        if ($pk.Count -eq 0) { return 'Installed programs: none watched' }
        $parts = foreach ($p in $pk) { if ($p['installed']) { "$($p['id']) was installed ($($p['version']))" } else { "$($p['id']) was not installed" } }
        return 'Programs: ' + ($parts -join '; ')
    } catch { return 'Programs' }
}
function Undo-WingetPackage-Validate {
    param($Item)
    try {
        foreach ($p in @($Item['state']['packages'])) {
            if ([string]$p['id'] -notmatch '^[A-Za-z0-9][A-Za-z0-9._+-]{1,100}$') { return @{ valid = $false; reason = 'package id not allowed' } }
        }
        foreach ($id in (_WingetPackage_Ids $Item['params'])) {
            if ($id -notmatch '^[A-Za-z0-9][A-Za-z0-9._+-]{1,100}$') { return @{ valid = $false; reason = 'package id not allowed' } }
        }
        # what the engine installed must be a subset of what the tool may install
        $allowed = @(_WingetPackage_Ids $Item['params'])
        foreach ($id in @($Item['state']['installedByEngine'])) { if ($allowed -notcontains [string]$id) { return @{ valid = $false; reason = 'a program outside the tool list is marked as installed by StreamReady' } } }
        return @{ valid = $true; reason = $null }
    } catch { return @{ valid = $false; reason = $_.Exception.Message } }
}

# ---- specs\groupA.ps1 ----
# StreamReady undo engine - SPEC DATA for group A (services, power, memory, boot, environment). DATA ONLY: hashtable assignments.
# Source of truth for what is captured and restored: reviews\UNDO-SPEC-A.md.
#
# $script:UndoTweakSpecs[<tweak id>] = @{ Items = @( @{ Type = '<provider>'; Params = @{ ... } } ); Irreversible = @( @{ What; Why; BestRecovery } ) }
#   Items are captured in the order listed, BEFORE the Apply function runs, and restored in REVERSE order.
#   A Params value may be a scriptblock that is evaluated at capture time.
#
# The REGISTRY parts of these tweaks are ordinary Items of type 'Registry' (Params Key + Name) in the same Items list, so they are
# captured and restored by the engine like every other item (an earlier version kept them in a side table that nothing read).
# Test-GroupASpecs checks that every registry value the Apply functions write is covered by an Item.
# Every item here is STATIC (no scriptblock): the engine compares a saved record with this spec exactly, so a changed record
# can never ask a provider to touch anything that is not written here. Anything that needs a file (the boot store safety copy)
# is made by the provider's Prepare step inside the private record folder.

if ($null -eq $script:UndoTweakSpecs) { $script:UndoTweakSpecs = @{} }

