            Type   = 'RegistryTree'
            Params = @{
                Key = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Explorer\Desktop\NameSpace\{f874310e-b6b7-47dc-bc84-b9e6b38f5903}'
            }
        }
    )
    Irreversible = @(
        @{
            What         = 'Navigation pane item in currently open File Explorer windows'
            Why          = 'File Explorer caches desktop namespace items in memory'
            BestRecovery = 'Restart Windows Explorer or sign out for Home to reappear in navigation tree'
        }
    )
}

# ---- specs\groupD.ps1 ----
# Group D specs: which providers each immediate TOOL needs. Data plus a few small helper functions that only read UI state.
# Key = the control name of the tool (Btn...). One record per click (kind 'tool').
# Items are captured in this order and restored in REVERSE order.
# 'Allow' (optional, per item) = regular expressions that every param value of an item of that spec entry must match; the core
# checks them when a saved record is loaded, so a changed record file cannot point a tool at anything else.
# Tools with no entry (BtnReapplyDrifted, BtnFlushDns) have nothing to record: the first one goes through the tweak engine, the
# second changes no setting.

if (-not $script:UndoToolSpecs) { $script:UndoToolSpecs = @{} }
function _GD_WifiGuid {
    try {
        $n = Get-NetworkAdapterStatus
        if ($n.WifiAdapter) { return ([guid]$n.WifiAdapter.InterfaceGuid).ToString() }
    } catch {}
    return '00000000-0000-0000-0000-000000000000'
}
function _GD_WifiParams {
    # one params table for the Wi-Fi adapter, or NOTHING when there is no Wi-Fi adapter (then there is nothing to change)
    param([string]$Mode, [string]$Match, [string[]]$Fields)
    $g = _GD_WifiGuid
    if ($g -eq '00000000-0000-0000-0000-000000000000') { return @() }
    $h = @{ Mode = $Mode; InterfaceGuids = @($g) }
    if ($Match) { $h['DisplayMatch'] = $Match }
    if ($Fields) { $h['PowerFields'] = @($Fields) }
    return @($h)
}
function _GD_StartupParams {
    try {
        $sel = [string]$c['StartupList'].SelectedItem
        if ($sel -and $sel -notmatch 'No startup') {
            $n = $sel -replace '^\[.*?\] ', ''
            $hive = if ($sel -match '\[User\]') { 'HKCU' } else { 'HKLM' }
            return @(@{ Key = "$($hive):\Software\Microsoft\Windows\CurrentVersion\Run"; Name = $n })
        }
    } catch {}
    return @()
}
function _GD_IfeoParams {
    param([string[]]$Values)
    $out = @()
    foreach ($exe in @('steam.exe', 'EpicGamesLauncher.exe', 'Battle.net.exe', 'RiotClientServices.exe', 'EADesktop.exe')) {
        foreach ($v in $Values) { $out += , @{ Key = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\$exe\PerfOptions"; Name = $v } }
    }
    return $out
}
$script:UndoAppIdMap = [ordered]@{
    'ChkInstallChrome' = 'Google.Chrome'; 'ChkInstallFirefox' = 'Mozilla.Firefox'; 'ChkInstallBrave' = 'Brave.Brave'; 'ChkInstallDiscord' = 'Discord.Discord'
    'ChkInstallSlack' = 'SlackTechnologies.Slack'; 'ChkInstallZoom' = 'Zoom.Zoom'; 'ChkInstallOBS' = 'OBSProject.OBSStudio'; 'ChkInstallSteam' = 'Valve.Steam'
    'ChkInstall7zip' = '7zip.7zip'; 'ChkInstallVLC' = 'VideoLAN.VLC'; 'ChkInstallNotepad' = 'Notepad++.Notepad++'; 'ChkInstallVSCode' = 'Microsoft.VisualStudioCode'
    'ChkInstallGit' = 'Git.Git'; 'ChkInstallWinRAR' = 'RARLab.WinRAR'; 'ChkInstallStartAllBack' = 'StartIsBack.StartAllBack'; 'ChkInstallNilesoft' = 'Nilesoft.Shell'
    'ChkInstallTranslucentTB' = 'TranslucentTB.TranslucentTB'; 'ChkInstallMPC' = 'clsid2.mpc-hc'; 'ChkInstallOnlyOffice' = 'ONLYOFFICE.DesktopEditors'; 'ChkInstallHandbrake' = 'HandBrake.HandBrake'
}
function _GD_SelectedAppIds {
    $ids = @()
    foreach ($k in $script:UndoAppIdMap.Keys) { try { if ($c[$k] -and $c[$k].IsChecked) { $ids += $script:UndoAppIdMap[$k] } } catch {} }
    return $ids
}
function _GD_WuItems {
    $wu = 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate'
    $items = @()
    foreach ($n in 'DeferFeatureUpdates', 'DeferFeatureUpdatesPeriodInDays', 'DeferQualityUpdates', 'DeferQualityUpdatesPeriodInDays') { $items += , @{ Type = 'Registry'; Params = @{ Key = $wu; Name = $n } } }
    foreach ($n in 'NoAutoUpdate', 'AUOptions') { $items += , @{ Type = 'Registry'; Params = @{ Key = "$wu\AU"; Name = $n } } }
    $items += , @{ Type = 'Service'; Params = @{ Name = 'wuauserv'; StopIfWasStopped = $true } }
    return $items
}
