# A password stored in plain text in the registry (older versions did that) is never copied into StreamReady's records. If one exists the
# tool is blocked with a plain message, because Apply deletes it. Items are restored in reverse order: the stored password first; when it
# cannot be put back (it never is when one existed before) the two sign-in values are left as they are (SkipWhenManual), so Windows does not
# try to sign in with a password that is not the user's.
$script:UndoGuardMessage = 'A password for automatic sign-in is stored in plain text in the registry (Winlogon DefaultPassword). StreamReady does not copy passwords into its records and will not delete this one without a copy. Remove it yourself first (turn automatic sign-in off in Windows with netplwiz) and try again.'
$script:UndoToolSpecs['BtnSetupAutologin'] = @{
    Items = @(
        @{ Type = 'RegistryGuard'; Params = @{ Key = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Winlogon'; Name = 'DefaultPassword'; Message = $script:UndoGuardMessage } },
        @{ Type = 'Registry'; Params = @{ Key = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Winlogon'; Name = 'AutoAdminLogon' }; SwitchOffWhenManual = $true },
        @{ Type = 'Registry'; Params = @{ Key = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Winlogon'; Name = 'DefaultUsername' }; SkipWhenManual = $true },
        @{ Type = 'LsaSecret'; Params = @{ Name = 'DefaultPassword' } }
    )
    Irreversible = @( @{ Warn = $true; What = 'A password that was already stored for automatic sign-in'; Why = 'it is replaced and StreamReady does not keep a copy of any password, so Undo cannot give it back (it removes the new one if none existed before).'; BestRecovery = 'Enter the password again if you want the old automatic sign-in back.' } )
}
$script:UndoToolSpecs['BtnDisableAutologin'] = @{
    Items = @(
        @{ Type = 'RegistryGuard'; Params = @{ Key = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Winlogon'; Name = 'DefaultPassword'; Message = $script:UndoGuardMessage } },
        @{ Type = 'Registry'; Params = @{ Key = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Winlogon'; Name = 'AutoAdminLogon' }; SwitchOffWhenManual = $true },
        @{ Type = 'LsaSecret'; Params = @{ Name = 'DefaultPassword' } }
    )
    Irreversible = @( @{ Warn = $true; What = 'The stored sign-in password'; Why = 'it is deleted and StreamReady does not keep a copy of any password, so Undo cannot give it back.'; BestRecovery = 'To turn automatic sign-in back on, enter your password again with Turn On Automatic Login.' } )
}

