#region UndoEngine hooks BEGIN
if (-not $script:UndoSessionRecordIds) { $script:UndoSessionRecordIds = @{} }
if (-not $script:PartialDetail) { $script:PartialDetail = @{} }
if (-not $script:UndoConsent) { $script:UndoConsent = @{} }
$script:UndoEngineReady = $false

function Initialize-UndoEngine {
    # idempotent: v2 specs for the legacy registry tweaks, then copy usable schema 1 records, then set the old file aside
    # the edition decides paths the group B timer and NPI specs resolve at capture time; the free script sets Free here
    if (-not $script:UndoEdition) { $script:UndoEdition = 'Paid' }      # the free build sets 'Free' at the top of its engine region
    try {
        [void](Undo-Engine-InitSpecs)
        # the protected folder must exist before the first action (helpers and file backups live below it)
        if (-not $script:UndoV2Dir -and (Get-Command Initialize-ProtectedDir -ErrorAction SilentlyContinue)) {
            $pd = Join-Path $env:ProgramData (Undo-RootName)
            if (-not (Test-Path -LiteralPath $pd)) { [void](Initialize-ProtectedDir $pd) }
        }
        $imp = Undo-Engine-ImportLegacy
        if ($imp.imported -gt 0 -and $imp.durable -and $imp.rejected -eq 0 -and $script:UndoRecordPath -and (Test-Path -LiteralPath $script:UndoRecordPath)) {
            $keep = "$($script:UndoRecordPath).imported-$([datetime]::Now.ToString('yyyyMMdd-HHmmss'))"
            try { Move-Item -LiteralPath $script:UndoRecordPath -Destination $keep -ErrorAction Stop; Write-SR "Saved originals from an earlier version were moved to the new undo store ($($imp.imported)). The old file was kept as $keep" 'INFO' } catch {}
        } elseif ($imp.rejected -gt 0 -or ($imp.imported -gt 0 -and -not $imp.durable)) {
            Write-SR "Some saved originals from an earlier version could not be moved to the new undo store (imported $($imp.imported), not usable $($imp.rejected)). The old file was left where it is." 'WARN'
        }
        $script:UndoEngineReady = $true
    } catch { Write-SR "The undo engine could not start: $($_.Exception.Message)" 'WARN' }
}

function Confirm-UndoIrreversibleTweaks {
    # wording shown BEFORE anything is changed, for the parts that physically cannot be put back. Fails CLOSED: if the question
    # cannot be asked, the answer is no. A yes is remembered for this batch (consent), so the same wording is not asked twice.
    param([string[]]$Names)
    try {
        if (-not $script:UndoEngineReady) { Initialize-UndoEngine }
        $irr = @(); $ask = @()
        foreach ($n in @($Names)) {
            $t = Undo-Engine-IrreversibleText $n
            if ($t) { if (-not $script:UndoConsent[$n]) { $irr += "$(Get-PlainName $n): $t"; $ask += $n } }
        }
        if ($irr.Count -eq 0) { return $true }
        $txt = "Some parts of what you selected cannot be put back by Undo:`n`n" + ($irr -join "`n`n") + "`n`nContinue?"
        if (Confirm-PresetBox $txt 'StreamReady - Cannot be fully undone') { foreach ($n in $ask) { $script:UndoConsent[$n] = $true }; return $true }
        return $false
    } catch { return $false }
}

# used by the Apply functions that act on network adapters (the integration replaces Get-NetAdapter there): only the captured adapters.
# A plan that is present but empty means "no adapter at all"; there is no unrestricted fallback while a plan is frozen.
function Get-NetAdapterFrozen {
    $all = @(Get-NetAdapter @args)
    $fz = $script:UndoFrozenNow
    if ($null -ne $fz) { $g = @($fz.guids); $all = @($all | Where-Object { $g -contains ([string]$_.InterfaceGuid).Trim('{}').ToLowerInvariant() }) }
    return $all
}

function Get-UndoToolPlainName {
    param([string]$Name)
    try { if ($script:ProCaptions -and $script:ProCaptions.ContainsKey($Name)) { return [string]$script:ProCaptions[$Name].title } } catch {}
    try { if ($c[$Name] -and $c[$Name].Content) { return ([string]$c[$Name].Content -replace '[^\x20-\x7E]', '').Trim() } } catch {}
    return ($Name -replace '^Btn', '')
}

function Test-UndoGpuTarget {
    # the GPU Apply handlers act on $script:GpuSubkey: only when that key is one of the targets captured for the tweak being applied.
    # Fails closed (any doubt = $false); with no engine record for this tweak (legacy path) it does not interfere.
    try {
        $id = [string]$script:UndoCurrentId
        if (-not $id -or -not $script:UndoPlans.ContainsKey($id)) { return $true }
        $targets = @()
        foreach ($it in @($script:UndoPlans[$id]['items'])) {
            if ([string]$it['type'] -eq 'GpuDriverProperty') { $targets += @($it['state']['frozenTargets']); if ($it['state']['applyTarget']) { $targets += [string]$it['state']['applyTarget'] } }
        }
        if ($targets.Count -eq 0) { return $true }
        $want = Undo-Reg-Canon ([string]$script:GpuSubkey)
        foreach ($tg in $targets) { if ((Undo-Reg-Canon ([string]$tg)) -eq $want) { return $true } }
        return $false
    } catch { return $false }
}
function Get-UndoNotAppliedText {
    # plain wording for "the original could not be recorded" (the technical reason follows in brackets)
    param($Begin)
    $what = [string]$Begin.failedWhat; $err = [string]$Begin.error
    if ($err -match 'running|in use') { return "Not applied: this tool's helper is still running. Undo the previous run first, then try again. Nothing was changed." }
    if ($Begin.invalidSaved) { return "Not applied: an earlier saved original for this change cannot be used by this version, and StreamReady will not record today's changed settings as the original. Open History to review it. Nothing was changed." }
    if ($err -match 'not safe to use') { return "Not applied: the folder for saved originals is not safe to use, so StreamReady cannot promise an Undo. Nothing was changed." }
    if ($err -match 'damaged') { return "Not applied: the list of saved originals is damaged, so StreamReady cannot promise an Undo. Open History to start a new list. Nothing was changed." }
    if ($err -match 'no undo specification') { return "Not applied: StreamReady has no Undo for this item, so it was not changed." }
    return "Not applied: could not record the original $what ($err). Nothing was changed."
}

# ---- tweaks: capture before, restore on Undo, for ALL tweaks -----------------------------------------------------------------
function Invoke-TweakBatch {
    param([string[]]$Names)
    $Names = @($Names)
    if ($Names.Count -eq 0) { return }
    if (-not $script:UndoEngineReady) { Initialize-UndoEngine }
    [void](Undo-Engine-InitSpecs)      # idempotent: picks up legacy rows added after start-up

    # nothing is changed unless EVERY selected item has an undo specification (a missing one is a bug, not "run without undo")
    $noSpec = @($Names | Where-Object { $dispatch.ContainsKey($_) -and $dispatch[$_] -and -not (Undo-Engine-HasSpec $_) })
    if ($noSpec.Count -gt 0) {
        Write-SR "Nothing was changed: StreamReady has no Undo for $($noSpec -join ', '). This is a bug." 'FAIL'
        $script:LastBatchResult = $null
        Fail "Nothing was changed: no Undo is defined for $((@($noSpec | ForEach-Object { Get-PlainName $_ })) -join ', ')."
        return
    }
    # the wording about parts that cannot be put back is enforced HERE, so every route (basket, Apply All, drift reapply) asks
    if (-not (Confirm-UndoIrreversibleTweaks $Names)) {
        Write-SR 'The batch was cancelled before anything changed.' 'INFO'
        $script:LastBatchResult = $null
        Fail 'Cancelled. Nothing was changed.'
        return
    }

    Working 5 "Creating restore point..."
    $rp = New-StreamReadyRestorePoint -Description "StreamReady Before Tweaks"
    if (-not $rp.Ok -and $rp.Message -notmatch '^A restore point from within') {
        [System.Windows.MessageBox]::Show($rp.Message, "StreamReady - Restore Point", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Warning) | Out-Null
    }

    $undoBatch = [ordered]@{}
    $script:PartialNotes = @{}
    $script:PartialDetail = @{}
    $batchId = [guid]::NewGuid().ToString()
    $total = $Names.Count; $i = 0
    $successCount = 0; $skipCount = 0; $failCount = 0
    $skipped = [System.Collections.Generic.List[string]]::new()
    $failed  = [System.Collections.Generic.List[string]]::new()
    Write-SR "Applying $total tweak$(if($total -ne 1){'s'})" 'INFO'

    foreach ($name in $Names) {
        $i++
        $label = if ($c[$name]) { $c[$name].Content } else { $name }
        Working ([int]($i / $total * 95)) "Applying: $label..."
        Write-SR "[$i/$total] $label" 'APPLY'
        $rec = $null; $reused = $false; $script:ScoreSkipReason = $null
        try {
            if (-not $dispatch.ContainsKey($name) -or -not $dispatch[$name]) {
                $skipCount++; $skipped.Add($label)
                Register-SettingOutcome $name 'NotApplicable'
                Write-SR "$label skipped - not applicable to this PC" 'WARN'
                if ($c[$name]) { try { $c[$name].IsChecked = $false } catch {} }
                continue
            }
            $b = Undo-Engine-Begin -Id $name -Kind 'tweak' -BatchId $batchId
            if ($b.notApplicable) {
                $skipCount++; $skipped.Add($label)
                Register-SettingOutcome $name 'MissingTarget'
                Write-SR "$label skipped - nothing matching was found on this PC to change" 'WARN'
                if ($c[$name]) { try { $c[$name].IsChecked = $false } catch {} }
                continue
            }
            if (-not $b.ok) {
                $failCount++; $failed.Add($label); $script:PartialNotes[$name] = 'notapplied'
                $script:PartialDetail[$name] = Get-UndoNotAppliedText $b
                Write-SR "$label was not applied: the original could not be recorded ($($b.error))" 'FAIL'
                if ($c[$name]) { try { $c[$name].IsChecked = $false } catch {} }
                continue
            }
            $rec = $b.record; $reused = [bool]$b.reused
            $script:UndoFrozenNow = Undo-Engine-FrozenPlan $name      # Apply may only touch the adapters that were captured
            $script:UndoCurrentId = $name
            try { $undo = & $dispatch[$name] } finally { $script:UndoFrozenNow = $null; $script:UndoCurrentId = $null }
            if ($undo) { Register-SettingOutcome $name 'Succeeded' }
            elseif ($script:ScoreSkipReason) { Register-SettingOutcome $name $script:ScoreSkipReason }
            if ($b.none) {
                # a spec that declares no items (reviewed "nothing to record"): keep the built-in undo
                if ($undo -and $name -eq 'ChkGpuNvNpiProfile') { $undo = New-ManualRecoveryUndo $undo }
                if ($undo) { $undoBatch[$name] = $undo; $successCount++ } else { $skipCount++; $skipped.Add($label); Write-SR "$label skipped - precondition not met (see log above)" 'WARN' }
            }
            elseif ($undo) {
                $fin = Undo-Engine-Finish -Record $rec -Reused $reused
                if ($fin.outcome -eq 'unchanged') {
                    # the action ran but every setting was already as it asked: nothing to undo and nothing was applied
                    $skipCount++; $skipped.Add($label)
                    Write-SR "$label skipped - the setting was already as requested, nothing changed" 'INFO'
                } else {
                    $rid = [string]$rec['id']
                    $script:UndoSessionRecordIds[$rid] = $true
                    $undoBatch[$name] = { Undo-Engine-ToolUndoRun $rid }.GetNewClosure()
                    $successCount++
                    if (-not $fin.persisted) { $script:UndoSaveFailed = $true; Write-SR "$label was applied but its saved original could not be updated on disk; Undo works until you close StreamReady." 'WARN' }
                    if ($fin.afterApplyFailed) { Write-SR "$label was applied, but StreamReady could not record everything the change did. Undo keeps what it has and tells you the steps it cannot do itself." 'WARN' }
                }
            } else {
                [void](Undo-Engine-IfUnchanged -Record $rec -Reused $reused)
                $skipCount++; $skipped.Add($label)
                Write-SR "$label skipped - precondition not met (see log above)" 'WARN'
            }
        } catch {
            $failCount++
            $failed.Add($label)
            Write-SR "$label failed: $_" 'FAIL'
            $c['LogText'].Text = "Warning: $label failed - $_"
            if ($rec) {
                $f = Undo-Engine-ApplyFailed -Record $rec -Reason "$_" -Reused $reused
                $script:PartialNotes[$name] = $(if ($f.restored) { 'rolled' } else { 'saved' })
                $script:PartialDetail[$name] = $f.message
                Write-SR "$label stopped part-way. $($f.message)" $(if ($f.restored) { 'OK' } else { 'WARN' })
                if (-not $f.restored) { $script:UndoSessionRecordIds[[string]$rec['id']] = $false }
            } else { $script:PartialNotes[$name] = 'none' }
        }
        if ($c[$name]) { try { $c[$name].IsChecked = $false } catch {} }
    }
    $script:UndoConsent = @{}

    if ($undoBatch.Count -gt 0) {
        $script:UndoStack.Push($undoBatch)
        $c['BtnUndoLast'].IsEnabled = $true
        $c['BtnUndoLast'].Content   = "Undo Last Batch ($($undoBatch.Count) tweak$(if($undoBatch.Count -ne 1){'s'}))"
        Save-AppliedTweakState -Names @($undoBatch.Keys)
    }

    Update-Count
    $script:LastBatchResult = @{ Time = [datetime]::Now; Names = @($Names); Batch = $(if ($undoBatch.Count -gt 0) { $script:UndoStack.Peek() } else { $undoBatch }); Failed = @($failed); Skipped = @($skipped) }
    $parts = [System.Collections.Generic.List[string]]::new()
    if ($successCount -gt 0) { $parts.Add("$successCount applied") }
    if ($skipCount -gt 0)    { $parts.Add("$skipCount skipped") }
    if ($failCount -gt 0)    { $parts.Add("$failCount failed") }
    $summary = $parts -join ", "

    if ($skipCount -gt 0) { Write-SR "Skipped: $($skipped -join ', ')" 'WARN' }
    if ($failCount -gt 0) { Write-SR "Failed: $($failed -join ', ')" 'FAIL' }

    if ($failCount -eq 0 -and $skipCount -eq 0) {
        Done "$summary."
        Write-SR "All done! $summary." 'SECTION'
    } elseif ($successCount -gt 0) {
        Set-Progress 100 "$summary - check log for details." "#f0b545"
        Write-SR "Batch finished with issues: $summary." 'SECTION'
    } else {
        Fail "$summary - check log for details."
        Write-SR "Batch finished with issues: $summary." 'SECTION'
    }
}

# History: a saved original from an earlier session (tweak or tool) is restored through the engine
function Invoke-UndoRecordRestore {
    # one place for "restore this record" with the questions a person must answer: a newer change on the same setting, manual steps
    param([string]$RecordId, [string]$Name)
    $res = Undo-Engine-Restore -Id $RecordId
    if ((-not $res.ok) -and @($res.blockedBy).Count -gt 0) {
        $txt = "$(Get-UndoToolPlainName $Name) shares a setting with a newer change ($(@($res.blockedByNames) -join ', ')).`n`nTo end up exactly where you started, the newer change has to be undone first. Undo both now?"
        if (Confirm-PresetBox $txt 'StreamReady - Undo in the right order') { $res = Undo-Engine-Restore -Id $RecordId -WithNewer }
        else { return $res }
    }
    return $res
}
function Undo-PersistedTweak {
    param([string]$Name)
    $script:HomeLastLoad = [datetime]::MinValue
    try {
        if (-not $script:UndoEngineReady) { Initialize-UndoEngine }
        $recs = @(Undo-Engine-List -TweakId $Name)
        if ($recs.Count -eq 0 -and $script:UndoRestoredNames.ContainsKey($Name)) {
            # undone already as part of a cascade (an older change that was undone together with its newer one): not a failure
            Remove-AppliedTweakState -Names @($Name); Write-SR "$Name was already undone together with another change." 'OK'
            $c['LogText'].Text = "$(Get-PlainName $Name) was already undone together with another change."
            return $true
        }
        if ($recs.Count -eq 0) {
            Write-SR "No saved original is available for $Name." 'WARN'
            $c['LogText'].Text = "No saved original is available for $(Get-PlainName $Name)."
            return $false
        }
        $ok = $true
        foreach ($r in @($recs | Sort-Object { $_['capturedAt'] } -Descending)) {
            Write-SR "Reversing (saved original values): $Name" 'UNDO'
            $res = Invoke-UndoRecordRestore ([string]$r['id']) $Name
            if ($res.needsUser) {
                $ok = $false
                if ($script:ManualPending -is [hashtable]) { $script:ManualPending[$Name] = $true }
                Write-SR "Undo of $Name needs your steps: $($res.message)" 'WARN'
                $c['LogText'].Text = "$(Get-PlainName $Name) needs your steps: $($res.message)"
            }
            elseif (-not $res.ok) { $ok = $false; Write-SR "Undo failed for $Name`: $($res.message)" 'FAIL'; $c['LogText'].Text = "Could not undo $(Get-PlainName $Name): $($res.message)" }
        }
        if ($ok) { Remove-AppliedTweakState -Names @($Name); Write-SR "Undone from saved record: $Name" 'OK' }
        if ($ok -and $script:UndoRestoredNames.Count -gt 0) { Remove-AppliedTweakState -Names @($script:UndoRestoredNames.Keys) }
        return $ok
    } catch { Write-SR "Undo failed for $Name`: $($_.Exception.Message)" 'FAIL'; return $false }
}

# ---- tools: every immediate tool captures before and restores on Undo -----------------------------------------------------------
function Invoke-UndoToolClick {
    param([string]$Name, [scriptblock]$Body)
    if (-not $script:UndoEngineReady) { Initialize-UndoEngine }
    if (-not (Undo-Engine-HasSpec $Name)) {
        # fail closed: a tool whose undo specification did not load does not run
        Write-SR "$(Get-UndoToolPlainName $Name) was not run: StreamReady has no Undo for it (a bug)." 'FAIL'
        try { Fail 'Not run: no Undo is defined for this tool.' } catch {}
        return
    }
    $spec = Undo-Spec-Get $Name
    $toolName = Get-UndoToolPlainName $Name
    # every wording about parts that cannot be put back is shown BEFORE the action: a confirmation when an entry is marked as
    # important (or the tool has nothing undoable at all), otherwise in the status line and the log
    $irrAll = Undo-Engine-IrreversibleText $Name
    $warn = @($spec.Irreversible | Where-Object { $_ -and $_.Warn })
    $needsConfirm = (($warn.Count -gt 0) -or ((@($spec.Items).Count -eq 0) -and (@($spec.Irreversible).Count -gt 0) -and ($Name -notin @('BtnProcessIdleTasks', 'BtnReleaseStandby'))))
    if ($irrAll) {
        if ($needsConfirm) {
            if (-not (Confirm-PresetBox "$irrAll`n`nContinue?" "StreamReady - $toolName")) { Write-SR "$toolName was cancelled before anything changed." 'INFO'; return }
        } else {
            Write-SR "Before it starts: $irrAll" 'INFO'
            try { $c['LogText'].Text = "Good to know: $irrAll" } catch {}
        }
    }
    try { Working 5 "Saving the original state for $toolName..." } catch {}
    $inner = $Body; $nm = $Name
    $guarded = { $script:UndoFrozenNow = Undo-Engine-FrozenPlan $nm; try { & $inner } finally { $script:UndoFrozenNow = $null } }.GetNewClosure()
    $depth = $script:UndoStack.Count
    $run = Undo-Engine-ToolRun -ToolId $Name -Apply $guarded
    if (-not $run.ok) {
        $msg = if ($run.notRecorded) { Get-UndoNotAppliedText @{ failedWhat = $run.failedWhat; error = $run.error } } else { $run.message }
        Write-SR "${toolName}: $msg" 'WARN'
        try { Fail $msg } catch {}
        try { $c['LogText'].Text = $msg } catch {}
        return
    }
    if ($run.none) { return }
    # the tool's own session-only undo (if it pushed one) is replaced by the engine's saved-original undo
    while ($script:UndoStack.Count -gt $depth) { [void]$script:UndoStack.Pop() }
    if ($run.unchanged) { Update-UndoButton; return }       # nothing was changed
    $rid = [string]$run.recordId
    if ($run.persistFailed) { Write-SR "${toolName}: $($run.message)" 'WARN'; $script:UndoSaveFailed = $true }
    if ($run.evidenceMissing) { Write-SR "${toolName}: was applied, but StreamReady could not record everything the change did. Undo keeps what it has and tells you the steps it cannot do itself." 'WARN'; try { $c['LogText'].Text = "$toolName was applied, but StreamReady could not record everything it did, so Undo may need steps from you." } catch {} }
    $script:UndoSessionRecordIds[$rid] = $true
    $key = "__$toolName__"
    $script:UndoStack.Push(@{ $key = $run.undo })
    Update-UndoButton
    $c['BtnUndoLast'].Content = "Undo Last Batch ($toolName)"
}

# History: saved originals that are not part of this session's batches, records that need the user's own steps, and a damaged list
function Add-UndoPendingCard {
    try {
        if (-not $script:UndoEngineReady) { Initialize-UndoEngine }
        $st = Undo-Store-Read
        $recs = @()
        $inv = @()
        if ($st.ok) { $recs = @(Undo-Engine-List | Where-Object { ($_['status'] -eq 'manual') -or (@($_['items'] | Where-Object { $_['deferred'] -eq $true }).Count -gt 0) -or (-not $script:UndoSessionRecordIds[[string]$_['id']] -and ($_['kind'] -eq 'tool' -or $script:UndoEdition -eq 'Free')) }); $inv = @(Undo-Engine-InvalidList) }
        if ($st.ok -and $recs.Count -eq 0 -and $inv.Count -eq 0) { return }
        $card = New-Object System.Windows.Controls.Border
        $card.Background = (Br '#0d0d16'); $card.BorderBrush = (Br '#28242f'); $card.BorderThickness = [System.Windows.Thickness]::new(1)
        $card.CornerRadius = [System.Windows.CornerRadius]::new(10); $card.Padding = [System.Windows.Thickness]::new(16,12,16,10)
        $card.Margin = [System.Windows.Thickness]::new(0,0,0,10)
        $sp = New-Object System.Windows.Controls.StackPanel
        if (-not $st.ok) {
            $sp.Children.Add((New-Text $(if ($st.state -eq 'untrusted') { 'The folder for saved originals is not safe to use' } else { 'The list of saved originals is damaged' }) 14 '#f0b545' 'SemiBold')) | Out-Null
            $sp.Children.Add((New-Text ([string]$st.error) 12 '#8b8b9c')) | Out-Null
            if ($st.state -eq 'untrusted') { $card.Child = $sp; $c['HistoryItems'].Children.Add($card) | Out-Null; return }
            $rb = New-Object System.Windows.Controls.Button
            $rb.Style = $window.FindResource('BtnGray'); $rb.Content = 'Start a new undo list'; $rb.Height = 30; $rb.Margin = [System.Windows.Thickness]::new(0,8,0,0); $rb.HorizontalAlignment = 'Left'
            $rb.Add_Click({ param($s, $ev)
                if (Confirm-PresetBox "The damaged file is kept next to the new list, but its originals can no longer be used by Undo. Start a new list?" 'StreamReady - Start a new undo list') {
                    $r = Undo-Store-Recover; try { $c['LogText'].Text = $r.message } catch {}
                    Refresh-HistoryPage
                } })
            $sp.Children.Add($rb) | Out-Null
            $card.Child = $sp
            $c['HistoryItems'].Children.Add($card) | Out-Null
            return
        }
        $sp.Children.Add((New-Text 'Saved originals (earlier sessions and items that need your steps)' 14 '#edecf3' 'SemiBold')) | Out-Null
        $sp.Children.Add((New-Text 'Each line is a setting that was changed and its saved original. Undo puts them back. Items that say "needs your steps" cannot be finished automatically.' 12 '#8b8b9c')) | Out-Null
        foreach ($r in $recs) {
            $isManual = ($r['status'] -eq 'manual')
            $row = New-Object System.Windows.Controls.DockPanel
            $row.LastChildFill = $false; $row.Margin = [System.Windows.Thickness]::new(0,8,0,0)
            $u = New-Object System.Windows.Controls.Button
            $u.Style = $window.FindResource('BtnGray'); $u.Content = $(if ($isManual) { 'I did these steps' } else { 'Undo' }); $u.Height = 28; $u.Padding = [System.Windows.Thickness]::new(12,0,12,0); $u.Tag = [string]$r['id']
            $u.Add_Click({ param($s, $ev)
                $rid2 = [string]$s.Tag
                $rec2 = @(Undo-Engine-List | Where-Object { [string]$_['id'] -eq $rid2 })[0]
                if ($rec2 -and $rec2['status'] -eq 'manual') { $res = Undo-Engine-Acknowledge -Id $rid2; if ($res.ok) { Done $res.message } else { Fail $res.message } }
                else {
                    $res = Invoke-UndoRecordRestore $rid2 ([string]$rec2['tweakId'])
                    if ($res.ok -and $rec2['kind'] -eq 'tweak') { try { Remove-AppliedTweakState -Names @([string]$rec2['tweakId']) } catch {} }
                    if ($res.needsUser) { Fail "Needs your steps: $($res.message)" } elseif ($res.ok) { Done 'Put back to the original.' } else { Fail $res.message }
                }
                Refresh-HistoryPage })
            [System.Windows.Controls.DockPanel]::SetDock($u, 'Right'); $row.Children.Add($u) | Out-Null
            if (@($r['items'] | Where-Object { $_['deferred'] -eq $true }).Count -gt 0) {
                $g = New-Object System.Windows.Controls.Button
                $g.Style = $window.FindResource('BtnGray'); $g.Content = 'Give up on this'; $g.Height = 28; $g.Margin = [System.Windows.Thickness]::new(0,0,8,0); $g.Padding = [System.Windows.Thickness]::new(12,0,12,0); $g.Tag = [string]$r['id']
                $g.Add_Click({ param($s, $ev)
                    if (Confirm-PresetBox "The network adapter is not connected, so its saved DNS settings were not put back. If you give up, they are removed from the list and cannot be put back later. Give up?" 'StreamReady - Give up on a saved original') {
                        $res = Undo-Engine-Acknowledge -Id ([string]$s.Tag)
                        if ($res.ok) { Done $res.message } else { Fail $res.message }
                        Refresh-HistoryPage
                    } })
                [System.Windows.Controls.DockPanel]::SetDock($g, 'Right'); $row.Children.Add($g) | Out-Null
            }
            $when = ''; try { $when = ([datetime]::Parse([string]$r['capturedAt'])).ToLocalTime().ToString('d MMM HH:mm') } catch {}
            $nt = New-Text "$(Get-UndoToolPlainName ([string]$r['tweakId']))  $when" 13 '#c9c7d6'; $nt.VerticalAlignment = 'Center'
            [System.Windows.Controls.DockPanel]::SetDock($nt, 'Left'); $row.Children.Add($nt) | Out-Null
            $sp.Children.Add($row) | Out-Null
            foreach ($ln in @(Undo-Engine-Describe -Record $r)) {
                $sp.Children.Add((New-Text ("  " + $ln) 11 '#8b8b9c')) | Out-Null
            }
        }
        foreach ($iv in $inv) {
            $row = New-Object System.Windows.Controls.DockPanel
            $row.LastChildFill = $false; $row.Margin = [System.Windows.Thickness]::new(0,8,0,0)
            $u = New-Object System.Windows.Controls.Button
            $u.Style = $window.FindResource('BtnGray'); $u.Content = 'Keep a copy and discard'; $u.Height = 28; $u.Padding = [System.Windows.Thickness]::new(12,0,12,0); $u.Tag = [string]$iv.id
            $u.Add_Click({ param($s, $ev)
                if (Confirm-PresetBox "This saved original cannot be used by this version, so Undo cannot put it back. A copy is kept next to the list. Discard it so the change can be applied again?" 'StreamReady - Discard a saved original') {
                    $res = Undo-Engine-DiscardInvalid -Id ([string]$s.Tag)
                    if ($res.ok) { Done $res.message } else { Fail $res.message }
                    Refresh-HistoryPage
                } })
            [System.Windows.Controls.DockPanel]::SetDock($u, 'Right'); $row.Children.Add($u) | Out-Null
            $nt = New-Text "$(Get-UndoToolPlainName ([string]$iv.tweakId)): a saved original that cannot be used" 13 '#f0b545'; $nt.VerticalAlignment = 'Center'
            [System.Windows.Controls.DockPanel]::SetDock($nt, 'Left'); $row.Children.Add($nt) | Out-Null
            $sp.Children.Add($row) | Out-Null
            $sp.Children.Add((New-Text ("  Reason: " + [string]$iv.reason + ". This change is blocked until you decide.") 11 '#8b8b9c')) | Out-Null
        }
        $card.Child = $sp
        $c['HistoryItems'].Children.Add($card) | Out-Null
    } catch {}
}
#endregion UndoEngine hooks END

#region UndoEngine free support BEGIN
# Support functions the undo engine needs from the app. The free script was written before the paid script got them, so this block
# adds them (they come LATER in the script, so they replace older versions of the same name). Copied from the working paid script by
# AST extraction (last definition of each name). Only used for the free edition; ASCII only.

if (-not $script:PresetMsg) { $script:PresetMsg = [System.Windows.MessageBox] }
if (-not ($script:ManualPending -is [hashtable])) { $script:ManualPending = @{} }
if (-not ($script:ManualInner -is [hashtable])) { $script:ManualInner = @{} }

function Confirm-PresetBox {
    param([string]$Text, [string]$Title)
    $r = $script:PresetMsg.Show($Text, $Title, [System.Windows.MessageBoxButton]::OKCancel, [System.Windows.MessageBoxImage]::Warning)
    return ($r -eq [System.Windows.MessageBoxResult]::OK)
}

function New-ManualRecoveryUndo {
    param($Inner, [string]$Name = 'ChkGpuNvNpiProfile')
    $script:ManualInner[$Name] = $Inner
    return [scriptblock]::Create("Invoke-ManualRecovery '$Name'")
}

function Invoke-ManualRecovery {
    param([string]$Name)
    $inner = $script:ManualInner[$Name]
    if ($inner) { & $inner }
    $script:ManualPending[$Name] = $true
    $c['LogText'].Text = "$(Get-PlainName $Name) needs manual recovery. The steps are in the log. StreamReady cannot restore it by itself."
}

function Test-RegKeyStrict {
    param([string]$Key)
    try { $null = Get-Item -LiteralPath $Key -ErrorAction Stop; return $true }
    catch [System.Management.Automation.ItemNotFoundException] { return $false }
}

function Set-RegNoneValue {
    param([string]$Key, [string]$Name, [byte[]]$Bytes)
    if ($Key -match '^HKCU:\\(.*)$') { $hive = [Microsoft.Win32.Registry]::CurrentUser }
    elseif ($Key -match '^HKLM:\\(.*)$') { $hive = [Microsoft.Win32.Registry]::LocalMachine }
    else { throw "Unsupported registry path: $Key" }
    $sk = $hive.CreateSubKey($Matches[1])
    try { $sk.SetValue($Name, $Bytes, [Microsoft.Win32.RegistryValueKind]::None) } finally { $sk.Close() }
}

function Remove-EmptyCreatedKeys {
    param([string]$Key, [string]$Root)
    $cur = $Key
    while ($true) {
        if (Test-RegKeyStrict $cur) {
            $k = Get-Item -LiteralPath $cur -ErrorAction Stop
            if (@($k.GetValueNames()).Count -gt 0 -or @($k.GetSubKeyNames()).Count -gt 0) { break }
            Remove-Item -LiteralPath $cur -ErrorAction Stop
        }
        if ($cur -eq $Root) { break }
        $cur = Split-Path -Path $cur -Parent
        if (-not $cur) { break }
    }
}

function Get-RegItemState {
    param([string]$Key, [string]$Name, [string]$Token = '')
    $r = @{ Kind = $(if ($Token) { 'Token' } else { 'Value' }); Key = $Key; Name = $Name; Token = $Token
            KeyExisted = $false; CreatedRoot = $null; ValueExisted = $false; Type = $null; Data = $null; TokenExisted = $false; TokenValue = $null }
    $r.KeyExisted = Test-RegKeyStrict $Key
    if (-not $r.KeyExisted) {
        $cur = $Key; $root = $Key
        while ($true) {
            $parent = Split-Path -Path $cur -Parent
            if (-not $parent -or (Test-RegKeyStrict $parent)) { break }
            $root = $parent; $cur = $parent
        }
        $r.CreatedRoot = $root
    } else {
        $k = Get-Item -LiteralPath $Key -ErrorAction Stop
        if (@($k.GetValueNames()) -contains $Name) {
            $r.ValueExisted = $true
            $kind = $k.GetValueKind($Name)
            $r.Type = [string]$kind
            $v = $k.GetValue($Name, $null, [Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames)
            $r.Data = if ($kind -eq [Microsoft.Win32.RegistryValueKind]::Binary -or $kind -eq [Microsoft.Win32.RegistryValueKind]::None) { [Convert]::ToBase64String([byte[]]$v) } else { $v }
        }
    }
    # token rows are edited as text, so only a plain string original can be put back exactly
    if ($Token -and $r.ValueExisted -and $r.Type -ne 'String') { throw "The existing value $Name is of type $($r.Type), which cannot be put back exactly after a token change. Nothing was changed." }
    if ($Token -and $r.ValueExisted -and ([string]$r.Data) -match ([regex]::Escape($Token) + '=(\d+)')) { $r.TokenExisted = $true; $r.TokenValue = $Matches[1] }
    return $r
}

function Restore-RegItemState {
    param($R)
    $key = [string]$R.Key; $name = [string]$R.Name
    if ($R.Kind -eq 'Token') {
        $cur = $null
        $keyThere = Test-RegKeyStrict $key
        if ($keyThere -and (@((Get-Item -LiteralPath $key -ErrorAction Stop).GetValueNames()) -contains $name)) {
            $cur = (Get-ItemProperty -LiteralPath $key -Name $name -ErrorAction Stop).$name
        }
        if ($null -eq $cur) { $cur = '' }
        $tok = [regex]::Escape([string]$R.Token)
        if ($R.TokenExisted) {
            if ($cur -match "$tok=\d+") { $cur = $cur -replace "$tok=\d+", ("{0}={1}" -f $R.Token, $R.TokenValue) }
            else { $cur = $cur + ("{0}={1};" -f $R.Token, $R.TokenValue) }
        } else { $cur = $cur -replace "$tok=\d+;?", '' }
        if ([string]::IsNullOrEmpty($cur) -and -not ($R.ValueExisted -and [string]$R.Data -eq '')) {
            if ($keyThere -and (@((Get-Item -LiteralPath $key -ErrorAction Stop).GetValueNames()) -contains $name)) {
                Remove-ItemProperty -LiteralPath $key -Name $name -ErrorAction Stop
                if (@((Get-Item -LiteralPath $key -ErrorAction Stop).GetValueNames()) -contains $name) { throw "The value $name could not be removed." }
            }
        } else {
            if (-not $keyThere) { New-Item -Path $key -Force | Out-Null }
            Set-ItemProperty -LiteralPath $key -Name $name -Value $cur -Type String -ErrorAction Stop
            $back = (Get-ItemProperty -LiteralPath $key -Name $name -ErrorAction Stop).$name
            if ([string]$back -ne [string]$cur) { throw "The value $name did not read back as expected." }
        }
    }
    elseif ($R.ValueExisted) {
        if (-not (Test-RegKeyStrict $key)) { New-Item -Path $key -Force | Out-Null }
        $type = [string]$R.Type
        $data = $R.Data
        if ($type -eq 'None') { Set-RegNoneValue $key $name ([Convert]::FromBase64String([string]$data)) }
        else {
            switch ($type) {
                'DWord'       { $data = [int][long]$data }
                'QWord'       { $data = [long]$data }
                'Binary'      { $data = [Convert]::FromBase64String([string]$data) }
                'MultiString' { $data = [string[]]@($data) }
                default       { $data = [string]$data }
            }
            Set-ItemProperty -LiteralPath $key -Name $name -Value $data -Type $type -ErrorAction Stop
        }
    }
    else {
        if (Test-RegKeyStrict $key) {
            if (@((Get-Item -LiteralPath $key -ErrorAction Stop).GetValueNames()) -contains $name) { Remove-ItemProperty -LiteralPath $key -Name $name -ErrorAction Stop }
        }
    }
    if ($R.CreatedRoot) { Remove-EmptyCreatedKeys $key ([string]$R.CreatedRoot) }
}
#endregion UndoEngine free support END

#endregion v7 Stage 2

#endregion UI Event Handlers

#region App Launch
# ─── Startup load ──────────────────────────────────────────────────────────────
$window.Add_Loaded({
    # Let WPF paint the (dark) window first, then do the slow start-up work. Without this the
    # window shows as a blank white box until every query below has finished.
    [void]$window.Dispatcher.BeginInvoke([System.Windows.Threading.DispatcherPriority]::ContextIdle, [Action]{
    try {
    Write-SR "StreamReady PC Optimization Toolkit (Open Source Edition) v1.0.0" 'SECTION'
    Write-SR "Running as Administrator - GPU: $($script:GpuVendor.ToUpper())" 'OK'
    # Show correct GPU vendor panel in Gaming tab
    switch ($script:GpuVendor) {
        "nvidia" { $c['PanelNvidia'].Visibility = 'Visible' }
        "amd"    { $c['PanelAmd'].Visibility    = 'Visible' }
        default  { $c['LblNoGpu'].Visibility    = 'Visible' }
    }
    Update-Count
    # Force-load Dashboard now (it's the default view)
    Load-Dashboard
    $script:DashboardLoaded = $true
    if (Get-Command Initialize-CpuArchCards -ErrorAction SilentlyContinue) { Initialize-CpuArchCards }
    if (Get-Command Update-GpuPrefList -ErrorAction SilentlyContinue) { Update-GpuPrefList }
    Done "StreamReady ready."
    # Select Dashboard by default (triggers SelectionChanged → shows SecDashboard).
    # Index 0, not 1 - the sidebar no longer has non-selectable group-header items
    # ahead of it (icon-only rail redesign removed the PERFORMANCE/WINDOWS/TOOLS labels).
    $script:SkipSideNavLoad = $true   # the dashboard was loaded just above; selecting the first item must not load it again
    $c['SideNav'].SelectedIndex = 0
    $script:SkipSideNavLoad = $false
    Initialize-ShellUi
    Start-StartupPrefetch
    } catch {
        Write-SR "Start-up load error: $($_.Exception.Message)" 'FAIL'
        # Never leave a blank window. If the new shell did not come up, show the old panel view, but every control in it is locked
        # (disabled) unless the saved Safe Mode choice is known to be off, so Safe Mode can never be bypassed by this fallback.
        if (-not $script:SrPage -and $c['ProHost'].Visibility -ne 'Visible') {
            $c['SimpleHost'].Visibility = 'Collapsed'; $c['ProHost'].Visibility = 'Visible'
            try { $c['SideNav'].SelectedIndex = 0 } catch {}
            $safeOff = $false
            try {
                if (Test-Path -LiteralPath $script:SrSettingsPath) { $sj = Get-Content -LiteralPath $script:SrSettingsPath -Raw -EA Stop | ConvertFrom-Json; $safeOff = ($null -ne $sj.safeMode -and -not [bool]$sj.safeMode) }
                else { $safeOff = $true }
            } catch { $safeOff = $false }
            if (-not $safeOff) {
                try { $window.FindName('ContentArea').IsEnabled = $false } catch {}
                try { $window.FindName('ContentArea').ToolTip = 'Safe Mode is on, or its setting could not be read, so these panels are locked. Restart StreamReady.' } catch {}
                try { $c['LogText'].Text = 'The new view could not start. The old panels are locked because Safe Mode is on or could not be checked. Restart StreamReady.' } catch {}
            }
        }
    }
    })
})

$window.Add_Closing({
    $script:IdleStop = $true
    # Stop the Dashboard ping timer and free the Ping object if still in-flight
    if ($script:_PingTimer -and $script:_PingTimer.IsEnabled) {
        $script:_PingTimer.Stop()
        try { $script:_Pinger.Dispose() } catch {}
    }
    # Same cleanup for the regional latency test's runspace, if still in-flight
    if ($script:_RegionPingTimer -and $script:_RegionPingTimer.IsEnabled) {
        $script:_RegionPingTimer.Stop()
        try { $script:_RegionPingPs.Dispose() } catch {}
        try { $script:_RegionPingRs.Close(); $script:_RegionPingRs.Dispose() } catch {}
    }
    # Same cleanup for the DNS speed test's UDP sockets, if still in-flight
    if ($script:_DnsSpeedTimer -and $script:_DnsSpeedTimer.IsEnabled) {
        $script:_DnsSpeedTimer.Stop()
        if ($script:_DnsSpeedHandles) {
            foreach ($h in $script:_DnsSpeedHandles.Values) { if ($h.Udp) { try { $h.Udp.Close() } catch {} } }
        }
    }
    # Same cleanup for Load-NetInfo's async ping runspace, if still in-flight
    if ($script:_NetPingTimer -and $script:_NetPingTimer.IsEnabled) {
        $script:_NetPingTimer.Stop()
        try { $script:_NetPingPs.Dispose() } catch {}
        try { $script:_NetPingRs.Close(); $script:_NetPingRs.Dispose() } catch {}
    }
    # Stop the Dashboard live-metrics sampler
    if ($script:_DashMetricsTimer -and $script:_DashMetricsTimer.IsEnabled) {
        $script:_DashMetricsTimer.Stop()
    }
})

$window.ShowDialog() | Out-Null
#endregion App Launch
